# ==========================================================
# 기존 levels / voice_levels 는 기본키가 user_id 하나뿐이라
# A 서버에서 쌓은 레벨이 B 서버에서도 그대로 보이는 문제가 있었습니다.
# users(포인트) 테이블처럼 (guild_id, user_id) 로 분리합니다.
#
# 기존 데이터는 버리지 않고 guild_id=0 (레거시 공용) 으로 보존한 뒤,
# 각 서버에서 처음 조회될 때 그 서버 몫으로 복사해줍니다.

def mnb_migrate_level_tables():
    """levels / voice_levels 에 guild_id 를 추가하고 기본키를 재구성합니다.
    이미 마이그레이션된 경우에는 아무것도 하지 않습니다.
    """
    try:
        c.execute("PRAGMA table_info(levels)")
        cols = [r[1] for r in c.fetchall()]
        if not cols:
            return False
        if "guild_id" in cols:
            return False  # 이미 완료

        print("🔄 레벨 테이블 서버별 분리 마이그레이션을 시작합니다...")

        # ---- levels ----
        c.execute("""
        CREATE TABLE IF NOT EXISTS levels_v2 (
            guild_id INTEGER DEFAULT 0,
            user_id INTEGER,
            exp INTEGER DEFAULT 0,
            level INTEGER DEFAULT 1,
            PRIMARY KEY (guild_id, user_id)
        )
        """)
        c.execute(
            "INSERT OR IGNORE INTO levels_v2(guild_id, user_id, exp, level) "
            "SELECT 0, user_id, exp, level FROM levels"
        )
        c.execute("DROP TABLE levels")
        c.execute("ALTER TABLE levels_v2 RENAME TO levels")

        # ---- voice_levels ----
        c.execute("""
        CREATE TABLE IF NOT EXISTS voice_levels_v2 (
            guild_id INTEGER DEFAULT 0,
            user_id INTEGER,
            exp INTEGER DEFAULT 0,
            level INTEGER DEFAULT 1,
            total_seconds INTEGER DEFAULT 0,
            PRIMARY KEY (guild_id, user_id)
        )
        """)
        c.execute(
            "INSERT OR IGNORE INTO voice_levels_v2(guild_id, user_id, exp, level, total_seconds) "
            "SELECT 0, user_id, exp, level, total_seconds FROM voice_levels"
        )
        c.execute("DROP TABLE voice_levels")
        c.execute("ALTER TABLE voice_levels_v2 RENAME TO voice_levels")

        conn.commit()
        print("✅ 레벨 테이블 마이그레이션 완료 (기존 데이터는 guild_id=0 에 보존)")
        return True
    except sqlite3.Error as e:
        try:
            conn.rollback()
        except Exception:
            pass
        print(f"⚠️ 레벨 마이그레이션 실패: {e}")
        return False


mnb_migrate_level_tables()


# 레거시(guild_id=0) 데이터를 해당 서버로 1회 승계합니다.
_MNB_LEGACY_LEVEL_CLAIMED = set()


def _mnb_claim_legacy_level(guild_id: int, user_id: int):
    """예전 공용 레벨 데이터를 이 서버 몫으로 한 번만 복사합니다."""
    if guild_id <= 0:
        return
    key = (guild_id, user_id)
    if key in _MNB_LEGACY_LEVEL_CLAIMED:
        return
    _MNB_LEGACY_LEVEL_CLAIMED.add(key)
    try:
        c.execute(
            "INSERT OR IGNORE INTO levels(guild_id, user_id, exp, level) "
            "SELECT ?, user_id, exp, level FROM levels WHERE guild_id=0 AND user_id=?",
            (guild_id, user_id),
        )
        c.execute(
            "INSERT OR IGNORE INTO voice_levels(guild_id, user_id, exp, level, total_seconds) "
            "SELECT ?, user_id, exp, level, total_seconds FROM voice_levels WHERE guild_id=0 AND user_id=?",
            (guild_id, user_id),
        )
        conn.commit()
    except sqlite3.Error:
        pass


