class EmbedEditModal(discord.ui.Modal):
    def __init__(self, key, current_config):
        super().__init__(title="임베드 디자인 수정")
        self.key = key
        self.title_input = discord.ui.TextInput(label="제목", default=current_config.get("title", ""))
        self.desc_input = discord.ui.TextInput(label="내용", style=discord.TextStyle.paragraph, default=current_config.get("description", ""))
        self.color_input = discord.ui.TextInput(label="색상 HEX (예: 87CEFA)", default=current_config.get("color", "87CEFA"))
        self.img_input = discord.ui.TextInput(label="이미지 URL (비워두면 삭제)", default=current_config.get("image_url", ""), required=False)
        self.add_item(self.title_input)
        self.add_item(self.desc_input)
        self.add_item(self.color_input)
        self.add_item(self.img_input)

    async def on_submit(self, interaction: discord.Interaction):
        save_recruit_embed_config(
            interaction.guild.id, self.key, 
            str(self.title_input.value), str(self.desc_input.value),
            str(self.color_input.value), str(self.img_input.value), "Designed by 냥이"
        )
        await interaction.response.send_message("✅ 디자인이 저장되었습니다!", ephemeral=True)

class ProfileRoleSelect(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label=name, description=f"{name} 역할을 선택/해제합니다.")
            for name in PROFILE_ROLE_NAMES
        ]
        super().__init__(
            placeholder="프로필 역할을 선택해주세요",
            min_values=0,
            max_values=len(options),
            options=options,
            custom_id="profile_role_select"
        )

    async def callback(self, interaction: discord.Interaction):
        if interaction.guild is None:
            return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

        member = interaction.user
        selected_names = set(self.values)

        add_roles = []
        remove_roles = []

        for role_name in PROFILE_ROLE_NAMES:
            role = discord.utils.get(interaction.guild.roles, name=role_name)
            if role is None:
                continue

            if role_name in selected_names and role not in member.roles:
                add_roles.append(role)
            elif role_name not in selected_names and role in member.roles:
                remove_roles.append(role)

        try:
            if add_roles:
                await member.add_roles(*add_roles, reason="프로필 역할 선택")
            if remove_roles:
                await member.remove_roles(*remove_roles, reason="프로필 역할 선택 해제")
        except discord.Forbidden:
            return await safe_interaction_send(interaction, 
                "❌ 봇 역할 위치가 낮아서 역할을 지급/해제할 수 없습니다.",
                ephemeral=True
            )
        except discord.HTTPException:
            return await safe_interaction_send(interaction, 
                "❌ 역할 처리 중 오류가 발생했습니다.",
                ephemeral=True
            )

        added_text = ", ".join(role.name for role in add_roles) if add_roles else "없음"
        removed_text = ", ".join(role.name for role in remove_roles) if remove_roles else "없음"

        await safe_interaction_send(interaction, 
            f"✅ 프로필 역할 선택이 완료됐습니다.\n추가: {added_text}\n해제: {removed_text}",
            ephemeral=True
        )


