async def create_friend_role_select_channel(guild: discord.Guild):
    """📌 필독(또는 기본) 카테고리에 프로필/크리에이터/할사람 역할 선택 채널·패널을 만듭니다.

    이미 패널이 전송돼 있으면 중복으로 다시 보내지 않습니다.
    """
    role_panel_category, _used_rule_category = await get_rule_or_default_category_for_panels(guild)

    channel = discord.utils.get(guild.text_channels, name="｜・(🎭)：역할선택")
    if channel is None:
        await mnb_cleanup_old_named_channels(role_panel_category, {"🎭-역할선택"})
        channel = await guild.create_text_channel("｜・(🎭)：역할선택", category=role_panel_category)
    elif channel.category != role_panel_category:
        await channel.edit(category=role_panel_category)

    newface_role = discord.utils.get(guild.roles, name="뉴페이스")
    unverified_role = discord.utils.get(guild.roles, name="미인증")

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
    }
    if newface_role:
        overwrites[newface_role] = discord.PermissionOverwrite(view_channel=True, read_message_history=True)
    if unverified_role:
        overwrites[unverified_role] = discord.PermissionOverwrite(view_channel=False)

    await channel.edit(overwrites=overwrites)

    # 이미 패널이 전송돼 있으면 중복으로 다시 보내지 않습니다.
    already_sent = False
    try:
        async for msg in channel.history(limit=20):
            if msg.author == bot.user and msg.embeds:
                title = msg.embeds[0].title or ""
                if "프로필 역할 선택" in title:
                    already_sent = True
                    break
    except discord.HTTPException:
        pass

    panel_sent = False
    if not already_sent:
        embed = discord.Embed(
            title="🎭 프로필 역할 선택",
            description=(
                "아래 선택 박스를 눌러서 프로필 역할을 받을 수 있어요.\n\n"
                "선택 가능 역할\n"
                "• 남성 / 여성\n"
                "• 성인 / 미성년자\n\n"
                "다시 선택하면 역할을 바꿀 수 있습니다."
            ),
            color=BOT_COLOR
        )
        if bot.user:
            embed.set_thumbnail(url=bot.user.display_avatar.url)
        embed.set_footer(text="🌸 뉴페이스도 쉽게 누를 수 있는 역할 선택 패널")
        await channel.send(embed=embed, view=ProfileRoleSelectView())

        creator_embed = discord.Embed(
            title="🎬 크리에이터 역할 선택",
            description="스트리머, 유튜버, 디자이너, 개발자 역할을 선택할 수 있습니다.",
            color=BOT_COLOR
        )
        await channel.send(embed=creator_embed, view=CreatorRoleSelectView())

        friend_embed = discord.Embed(
            title="🤝 할사람 역할 선택",
            description="친구할사람?, 우프할사람?, 게임할사람? 역할을 선택할 수 있습니다.",
            color=BOT_COLOR
        )
        await channel.send(embed=friend_embed, view=FriendWantedRoleSelectView())
        panel_sent = True

    return channel, panel_sent


async def create_profile_role_panel(interaction: discord.Interaction):
    if await reject_if_not_setup_manager(interaction):
        return
    if await reject_if_not_bot_manager(interaction):
        return
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    guild = interaction.guild
    await safe_interaction_defer(interaction, ephemeral=True)

    channel, panel_sent = await create_friend_role_select_channel(guild)

    await interaction.followup.send(
        f"✅ 역할 선택 패널을 {channel.mention} 에 {'새로 생성했습니다' if panel_sent else '이미 있어서 그대로 뒀습니다'}.",
        ephemeral=True
    )
    await send_log(guild, f"🎭 역할 선택 패널 생성\n채널: {channel.mention}\n관리자: {interaction.user.mention}", "general")


