class UnifiedPanelCustomEmbedButton(discord.ui.Button):
    """/임베드설정 안에서 /패널 주요 임베드를 버튼으로 바로 수정하는 버튼입니다."""

    STYLE_BY_PANEL_KEY = {
        "ticket": discord.ButtonStyle.green,
        "support_ticket": discord.ButtonStyle.green,
        "music": discord.ButtonStyle.green,
        "boost": discord.ButtonStyle.green,
        "shop": discord.ButtonStyle.green,
        "security": discord.ButtonStyle.red,
        "warning": discord.ButtonStyle.red,
        "admin": discord.ButtonStyle.red,
        "staff_tools": discord.ButtonStyle.red,
        "event": discord.ButtonStyle.blurple,
        "event_end": discord.ButtonStyle.blurple,
        "game_role": discord.ButtonStyle.blurple,
        "title": discord.ButtonStyle.blurple,
        "devlog": discord.ButtonStyle.blurple,
    }

    def __init__(self, panel_key: str, target_channel_id: int = 0, row: int = 0):
        meta = PANEL_CUSTOM_EMBED_DISPLAY_META.get(panel_key, {})
        label = meta.get("name", panel_key)[:80]
        emoji = meta.get("emoji")
        style = self.STYLE_BY_PANEL_KEY.get(panel_key, discord.ButtonStyle.gray)
        super().__init__(label=label, emoji=emoji, style=style, row=row)
        self.panel_key = panel_key
        self.embed_type = PANEL_CUSTOM_EMBED_TYPES.get(panel_key, "")
        self.display_name = meta.get("name", panel_key)
        self.target_channel_id = target_channel_id

    async def callback(self, interaction: discord.Interaction):
        if await reject_if_not_setup_manager(interaction):
            return
        if not self.embed_type:
            return await safe_interaction_send(interaction, "❌ 아직 연결되지 않은 패널 임베드입니다.", ephemeral=True)
        await interaction.response.send_modal(
            UnifiedAutoEmbedEditModal(
                interaction.guild.id,
                self.embed_type,
                self.display_name,
                self.target_channel_id,
            )
        )


