async def create_log_category(interaction: discord.Interaction):
    if await reject_if_not_setup_manager(interaction):
        return
    if not interaction.user.guild_permissions.administrator:
        return await safe_interaction_send(interaction, 
            "❌ 관리자만 사용할 수 있습니다.",
            ephemeral=True
        )

    guild = interaction.guild
    if guild is None:
        return await safe_interaction_send(interaction, 
            "❌ 서버에서만 사용할 수 있습니다.",
            ephemeral=True
        )

    await safe_interaction_defer(interaction, ephemeral=True)

    category = discord.utils.get(guild.categories, name=LOG_CATEGORY_NAME)
    if category is None:
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
        }
        category = await guild.create_category(LOG_CATEGORY_NAME, overwrites=overwrites)

    created = []
    for channel_name in LOG_CHANNEL_NAMES.values():
        channel = discord.utils.get(guild.text_channels, name=channel_name)
        if channel is None:
            await guild.create_text_channel(channel_name, category=category)
            created.append(channel_name)

    if created:
        result = "\n".join(f"• `{name}`" for name in created)
        await interaction.followup.send(
            f"✅ 로그 카테고리와 로그 채널을 생성했습니다.\n{result}",
            ephemeral=True
        )
    else:
        await interaction.followup.send(
            "✅ 이미 모든 로그 채널이 있습니다.",
            ephemeral=True
        )

    await send_log(guild, f"📁 로그 카테고리 생성/확인\n관리자: {interaction.user.mention}", "general")


log_group = app_commands.Group(name="로그", description="로그 채널을 직접 정하고 켜거나 끕니다.")


def log_type_label(log_type: str) -> str:
    return LOG_TYPE_LABELS.get(str(log_type or "general"), str(log_type or "general"))


def log_channel_text(guild: discord.Guild, log_type: str) -> str:
    if guild is None:
        return "미설정"
    if log_type == "levelup":
        channel_id = 0
        try:
            row = get_log_setting(guild.id, "levelup")
            channel_id = int(row[1] or 0) if row is not None and row[1] else 0
        except Exception:
            channel_id = 0
        if not channel_id:
            channel_id = get_saved_channel_id(guild.id, "level_channel_id")
        channel = guild.get_channel(channel_id) if channel_id else None
        return channel.mention if channel else "자동 선택"
    channel = get_log_channel(guild, log_type)
    return channel.mention if channel else "미설정"


