async def ensure_log_category_channels(guild: discord.Guild):
    """로그 카테고리와 모든 로그 채널을 생성/확인합니다."""
    category = discord.utils.get(guild.categories, name=LOG_CATEGORY_NAME)
    if category is None:
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
        }
        category = await guild.create_category(LOG_CATEGORY_NAME, overwrites=overwrites)

    created = []
    for channel_name in LOG_CHANNEL_NAMES.values():
        channel = discord.utils.get(guild.text_channels, name=channel_name)
        if channel is None:
            await guild.create_text_channel(channel_name, category=category)
            created.append(channel_name)
        elif channel.category != category:
            await channel.edit(category=category)

    await apply_log_category_permissions(guild)
    return category, created


# 기본카테고리(필독/채팅방/음성방/이벤트 등) 이름을 이 스타일로 꾸밉니다.
# 예: "📌 필독" -> "▬▬▬▬▬ 📌 필독 ▬▬▬▬▬"
# 이미 서버에 있는 카테고리는 건드리지 않고, 새로 만들 때만 이 스타일이 적용됩니다.
MNB_CATEGORY_DECOR_BAR = "▬▬▬▬▬"


def mnb_decorate_category_display_name(plain_name: str) -> str:
    """카테고리 생성용 표시 이름을 꾸며줍니다. (예: '📌 필독' -> '▬▬▬▬▬ 📌 필독 ▬▬▬▬▬')"""
    text = (plain_name or "").strip()
    if not text:
        return text
    return f"{MNB_CATEGORY_DECOR_BAR} {text} {MNB_CATEGORY_DECOR_BAR}"


def mnb_find_category_loose(guild: discord.Guild, keyword: str):
    """카테고리를 정확한 이름이 아니라 '핵심 키워드 포함 여부'로 찾습니다.
    꾸밈 기호(▬, ------ 등)가 붙어 있어도 같은 카테고리로 인식하기 위해서입니다."""
    if guild is None or not keyword:
        return None
    key = keyword.strip()
    # 1) 정확히 일치하는 경우 (예전 스타일 그대로 남아있는 서버 호환)
    exact = discord.utils.get(guild.categories, name=key)
    if exact is not None:
        return exact
    # 2) 꾸며진 이름 안에 키워드가 포함된 경우
    for cat in guild.categories:
        if key in (cat.name or ""):
            return cat
    return None


async def get_or_create_category(guild: discord.Guild, name: str):
    # 먼저 예전 방식(정확한 이름) + 새 방식(꾸며진 이름 포함) 둘 다로 기존 카테고리를 찾습니다.
    category = mnb_find_category_loose(guild, name)
    if category is None:
        category = await guild.create_category(mnb_decorate_category_display_name(name))
    return category


async def get_or_create_category_under_rule(guild: discord.Guild, name: str):
    """카테고리를 만들되, 필독 카테고리는 자동으로 만들지 않습니다.

    예전에는 기준 위치를 잡으려고 `📌 필독`이 없으면 자동 생성했지만,
    이제는 필독이 이미 있을 때만 그 아래로 배치하고 없으면 일반 생성합니다.
    """
    rule_category = mnb_find_category_loose(guild, "📌 필독")

    category = discord.utils.get(guild.categories, name=name)
    if category is None:
        kwargs = {}
        if rule_category is not None:
            kwargs["position"] = rule_category.position + 1
        category = await guild.create_category(name, **kwargs)
    elif rule_category is not None:
        try:
            await category.edit(position=rule_category.position + 1)
        except discord.HTTPException:
            pass
    return category


async def get_or_create_text_channel(guild: discord.Guild, name: str, category: discord.CategoryChannel):
    channel = discord.utils.get(guild.text_channels, name=name)
    if channel is None:
        channel = await guild.create_text_channel(name, category=category)
    elif channel.category != category:
        await channel.edit(category=category)
    return channel


async def get_rule_or_default_category_for_panels(guild: discord.Guild):
    """인증/부스트 같은 패널용 카테고리를 가져옵니다.

    `📌 필독`이 있으면 그곳을 쓰지만, 없을 때는 필독을 새로 만들지 않고
    `📦 기본 서버` 카테고리를 사용합니다.
    """
    category = mnb_find_category_loose(guild, "📌 필독")
    if category is not None:
        return category, True
    category = await get_or_create_category(guild, DEFAULT_SERVER_CATEGORY_NAME)
    return category, False


async def get_or_create_voice_channel(guild: discord.Guild, name: str, category: discord.CategoryChannel, user_limit: int = None):
    channel = discord.utils.get(guild.voice_channels, name=name)
    if channel is None:
        kwargs = {"category": category}
        if user_limit is not None:
            kwargs["user_limit"] = int(user_limit or 0)
        channel = await guild.create_voice_channel(name, **kwargs)
    else:
        edit_kwargs = {}
        if channel.category != category:
            edit_kwargs["category"] = category
        if user_limit is not None and channel.user_limit != int(user_limit or 0):
            edit_kwargs["user_limit"] = int(user_limit or 0)
        if edit_kwargs:
            await channel.edit(**edit_kwargs)
    return channel


# 여러 카테고리(1채널·2채널·3채널)에 같은 이름의 채널을 각각 만들 때,
# 이름만 보고 찾는 기존 헬퍼는 하나의 채널을 계속 다른 카테고리로 옮겨버립니다.
# 아래 헬퍼는 "이 카테고리 안"에서만 찾으므로 카테고리마다 독립적으로 생성됩니다.
async def get_or_create_text_channel_in_category(guild: discord.Guild, name: str, category: discord.CategoryChannel):
    channel = discord.utils.get(category.text_channels, name=name)
    if channel is None:
        channel = await guild.create_text_channel(name, category=category)
    return channel


async def get_or_create_voice_channel_in_category(guild: discord.Guild, name: str, category: discord.CategoryChannel, user_limit: int = None):
    channel = discord.utils.get(category.voice_channels, name=name)
    if channel is None:
        kwargs = {"category": category}
        if user_limit is not None:
            kwargs["user_limit"] = int(user_limit or 0)
        channel = await guild.create_voice_channel(name, **kwargs)
    elif user_limit is not None and channel.user_limit != int(user_limit or 0):
        await channel.edit(user_limit=int(user_limit or 0))
    return channel


async def apply_log_category_permissions(guild: discord.Guild):
    """로그 카테고리는 관리자만 볼 수 있게 설정합니다."""
    category = discord.utils.get(guild.categories, name=LOG_CATEGORY_NAME)
    if category is None:
        return

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
    }

    # 아래 역할들이 있으면 로그를 볼 수 있게 추가합니다.
    for role_name in ["대표", "부대표", "총관리자", "부관리자"]:
        role = discord.utils.get(guild.roles, name=role_name)
        if role:
            overwrites[role] = discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True)

    await category.edit(overwrites=overwrites)
    for channel in category.channels:
        await channel.edit(sync_permissions=True)


async def apply_default_server_permissions(guild: discord.Guild, default_category: discord.CategoryChannel):
    """인사/퇴장/인증은 미인증만 보이게 설정합니다."""
    unverified_role = discord.utils.get(guild.roles, name="미인증")

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
    }
    if unverified_role:
        overwrites[unverified_role] = discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True)

    await default_category.edit(overwrites=overwrites)
    for channel in default_category.channels:
        await channel.edit(sync_permissions=True)


async def apply_rule_category_permissions(guild: discord.Guild, category: discord.CategoryChannel):
    """필독 카테고리는 미인증/인증 유저 모두 볼 수 있게 설정합니다."""
    unverified_role = discord.utils.get(guild.roles, name="미인증")

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=True, read_message_history=True),
        guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
    }
    if unverified_role:
        overwrites[unverified_role] = discord.PermissionOverwrite(view_channel=True, read_message_history=True)

    await category.edit(overwrites=overwrites)
    for channel in category.channels:
        await channel.edit(sync_permissions=True)


async def send_rules_message_to_channel(channel: discord.TextChannel):
    """규칙 채널에 설정된 규칙 임베드를 전송합니다. 이미 있으면 중복 전송하지 않습니다."""
    try:
        async for msg in channel.history(limit=30):
            if msg.author == bot.user and msg.embeds:
                title = msg.embeds[0].title or ""
                if "서버 규칙" in title or "규칙" in title:
                    return False
    except discord.HTTPException:
        pass

    await channel.send(embed=build_auto_embed(channel.guild, "rules"))
    return True


async def create_rule_category_channels(guild: discord.Guild):
    """필독/규칙 채널을 확인합니다.

    기본값에서는 `📌 필독` 카테고리와 `｜・(📌)：필독`, `｜・(📜)：규칙` 채널을
    자동 생성하지 않습니다. 이미 존재하는 경우에만 권한/안내를 정리합니다.
    """
    if MNB_DISABLE_AUTO_RULE_CATEGORY:
        rule_category = mnb_find_category_loose(guild, "📌 필독")
        rule_channel = get_channel_by_id_or_name(
            guild, RULE_CHANNEL_ID, ["｜・(📌)：필독", "📌︱필독", "필독", "📌-필독", "규칙"], "text"
        )
        rules_channel = get_channel_by_id_or_name(
            guild, 0, ["｜・(📜)：규칙", "📜︱이용규칙", "규칙", "📜-규칙", "이용규칙"], "text"
        )
        # 자동 생성은 꺼져 있어도, 이미 있는 채널 이름이 예전 스타일이면 새로 만들지 않고 이름만 예쁘게 바꿔줍니다.
        if isinstance(rule_channel, discord.TextChannel) and rule_channel.name != "｜・(📌)：필독":
            try:
                await rule_channel.edit(name="｜・(📌)：필독")
            except (discord.Forbidden, discord.HTTPException):
                pass
        if isinstance(rules_channel, discord.TextChannel) and rules_channel.name != "｜・(📜)：규칙":
            try:
                await rules_channel.edit(name="｜・(📜)：규칙")
            except (discord.Forbidden, discord.HTTPException):
                pass
        rules_message_sent = False
        if rule_category is not None:
            await apply_rule_category_permissions(guild, rule_category)
            if isinstance(rules_channel, discord.TextChannel):
                rules_message_sent = await send_rules_message_to_channel(rules_channel)
        return rule_category, rule_channel, rules_channel, rules_message_sent

    rule_category = await get_or_create_category(guild, "📌 필독")
    await mnb_cleanup_old_named_channels(rule_category, MNB_OLD_PLAIN_NAMES_BY_SCOPE["rule"])
    rule_channel = await get_or_create_text_channel(guild, "｜・(📌)：필독", rule_category)
    rules_channel = await get_or_create_text_channel(guild, "｜・(📜)：규칙", rule_category)
    await get_or_create_text_channel(guild, "｜・(👋)：인사-퇴장", rule_category)
    boost_channel = await get_or_create_text_channel(guild, "｜・(🚀)：서버부스트", rule_category)
    await apply_rule_category_permissions(guild, rule_category)
    save_guild_channel_ids(guild, boost_channel_id=boost_channel)
    rules_message_sent = await send_rules_message_to_channel(rules_channel)
    await create_recruit_channels_under_rule(guild)
    return rule_category, rule_channel, rules_channel, rules_message_sent, boost_channel


async def apply_member_category_permissions(guild: discord.Guild, category: discord.CategoryChannel):
    """일반 카테고리는 인증한 유저는 보이고 미인증은 안 보이게 설정합니다."""
    unverified_role = discord.utils.get(guild.roles, name="미인증")

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=True, read_message_history=True),
        guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True, connect=True, speak=True),
    }
    if unverified_role:
        overwrites[unverified_role] = discord.PermissionOverwrite(view_channel=False, connect=False)

    await category.edit(overwrites=overwrites)
    for channel in category.channels:
        await channel.edit(sync_permissions=True)


