async def create_game_category_channels(guild: discord.Guild):
    """🎮 게임방 카테고리와 게임 채팅/역할/음성방을 간단하게 생성합니다.

    v232 변경점
    - 발로란트/롤 티어별 음성방을 만들지 않습니다.
    - 발로란트 티어 통방, 롤 티어 통방도 만들지 않습니다.
    - 발로란트/롤 티어표 텍스트 채널도 자동 생성하지 않습니다.
    - 일반 게임 음성방은 최대 4개까지만 만듭니다.
    """
    game_category = await get_or_create_category(guild, "🎮 게임방")
    await apply_member_category_permissions(guild, game_category)
    await mnb_cleanup_old_named_channels(game_category, MNB_OLD_PLAIN_NAMES_BY_SCOPE["game"])

    game_chat_channel = await get_or_create_text_channel(guild, "｜・(🎮)：게임채팅", game_category)
    game_role_channel = await get_or_create_text_channel(guild, "｜・(🎮)：게임역할선택", game_category)

    game_role_panel_sent = await send_game_role_panel_to_channel(game_role_channel)

    # 일반 게임 음성방은 최대 4개까지만 자동 생성합니다.
    game_voice_channels = []
    for index in range(1, 5):
        voice_channel = await get_or_create_voice_channel(guild, f"・(🎮) 게임 음성 {index}", game_category)
        game_voice_channels.append(voice_channel)
        await asyncio.sleep(0.03)

    save_guild_settings(guild, game_role_channel=game_role_channel)
    return {
        "game_category": game_category,
        "game_chat_channel": game_chat_channel,
        "game_role_channel": game_role_channel,
        "game_role_panel_sent": game_role_panel_sent,
        "game_voice_channel": game_voice_channels[0] if game_voice_channels else None,
        "game_voice_channels": game_voice_channels,
        "valorant_tier_channel": None,
        "lol_tier_channel": None,
        "valorant_voice_channel": None,
        "lol_voice_channel": None,
        "valorant_voice_channels": [],
        "lol_voice_channels": [],
    }


