# 같은 사람에게 같은 날 포인트가 두 번 지급되지 않도록 남기는 기록입니다.
try:
    c.execute("""
    CREATE TABLE IF NOT EXISTS birthday_reward_logs (
        guild_id INTEGER,
        user_id INTEGER,
        reward_date TEXT,
        PRIMARY KEY (guild_id, user_id, reward_date)
    )
    """)
    conn.commit()
except sqlite3.Error:
    pass


def get_kst_today() -> datetime.date:
    return datetime.datetime.now(KST_TIMEZONE).date()


def parse_birthday_date(text: str):
    """생일 입력을 더 넓게 인식합니다.

    지원 예시: 03-14, 3/14, 3.14, 3월14일, 0314, 2009-03-14, 2009.03.14
    생년을 입력하지 않으면 0으로 저장해서 나이는 표시하지 않습니다.
    """
    value = (text or "").strip()
    if not value:
        return None

    value = value.replace("년", "-").replace("월", "-").replace("일", "")
    value = value.replace("/", "-").replace(".", "-").replace("_", "-")
    value = re.sub(r"\s+", "", value)

    compact = re.fullmatch(r"(\d{4})?(\d{2})(\d{2})", value)
    if compact:
        year = int(compact.group(1) or 0)
        month = int(compact.group(2))
        day = int(compact.group(3))
    else:
        match = re.fullmatch(r"(?:(\d{4})-)?(\d{1,2})-(\d{1,2})", value)
        if not match:
            return None
        year = int(match.group(1) or 0)
        month = int(match.group(2))
        day = int(match.group(3))

    try:
        datetime.date(year or 2000, month, day)
    except ValueError:
        return None
    return year, month, day


def calculate_birthday_age(birth_year: int, month: int, day: int) -> int:
    if not birth_year:
        return -1
    today = get_kst_today()
    age = today.year - int(birth_year) - ((today.month, today.day) < (int(month), int(day)))
    return age if age >= 0 else -1


def days_until_birthday(month: int, day: int, today: datetime.date = None) -> int:
    today = today or get_kst_today()
    try:
        target = datetime.date(today.year, int(month), int(day))
    except ValueError:
        # 2/29는 윤년이 아닌 해에는 3/1로 계산합니다.
        target = datetime.date(today.year, 3, 1)
    if target < today:
        try:
            target = datetime.date(today.year + 1, int(month), int(day))
        except ValueError:
            target = datetime.date(today.year + 1, 3, 1)
    return (target - today).days


def format_birthday_record(guild: discord.Guild, row):
    user_id, month, day, birth_year, age_visible, note = row
    dday = days_until_birthday(int(month), int(day))
    if dday == 0:
        dday_text = " · **오늘! 🎉**"
    elif dday == 1:
        dday_text = " · D-1"
    else:
        dday_text = f" · D-{dday}"

    age_text = ""
    age = calculate_birthday_age(int(birth_year or 0), int(month), int(day))
    if age_visible and age >= 0:
        age_text = f" · {age}살"

    note_text = f" · {str(note)[:40]}" if note else ""
    return f"🎂 <@{int(user_id)}> — **{int(month):02d}/{int(day):02d}**{dday_text}{age_text}{note_text}"


def fetch_birthday_rows(guild_id: int, *, month: int = None, limit: int = 200):
    if month:
        c.execute(
            """
            SELECT user_id, month, day, birth_year, age_visible, note
            FROM birthday_records
            WHERE guild_id=? AND month=?
            ORDER BY day ASC, user_id ASC
            LIMIT ?
            """,
            (guild_id, int(month), int(limit)),
        )
    else:
        c.execute(
            """
            SELECT user_id, month, day, birth_year, age_visible, note
            FROM birthday_records
            WHERE guild_id=?
            ORDER BY month ASC, day ASC, user_id ASC
            LIMIT ?
            """,
            (guild_id, int(limit)),
        )
    return c.fetchall()


def fetch_upcoming_birthday_rows(guild_id: int, days: int = 30, limit: int = 15):
    rows = fetch_birthday_rows(guild_id, limit=500)
    rows.sort(key=lambda row: (days_until_birthday(int(row[1]), int(row[2])), int(row[1]), int(row[2]), int(row[0])))
    result = []
    for row in rows:
        if days_until_birthday(int(row[1]), int(row[2])) <= days:
            result.append(row)
        if len(result) >= limit:
            break
    return result


def build_birthday_record_embed(guild: discord.Guild):
    rows = fetch_birthday_rows(guild.id, limit=500)
    today = get_kst_today()
    embed = discord.Embed(
        title="🎁 생일기록",
        description=(
            "서버 멤버들의 생일을 월별로 정리했어요.\n"
            "개인정보 보호를 위해 생년/나이는 본인이 공개로 선택했을 때만 표시됩니다.\n\n"
            "🎂 등록/수정은 `｜・(🎂)：생일등록` 채널 버튼 또는 `/생일 등록`으로 할 수 있어요."
        ),
        color=0x87CEEB,
    )
    if guild.icon:
        embed.set_thumbnail(url=guild.icon.url)

    today_rows = [row for row in rows if int(row[1]) == today.month and int(row[2]) == today.day]
    upcoming_rows = fetch_upcoming_birthday_rows(guild.id, days=30, limit=8)

    if today_rows:
        embed.add_field(
            name="🎉 오늘 생일",
            value="\n".join(format_birthday_record(guild, row) for row in today_rows)[:1024],
            inline=False,
        )

    if upcoming_rows:
        embed.add_field(
            name="🩵 다가오는 생일 30일",
            value="\n".join(format_birthday_record(guild, row) for row in upcoming_rows)[:1024],
            inline=False,
        )

    monthly = {}
    for row in rows:
        monthly.setdefault(int(row[1]), []).append(row)

    if monthly:
        for month in range(1, 13):
            month_rows = monthly.get(month, [])
            if not month_rows:
                continue
            value = "\n".join(format_birthday_record(guild, row) for row in month_rows[:12])
            if len(month_rows) > 12:
                value += f"\n…외 {len(month_rows) - 12}명"
            embed.add_field(name=f"{month}월 생일 · {len(month_rows)}명", value=value[:1024], inline=False)
    else:
        embed.add_field(
            name="아직 기록 없음",
            value="`｜・(🎂)：생일등록` 채널의 버튼 또는 `/생일 등록`으로 첫 생일을 등록해보세요.",
            inline=False,
        )

    embed.set_footer(text=f"만능 봇 | 생일기록 자동 업데이트 | 등록 {len(rows)}명")
    return embed


async def safe_ephemeral_send(interaction: discord.Interaction, content: str = None, *, embed: discord.Embed = None, view: discord.ui.View = None):
    kwargs = {"ephemeral": True}
    if content is not None:
        kwargs["content"] = content
    if embed is not None:
        kwargs["embed"] = embed
    if view is not None:
        kwargs["view"] = view
    if interaction.response.is_done():
        return await interaction.followup.send(**kwargs)
    return await safe_interaction_send(interaction, **kwargs)


async def sync_birthday_record_channel(guild: discord.Guild):
    channel = get_channel_by_id_or_name(guild, 0, ["｜・(🎁)：생일기록", "생일기록"], "text")
    if not channel:
        return False

    embed = build_birthday_record_embed(guild)
    try:
        async for msg in channel.history(limit=40):
            if msg.author == bot.user and msg.embeds and (msg.embeds[0].title or "") == "🎁 생일기록":
                await msg.edit(embed=embed)
                return True
        await channel.send(embed=embed)
        return True
    except (discord.Forbidden, discord.HTTPException):
        return False


async def show_my_birthday_record(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_ephemeral_send(interaction, "❌ 서버에서만 사용할 수 있어요.")
    c.execute(
        "SELECT user_id, month, day, birth_year, age_visible, note FROM birthday_records WHERE guild_id=? AND user_id=?",
        (interaction.guild.id, interaction.user.id),
    )
    row = c.fetchone()
    if not row:
        return await safe_ephemeral_send(interaction, "ℹ️ 아직 생일을 등록하지 않았어요. `생일 등록` 버튼을 눌러서 등록해보세요.")

    embed = discord.Embed(
        title="🎂 내 생일 기록",
        description=format_birthday_record(interaction.guild, row),
        color=0x87CEEB,
    )
    embed.set_footer(text="만능 봇 | 생일 확인")
    await safe_ephemeral_send(interaction, embed=embed)


async def show_birthday_list_for_interaction(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_ephemeral_send(interaction, "❌ 서버에서만 사용할 수 있어요.")
    await sync_birthday_record_channel(interaction.guild)
    rows = fetch_upcoming_birthday_rows(interaction.guild.id, days=60, limit=20)
    if not rows:
        return await safe_ephemeral_send(interaction, "ℹ️ 아직 등록된 생일이 없어요.")

    embed = discord.Embed(
        title="🎁 다가오는 생일 목록",
        description="가까운 생일부터 최대 20명까지 보여줘요.",
        color=0x87CEEB,
    )
    embed.add_field(name="다가오는 생일", value="\n".join(format_birthday_record(interaction.guild, row) for row in rows)[:1024], inline=False)
    embed.set_footer(text="만능 봇 | 생일 목록")
    await safe_ephemeral_send(interaction, embed=embed)


async def show_upcoming_birthdays_for_interaction(interaction: discord.Interaction, days: int = 30):
    if interaction.guild is None:
        return await safe_ephemeral_send(interaction, "❌ 서버에서만 사용할 수 있어요.")
