def build_birthday_register_panel_embed(guild: discord.Guild):
    upcoming_rows = fetch_upcoming_birthday_rows(guild.id, days=30, limit=5) if guild else []
    upcoming_text = "\n".join(format_birthday_record(guild, row) for row in upcoming_rows) if upcoming_rows else "아직 다가오는 생일 기록이 없어요."
    embed = discord.Embed(
        title="🩵🎂 생일 등록 센터",
        description=(
            "아래 버튼으로 생일을 쉽고 예쁘게 관리할 수 있어요.\n"
            "나이는 기본 비공개이며, 본인이 공개를 선택했을 때만 기록에 표시됩니다.\n\n"
            "**사용 가능한 입력 예시**\n"
            "`03-14` · `0314` · `3월14일` · `2009-03-14`\n\n"
            "**버튼 안내**\n"
            "🎂 등록 · ✏️ 수정 · 🔍 내 생일 · 🩵 다가오는 생일 · 🎁 목록 · 🗑️ 삭제"
        ),
        color=0x87CEEB,
    )
    embed.add_field(name="🩵 다가오는 생일 미리보기", value=upcoming_text[:1024], inline=False)
    embed.add_field(name="🔒 개인정보 안내", value="생년을 입력하지 않으면 나이는 저장/표시되지 않아요. 생년을 입력해도 공개 여부를 끄면 월/일만 보여요.", inline=False)
    if guild and guild.icon:
        embed.set_thumbnail(url=guild.icon.url)
    embed.set_footer(text="만능 봇 | 생일 등록 센터 | Sky Blue Edition")
    return embed


async def send_birthday_register_panel_once(channel: discord.TextChannel):
    embed = build_birthday_register_panel_embed(channel.guild)
    view = BirthdayPanelView()
    try:
        async for msg in channel.history(limit=40):
            if msg.author == bot.user and msg.embeds:
                title = msg.embeds[0].title or ""
                if "생일" in title and ("등록 패널" in title or "등록 센터" in title):
                    await msg.edit(embed=embed, view=view)
                    return False
        await channel.send(embed=embed, view=view)
        return True
    except (discord.Forbidden, discord.HTTPException):
        return False


# =========================
# 생일 자동 보상/역할 시스템
# =========================
BIRTHDAY_REWARD_DEFAULTS = {
    "enabled": 1,
    "reward_point": 1000,
    "role_name": "🎂 생일자",
    "remove_next_day": 1,
    "dm_enabled": 1,
}


def get_birthday_reward_settings(guild_id: int) -> dict:
    """서버별 생일 보상 설정을 가져오거나 기본값으로 생성합니다."""
    try:
        c.execute(
            "SELECT enabled, reward_point, role_name, remove_next_day, dm_enabled "
            "FROM birthday_reward_settings WHERE guild_id=?",
            (guild_id,),
        )
        row = c.fetchone()
    except sqlite3.Error:
        row = None

    if row is None:
        try:
            c.execute(
                "INSERT OR IGNORE INTO birthday_reward_settings"
                "(guild_id, enabled, reward_point, role_name, remove_next_day, dm_enabled, updated_at) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                (
                    guild_id,
                    BIRTHDAY_REWARD_DEFAULTS["enabled"],
                    BIRTHDAY_REWARD_DEFAULTS["reward_point"],
                    BIRTHDAY_REWARD_DEFAULTS["role_name"],
                    BIRTHDAY_REWARD_DEFAULTS["remove_next_day"],
                    BIRTHDAY_REWARD_DEFAULTS["dm_enabled"],
                    datetime.datetime.now(KST_TIMEZONE).strftime("%Y-%m-%d %H:%M:%S"),
                ),
            )
            conn.commit()
        except sqlite3.Error:
            pass
        return dict(BIRTHDAY_REWARD_DEFAULTS)

    return {
        "enabled": int(row[0] or 0),
        "reward_point": int(row[1] or 0),
        "role_name": (row[2] or "").strip(),
        "remove_next_day": int(row[3] or 0),
        "dm_enabled": int(row[4] or 0),
    }


def update_birthday_reward_settings(guild_id: int, **fields) -> dict:
    """생일 보상 설정 일부 항목만 갱신합니다."""
    current = get_birthday_reward_settings(guild_id)
    current.update({k: v for k, v in fields.items() if v is not None})
    try:
        c.execute(
            "INSERT INTO birthday_reward_settings"
            "(guild_id, enabled, reward_point, role_name, remove_next_day, dm_enabled, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(guild_id) DO UPDATE SET "
            "enabled=excluded.enabled, reward_point=excluded.reward_point, "
            "role_name=excluded.role_name, remove_next_day=excluded.remove_next_day, "
            "dm_enabled=excluded.dm_enabled, updated_at=excluded.updated_at",
            (
                guild_id,
                int(current["enabled"]),
                int(current["reward_point"]),
                (current["role_name"] or "").strip(),
                int(current["remove_next_day"]),
                int(current["dm_enabled"]),
                datetime.datetime.now(KST_TIMEZONE).strftime("%Y-%m-%d %H:%M:%S"),
            ),
        )
        conn.commit()
    except sqlite3.Error:
        pass
    return current


async def get_or_create_birthday_role(guild: discord.Guild, role_name: str):
    """생일 역할이 없으면 만들어서 반환합니다. 실패하면 None."""
    role_name = (role_name or "").strip()
    if not role_name:
        return None
    role = discord.utils.get(guild.roles, name=role_name)
    if role is not None:
        return role
    try:
        role = await guild.create_role(
            name=role_name,
            color=discord.Color.from_rgb(135, 206, 235),
            hoist=True,
            mentionable=True,
            reason="생일 자동 축하 역할 생성",
        )
        return role
    except (discord.Forbidden, discord.HTTPException):
        return None


async def grant_birthday_rewards(guild: discord.Guild, rows, today_text: str):
    """오늘 생일인 멤버들에게 포인트/역할을 지급하고 결과 텍스트를 돌려줍니다.

    rows: (user_id, month, day, birth_year, age_visible, note) 형태의 목록
    반환: 축하 메시지에 덧붙일 요약 문자열(없으면 빈 문자열)
    """
    settings = get_birthday_reward_settings(guild.id)
    if not settings["enabled"]:
        return ""

    reward_point = int(settings["reward_point"] or 0)
    role = None
    if settings["role_name"]:
        role = await get_or_create_birthday_role(guild, settings["role_name"])

    rewarded_point_members = []
    role_members = []

    for row in rows:
        user_id = int(row[0])
        member = guild.get_member(user_id)
        if member is None:
            try:
                member = await guild.fetch_member(user_id)
            except (discord.NotFound, discord.HTTPException):
                member = None
        if member is None:
            continue

        # 포인트 지급 (하루 1회만)
        if reward_point > 0:
            try:
                c.execute(
                    "SELECT 1 FROM birthday_reward_logs WHERE guild_id=? AND user_id=? AND reward_date=?",
                    (guild.id, user_id, today_text),
                )
                already = c.fetchone()
            except sqlite3.Error:
                already = None

            if not already:
                current_point = get_user_point(guild.id, user_id)
                set_user_point(guild.id, user_id, current_point + reward_point)
                try:
                    c.execute(
                        "INSERT OR IGNORE INTO birthday_reward_logs(guild_id, user_id, reward_date) VALUES (?, ?, ?)",
                        (guild.id, user_id, today_text),
                    )
                    conn.commit()
                except sqlite3.Error:
                    pass
                rewarded_point_members.append(member)

        # 역할 지급
        if role is not None and role not in getattr(member, "roles", []):
            try:
                await member.add_roles(role, reason="생일 자동 축하 역할 지급")
                role_members.append(member)
                c.execute(
                    "INSERT OR REPLACE INTO birthday_role_grants(guild_id, user_id, role_id, granted_date) "
                    "VALUES (?, ?, ?, ?)",
                    (guild.id, user_id, role.id, today_text),
                )
                conn.commit()
            except (discord.Forbidden, discord.HTTPException):
                pass
            except sqlite3.Error:
                pass
        elif role is not None:
            # 이미 역할이 있어도 회수 기준일은 오늘로 갱신합니다.
            try:
                c.execute(
                    "INSERT OR REPLACE INTO birthday_role_grants(guild_id, user_id, role_id, granted_date) "
                    "VALUES (?, ?, ?, ?)",
                    (guild.id, user_id, role.id, today_text),
                )
                conn.commit()
            except sqlite3.Error:
                pass

        # 축하 DM
        if settings["dm_enabled"]:
            try:
                dm_lines = ["🎉 생일 축하해요! 오늘 하루 행복하게 보내세요. 🎂"]
                if reward_point > 0:
                    dm_lines.append(f"🎁 생일 선물로 **{reward_point:,} 포인트**를 드렸어요!")
                if role is not None:
                    dm_lines.append(f"👑 오늘 하루 **{role.name}** 역할을 달아드렸어요!")
                await member.send("\n".join(dm_lines))
            except (discord.Forbidden, discord.HTTPException):
                pass

    # 축하 임베드에 덧붙일 요약
    summary_parts = []
    if reward_point > 0 and rewarded_point_members:
        summary_parts.append(f"🎁 생일 포인트 **{reward_point:,}P** 지급 완료!")
    if role is not None and role_members:
        summary_parts.append(f"👑 오늘 하루 **{role.name}** 역할을 달아드렸어요!")
    return ("\n\n" + "\n".join(summary_parts)) if summary_parts else ""


async def cleanup_expired_birthday_roles(guild: discord.Guild, today_text: str):
    """생일 다음 날이 된 멤버의 생일 역할을 회수합니다."""
    settings = get_birthday_reward_settings(guild.id)
    if not settings["remove_next_day"]:
        return
    try:
        c.execute(
            "SELECT user_id, role_id, granted_date FROM birthday_role_grants WHERE guild_id=?",
            (guild.id,),
        )
        grants = c.fetchall()
    except sqlite3.Error:
        return

    for user_id, role_id, granted_date in grants:
        # 오늘 지급한 역할은 유지, 그 이전에 지급한 역할만 회수합니다.
        if str(granted_date) == today_text:
            continue
        role = guild.get_role(int(role_id))
        member = guild.get_member(int(user_id))
        if role is not None and member is not None and role in member.roles:
            try:
                await member.remove_roles(role, reason="생일 다음 날 역할 자동 회수")
            except (discord.Forbidden, discord.HTTPException):
                pass
        try:
            c.execute(
                "DELETE FROM birthday_role_grants WHERE guild_id=? AND user_id=? AND role_id=?",
                (guild.id, int(user_id), int(role_id)),
            )
            conn.commit()
        except sqlite3.Error:
            pass


@tasks.loop(minutes=30)
async def birthday_daily_reminder():
    """매일 오전 9시(KST)에 오늘 생일을 한 번만 축하합니다."""
    now = datetime.datetime.now(KST_TIMEZONE)
    # 09:00~09:29 사이에만 작동해서 30분 루프가 하루 1회만 발송합니다.
    if now.hour != 9 or now.minute >= 30:
        return

    today_text = now.date().isoformat()
    for guild in list(bot.guilds):
        try:
            c.execute("SELECT 1 FROM birthday_notification_logs WHERE guild_id=? AND sent_date=?", (guild.id, today_text))
            if c.fetchone():
                continue

            # 어제 생일이었던 멤버의 생일 역할을 먼저 회수합니다. (오늘 생일이 없어도 실행)
            try:
                await cleanup_expired_birthday_roles(guild, today_text)
            except Exception:
                pass

            c.execute(
                """
                SELECT user_id, month, day, birth_year, age_visible, note
                FROM birthday_records
                WHERE guild_id=? AND month=? AND day=?
                ORDER BY user_id ASC
                """,
                (guild.id, now.month, now.day),
            )
            rows = c.fetchall()
            if not rows:
                # 오늘 생일이 없어도 역할 회수는 이미 처리했으니 오늘 실행 기록을 남깁니다.
                try:
                    c.execute(
                        "INSERT OR IGNORE INTO birthday_notification_logs(guild_id, sent_date, created_at) VALUES (?, ?, ?)",
                        (guild.id, today_text, now.strftime("%Y-%m-%d %H:%M:%S")),
                    )
                    conn.commit()
                except sqlite3.Error:
                    pass
                continue

            # 포인트/역할 자동 지급
            reward_summary = ""
            try:
                reward_summary = await grant_birthday_rewards(guild, rows, today_text)
            except Exception as e:
                print(f"⚠️ {getattr(guild, 'name', guild.id)} 생일 보상 지급 실패: {e}")

            channel = get_channel_by_id_or_name(guild, 0, ["｜・(🎁)：생일기록", "｜・(🎂)：생일등록", "생일기록", "생일등록"], "text")
            if not channel:
                # 채널이 없어도 보상은 이미 지급했으니 오늘 실행 기록을 남깁니다.
                try:
                    c.execute(
                        "INSERT OR IGNORE INTO birthday_notification_logs(guild_id, sent_date, created_at) VALUES (?, ?, ?)",
                        (guild.id, today_text, now.strftime("%Y-%m-%d %H:%M:%S")),
                    )
                    conn.commit()
                except sqlite3.Error:
                    pass
                continue

            mentions = " ".join(f"<@{int(row[0])}>" for row in rows[:10])
            embed = discord.Embed(
                title="🎉 오늘 생일이에요!",
                description=(
                    f"오늘 생일인 멤버를 다 같이 축하해줘요!\n\n{mentions}\n\n"
                    + "\n".join(format_birthday_record(guild, row) for row in rows[:15])
                    + (reward_summary or "")
                )[:4000],
                color=0x87CEEB,
            )
            if guild.icon:
                embed.set_thumbnail(url=guild.icon.url)
            embed.set_footer(text="만능 봇 | 매일 오전 9시 생일 알림")
            await channel.send(embed=embed)
            await sync_birthday_record_channel(guild)

            c.execute(
                "INSERT OR IGNORE INTO birthday_notification_logs(guild_id, sent_date, created_at) VALUES (?, ?, ?)",
                (guild.id, today_text, now.strftime("%Y-%m-%d %H:%M:%S")),
            )
            conn.commit()
        except Exception as e:
            print(f"⚠️ {getattr(guild, 'name', guild.id)} 생일 알림 실패: {e}")


