async def send_music_panel_to_channel(channel: discord.TextChannel):
    """뮤직 명령어 채널에 뮤직 패널을 전송합니다. 이미 있으면 중복 전송하지 않습니다."""
    try:
        async for msg in channel.history(limit=30):
            if msg.author == bot.user and msg.embeds:
                title = msg.embeds[0].title or ""
                if "뮤직" in title and msg.components:
                    return False
    except discord.HTTPException:
        pass

    embed = await build_music_panel_embed()
    embed = apply_custom_panel_embed(channel.guild, "music", embed)
    await channel.send(embed=embed, view=MusicPanelView())
    return True


def get_saved_music_panel_channel(guild: discord.Guild):
    """/서버 음악채널설정 또는 대시보드에서 지정한 뮤직 패널 채널을 우선 사용합니다."""
    if guild is None:
        return None
    try:
        saved_id = int(get_saved_channel_id(guild.id, "music_command_channel_id") or 0)
    except Exception:
        saved_id = 0
    if not saved_id:
        return None
    channel = guild.get_channel(saved_id)
    if isinstance(channel, discord.TextChannel):
        return channel
    return None


