async def create_tts_category_channels(guild: discord.Guild):
    """🔊 TTS 카테고리, TTS 채팅방 1개, TTS 통방 3개를 생성/확인합니다.

    v228: 관리자가 `/서버 tts채널설정`으로 지정한 채널이 있으면
    기본 `｜・(🔊)：tts` 채널을 새로 만들지 않고 지정 채널을 TTS 안내/채팅 기준으로 사용합니다.
    """
    tts_category = await get_or_create_category(guild, TTS_CATEGORY_NAME)
    await apply_member_category_permissions(guild, tts_category)
    await mnb_cleanup_old_named_channels(tts_category, MNB_OLD_PLAIN_NAMES_BY_SCOPE["tts"])

    tts_text_channel = None
    try:
        saved_tts_text_id = int(get_saved_channel_id(guild.id, "tts_text_channel_id") or 0)
        if saved_tts_text_id:
            saved_channel = guild.get_channel(saved_tts_text_id)
            if isinstance(saved_channel, discord.TextChannel):
                tts_text_channel = saved_channel
    except Exception:
        tts_text_channel = None

    if tts_text_channel is None:
        tts_text_channel = await get_or_create_text_channel(guild, TTS_TEXT_CHANNEL_NAME, tts_category)
        save_guild_channel_ids(guild, tts_text_channel_id=tts_text_channel)

    tts_voice_channels = []
    for voice_name in TTS_VOICE_CHANNEL_NAMES:
        voice_channel = await get_or_create_voice_channel(guild, voice_name, tts_category)
        tts_voice_channels.append(voice_channel)
        await asyncio.sleep(0.1)
    await get_or_create_voice_channel(guild, TEMP_VOICE_CREATE_CHANNEL_NAME, tts_category)

    guide_sent = await send_tts_guide_to_channel(tts_text_channel)
    first_voice_channel = tts_voice_channels[0] if tts_voice_channels else None
    if first_voice_channel:
        save_guild_channel_ids(guild, tts_voice_channel_id=first_voice_channel)
    return tts_category, tts_text_channel, first_voice_channel, guide_sent


def get_tts_voice_channels(guild: discord.Guild):
    if guild is None:
        return []
    channels = []
    for name in TTS_VOICE_CHANNEL_NAMES:
        channel = discord.utils.get(guild.voice_channels, name=name)
        if channel:
            channels.append(channel)
    return channels


def find_auto_tts_voice_channel(member: discord.Member, text_channel: discord.TextChannel = None):
    """TTS 채팅방에 글을 입력했을 때 봇이 들어갈 통방을 고릅니다."""
    if member is None or member.guild is None:
        return None

    # 유저가 이미 음성방에 있으면 그 방으로 들어갑니다.
    if member.voice and member.voice.channel:
        return member.voice.channel

    # 유저가 음성방에 없을 때는 TTS 통방 중 사람이 있는 방을 먼저 찾습니다.
    tts_voice_channels = get_tts_voice_channels(member.guild)
    for channel in tts_voice_channels:
        humans = [m for m in channel.members if not m.bot]
        if humans:
            return channel

    # 아무도 없으면 첫 번째 TTS 통방으로 들어갑니다.
    if tts_voice_channels:
        return tts_voice_channels[0]

    return None


def get_existing_tts_voice_client(guild: discord.Guild):
    """이미 /입장으로 연결된 TTS 음성 클라이언트만 찾습니다. 없으면 None입니다."""
    if guild is None:
        return None
    try:
        if TTS_BOT_TOKEN and tts_sub_bot and tts_sub_bot.is_ready():
            sub_guild = tts_sub_bot.get_guild(guild.id)
            if sub_guild is not None:
                existing = discord.utils.get(tts_sub_bot.voice_clients, guild=sub_guild)
                if existing is not None and getattr(existing, "channel", None) is not None:
                    return existing
    except Exception:
        pass
    existing = getattr(guild, "voice_client", None)
    if existing is not None and getattr(existing, "channel", None) is not None:
        return existing
    return None


def member_is_in_tts_voice_channel(member: discord.Member, voice_client) -> bool:
    """TTS 봇이 들어간 음성방에 있는 유저의 채팅만 읽습니다."""
    try:
        if member is None or voice_client is None or not getattr(voice_client, "channel", None):
            return False
        if not getattr(member, "voice", None) or not member.voice.channel:
            return False
        return int(member.voice.channel.id) == int(voice_client.channel.id)
    except Exception:
        return False


def message_is_connected_voice_chat(message: discord.Message, voice_client) -> bool:
    """메시지가 TTS 봇이 들어간 바로 그 음성 채널의 채팅인지 확인합니다.

    Discord 음성 채널에는 채널 안에 붙어 있는 채팅이 있고,
    discord.py에서는 그 메시지의 channel id가 음성 채널 id와 같게 들어올 수 있습니다.
    일부 환경에서 thread/parent 형태로 들어오는 경우도 같이 허용합니다.
    """
    try:
        if message is None or voice_client is None or not getattr(voice_client, "channel", None):
            return False
        voice_channel_id = int(voice_client.channel.id)
        msg_channel = getattr(message, "channel", None)
        if msg_channel is None:
            return False
        if int(getattr(msg_channel, "id", 0) or 0) == voice_channel_id:
            return True
        parent = getattr(msg_channel, "parent", None)
        if parent is not None and int(getattr(parent, "id", 0) or 0) == voice_channel_id:
            return True
        parent_id = getattr(msg_channel, "parent_id", None)
        if parent_id is not None and int(parent_id) == voice_channel_id:
            return True
    except Exception:
        return False
    return False


def should_auto_tts_message(message: discord.Message) -> bool:
    """일반 채팅을 TTS로 읽을지 판단합니다.

    - 명령어(!, ., /)는 읽지 않습니다.
    - 채팅만으로 봇이 음성방에 자동 입장하지 않습니다.
    - `/입장`으로 TTS 봇이 먼저 들어온 뒤, 같은 음성방 유저의 채팅만 읽습니다.
    - 기본값은 일반 채팅방이 아니라, 그 음성 채널 안의 채팅만 읽기입니다.
    """
    if message is None or message.guild is None or getattr(message.author, "bot", False):
        return False

    content = (message.content or "").strip()
    if not content:
        return False
    if content.startswith(("!", ".", "/")):
        return False

    # 너무 긴 글은 TTS 도배 방지용으로 제외합니다.
    if len(content) > 120:
        return False

    voice_client = get_existing_tts_voice_client(message.guild)
    if MNB_TTS_REQUIRE_JOIN_COMMAND and voice_client is None:
        return False
    if voice_client is None:
        return False
    if not member_is_in_tts_voice_channel(message.author, voice_client):
        return False

    # 기본값: 서버 전체 채팅방/일반 채팅방은 읽지 않습니다.
    # 1순위: TTS 봇이 들어가 있는 그 음성 채널의 채팅
    # 2순위: 관리자가 `/서버 tts채널설정`으로 직접 지정한 TTS 텍스트 채널
    if MNB_TTS_ONLY_CONNECTED_VOICE_CHAT:
        if message_is_connected_voice_chat(message, voice_client):
            return True
        configured_tts_text_id = get_configured_tts_text_channel_id(message.guild)
        if configured_tts_text_id and int(getattr(message.channel, "id", 0) or 0) == int(configured_tts_text_id):
            return True
        return False

    # 예전 방식이 필요하면 MNB_TTS_READ_ALL_CHANNELS_AFTER_JOIN=1 로 켤 수 있습니다.
    if MNB_TTS_READ_ALL_CHANNELS_AFTER_JOIN:
        return True

    # 수동 제한 모드에서는 TTS 전용 텍스트 채널만 읽습니다.
    if getattr(message.channel, "name", "") in TTS_CHANNEL_NAMES:
        return True

    return False


def should_skip_tts_by_cooldown(message: discord.Message) -> bool:
    """v220: 자유 TTS가 너무 빠르게 반복 재생되는 것을 막습니다.

    관리자는 테스트/방송 상황에서 바로 말할 수 있게 쿨타임을 적용하지 않습니다.
    """
    if message is None or message.guild is None or message.author is None:
        return False
    if getattr(message.author, "guild_permissions", None) and message.author.guild_permissions.manage_messages:
        return False
    if MNB_TTS_AUTO_COOLDOWN_SECONDS <= 0:
        return False

    now_ts = time.time()
    key = (message.guild.id, message.author.id)
    last_ts = MNB_TTS_COOLDOWNS.get(key, 0.0)
    if now_ts - last_ts < MNB_TTS_AUTO_COOLDOWN_SECONDS:
        return True
    MNB_TTS_COOLDOWNS[key] = now_ts

    # 메모리가 계속 커지지 않게 오래된 항목을 가끔 정리합니다.
    if len(MNB_TTS_COOLDOWNS) > 1000:
        cutoff = now_ts - 60
        for old_key, ts in list(MNB_TTS_COOLDOWNS.items()):
            if ts < cutoff:
                MNB_TTS_COOLDOWNS.pop(old_key, None)
    return False


