class SetupBaseRoleOverrideModal(discord.ui.Modal, title="✏️ 기본 역할 꾸미기"):
    base_name = discord.ui.TextInput(label="기본 역할 이름", placeholder="예: 뉴페이스, 대표, 유튜버", max_length=100, required=True)
    new_name = discord.ui.TextInput(label="새 이름 (비우면 이름 유지)", placeholder="예: 새싹멤버", max_length=100, required=False)
    color_hex = discord.ui.TextInput(label="새 색상 (비우면 색 유지)", placeholder="#FFB6C1 / 핑크 / 골드 / 기본", max_length=20, required=False)

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        if guild is None:
            return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
        if await reject_if_not_setup_manager(interaction):
            return

        base = str(self.base_name.value or "").strip()
        known = {n for names in SETUP_BASE_ROLE_GROUPS.values() for n in names}
        if base not in known:
            return await safe_interaction_send(
                interaction,
                create_embed("❌ 꾸미기 실패", f"`{base}` 는 자동생성 기본 역할이 아니에요.\n기본 역할 이름을 정확히 입력해주세요.", COLOR_WARNING),
                ephemeral=True,
            )

        new_name_val = str(self.new_name.value or "").strip()
        color_val = str(self.color_hex.value or "").strip()
        if not new_name_val and not color_val:
            return await safe_interaction_send(interaction, "❌ 새 이름 또는 새 색상 중 하나는 입력해주세요.", ephemeral=True)

        stored_color = None
        if color_val:
            try:
                _c, color_text = parse_role_maker_color(color_val)
                stored_color = "" if color_text == "기본" else color_text
            except ValueError as e:
                return await safe_interaction_send(interaction, create_embed("❌ 꾸미기 실패", str(e), COLOR_WARNING), ephemeral=True)

        if new_name_val:
            try:
                new_name_val = validate_custom_role_name(new_name_val)
            except ValueError as e:
                return await safe_interaction_send(interaction, create_embed("❌ 꾸미기 실패", str(e), COLOR_WARNING), ephemeral=True)

        set_setup_role_override(
            guild.id, base,
            new_name=(new_name_val if new_name_val else None),
            color_hex=(stored_color if stored_color is not None else None),
        )
        await safe_interaction_send(interaction, embed=build_setup_role_customize_embed(guild), ephemeral=True)
        await send_log(guild, f"✏️ 기본 역할 오버라이드: `{base}`\n관리자: {interaction.user.mention}", "general")


class SetupCustomRoleRemoveSelect(discord.ui.Select):
    def __init__(self, guild: discord.Guild):
        options = []
        for role_name, _c, _h, group_key, _o in get_custom_setup_roles(guild.id):
            options.append(discord.SelectOption(label=role_name[:100], value=role_name[:100],
                                                description=f"{SETUP_ROLE_GROUP_LABELS.get(group_key, group_key)[:40]}"))
        if not options:
            options = [discord.SelectOption(label="등록된 커스텀 역할 없음", value="__none__")]
        super().__init__(placeholder="목록에서 뺄 커스텀 역할 선택", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        if await reject_if_not_setup_manager(interaction):
            return
        val = self.values[0]
        if val == "__none__":
            return await safe_interaction_send(interaction, "뺄 역할이 없어요.", ephemeral=True)
        remove_custom_setup_role(interaction.guild.id, val)
        await safe_interaction_send(
            interaction,
            f"✅ `{val}` 을(를) 자동생성 목록에서 제외했어요. (서버에 이미 만들어진 역할은 그대로 있어요.)",
            ephemeral=True,
        )


