setting_group = app_commands.Group(name="설정", description="서버 보안 기능을 설정합니다.")


async def require_admin_interaction(interaction: discord.Interaction):
    if interaction.guild is None:
        await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
        return False
    if not interaction.user.guild_permissions.administrator:
        await safe_interaction_send(interaction, "❌ 관리자만 사용할 수 있습니다.", ephemeral=True)
        return False
    return True


