@setting_group.command(name="인증역할설정", description="인증 시 지급할 역할과 제거할 역할을 직접 지정합니다.")
@app_commands.describe(
    지급역할="인증 완료 시 지급할 역할 (비워두면 기존 값 유지)",
    제거역할="인증 완료 시 제거할 역할 (비워두면 기존 값 유지)",
)
async def setting_verify_role(
    interaction: discord.Interaction,
    지급역할: discord.Role = None,
    제거역할: discord.Role = None,
):
    if not await require_admin_interaction(interaction):
        return
    if 지급역할 is None and 제거역할 is None:
        return await safe_interaction_send(
            interaction,
            "❌ `지급역할` 또는 `제거역할` 중 최소 하나는 선택해주세요.",
            ephemeral=True,
        )

    guild = interaction.guild
    bot_member = guild.me
    problems = []
    for label, role in (("지급역할", 지급역할), ("제거역할", 제거역할)):
        if role is None:
            continue
        if role.is_default():
            problems.append(f"`{label}`에 @everyone 은 지정할 수 없어요.")
        elif role.managed:
            problems.append(f"`{label}`({role.name})는 봇/연동 전용 역할이라 지정할 수 없어요.")
        elif bot_member and role >= bot_member.top_role:
            problems.append(f"`{label}`({role.name})가 봇 역할보다 위에 있어 사용할 수 없어요. 봇 역할을 더 위로 올려주세요.")
    if problems:
        return await safe_interaction_send(
            interaction,
            create_embed("❌ 인증 역할 설정 실패", "\n".join(problems), COLOR_WARNING),
            ephemeral=True,
        )

    set_verify_role(
        guild.id,
        grant_role_id=(지급역할.id if 지급역할 else None),
        remove_role_id=(제거역할.id if 제거역할 else None),
    )

    grant_role, remove_role = resolve_verify_roles(guild)
    embed = create_embed(
        "✅ 인증 역할 설정 완료",
        "이제 멤버가 `인증하기` 버튼으로 인증을 완료하면 아래 역할이 적용돼요.",
    )
    embed.add_field(name="지급 역할", value=(grant_role.mention if grant_role else "없음"), inline=True)
    embed.add_field(name="제거 역할", value=(remove_role.mention if remove_role else "없음"), inline=True)
    embed.add_field(
        name="안내",
        value="지정하지 않은 항목은 이전 설정(또는 기존 뉴페이스/미인증 기본값)을 그대로 사용합니다.",
        inline=False,
    )
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)
    await send_log(
        guild,
        f"🎭 인증 역할 설정\n지급: {grant_role.mention if grant_role else '없음'} / 제거: {remove_role.mention if remove_role else '없음'}\n관리자: {interaction.user.mention}",
        "general",
    )


@setting_group.command(name="인증역할확인", description="현재 인증 시 적용되는 지급/제거 역할을 확인합니다.")
async def setting_verify_role_view(interaction: discord.Interaction):
    if not await require_admin_interaction(interaction):
        return
    guild = interaction.guild
    grant_id, remove_id = get_verify_role_settings(guild.id)
    grant_role, remove_role = resolve_verify_roles(guild)

    def _fmt(role, custom_id):
        if role is None:
            return "설정 안 됨"
        source = "직접 지정" if custom_id else "기본값"
        return f"{role.mention} ({source})"

    embed = create_embed("🎭 현재 인증 역할", "인증 완료 시 적용되는 역할입니다.")
    embed.add_field(name="지급 역할", value=_fmt(grant_role, grant_id), inline=True)
    embed.add_field(name="제거 역할", value=_fmt(remove_role, remove_id), inline=True)
    embed.set_footer(text="변경: /설정 인증역할설정 · 초기화: /설정 인증역할초기화")
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)


