@app_commands.describe(
    상태="레이드 자동방어 켜기=True / 끄기=False",
    기준인원="이 인원 이상 몰려 입장하면 레이드로 판단 (기본 8)",
    감지초="몇 초 안의 입장을 세는지 (기본 15초)",
    조치="레이드 판단 시 취할 행동",
    신규계정일수="'신규계정 추방' 조치에서 신규로 볼 계정 나이(일) (기본 7)",
)
@app_commands.choices(조치=[
    app_commands.Choice(name="🔔 알림만", value="alert"),
    app_commands.Choice(name="👢 신규계정만 자동 추방", value="kick_new"),
    app_commands.Choice(name="👢 몰려든 인원 전원 추방", value="kick"),
    app_commands.Choice(name="⛔ 몰려든 인원 전원 밴", value="ban"),
])
async def setting_raid_guard(
    interaction: discord.Interaction,
    상태: bool = None,
    기준인원: int = None,
    감지초: int = None,
    조치: app_commands.Choice[str] = None,
    신규계정일수: int = None,
):
    if not await require_admin_interaction(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)

    fields = {}
    if 상태 is not None:
        fields["enabled"] = 상태
    if 기준인원 is not None:
        fields["join_threshold"] = max(2, int(기준인원))
    if 감지초 is not None:
        fields["window_seconds"] = max(3, int(감지초))
    if 조치 is not None:
        fields["action"] = 조치.value
    if 신규계정일수 is not None:
        fields["min_account_days"] = max(0, int(신규계정일수))

    settings = update_raid_guard_settings(interaction.guild.id, **fields)

    # 자동 추방/밴을 켰는데 봇 권한이 없으면 미리 경고합니다.
    warn_perm = ""
    me = interaction.guild.me
    if settings["enabled"] and settings["action"] in ("kick_new", "kick") and me and not me.guild_permissions.kick_members:
        warn_perm = "\n⚠️ 봇에게 **멤버 추방** 권한이 없어서 조치가 실패할 수 있어요."
    if settings["enabled"] and settings["action"] == "ban" and me and not me.guild_permissions.ban_members:
        warn_perm = "\n⚠️ 봇에게 **멤버 차단(밴)** 권한이 없어서 조치가 실패할 수 있어요."

    embed = create_embed(
        "🚨 레이드 자동방어 설정",
        f"상태: **{security_state_text(settings['enabled'])}**\n\n"
        f"감지 기준: **{settings['window_seconds']}초 내 {settings['join_threshold']}명 이상 입장**\n"
        f"조치: **{RAID_GUARD_ACTION_LABELS.get(settings['action'], settings['action'])}**\n"
        f"신규계정 기준: **{settings['min_account_days']}일 미만**"
        + warn_perm
    )
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)
    await send_log(interaction.guild, f"🚨 레이드 자동방어 {security_state_text(settings['enabled'])}\n관리자: {interaction.user.mention}", "general")


class CensorEnablePanelView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=300)

    async def _enable_censor_category(self, interaction: discord.Interaction, category_key: str):
        if not await require_admin_interaction(interaction):
            return
        info = CENSOR_CATEGORY_LABELS.get(category_key, {"label": category_key})
        set_security_setting(interaction.guild.id, "auto_filter", True)
        set_security_setting(interaction.guild.id, "security_log_enabled", True)
        set_censor_category_setting(interaction.guild.id, category_key, True)
        await safe_interaction_edit(interaction, embed=build_censor_panel_embed(interaction.guild), view=CensorEnablePanelView())
        await send_log(
            interaction.guild,
            f"🧹 검열켜기 패널\n카테고리: `{info.get('label', category_key)}`\n상태: 켜짐 ✅\n관리자: {interaction.user.mention}",
            "general"
        )

    async def _enable_spam_category(self, interaction: discord.Interaction, category_key: str):
        if not await require_admin_interaction(interaction):
            return
        info = CENSOR_CATEGORY_LABELS.get(category_key, {"label": category_key})
        set_security_setting(interaction.guild.id, "spam_protection", True)
        set_security_setting(interaction.guild.id, "security_log_enabled", True)
        set_censor_category_setting(interaction.guild.id, category_key, True)
        await safe_interaction_edit(interaction, embed=build_censor_panel_embed(interaction.guild), view=CensorEnablePanelView())
        await send_log(
            interaction.guild,
            f"⚠️ 스팸검열 패널\n카테고리: `{info.get('label', category_key)}`\n상태: 켜짐 ✅\n관리자: {interaction.user.mention}",
            "general"
        )

    async def _enable_security_feature(self, interaction: discord.Interaction, setting_key: str, label: str):
        if not await require_admin_interaction(interaction):
            return
        set_security_setting(interaction.guild.id, setting_key, True)
        set_security_setting(interaction.guild.id, "security_log_enabled", True)
        await safe_interaction_edit(interaction, embed=build_censor_panel_embed(interaction.guild), view=CensorEnablePanelView())
        await send_log(
            interaction.guild,
            f"🧹 검열켜기 패널\n카테고리: `{label}`\n상태: 켜짐 ✅\n관리자: {interaction.user.mention}",
            "general"
        )

    async def _set_all(self, interaction: discord.Interaction, enabled: bool):
        if not await require_admin_interaction(interaction):
            return
        for setting_key in [
            "auto_filter",
            "spam_protection",
            "mention_spam_detection",
            "dangerous_file_block",
            "token_leak_guard",
            "new_account_guard",
            "raid_detection",
            "permission_guard",
        ]:
            set_security_setting(interaction.guild.id, setting_key, enabled)
        set_security_setting(interaction.guild.id, "security_log_enabled", True)
        set_all_censor_category_settings(interaction.guild.id, enabled)
        await safe_interaction_edit(interaction, embed=build_censor_panel_embed(interaction.guild), view=CensorEnablePanelView())
        await send_log(
            interaction.guild,
            f"🧹 검열패널 전체 {'켜기' if enabled else '끄기'}\n관리자: {interaction.user.mention}",
            "general"
        )

