def build_security_panel_embed(guild: discord.Guild):
    settings = get_security_settings(guild.id)
    bad_count = len(get_custom_filter_words(guild.id))
    malicious_count = len(list_malicious_users(guild.id, 100))
    recent_logs = count_security_logs(guild.id, 24)
    embed = create_embed(
        "🛡️ 만능봇 업그레이드 보안패널",
        "아래 버튼으로 서버 보호 기능을 바로 켜고 끌 수 있어요. (관리자 전용)",
    )
    if bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    embed.add_field(
        name="🛡️ 핵심 보호",
        value=(
            f"악성유저감지 **{security_state_text(settings['malicious_user_detection'])}**　"
            f"자동검열 **{security_state_text(settings['auto_filter'])}**\n"
            f"테러감지 **{security_state_text(settings['raid_detection'])}**　"
            f"도배보호 **{security_state_text(settings['spam_protection'])}**"
        ),
        inline=False,
    )
    embed.add_field(
        name="🔐 추가 보호",
        value=(
            f"멘션테러감지 **{security_state_text(settings['mention_spam_detection'])}**　"
            f"새계정보호 **{security_state_text(settings['new_account_guard'])}**\n"
            f"위험파일차단 **{security_state_text(settings['dangerous_file_block'])}**　"
            f"토큰보호 **{security_state_text(settings['token_leak_guard'])}**\n"
            f"권한보호 **{security_state_text(settings['permission_guard'])}**　"
            f"보안로그저장 **{security_state_text(settings['security_log_enabled'])}**"
        ),
        inline=False,
    )
    embed.add_field(
        name="📊 현황",
        value=f"등록 악성유저 `{malicious_count}`명 · 추가 차단단어 `{bad_count}`개 · 최근 24시간 로그 `{recent_logs}`건",
        inline=False,
    )
    embed.add_field(
        name="✨ 추가된 보호 기능 설명",
        value=(
            "• 도배보호: 짧은 시간 반복 채팅 자동 경고\n"
            "• 멘션테러감지: 대량 멘션/@everyone 감지\n"
            f"• 새계정보호: 생성 {SECURITY_NEW_ACCOUNT_DAYS}일 미만 계정 입장 알림\n"
            "• 위험파일차단: exe/bat/js/ps1 등 위험 첨부파일 삭제\n"
            "• 토큰보호: 봇 토큰처럼 보이는 문자열 즉시 삭제\n"
            "• 권한보호: 관리자/역할관리 같은 위험 권한 부여 감지\n"
            "• 보안로그: 최근 차단/감지 기록 확인"
        ),
        inline=False
    )
    return embed


