async def create_friend_roles_command(interaction: discord.Interaction, 생성범위: app_commands.Choice[str] = None):
    if await reject_if_not_setup_manager(interaction):
        return
    if await reject_if_not_bot_manager(interaction):
        return

    guild = interaction.guild
    if guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    if 생성범위 is None:
        return await open_friend_role_scope_panel(interaction)

    await safe_interaction_defer(interaction, ephemeral=True)
    scope = 생성범위.value
    role_scope_labels = FRIEND_ROLE_SCOPE_LABELS
    created, deleted, skipped_delete, updated = await create_friend_roles(guild, scope=scope)
    scope_label = role_scope_labels.get(scope, "전체")

    await interaction.followup.send(
        f"✅ 역할 자동 생성을 완료했습니다.\n"
        f"생성범위: **{scope_label}**\n"
        f"기존 삭제: **{len(deleted)}개**\n"
        f"새로 생성: **{len(created)}개**\n"
        f"삭제 못한 역할: **{len(skipped_delete)}개**\n"
        f"권한 정리: **{len(updated)}개**",
        ephemeral=True
    )
    await send_log(guild, f"🎭 역할 자동 생성/확인\n범위: {scope_label}\n관리자: {interaction.user.mention}\n기존 삭제: {len(deleted)}개\n새로 생성: {len(created)}개\n삭제 못한 역할: {len(skipped_delete)}개\n권한 정리: {len(updated)}개", "general")


@app_commands.describe(생성범위="생성할 친목섭 묶음을 선택하세요.")
@app_commands.choices(생성범위=[
    app_commands.Choice(name="서버맞춤 자동", value="auto"),
    app_commands.Choice(name="전체", value="all"),
    app_commands.Choice(name="역할만 패널", value="roles"),
    app_commands.Choice(name="기본카테고리 패널", value="basic"),
    app_commands.Choice(name="게임방", value="game"),
    app_commands.Choice(name="내전방", value="scrim"),
    app_commands.Choice(name="강화방", value="enhance"),
    app_commands.Choice(name="RPG방", value="rpg"),
    app_commands.Choice(name="미니게임방", value="gambling"),
    app_commands.Choice(name="생일", value="birthday"),
    app_commands.Choice(name="서버부스트", value="boost"),
    app_commands.Choice(name="로그", value="logs"),
    app_commands.Choice(name="서버스텟", value="stats"),
    app_commands.Choice(name="티켓", value="ticket"),
    app_commands.Choice(name="봇명령어", value="bot_shop"),
    app_commands.Choice(name="뮤직", value="music"),
    app_commands.Choice(name="TTS", value="tts"),
    app_commands.Choice(name="개발로그", value="devlog"),
])
async def create_friend_server(
    interaction: discord.Interaction,
    생성범위: app_commands.Choice[str] = None,
    *,
    이름: str = None,
    카테고리이름: str = None,
    텍스트채널: str = None,
    음성채널: str = None,
    꾸미기: bool = True,
):
    if await reject_if_not_setup_manager(interaction):
        return
    if await reject_if_not_bot_manager(interaction):
        return

    guild = interaction.guild
    if guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    if 생성범위 is None:
        return await open_friend_setup_panel(interaction)

    scope = 생성범위.value
    if scope == "roles":
        return await open_friend_role_scope_panel(interaction)
    if scope == "basic":
        return await open_friend_basic_category_panel(interaction)

    await safe_interaction_defer(interaction, ephemeral=True)
    scope_labels = {
        "auto": "서버맞춤 자동",
        "all": "전체",
        "roles": "역할만",
        "basic": "기본카테고리",
        "game": "게임방",
        "scrim": "내전방",
        "enhance": "강화방",
        "gambling": "미니게임방",
        "birthday": "생일",
        "boost": "서버부스트",
        "logs": "로그",
        "stats": "서버스텟",
        "ticket": "티켓",
        "bot_shop": "봇명령어",
        "music": "뮤직",
        "tts": "TTS",
        "devlog": "개발로그",
        "rpg": "RPG방",
        "custom": "커스텀",
    }

    if scope == "auto":
        picked_scopes, result_lines = await create_friend_server_auto_profile(guild)
        embed = build_friend_scope_result_embed(
            "🌸 친목섭 서버맞춤 생성 완료",
            "서버맞춤 자동",
            [
                "선택된 범위: " + (", ".join(picked_scopes) if picked_scopes else "기본"),
                *result_lines,
            ],
            FRIEND_SERVER_COLORS.get("main", BOT_COLOR),
        )
        await interaction.followup.send(embed=embed, ephemeral=True)
        await send_log(guild, f"🌸 친목섭 서버맞춤 생성\n범위: {', '.join(picked_scopes)}\n관리자: {interaction.user.mention}", "general")
        return

    if scope != "all":
        result_lines = []
        if scope == "roles":
            created, deleted, skipped_delete, updated = await create_friend_roles(guild)
            result_lines.append(f"🎭 역할: 새로 생성 `{len(created)}`개 / 정리 `{len(updated)}`개 / 삭제 못함 `{len(skipped_delete)}`개")
        elif scope == "game":
            game_layout = await create_game_category_channels(guild)
            result_lines.append(
                f"🎮 게임방: {game_layout.get('game_category').mention if game_layout.get('game_category') else '미설정'} / "
                f"게임채팅 {game_layout.get('game_chat_channel').mention if game_layout.get('game_chat_channel') else '미설정'} / "
                f"게임음성 `{len(game_layout.get('game_voice_channels') or [])}`개 / "
                f"티어표·티어통방 자동생성 `꺼짐` / "
                f"패널 {'새로 전송됨' if game_layout.get('game_role_panel_sent') else '이미 있음'}"
            )
        elif scope == "scrim":
            scrim_layout = await create_scrim_category_channels(guild)
            result_lines.append(
                f"⚔️ 내전방: {scrim_layout.get('scrim_category').mention if scrim_layout.get('scrim_category') else '미설정'} / "
                f"내전채널 {scrim_layout.get('scrim_text_channel').mention if scrim_layout.get('scrim_text_channel') else '미설정'} / "
                "대기실·팀 음성 생성/복구 완료"
            )
        elif scope == "enhance":
            enhance_layout = await create_enhance_category_channels(guild, send_guide=True)
            result_lines.append(
                f"⚒️ 강화방: {enhance_layout.get('enhance_category').mention if enhance_layout.get('enhance_category') else '미설정'} / "
                f"강화채널 {enhance_layout.get('enhance_channel').mention if enhance_layout.get('enhance_channel') else '미설정'} / "
                f"안내 {'새로 전송됨' if enhance_layout.get('enhance_guide_sent') else '이미 있음'}"
            )
        elif scope == "gambling":
            gambling_layout = await create_gambling_category_channels(guild, send_guide=True)
            result_lines.append(
                f"🎮 미니게임방: {gambling_layout.get('gambling_category').mention if gambling_layout.get('gambling_category') else '미설정'} / "
                f"규칙 {gambling_layout.get('gambling_rules_channel').mention if gambling_layout.get('gambling_rules_channel') else '미설정'} / "
                f"채팅 {gambling_layout.get('gambling_chat_channel').mention if gambling_layout.get('gambling_chat_channel') else '미설정'} / "
                f"명령어방 {gambling_layout.get('dice_channel').mention if gambling_layout.get('dice_channel') else '미설정'}"
            )
        elif scope == "birthday":
            birthday_category, birthday_register_channel, birthday_record_channel = await create_birthday_channels(guild)
            result_lines.append(
                f"🎂 생일방: {birthday_category.mention if birthday_category else '미설정'} / "
                f"생일등록 {birthday_register_channel.mention if birthday_register_channel else '미설정'} / "
                f"생일기록 {birthday_record_channel.mention if birthday_record_channel else '미설정'} / 패널·기록 새로고침 완료"
            )
        elif scope == "boost":
            boost_category, used_rule_category = await get_rule_or_default_category_for_panels(guild)
            boost_channel = await get_or_create_text_channel(guild, "｜・(🚀)：서버부스트", boost_category)
            if used_rule_category:
                await apply_rule_category_permissions(guild, boost_category)
                save_guild_channel_ids(guild, boost_channel_id=boost_channel, welcome_category_id=boost_category, rule_category_id=boost_category)
            else:
                await apply_default_server_permissions(guild, boost_category)
                save_guild_channel_ids(guild, boost_channel_id=boost_channel, welcome_category_id=boost_category)
            result_lines.append(f"🚀 서버부스트: {boost_channel.mention if boost_channel else '미설정'} 채널 생성/복구 완료")
        elif scope == "logs":
            _, created_log_channels = await ensure_log_category_channels(guild)
            result_lines.append(f"📁 로그 카테고리: 새 로그 채널 `{len(created_log_channels)}`개")
        elif scope == "stats":
            _, created_stats_channels = await ensure_server_stats_channels(guild)
            result_lines.append(f"📊 서버스텟: 새 스텟 채널 `{created_stats_channels}`개")
        elif scope == "ticket":
            ticket_category, ticket_panel_channel, ticket_log_channel, panel_sent = await create_ticket_category_channels(guild, send_panel=True)
            await apply_member_category_permissions(guild, ticket_category)
            result_lines.append(f"🎫 티켓: {ticket_panel_channel.mention if ticket_panel_channel else '미설정'} / 패널 {'새로 전송됨' if panel_sent else '이미 있음'}")
        elif scope == "bot_shop":
            bot_command_layout = await create_bot_command_category_channels(guild, send_guides=True)
            result_lines.append(
                f"🤖 봇명령어: {bot_command_layout.get('bot_command_channel').mention if bot_command_layout.get('bot_command_channel') else '미설정'} / "
                f"🛒 상점: {bot_command_layout.get('shop_channel').mention if bot_command_layout.get('shop_channel') else '미설정'} / "
                f"💰 포인트: {bot_command_layout.get('point_channel').mention if bot_command_layout.get('point_channel') else '미설정'}"
            )
        elif scope == "music":
            music_layout = await create_music_category_channels(guild, send_panel=True)
            result_lines.append(f"🎵 뮤직: {music_layout.get('music_command_channel').mention if music_layout.get('music_command_channel') else '미설정'} / 패널 {'새로 전송됨' if music_layout.get('music_panel_sent') else '이미 있음'}")
        elif scope == "tts":
            _, tts_text_channel, tts_voice_channel, tts_guide_sent = await create_tts_category_channels(guild)
            result_lines.append(f"🔊 TTS: {tts_text_channel.mention if tts_text_channel else '미설정'} / 음성 {tts_voice_channel.mention if tts_voice_channel else '미설정'} / 안내 {'새로 전송됨' if tts_guide_sent else '이미 있음'}")
        elif scope == "devlog":
            if is_official_support_guild(guild):
                devlog_result = await ensure_development_log_channels(guild)
                await send_development_log_intro_embeds(guild)
                result_lines.append(f"📈 개발로그: 공식 지원 서버 확인 / 새로 생성 `{len(devlog_result.get('created', []))}`개 / 안내패널 준비")
            else:
                result_lines.append("📈 개발로그: 공식 지원 서버에서만 생성됩니다. `OFFICIAL_SUPPORT_GUILD_ID`를 공식 지원 서버 ID로 설정해주세요.")
        elif scope == "rpg":
            rpg_deleted_count = await rpg_reset_rpg_rooms(guild)  # 기존 RPG방 자동 삭제 후 새로 생성
            rpg_layout = await create_rpg_category_channels(guild, send_guide=True)
            result_lines.append(
                f"⚔️ RPG방: 기존 채널 `{rpg_deleted_count}`개 삭제 후 새로 생성 / "
                f"{_panel_channel_text(rpg_layout.get('category'))} / "
                f"사냥 {_panel_channel_text(rpg_layout.get('hunt_channel'))} · "
                f"보스 {_panel_channel_text(rpg_layout.get('boss_channel'))} · "
                f"던전 {_panel_channel_text(rpg_layout.get('dungeon_channel'))} · "
                f"레이드 {_panel_channel_text(rpg_layout.get('raid_channel'))} · "
                f"대결장 {_panel_channel_text(rpg_layout.get('pvp_channel'))} · "
                f"뽑기 {_panel_channel_text(rpg_layout.get('gacha_channel'))} · "
                f"강화·세공 {_panel_channel_text(rpg_layout.get('forge_channel'))} · "
                f"상점 {_panel_channel_text(rpg_layout.get('shop_channel'))} · "
                f"랭킹 {_panel_channel_text(rpg_layout.get('ranking_channel'))} · "
                f"패널 {_panel_channel_text(rpg_layout.get('panel_channel'))} · "
                f"안내 {_panel_channel_text(rpg_layout.get('guide_channel'))}\n"
                f"↳ 기능별 전용 채널이 `/rpg 채널설정`에 자동 연결됐고, 패널 채널에 RPG 통합 패널이 게시됐어요."
            )
        elif scope == "custom":
            if 카테고리이름:
                custom_preset_name = (이름 or 카테고리이름).strip()
                custom_category_name = 카테고리이름.strip()
                custom_text_names = mnb_parse_channel_name_list(텍스트채널)
                custom_voice_names = mnb_parse_channel_name_list(음성채널)
                if not custom_text_names and not custom_voice_names:
                    custom_text_names = ["일반"]
                mnb_save_custom_friend_layout(guild.id, custom_preset_name, custom_category_name, custom_text_names, custom_voice_names)
            elif 이름:
                saved_layout = mnb_get_custom_friend_layout(guild.id, 이름.strip())
                if not saved_layout:
                    await interaction.followup.send(
                        f"❌ `{이름}`이라는 커스텀 구성을 이 서버에서 찾을 수 없어요. `/나만의카테고리 목록`으로 확인해주세요.",
                        ephemeral=True,
                    )
                    return
                custom_preset_name = 이름.strip()
                custom_category_name = saved_layout["category_name"]
                custom_text_names = saved_layout["text_channels"]
                custom_voice_names = saved_layout["voice_channels"]
            else:
                saved_names = mnb_list_custom_friend_layouts(guild.id)
                if saved_names:
                    names_text = ", ".join(f"`{n}`" for n in saved_names)
                    await interaction.followup.send(
                        f"이 서버에 저장된 커스텀 구성: {names_text}\n"
                        f"`이름`을 입력하면 자동완성으로 골라서 바로 만들 수 있어요. (예: `/서버 친목섭 생성범위:커스텀 이름:...`)",
                        ephemeral=True,
                    )
                else:
                    await interaction.followup.send(
                        "❌ 이 서버에는 아직 저장된 커스텀 구성이 없어요. `이름`과 `카테고리이름`을 함께 입력해서 처음 만들어주세요.\n"
                        "예: `/서버 친목섭 생성범위:커스텀 이름:스터디 카테고리이름:모임 텍스트채널:공지,잡담 음성채널:음성1,음성2`\n"
                        "버튼으로 만들고 싶으면 `/친목섭`을 옵션 없이 실행하고 `🎨 커스텀` 버튼을 눌러주세요.",
                        ephemeral=True,
                    )
                return

            custom_category, custom_created_text, custom_created_voice = await create_custom_friend_layout(
                guild, custom_category_name, custom_text_names, custom_voice_names, decorate=꾸미기
            )
            result_lines.append(
                f"🏷️ 이름: `{custom_preset_name}` / "
                f"🎨 커스텀: {custom_category.mention if custom_category else '미설정'} / "
                f"텍스트 `{len(custom_created_text)}`개 / 음성 `{len(custom_created_voice)}`개 / "
                f"꾸미기 {'✅ 켜짐' if 꾸미기 else '⬜ 꺼짐'}"
            )
        else:
            layout = await create_friend_server_layout(guild)
            result_lines.append(
                f"📦 기본카테고리: 필독 {layout.get('rule_category').mention if layout.get('rule_category') else '미설정'} / "
                f"인사-퇴장 {layout.get('welcome_channel').mention if layout.get('welcome_channel') else '미설정'} / "
                f"부스트알림 {layout.get('boost_channel').mention if layout.get('boost_channel') else '미설정'} / "
                f"인증 {layout.get('verify_channel').mention if layout.get('verify_channel') else '미설정'}"
            )

