c.execute("""
CREATE TABLE IF NOT EXISTS enhance_reset_state (
    guild_id INTEGER PRIMARY KEY,
    period_key INTEGER DEFAULT 0,
    reset_at TEXT
)
""")
conn.commit()


def get_enhance_period_key():
    today = datetime.date.today()
    days = (today - ENHANCE_RESET_ANCHOR).days
    return max(0, days // ENHANCE_RESET_DAYS)


def ensure_enhance_biweekly_reset(guild_id: int):
    """강화 기록을 2주 단위로 자동 초기화합니다. 첫 실행 시에는 현재 주기만 저장합니다."""
    if not guild_id:
        return False
    current_period = get_enhance_period_key()
    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    c.execute("SELECT period_key FROM enhance_reset_state WHERE guild_id=?", (guild_id,))
    row = c.fetchone()
    if row is None:
        c.execute(
            "INSERT OR IGNORE INTO enhance_reset_state(guild_id, period_key, reset_at) VALUES (?, ?, ?)",
            (guild_id, current_period, now)
        )
        conn.commit()
        return False
    saved_period = int(row[0] or 0)
    if saved_period == current_period:
        return False
    c.execute("DELETE FROM enhance_items WHERE guild_id=?", (guild_id,))
    c.execute(
        "UPDATE enhance_reset_state SET period_key=?, reset_at=? WHERE guild_id=?",
        (current_period, now, guild_id)
    )
    conn.commit()
    return True


def get_next_enhance_reset_text():
    current_period = get_enhance_period_key()
    next_date = ENHANCE_RESET_ANCHOR + datetime.timedelta(days=(current_period + 1) * ENHANCE_RESET_DAYS)
    return next_date.strftime("%Y-%m-%d")


def get_enhance_milestone_title(level: int):
    return ENHANCE_MILESTONE_TITLES.get(int(level or 0), "")


@tasks.loop(hours=6)
async def enhance_biweekly_reset_checker():
    for guild in list(bot.guilds):
        try:
            reset_done = ensure_enhance_biweekly_reset(guild.id)
            if reset_done:
                await send_log(
                    guild,
                    f"🔄 강화 2주 시즌 초기화 완료\n다음 초기화 예정일: **{get_next_enhance_reset_text()}**",
                    "general"
                )
        except Exception:
            pass

def get_enhance_rates(level: int, success_bonus: int = 0, destroy_reduction: int = 0):
    """강화 단계별 확률을 계산합니다.

    v216 밸런스 상향:
    - 최대 +150강 기준이라 초중반 성공률을 크게 올렸습니다.
    - 기존에는 +10강 근처가 강화확률업권(+15%)을 써도 45%라 너무 빡셌습니다.
    - 이제 +6~+10 구간은 기본 70%, 확률업권 사용 시 85%로 적용됩니다.
    - 고강 구간도 10% 고정이 아니라 단계별로 천천히 낮아집니다.
    """
    level = max(0, int(level or 0))

    # 현재 강화 단계 기준 확률입니다. 예: level 10이면 +10 -> +11 시도 확률.
    # 형식: (최대 현재 단계, 성공, 실패, 하락, 파괴)
    rate_tiers = [
        (2, 95, 5, 0, 0),
        (5, 88, 10, 2, 0),
        (10, 70, 20, 10, 0),
        (20, 62, 22, 14, 2),
        (30, 55, 25, 17, 3),
        (40, 48, 27, 20, 5),
        (50, 42, 30, 22, 6),
        (60, 36, 32, 24, 8),
        (70, 31, 34, 25, 10),
        (80, 27, 35, 26, 12),
        (90, 23, 36, 27, 14),
        (100, 20, 38, 27, 15),
        (110, 17, 39, 28, 16),
        (120, 14, 40, 29, 17),
        (130, 12, 41, 29, 18),
        (140, 10, 42, 29, 19),
        (ENHANCE_MAX_LEVEL, 8, 43, 29, 20),
    ]

    base_success, base_fail, base_down, base_destroy = rate_tiers[-1][1:]
    for max_level, tier_success, tier_fail, tier_down, tier_destroy in rate_tiers:
        if level <= max_level:
            base_success, base_fail, base_down, base_destroy = tier_success, tier_fail, tier_down, tier_destroy
            break

    success = min(95, base_success + max(0, int(success_bonus or 0)))
    destroy = max(0, base_destroy - max(0, int(destroy_reduction or 0)))

    # 성공/파괴 보정 후 남은 확률을 실패와 하락에 분배합니다.
    # 이렇게 해야 역할 부스트/확률업권을 써도 전체 합계가 항상 100%로 맞습니다.
    remain = max(0, 100 - success - destroy)
    down_ratio = base_down / max(1, base_fail + base_down)
    down = int(round(remain * down_ratio))
    fail = max(0, remain - down)

    return {"success": success, "fail": fail, "down": down, "destroy": destroy}


def get_enhance_item(guild_id: int, user_id: int, item_name: str):
    c.execute(
        """
        SELECT level, success_count, fail_count, down_count, destroy_count, total_attempts, best_level
        FROM enhance_items
        WHERE guild_id=? AND user_id=? AND item_name=?
        """,
        (guild_id, user_id, item_name)
    )
    row = c.fetchone()
    if row is None:
        return 0, 0, 0, 0, 0, 0, 0
    return row


def save_enhance_item(guild_id: int, user_id: int, item_name: str, level: int, success_count: int, fail_count: int, down_count: int, destroy_count: int, total_attempts: int, best_level: int):
    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    c.execute(
        """
        INSERT OR REPLACE INTO enhance_items(
            guild_id, user_id, item_name, level, success_count, fail_count, down_count,
            destroy_count, total_attempts, best_level, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (guild_id, user_id, item_name, level, success_count, fail_count, down_count, destroy_count, total_attempts, best_level, now)
    )
    conn.commit()


def get_enhance_boost_for_member(member: discord.Member):
    if member is None or member.guild is None:
        return 0, 0

    role_ids = [role.id for role in member.roles]
    if not role_ids:
        return 0, 0

    placeholders = ",".join("?" for _ in role_ids)
    c.execute(
        f"""
        SELECT success_bonus, destroy_reduction
        FROM enhance_boosts
        WHERE guild_id=? AND role_id IN ({placeholders})
        """,
        [member.guild.id, *role_ids]
    )
    rows = c.fetchall()
    if not rows:
        return 0, 0
    return max(row[0] for row in rows), max(row[1] for row in rows)


