# =========================
# 뮤직 채팅 자동 재생
# =========================
# 뮤직패널 버튼을 누르지 않아도, 연결된 채팅채널에 제목을 치면 바로 재생됩니다.
# 검색 기준은 `사클: 제목`, `유튜브: 제목`처럼 따로 선택할 수 있습니다.

MUSIC_CHAT_SKIP_WORDS = {
    "", "안녕", "하이", "ㅎㅇ", "ㅋㅋ", "ㅋㅋㅋ", "ㅠㅠ", "ㄱㄱ", "ㄴㄴ",
    "재생", "스킵", "대기열", "볼륨", "종료", "일시정지", "다시재생",
}


def normalize_music_chat_name(name: str):
    return re.sub(r"[^0-9a-zA-Z가-힣]", "", (name or "").lower())


def is_youtube_url(text: str) -> bool:
    return bool(re.search(r"https?://(?:www\.|m\.)?(?:youtube\.com|youtu\.be)/|https?://music\.youtube\.com/", text or "", re.I))


def is_soundcloud_url(text: str) -> bool:
    return bool(re.search(r"https?://(?:www\.)?soundcloud\.com/", text or "", re.I))

def parse_music_chat_request(content: str):
    """채팅으로 입력한 재생 요청을 분석합니다.

    지원 예시:
    - 사클: 오늘 하루도 고생한 당신에게 피아노 모음
    - 유튜브: 오늘 하루도 고생한 당신에게 피아노 모음
    - 1번 사클: 제목
    - 2 유튜브: 제목
    - 제목만 입력하면 기본값은 SoundCloud 제목 검색

    v218: 원하는 채널 사용 모드에서는 일반 대화가 노래로 오인되지 않도록
    `사클:` / `유튜브:` / `1번 사클:` 같은 명확한 접두어가 있을 때만
    모든 채널에서 바로 재생합니다.
    """
    raw = (content or "").strip()
    if not raw or raw.startswith(("!", ".", "/")):
        return None
    if len(raw) > 300:
        raw = raw[:300].strip()

    lowered = raw.lower().strip()
    if normalize_music_chat_name(lowered) in {normalize_music_chat_name(w) for w in MUSIC_CHAT_SKIP_WORDS}:
        return None

    explicit_prefix = False
    requested_slot = None
    slot_match = re.match(r"^\s*(?:커스텀\s*)?([123])\s*(?:번)?\s*[:：\-]?\s+(.+)$", raw)
    if slot_match:
        requested_slot = int(slot_match.group(1))
        raw = slot_match.group(2).strip()
        lowered = raw.lower().strip()
        explicit_prefix = True

    # parse_music_source_prefix는 `사클:` / `유튜브:` 접두어를 처리합니다.
    source, query = parse_music_source_prefix(raw)
    if source:
        explicit_prefix = True

    if not source:
        source_words = [
            ("soundcloud", ["사클 ", "사클검색 ", "사운드클라우드 ", "soundcloud ", "sc "]),
            ("youtube", ["유튜브 ", "유튜브검색 ", "youtube ", "yt "]),
        ]
        for source_name, prefixes in source_words:
            for prefix in prefixes:
                if lowered.startswith(prefix):
                    source = source_name
                    query = raw[len(prefix):].strip()
                    explicit_prefix = True
                    break
            if source:
                break

    if not source:
        if is_youtube_url(raw):
            source = "youtube"
            query = raw
            explicit_prefix = True
        elif is_soundcloud_url(raw):
            source = "soundcloud"
            query = raw
            explicit_prefix = True
        else:
            source = "soundcloud"
            query = raw

    query = (query or "").strip()
    if not query or normalize_music_chat_name(query) in {normalize_music_chat_name(w) for w in MUSIC_CHAT_SKIP_WORDS}:
        return None

    return {"slot": requested_slot, "source": source, "query": query, "explicit": explicit_prefix}


def get_configured_music_chat_channel_id(guild: discord.Guild) -> int:
    """관리자가 직접 지정한 음악 채팅/패널 채널 ID를 가져옵니다."""
    if guild is None:
        return 0
    try:
        return int(get_saved_channel_id(guild.id, "music_command_channel_id") or 0)
    except Exception:
        return 0


def is_configured_music_chat_channel(guild: discord.Guild, channel) -> bool:
    """유튜브/사클 링크·제목 채팅 자동재생이 허용된 채널인지 확인합니다."""
    if guild is None or channel is None:
        return False
    configured_id = get_configured_music_chat_channel_id(guild)
    if not configured_id:
        return False
    return int(getattr(channel, "id", 0) or 0) == configured_id


def is_main_music_chat_channel(guild: discord.Guild, channel):
    if guild is None or channel is None:
        return False
    channel_id = int(getattr(channel, "id", 0) or 0)

    configured_id = get_configured_music_chat_channel_id(guild)
    if configured_id:
        # 직접 지정한 음악 채널이 있으면 그 채널에서만 채팅 링크/제목 재생을 허용합니다.
        # 현재재생/재생목록/다른 뮤직 이름 채널에서는 봇이 반응하지 않습니다.
        return channel_id == configured_id

    for column in ("music_command_channel_id", "music_now_playing_channel_id", "music_queue_channel_id"):
        try:
            saved_id = int(get_saved_channel_id(guild.id, column) or 0)
        except Exception:
            saved_id = 0
        if saved_id and saved_id == channel_id:
            return True

    name_norm = normalize_music_chat_name(getattr(channel, "name", ""))
    music_keywords = ["뮤직", "음악", "노래", "재생", "music", "song", "nowplaying", "현재재생"]
    return any(keyword in name_norm for keyword in music_keywords)


def is_channel_for_custom_music_chat(guild: discord.Guild, slot: int, channel, voice_channel):
    if guild is None or channel is None or voice_channel is None:
        return False
    channel_id = int(getattr(channel, "id", 0) or 0)
    voice_id = int(getattr(voice_channel, "id", 0) or 0)

    # 음성채널 자체의 채팅에 입력한 경우
    if channel_id and voice_id and channel_id == voice_id:
        return True

    resolved = resolve_custom_music_text_channel(guild, voice_channel, None)
    if resolved and int(getattr(resolved, "id", 0) or 0) == channel_id:
        return True

    # 같은 카테고리의 통방/뮤직/채팅 채널도 허용합니다.
    if getattr(channel, "category_id", None) == getattr(voice_channel, "category_id", None):
        name_norm = normalize_music_chat_name(getattr(channel, "name", ""))
        if any(keyword in name_norm for keyword in ["통방", "채팅", "뮤직", "음악", "노래", "music", "chat"]):
            return True
    return False


def find_custom_music_slot_for_chat(message: discord.Message, requested_slot: int | None):
    if message.guild is None:
        return None, None
    author_voice = getattr(getattr(message.author, "voice", None), "channel", None)
    if author_voice is None:
        return None, "❌ 먼저 사용할 통방/음성채널에 들어가주세요."

    candidate_slots = [requested_slot] if requested_slot else [1, 2, 3]
    matched = []
    for slot in candidate_slots:
        if not slot:
            continue
        vc = get_custom_music_voice_client(int(slot), message.guild.id)
        if not vc or not getattr(vc, "channel", None):
            continue
        if int(vc.channel.id) != int(author_voice.id):
            continue
        # 원하는 채널 사용 모드: 같은 통방에 들어가 있기만 하면
        # `1번 사클: 제목` 같은 명령을 어느 텍스트 채널에서나 사용할 수 있습니다.
        if MNB_FREE_CHANNEL_MODE and MNB_MUSIC_EXPLICIT_ANY_CHANNEL:
            matched.append(int(slot))
            continue
        if is_channel_for_custom_music_chat(message.guild, int(slot), message.channel, vc.channel):
            matched.append(int(slot))

    if requested_slot and not matched:
        return None, f"❌ {requested_slot}번 커스텀 봇이 지금 네가 들어간 통방에 없거나, 이 채팅채널과 연결되어 있지 않아요."
    if len(matched) > 1:
        return None, "❌ 같은 통방에 커스텀 봇이 여러 개 있어요. `1번 사클: 제목`처럼 번호를 붙여주세요."
    if matched:
        return matched[0], None
    return None, None


async def ensure_main_music_voice_from_message(message: discord.Message):
    if message.guild is None:
        return None, "❌ 서버에서만 사용할 수 있어요."
    if not getattr(message.author, "voice", None) or not message.author.voice.channel:
        return None, "❌ 먼저 음성 채널에 들어가주세요."

    voice_channel = message.author.voice.channel
    voice_client = message.guild.voice_client
    try:
        if voice_client is None:
            return await voice_channel.connect(), None
        if voice_client.channel != voice_channel:
            await voice_client.move_to(voice_channel)
        return voice_client, None
    except (discord.Forbidden, discord.HTTPException) as e:
        return None, f"❌ 음성 채널 입장 실패: `{e}`"


async def play_main_music_from_chat(message: discord.Message, query: str, source: str):
    voice_client, error = await ensure_main_music_voice_from_message(message)
    if error:
        await message.channel.send(error, delete_after=8)
        return True

    try:
        track = await extract_music_info(query, source)
    except Exception as e:
        await message.channel.send(f"❌ 노래 정보를 가져오지 못했어요.\n`{e}`", delete_after=12)
        return True

    queue = get_music_queue(message.guild.id)
    queue.append(track)

    if not voice_client.is_playing() and not voice_client.is_paused():
        await play_music_next(message.guild)
        msg = (
            f"🎶 채팅으로 바로 재생을 시작했어요!\n"
            f"{track.get('service_emoji', '🎧')} **{track['title']}**\n"
            f"서비스: `{track.get('service', '검색')}` ㅣ 길이: `{format_duration(track.get('duration'))}`"
        )
    else:
        await send_music_now_playing_box(message.guild, track, queued=True)
        msg = (
            f"✅ 채팅으로 대기열에 추가했어요!\n"
            f"{track.get('service_emoji', '🎧')} **{track['title']}**\n"
            f"서비스: `{track.get('service', '검색')}` ㅣ 길이: `{format_duration(track.get('duration'))}`"
        )
    await message.channel.send(msg[:1900])
    return True


async def play_custom_music_from_chat(message: discord.Message, slot: int, query: str, source: str):
    voice_client = get_custom_music_voice_client(slot, message.guild.id)
    if voice_client is None:
        await message.channel.send(f"❌ {slot}번 커스텀 봇이 아직 통방에 없어요. `/커스텀`에서 {slot}번 통방 입장을 먼저 눌러주세요.", delete_after=8)
        return True

    try:
        track = await extract_music_info(query, source)
    except Exception as e:
        await message.channel.send(f"❌ {slot}번 커스텀 봇 노래 정보를 가져오지 못했어요.\n`{e}`", delete_after=12)
        return True

    queue = get_custom_music_queue(slot, message.guild.id)
    queue.append(track)

    if not voice_client.is_playing() and not voice_client.is_paused():
        await play_custom_music_next(slot, message.guild.id)
        msg = (
            f"🎶 채팅으로 **{slot}번 커스텀 봇** 재생을 시작했어요!\n"
            f"{track.get('service_emoji', '🎧')} **{track['title']}**\n"
            f"서비스: `{track.get('service', '검색')}` ㅣ 길이: `{format_duration(track.get('duration'))}`"
        )
    else:
        await send_custom_music_now_playing_box(slot, message.guild.id, track, queued=True)
        msg = (
            f"✅ 채팅으로 **{slot}번 커스텀 봇** 대기열에 추가했어요!\n"
            f"{track.get('service_emoji', '🎧')} **{track['title']}**\n"
            f"서비스: `{track.get('service', '검색')}` ㅣ 길이: `{format_duration(track.get('duration'))}`"
        )
    await message.channel.send(msg[:1900])
    return True


async def maybe_play_music_from_chat_message(message: discord.Message):
    if message.guild is None or message.author.bot:
        return False
    parsed = parse_music_chat_request(message.content)
    if not parsed:
        return False

    requested_slot = parsed["slot"]
    source = parsed["source"]
    query = parsed["query"]
    explicit_prefix = bool(parsed.get("explicit"))

    configured_music_channel_id = get_configured_music_chat_channel_id(message.guild)
    if MNB_MUSIC_CHAT_ONLY_CONFIGURED_CHANNEL and configured_music_channel_id:
        # 유튜브/사클 링크나 `유튜브: 제목` 같은 명시 요청도
        # 관리자가 지정한 음악 채널 밖에서는 완전히 조용히 무시합니다.
        if int(getattr(message.channel, "id", 0) or 0) != int(configured_music_channel_id):
            return False

    # 1순위: 커스텀 봇 패널/통방 채팅채널
    slot, slot_error = find_custom_music_slot_for_chat(message, requested_slot)
    if slot:
        return await play_custom_music_from_chat(message, slot, query, source)
    if requested_slot and slot_error:
        await message.channel.send(slot_error, delete_after=8)
        return True

    # 2순위: 메인 뮤직 채널
    # `사클: 제목`, `유튜브: 제목`처럼 명확한 접두어가 있으면
    # 뮤직 전용 채널을 만들지 않아도 현재 채널에서 바로 사용할 수 있습니다.
    if is_main_music_chat_channel(message.guild, message.channel) or (
        not configured_music_channel_id
        and MNB_FREE_CHANNEL_MODE
        and MNB_MUSIC_EXPLICIT_ANY_CHANNEL
        and explicit_prefix
    ):
        return await play_main_music_from_chat(message, query, source)

    return False


def normalize_spam_text(content: str) -> str:
    return re.sub(r"\s+", " ", (content or "").lower()).strip()


def count_emoji_like(content: str) -> int:
    if not content:
        return 0
    custom_count = len(CUSTOM_EMOJI_REGEX.findall(content))
    unicode_count = 0
    for ch in content:
        code = ord(ch)
        if (
            0x1F300 <= code <= 0x1FAFF
            or 0x2600 <= code <= 0x27BF
            or 0xFE00 <= code <= 0xFE0F
        ):
            unicode_count += 1
    return custom_count + unicode_count


def is_caps_spam(content: str) -> bool:
    letters = [ch for ch in (content or "") if ch.isalpha() and ch.isascii()]
    if len(letters) < CENSOR_CAPS_MIN_LETTERS:
        return False
    upper_count = sum(1 for ch in letters if ch.isupper())
    return (upper_count / max(len(letters), 1)) >= CENSOR_CAPS_RATIO


async def handle_spam_censor_violation(message: discord.Message, reason: str, log_action: str = "스팸검열"):
    try:
        await message.delete()
    except discord.HTTPException:
        pass

    warning_count = await add_auto_warning(message.author, reason)
    add_security_log(message.guild.id, message.author.id, log_action, reason, message.channel.id)
    try:
        await message.channel.send(
            f"⚠️ {message.author.mention}님 스팸/도배 검열에 의해 메시지가 삭제되었습니다.\n사유: **{reason}**\n누적 경고: {warning_count}회",
            delete_after=8
        )
    except discord.HTTPException:
        pass
    await send_log(
        message.guild,
        f"⚠️ {log_action}\n대상: {message.author.mention}\n채널: {message.channel.mention}\n사유: {reason}\n누적 경고: {warning_count}회",
        "warning"
    )
    # 서버에 자동 제재 규칙이 있으면 우선 적용합니다.
    escalation_applied = ""
    try:
        escalation_applied = await apply_warning_escalation(message.author, warning_count)
    except Exception:
        escalation_applied = ""

    if escalation_applied:
        try:
            await message.channel.send(escalation_applied, delete_after=10)
        except discord.HTTPException:
            pass
    elif warning_count >= 5:
        # 규칙이 없을 때만 기존 기본 동작(경고 5회 자동 밴)을 유지합니다.
        try:
            await message.author.ban(reason="경고 5회 누적 자동 차단")
            log_moderation_action(message.guild.id, message.author.id, 0, "ban", "경고 5회 누적 자동 차단")
            await send_log(message.guild, f"⛔ 자동 밴\n대상: {message.author}\n사유: 경고 5회 누적", "punishment")
        except (discord.Forbidden, discord.HTTPException):
            await send_log(message.guild, f"❌ 자동 밴 실패\n대상: {message.author}\n사유: 권한 부족 또는 API 오류", "punishment")
    return True


# =========================
# 메시지 처리: 초대링크 / 금지어 / 도배 / 레벨
# =========================

async def _mnb_legacy_on_message(message: discord.Message):
    if message.author.bot:
        # 공식 사이트/대시보드가 봇 계정으로 임베드만 보낸 경우
        # 인증/티켓/주요 패널 버튼을 자동으로 붙입니다.
        await maybe_attach_auto_buttons_to_bot_embed(message)
        return

    if message.guild is None:
        await mnb_v212_process_commands_once(message)
        return

    # 뮤직패널 채팅채널에서는 버튼을 누르지 않아도 채팅 입력만으로 재생합니다.
    # 예: 사클: 제목 / 유튜브: 제목 / 1번 사클: 제목
    # 음악 요청은 TTS보다 먼저 처리해서 `사클: 제목` 같은 문장이 읽히지 않게 합니다.
    if await maybe_play_music_from_chat_message(message):
        return

    # TTS 음성채널 채팅 모드:
    # /입장으로 TTS 봇을 부른 뒤, 그 음성 채널에 붙어 있는 채팅만 읽습니다.
    # 서버 전체 채팅방/일반 채팅방의 메시지는 읽지 않습니다.
    if should_auto_tts_message(message) and not should_skip_tts_by_cooldown(message):
        ok, tts_message = await speak_tts_in_voice(message.author, message.content, message.channel)
        if not ok:
            # 재생 중인 상태는 채팅마다 오류가 쌓이지 않게 조용히 무시합니다.
            if "현재 다른 음성이 재생 중" not in tts_message:
                try:
                    await message.channel.send(tts_message, delete_after=6)
                except discord.HTTPException:
                    pass
        else:
            await send_log(
                message.guild,
                f"🔊 TTS 음성채팅 재생\n유저: {message.author.mention}\n채팅위치: {message.channel.mention}\n음성채널: {message.author.voice.channel.mention if getattr(message.author, 'voice', None) and message.author.voice.channel else '자동 선택'}",
                "voice"
            )

    user_id = message.author.id
    now = datetime.datetime.now().timestamp()
    content_lower = message.content.lower()

    security_settings = get_security_settings(message.guild.id)
    censor_settings = get_censor_category_settings(message.guild.id)
    if security_settings.get("token_leak_guard") and not message.author.guild_permissions.manage_messages and looks_like_discord_token(message.content):
        try:
            await message.delete()
        except discord.HTTPException:
            pass
        warning_count = await add_auto_warning(message.author, "토큰 의심 문자열 게시")
        add_security_log(message.guild.id, message.author.id, "토큰보호", "토큰 의심 문자열 자동 삭제", message.channel.id)
        await message.channel.send(
            f"🔐 {message.author.mention}님 토큰처럼 보이는 문자열이 감지되어 메시지를 삭제했습니다.\n누적 경고: {warning_count}회",
            delete_after=8
        )
        await send_log(
            message.guild,
            f"🔐 토큰보호 감지\n대상: {message.author.mention}\n채널: {message.channel.mention}\n내용은 보안상 로그에 저장하지 않았습니다.\n누적 경고: {warning_count}회",
            "warning"
        )
        return

    if security_settings.get("dangerous_file_block") and not message.author.guild_permissions.manage_messages:
        dangerous_filename = find_dangerous_attachment_name(message)
        if dangerous_filename:
            try:
                await message.delete()
            except discord.HTTPException:
                pass
            warning_count = await add_auto_warning(message.author, "위험 첨부파일 게시")
            add_security_log(message.guild.id, message.author.id, "위험파일차단", dangerous_filename[:200], message.channel.id)
            await message.channel.send(
                f"📎 {message.author.mention}님 위험할 수 있는 첨부파일이 감지되어 메시지를 삭제했습니다.\n파일: `{dangerous_filename[:80]}`\n누적 경고: {warning_count}회",
                delete_after=8
            )
            await send_log(
                message.guild,
                f"📎 위험파일차단\n대상: {message.author.mention}\n채널: {message.channel.mention}\n파일: `{dangerous_filename[:200]}`\n누적 경고: {warning_count}회",
                "warning"
            )
            return

    if security_settings.get("mention_spam_detection") and not message.author.guild_permissions.manage_messages:
        mention_count = len(message.mentions)
        role_mention_count = len(message.role_mentions)
        total_mentions = mention_count + role_mention_count
        mention_reason = None

        if message.mention_everyone:
            mention_reason = "@everyone/@here 멘션 사용"
        elif total_mentions >= SECURITY_MENTION_LIMIT:
            mention_reason = f"대량 멘션 {total_mentions}개"
        elif role_mention_count >= SECURITY_ROLE_MENTION_LIMIT:
            mention_reason = f"역할 멘션 {role_mention_count}개"

        if mention_reason:
            try:
                await message.delete()
            except discord.HTTPException:
                pass
            warning_count = await add_auto_warning(message.author, mention_reason)
            add_security_log(message.guild.id, message.author.id, "멘션테러감지", mention_reason, message.channel.id)
            await message.channel.send(
                f"📣 {message.author.mention}님 멘션테러감지에 의해 메시지가 삭제되었습니다.\n사유: **{mention_reason}**\n누적 경고: {warning_count}회",
                delete_after=8
            )
            await send_log(
                message.guild,
                f"📣 멘션테러감지\n대상: {message.author.mention}\n채널: {message.channel.mention}\n사유: {mention_reason}\n누적 경고: {warning_count}회",
                "warning"
            )
            return

    if security_settings.get("auto_filter") and not message.author.guild_permissions.manage_messages:
        filter_reason = None
        filter_log_title = None

        if censor_settings.get("ip_block", True) and IP_BLOCK_REGEX.search(message.content):
            filter_reason = "IP 주소 게시"
            filter_log_title = "🛡️ IP 주소 차단"
        elif censor_settings.get("invite_links", True) and any(word in content_lower for word in AUTO_FILTER_INVITE_WORDS):
            filter_reason = "초대 링크 게시"
            filter_log_title = "🚫 초대 링크 차단"
        elif censor_settings.get("url_links", False) and not is_music_recommendation_channel(message.channel) and URL_BLOCK_REGEX.search(message.content or ""):
            filter_reason = "외부 링크 게시"
            filter_log_title = "🔗 일반 링크 차단"
        else:
            matched_word = None
            if censor_settings.get("bad_words", True):
                matched_word = next((word for word in AUTO_FILTER_BAD_WORDS if word and word in content_lower), None)
            if not matched_word and censor_settings.get("custom_words", True):
                matched_word = next((word for word in get_custom_filter_words(message.guild.id) if word and word in content_lower), None)
            if matched_word:
                filter_reason = f"금지어 사용({matched_word})"
                filter_log_title = "🤬 금지어 차단"

        if filter_reason:
            try:
                await message.delete()
            except discord.HTTPException:
                pass

            warning_count = await add_auto_warning(message.author, filter_reason)
            add_security_log(message.guild.id, message.author.id, "자동검열", filter_reason, message.channel.id)
            await message.channel.send(
                f"🧹 {message.author.mention}님 자동검열에 의해 메시지가 삭제되었습니다.\n사유: **{filter_reason}**\n누적 경고: {warning_count}회",
                delete_after=8
            )
            await send_log(
                message.guild,
                f"{filter_log_title}\n대상: {message.author.mention}\n채널: {message.channel.mention}\n내용: {message.content}\n누적 경고: {warning_count}회",
                "warning"
            )
            return

    if security_settings.get("spam_protection") and not message.author.guild_permissions.manage_messages:
        spam_reason = None
        spam_action = "스팸검열"

        if censor_settings.get("fast_spam", True):
            spam_key = (message.guild.id, user_id)
            spam_tracker.setdefault(spam_key, []).append(now)
            spam_tracker[spam_key] = [t for t in spam_tracker[spam_key] if now - t <= SPAM_TIME]
            if len(spam_tracker[spam_key]) >= SPAM_LIMIT:
                spam_tracker[spam_key] = []
                spam_reason = f"빠른 채팅 도배({SPAM_TIME}초 내 {SPAM_LIMIT}회)"
                spam_action = "빠른도배감지"

        normalized_content = normalize_spam_text(message.content)
        if not spam_reason and censor_settings.get("repeat_spam", True) and normalized_content and len(normalized_content) >= 2:
            repeat_key = (message.guild.id, user_id)
            repeat_message_tracker.setdefault(repeat_key, []).append((normalized_content, now))
            repeat_message_tracker[repeat_key] = [
                (text, ts) for text, ts in repeat_message_tracker[repeat_key]
                if now - ts <= CENSOR_REPEAT_WINDOW
            ]
            repeat_count = sum(1 for text, ts in repeat_message_tracker[repeat_key] if text == normalized_content)
            if repeat_count >= CENSOR_REPEAT_LIMIT:
                repeat_message_tracker[repeat_key] = []
                spam_reason = f"반복 문장 도배({CENSOR_REPEAT_WINDOW}초 내 같은 문장 {CENSOR_REPEAT_LIMIT}회)"
                spam_action = "반복도배감지"

        if not spam_reason and censor_settings.get("long_text_spam", False) and len(message.content or "") >= CENSOR_LONG_TEXT_LIMIT:
            spam_reason = f"긴 글 도배({len(message.content or '')}자)"
            spam_action = "긴글도배감지"

        if not spam_reason and censor_settings.get("newline_spam", False) and (message.content or "").count("\n") >= CENSOR_NEWLINE_LIMIT:
            spam_reason = f"줄바꿈 도배({(message.content or '').count(chr(10))}줄)"
            spam_action = "줄바꿈도배감지"

        if not spam_reason and censor_settings.get("caps_spam", False) and is_caps_spam(message.content or ""):
            spam_reason = "대문자 도배"
            spam_action = "대문자도배감지"

        emoji_count = count_emoji_like(message.content or "")
        if not spam_reason and censor_settings.get("emoji_spam", False) and emoji_count >= CENSOR_EMOJI_LIMIT:
            spam_reason = f"이모지 도배({emoji_count}개)"
            spam_action = "이모지도배감지"

        if not spam_reason and censor_settings.get("attachment_spam", True) and getattr(message, "attachments", None):
            attachment_count = len(message.attachments)
            if attachment_count >= CENSOR_ATTACHMENT_SINGLE_LIMIT:
                spam_reason = f"첨부파일 도배({attachment_count}개)"
                spam_action = "첨부도배감지"
            else:
                attachment_key = (message.guild.id, user_id)
                attachment_spam_tracker.setdefault(attachment_key, []).append((attachment_count, now))
                attachment_spam_tracker[attachment_key] = [
                    (count, ts) for count, ts in attachment_spam_tracker[attachment_key]
                    if now - ts <= CENSOR_ATTACHMENT_WINDOW
                ]
                total_attachments = sum(count for count, ts in attachment_spam_tracker[attachment_key])
                if total_attachments >= CENSOR_ATTACHMENT_LIMIT:
                    attachment_spam_tracker[attachment_key] = []
                    spam_reason = f"첨부파일 연속 도배({CENSOR_ATTACHMENT_WINDOW}초 내 {total_attachments}개)"
                    spam_action = "첨부도배감지"

        if spam_reason:
            await handle_spam_censor_violation(message, spam_reason, spam_action)
            return

    try:
        add_daily_mission_message_progress(message.guild.id, user_id)
        add_weekly_mission_message_progress(message.guild.id, user_id)
        await sync_weekly_mission_champion_title(message.guild)
    except Exception:
        pass

    last_exp_time = exp_cooldowns.get(user_id, 0)
    if now - last_exp_time >= EXP_COOLDOWN:
        exp_cooldowns[user_id] = now
        if mnb_is_level_excluded(message.guild.id, message.channel.id):
            return await mnb_v212_process_commands_once(message)
        exp, level = get_or_create_level_user(message.guild.id, user_id)
        exp_gain = 20 if has_exp_booster(user_id) else 10
        try:
            _lv_rate = int(get_level_settings(message.guild.id).get("chat_exp_rate") or 100)
            exp_gain = exp_gain * _lv_rate // 100
        except Exception:
            pass
        if exp_gain <= 0:
            return await mnb_v212_process_commands_once(message)
        exp += exp_gain
        need_exp = level * 100
        if exp >= need_exp:
            old_level = level
            level += 1
            exp -= need_exp
            await send_public_levelup_announcement(
                message.author,
                "🎉 채팅 레벨업!",
                f"{message.author.mention} 님의 채팅 레벨이 **Lv.{old_level} → Lv.{level}** 로 올랐어요!",
                preferred_channel=message.channel,
            )
            try:
                await mnb_grant_level_rewards(message.author, level)
            except Exception:
                pass
            try:
                await mnb_notify_new_achievements(message.author, message.channel)
            except Exception:
                pass
        c.execute("UPDATE levels SET exp=?, level=? WHERE guild_id=? AND user_id=?", (exp, level, message.guild.id, user_id))
        conn.commit()

    await mnb_v212_process_commands_once(message)


@bot.event
async def on_message_edit(before: discord.Message, after: discord.Message):
    if before.guild is None:
        return
    if before.author.bot:
        # 대시보드에서 기존 봇 임베드를 수정했을 때도 버튼을 자동 복구합니다.
        await maybe_attach_auto_buttons_to_bot_embed(after)
        return
    await send_log(before.guild, f"✏️ 메시지 수정\n채널: {before.channel.mention}\n작성자: {before.author.mention}\n수정 전: {before.content}\n수정 후: {after.content}", "chat")


@bot.event
async def on_message_delete(message: discord.Message):
    if message.author.bot or message.guild is None:
        return
    try:
        mnb_store_deleted_message(message)
    except Exception:
        pass
    await send_log(message.guild, f"🗑 삭제된 메시지\n채널: {message.channel.mention}\n작성자: {message.author.mention}\n내용: {message.content}", "chat")


