# =========================
# RPG 시스템 (몬스터 사냥 / 무기 강화 / 속성 부여)
# =========================
with DB_MUTEX:
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_players (
        guild_id INTEGER,
        user_id INTEGER,
        level INTEGER DEFAULT 1,
        exp INTEGER DEFAULT 0,
        hp INTEGER DEFAULT 100,
        max_hp INTEGER DEFAULT 100,
        weapon_level INTEGER DEFAULT 1,
        weapon_element TEXT DEFAULT '',
        hp_potion_purchases INTEGER DEFAULT 0,
        hp_potion_reset_date TEXT DEFAULT '',
        last_hunt_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id)
    )
    """)
    conn.commit()

    # v2 업그레이드: 방어구, 보스 쿨타임, 일일퀘스트용 컬럼을 안전하게 추가합니다.
    c.execute("PRAGMA table_info(rpg_players)")
    _rpg_existing_columns = {row[1] for row in c.fetchall()}
    _rpg_extra_columns = {
        "armor_level": "INTEGER DEFAULT 0",
        "last_boss_at": "TEXT DEFAULT ''",
        "daily_hunt_count": "INTEGER DEFAULT 0",
        "daily_quest_date": "TEXT DEFAULT ''",
        "daily_quest_claimed": "INTEGER DEFAULT 0",
        "weapon_rarity": "INTEGER DEFAULT 0",
        "armor_rarity": "INTEGER DEFAULT 0",
        "active_pet_name": "TEXT DEFAULT ''",
        "pet_data": "TEXT DEFAULT ''",
        "relic_slot1": "TEXT DEFAULT ''",
        "relic_slot2": "TEXT DEFAULT ''",
        "relic_slot3": "TEXT DEFAULT ''",
        "relic_slot4": "TEXT DEFAULT ''",
        "relic_slot5": "TEXT DEFAULT ''",
        "job": "TEXT DEFAULT ''",
        "stat_points": "INTEGER DEFAULT 0",
        "stat_attack": "INTEGER DEFAULT 0",
        "stat_magic": "INTEGER DEFAULT 0",
        "stat_agility": "INTEGER DEFAULT 0",
        "stat_luck": "INTEGER DEFAULT 0",
        "stat_hp_regen": "INTEGER DEFAULT 0",
        "stat_mp_regen": "INTEGER DEFAULT 0",
        "stat_int": "INTEGER DEFAULT 0",
        "pvp_wins": "INTEGER DEFAULT 0",
        "pvp_losses": "INTEGER DEFAULT 0",
        "weapon_options": "TEXT DEFAULT ''",
        "armor_options": "TEXT DEFAULT ''",
        "dungeon_floor": "INTEGER DEFAULT 0",
        "dungeon_date": "TEXT DEFAULT ''",
        "dungeon_attempts": "INTEGER DEFAULT 0",
        "accessory": "TEXT DEFAULT ''",
        "active_skill": "TEXT DEFAULT ''",
        "race": "TEXT DEFAULT ''",
        "skill_levels": "TEXT DEFAULT ''",
        "perks": "TEXT DEFAULT ''",
        "perk_points": "INTEGER DEFAULT 0",
        "mastery": "TEXT DEFAULT ''",
        "professions": "TEXT DEFAULT ''",
        "location": "TEXT DEFAULT 'town'",
        "social_role": "TEXT DEFAULT ''",
        "gather_date": "TEXT DEFAULT ''",
        "gather_count": "INTEGER DEFAULT 0",
        "rebirth": "INTEGER DEFAULT 0",
        "evolution": "INTEGER DEFAULT 0",
        "dimension": "INTEGER DEFAULT 0",
        "jobquest": "TEXT DEFAULT ''",
        "death_traits": "TEXT DEFAULT ''",
        "lifespan": "INTEGER DEFAULT 0",
        "last_death": "TEXT DEFAULT ''",
        "tactic": "TEXT DEFAULT 'balanced'",
        "food_buff": "TEXT DEFAULT ''",
        "custom_weapon": "TEXT DEFAULT ''",
        "last_daily": "TEXT DEFAULT ''",
        "daily_streak": "INTEGER DEFAULT 0",
        "pet_dispatch": "TEXT DEFAULT ''",
    }
    for _rpg_column, _rpg_definition in _rpg_extra_columns.items():
        if _rpg_column not in _rpg_existing_columns:
            try:
                c.execute(f"ALTER TABLE rpg_players ADD COLUMN {_rpg_column} {_rpg_definition}")
            except sqlite3.OperationalError:
                pass
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_pets (
        guild_id INTEGER,
        user_id INTEGER,
        pet_name TEXT,
        rarity_index INTEGER DEFAULT 0,
        count INTEGER DEFAULT 1,
        obtained_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id, pet_name)
    )
    """)
    conn.commit()

    # RPG 업적 보상 수령 기록 (진행도는 기존 스탯에서 실시간 계산, 여기엔 '수령 완료'만 저장)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_achievements (
        guild_id INTEGER,
        user_id INTEGER,
        ach_key TEXT,
        claimed_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id, ach_key)
    )
    """)
    conn.commit()

    # RPG 주간 랭킹 보상 지급 기록 (같은 주에 중복 지급 방지)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_weekly_reward (
        guild_id INTEGER,
        week_key TEXT,
        paid_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, week_key)
    )
    """)
    conn.commit()

    # rpg_players.custom_weapon(단일 장착 슬롯)은 그대로 두고, 장착 시 이 표의 데이터를 복사합니다.
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_custom_weapons (
        weapon_uid INTEGER PRIMARY KEY AUTOINCREMENT,
        guild_id INTEGER,
        user_id INTEGER,
        name TEXT,
        blade TEXT,
        handle TEXT,
        gem TEXT,
        power INTEGER DEFAULT 0,
        defense INTEGER DEFAULT 0,
        crit REAL DEFAULT 0.0,
        equipped INTEGER DEFAULT 0,
        created_at TEXT DEFAULT ''
    )
    """)
    conn.commit()
    c.execute("CREATE INDEX IF NOT EXISTS idx_rpg_custom_weapons_owner ON rpg_custom_weapons (guild_id, user_id)")
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_relics (
        guild_id INTEGER,
        user_id INTEGER,
        relic_id TEXT,
        count INTEGER DEFAULT 1,
        obtained_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id, relic_id)
    )
    """)
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_channels (
        guild_id INTEGER,
        feature TEXT,
        channel_id INTEGER,
        PRIMARY KEY (guild_id, feature)
    )
    """)
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_gacha_pity (
        guild_id INTEGER,
        user_id INTEGER,
        gacha_type TEXT,
        count INTEGER DEFAULT 0,
        PRIMARY KEY (guild_id, user_id, gacha_type)
    )
    """)
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_raids (
        guild_id INTEGER PRIMARY KEY,
        boss_name TEXT,
        boss_emoji TEXT,
        max_hp INTEGER,
        hp INTEGER,
        difficulty TEXT,
        started_at TEXT,
        started_by INTEGER
    )
    """)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_raid_damage (
        guild_id INTEGER,
        user_id INTEGER,
        damage INTEGER DEFAULT 0,
        last_attack_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id)
    )
    """)
    conn.commit()

    # 월드보스 — 서버 전체가 함께 때리는 대형 보스 (레이드와 별개, 더 큰 규모)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_worldboss (
        guild_id INTEGER PRIMARY KEY,
        boss_name TEXT,
        boss_emoji TEXT,
        max_hp INTEGER,
        hp INTEGER,
        started_at TEXT DEFAULT '',
        reward_pool INTEGER DEFAULT 0
    )
    """)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_worldboss_damage (
        guild_id INTEGER,
        user_id INTEGER,
        damage INTEGER DEFAULT 0,
        last_attack_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id)
    )
    """)
    conn.commit()

    # 개인 리마인더 — /알림 으로 등록, 지정 시각이 되면 멘션으로 알려줌
    c.execute("""
    CREATE TABLE IF NOT EXISTS reminders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        guild_id INTEGER,
        channel_id INTEGER,
        user_id INTEGER,
        content TEXT,
        remind_at TEXT,
        created_at TEXT
    )
    """)
    conn.commit()

    # 커스텀 자동응답 — 관리자가 등록한 트리거 단어에 봇이 지정 답변
    c.execute("""
    CREATE TABLE IF NOT EXISTS custom_responses (
        guild_id INTEGER,
        trigger TEXT,
        response TEXT,
        match_type TEXT DEFAULT 'exact',
        created_by INTEGER,
        created_at TEXT,
        PRIMARY KEY (guild_id, trigger)
    )
    """)
    conn.commit()

    # 익명 질문상자 — 서버별로 익명 질문이 올라갈 채널 지정
    c.execute("""
    CREATE TABLE IF NOT EXISTS anon_question_settings (
        guild_id INTEGER PRIMARY KEY,
        channel_id INTEGER,
        enabled INTEGER DEFAULT 1
    )
    """)
    conn.commit()

    # 기념일/디데이 — 서버별로 등록해두고 남은 날짜를 조회
    c.execute("""
    CREATE TABLE IF NOT EXISTS anniversaries (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        guild_id INTEGER,
        title TEXT,
        target_date TEXT,
        created_by INTEGER,
        created_at TEXT
    )
    """)
    conn.commit()

    # 개인 할일 목록 — 유저별 todo 관리 (완료 체크/삭제)
    c.execute("""
    CREATE TABLE IF NOT EXISTS todos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        content TEXT,
        done INTEGER DEFAULT 0,
        due_date TEXT DEFAULT '',
        created_at TEXT
    )
    """)
    conn.commit()

    # 16번: 서버 경제 — 복권 / 경매장 / 유저 시장
    # 복권: 회차별 상금 풀과 참여자 티켓을 관리
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_lottery (
        guild_id INTEGER PRIMARY KEY,
        round_no INTEGER DEFAULT 1,
        pool INTEGER DEFAULT 0,
        draw_date TEXT DEFAULT ''
    )
    """)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_lottery_tickets (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        guild_id INTEGER,
        round_no INTEGER,
        user_id INTEGER,
        numbers TEXT,
        bought_at TEXT
    )
    """)
    # 경매장: 아이템을 걸고 입찰받아 최고가에 낙찰
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_auctions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        guild_id INTEGER,
        seller_id INTEGER,
        item_name TEXT,
        amount INTEGER DEFAULT 1,
        start_price INTEGER,
        current_bid INTEGER,
        top_bidder_id INTEGER DEFAULT 0,
        end_at TEXT,
        status TEXT DEFAULT 'open',
        created_at TEXT
    )
    """)
    # 유저 시장: 고정가 판매 등록 (즉시 구매)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_market (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        guild_id INTEGER,
        seller_id INTEGER,
        item_name TEXT,
        amount INTEGER DEFAULT 1,
        price INTEGER,
        status TEXT DEFAULT 'open',
        created_at TEXT
    )
    """)
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_guilds (
        guild_id INTEGER,
        clan_id TEXT,
        name TEXT,
        leader_id INTEGER,
        level INTEGER DEFAULT 1,
        exp INTEGER DEFAULT 0,
        notice TEXT DEFAULT '',
        created_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, clan_id)
    )
    """)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_guild_members (
        guild_id INTEGER,
        user_id INTEGER,
        clan_id TEXT,
        contribution INTEGER DEFAULT 0,
        joined_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id)
    )
    """)
    conn.commit()

    conn.commit()

    #  category: monster/boss/pet/relic/accessory,  key: 항목 식별자(이름 또는 id)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_images (
        category TEXT,
        key TEXT,
        url TEXT,
        PRIMARY KEY (category, key)
    )
    """)
    conn.commit()

    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_parties (
        guild_id INTEGER,
        party_id TEXT,
        leader_id INTEGER,
        name TEXT,
        created_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, party_id)
    )
    """)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_party_members (
        guild_id INTEGER,
        user_id INTEGER,
        party_id TEXT,
        joined_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id)
    )
    """)
    conn.commit()

    for _gcol, _gdef in [
        ("territory_level", "INTEGER DEFAULT 1"),
        ("resources", "INTEGER DEFAULT 0"),
        ("war_wins", "INTEGER DEFAULT 0"),
        ("war_losses", "INTEGER DEFAULT 0"),
    ]:
        try:
            c.execute(f"ALTER TABLE rpg_guilds ADD COLUMN {_gcol} {_gdef}")
        except sqlite3.OperationalError:
            pass
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_guild_storage (
        guild_id INTEGER,
        clan_id TEXT,
        item_name TEXT,
        amount INTEGER DEFAULT 0,
        PRIMARY KEY (guild_id, clan_id, item_name)
    )
    """)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_guild_relations (
        guild_id INTEGER,
        clan_a TEXT,
        clan_b TEXT,
        relation TEXT DEFAULT 'neutral',
        PRIMARY KEY (guild_id, clan_a, clan_b)
    )
    """)
    # 6번: 길드 레이드 (길드원 협동 보스)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_guild_raids (
        guild_id INTEGER,
        clan_id TEXT,
        boss_name TEXT,
        boss_emoji TEXT,
        max_hp INTEGER,
        hp INTEGER,
        reward_resources INTEGER DEFAULT 0,
        PRIMARY KEY (guild_id, clan_id)
    )
    """)
    # PvP 시즌 (2주마다 초기화 + 1~5등 보상)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_pvp_season (
        guild_id INTEGER PRIMARY KEY,
        season_key INTEGER DEFAULT 0,
        reset_at TEXT DEFAULT ''
    )
    """)
    conn.commit()

    # 던전 시즌(2주마다 층수 초기화 + 1~3등 보상)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_dungeon_season (
        guild_id INTEGER PRIMARY KEY,
        season_key INTEGER DEFAULT 0,
        reset_at TEXT DEFAULT ''
    )
    """)
    conn.commit()

    # 명예의 전당 — 역대 시즌 1위 기록 보관 (PvP/던전 시즌 종료 시 자동 기록)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_hall_of_fame (
        guild_id INTEGER,
        category TEXT,
        season_key INTEGER,
        user_id INTEGER,
        record INTEGER DEFAULT 0,
        recorded_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, category, season_key)
    )
    """)
    conn.commit()

    # 시즌패스 — 활동으로 XP를 쌓아 티어를 올리고 보상 수령 (월간 시즌, 매달 1일 초기화)
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_season_pass (
        guild_id INTEGER,
        user_id INTEGER,
        season_key INTEGER,
        xp INTEGER DEFAULT 0,
        claimed_tiers TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id, season_key)
    )
    """)
    conn.commit()

    # v7확장: 차원 돌파 도전 과제 진행 상황 추적
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_dimension_challenges (
        guild_id INTEGER,
        user_id INTEGER,
        dimension_gate INTEGER,
        challenge_type TEXT,
        progress INTEGER DEFAULT 0,
        target INTEGER DEFAULT 0,
        started_at TEXT DEFAULT '',
        completed_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id, dimension_gate)
    )
    """)
    conn.commit()

    # v7확장: 플레이어가 획득한 진화 스킬 기록
    c.execute("""
    CREATE TABLE IF NOT EXISTS rpg_evolution_skills (
        guild_id INTEGER,
        user_id INTEGER,
        evolution_level INTEGER,
        skill_name TEXT,
        unlocked_at TEXT DEFAULT '',
        PRIMARY KEY (guild_id, user_id, evolution_level)
    )
    """)
    conn.commit()

