# =========================
# 관리자가 여는 이벤트(예: 경험치 2배)와 서버 부스트 보너스를 사냥/보스/던전/뽑기에 공통 적용합니다.
# rpg_event_state[guild_id] = {"exp": 2.0, "gold": 2.0, "drop": 1.0, "gacha": 1.0, "until": iso, "name": "..."}
rpg_event_state = {}
RPG_BOOST_REWARD_MULT = 1.5      # 서버 부스트 시 보상(경험치/포인트) 배율
RPG_BOOST_RARITY_BONUS = 0.05    # 서버 부스트 시 뽑기 상위등급 확률 가산치 (5%p씩 상위로 이동)


def rpg_guild_boosted(guild) -> bool:
    """서버가 부스트되어 있는지 (부스트 1개 이상)"""
    try:
        return bool(guild) and (guild.premium_subscription_count or 0) > 0
    except Exception:
        return False


def rpg_get_event(guild_id: int) -> dict:
    """진행 중인 이벤트를 돌려줍니다. 만료됐으면 자동 정리하고 빈 dict 반환."""
    ev = rpg_event_state.get(guild_id)
    if not ev:
        return {}
    until = ev.get("until")
    if until:
        try:
            if datetime.datetime.now() > datetime.datetime.fromisoformat(until):
                rpg_event_state.pop(guild_id, None)
                return {}
        except (ValueError, TypeError):
            pass
    return ev


def rpg_reward_multiplier(guild, guild_id: int, kind: str) -> float:
    """경험치/포인트/드랍 보상 배율 = 이벤트 배율 × (부스트면 1.5). kind: 'exp'|'gold'|'drop'"""
    ev = rpg_get_event(guild_id)
    mult = float(ev.get(kind, 1.0)) if ev else 1.0
    if rpg_guild_boosted(guild) and kind in ("exp", "gold", "drop"):
        mult *= RPG_BOOST_REWARD_MULT
    return mult


def rpg_gacha_rarity_shift(guild, guild_id: int) -> float:
    """뽑기 상위등급 확률 가산치. 이벤트 gacha 보너스 + 부스트 보너스를 합칩니다. (0.0~)"""
    bonus = 0.0
    ev = rpg_get_event(guild_id)
    if ev:
        bonus += max(0.0, float(ev.get("gacha", 1.0)) - 1.0)  # gacha=1.5 이면 +0.5
    if rpg_guild_boosted(guild):
        bonus += RPG_BOOST_RARITY_BONUS
    return bonus


# ===== 뽑기 레벨 시스템 (모든 뽑기 합산) =====
# 뽑기를 할 때마다 누적 횟수가 쌓이고, 특정 횟수마다 뽑기 레벨이 오릅니다.
# 레벨이 오르면 상위등급 확률(rarity_shift)이 영구적으로 조금씩 증가하고, 레벨업 보상을 받습니다.
RPG_GACHA_TOTAL_KEY = "__total__"   # rpg_gacha_pity 테이블에 총 뽑기 횟수를 저장하는 특수 키
# 각 레벨에 도달하는 누적 횟수. 100, 300, 500, 700, ... (레벨 오를수록 +200씩)
RPG_GACHA_LEVEL_THRESHOLDS = [100, 300, 500, 700, 1000, 1500, 2000, 3000, 5000, 7000, 10000]
RPG_GACHA_LEVEL_SHIFT_PER = 0.02    # 레벨당 상위등급 확률 가산치


def rpg_gacha_level_for_count(total: int) -> int:
    """누적 뽑기 횟수에 해당하는 뽑기 레벨 (1부터 시작)."""
    level = 1
    for th in RPG_GACHA_LEVEL_THRESHOLDS:
        if total >= th:
            level += 1
        else:
            break
    return level


def rpg_gacha_next_threshold(total: int):
    """다음 레벨까지 필요한 (다음 임계값, 남은 횟수). 최고 레벨이면 (None, 0)."""
    for th in RPG_GACHA_LEVEL_THRESHOLDS:
        if total < th:
            return th, th - total
    return None, 0


def rpg_get_gacha_total(guild_id: int, user_id: int) -> int:
    return rpg_get_pity(guild_id, user_id, RPG_GACHA_TOTAL_KEY)


def rpg_gacha_level_shift(guild_id: int, user_id: int) -> float:
    """뽑기 레벨에 따른 상위등급 확률 가산치."""
    total = rpg_get_gacha_total(guild_id, user_id)
    level = rpg_gacha_level_for_count(total)
    return (level - 1) * RPG_GACHA_LEVEL_SHIFT_PER


# 레벨업 시 지급 보상 (레벨 → (포인트, 아이템명, 아이템수))
def rpg_gacha_level_reward(level: int):
    if level % 5 == 0:
        return (5000, "유물함", 1)      # 5의 배수 레벨: 큰 보상
    if level % 2 == 0:
        return (2000, "소환권", 2)      # 짝수 레벨
    return (1000, "강화석", 3)          # 홀수 레벨


def rpg_gacha_add_pulls(guild_id: int, user_id: int, count: int) -> list:
    """뽑기 횟수를 누적하고, 이번에 오른 레벨들의 (레벨, 보상) 목록을 돌려줍니다."""
    before = rpg_get_gacha_total(guild_id, user_id)
    after = before + count
    rpg_set_pity(guild_id, user_id, RPG_GACHA_TOTAL_KEY, after)
    before_level = rpg_gacha_level_for_count(before)
    after_level = rpg_gacha_level_for_count(after)
    level_ups = []
    if after_level > before_level:
        for lv in range(before_level + 1, after_level + 1):
            reward = rpg_gacha_level_reward(lv)
            point, item_name, item_amt = reward
            if point:
                set_user_point(guild_id, user_id, get_user_point(guild_id, user_id) + point)
            if item_name and item_amt:
                add_inventory_item(user_id, item_name, item_amt, guild_id=guild_id)
            level_ups.append((lv, reward))
    return level_ups


