def rpg_build_event_embed(guild_id: int) -> discord.Embed:
    ev = rpg_get_event(guild_id)
    if ev:
        until = ev.get("until", "")
        mults = []
        if ev.get("exp", 1.0) != 1.0:
            mults.append(f"경험치 x{ev['exp']:g}")
        if ev.get("gold", 1.0) != 1.0:
            mults.append(f"포인트 x{ev['gold']:g}")
        if ev.get("drop", 1.0) != 1.0:
            mults.append(f"드랍률 x{ev['drop']:g}")
        if ev.get("gacha", 1.0) != 1.0:
            mults.append(f"뽑기확률 UP")
        desc = f"🟢 **진행 중: {ev.get('name', '이벤트')}**\n효과: {', '.join(mults) or '없음'}\n종료: {until[:16] if until else '수동'}"
    else:
        desc = "🔴 현재 진행 중인 이벤트가 없어요.\n아래 메뉴에서 이벤트를 선택하면 바로 시작됩니다."
    embed = discord.Embed(title="🎉 RPG 이벤트 관리", description=desc, color=discord.Color.gold())
    embed.add_field(
        name="ℹ️ 참고",
        value="이벤트 효과는 사냥·보스·던전·레이드 보상과 뽑기에 자동 적용돼요. 서버 부스트 보너스(1.5배)와도 중첩됩니다.",
        inline=False,
    )
    embed.set_footer(text="관리자 전용 | 만능 봇 RPG 이벤트")
    return embed


class RPGEventPresetSelect(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label=preset["name"], description=f"{preset['hours']}시간 지속", value=key)
            for key, preset in RPG_EVENT_PRESETS.items()
        ]
        super().__init__(placeholder="시작할 이벤트를 선택하세요", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction: discord.Interaction):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
        preset = RPG_EVENT_PRESETS[self.values[0]]
        until = (datetime.datetime.now() + datetime.timedelta(hours=preset["hours"])).isoformat()
        rpg_event_state[self.view.guild_id] = {
            "name": preset["name"], "exp": preset["exp"], "gold": preset["gold"],
            "drop": preset["drop"], "gacha": preset["gacha"], "until": until,
        }
        embed = rpg_build_event_embed(self.view.guild_id)
        embed.add_field(name="✅ 시작됨!", value=f"**{preset['name']}** 이벤트가 시작됐어요! ({preset['hours']}시간)", inline=False)
        await interaction.response.edit_message(embed=embed, view=self.view)


class RPGEventAdminView(discord.ui.View):
    def __init__(self, guild_id: int):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.add_item(RPGEventPresetSelect())

    @discord.ui.button(label="이벤트 종료", emoji="⏹️", style=discord.ButtonStyle.danger, row=1)
    async def end_event(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
        rpg_event_state.pop(self.guild_id, None)
        embed = rpg_build_event_embed(self.guild_id)
        embed.add_field(name="⏹️ 종료됨", value="진행 중이던 이벤트를 종료했어요.", inline=False)
        await interaction.response.edit_message(embed=embed, view=self)


