RPG_STAT_BY_NAME = {name: field for field, name, _e, _d in RPG_STATS}


def rpg_stat_bonus_pct(player: dict, stat_field: str) -> float:
    """스탯 5포인트마다 5%씩 증가하는 보너스 비율을 돌려줍니다. (예: 12포인트 → 0.10)"""
    points = player.get(stat_field, 0) or 0
    return (points // RPG_STAT_STEP) * RPG_STAT_STEP_BONUS


def rpg_dodge_chance(player: dict) -> float:
    """민첩 스탯 + 세공 옵션 기반 회피율 (최대 50%)"""
    return min(0.50, rpg_stat_bonus_pct(player, "stat_agility") + rpg_engrave_total(player, "opt_dodge") / 100)


def rpg_drop_rate_multiplier(player: dict) -> float:
    """럭 스탯 + 세공 옵션 기반 드랍률 배율 (몬스터/보스 공용)"""
    luck_bonus = min(RPG_DROP_CAP, rpg_stat_bonus_pct(player, "stat_luck"))  # 럭 드랍 보너스는 +50%까지
    return 1.0 + luck_bonus + rpg_engrave_total(player, "opt_drop") / 100


def rpg_luck_crit_bonus(player: dict) -> float:
    """6번: 럭 스탯 5포인트당 크리 확률 +1% (상한 +30%)"""
    points = player.get("stat_luck", 0) or 0
    return min(RPG_LUCK_CRIT_CAP, (points // RPG_STAT_STEP) * RPG_LUCK_CRIT_PER_STEP)


def rpg_skill_crit_enabled(player: dict) -> bool:
    """6번: MP회복 스탯 100 이상이면 스킬(추가타·반격 등)에도 크리가 적용됨"""
    return (player.get("stat_mp_regen", 0) or 0) >= RPG_MP_SKILL_CRIT_THRESHOLD


def rpg_stat_effect_label(player: dict, stat_field: str) -> str:
    """6번: 스탯 효과 표시. 상한 도달 시 (Max) 표기."""
    points = player.get(stat_field, 0) or 0
    if stat_field == "stat_agility":
        pct = min(RPG_DODGE_CAP, rpg_stat_bonus_pct(player, stat_field)) * 100
        maxed = points >= RPG_DODGE_CAP_POINTS
        return f"회피 +{pct:.0f}%" + (" (Max)" if maxed else "")
    if stat_field == "stat_luck":
        drop_pct = min(RPG_DROP_CAP, rpg_stat_bonus_pct(player, stat_field)) * 100
        crit_pct = rpg_luck_crit_bonus(player) * 100
        drop_maxed = points >= RPG_DROP_CAP_POINTS
        return f"드랍 +{drop_pct:.0f}%{' (Max)' if drop_maxed else ''}, 크리 +{crit_pct:.0f}%"
    # 기타 스탯: 일반 % 보너스
    pct = rpg_stat_bonus_pct(player, stat_field) * 100
    return f"+{pct:.0f}%"


def rpg_heal_multiplier(player: dict) -> float:
    """HP회복량 스탯 + 세공 옵션 기반 회복 효과 배율 (물약·사제 자힐 등)"""
    return 1.0 + rpg_stat_bonus_pct(player, "stat_hp_regen") + rpg_engrave_total(player, "opt_heal") / 100


def rpg_exp_multiplier(player: dict) -> float:
    """지력 스탯 + 세공 옵션 기반 경험치 획득 배율"""
    return 1.0 + rpg_stat_bonus_pct(player, "stat_int") + rpg_engrave_total(player, "opt_exp") / 100


