def rpg_equip_name(kind: str, level: int, rarity_index: int = -1) -> str:
    # ??? 등급(사신수)은 전용 이름을 사용합니다. (강화수치로 사신수 종류를 안정적으로 결정)
    if rarity_index >= RPG_SASIN_RARITY_INDEX:
        names = RPG_SASIN_WEAPON_NAMES if kind == "weapon" else RPG_SASIN_ARMOR_NAMES
        return names[(level or 0) % len(names)]
    names = RPG_WEAPON_NAMES if kind == "weapon" else RPG_ARMOR_NAMES
    idx = min(len(names) - 1, max(0, (level or 0) // 5))  # 5강화 단위로 이름 변화
    return names[idx]


