def _rpg_key_is_text(key: str) -> bool:
    return key in _RPG_TEXT_KEYS


def get_or_create_rpg_player(guild_id: int, user_id: int) -> dict:
    with DB_MUTEX:
        c.execute(
            "SELECT level, exp, hp, max_hp, weapon_level, weapon_element, hp_potion_purchases, hp_potion_reset_date, last_hunt_at, "
            "armor_level, last_boss_at, daily_hunt_count, daily_quest_date, daily_quest_claimed, "
            "weapon_rarity, armor_rarity, active_pet_name, pet_data, relic_slot1, relic_slot2, relic_slot3, relic_slot4, relic_slot5, job, "
            "stat_points, stat_attack, stat_magic, stat_agility, stat_luck, stat_hp_regen, stat_mp_regen, stat_int, pvp_wins, pvp_losses, weapon_options, armor_options, dungeon_floor, dungeon_date, dungeon_attempts, accessory, active_skill, race, skill_levels, perks, perk_points, mastery, professions, location, social_role, gather_date, gather_count, rebirth, evolution, dimension, jobquest, death_traits, lifespan, last_death, tactic, food_buff, custom_weapon "
            "FROM rpg_players WHERE guild_id=? AND user_id=?",
            (guild_id, user_id),
        )
        row = c.fetchone()
        if row is None:
            c.execute(
                "INSERT INTO rpg_players (guild_id, user_id, level, exp, hp, max_hp, weapon_level, weapon_element, hp_potion_purchases, hp_potion_reset_date, last_hunt_at) "
                "VALUES (?, ?, 1, 0, 100, 100, 1, '', 0, '', '')",
                (guild_id, user_id),
            )
            conn.commit()
            # 새로 만든 캐릭터는 기본값으로 채웁니다. keys 순서에 맞춰 자동 생성해
            # 컬럼 추가 시 폴백 튜플이 어긋나는 실수를 방지합니다.
            _default_row = {
                "level": 1, "exp": 0, "hp": 100, "max_hp": 100, "weapon_level": 1, "weapon_element": "",
                "hp_potion_purchases": 0, "hp_potion_reset_date": "", "last_hunt_at": "",
                "location": "town", "tactic": "balanced",
            }
            row = tuple(_default_row.get(k, "" if _rpg_key_is_text(k) else 0) for k in _RPG_PLAYER_KEYS)
    keys = _RPG_PLAYER_KEYS
    player = dict(zip(keys, row))
    # 예전 데이터(컬럼 추가 전)는 None으로 나올 수 있어 기본값으로 안전하게 채웁니다.
    player["armor_level"] = player["armor_level"] or 0
    player["last_boss_at"] = player["last_boss_at"] or ""
    player["daily_hunt_count"] = player["daily_hunt_count"] or 0
    player["daily_quest_date"] = player["daily_quest_date"] or ""
    player["daily_quest_claimed"] = player["daily_quest_claimed"] or 0
    player["weapon_rarity"] = player["weapon_rarity"] or 0
    player["armor_rarity"] = player["armor_rarity"] or 0
    player["active_pet_name"] = player["active_pet_name"] or ""
    player["pet_data"] = player.get("pet_data") or ""
    for slot_field in ("relic_slot1", "relic_slot2", "relic_slot3", "relic_slot4", "relic_slot5"):
        player[slot_field] = player[slot_field] or ""
    player["job"] = player["job"] or ""
    for stat_field in RPG_STAT_FIELDS:
        player[stat_field] = player[stat_field] or 0
    player["stat_points"] = player["stat_points"] or 0
    player["pvp_wins"] = player["pvp_wins"] or 0
    player["pvp_losses"] = player["pvp_losses"] or 0
    player["weapon_options"] = player["weapon_options"] or ""
    player["armor_options"] = player["armor_options"] or ""
    player["dungeon_floor"] = player["dungeon_floor"] or 0
    player["dungeon_date"] = player["dungeon_date"] or ""
    player["dungeon_attempts"] = player["dungeon_attempts"] or 0
    player["accessory"] = player["accessory"] or ""
    player["active_skill"] = player["active_skill"] or ""
    player["race"] = player["race"] or ""
    player["skill_levels"] = player["skill_levels"] or ""
    player["perks"] = player["perks"] or ""
    player["perk_points"] = player["perk_points"] or 0
    player["mastery"] = player["mastery"] or ""
    player["professions"] = player["professions"] or ""
    player["location"] = player["location"] or "town"
    player["social_role"] = player["social_role"] or ""
    player["gather_date"] = player["gather_date"] or ""
    player["gather_count"] = player["gather_count"] or 0
    player["rebirth"] = player["rebirth"] or 0
    player["evolution"] = player["evolution"] or 0
    player["dimension"] = player["dimension"] or 0
    player["jobquest"] = player["jobquest"] or ""
    player["death_traits"] = player["death_traits"] or ""
    player["lifespan"] = player["lifespan"] or 0
    player["last_death"] = player["last_death"] or ""
    player["tactic"] = player.get("tactic") or "balanced"
    player["food_buff"] = player.get("food_buff") or ""
    player["custom_weapon"] = player.get("custom_weapon") or ""

    # 스탯 시스템 도입 전에 레벨업했던 유저에게도 (레벨-1)*3 포인트를 소급 지급합니다.
    expected_total = (player["level"] - 1) * RPG_STAT_POINTS_PER_LEVEL
    current_total = player["stat_points"] + sum(player[field] for field in RPG_STAT_FIELDS)
    if current_total < expected_total:
        player["stat_points"] += expected_total - current_total
        save_rpg_player(guild_id, user_id, stat_points=player["stat_points"])
    return player


def save_rpg_player(guild_id: int, user_id: int, **fields):
    if not fields:
        return
    with DB_MUTEX:
        assignments = ", ".join(f"{key}=?" for key in fields.keys())
        values = list(fields.values()) + [guild_id, user_id]
        c.execute(f"UPDATE rpg_players SET {assignments} WHERE guild_id=? AND user_id=?", values)
        conn.commit()


def rpg_rarity_tier(rarity_index: int) -> dict:
    idx = max(0, min(rarity_index or 0, len(RPG_RARITY_TIERS) - 1))
    return RPG_RARITY_TIERS[idx]


# ---------- 펫이 유저에게 주는 버프 ----------
# 펫 희귀도(rarity_index)별로 부가 능력치 버프를 줍니다. 버프 종류는 희귀도가 높을수록 강해지고,
# 펫 레벨/진화에 따라 추가로 상승합니다. (전투력 고정 보너스와 별개)
RPG_PET_BUFF_BY_RARITY = {
    # rarity_index: {버프키: 기본%}
    0: {"exp": 0.03},                                        # 흔함: 경험치 +3%
    1: {"exp": 0.05, "gold": 0.05},                          # 고급: 경험치·골드 +5%
    2: {"power": 0.05, "drop": 0.05},                        # 희귀: 공격 +5%, 드랍 +5%
    3: {"power": 0.08, "defense": 0.05, "crit": 0.03},       # 영웅: 공격 +8%, 방어 +5%, 크리 +3%
    4: {"power": 0.10, "defense": 0.08, "crit": 0.05, "heal": 0.05},  # 전설
    5: {"power": 0.15, "defense": 0.10, "crit": 0.07, "heal": 0.08, "exp": 0.10},  # 신화
    6: {"power": 0.25, "defense": 0.18, "crit": 0.12, "heal": 0.15, "exp": 0.20, "drop": 0.15},  # ??? 사신수
}
RPG_PET_BUFF_LABELS = {
    "power": "공격력", "defense": "방어력", "crit": "크리 확률",
    "heal": "회복량", "exp": "획득 경험치", "gold": "획득 골드", "drop": "드랍률",
}


def rpg_pet_buffs(player: dict) -> dict:
    """장착 펫이 유저에게 주는 버프 딕셔너리 {버프키: 비율}. 레벨·진화로 강화됨."""
    pet_name = player.get("active_pet_name") or ""
    info = RPG_PET_INFO_BY_NAME.get(pet_name)
    if not info:
        return {}
    rarity_index = info[0]
    base_buffs = RPG_PET_BUFF_BY_RARITY.get(rarity_index, {})
    if not base_buffs:
        return {}
    pdata = rpg_get_pet_state(player, pet_name)
    # 레벨당 +2%, 진화 단계당 +30% 강화
    level_mult = 1.0 + 0.02 * (pdata["level"] - 1)
    evo_mult = 1.0 + 0.3 * pdata["evolution"]
    total_mult = level_mult * evo_mult
    return {k: v * total_mult for k, v in base_buffs.items()}


def rpg_pet_buff(player: dict, key: str) -> float:
    """특정 버프 값 (없으면 0)."""
    return rpg_pet_buffs(player).get(key, 0.0)


def rpg_pet_power_bonus(player: dict) -> int:
    pet_name = player.get("active_pet_name") or ""
    info = RPG_PET_INFO_BY_NAME.get(pet_name)
    if not info:
        return 0
    base = info[1]
    # 5번: 펫 성장/진화 반영 — 레벨과 진화 단계에 따라 파워 보너스 상승
    pdata = rpg_get_pet_state(player, pet_name)
    level_bonus = int(base * 0.05 * (pdata["level"] - 1))       # 레벨당 기본 보너스 +5%
    evo_mult = 1.0 + 0.5 * pdata["evolution"]                    # 진화 1단계당 +50%
    return int((base + level_bonus) * evo_mult)


# ---------- 5번: 펫 성장 · 진화 · 버프 ----------
RPG_PET_MAX_LEVEL = 50           # 펫 최대 레벨
RPG_PET_EVOLVE_LEVELS = [20, 40]  # 이 레벨에 도달하면 진화 가능 (진화 1, 2단계)
RPG_PET_EVOLVE_ITEM = "펫 진화석"  # 진화에 필요한 아이템
RPG_PET_EXP_PER_HUNT = 8          # 전투 1회당 펫 경험치
RPG_PET_EVOLVE_STAGE_NAMES = ["", "각성", "초월"]  # 진화 단계 이름


def rpg_pet_exp_needed(level: int) -> int:
    """펫 레벨업 필요 경험치."""
    return 30 + (level - 1) * 25


def _rpg_load_pet_data(player: dict) -> dict:
    raw = player.get("pet_data") or ""
    if not raw:
        return {}
    try:
        return json.loads(raw)
    except Exception:
        return {}


def rpg_get_pet_state(player: dict, pet_name: str) -> dict:
    """특정 펫의 성장 상태를 돌려줍니다. 없으면 기본값."""
    data = _rpg_load_pet_data(player)
    st = data.get(pet_name) or {}
    return {
        "level": max(1, int(st.get("level", 1))),
        "exp": max(0, int(st.get("exp", 0))),
        "evolution": max(0, int(st.get("evolution", 0))),
    }


def rpg_save_pet_state(guild_id, user_id, pet_name: str, state: dict):
    player = get_or_create_rpg_player(guild_id, user_id)
    data = _rpg_load_pet_data(player)
    data[pet_name] = {
        "level": state["level"], "exp": state["exp"], "evolution": state["evolution"],
    }
    save_rpg_player(guild_id, user_id, pet_data=json.dumps(data, ensure_ascii=False))


def rpg_pet_gain_exp(guild_id, user_id, amount: int = RPG_PET_EXP_PER_HUNT) -> dict:
    """장착한 펫에게 경험치를 주고, 레벨업이 있으면 정보를 반환합니다."""
    player = get_or_create_rpg_player(guild_id, user_id)
    pet_name = player.get("active_pet_name") or ""
    if not pet_name or pet_name not in RPG_PET_INFO_BY_NAME:
        return {"leveled": False}
    st = rpg_get_pet_state(player, pet_name)
    if st["level"] >= RPG_PET_MAX_LEVEL:
        return {"leveled": False, "maxed": True, "pet_name": pet_name}
    st["exp"] += amount
    leveled = 0
    while st["level"] < RPG_PET_MAX_LEVEL and st["exp"] >= rpg_pet_exp_needed(st["level"]):
        st["exp"] -= rpg_pet_exp_needed(st["level"])
        st["level"] += 1
        leveled += 1
    if st["level"] >= RPG_PET_MAX_LEVEL:
        st["exp"] = 0
    rpg_save_pet_state(guild_id, user_id, pet_name, st)
    can_evolve = st["evolution"] < len(RPG_PET_EVOLVE_LEVELS) and st["level"] >= RPG_PET_EVOLVE_LEVELS[st["evolution"]]
    return {"leveled": leveled > 0, "level": st["level"], "level_ups": leveled,
            "pet_name": pet_name, "can_evolve": can_evolve}


def rpg_pet_evolve(guild_id, user_id) -> dict:
    """장착 펫을 진화시킵니다. 진화석 필요 + 레벨 조건."""
    player = get_or_create_rpg_player(guild_id, user_id)
    pet_name = player.get("active_pet_name") or ""
    if not pet_name or pet_name not in RPG_PET_INFO_BY_NAME:
        return {"error": "먼저 펫을 장착해주세요."}
    st = rpg_get_pet_state(player, pet_name)
    if st["evolution"] >= len(RPG_PET_EVOLVE_LEVELS):
        return {"error": "이미 최종 진화 단계예요."}
    need_level = RPG_PET_EVOLVE_LEVELS[st["evolution"]]
    if st["level"] < need_level:
        return {"error": f"진화하려면 펫 레벨 {need_level} 이상이 필요해요. (현재 Lv.{st['level']})"}
    if get_inventory_amount(user_id, RPG_PET_EVOLVE_ITEM) < 1:
        return {"error": f"진화에는 **{RPG_PET_EVOLVE_ITEM}**이 1개 필요해요. `/rpg 상점`에서 구매하세요."}
    consume_inventory_item(user_id, RPG_PET_EVOLVE_ITEM, 1)
    st["evolution"] += 1
    rpg_save_pet_state(guild_id, user_id, pet_name, st)
    stage_name = RPG_PET_EVOLVE_STAGE_NAMES[st["evolution"]] if st["evolution"] < len(RPG_PET_EVOLVE_STAGE_NAMES) else f"{st['evolution']}단계"
    return {"pet_name": pet_name, "evolution": st["evolution"], "stage_name": stage_name}


