for _base_id, _branches in RPG_JOB_BRANCHES.items():
    for _bid, _bname, _bdesc, _bmult in _branches:
        RPG_JOB_BRANCH_BY_ID[_bid] = (_base_id, _bname, _bdesc, _bmult)


# ============================================================
# 풀 트리 전직: 2차~마스터까지 매 단계마다 2갈래로 갈라집니다.
# 각 노드에서 다음 단계로 갈 때 (접미사, 이름접두, 스탯강화방향) 2가지 중 선택.
# 노드 id = "<2차분기id>>path" 형태로 경로를 누적 저장합니다.
#   예: warrior_warlord  →  warrior_warlord>a  →  warrior_warlord>a>b ...
# 이렇게 하면 데이터를 수백 개 나열하지 않아도 트리가 무한 확장됩니다.
# ============================================================
# 각 상위 단계(3·4·5·마스터)에서 제공되는 2갈래의 "성향" 정의.
# (접미사키, 표시명 접미어, 강화할 스탯 방향)
RPG_JOB_TREE_SPLITS = {
    3: [
        ("off", "· 공세", {"power_pct": 1.3, "crit_mult_bonus": 1.3, "extra_attack_pct": 1.3}),
        ("def", "· 수호", {"defense_pct": 1.3, "reflect_pct": 1.3, "heal_pct": 1.2}),
    ],
    4: [
        ("crit", "· 필멸", {"crit_chance_bonus": 1.3, "crit_mult_bonus": 1.4, "first_strike_chance": 1.2}),
        ("swift", "· 질풍", {"extra_attack_chance": 1.4, "first_strike_chance": 1.3, "extra_attack_pct": 1.2}),
    ],
    5: [
        ("power", "· 패왕", {"power_pct": 1.4, "extra_attack_pct": 1.3, "crit_mult_bonus": 1.2}),
        ("holy", "· 성좌", {"heal_pct": 1.4, "heal_chance": 1.3, "reflect_pct": 1.3, "defense_pct": 1.2}),
    ],
    6: [
        ("chaos", "· 혼돈", {"power_pct": 1.5, "crit_mult_bonus": 1.4, "extra_attack_pct": 1.4}),
        ("order", "· 질서", {"defense_pct": 1.4, "heal_pct": 1.4, "reflect_pct": 1.4, "reflect_chance": 1.3}),
    ],
}
RPG_JOB_TREE_TITLE_SUFFIX = {  # 최종 표시 이름에 붙는 칭호 (tier별)
    3: {"off": "광휘", "def": "불굴"},
    4: {"crit": "심판", "swift": "폭풍"},
    5: {"power": "패왕", "holy": "성좌"},
    6: {"chaos": "혼돈군주", "order": "질서수호자"},
}


def rpg_split_job_path(job_id: str):
    """노드 id에서 (2차 분기 base_id, [단계별 선택키...]) 를 분리."""
    if ">" in job_id:
        base, _, rest = job_id.partition(">")
        path = [p for p in rest.split(">") if p]
        return base, path
    return job_id, []


def rpg_tree_children(job_id: str, next_tier: int):
    """이 노드에서 next_tier로 전직할 때 선택 가능한 2갈래를 돌려줍니다.
    (child_job_id, 표시명, 설명, 강화배율) 튜플 리스트. 갈래가 없으면 빈 리스트."""
    splits = RPG_JOB_TREE_SPLITS.get(next_tier)
    if not splits:
        return []
    base2, path = rpg_split_job_path(job_id)
    # 2차 분기여야 트리 진입 가능
    if base2 not in RPG_JOB_BRANCH_BY_ID:
        return []
    _b, bname, _d, _m = RPG_JOB_BRANCH_BY_ID[base2]
    children = []
    for key, name_suffix, stat_dir in splits:
        child_id = f"{job_id}>{key}"
        title = RPG_JOB_TREE_TITLE_SUFFIX.get(next_tier, {}).get(key, key)
        display = f"{bname} {title}"
        desc = f"{name_suffix.replace('· ', '')} 특화 — {bname}의 {RPG_JOB_TIER_LABELS[next_tier-1]} 갈래"
        children.append((child_id, display, desc, stat_dir))
    return children


def rpg_resolve_job_line(job_id):
    """job_id가 분기/트리 노드면 기본 직업 라인 + 분기 정보를 합성해서 돌려줍니다."""
    if job_id in RPG_JOB_LINES_BY_ID:
        return RPG_JOB_LINES_BY_ID[job_id]

    base2, path = rpg_split_job_path(job_id)
    branch = RPG_JOB_BRANCH_BY_ID.get(base2)
    if not branch:
        return None
    base_id, bname, bdesc, bmult = branch
    base = RPG_JOB_LINES_BY_ID.get(base_id)
    if not base:
        return None
    new_stats = dict(base["base_stats"])
    RPG_BRANCH_SEED = {
        "power_pct": 0.10, "defense_pct": 0.10, "reflect_chance": 0.10, "reflect_pct": 0.15,
        "extra_attack_chance": 0.12, "extra_attack_pct": 0.25, "crit_chance_bonus": 0.06,
        "crit_mult_bonus": 0.12, "heal_chance": 0.08, "heal_pct": 0.08, "first_strike_chance": 0.10,
    }
    # 2차 분기 특성 반영
    for k, mult in bmult.items():
        if k not in new_stats:
            continue
        cur = new_stats[k]
        if abs(cur) > 1e-9:
            new_stats[k] = round(cur * mult, 4)
        else:
            new_stats[k] = round(RPG_BRANCH_SEED.get(k, 0.05) * mult, 4)

    # 트리 경로(3차 이상 선택)의 성향 강화 반영
    display_suffixes = []
    for depth, choice_key in enumerate(path):
        node_tier = 3 + depth  # path[0]은 3차 선택
        splits = RPG_JOB_TREE_SPLITS.get(node_tier, [])
        split = next((s for s in splits if s[0] == choice_key), None)
        if not split:
            continue
        _key, _suffix, stat_dir = split
        for k, mult in stat_dir.items():
            if k in new_stats and abs(new_stats[k]) > 1e-9:
                new_stats[k] = round(new_stats[k] * mult, 4)
            elif k in new_stats:
                new_stats[k] = round(RPG_BRANCH_SEED.get(k, 0.05) * mult, 4)
        title = RPG_JOB_TREE_TITLE_SUFFIX.get(node_tier, {}).get(choice_key, "")
        if title:
            display_suffixes.append(title)

    # 표시 이름 구성
    titles = list(base["tier_titles"])
    titles[1] = bname
    for t in range(2, 6):
        # 트리 선택이 있으면 그 칭호를, 없으면 기본 단계 라벨
        suffix = display_suffixes[t - 2] if (t - 2) < len(display_suffixes) else ""
        titles[t] = f"{bname} {suffix}".strip() if suffix else (bname + " " + RPG_JOB_TIER_LABELS[t])

    line_name = base["line_name"] + "\u2192" + bname
    if display_suffixes:
        line_name += " " + " ".join(display_suffixes)
    return {
        "job_id": job_id, "icon": base["icon"], "color": base["color"],
        "line_name": line_name,
        "tier_titles": titles, "base_stats": new_stats,
        "skill_desc": bdesc, "_base_id": base_id, "_branch_name": bname,
    }


RPG_NO_JOB_STATS = {
    "power_pct": 0.0, "defense_pct": 0.0,
    "reflect_chance": 0.0, "reflect_pct": 0.0,
    "extra_attack_chance": 0.0, "extra_attack_pct": 0.0,
    "crit_chance_bonus": 0.0, "crit_mult_bonus": 0.0,
    "heal_chance": 0.0, "heal_pct": 0.0,
    "first_strike_chance": 0.0,
}


def rpg_parse_job_field(job_field: str) -> tuple:
    """DB에 저장된 job 문자열("warrior:3")을 (job_id, tier)로 분리합니다.
    예전 버전 데이터(콜론 없이 "warrior"만 저장됨)는 1차전직으로 취급합니다."""
    raw = (job_field or "").strip()
    if not raw:
        return "", 0
    if ":" in raw:
        job_id, _, tier_text = raw.partition(":")
        try:
            tier = int(tier_text)
        except ValueError:
            tier = 1
        return job_id, max(1, min(6, tier))
    return raw, 1  # 콜론 없는 예전 데이터 호환


def rpg_job_stats(job_field: str) -> dict:
    """현재 직업 단계에 맞춰 배율이 적용된 스킬 수치를 돌려줍니다. (분기 직업 포함)"""
    job_id, tier = rpg_parse_job_field(job_field)
    line = rpg_resolve_job_line(job_id)
    if not line or tier <= 0:
        stats = dict(RPG_NO_JOB_STATS)
        stats.update({"job_id": "", "tier": 0, "line_name": "미선택", "tier_title": "미선택", "skill_desc": "`/rpg 직업선택`으로 직업을 골라보세요."})
        return stats
    mult = RPG_JOB_TIER_STAT_MULT[tier - 1]
    stats = {key: round(value * mult, 4) for key, value in line["base_stats"].items()}
    stats.update({
        "job_id": job_id, "tier": tier,
        "line_name": line["line_name"], "tier_title": line["tier_titles"][tier - 1],
        "skill_desc": line["skill_desc"],
    })
    return stats


def rpg_job_info(job_id: str) -> dict:
    """(구버전 호환용) job_id 하나만 받아 1차전직 기준 스탯을 돌려줍니다."""
    return rpg_job_stats(job_id)


