# ---------- 11번: 종족 특성 ----------
# 캐릭터 생성 시 1회 선택 (되돌리려면 종족변경권 필요). 종족별 상시 보너스.
RPG_RACES = {
    "human":    {"name": "휴먼",     "emoji": "🧑", "desc": "균형잡힌 만능형", "bonus": {"power": 0.05, "defense": 0.05, "exp": 0.05}},
    "elf":      {"name": "엘프",     "emoji": "🧝", "desc": "마법·회피에 능함", "bonus": {"power": 0.10, "dodge": 0.05}},
    "dwarf":    {"name": "드워프",   "emoji": "🧔", "desc": "튼튼한 방어와 제작", "bonus": {"defense": 0.15, "craft": 0.20}},
    "orc":      {"name": "오크",     "emoji": "👹", "desc": "압도적 공격력", "bonus": {"power": 0.15, "defense": -0.05}},
    "beast":    {"name": "수인",     "emoji": "🐺", "desc": "빠른 연타와 크리티컬", "bonus": {"power": 0.08, "crit": 0.08}},
    "undead":   {"name": "언데드",   "emoji": "💀", "desc": "흡혈과 끈질긴 생존", "bonus": {"power": 0.06, "heal": 0.15}},
    "dragonborn": {"name": "용인",   "emoji": "🐲", "desc": "용의 피를 이은 강대함", "bonus": {"power": 0.10, "defense": 0.10}},
    "fairy":    {"name": "페어리",   "emoji": "🧚", "desc": "행운과 채집의 축복", "bonus": {"gather": 0.25, "exp": 0.10, "dodge": 0.05}},
}


def rpg_race_bonus(player: dict, key: str) -> float:
    race = RPG_RACES.get(player.get("race") or "")
    if not race:
        return 0.0
    return race["bonus"].get(key, 0.0)


# ---------- 18번: 유기적 성장 (숙련도) ----------
# 특정 행동을 반복하면 그 분야 숙련도가 오르고, 숙련도가 능력치로 환원됩니다.
# mastery는 "종류:경험치" CSV로 저장. (예: "hunt:1200,boss:340")
RPG_MASTERY_KINDS = {
    "hunt":  {"name": "사냥 숙련", "emoji": "⚔️", "grants": "power"},
    "boss":  {"name": "보스 숙련", "emoji": "👑", "grants": "power"},
    "defense": {"name": "수련 숙련", "emoji": "🛡️", "grants": "defense"},
}
RPG_MASTERY_PER_LEVEL = 500       # 숙련 경험치 500당 숙련 1레벨
RPG_MASTERY_BONUS_PER_LEVEL = 0.01  # 숙련 1레벨당 +1%
RPG_MASTERY_MAX_LEVEL = 50


def rpg_parse_mastery(player: dict) -> dict:
    result = {}
    raw = player.get("mastery") or ""
    for part in raw.split(","):
        if ":" in part:
            k, _, v = part.partition(":")
            try:
                result[k.strip()] = int(v)
            except ValueError:
                pass
    return result


def rpg_mastery_level(exp: int) -> int:
    return min(RPG_MASTERY_MAX_LEVEL, exp // RPG_MASTERY_PER_LEVEL)


def rpg_mastery_bonus(player: dict, grant_key: str) -> float:
    """해당 능력치(power/defense)를 부여하는 모든 숙련의 합산 보너스."""
    masteries = rpg_parse_mastery(player)
    total = 0.0
    for kind, exp in masteries.items():
        info = RPG_MASTERY_KINDS.get(kind)
        if info and info["grants"] == grant_key:
            total += rpg_mastery_level(exp) * RPG_MASTERY_BONUS_PER_LEVEL
    return total


def rpg_add_mastery(guild_id: int, user_id: int, kind: str, amount: int):
    """숙련 경험치를 추가하고 저장합니다. 레벨업 시 (이전레벨, 새레벨) 반환, 아니면 None."""
    player = get_or_create_rpg_player(guild_id, user_id)
    masteries = rpg_parse_mastery(player)
    before = rpg_mastery_level(masteries.get(kind, 0))
    masteries[kind] = masteries.get(kind, 0) + amount
    after = rpg_mastery_level(masteries[kind])
    new_raw = ",".join(f"{k}:{v}" for k, v in masteries.items())
    save_rpg_player(guild_id, user_id, mastery=new_raw)
    if after > before:
        return (before, after, RPG_MASTERY_KINDS.get(kind, {}).get("name", kind))
    return None


# ---------- 19번: 스킬 레벨업 ----------
# 스킬 사용/전투로 스킬 숙련이 쌓이고, 스킬레벨이 오르면 피해 배율이 증가합니다.
# skill_levels는 "skill_id:레벨" CSV. 스킬레벨 1당 피해 +8%. 최대 10레벨.
RPG_SKILL_MAX_LEVEL = 10
RPG_SKILL_DMG_PER_LEVEL = 0.08


def rpg_parse_skill_levels(player: dict) -> dict:
    result = {}
    raw = player.get("skill_levels") or ""
    for part in raw.split(","):
        if ":" in part:
            k, _, v = part.partition(":")
            try:
                result[k.strip()] = int(v)
            except ValueError:
                pass
    return result


def rpg_skill_level(player: dict, skill_id: str) -> int:
    return rpg_parse_skill_levels(player).get(skill_id, 1)


def rpg_skill_level_mult(player: dict, skill_id: str) -> float:
    """스킬 레벨에 따른 추가 피해 배율 (레벨1=1.0)."""
    lv = rpg_skill_level(player, skill_id)
    return 1 + (lv - 1) * RPG_SKILL_DMG_PER_LEVEL


def rpg_add_skill_exp(guild_id: int, user_id: int, skill_id: str):
    """스킬을 쓸 때마다 레벨을 올려줍니다(간단화: 사용 3회당 1레벨). 레벨업 시 새 레벨 반환."""
    player = get_or_create_rpg_player(guild_id, user_id)
    levels = rpg_parse_skill_levels(player)
    # "__use_<id>" 히든 카운터로 사용횟수 관리
    use_key = f"_u_{skill_id}"
    uses = levels.get(use_key, 0) + 1
    levels[use_key] = uses
    cur_level = levels.get(skill_id, 1)
    leveled = None
    if uses % 3 == 0 and cur_level < RPG_SKILL_MAX_LEVEL:
        levels[skill_id] = cur_level + 1
        leveled = cur_level + 1
    new_raw = ",".join(f"{k}:{v}" for k, v in levels.items())
    save_rpg_player(guild_id, user_id, skill_levels=new_raw)
    return leveled


# ---------- 7번: 스킬트리 / 퍽 ----------
# 레벨업마다 퍽 포인트를 얻고, 퍽 트리에서 원하는 노드를 찍어 상시 보너스를 얻습니다.
# perks는 "perk_id,perk_id,..." CSV로 저장.
RPG_PERK_TREE = {
    # perk_id: (이름, 설명, 선행 perk(없으면 None), 보너스dict, 필요 포인트)
    "atk1":  ("💪 공격 숙련 I", "전투력 +5%", None, {"power": 0.05}, 1),
    "atk2":  ("💪 공격 숙련 II", "전투력 +10%", "atk1", {"power": 0.10}, 2),
    "atk3":  ("⚡ 광폭화", "전투력 +20%", "atk2", {"power": 0.20}, 3),
    "def1":  ("🛡️ 방어 숙련 I", "방어력 +8%", None, {"defense": 0.08}, 1),
    "def2":  ("🛡️ 방어 숙련 II", "방어력 +15%", "def1", {"defense": 0.15}, 2),
    "def3":  ("🏰 철벽", "방어력 +25%", "def2", {"defense": 0.25}, 3),
    "util1": ("🍀 행운", "경험치 +10%", None, {"exp": 0.10}, 1),
    "util2": ("💎 부의 감각", "골드 +15%", "util1", {"gold": 0.15}, 2),
    "hybrid":("🌟 만능", "전투력·방어력 +8%", "atk1", {"power": 0.08, "defense": 0.08}, 2),
}
RPG_PERK_POINTS_PER_LEVEL = 1  # 레벨업 1회당 퍽포인트 (일부 레벨에서만 지급하려면 조정)
RPG_PERK_POINT_LEVEL_INTERVAL = 5  # 5레벨마다 1퍽포인트


def rpg_parse_perks(player: dict) -> set:
    raw = player.get("perks") or ""
    return set(p for p in raw.split(",") if p)


def rpg_perk_bonus(player: dict, key: str) -> float:
    total = 0.0
    for pid in rpg_parse_perks(player):
        node = RPG_PERK_TREE.get(pid)
        if node:
            total += node[3].get(key, 0.0)
    return total


def rpg_can_take_perk(player: dict, perk_id: str) -> tuple:
    """(가능여부, 사유) 반환."""
    node = RPG_PERK_TREE.get(perk_id)
    if not node:
        return False, "존재하지 않는 퍽이에요."
    taken = rpg_parse_perks(player)
    if perk_id in taken:
        return False, "이미 습득한 퍽이에요."
    prereq = node[2]
    if prereq and prereq not in taken:
        return False, f"선행 퍽({RPG_PERK_TREE[prereq][0]})이 필요해요."
    if (player.get("perk_points") or 0) < node[4]:
        return False, f"퍽 포인트가 부족해요. (필요 {node[4]})"
    return True, ""


