def rpg_parse_professions(player: dict) -> dict:
    result = {}
    for part in (player.get("professions") or "").split(","):
        if ":" in part:
            k, _, v = part.partition(":")
            try:
                result[k.strip()] = int(v)
            except ValueError:
                pass
    return result


def rpg_prof_level(exp: int) -> int:
    return min(RPG_PROF_MAX_LEVEL, exp // RPG_PROF_EXP_PER_LEVEL)


def rpg_add_prof_exp(guild_id: int, user_id: int, prof: str, amount: int):
    player = get_or_create_rpg_player(guild_id, user_id)
    profs = rpg_parse_professions(player)
    before = rpg_prof_level(profs.get(prof, 0))
    profs[prof] = profs.get(prof, 0) + amount
    after = rpg_prof_level(profs[prof])
    save_rpg_player(guild_id, user_id, professions=",".join(f"{k}:{v}" for k, v in profs.items()))
    return (after > before), after


def rpg_gather_daily_left(player: dict) -> int:
    today = datetime.datetime.now().strftime("%Y-%m-%d")
    if player.get("gather_date") != today:
        return RPG_GATHER_DAILY_LIMIT
    return max(0, RPG_GATHER_DAILY_LIMIT - (player.get("gather_count") or 0))


