def rpg_get_discovered(player: dict) -> set:
    """이미 발견한 탐험지역 집합. (mastery 필드 재활용 대신 professions에 explore: 저장은 복잡 → 별도 파싱)"""
    raw = player.get("mastery") or ""
    discovered = set()
    for part in raw.split(","):
        if part.startswith("disc_"):
            discovered.add(part[5:].split(":")[0])
    return discovered


def rpg_mark_discovered(guild_id, user_id, zone_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    raw = player.get("mastery") or ""
    parts = [p for p in raw.split(",") if p]
    parts.append(f"disc_{zone_id}:1")
    save_rpg_player(guild_id, user_id, mastery=",".join(parts))


def rpg_current_env(player: dict) -> dict:
    loc = RPG_LOCATIONS.get(player.get("location") or "town", RPG_LOCATIONS["town"])
    return RPG_ENVIRONMENTS.get(loc["env"], RPG_ENVIRONMENTS["평온"])


def rpg_location_gather_bonus(player: dict, prof: str) -> float:
    """현재 지역이 해당 생산직에 주는 보너스."""
    loc = RPG_LOCATIONS.get(player.get("location") or "town", RPG_LOCATIONS["town"])
    if loc.get("gather_bonus") == prof:
        return 0.2
    return 0.0


