def rpg_get_tactic(player: dict) -> dict:
    """플레이어의 현재 전술 프리셋. 없으면 균형."""
    return RPG_TACTICS.get(player.get("tactic") or "balanced", RPG_TACTICS["balanced"])


def rpg_pop_food_buff(guild_id, user_id, player: dict) -> dict:
    """음식 버프(다음 전투 1회)를 소비합니다. {power: x, defense: y, name: 표시명} 배율 보너스를 돌려줘요."""
    raw = player.get("food_buff") or ""
    if not raw or ":" not in raw:
        return {}
    effect, _, val_str = raw.partition(":")
    try:
        value = float(val_str)
    except ValueError:
        value = 0.0
    save_rpg_player(guild_id, user_id, food_buff="")  # 1회 소비
    player["food_buff"] = ""
    if effect == "buff_power":
        return {"power": value, "name": "🍖 힘의 정식"}
    if effect == "buff_defense":
        return {"defense": value, "name": "🍱 광부의 도시락"}
    if effect == "buff_all":
        return {"power": value, "defense": value, "name": "🎉 진수성찬"}
    return {}


