# ============================================================
# 서버의 실제 시각(KST 기준)에 따라 시간대가 바뀌고,
# 시간대별로 몬스터 강함·보상·드랍률이 달라집니다.
RPG_TIME_PHASES = [
    # (시작시, 종료시(미포함), key, 이름, 몬스터배율, 보상배율, 드랍배율, 설명)
    (5,  10, "dawn",  "🌅 새벽",   0.95, 1.10, 1.10, "선선한 새벽. 몬스터가 약하고 보상·드랍이 늘어요."),
    (10, 17, "day",   "☀️ 낮",     1.00, 1.00, 1.00, "평범한 대낮. 표준 전투."),
    (17, 20, "dusk",  "🌇 황혼",   1.05, 1.05, 1.05, "해질녘. 조금 강한 대신 보상도 조금 더."),
    (20, 24, "night", "🌙 밤",     1.15, 1.15, 1.20, "위험한 밤. 몬스터가 강하지만 보상·드랍이 크게 늘어요."),
    (0,  5,  "midnight", "🌌 심야", 1.25, 1.25, 1.30, "가장 위험한 심야. 최고 난이도·최고 보상!"),
]


def rpg_current_time_phase() -> dict:
    """현재 KST 시각 기준 시간대 정보를 돌려줍니다."""
    try:
        now = datetime.datetime.now()  # 서버 로컬 시간 (배포 환경 KST 가정)
        hour = now.hour
    except Exception:
        hour = 12
    for start, end, key, name, mon_mult, reward_mult, drop_mult, desc in RPG_TIME_PHASES:
        if start <= hour < end:
            return {"key": key, "name": name, "monster_mult": mon_mult,
                    "reward_mult": reward_mult, "drop_mult": drop_mult, "desc": desc, "hour": hour}
    # 폴백 (낮)
    return {"key": "day", "name": "☀️ 낮", "monster_mult": 1.0,
            "reward_mult": 1.0, "drop_mult": 1.0, "desc": "표준 전투.", "hour": hour}


def rpg_parse_death_traits(player: dict) -> dict:
    result = {}
    for part in (player.get("death_traits") or "").split(","):
        if ":" in part:
            k, _, v = part.partition(":")
            try:
                result[k.strip()] = int(v)
            except ValueError:
                pass
    return result


def rpg_death_trait_bonus(player: dict, grant_key: str) -> float:
    """해당 능력치를 부여하는 죽음특성의 합산 보너스."""
    traits = rpg_parse_death_traits(player)
    total = 0.0
    for tid, level in traits.items():
        info = RPG_DEATH_TRAITS.get(tid)
        if info and info["grants"] == grant_key:
            total += min(level, info["max"]) * info["per"]
    return total


def rpg_record_death(guild_id, user_id, death_type: str) -> dict:
    """죽음을 기록하고 해당 특성을 1 올립니다. 획득한 특성 정보를 돌려줍니다."""
    info = RPG_DEATH_TRAITS.get(death_type)
    if not info:
        return None
    player = get_or_create_rpg_player(guild_id, user_id)
    traits = rpg_parse_death_traits(player)
    cur = traits.get(death_type, 0)
    if cur >= info["max"]:
        # 이미 최대치
        save_rpg_player(guild_id, user_id, last_death=death_type)
        return {"info": info, "level": cur, "maxed": True}
    traits[death_type] = cur + 1
    kwargs = {"death_traits": ",".join(f"{k}:{v}" for k, v in traits.items()), "last_death": death_type}
    # 장수 특성이면 수명(lifespan)도 증가
    if info["grants"] == "lifespan":
        kwargs["lifespan"] = (player.get("lifespan") or 0) + info["per"]
    save_rpg_player(guild_id, user_id, **kwargs)
    return {"info": info, "level": cur + 1, "maxed": False}


def rpg_build_sigabane_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    traits = rpg_parse_death_traits(player)
    lines = []
    for tid, info in RPG_DEATH_TRAITS.items():
        lv = traits.get(tid, 0)
        if info["grants"] in ("lifespan",):
            eff = f"수명 +{lv * info['per']}일"
        elif info["grants"] == "max_hp":
            eff = f"최대체력 +{int(lv * info['per'] * 100)}%"
        else:
            eff = f"+{int(lv * info['per'] * 100)}%"
        bar = "■" * lv + "□" * (info["max"] - lv)
        lines.append(f"{info['name']} Lv.{lv}/{info['max']} ({eff})\n└ {info['desc']} · {bar}")
    embed = discord.Embed(
        title="⚰️ 시가바네 — 죽음을 통한 성장",
        description=(
            f"죽음의 방식에 따라 다음 생에 영구 특성이 쌓여요.\n"
            f"현재 수명 보너스: **+{player.get('lifespan') or 0}일**\n\n"
            + "\n".join(lines)
        ),
        color=discord.Color.dark_grey(),
    )
    embed.set_footer(text="독사=독저항 · 노환=수명 · 포위사=공방 · 상식을 깨는 성장! | 만능 봇 RPG")
    return embed


