def rpg_evolution_title(player: dict) -> str:
    ev = min(len(RPG_EVOLUTION_TITLES) - 1, player.get("evolution") or 0)
    return RPG_EVOLUTION_TITLES[ev]


def rpg_dimension_gate_level(player: dict) -> int:
    """다음 차원 돌파가 필요한 레벨. (10의 배수마다 게이트)"""
    dim = player.get("dimension") or 0
    return (dim + 1) * RPG_DIMENSION_INTERVAL


def rpg_needs_dimension_break(player: dict) -> bool:
    """현재 레벨이 다음 게이트 이상인데 아직 돌파 안 했으면 True."""
    return player["level"] >= rpg_dimension_gate_level(player) and player["level"] < RPG_MAX_LEVEL


def rpg_dimension_passive_bonus(player: dict, stat_type: str) -> float:
    """차원 패시브 능력 곱셈 보너스 반환"""
    dim = player.get("dimension") or 0
    passive = RPG_DIMENSION_PASSIVES.get(dim, RPG_DIMENSION_PASSIVES[0])
    return passive.get(stat_type, 1.0)


def rpg_current_dimension_challenge(player: dict) -> dict:
    """현재 플레이어의 차원 돌파 도전 과제 반환"""
    dim = player.get("dimension") or 0
    return RPG_DIMENSION_CHALLENGES.get(dim, {})


def get_dimension_challenge_progress(guild_id: int, user_id: int, dimension_gate: int) -> dict:
    """차원 도전 진행 상황 조회"""
    try:
        c = get_db().cursor()
        c.execute(
            "SELECT challenge_type, progress, target, started_at, completed_at FROM rpg_dimension_challenges WHERE guild_id = ? AND user_id = ? AND dimension_gate = ?",
            (guild_id, user_id, dimension_gate)
        )
        row = c.fetchone()
        if row:
            return {
                "type": row[0],
                "progress": row[1],
                "target": row[2],
                "started_at": row[3],
                "completed_at": row[4],
            }
    except Exception:
        pass
    return None


def save_dimension_challenge_progress(guild_id: int, user_id: int, dimension_gate: int, challenge_type: str, progress: int, target: int):
    """차원 도전 진행 상황 저장"""
    try:
        c = get_db().cursor()
        import datetime
        now = datetime.datetime.now().isoformat()
        c.execute(
            """INSERT INTO rpg_dimension_challenges (guild_id, user_id, dimension_gate, challenge_type, progress, target, started_at)
               VALUES (?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(guild_id, user_id, dimension_gate) DO UPDATE SET progress=?, target=?""",
            (guild_id, user_id, dimension_gate, challenge_type, progress, target, now, progress, target)
        )
        get_db().commit()
    except Exception as e:
        print(f"[DB Error] save_dimension_challenge_progress: {e}")


def complete_dimension_challenge(guild_id: int, user_id: int, dimension_gate: int):
    """차원 도전 완료 처리"""
    try:
        c = get_db().cursor()
        import datetime
        now = datetime.datetime.now().isoformat()
        c.execute(
            "UPDATE rpg_dimension_challenges SET completed_at = ? WHERE guild_id = ? AND user_id = ? AND dimension_gate = ?",
            (now, guild_id, user_id, dimension_gate)
        )
        get_db().commit()
    except Exception as e:
        print(f"[DB Error] complete_dimension_challenge: {e}")


def unlock_evolution_skill(guild_id: int, user_id: int, evolution_level: int, skill_name: str):
    """진화 스킬 해금"""
    try:
        c = get_db().cursor()
        import datetime
        now = datetime.datetime.now().isoformat()
        c.execute(
            """INSERT OR IGNORE INTO rpg_evolution_skills (guild_id, user_id, evolution_level, skill_name, unlocked_at)
               VALUES (?, ?, ?, ?, ?)""",
            (guild_id, user_id, evolution_level, skill_name, now)
        )
        get_db().commit()
    except Exception as e:
        print(f"[DB Error] unlock_evolution_skill: {e}")


def get_player_unlocked_skills(guild_id: int, user_id: int) -> list:
    """플레이어가 해금한 스킬 목록"""
    try:
        c = get_db().cursor()
        c.execute(
            "SELECT evolution_level, skill_name FROM rpg_evolution_skills WHERE guild_id = ? AND user_id = ? ORDER BY evolution_level",
            (guild_id, user_id)
        )
        return [{"level": row[0], "name": row[1]} for row in c.fetchall()]
    except Exception:
        return []


# ---------- 3번: 전직 퀘스트 ----------
# 2·3차 전직 시 전직서만이 아니라 퀘스트(특정 조건)를 완료해야 합니다.
# jobquest 필드에 진행상황 "quest_id:진행도" 저장.
RPG_JOB_QUESTS = {
    2: {"id": "q_tier2", "name": "각성의 시련", "desc": "몬스터 30마리 처치", "target": 30, "type": "hunt"},
    3: {"id": "q_tier3", "name": "숙련의 증명", "desc": "보스 10회 처치", "target": 10, "type": "boss"},
    4: {"id": "q_tier4", "name": "초월의 관문", "desc": "던전 50층 도달", "target": 50, "type": "dungeon"},
    5: {"id": "q_tier5", "name": "극한의 수련", "desc": "레이드 5회 참여", "target": 5, "type": "raid"},
    6: {"id": "q_master", "name": "마스터의 길", "desc": "PvP 10승", "target": 10, "type": "pvp"},
}


def rpg_parse_jobquest(player: dict) -> dict:
    result = {}
    for part in (player.get("jobquest") or "").split(","):
        if ":" in part:
            k, _, v = part.partition(":")
            try:
                result[k.strip()] = int(v)
            except ValueError:
                pass
    return result


def rpg_jobquest_progress(player: dict, next_tier: int) -> tuple:
    """(현재 진행도, 목표, 완료여부)."""
    quest = RPG_JOB_QUESTS.get(next_tier)
    if not quest:
        return 0, 0, True  # 퀘스트 없으면 통과
    progress = rpg_parse_jobquest(player).get(quest["id"], 0)
    # 일부 퀘스트는 플레이어 통계로 자동 판정
    if quest["type"] == "dungeon":
        progress = max(progress, player.get("dungeon_floor") or 0)
    elif quest["type"] == "pvp":
        progress = max(progress, player.get("pvp_wins") or 0)
    return progress, quest["target"], progress >= quest["target"]


def rpg_add_jobquest_progress(guild_id, user_id, quest_type, amount=1):
    """해당 타입의 활성 전직퀘스트 진행도를 올립니다."""
    player = get_or_create_rpg_player(guild_id, user_id)
    quests = rpg_parse_jobquest(player)
    changed = False
    for tier, q in RPG_JOB_QUESTS.items():
        if q["type"] == quest_type:
            cur = quests.get(q["id"], 0)
            if cur < q["target"]:
                quests[q["id"]] = cur + amount
                changed = True
    if changed:
        save_rpg_player(guild_id, user_id, jobquest=",".join(f"{k}:{v}" for k, v in quests.items()))


def rpg_player_power(player: dict) -> int:
    base = 10 + player["weapon_level"] * 8
    if player.get("weapon_element"):
        base = int(base * (1 + RPG_ELEMENT_BONUS))
    base = int(base * rpg_rarity_tier(player.get("weapon_rarity", 0))["multiplier"])
    base += rpg_pet_power_bonus(player)
    relic_power, _relic_defense = rpg_relic_flat_bonus(player)
    acc_power, _acc_def = rpg_accessory_bonus(player)  # 장신구 보너스
    power_mult, _defense_mult = rpg_relic_set_bonus_multiplier(player)
    job = rpg_job_stats(player.get("job"))
    power_mult *= (1 + job["power_pct"])
    power_mult *= (1 + rpg_stat_bonus_pct(player, "stat_attack"))  # 공격력 스탯
    power_mult *= (1 + rpg_engrave_total(player, "opt_power") / 100)  # 세공 옵션
    power_mult *= (1 + rpg_race_bonus(player, "power"))    # 종족 특성
    power_mult *= (1 + rpg_perk_bonus(player, "power"))    # 퍽
    power_mult *= (1 + rpg_mastery_bonus(player, "power")) # 유기적 성장(숙련도)
    power_mult *= (1 + rpg_rebirth_bonus(player))          # 환생 보너스
    power_mult *= (1 + rpg_death_trait_bonus(player, "power_defense"))  # 시가바네: 백병의 투혼
    power_mult *= rpg_dimension_passive_bonus(player, "power")  # 차원 패시브
    power_mult *= (1 + rpg_pet_buff(player, "power"))      # 펫 버프: 공격력
    power_mult *= (1 + (player.get("_guild_power_buff", 0.0) or 0.0))  # 길드 버프: 공격력
    cw_power, _cw_def, _cw_crit = rpg_custom_weapon_bonus(player)  # 🛠️ 커스텀 무기
    return int((base + relic_power + acc_power + cw_power) * power_mult)


def rpg_player_defense(player: dict) -> int:
    base = player.get("armor_level", 0) * 3
    base = int(base * rpg_rarity_tier(player.get("armor_rarity", 0))["multiplier"])
    _relic_power, relic_defense = rpg_relic_flat_bonus(player)
    _acc_power, acc_def = rpg_accessory_bonus(player)  # 장신구 보너스
    _power_mult, defense_mult = rpg_relic_set_bonus_multiplier(player)
    job = rpg_job_stats(player.get("job"))
    defense_mult *= (1 + job["defense_pct"])
    defense_mult *= (1 + rpg_engrave_total(player, "opt_defense") / 100)  # 세공 옵션
    defense_mult *= (1 + rpg_race_bonus(player, "defense"))    # 종족 특성
    defense_mult *= (1 + rpg_perk_bonus(player, "defense"))    # 퍽
    defense_mult *= (1 + rpg_mastery_bonus(player, "defense")) # 유기적 성장
    defense_mult *= (1 + rpg_rebirth_bonus(player))            # 환생 보너스
    defense_mult *= (1 + rpg_death_trait_bonus(player, "power_defense"))  # 시가바네: 백병의 투혼
    defense_mult *= rpg_dimension_passive_bonus(player, "defense")  # 차원 패시브
    defense_mult *= (1 + rpg_pet_buff(player, "defense"))      # 펫 버프: 방어력
    defense_mult *= (1 + (player.get("_guild_defense_buff", 0.0) or 0.0))  # 길드 버프: 방어력
    _cw_pow, cw_def, _cw_crit = rpg_custom_weapon_bonus(player)  # 🛠️ 커스텀 무기
    return int((base + relic_defense + acc_def + cw_def) * defense_mult)


def rpg_pick_monster(player_level: int, location: str = None) -> dict:
    eligible = [m for m in RPG_MONSTERS if m["min_level"] <= player_level] or [RPG_MONSTERS[0]]
    if location and location in RPG_LOCATION_MONSTERS:
        # 지역 지정 시: 그 지역의 몬스터 중 레벨 조건 맞는 것 우선 (없으면 지역 전체)
        loc_names = RPG_LOCATION_MONSTERS[location]
        loc_pool = [m for m in eligible if m["name"] in loc_names] or [m for m in RPG_MONSTERS if m["name"] in loc_names] or eligible
        return random.choice(loc_pool)
    return random.choice(eligible)


def rpg_pick_boss(player_level: int, location: str = None) -> dict:
    eligible = [b for b in RPG_BOSSES if b["min_level"] <= player_level] or [RPG_BOSSES[0]]
    if location and location in RPG_LOCATION_BOSSES:
        loc_names = RPG_LOCATION_BOSSES[location]
        loc_pool = [b for b in eligible if b["name"] in loc_names] or [b for b in RPG_BOSSES if b["name"] in loc_names] or eligible
        return random.choice(loc_pool)
    return random.choice(eligible)


def rpg_simulate_battle(player: dict, monster: dict, skill=None):
    """간단한 자동 전투 시뮬레이션입니다. (플레이어 HP, 몬스터 HP, 승리 여부, 로그, 받은 피해)를 돌려줍니다.

    무기 레벨/속성이 공격력에, 방어구 레벨이 방어력(피해 감소)에 반영되고,
    플레이어 공격은 기본 15% 확률로 크리티컬(1.5배 피해)이 터집니다.
    직업 스킬(추가타/반격/자힐/크리 보너스)과 스탯(마력=스킬피해, 민첩=회피,
    MP회복량=스킬 발동확률, HP회복량=자힐량)이 자동으로 함께 반영됩니다.
    """
    player_power = rpg_player_power(player)
    defense = rpg_player_defense(player)
    job = rpg_job_stats(player.get("job"))
    skill_dmg_mult = 1 + rpg_stat_bonus_pct(player, "stat_magic") + rpg_engrave_total(player, "opt_skill_dmg") / 100  # 마력+세공: 스킬 피해
    proc_mult = 1 + rpg_stat_bonus_pct(player, "stat_mp_regen")          # MP회복량: 스킬 발동확률 증가
    dodge_chance = rpg_dodge_chance(player)                              # 민첩+세공: 회피
    heal_mult = rpg_heal_multiplier(player)                              # HP회복량+세공: 자힐 증가
    dmg_reduce = min(0.6, rpg_engrave_total(player, "opt_dmg_reduce") / 100)  # 세공: 받는 피해 감소
    crit_chance = 0.15 + job["crit_chance_bonus"] + rpg_engrave_total(player, "opt_crit_chance") / 100
    crit_chance += rpg_luck_crit_bonus(player)   # 6번: 럭 스탯 크리 확률 보너스
    crit_chance += rpg_pet_buff(player, "crit")  # 펫 버프: 크리 확률
    crit_chance += rpg_custom_weapon_bonus(player)[2]  # 🛠️ 커스텀 무기 보석 크리
    crit_mult = 1.5 + job["crit_mult_bonus"] + rpg_engrave_total(player, "opt_crit_dmg") / 100
    extra_attack_chance = min(0.9, job["extra_attack_chance"] * proc_mult)
    reflect_chance = min(0.9, job["reflect_chance"] * proc_mult)
    heal_chance = min(0.9, job["heal_chance"] * proc_mult)
    first_strike_chance = min(0.9, job.get("first_strike_chance", 0.0) * proc_mult)  # 도적: 선공
    skill_crit_on = rpg_skill_crit_enabled(player)  # 6번: MP회복 100↑이면 스킬(추가타)도 크리

    # 14번: 전술(갬빗) 프리셋 보정 적용
    tactic = rpg_get_tactic(player)
    tactic_atk = tactic["atk_mult"]
    tactic_taken = tactic["taken_mult"]
    crit_chance = min(0.95, crit_chance + tactic["crit_add"])
    dodge_chance = min(0.75, dodge_chance + tactic["dodge_add"])
    heal_mult *= tactic["heal_mult"]

    # 광전사 특수 규칙: 체력 10 고정, 부활 3회, 10턴 후 확정 사망
    is_berserker = (rpg_resolve_job_line(job.get("job_id")) or {}).get("special") == "berserker"
    berserker_revives = 3 if is_berserker else 0
    berserker_turn_limit = 10 if is_berserker else None
    # 광전사 너프: 극단적 생존력(체력10·부활3) 대신 주는 피해를 크게 낮춰 밸런스 조정
    berserker_dmg_mult = 0.55 if is_berserker else 1.0

    player_hp = 10 if is_berserker else player["hp"]
    max_hp = 10 if is_berserker else player.get("max_hp", player_hp)
    monster_hp = monster["hp"]
    log = []
    rounds = 0

    # 🗡️ 도적 선공: 전투 시작 시 확률로 무료 선제공격 1회
    if first_strike_chance and random.random() < first_strike_chance:
        fs_dmg = max(1, int(player_power * random.uniform(1.0, 1.4)))
        monster_hp -= fs_dmg
        log.append(f"🗡️선공! {monster['emoji']} {monster['name']}에게 선제공격 **{fs_dmg}** 피해")

    max_rounds = berserker_turn_limit if berserker_turn_limit else 12
    while player_hp > 0 and monster_hp > 0 and rounds < max_rounds:
        rounds += 1
        is_crit = random.random() < crit_chance
        dmg_to_monster = max(1, int(player_power * random.uniform(0.8, 1.2)))
        if is_crit:
            dmg_to_monster = int(dmg_to_monster * crit_mult)
        crit_text = " 💥크리티컬!" if is_crit else ""
        skill_text = ""
        if skill and rounds == 1:  # 스킬은 전투 첫 타에 발동
            dmg_to_monster = int(dmg_to_monster * skill["mult"])
            skill_text = f" {skill['name']}!"
        extra_text = ""
        if extra_attack_chance and random.random() < extra_attack_chance:
            extra_dmg = max(1, int(player_power * job["extra_attack_pct"] * skill_dmg_mult))
            # 6번: MP회복 100↑이면 추가타(스킬)에도 크리 적용
            if skill_crit_on and random.random() < crit_chance:
                extra_dmg = int(extra_dmg * crit_mult)
                extra_text = f" 🔮추가타+{extra_dmg}💥"
            else:
                extra_text = f" 🔮추가타+{extra_dmg}"
            dmg_to_monster += extra_dmg
        # 14번: 전술 공격 배율
        if tactic_atk != 1.0:
            dmg_to_monster = max(1, int(dmg_to_monster * tactic_atk))
        # 광전사 너프: 주는 피해 감소
        if berserker_dmg_mult != 1.0:
            dmg_to_monster = max(1, int(dmg_to_monster * berserker_dmg_mult))
        monster_hp -= dmg_to_monster
        if monster_hp <= 0:
            log.append(f"{rounds}R｜{monster['emoji']} {monster['name']}에게 **{dmg_to_monster}** 피해{crit_text}{skill_text}{extra_text} → 처치!")
            break
        # 민첩 스탯 기반 회피
        if dodge_chance and random.random() < dodge_chance:
            log.append(f"{rounds}R｜{monster['emoji']} {monster['name']}에게 **{dmg_to_monster}** 피해{crit_text}{skill_text}{extra_text} / 💨 공격을 회피했다!")
            continue
        raw_dmg_to_player = max(1, int(monster["power"] * random.uniform(0.8, 1.2)))
        dmg_to_player = max(1, raw_dmg_to_player - defense)
        if dmg_reduce:
            dmg_to_player = max(1, int(dmg_to_player * (1 - dmg_reduce)))  # 세공: 받는 피해 감소
        # 14번: 전술 받는 피해 배율
        if tactic_taken != 1.0:
            dmg_to_player = max(1, int(dmg_to_player * tactic_taken))
        defense_text = f" (방어 -{min(defense, raw_dmg_to_player - 1)})" if defense > 0 else ""
        reflect_text = ""
        if reflect_chance and random.random() < reflect_chance:
            reflect_dmg = max(1, int(dmg_to_player * job["reflect_pct"] * skill_dmg_mult))
            # 6번: MP회복 100↑이면 반격(스킬)에도 크리 적용
            if skill_crit_on and random.random() < crit_chance:
                reflect_dmg = int(reflect_dmg * crit_mult)
                reflect_text = f" 🔁반격 {reflect_dmg}💥"
            else:
                reflect_text = f" 🔁반격 {reflect_dmg}"
            monster_hp -= reflect_dmg
        player_hp -= dmg_to_player
        heal_text = ""
        # 광전사 부활: 체력이 0 이하가 되면 부활권 소모하고 체력 10으로 부활 (최대 3회)
        if is_berserker and player_hp <= 0 and berserker_revives > 0:
            berserker_revives -= 1
            player_hp = 10
            heal_text = f" ☠️부활! (남은 부활 {berserker_revives}회)"
        elif heal_chance and player_hp > 0 and random.random() < heal_chance:
            heal_amt = max(1, int(max_hp * job["heal_pct"] * heal_mult))
            before_hp = player_hp
            player_hp = min(max_hp, player_hp + heal_amt)
            if player_hp > before_hp:
                heal_text = f" ✨자힐 +{player_hp - before_hp}"
        log.append(f"{rounds}R｜{monster['emoji']} {monster['name']}에게 **{dmg_to_monster}** 피해{crit_text}{skill_text}{extra_text} / 나는 **{dmg_to_player}** 피해 받음{defense_text}{reflect_text}{heal_text}")

    # 광전사: 10턴 내에 못 이기면 확정 사망
    if is_berserker and monster_hp > 0 and rounds >= (berserker_turn_limit or 10):
        player_hp = 0
        log.append(f"☠️ 광전사의 광기가 다했다... 10턴이 지나 확정 사망!")
    won = monster_hp <= 0 and player_hp > 0
    player_hp = max(0, player_hp)
    if is_berserker:
        # 광전사는 별도의 10HP 상태로 싸우므로, 실제 체력에는 승리 시 영향 없음/패배 시 전멸 처리
        if won:
            real_hp = player["hp"]  # 승리하면 실제 체력 유지
            damage_taken = 0
        else:
            real_hp = 0  # 패배(사망)하면 실제 체력 0
            damage_taken = player["hp"]
        return real_hp, max(0, monster_hp), won, log, damage_taken
    damage_taken = player["hp"] - player_hp
    return player_hp, max(0, monster_hp), won, log, damage_taken


def rpg_apply_exp(player: dict, exp_gain: int):
    """경험치를 더하고 레벨업 처리를 합니다. (레벨업 목록, player)를 돌려줍니다.
    - 지력 스탯에 따라 획득 경험치가 증가합니다.
    - 레벨업 1회당 스탯 포인트 +3 (stat_points)
    - 최대 레벨은 255이며, 도달하면 경험치가 더 쌓이지 않습니다."""
    exp_gain = int(exp_gain * rpg_exp_multiplier(player))
    level = player["level"]
    exp = player["exp"] + exp_gain
    max_hp = player["max_hp"]
    level_ups = []
    while level < RPG_MAX_LEVEL and exp >= rpg_exp_needed(level):
        exp -= rpg_exp_needed(level)
        level += 1
        max_hp += 10
        level_ups.append(level)
    if level >= RPG_MAX_LEVEL:
        level = RPG_MAX_LEVEL
        exp = 0  # 만렙 도달 시 경험치 고정
    player["level"] = level
    player["exp"] = exp
    player["max_hp"] = max_hp
    if level_ups:
        player["hp"] = max_hp  # 레벨업 시 체력 전부 회복
        player["stat_points"] = player.get("stat_points", 0) + RPG_STAT_POINTS_PER_LEVEL * len(level_ups)
        # 퍽 포인트: 5레벨 단위를 넘을 때마다 1개 지급
        perk_gained = sum(1 for lv in level_ups if lv % RPG_PERK_POINT_LEVEL_INTERVAL == 0)
        if perk_gained:
            player["perk_points"] = (player.get("perk_points") or 0) + perk_gained
    return level_ups, player


def rpg_pet_tier_weight(entry: dict) -> float:
    """가챠 추첨용 등급 가중치. per_pet_rate면 (개당 확률 × 펫 수)가 등급 전체 확률입니다."""
    if entry.get("per_pet_rate"):
        return entry["rate"] * len(entry["pets"])
    return entry["rate"]


def rpg_roll_pet() -> tuple:
    """가챠 확률에 따라 등급을 먼저 뽑고, 그 등급 안에서 펫 하나를 무작위로 정합니다. (펫이름, 등급인덱스, 전투력보너스)를 돌려줍니다."""
    roll = random.random()
    cumulative = 0.0
    for entry in RPG_PET_POOL:
        cumulative += rpg_pet_tier_weight(entry)
        if roll <= cumulative:
            pet_name = random.choice(entry["pets"])
            return pet_name, entry["rarity_index"], entry["power_bonus"]
    # 어느 등급에도 안 걸리면(대부분의 확률) 최하위 등급으로 처리
    base = RPG_PET_POOL[0]
    pet_name = random.choice(base["pets"])
    return pet_name, base["rarity_index"], base["power_bonus"]


def rpg_get_pets(guild_id: int, user_id: int):
    with DB_MUTEX:
        c.execute(
            "SELECT pet_name, rarity_index, count FROM rpg_pets WHERE guild_id=? AND user_id=? ORDER BY rarity_index DESC, pet_name ASC",
            (guild_id, user_id),
        )
        return c.fetchall()


def rpg_add_pet(guild_id: int, user_id: int, pet_name: str, rarity_index: int):
    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with DB_MUTEX:
        c.execute(
            "SELECT count FROM rpg_pets WHERE guild_id=? AND user_id=? AND pet_name=?",
            (guild_id, user_id, pet_name),
        )
        row = c.fetchone()
        if row:
            c.execute(
                "UPDATE rpg_pets SET count=count+1 WHERE guild_id=? AND user_id=? AND pet_name=?",
                (guild_id, user_id, pet_name),
            )
        else:
            c.execute(
                "INSERT INTO rpg_pets (guild_id, user_id, pet_name, rarity_index, count, obtained_at) VALUES (?, ?, ?, ?, 1, ?)",
                (guild_id, user_id, pet_name, rarity_index, now),
            )
        conn.commit()


def rpg_owns_pet(guild_id: int, user_id: int, pet_name: str) -> bool:
    with DB_MUTEX:
        c.execute(
            "SELECT 1 FROM rpg_pets WHERE guild_id=? AND user_id=? AND pet_name=?",
            (guild_id, user_id, pet_name),
        )
        return c.fetchone() is not None


# ===== 펫 합성 — 같은 희귀도 펫 2종을 소모해 상위 희귀도 펫 도전 =====
# 각성(같은 펫 5마리→진화)과 겹치지 않는 별도 시스템. 서로 다른 펫 2종을 재료로 씁니다.
RPG_PET_FUSION_SUCCESS = 0.6   # 상위 희귀도 성공 확률 (실패 시 같은 희귀도 펫 획득)
RPG_PET_FUSION_MAX_RARITY = 5  # 합성으로 도달 가능한 최대 희귀도 (사신수 6은 제외)


def rpg_pet_rarity_pool(rarity_index: int):
    for entry in RPG_PET_POOL:
        if entry["rarity_index"] == rarity_index:
            return entry["pets"]
    return []


def rpg_pet_consume_one(guild_id: int, user_id: int, pet_name: str) -> bool:
    """펫 1마리 소모 (count-1, 0이면 삭제). 성공 여부 반환."""
    with DB_MUTEX:
        c.execute("SELECT count FROM rpg_pets WHERE guild_id=? AND user_id=? AND pet_name=?", (guild_id, user_id, pet_name))
        row = c.fetchone()
        if not row or int(row[0] or 0) < 1:
            return False
        if int(row[0]) <= 1:
            c.execute("DELETE FROM rpg_pets WHERE guild_id=? AND user_id=? AND pet_name=?", (guild_id, user_id, pet_name))
        else:
            c.execute("UPDATE rpg_pets SET count=count-1 WHERE guild_id=? AND user_id=? AND pet_name=?", (guild_id, user_id, pet_name))
        conn.commit()
        return True


def rpg_pet_fusion(guild_id: int, user_id: int, pet_a: str, pet_b: str) -> dict:
    """같은 희귀도 펫 2종을 합성해 상위(또는 실패 시 동급) 펫을 획득."""
    if pet_a == pet_b:
        return {"ok": False, "msg": "서로 다른 두 펫을 골라주세요. (같은 펫 여러 마리는 각성으로 진화시켜요)"}
    pets = {name: (rarity, count) for name, rarity, count in rpg_get_pets(guild_id, user_id)}
    if pet_a not in pets or pet_b not in pets:
        return {"ok": False, "msg": "보유하지 않은 펫이 포함돼 있어요."}
    ra, ca = pets[pet_a]
    rb, cb = pets[pet_b]
    if ra != rb:
        return {"ok": False, "msg": "같은 희귀도의 펫 2종만 합성할 수 있어요."}
    if ra >= RPG_PET_FUSION_MAX_RARITY:
        return {"ok": False, "msg": "최고 희귀도 펫은 합성 재료로 쓸 수 없어요."}
    if ca < 1 or cb < 1:
        return {"ok": False, "msg": "재료 펫이 부족해요."}

    # 재료 소모
    if not rpg_pet_consume_one(guild_id, user_id, pet_a) or not rpg_pet_consume_one(guild_id, user_id, pet_b):
        return {"ok": False, "msg": "재료 소모 중 문제가 생겼어요. 다시 시도해주세요."}

    success = random.random() < RPG_PET_FUSION_SUCCESS
    result_rarity = ra + 1 if success else ra
    pool = rpg_pet_rarity_pool(result_rarity) or rpg_pet_rarity_pool(ra)
    new_pet = random.choice(pool)
    rpg_add_pet(guild_id, user_id, new_pet, result_rarity)
    return {"ok": True, "success": success, "pet": new_pet, "rarity": result_rarity}


RPG_PET_AWAKEN_COST = 5           # 각성 1회에 필요한 중복 펫 수
RPG_PET_MAX_AWAKEN = 5            # 펫 각성 최대 단계


def rpg_pet_awaken_targets(guild_id: int, user_id: int) -> list:
    """각성 가능한(중복 5마리 이상 보유) 펫 목록을 돌려줍니다.
    반환: [{name, rarity_index, count, evolution, can}, ...]"""
    player = get_or_create_rpg_player(guild_id, user_id)
    result = []
    for pet_name, rarity_index, count in rpg_get_pets(guild_id, user_id):
        st = rpg_get_pet_state(player, pet_name)
        evo = st["evolution"]
        can = count >= RPG_PET_AWAKEN_COST and evo < RPG_PET_MAX_AWAKEN
        result.append({
            "name": pet_name, "rarity_index": rarity_index, "count": count,
            "evolution": evo, "can": can,
        })
    return result


def rpg_awaken_pet(guild_id: int, user_id: int, pet_name: str) -> dict:
    """중복 펫 5마리를 소비해 해당 펫을 1단계 각성시킵니다."""
    player = get_or_create_rpg_player(guild_id, user_id)
    with DB_MUTEX:
        c.execute("SELECT count FROM rpg_pets WHERE guild_id=? AND user_id=? AND pet_name=?",
                  (guild_id, user_id, pet_name))
        row = c.fetchone()
    if not row:
        return {"error": "그 펫을 보유하고 있지 않아요."}
    count = row[0]
    st = rpg_get_pet_state(player, pet_name)
    if st["evolution"] >= RPG_PET_MAX_AWAKEN:
        return {"error": f"이미 최대 각성(★{RPG_PET_MAX_AWAKEN}) 단계예요."}
    if count < RPG_PET_AWAKEN_COST:
        return {"error": f"각성하려면 같은 펫이 {RPG_PET_AWAKEN_COST}마리 필요해요. (현재 {count}마리)"}
    # 중복 5마리 소비
    with DB_MUTEX:
        c.execute("UPDATE rpg_pets SET count=count-? WHERE guild_id=? AND user_id=? AND pet_name=?",
                  (RPG_PET_AWAKEN_COST, guild_id, user_id, pet_name))
        conn.commit()
    # evolution +1
    st["evolution"] = st["evolution"] + 1
    rpg_save_pet_state(guild_id, user_id, pet_name, st)
    return {
        "ok": True, "name": pet_name, "evolution": st["evolution"],
        "remaining": count - RPG_PET_AWAKEN_COST,
        "power_up_pct": int(0.5 * st["evolution"] * 100),
    }


def rpg_build_pet_awaken_embed(guild_id, user_id) -> discord.Embed:
    targets = rpg_pet_awaken_targets(guild_id, user_id)
    star = lambda n: "★" * n + "☆" * (RPG_PET_MAX_AWAKEN - n)
    if not targets:
        desc = "보유한 펫이 없어요. `/rpg 뽑기 종류:펫`으로 펫을 모아보세요!"
    else:
        lines = []
        for t in targets:
            ready = "  ✅각성가능" if t["can"] else (
                "  (최대각성)" if t["evolution"] >= RPG_PET_MAX_AWAKEN else f"  ({t['count']}/{RPG_PET_AWAKEN_COST}마리)"
            )
            lines.append(f"{t['name']} {star(t['evolution'])} · 보유 {t['count']}마리{ready}")
        desc = (
            f"같은 펫을 **{RPG_PET_AWAKEN_COST}마리** 모을 때마다 1단계 각성할 수 있어요.\n"
            f"각성 1단계당 펫 전투력 **+50%** (최대 ★{RPG_PET_MAX_AWAKEN}단계)\n\n"
            + "\n".join(lines[:20])
        )
    embed = discord.Embed(title="🐾 펫 각성", description=desc, color=discord.Color.magenta())
    embed.set_footer(text="아래 메뉴에서 펫을 골라 각성하세요 | 만능 봇 RPG")
    return embed


class RPGPetAwakenSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        targets = [t for t in rpg_pet_awaken_targets(guild_id, user_id) if t["can"]][:25]
        options = []
        for t in targets:
            options.append(discord.SelectOption(
                label=t["name"][:100],
                description=f"보유 {t['count']}마리 → 5마리 소비, ★{t['evolution']}→★{t['evolution']+1}"[:100],
                value=t["name"],
                emoji="🐾",
            ))
        if not options:
            options.append(discord.SelectOption(label="각성 가능한 펫이 없어요", value="__none__"))
        super().__init__(placeholder="각성할 펫 선택 (같은 펫 5마리 필요)", min_values=1, max_values=1, options=options)

    async def callback(self, interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        res = rpg_awaken_pet(self.guild_id, self.user_id, self.values[0])
        if "error" in res:
            return await interaction.response.send_message(f"❌ {res['error']}", ephemeral=True)
        note = (
            f"🎉 **{res['name']}** 각성 성공! ★{res['evolution']}단계 달성!\n"
            f"⚔️ 펫 전투력 +{res['power_up_pct']}% · 남은 보유 {res['remaining']}마리"
        )
        embed = rpg_build_pet_awaken_embed(self.guild_id, self.user_id)
        embed.description = note + "\n\n" + (embed.description or "")
        await interaction.response.edit_message(embed=embed, view=RPGPetAwakenView(self.guild_id, self.user_id))


class RPGPetAwakenView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=180)
        self.guild_id = guild_id
        self.user_id = user_id
        self.add_item(RPGPetAwakenSelect(guild_id, user_id))

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True


