# @app_commands.describe(칭호="원하는 칭호 예: 귀요미, 서버요정, 전설의냥이")
async def use_title_ticket(interaction: discord.Interaction, 칭호: str):
    if await reject_if_not_bot_manager(interaction):
        return
    if interaction.guild is None or not isinstance(interaction.user, discord.Member):
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    title = safe_role_text(칭호, max_len=20)
    if len(title) < 1:
        return await safe_interaction_send(interaction, "❌ 사용할 수 없는 칭호입니다.", ephemeral=True)

    if get_inventory_amount(interaction.user.id, "칭호권") < 1:
        return await safe_interaction_send(interaction, "❌ 인벤토리에 `칭호권`이 없습니다. `/rpg 상점`에서 구매해주세요.", ephemeral=True)

    if not consume_inventory_item(interaction.user.id, "칭호권", 1):
        return await safe_interaction_send(interaction, "❌ 아이템 사용 중 오류가 발생했습니다.", ephemeral=True)

    role_name = f"🏷️ {title}"
    try:
        role = await get_or_create_simple_role(
            interaction.guild,
            role_name[:100],
            color=discord.Color.random(),
            hoist=False,
            mentionable=True,
        )
        await interaction.user.add_roles(role, reason="칭호권 사용")
        # /칭호 통합 패널에서도 바로 보이도록 DB 칭호 목록에도 저장하고 대표 칭호로 장착합니다.
        try:
            add_user_title(interaction.guild.id, interaction.user.id, title)
            equip_user_title(interaction.guild.id, interaction.user.id, title)
        except Exception:
            pass
    except discord.Forbidden:
        return await safe_interaction_send(interaction, "❌ 봇 역할 위치 또는 권한이 부족해서 칭호 역할을 줄 수 없습니다.", ephemeral=True)
    except discord.HTTPException as e:
        return await safe_interaction_send(interaction, f"❌ 칭호 생성 실패: `{e}`", ephemeral=True)

    await safe_interaction_send(interaction, f"✅ 칭호 {role.mention} 를 지급하고 `/칭호` 대표 칭호로 장착했습니다!", ephemeral=True)


