class TicketOpenButton(discord.ui.Button):
    """티켓 종류 하나에 대응하는 동적 버튼."""
    def __init__(self, ticket_type: dict):
        style = TICKET_BUTTON_STYLES.get(ticket_type.get("button_style", "green"), discord.ButtonStyle.green)
        super().__init__(
            label=ticket_type.get("label", "문의")[:80],
            emoji=ticket_type.get("emoji") or None,
            style=style,
            custom_id=f"ticket_open:{ticket_type['type_key']}",
        )
        self.type_key = ticket_type["type_key"]

    async def callback(self, interaction: discord.Interaction):
        guild = interaction.guild
        if guild is None:
            return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
        t = get_ticket_type(guild.id, self.type_key)
        if t is None:
            return await safe_interaction_send(interaction, "❌ 이 문의 종류가 삭제되었어요. 관리자에게 패널 재전송을 요청해주세요.", ephemeral=True)
        await UnifiedTicketView.create_ticket_for_type(interaction, t)


class UnifiedTicketView(discord.ui.View):
    def __init__(self, guild_id: int = None):
        super().__init__(timeout=None)
        # guild_id가 주어지면 그 서버의 커스텀 종류로 버튼을 구성합니다.
        # persistent 등록(빈 guild_id) 시에는 기본 3종 custom_id로 등록해둡니다.
        types = get_ticket_types(guild_id) if guild_id else [dict(t) for t in DEFAULT_TICKET_TYPES]
        for t in types[:25]:
            self.add_item(TicketOpenButton(t))

    @staticmethod
    async def create_ticket_for_type(interaction: discord.Interaction, t: dict):
        guild = interaction.guild
        user = interaction.user
        ticket_type = t["label"]
        emoji = t.get("emoji") or "🎫"

        # 카테고리: 서버 지정 → 기존 상수 → 이름 매칭 → 새로 생성
        category = resolve_ticket_category(guild)
        if category is None and TICKET_CATEGORY_ID:
            category = guild.get_channel(TICKET_CATEGORY_ID)
        if category is None:
            category = mnb_find_category_loose(guild, "🎫 티켓")
        if category is None:
            try:
                category = await guild.create_category("🎫 티켓")
            except discord.Forbidden:
                category = None

        # 담당 역할: 서버 지정 → 이름 매칭 → 관리자 권한 역할 자동 폴백
        staff_role = resolve_ticket_staff_role(guild)
        if staff_role is None:
            staff_role = next(
                (r for r in guild.roles if not r.is_default() and not r.managed and r.permissions.administrator),
                None,
            )
        # 그래도 없으면 역할 없이 진행 (생성자+봇+관리자 권한 보유자만 접근)

        channel_name = f"{t['type_key']}-{user.id}".lower().replace(" ", "-")
        existing = discord.utils.get(guild.text_channels, name=channel_name)
        if existing:
            return await safe_interaction_send(interaction, f"이미 열린 티켓이 있어요: {existing.mention}", ephemeral=True)
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            user: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
            guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True, manage_channels=True),
        }
        if staff_role is not None:
            overwrites[staff_role] = discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True, manage_channels=True)
        try:
            channel = await guild.create_text_channel(name=channel_name, category=category, overwrites=overwrites, topic=f"{ticket_type} 티켓 | 생성자: {user.id}", reason=f"{user} {ticket_type} 티켓 생성")
        except discord.Forbidden:
            return await safe_interaction_send(interaction, "❌ 채널을 만들 권한이 없어요. 봇에게 '채널 관리' 권한을 주세요.", ephemeral=True)
        intro_title = t.get("intro_title") or f"{emoji} {ticket_type} 티켓"
        intro_desc = t.get("intro_description") or f"{user.mention}님, 내용을 자세히 적어주세요.\n\n관리자가 확인 후 답변드릴게요."
        try:
            intro_desc = render_auto_embed_text(intro_desc, guild)
        except Exception:
            pass
        embed = create_embed(intro_title, intro_desc[:4096])
        mention = f"{user.mention} {staff_role.mention}" if staff_role is not None else user.mention
        await channel.send(content=mention, embed=embed, view=TicketControlView())
        await send_ticket_log(guild, f"{emoji} `{ticket_type}` 티켓 생성: {channel.mention} / 생성자: {user.mention}")
        await safe_interaction_send(interaction, f"{emoji} 티켓이 생성되었어요: {channel.mention}", ephemeral=True)


# Slash command disabled to stay under Discord's 100-command global limit. Use /패널 instead.
async def ticket_panel(interaction: discord.Interaction):
    if not interaction.user.guild_permissions.administrator:
        return await safe_interaction_send(interaction, "❌ 관리자만 사용할 수 있어요.", ephemeral=True)
    embed = build_ticket_panel_embed(interaction.guild)
    await safe_interaction_send(interaction, embed=embed, view=UnifiedTicketView(interaction.guild.id))


def register_all_guild_ticket_views_once():
    """저장된 커스텀 티켓 종류가 있는 모든 서버의 뷰를 persistent 등록합니다.
    기본 3종과 custom_id가 겹치는 종류는 이미 기본 뷰가 처리하므로 중복돼도 무해합니다."""
    try:
        with DB_MUTEX:
            guild_ids = [r[0] for r in c.execute("SELECT DISTINCT guild_id FROM ticket_types").fetchall()]
    except Exception:
        guild_ids = []
    for gid in guild_ids:
        try:
            bot.add_view(UnifiedTicketView(gid))
        except Exception:
            pass


