# 티켓툴 스타일 관리 GUI (/서버 티켓관리)
# =========================

import unicodedata as _mnb_unicodedata


def _slugify_ticket_key(label: str) -> str:
    """라벨에서 안전한 type_key를 만듭니다. custom_id/채널명에 쓰이므로 소문자 영숫자만."""
    base = _mnb_unicodedata.normalize("NFKD", label)
    base = "".join(ch for ch in base if ch.isalnum()).lower()
    if not base:
        base = "type"
    return base[:20]


def _unique_ticket_key(guild_id: int, label: str) -> str:
    existing = {t["type_key"] for t in get_ticket_types(guild_id)}
    base = _slugify_ticket_key(label)
    key = base
    i = 2
    while key in existing:
        key = f"{base}{i}"
        i += 1
    return key


def build_ticket_admin_home_embed(guild):
    types = get_ticket_types(guild.id)
    lines = []
    for i, t in enumerate(types, start=1):
        style_ko = TICKET_BUTTON_STYLE_NAMES.get(t["button_style"], t["button_style"])
        lines.append(f"{i}. {t.get('emoji','')} **{t['label']}**  ·  버튼색: {style_ko}")
    if not _ticket_types_initialized(guild.id):
        note = "\n\n💡 아직 저장 전이라 **기본 3종**이 표시돼요. 편집/추가/삭제하면 이 서버 전용으로 저장됩니다."
    else:
        note = ""
    body = "\n".join(lines) if lines else "등록된 문의 종류가 없습니다. `종류 추가`로 만들어주세요."
    cfg = get_ticket_panel_config(guild.id)
    staff_role = guild.get_role(cfg.get("staff_role_id", 0)) if cfg.get("staff_role_id") else None
    category = guild.get_channel(cfg.get("category_id", 0)) if cfg.get("category_id") else None
    staff_txt = staff_role.mention if staff_role else "자동 감지 (관리자 역할)"
    cat_txt = category.name if category else "자동 (🎫 티켓)"
    embed = create_embed(
        "🎫 티켓 패널 관리",
        "티켓툴처럼 문의 버튼과 안내문을 직접 꾸밀 수 있어요.\n\n"
        f"**현재 문의 종류 ({len(types)}개)**\n{body}{note}\n\n"
        f"🛡️ **담당 역할**: {staff_txt}\n"
        f"📂 **카테고리**: {cat_txt}\n\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "• `종류 추가` — 새 문의 버튼 만들기\n"
        "• `종류 편집` — 라벨·이모지·버튼색·안내문 수정\n"
        "• `종류 삭제` — 문의 버튼 제거\n"
        "• `패널 꾸미기` — 패널 임베드 제목·내용·색 수정\n"
        "• `담당 역할 설정` / `카테고리 설정` — 티켓 접근 역할·생성 위치 지정\n"
        "• `미리보기` / `채널에 전송` — 실제 패널 확인·게시"
    )
    return embed


class TicketTypeEditModal(discord.ui.Modal):
    """문의 종류 하나를 추가/편집하는 모달 (5필드 한도 준수)."""
    def __init__(self, guild_id: int, type_key: str = None):
        self.guild_id = guild_id
        self.type_key = type_key
        existing = get_ticket_type(guild_id, type_key) if type_key else None
        title = "문의 종류 편집" if existing else "문의 종류 추가"
        super().__init__(title=title)
        self.label_in = discord.ui.TextInput(
            label="버튼 라벨", placeholder="예: 일반 문의", required=True, max_length=80,
            default=(existing or {}).get("label", ""))
        self.emoji_in = discord.ui.TextInput(
            label="버튼 이모지", placeholder="예: 🎫 (비워도 됨)", required=False, max_length=8,
            default=(existing or {}).get("emoji", ""))
        self.intro_title_in = discord.ui.TextInput(
            label="안내 제목", placeholder="티켓 채널 상단 제목", required=False, max_length=256,
            default=(existing or {}).get("intro_title", ""))
        self.intro_desc_in = discord.ui.TextInput(
            label="안내 내용", placeholder="티켓을 열면 표시할 안내문", required=False,
            style=discord.TextStyle.paragraph, max_length=3900,
            default=(existing or {}).get("intro_description", ""))
        self.style_in = discord.ui.TextInput(
            label="버튼색 (green/blurple/red/gray)", placeholder="green / blurple / red / gray",
            required=False, max_length=10,
            default=(existing or {}).get("button_style", "green"))
        for item in (self.label_in, self.emoji_in, self.intro_title_in, self.intro_desc_in, self.style_in):
            self.add_item(item)

    async def on_submit(self, interaction: discord.Interaction):
        ensure_ticket_types_seeded(self.guild_id)
        label = self.label_in.value.strip()
        emoji = self.emoji_in.value.strip()
        style = (self.style_in.value or "green").strip().lower()
        if style not in TICKET_BUTTON_STYLES:
            style = "green"
        key = self.type_key or _unique_ticket_key(self.guild_id, label)
        save_ticket_type(
            self.guild_id, key,
            label=label, emoji=emoji, button_style=style,
            intro_title=self.intro_title_in.value.strip(),
            intro_description=self.intro_desc_in.value.strip(),
            sort_order=None if not self.type_key else _current_sort(self.guild_id, key),
            created_by=interaction.user.id,
        )
        # 뷰 갱신 등록 (재시작 후에도 동작하도록)
        try:
            bot.add_view(UnifiedTicketView(self.guild_id))
        except Exception:
            pass
        await safe_interaction_edit(
            interaction,
            embed=build_ticket_admin_home_embed(interaction.guild),
            view=TicketAdminHomeView(self.guild_id),
        )


def _current_sort(guild_id: int, type_key: str):
    with DB_MUTEX:
        row = c.execute("SELECT sort_order FROM ticket_types WHERE guild_id=? AND type_key=?", (guild_id, type_key)).fetchone()
    return row[0] if row else None


class TicketTypeEditSelect(discord.ui.Select):
    """편집/삭제 대상 종류를 고르는 셀렉트."""
    def __init__(self, guild_id: int, mode: str):
        self.guild_id = guild_id
        self.mode = mode  # "edit" or "delete"
        types = get_ticket_types(guild_id)
        options = [
            discord.SelectOption(label=t["label"][:100], value=t["type_key"], emoji=t.get("emoji") or None,
                                 description=f"버튼색 {TICKET_BUTTON_STYLE_NAMES.get(t['button_style'], t['button_style'])}")
            for t in types[:25]
        ]
        placeholder = "편집할 문의 종류를 선택" if mode == "edit" else "삭제할 문의 종류를 선택"
        super().__init__(placeholder=placeholder, min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        key = self.values[0]
        if self.mode == "edit":
            await interaction.response.send_modal(TicketTypeEditModal(self.guild_id, key))
        else:
            ensure_ticket_types_seeded(self.guild_id)
            if len(get_ticket_types(self.guild_id)) <= 1:
                return await safe_interaction_send(interaction, "❌ 최소 1개 종류는 남겨야 해요.", ephemeral=True)
            delete_ticket_type(self.guild_id, key)
            try:
                bot.add_view(UnifiedTicketView(self.guild_id))
            except Exception:
                pass
            await safe_interaction_edit(
                interaction,
                embed=build_ticket_admin_home_embed(interaction.guild),
                view=TicketAdminHomeView(self.guild_id),
            )


