def mnb_format_saved_channel(guild: discord.Guild, channel_id: int):
    """저장된 채널 ID를 보기 좋은 멘션/상태 문구로 변환합니다."""
    try:
        channel_id = int(channel_id or 0)
    except (TypeError, ValueError):
        channel_id = 0
    if not guild or not channel_id:
        return "`미설정`"
    channel = guild.get_channel(channel_id)
    if channel:
        return channel.mention
    return f"`삭제됨 또는 접근불가: {channel_id}`"


def get_configured_levelup_channel_id(guild: discord.Guild) -> int:
    """레벨업 알림용으로 직접 지정된 채널 ID를 가져옵니다."""
    if guild is None:
        return 0
    try:
        row = get_log_setting(guild.id, "levelup")
        if row is not None and row[1]:
            return int(row[1] or 0)
    except Exception:
        pass
    try:
        return int(get_saved_channel_id(guild.id, "level_channel_id") or 0)
    except Exception:
        return 0


def get_configured_tts_text_channel_id(guild: discord.Guild) -> int:
    """TTS 채팅용으로 직접 지정된 텍스트 채널 ID를 가져옵니다."""
    if guild is None:
        return 0
    try:
        return int(get_saved_channel_id(guild.id, "tts_text_channel_id") or 0)
    except Exception:
        return 0


