# =========================
# 버스킹 MR 시스템
# =========================

BUSKING_TEXT_CHANNEL_NAMES = ["｜・(🎤)：버스킹채팅", "🎤︱버스킹채팅", "버스킹채팅", "버스킹", "busking"]
BUSKING_COMMON_VOICE_CHANNEL_NAMES = [
    "🎤 버스킹 통방", "🎤︱버스킹 통방", "🎤ㅣ버스킹 통방", "🎤-버스킹통방",
    "🎤 통방", "🎤︱통방", "🎤ㅣ통방", "🎤-통방",
    "버스킹 통방", "버스킹통방", "통방", "통화방", "노래통방", "음악통방",
    "general voice", "voice chat",
]
BUSKING_STAGE_VOICE_CHANNEL_NAMES = ["🎤 버스킹 무대", "🎤︱버스킹 무대", "버스킹 무대", "버스킹", "busking stage"]
BUSKING_VOICE_CHANNEL_NAMES = BUSKING_COMMON_VOICE_CHANNEL_NAMES + BUSKING_STAGE_VOICE_CHANNEL_NAMES


def is_busking_related_channel(channel):
    if channel is None:
        return False
    channel_name = getattr(channel, "name", "") or ""
    category_name = getattr(getattr(channel, "category", None), "name", "") or ""
    return "버스킹" in channel_name or "busking" in channel_name.lower() or "버스킹" in category_name or "busking" in category_name.lower()


def find_busking_voice_channel(guild: discord.Guild, member: discord.Member = None):
    """버스킹 MR을 들려줄 음성 채널을 찾습니다.

    우선순위:
    1) 명령어를 누른 사람이 들어가 있는 음성방
    2) 사람이 들어가 있는 `통방`/`버스킹 통방`
    3) 사람이 들어가 있는 `버스킹 무대`
    4) 비어 있어도 이름이 맞는 통방/버스킹 무대
    """
    if guild is None:
        return None

    if isinstance(member, discord.Member) and member.voice and member.voice.channel:
        return member.voice.channel

    name_priority = [name.lower().replace(" ", "") for name in BUSKING_VOICE_CHANNEL_NAMES]
    occupied_candidates = []
    empty_candidates = []
    for channel in guild.voice_channels:
        normalized = (channel.name or "").lower().replace(" ", "")
        category_name = (getattr(channel.category, "name", "") or "").lower().replace(" ", "")
        matched = (
            any(name and name in normalized for name in name_priority)
            or "통방" in normalized
            or "버스킹" in normalized
            or "busking" in normalized
            or "통방" in category_name
            or "버스킹" in category_name
            or "busking" in category_name
        )
        if not matched:
            continue
        humans = [m for m in channel.members if not m.bot]
        if humans:
            occupied_candidates.append(channel)
        else:
            empty_candidates.append(channel)

    if occupied_candidates:
        return occupied_candidates[0]
    if empty_candidates:
        return empty_candidates[0]
    return None


async def ensure_busking_voice_after_defer(interaction: discord.Interaction):
    if interaction.guild is None:
        await interaction.followup.send("❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
        return None

    voice_channel = find_busking_voice_channel(interaction.guild, interaction.user if isinstance(interaction.user, discord.Member) else None)

    if voice_channel is None:
        await interaction.followup.send(
            "❌ MR을 들려줄 통방을 찾지 못했어요. `🎤 버스킹 통방`, `통방`, `🎤 버스킹 무대` 중 하나를 만들어주세요.",
            ephemeral=True,
        )
        return None

    voice_client = interaction.guild.voice_client
    if voice_client is None:
        return await voice_channel.connect()
    if voice_client.channel != voice_channel:
        await voice_client.move_to(voice_channel)
    return voice_client


def build_busking_panel_embed(guild: discord.Guild):
    config = get_auto_embed_config(guild.id, "panel_busking")
    embed = discord.Embed(
        title=render_auto_embed_text(config.get("title", "🎤 버스킹 MR 패널"), guild)[:256],
        description=render_auto_embed_text(config.get("description", ""), guild)[:4096],
        color=normalize_embed_color(config.get("color", "B18CFF")),
    )
    embed.add_field(
        name="🎙️ 사용 방법",
        value=(
            "1. `/버스킹 mr:노래제목`으로 바로 통방에 MR을 틀 수 있어요.\n"
            "2. MR 입력을 비워두고 `/버스킹`만 쓰면 버튼형 패널이 열립니다.\n"
            "3. 유저가 음성방에 있으면 그 방, 없으면 사람이 있는 `통방`/`버스킹 무대`로 재생됩니다."
        ),
        inline=False,
    )
    embed.add_field(
        name="🎚️ 조작 버튼",
        value="`MR 바로 틀기` `MR 대기열 추가` `일시정지` `다시재생` `스킵` `볼륨` `종료`",
        inline=False,
    )
    image_url = safe_url(config.get("image_url", ""))
    if image_url:
        embed.set_image(url=image_url)
    if guild.icon:
        embed.set_thumbnail(url=guild.icon.url)
    elif bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    footer = render_auto_embed_text(config.get("footer", "만능 봇 | 버스킹 MR 시스템"), guild)
    if footer:
        embed.set_footer(text=footer[:2048])
    return embed


async def play_busking_mr_from_query(interaction: discord.Interaction, query_text: str, *, add_to_queue: bool = False):
    """버스킹 MR을 통방/버스킹 음성방에 재생합니다.

    이 함수는 버튼 입력창과 `/버스킹 mr:` 직접 입력에서 같이 사용합니다.
    """
    voice_client = await ensure_busking_voice_after_defer(interaction)
    if voice_client is None:
        return

    query_text = (query_text or "").strip()
    if not query_text:
        return await interaction.followup.send("❌ MR 제목이나 링크를 입력해주세요.", ephemeral=True)

    try:
        track = await extract_music_info(query_text, "soundcloud")
    except Exception as e:
        return await interaction.followup.send(
            f"❌ MR 정보를 가져오지 못했어요.\n`{e}`",
            ephemeral=True,
        )

    track["service"] = "버스킹 MR"
    track["service_emoji"] = "🎤"
    track["is_busking_mr"] = True

    guild_id = interaction.guild.id
    queue = get_music_queue(guild_id)
    target_channel_name = getattr(getattr(voice_client, "channel", None), "name", "통방")

    if add_to_queue:
        queue.append(track)
        if not voice_client.is_playing() and not voice_client.is_paused():
            await play_music_next(interaction.guild)
            msg = (
                f"🎤 **{target_channel_name}**에 MR 재생을 시작했어요!\n"
                f"**{track['title']}** `[{format_duration(track.get('duration'))}]`"
            )
        else:
            await send_music_now_playing_box(interaction.guild, track, queued=True)
            msg = (
                f"✅ **{target_channel_name}** 버스킹 MR 대기열에 추가했어요!\n"
                f"**{track['title']}** `[{format_duration(track.get('duration'))}]`"
            )
    else:
        queue.clear()
        queue.append(track)
        loop_enabled[guild_id] = False
        skip_vote_users.pop(guild_id, None)
        if voice_client.is_playing() or voice_client.is_paused():
            voice_client.stop()
            msg = (
                f"🎤 **{target_channel_name}**에서 현재 재생을 멈추고 새 MR을 틀게요!\n"
                f"**{track['title']}** `[{format_duration(track.get('duration'))}]`"
            )
        else:
            await play_music_next(interaction.guild)
            msg = (
                f"🎤 **{target_channel_name}**에 버스킹 MR 재생을 시작했어요!\n"
                f"**{track['title']}** `[{format_duration(track.get('duration'))}]`"
            )

    await interaction.followup.send(msg, ephemeral=True)


class BuskingMRModal(discord.ui.Modal):
    def __init__(self, *, add_to_queue: bool = False):
        super().__init__(title="🎤 버스킹 MR 입력")
        self.add_to_queue = add_to_queue
        self.query = discord.ui.TextInput(
            label="MR 제목 또는 링크",
            placeholder="예: 아이유 좋은날 MR / 유튜브 링크 / 사운드클라우드 링크",
            required=True,
            max_length=300,
        )
        self.add_item(self.query)

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.guild is None:
            return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)

        await safe_interaction_defer(interaction, ephemeral=True)

        await play_busking_mr_from_query(interaction, str(self.query.value).strip(), add_to_queue=self.add_to_queue)


class BuskingPanelView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    async def _require_voice_client(self, interaction: discord.Interaction):
        if interaction.guild is None:
            await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
            return None
        voice_client = interaction.guild.voice_client
        if voice_client is None:
            await safe_interaction_send(interaction, "❌ 아직 봇이 음성 채널에 없어요. 먼저 `MR 바로 틀기`를 눌러주세요.", ephemeral=True)
            return None
        return voice_client

    @discord.ui.button(label="MR 바로 틀기", emoji="🎤", style=discord.ButtonStyle.green, custom_id="busking_mr_play_now")
    async def play_mr_now(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(BuskingMRModal(add_to_queue=False))

    @discord.ui.button(label="MR 대기열 추가", emoji="➕", style=discord.ButtonStyle.blurple, custom_id="busking_mr_queue")
    async def add_mr_queue(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(BuskingMRModal(add_to_queue=True))

    @discord.ui.button(label="일시정지", emoji="⏸️", style=discord.ButtonStyle.gray, custom_id="busking_pause")
    async def pause_mr(self, interaction: discord.Interaction, button: discord.ui.Button):
        vc = await self._require_voice_client(interaction)
        if vc is None:
            return
        if vc.is_playing():
            vc.pause()
            return await safe_interaction_send(interaction, "⏸️ 버스킹 MR을 일시정지했어요.", ephemeral=True)
        await safe_interaction_send(interaction, "❌ 현재 재생 중인 MR이 없어요.", ephemeral=True)

    @discord.ui.button(label="다시재생", emoji="▶️", style=discord.ButtonStyle.gray, custom_id="busking_resume")
    async def resume_mr(self, interaction: discord.Interaction, button: discord.ui.Button):
        vc = await self._require_voice_client(interaction)
        if vc is None:
            return
        if vc.is_paused():
            vc.resume()
            return await safe_interaction_send(interaction, "▶️ 버스킹 MR을 다시 재생했어요.", ephemeral=True)
        await safe_interaction_send(interaction, "❌ 일시정지된 MR이 없어요.", ephemeral=True)

    @discord.ui.button(label="스킵", emoji="⏭️", style=discord.ButtonStyle.blurple, custom_id="busking_skip")
    async def skip_mr(self, interaction: discord.Interaction, button: discord.ui.Button):
        vc = await self._require_voice_client(interaction)
        if vc is None:
            return
        if not (vc.is_playing() or vc.is_paused()):
            return await safe_interaction_send(interaction, "❌ 스킵할 MR이 없어요.", ephemeral=True)
        vc.stop()
        await safe_interaction_send(interaction, "⏭️ 현재 MR을 스킵했어요.", ephemeral=True)

    @discord.ui.button(label="대기열", emoji="📜", style=discord.ButtonStyle.gray, custom_id="busking_queue")
    async def queue_mr(self, interaction: discord.Interaction, button: discord.ui.Button):
        guild_id = interaction.guild.id
        queue = get_music_queue(guild_id)
        current = now_playing.get(guild_id)
        text = ""
        if current:
            text += f"🎤 **현재 MR**\n{current.get('service_emoji', '🎧')} {current.get('title', '제목 없음')} `[{format_duration(current.get('duration'))}]`\n\n"
        if queue:
            text += "📜 **대기 중인 MR**\n"
            for i, track in enumerate(list(queue)[:10], start=1):
                text += f"{i}. {track.get('service_emoji', '🎤')} {track.get('title', '제목 없음')} `[{format_duration(track.get('duration'))}]`\n"
        else:
            text += "대기 중인 MR이 없어요."
        await safe_interaction_send(interaction, embed=create_embed("📜 버스킹 MR 대기열", text[:4000]), ephemeral=True)

    @discord.ui.button(label="볼륨", emoji="🔊", style=discord.ButtonStyle.blurple, custom_id="busking_volume")
    async def volume_mr(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MusicVolumeModal())

    @discord.ui.button(label="종료", emoji="❌", style=discord.ButtonStyle.red, custom_id="busking_leave")
    async def leave_mr(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.guild is None:
            return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
        vc = interaction.guild.voice_client
        if vc:
            music_queues.pop(interaction.guild.id, None)
            now_playing.pop(interaction.guild.id, None)
            loop_enabled.pop(interaction.guild.id, None)
            skip_vote_users.pop(interaction.guild.id, None)
            await vc.disconnect()
            return await safe_interaction_send(interaction, "❌ 버스킹 MR을 종료하고 음성 채널에서 나갔어요.", ephemeral=True)
        await safe_interaction_send(interaction, "❌ 봇이 음성 채널에 없어요.", ephemeral=True)


# /버스킹 명령어는 사용자 요청으로 제거되었습니다.
# 기존 버스킹 내부 함수는 DB 호환을 위해 남겨두지만 슬래시 명령어로 등록하지 않습니다.
async def removed_busking_panel(interaction: discord.Interaction, mr: str = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)

    if mr and mr.strip():
        await safe_interaction_defer(interaction, ephemeral=True)
        return await play_busking_mr_from_query(interaction, mr.strip(), add_to_queue=False)

    embed = build_busking_panel_embed(interaction.guild)
    if is_busking_related_channel(interaction.channel):
        await safe_interaction_send(interaction, embed=embed, view=BuskingPanelView())
    else:
        await safe_interaction_send(interaction, 
            "🎤 `/버스킹 mr:노래제목`으로 바로 통방에 MR을 틀 수 있어요. 버튼으로도 사용할 수 있습니다.",
            embed=embed,
            view=BuskingPanelView(),
            ephemeral=True,
        )

