def mnb_help_is_admin(interaction: discord.Interaction) -> bool:
    """도움말에서 관리자 전용 메뉴를 보여줄지 판단합니다."""
    try:
        user = getattr(interaction, "user", None)
        perms = getattr(user, "guild_permissions", None)
        return bool(perms and perms.administrator)
    except Exception:
        return False


def build_public_help_embed(category_key: str = "main", *, is_admin: bool = False):
    data = HELP_CATEGORIES.get(category_key, HELP_CATEGORIES["main"])
    if data.get("admin_only") and not is_admin:
        data = HELP_CATEGORIES["main"]
    embed = discord.Embed(
        title=data["title"],
        description=data["description"],
        color=BOT_COLOR
    )
    for name, value, inline in data["fields"]:
        embed.add_field(name=name, value=value, inline=inline)
    if is_admin:
        embed.set_footer(text="관리자는 보안 메뉴까지 볼 수 있어요. 일반 유저에게는 보안 도움말이 숨겨집니다.")
    else:
        embed.set_footer(text="관리자 전용 명령어는 도움말에서 숨겨져 있어요.")
    if bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    return embed


class PublicHelpSelect(discord.ui.Select):
    def __init__(self, *, is_admin: bool = False):
        options = []
        for key, data in HELP_CATEGORIES.items():
            if data.get("admin_only") and not is_admin:
                continue
            options.append(discord.SelectOption(
                label=data["label"],
                value=key,
                emoji=data["emoji"],
                description=data["title"][:100]
            ))
        super().__init__(placeholder="보고 싶은 도움말 메뉴를 선택하세요.", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        is_admin = mnb_help_is_admin(interaction)
        selected_key = self.values[0]
        selected_data = HELP_CATEGORIES.get(selected_key, {})
        if selected_data.get("admin_only") and not is_admin:
            return await safe_interaction_send(interaction, "❌ 보안 도움말은 관리자만 볼 수 있어요.", ephemeral=True)
        await safe_interaction_edit(interaction,
            embed=build_public_help_embed(selected_key, is_admin=is_admin),
            view=PublicHelpView(is_admin=is_admin)
        )


class PublicHelpView(discord.ui.View):
    def __init__(self, *, is_admin: bool = False):
        super().__init__(timeout=180)
        self.is_admin = is_admin
        self.add_item(PublicHelpSelect(is_admin=is_admin))

    async def show_category(self, interaction: discord.Interaction, category_key: str):
        is_admin = self.is_admin or mnb_help_is_admin(interaction)
        await safe_interaction_edit(interaction,
            embed=build_public_help_embed(category_key, is_admin=is_admin),
            view=PublicHelpView(is_admin=is_admin)
        )

    @discord.ui.button(label="처음", emoji="🌸", style=discord.ButtonStyle.secondary, row=1)
    async def help_main_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self.show_category(interaction, "main")

    @discord.ui.button(label="음악/TTS", emoji="🎵", style=discord.ButtonStyle.secondary, row=1)
    async def help_music_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self.show_category(interaction, "music")

    @discord.ui.button(label="상점", emoji="💰", style=discord.ButtonStyle.secondary, row=1)
    async def help_economy_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self.show_category(interaction, "economy")

    @discord.ui.button(label="문의", emoji="🎫", style=discord.ButtonStyle.secondary, row=1)
    async def help_ticket_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self.show_category(interaction, "ticket")

    @discord.ui.button(label="편안한 이용", emoji="✨", style=discord.ButtonStyle.primary, row=2)
    async def help_comfort_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self.show_category(interaction, "comfort")


@bot.tree.command(name="도움말", description="일반 유저용 도움말을 보여줍니다.")
async def help_panel(interaction: discord.Interaction):
    is_admin = mnb_help_is_admin(interaction)
    await safe_interaction_send(interaction,
        embed=build_public_help_embed("main", is_admin=is_admin),
        view=PublicHelpView(is_admin=is_admin),
        ephemeral=True
    )


