    add_security_log(channel.guild.id, 0, "웹후크변경", f"채널: {channel.name}", channel.id)
    await send_log(
        channel.guild,
        f"🪝 웹후크 변경 감지\n채널: {channel.mention}\n권한보호가 켜져 있으니 웹후크 목록을 확인해주세요.",
        "warning"
    )

