def get_community_settings(guild_id: int) -> dict:
    """서버별 커뮤니티 설정을 가져오거나 기본값으로 생성합니다."""
    try:
        c.execute(
            "SELECT match_group_size, challenge_reward_point, challenge_reward_box, "
            "COALESCE(suggestion_channel_id, 0) "
            "FROM community_settings WHERE guild_id=?",
            (guild_id,),
        )
        row = c.fetchone()
    except sqlite3.Error:
        row = None

    if row is None:
        try:
            c.execute(
                "INSERT OR IGNORE INTO community_settings"
                "(guild_id, match_group_size, challenge_reward_point, challenge_reward_box, updated_at) "
                "VALUES (?, ?, ?, ?, ?)",
                (guild_id, 2, 300, 0, datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
            )
            conn.commit()
        except sqlite3.Error:
            pass
        return {"match_group_size": 2, "challenge_reward_point": 300, "challenge_reward_box": 0, "suggestion_channel_id": 0}

    return {
        "match_group_size": max(2, int(row[0] or 2)),
        "challenge_reward_point": max(0, int(row[1] or 0)),
        "challenge_reward_box": max(0, int(row[2] or 0)),
        "suggestion_channel_id": int(row[3] or 0),
    }


def update_community_settings(guild_id: int, **fields) -> dict:
    current = get_community_settings(guild_id)
    current.update({k: v for k, v in fields.items() if v is not None})
    try:
        c.execute(
            "INSERT INTO community_settings"
            "(guild_id, match_group_size, challenge_reward_point, challenge_reward_box, suggestion_channel_id, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(guild_id) DO UPDATE SET "
            "match_group_size=excluded.match_group_size, "
            "challenge_reward_point=excluded.challenge_reward_point, "
            "challenge_reward_box=excluded.challenge_reward_box, "
            "suggestion_channel_id=excluded.suggestion_channel_id, "
            "updated_at=excluded.updated_at",
            (
                guild_id,
                max(2, int(current["match_group_size"])),
                max(0, int(current["challenge_reward_point"])),
                max(0, int(current["challenge_reward_box"])),
                int(current.get("suggestion_channel_id", 0) or 0),
                datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            ),
        )
        conn.commit()
    except sqlite3.Error:
        pass
    return current


def log_community_anonymous(guild_id: int, author_id: int, kind: str, content: str, target_id: int = 0):
    """익명 제출을 추적용으로 기록합니다. 공개 게시글에는 작성자가 드러나지 않습니다."""
    try:
        c.execute(
            "INSERT INTO community_anonymous_logs(guild_id, author_id, kind, target_id, content, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (
                int(guild_id), int(author_id), str(kind)[:20], int(target_id or 0),
                str(content or "")[:1000], datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            ),
        )
        conn.commit()
    except sqlite3.Error:
        pass


def resolve_suggestion_channel(guild: discord.Guild, fallback: discord.TextChannel = None):
    """설정된 건의/칭찬 채널을 찾고, 없으면 fallback(명령 사용 채널)을 씁니다."""
    settings = get_community_settings(guild.id)
    channel_id = settings.get("suggestion_channel_id", 0)
    if channel_id:
        ch = guild.get_channel(int(channel_id))
        if ch is not None:
            return ch
    return fallback


class AnonymousSuggestionModal(discord.ui.Modal, title="📮 익명 건의함"):
    content = discord.ui.TextInput(
        label="건의/의견 내용",
        style=discord.TextStyle.paragraph,
        placeholder="서버에 바라는 점, 아이디어, 불편한 점을 자유롭게 적어주세요. (익명으로 전달돼요)",
        required=True,
        max_length=1000,
    )

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        target_channel = resolve_suggestion_channel(guild, interaction.channel)
        if target_channel is None:
            return await safe_interaction_send(interaction, "❌ 건의를 보낼 채널을 찾지 못했어요.", ephemeral=True)

        text = str(self.content.value or "").strip()
        embed = discord.Embed(
            title="📮 익명 건의가 도착했어요",
            description=text,
            color=0xCDB4DB,
        )
        embed.set_footer(text="만능 봇 | 익명 건의함 · 작성자는 공개되지 않아요")

        try:
            await target_channel.send(embed=embed)
        except (discord.Forbidden, discord.HTTPException):
            return await safe_interaction_send(interaction, "⚠️ 건의 채널에 메시지를 보낼 권한이 부족해요.", ephemeral=True)

        log_community_anonymous(guild.id, interaction.user.id, "suggestion", text)
        await safe_interaction_send(interaction, "✅ 익명으로 건의를 전달했어요. 소중한 의견 고마워요!", ephemeral=True)


