    embed.add_field(name="🔐 토큰 상태", value=token_state, inline=True)
    embed.add_field(
        name="🎚️ 조작 버튼",
        value="`재생` `일시정지` `다시재생` `스킵 투표` `대기열` `반복` `셔플` `볼륨` `종료`",
        inline=False,
    )
    custom_client = CUSTOM_BOT_CLIENTS.get(int(slot)) if "CUSTOM_BOT_CLIENTS" in globals() else None
