def _mnb_channel_display_name(channel):
    if channel is None:
        return "미설정"
    mention = getattr(channel, "mention", None)
    if mention:
        return f"{mention} (`{channel.name}` / `{channel.id}`)"
    return f"`{getattr(channel, 'name', '알 수 없음')}` (`{getattr(channel, 'id', 0)}`)"


def _mnb_unique_channels(channels):
    seen = set()
    result = []
    for channel in channels:
        cid = getattr(channel, "id", None)
        if cid is None or cid in seen:
            continue
        seen.add(cid)
        result.append(channel)
    return result


def resolve_guild_channel_by_query(guild: discord.Guild, query: str, *, category_only: bool = False, channel_only: bool = False):
    """멘션/ID/정확한 이름/부분 이름으로 채널을 찾습니다."""
    raw = (query or "").strip()
    if not guild or not raw:
        return None, "삭제할 대상을 입력해주세요. 예: `#채널`, `채널이름`, `채널ID`"

    if category_only:
        candidates = list(guild.categories)
    else:
        candidates = list(getattr(guild, "channels", []) or [])
        if not channel_only:
            candidates += list(guild.categories)
        else:
            candidates = [ch for ch in candidates if not isinstance(ch, discord.CategoryChannel)]
    candidates = _mnb_unique_channels(candidates)

    id_match = re.search(r"\d{15,25}", raw)
    if id_match:
        target_id = int(id_match.group(0))
        target = guild.get_channel(target_id)
        if target and target in candidates:
            return target, ""
        return None, f"`{target_id}` ID에 해당하는 삭제 대상을 찾지 못했어요."

    lowered = raw.lower().lstrip("#").strip()
    exact_matches = [ch for ch in candidates if (getattr(ch, "name", "") or "").lower() == lowered]
    if len(exact_matches) == 1:
        return exact_matches[0], ""
    if len(exact_matches) > 1:
        names = "\n".join(f"- `{ch.name}` / ID `{ch.id}`" for ch in exact_matches[:10])
        return None, "같은 이름의 채널이 여러 개 있어요. ID로 다시 입력해주세요.\n" + names

    partial_matches = [ch for ch in candidates if lowered and lowered in (getattr(ch, "name", "") or "").lower()]
    if len(partial_matches) == 1:
        return partial_matches[0], ""
    if len(partial_matches) > 1:
        names = "\n".join(f"- `{ch.name}` / ID `{ch.id}`" for ch in partial_matches[:10])
        return None, "비슷한 이름의 채널이 여러 개 있어요. 정확한 이름이나 ID로 다시 입력해주세요.\n" + names

    kind = "카테고리" if category_only else "채널"
    return None, f"`{raw}` {kind}을 찾지 못했어요. 멘션, 정확한 이름, ID 중 하나로 입력해주세요."


async def delete_channel_by_query_command(interaction: discord.Interaction, 대상: str, 확인: bool = False):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    if await reject_if_not_bot_manager(interaction):
        return

    guild = interaction.guild
    bot_member = guild.me or guild.get_member(bot.user.id if bot.user else 0)
    if not bot_member or not bot_member.guild_permissions.manage_channels:
        return await safe_interaction_send(interaction, "❌ 봇에게 `채널 관리` 권한이 없어서 삭제할 수 없어요.", ephemeral=True)

    target, error = resolve_guild_channel_by_query(guild, 대상, channel_only=True)
    if error:
        return await safe_interaction_send(interaction, "❌ 채널 삭제 실패\n" + error, ephemeral=True)
    if isinstance(target, discord.CategoryChannel):
        return await safe_interaction_send(interaction, "❌ 카테고리는 `/서버 카테고리삭제`로 삭제해주세요.", ephemeral=True)

    if not 확인:
        embed = create_embed(
            "⚠️ 채널 삭제 확인 필요",
            f"삭제 대상: {_mnb_channel_display_name(target)}\n\n"
            "정말 삭제하려면 명령어를 다시 실행하면서 `확인`을 `True`로 선택해주세요.\n"
            "예: `/서버 채널삭제 대상:#채널 확인:True`",
            COLOR_WARNING,
        )
        return await safe_interaction_send(interaction, embed=embed, ephemeral=True)

    target_name = getattr(target, "name", "알 수 없음")
    target_id = getattr(target, "id", 0)
    try:
        await target.delete(reason=f"/서버 채널삭제 사용: {interaction.user}")
    except discord.Forbidden:
        return await safe_interaction_send(interaction, "❌ 권한이 부족해서 채널을 삭제하지 못했어요. 봇 역할 위치와 `채널 관리` 권한을 확인해주세요.", ephemeral=True)
    except discord.HTTPException as e:
        return await safe_interaction_send(interaction, f"❌ Discord 오류로 채널 삭제에 실패했어요.\n`{e}`", ephemeral=True)

    embed = create_embed(
        "✅ 채널 삭제 완료",
        f"삭제한 채널: `{target_name}`\n채널 ID: `{target_id}`",
        FRIEND_SERVER_COLORS.get("warning", COLOR_WARNING),
    )
    try:
        await safe_interaction_send(interaction, embed=embed, ephemeral=True)
    except Exception:
        pass
    try:
        await send_log(guild, f"🗑️ 채널 삭제\n채널: `{target_name}` (`{target_id}`)\n관리자: {interaction.user.mention}", "general")
    except Exception:
        pass


async def delete_category_by_query_command(interaction: discord.Interaction, 대상: str, 하위채널까지: bool = False, 확인: bool = False):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    if await reject_if_not_bot_manager(interaction):
        return

    guild = interaction.guild
    bot_member = guild.me or guild.get_member(bot.user.id if bot.user else 0)
    if not bot_member or not bot_member.guild_permissions.manage_channels:
        return await safe_interaction_send(interaction, "❌ 봇에게 `채널 관리` 권한이 없어서 삭제할 수 없어요.", ephemeral=True)

    category, error = resolve_guild_channel_by_query(guild, 대상, category_only=True)
    if error:
        return await safe_interaction_send(interaction, "❌ 카테고리 삭제 실패\n" + error, ephemeral=True)
    if not isinstance(category, discord.CategoryChannel):
        return await safe_interaction_send(interaction, "❌ 카테고리만 삭제할 수 있어요.", ephemeral=True)

    child_channels = list(getattr(category, "channels", []) or [])
    child_preview = "없음" if not child_channels else "\n".join(f"- `{ch.name}`" for ch in child_channels[:12])
    if child_channels and len(child_channels) > 12:
        child_preview += f"\n- 외 {len(child_channels) - 12}개"

    if not 확인:
        mode_text = "카테고리와 하위 채널까지 전부 삭제" if 하위채널까지 else "카테고리만 삭제, 하위 채널은 서버 밖으로 분리될 수 있음"
        embed = create_embed(
            "⚠️ 카테고리 삭제 확인 필요",
            f"삭제 대상: `{category.name}` (`{category.id}`)\n"
            f"삭제 방식: **{mode_text}**\n\n"
            f"하위 채널:\n{child_preview}\n\n"
            "정말 삭제하려면 명령어를 다시 실행하면서 `확인`을 `True`로 선택해주세요.\n"
            "예: `/서버 카테고리삭제 대상:게임방 하위채널까지:True 확인:True`",
            COLOR_WARNING,
        )
        return await safe_interaction_send(interaction, embed=embed, ephemeral=True)

    category_name = category.name
    category_id = category.id
    deleted_children = 0
    skipped_children = []

    if 하위채널까지:
        for child in list(child_channels):
            if isinstance(child, discord.VoiceChannel) and any(not member.bot for member in child.members):
                skipped_children.append(child.name)
                continue
            try:
                await child.delete(reason=f"/서버 카테고리삭제 하위채널삭제 사용: {interaction.user}")
                deleted_children += 1
                await asyncio.sleep(0.15)
            except (discord.Forbidden, discord.HTTPException):
                skipped_children.append(child.name)

        if skipped_children:
            embed = create_embed(
                "⚠️ 일부 채널 삭제 못함",
                "사람이 들어있거나 권한이 부족한 채널이 있어서 카테고리 삭제를 멈췄어요.\n\n"
                f"삭제된 하위 채널: `{deleted_children}`개\n"
                "삭제 못한 채널:\n" + "\n".join(f"- `{name}`" for name in skipped_children[:12]),
                COLOR_WARNING,
            )
            return await safe_interaction_send(interaction, embed=embed, ephemeral=True)

    try:
        await category.delete(reason=f"/서버 카테고리삭제 사용: {interaction.user}")
    except discord.Forbidden:
        return await safe_interaction_send(interaction, "❌ 권한이 부족해서 카테고리를 삭제하지 못했어요. 봇 역할 위치와 `채널 관리` 권한을 확인해주세요.", ephemeral=True)
    except discord.HTTPException as e:
        return await safe_interaction_send(interaction, f"❌ Discord 오류로 카테고리 삭제에 실패했어요.\n`{e}`", ephemeral=True)

    embed = create_embed(
        "✅ 카테고리 삭제 완료",
        f"삭제한 카테고리: `{category_name}`\n카테고리 ID: `{category_id}`\n하위 채널 삭제: `{deleted_children}`개",
        FRIEND_SERVER_COLORS.get("warning", COLOR_WARNING),
    )
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)
    try:
        await send_log(
            guild,
            f"🗑️ 카테고리 삭제\n카테고리: `{category_name}` (`{category_id}`)\n하위 채널 삭제: `{deleted_children}`개\n관리자: {interaction.user.mention}",
            "general",
        )
    except Exception:
        pass


# =========================
# 직접 역할 만들기 박스형 모달
# =========================
ROLE_MAKER_COLOR_PRESETS = {
    "하늘": COLOR_SKY,
    "하늘색": COLOR_SKY,
    "연하늘": COLOR_SOFT_SKY,
    "핑크": COLOR_PINK,
    "연핑크": COLOR_PINK,
    "보라": COLOR_LAVENDER,
    "연보라": COLOR_LAVENDER,
    "민트": COLOR_MINT,
    "초록": COLOR_GREEN,
    "연초록": COLOR_GREEN,
    "골드": COLOR_GOLD,
    "노랑": COLOR_GOLD,
    "경고": COLOR_WARNING,
    "빨강": COLOR_WARNING,
    "회색": COLOR_GRAY,
    "그레이": COLOR_GRAY,
    "기본": 0,
    "없음": 0,
}


def parse_role_maker_color(raw_color: str):
    raw = (raw_color or "").strip()
    if not raw:
        return discord.Color.default(), "기본"

    key = raw.replace(" ", "").lower()
    for preset_name, preset_value in ROLE_MAKER_COLOR_PRESETS.items():
        if key == preset_name.lower():
            if preset_value == 0:
                return discord.Color.default(), "기본"
            return discord.Color(preset_value), f"#{preset_value:06X}"

    cleaned = raw.replace("#", "").replace("0x", "").replace("0X", "").strip()
    if len(cleaned) == 6:
        try:
            value = int(cleaned, 16)
            if 0 <= value <= 0xFFFFFF:
                return discord.Color(value), f"#{value:06X}"
        except ValueError:
            pass

    raise ValueError("색상은 `#87CEFA`, `87CEFA`, `하늘색`, `핑크`, `보라`, `민트`, `골드`, `기본` 중 하나로 입력해주세요.")


def parse_role_maker_bool(raw_text: str, *, default: bool = False):
    text = (raw_text or "").strip().lower().replace(" ", "")
    if not text:
        return default
    yes_values = {"y", "yes", "true", "1", "on", "예", "네", "ㅇ", "ㅇㅇ", "켜기", "사용", "보이게", "표시"}
    no_values = {"n", "no", "false", "0", "off", "아니오", "아니", "ㄴ", "ㄴㄴ", "끄기", "미사용", "숨김"}
    if text in yes_values:
        return True
    if text in no_values:
        return False
    return default


def validate_custom_role_name(role_name: str):
    name = (role_name or "").strip()
    if not name:
        raise ValueError("역할 이름을 입력해주세요.")
    if len(name) > 100:
        raise ValueError("역할 이름은 100자 이하로 입력해주세요.")
    blocked = {"@everyone", "everyone", "@here", "here"}
    if name.lower().replace(" ", "") in blocked:
        raise ValueError("이 이름은 역할 이름으로 사용할 수 없어요.")
    return name


# ----- 역할 만들기 패널: 만든 역할 추적 헬퍼 -----
def track_role_maker_role(guild_id: int, role_id: int, role_name: str, created_by: int):
    try:
        c.execute(
            "INSERT OR REPLACE INTO role_maker_created_roles"
            "(guild_id, role_id, role_name, created_by, created_at) VALUES (?, ?, ?, ?, ?)",
            (guild_id, role_id, role_name, created_by, datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
        )
        conn.commit()
    except sqlite3.Error:
        pass


def untrack_role_maker_role(guild_id: int, role_id: int):
    try:
        c.execute("DELETE FROM role_maker_created_roles WHERE guild_id=? AND role_id=?", (guild_id, role_id))
        conn.commit()
    except sqlite3.Error:
        pass


def get_role_maker_roles(guild: discord.Guild):
    """이 패널로 만든 역할 중 아직 서버에 존재하는 것만 (role, created_at) 로 반환합니다.
    삭제된 역할은 추적 목록에서도 정리합니다."""
    try:
        c.execute(
            "SELECT role_id, role_name, created_at FROM role_maker_created_roles "
            "WHERE guild_id=? ORDER BY created_at DESC",
            (guild.id,),
        )
        rows = c.fetchall()
    except sqlite3.Error:
        return []
    result = []
    for role_id, role_name, created_at in rows:
        role = guild.get_role(role_id)
        if role is None:
            untrack_role_maker_role(guild.id, role_id)
            continue
        result.append((role, created_at))
    return result


def apply_role_permissions_safely(base_perms, guild):
    """관리자 권한 지정 시 봇이 그 권한을 갖고 있을 때만 허용합니다.
    (봇이 없는 권한을 역할에 주려 하면 Discord가 거부하므로 사전 차단)"""
    bot_member = guild.me
    if bot_member is None:
        return base_perms
    if base_perms.administrator and not bot_member.guild_permissions.administrator:
        # 봇에 관리자 권한이 없으면 관리자 비트를 빼고 나머지만 적용
        safe = discord.Permissions(base_perms.value)
        safe.administrator = False
        return safe
    return base_perms


async def _apply_role_icon(guild: discord.Guild, role: discord.Role, emoji_raw: str) -> str:
    """역할 아이콘(이모지)을 적용합니다. 성공/사유 문자열을 반환합니다.
    서버 부스트 레벨 2 이상에서만 role_icons 기능이 열립니다."""
    if "ROLE_ICONS" not in guild.features:
        return "미적용(부스트 레벨2 필요)"
    try:
        # 유니코드 이모지는 unicode_emoji 로, 커스텀 이모지(<:name:id>)는 그 이미지를 아이콘으로.
        custom = re.match(r"<a?:\w+:(\d+)>", emoji_raw)
        if custom:
            emoji_obj = guild.get_emoji(int(custom.group(1)))
            if emoji_obj is None:
                return "미적용(서버에 없는 커스텀 이모지)"
            icon_bytes = await emoji_obj.read()
            await role.edit(display_icon=icon_bytes, reason="역할 만들기: 아이콘 설정")
        else:
            await role.edit(display_icon=emoji_raw, reason="역할 만들기: 아이콘 설정")
        return "적용됨"
    except discord.Forbidden:
        return "미적용(권한 부족)"
    except (discord.HTTPException, TypeError, ValueError):
        return "미적용(형식 오류)"


