# =========================
# 역할 만들기 패널: 여러 역할 한번에 만들기
# =========================
class RoleMakerBulkModal(discord.ui.Modal, title="📚 여러 역할 한번에 만들기"):
    roles_text = discord.ui.TextInput(
        label="역할 목록 (한 줄에 하나)",
        style=discord.TextStyle.paragraph,
        placeholder="롤\n발로란트 | 핑크\n오버워치 | #FF5555 | 운영진\n새벽반 | 보라 | 메시지관리, 닉네임관리",
        max_length=1500,
        required=True,
    )
    default_color = discord.ui.TextInput(
        label="기본 색상 (색 생략 시 적용)",
        placeholder="#87CEFA / 하늘색 / 기본",
        max_length=20,
        required=False,
        default="기본",
    )

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        if guild is None:
            return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
        if await reject_if_not_setup_manager(interaction):
            return
        await safe_interaction_defer(interaction, ephemeral=True)

        bot_member = guild.me
        if not bot_member or not bot_member.guild_permissions.manage_roles:
            return await interaction.followup.send(
                embed=create_embed("❌ 실패", "봇에게 `역할 관리` 권한이 없어요.", FRIEND_SERVER_COLORS.get("warning", COLOR_WARNING)),
                ephemeral=True,
            )

        try:
            default_col, _dtext = parse_role_maker_color(str(self.default_color.value))
        except ValueError:
            default_col = discord.Color.default()

        lines = [ln.strip() for ln in str(self.roles_text.value or "").splitlines() if ln.strip()]
        if not lines:
            return await interaction.followup.send("❌ 역할을 한 줄에 하나씩 입력해주세요.", ephemeral=True)
        if len(lines) > 20:
            return await interaction.followup.send("❌ 한 번에 최대 20개까지만 만들 수 있어요.", ephemeral=True)

        created_list, updated_list, failed_list = [], [], []
        for line in lines:
            # 형식: 이름 | 색상 | 권한   (색상/권한은 생략 가능)
            parts = [p.strip() for p in line.split("|")]
            raw_name = parts[0]
            raw_color = parts[1] if len(parts) >= 2 and parts[1] else ""
            raw_perm = parts[2] if len(parts) >= 3 and parts[2] else ""
            try:
                name = validate_custom_role_name(raw_name)
            except ValueError:
                failed_list.append(f"{raw_name} (이름 오류)")
                continue

            if raw_color:
                try:
                    col, _ct = parse_role_maker_color(raw_color)
                except ValueError:
                    col = default_col
            else:
                col = default_col

            preset, bits, _summary, unknown = _parse_setup_role_perm_input(raw_perm)
            if unknown:
                failed_list.append(f"{name} (권한 오류: {','.join(unknown)})")
                continue
            resolved = resolve_custom_role_permissions(preset, bits)
            perms = discord.Permissions.none() if resolved is None else apply_role_permissions_safely(resolved, guild)

            try:
                existing = discord.utils.get(guild.roles, name=name)
                if existing:
                    if existing >= bot_member.top_role:
                        failed_list.append(f"{name} (봇보다 높음)")
                        continue
                    await existing.edit(color=col, permissions=perms, reason=f"역할 일괄 생성: {interaction.user}")
                    track_role_maker_role(guild.id, existing.id, name, interaction.user.id)
                    updated_list.append(name)
                else:
                    new_role = await guild.create_role(
                        name=name, color=col, permissions=perms,
                        mentionable=False, reason=f"역할 일괄 생성: {interaction.user}",
                    )
                    track_role_maker_role(guild.id, new_role.id, name, interaction.user.id)
                    created_list.append(name)
                await asyncio.sleep(0.3)  # rate limit 여유
            except discord.Forbidden:
                failed_list.append(f"{name} (권한 부족)")
            except discord.HTTPException:
                failed_list.append(f"{name} (Discord 오류)")

        embed = discord.Embed(
            title="📚 여러 역할 만들기 결과",
            color=FRIEND_SERVER_COLORS.get("role", BOT_COLOR),
        )
        embed.add_field(name=f"✅ 새로 생성 ({len(created_list)})", value=(", ".join(created_list) or "없음"), inline=False)
        if updated_list:
            embed.add_field(name=f"🔄 기존 수정 ({len(updated_list)})", value=", ".join(updated_list), inline=False)
        if failed_list:
            embed.add_field(name=f"⚠️ 실패 ({len(failed_list)})", value="\n".join(failed_list), inline=False)
        embed.set_footer(text=f"{guild.name} | 만능 봇 역할 일괄 생성")
        await interaction.followup.send(embed=embed, ephemeral=True)
        await send_log(guild, f"📚 역할 일괄 생성 {len(created_list)}개 생성/{len(updated_list)}개 수정\n관리자: {interaction.user.mention}", "general")


