class FriendServerPanelView(discord.ui.View):
    def __init__(self, page=1):
        super().__init__(timeout=None)
        self.page = page
        self.add_buttons()

    def add_buttons(self):
        # 1페이지 메뉴
        if self.page == 1:
            self.add_item(discord.ui.Button(label="전체 생성", style=discord.ButtonStyle.primary, custom_id="all"))
            self.add_item(discord.ui.Button(label="게임방", style=discord.ButtonStyle.secondary, custom_id="game"))
            self.add_item(discord.ui.Button(label="내전방", style=discord.ButtonStyle.secondary, custom_id="scrim"))
            self.add_item(discord.ui.Button(label="다음 페이지 ➡️", style=discord.ButtonStyle.success, custom_id="next_page"))
        # 2페이지 메뉴
        else:
            self.add_item(discord.ui.Button(label="⬅️ 이전 페이지", style=discord.ButtonStyle.success, custom_id="prev_page"))
            self.add_item(discord.ui.Button(label="강화방", style=discord.ButtonStyle.secondary, custom_id="enhance"))
            self.add_item(discord.ui.Button(label="미니게임", style=discord.ButtonStyle.secondary, custom_id="gambling"))
            self.add_item(discord.ui.Button(label="로그/셋", style=discord.ButtonStyle.secondary, custom_id="logs"))

        # 디자인 수정 버튼 추가
        self.add_item(discord.ui.Button(label="디자인 수정", style=discord.ButtonStyle.danger, custom_id="edit_design"))

        # 모든 버튼 콜백 연결
        for item in self.children:
            if item.custom_id in ["next_page", "prev_page"]:
                item.callback = self.switch_page
            else:
                item.callback = self.run_server_creation

    async def switch_page(self, interaction: discord.Interaction):
        new_page = 2 if interaction.data["custom_id"] == "next_page" else 1
        await interaction.response.edit_message(view=FriendServerPanelView(page=new_page))

    async def run_server_creation(self, interaction: discord.Interaction):
        val = interaction.data["custom_id"]

        # 디자인 수정 버튼 로직
        if val == "edit_design":
            config = get_recruit_embed_config(interaction.guild.id, "benefit") or {}
            return await interaction.response.send_modal(EmbedEditModal("benefit", config))

        # 기존 서버 생성 로직
        await interaction.response.send_message(f"✅ {val} 구성 서버를 생성합니다...", ephemeral=True)
        choice = app_commands.Choice(name=val, value=val)
        await create_friend_server(interaction, choice)

