# ----- 미니게임 최상위 명령어 -----
# - 서버 포인트 전용이며 실제 돈/상품/현금성 보상과 연결하지 않습니다.
# - 유저 대결은 신청자 포인트만 적용합니다. 상대 포인트는 자동 차감하지 않습니다.
# - /마크는 구리/레드스톤 제거, 겉날개/엔더드래곤/용암/엔더맨/컴퓨터꺼짐 결과를 추가했습니다.
mini_game_group = app_commands.Group(name="미니게임", description="서버 포인트 금액을 직접 입력해서 즐기는 미니게임 모음입니다.")
SAFE_MINIGAME_COOLDOWN_SECONDS = 3
SAFE_MINIGAME_COOLDOWNS = {}
MANEUNG_MINIGAME_MIN_BET = 1
MANEUNG_MINIGAME_MAX_BET = 1_000_000


def _safe_game_footer():
    return "만능봇 미니게임 | 서버 포인트 전용 · 현금성 보상 없음"


def _safe_game_cooldown_left(guild_id: int, user_id: int, game_key: str):
    now = time.time()
    key = (int(guild_id or 0), int(user_id), str(game_key))
    last = SAFE_MINIGAME_COOLDOWNS.get(key, 0)
    left = SAFE_MINIGAME_COOLDOWN_SECONDS - (now - last)
    if left > 0:
        return int(left) + 1
    SAFE_MINIGAME_COOLDOWNS[key] = now
    return 0


def _safe_game_embed(title: str, description: str, color: int = COLOR_SOFT_SKY):
    embed = create_embed(title, description, color)
    embed.set_footer(text=_safe_game_footer())
    return embed


def _safe_game_guild_check(interaction: discord.Interaction, game_key: str):
    if interaction.guild is None:
        return "❌ 서버에서만 사용할 수 있어요."
    left = _safe_game_cooldown_left(interaction.guild.id, interaction.user.id, game_key)
    if left > 0:
        return f"⏳ 너무 빠르게 사용할 수 없어요. **{left}초** 뒤 다시 시도해주세요."
    return ""


def _safe_minigame_start_amount(interaction: discord.Interaction, amount: int, game_label: str):
    """입력한 서버 포인트를 먼저 차감합니다. 서버 내부 포인트 전용입니다."""
    if interaction.guild is None:
        return False, 0, "❌ 서버에서만 사용할 수 있어요."
    try:
        amount = int(amount)
    except (TypeError, ValueError):
        return False, 0, "❌ 사용할 포인트 금액이 올바르지 않아요."
    if amount < MANEUNG_MINIGAME_MIN_BET or amount > MANEUNG_MINIGAME_MAX_BET:
        return False, 0, f"❌ 금액은 **{MANEUNG_MINIGAME_MIN_BET:,}P ~ {MANEUNG_MINIGAME_MAX_BET:,}P** 사이로 입력해주세요."
    before_point = get_user_point(interaction.guild.id, interaction.user.id)
    if before_point < amount:
        return False, 0, f"❌ 포인트가 부족해요. {game_label} 사용금액은 **{amount:,}P**이고, 보유 포인트는 **{before_point:,}P**예요."
    set_user_point(interaction.guild.id, interaction.user.id, before_point - amount)
    return True, before_point, ""


def _safe_minigame_apply_result(guild_id: int, user_id: int, reward: int):
    reward = max(0, int(round(reward or 0)))
    current = get_user_point(guild_id, user_id)
    after_point = current + reward
    set_user_point(guild_id, user_id, after_point)
    return after_point


def _safe_minigame_money_line(amount: int, reward: int, before_point: int, after_point: int):
    profit = int(after_point) - int(before_point)
    sign = "+" if profit >= 0 else ""
    return (
        f"💸 사용금액: **{int(amount):,}P**\n"
        f"🎁 지급포인트: **{int(reward):,}P**\n"
        f"📊 포인트 변화: **{int(before_point):,}P → {int(after_point):,}P** (**{sign}{profit:,}P**)"
    )


def _safe_minigame_result_embed_for_member(title: str, guild: discord.Guild, member: discord.abc.User, amount: int, reward: int, before_point: int, result_text: str, color: int = COLOR_SOFT_SKY):
    after_point = _safe_minigame_apply_result(guild.id, member.id, reward)
    embed = _safe_game_embed(title, result_text, color)
    embed.add_field(name="포인트 정산", value=_safe_minigame_money_line(amount, reward, before_point, after_point), inline=False)
    return embed


def _safe_minigame_result_embed(title: str, interaction: discord.Interaction, amount: int, reward: int, before_point: int, result_text: str, color: int = COLOR_SOFT_SKY):
    return _safe_minigame_result_embed_for_member(title, interaction.guild, interaction.user, amount, reward, before_point, result_text, color)


def _mnb_format_multiplier(multiplier: float):
    try:
        multiplier = float(multiplier)
    except (TypeError, ValueError):
        multiplier = 0.0
    if multiplier.is_integer():
        return f"x{int(multiplier)}"
    return f"x{multiplier:g}"


RPS_CHOICES = {
    "scissors": ("✌️", "가위"),
    "rock": ("✊", "바위"),
    "paper": ("✋", "보"),
}
RPS_WIN_MAP = {"scissors": "paper", "rock": "scissors", "paper": "rock"}
PARITY_CHOICES = {"odd": "홀수", "even": "짝수"}


def _mnb_choice_label(mapping: dict, key: str):
    value = mapping.get(key)
    if isinstance(value, tuple):
        return f"{value[0]} {value[1]}"
    return str(value or key)


def _rps_result_text(my_choice: str, other_choice: str, my_name: str, other_name: str):
    if my_choice == other_choice:
        return "무승부"
    if RPS_WIN_MAP[my_choice] == other_choice:
        return f"{my_name} 승리"
    return f"{other_name} 승리"


def _owner_reward_from_result(result: str, owner_name: str, amount: int, win_multiplier: float = 2.0):
    if result == "무승부":
        return int(amount)
    if owner_name in result and "승리" in result:
        return int(round(amount * float(win_multiplier)))
    return 0


