ROULETTE_COLOR_LABELS = {
    "red": "빨강",
    "black": "검정",
    "yellow": "노랑",
    "blue": "파랑",
    "green": "초록",
}
ROULETTE_COLOR_MULTIPLIERS = {
    "red": 2.0,
    "black": 2.0,
    "yellow": 1.5,
    "blue": 1.5,
    "green": 14.0,
}
ROULETTE_PARITY_LABELS = {
    "odd": "홀수",
    "even": "짝수",
}
ROULETTE_PARITY_MULTIPLIERS = {"odd": 2.0, "even": 2.0}


def _maneung_roll_roulette_result():
    number = random.randint(0, 36)
    if number == 0:
        return number, "green", "초록", "none", "없음"
    color_key = random.choice(["red", "black", "yellow", "blue"])
    color_label = ROULETTE_COLOR_LABELS.get(color_key, color_key)
    parity_key = "odd" if number % 2 else "even"
    parity_label = ROULETTE_PARITY_LABELS.get(parity_key, parity_key)
    return number, color_key, color_label, parity_key, parity_label


@bot.tree.command(name="룰렛", description="사용할 포인트를 직접 입력해서 룰렛 색상/홀짝을 맞춰봅니다.")
@app_commands.describe(
    금액="사용할 서버 포인트",
    색상="맞출 색상입니다. 홀짝과 같이 고르면 둘 다 맞아야 성공입니다.",
    홀짝="맞출 홀짝입니다. 색상과 같이 고르면 둘 다 맞아야 성공입니다.",
)
@app_commands.choices(
    색상=[
        app_commands.Choice(name="빨강", value="red"),
        app_commands.Choice(name="검정", value="black"),
        app_commands.Choice(name="노랑", value="yellow"),
        app_commands.Choice(name="파랑", value="blue"),
        app_commands.Choice(name="초록", value="green"),
    ],
    홀짝=[
        app_commands.Choice(name="홀수", value="odd"),
        app_commands.Choice(name="짝수", value="even"),
    ],
)
async def legacy_roulette_top_command(
    interaction: discord.Interaction,
    금액: app_commands.Range[int, MANEUNG_MINIGAME_MIN_BET, MANEUNG_MINIGAME_MAX_BET],
    색상: app_commands.Choice[str] = None,
    홀짝: app_commands.Choice[str] = None,
):
    error = _safe_game_guild_check(interaction, "roulette")
    if error:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    selected_color = 색상.value if 색상 else None
    selected_parity = 홀짝.value if 홀짝 else None
    if not selected_color and not selected_parity:
        return await safe_interaction_send(interaction, "❌ 색상 또는 홀짝 중 1개 이상 선택해야 해요.", ephemeral=True)
    if selected_color == "green" and selected_parity:
        return await safe_interaction_send(interaction, "❌ 초록은 0이라 홀짝이 없어요. 초록은 색상만 선택해주세요.", ephemeral=True)
    ok, before_point, error = _safe_minigame_start_amount(interaction, int(금액), "룰렛")
    if not ok:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    number, result_color_key, result_color_label, result_parity_key, result_parity_label = _maneung_roll_roulette_result()
    selected_parts = []
    matched_parts = []
    total_multiplier = 1.0
    if selected_color:
        color_multiplier = ROULETTE_COLOR_MULTIPLIERS.get(selected_color, 0.0)
        total_multiplier *= color_multiplier
        selected_parts.append(f"🎨 {ROULETTE_COLOR_LABELS.get(selected_color, selected_color)} {_mnb_format_multiplier(color_multiplier)}")
        if selected_color == result_color_key:
            matched_parts.append("색상")
    if selected_parity:
        parity_multiplier = ROULETTE_PARITY_MULTIPLIERS.get(selected_parity, 0.0)
        total_multiplier *= parity_multiplier
        selected_parts.append(f"🔢 {ROULETTE_PARITY_LABELS.get(selected_parity, selected_parity)} {_mnb_format_multiplier(parity_multiplier)}")
        if selected_parity == result_parity_key:
            matched_parts.append("홀짝")
    required = int(bool(selected_color)) + int(bool(selected_parity))
    win = len(matched_parts) == required
    reward = int(round(int(금액) * total_multiplier)) if win else 0
    mode_text = f"콤보 {_mnb_format_multiplier(total_multiplier)}" if selected_color and selected_parity else f"단일 선택 {_mnb_format_multiplier(total_multiplier)}"
    result_text = (
        f"🎯 내 선택: **{' / '.join(selected_parts)}**\n"
        f"🧩 판정 방식: **{mode_text}**\n"
        f"🎡 결과 번호: **{number}**\n"
        f"🎨 색상: **{result_color_label}** / 🔢 홀짝: **{result_parity_label}**\n\n"
        f"{'✅ 성공! 선택한 배율대로 지급됐어요.' if win else '💫 실패! 선택한 포인트가 차감됐어요.'}"
    )
    embed = _safe_minigame_result_embed("🎯 룰렛", interaction, int(금액), reward, before_point, result_text, COLOR_GOLD if win else COLOR_GRAY)
    embed.add_field(
        name="배율표",
        value="빨강/검정 x2 · 노랑/파랑 x1.5 · 초록 x14 · 홀수/짝수 x2\n색상+홀짝을 같이 선택하면 **둘 다 맞았을 때만 배율이 곱해져요.**",
        inline=False,
    )
    await safe_interaction_send(interaction, embed=embed)


