def _minecraft_custom_emoji_url(emoji_text: str):
    """<:name:id> 형태의 커스텀 이모지를 임베드 썸네일 URL로 변환합니다."""
    try:
        match = re.search(r"<a?:[A-Za-z0-9_]+:(\d+)>", str(emoji_text or ""))
        if not match:
            return None
        emoji_id = match.group(1)
        return f"https://cdn.discordapp.com/emojis/{emoji_id}.png?size=128&quality=lossless"
    except Exception:
        return None


