def _minecraft_image_path(filename: str):
    # v243부터 /마크는 파일 첨부 이미지 대신 서버 커스텀 이모지를 우선 사용합니다.
    # 예전 로컬 이미지 방식도 호환만 남겨둡니다.
    if not filename:
        return None
    try:
        path = os.path.join(MINECRAFT_IMAGE_BASE_DIR, filename)
        if os.path.exists(path):
            return path
    except Exception:
        return None
    return None


def _settle_minecraft_multiplier(guild_id: int, user_id: int, before_point: int, amount: int, multiplier: float):
    """마크 광산은 결과 배율을 순수 손익으로 적용합니다.

    예: 1,000P에서 x3이면 +3,000P, -2배면 -2,000P입니다.
    최종 잔액은 0 아래로 내려가지 않게 막습니다.
    """
    delta = int(round(int(amount) * float(multiplier)))
    after_point = max(0, int(before_point) + delta)
    set_user_point(guild_id, user_id, after_point)
    return delta, after_point


@bot.tree.command(name="마크", description="사용할 포인트를 직접 입력해서 마인크래프트 광산을 채굴합니다.")
@app_commands.describe(금액="사용할 서버 포인트")
async def legacy_minecraft_top_command(
    interaction: discord.Interaction,
    금액: app_commands.Range[int, MANEUNG_MINIGAME_MIN_BET, MANEUNG_MINIGAME_MAX_BET],
):
    error = _safe_game_guild_check(interaction, "minecraft")
    if error:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    amount = int(금액)
    before_point = get_user_point(interaction.guild.id, interaction.user.id)
    if before_point < amount:
        return await safe_interaction_send(
            interaction,
            f"❌ 포인트가 부족해요. 마크 광산 사용금액은 **{amount:,}P**이고, 보유 포인트는 **{before_point:,}P**예요.",
            ephemeral=True,
        )
    roll = random.randint(1, 10000)
    selected = MINECRAFT_ORE_TABLE[-1]
    for row in MINECRAFT_ORE_TABLE:
        if roll <= row[0]:
            selected = row
            break
    _, item_name, multiplier, flavor, icon, image_filename = selected
    delta, after_point = _settle_minecraft_multiplier(interaction.guild.id, interaction.user.id, before_point, amount, multiplier)
    sign = "+" if delta >= 0 else ""

    if delta > 0:
        result_emoji = "💰"
        mood_line = f"오! **{item_name}** 발견!"
        change_label = "📈 획득"
        color = COLOR_GREEN
    elif delta < 0:
        result_emoji = "💸"
        mood_line = f"음? **{item_name}** 발생!"
        change_label = "📉 손실"
        color = COLOR_WARNING
    else:
        result_emoji = "⛏️"
        mood_line = f"아쉽다! **{item_name}** 발견!"
        change_label = "➖ 변화 없음"
        color = COLOR_GRAY

    embed = discord.Embed(
        title=f"{result_emoji} 마크 광질 결과",
        description=f"{mood_line}\n{flavor}",
        color=color,
    )
    embed.add_field(name="💰 배팅 금액", value=f"{amount:,}P", inline=True)
    embed.add_field(name=change_label, value=f"{sign}{delta:,}P", inline=True)
    embed.add_field(name="🪙 현재 잔액", value=f"{after_point:,}P", inline=True)
    thumb_url = _minecraft_result_art_url(item_name, icon)
    if thumb_url:
        embed.set_thumbnail(url=thumb_url)
    embed.set_footer(text=_safe_game_footer())
    await safe_interaction_send(interaction, embed=embed)


@bot.tree.command(name="소개팅", description="사용할 포인트를 직접 입력해서 친구 케미를 확인합니다.")
@app_commands.describe(금액="사용할 서버 포인트", 상대="같이 케미를 볼 멤버")
async def legacy_dating_top_command(
    interaction: discord.Interaction,
    금액: app_commands.Range[int, MANEUNG_MINIGAME_MIN_BET, MANEUNG_MINIGAME_MAX_BET],
    상대: discord.Member = None,
):
    error = _safe_game_guild_check(interaction, "dating")
    if error:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    if 상대 is not None and 상대.bot:
        return await safe_interaction_send(interaction, "❌ 봇 말고 서버 멤버를 선택해주세요.", ephemeral=True)
    ok, before_point, error = _safe_minigame_start_amount(interaction, int(금액), "소개팅")
    if not ok:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    target = 상대 or interaction.user
    percent = random.randint(1, 100)
    if percent >= 95:
        grade, multiplier, comment = "💘 운명급 케미", 3.0, "서버 듀오로 바로 나가도 될 정도예요!"
    elif percent >= 85:
        grade, multiplier, comment = "💕 완전 좋은 케미", 2.0, "대화가 잘 통할 것 같은 조합이에요."
    elif percent >= 70:
        grade, multiplier, comment = "💗 좋은 케미", 1.3, "같이 게임 한 판 하면 금방 친해질지도?"
    elif percent >= 50:
        grade, multiplier, comment = "💬 무난한 케미", 1.0, "본전! 가볍게 대화부터 시작해보세요."
    else:
        grade, multiplier, comment = "💔 아쉬운 케미", 0.0, "이번 카드는 아쉽지만 다음 기회가 있어요."
    reward = int(round(int(금액) * multiplier))
    if target.id == interaction.user.id:
        title = "💕 오늘의 자기 케미"
        target_text = interaction.user.mention
    else:
        title = "💕 친구 케미"
        target_text = f"{interaction.user.mention} × {target.mention}"
    result_text = (
        f"👥 대상: **{target_text}**\n"
        f"📊 케미 점수: **{percent}%**\n"
        f"🏷️ 등급: **{grade}** / 배율 **{_mnb_format_multiplier(multiplier)}**\n"
        f"💬 {comment}"
    )
    embed = _safe_minigame_result_embed(title, interaction, int(금액), reward, before_point, result_text, COLOR_PINK if reward >= int(금액) else COLOR_GRAY)
    embed.add_field(name="등급표", value="95+ x3 / 85+ x2 / 70+ x1.3 / 50+ x1 / 49 이하 x0", inline=False)
    await safe_interaction_send(interaction, embed=embed)


class SafeRPSChallengeView(discord.ui.View):
    def __init__(self, challenger: discord.Member, target: discord.Member, challenger_choice: str, amount: int, before_point: int):
        super().__init__(timeout=60)
        self.challenger = challenger
        self.target = target
        self.challenger_choice = challenger_choice
        self.amount = int(amount)
        self.before_point = int(before_point)
        self.resolved = False
        self.message = None

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.target.id:
            await safe_interaction_send(interaction, "❌ 이 버튼은 도전 받은 유저만 누를 수 있어요.", ephemeral=True)
            return False
        return True

    async def _finish(self, interaction: discord.Interaction, target_choice: str):
        if self.resolved:
            return
        self.resolved = True
        for item in self.children:
            item.disabled = True
        result = _rps_result_text(self.challenger_choice, target_choice, self.challenger.display_name, self.target.display_name)
        reward = _owner_reward_from_result(result, self.challenger.display_name, self.amount, 2.0)
        result_text = (
            f"{self.challenger.mention}: **{_mnb_choice_label(RPS_CHOICES, self.challenger_choice)}**\n"
            f"{self.target.mention}: **{_mnb_choice_label(RPS_CHOICES, target_choice)}**\n\n"
            f"🏆 결과: **{result}**\n"
            "상대 포인트는 자동 차감하지 않고, 신청자 포인트만 정산했어요."
        )
        embed = _safe_minigame_result_embed_for_member("✌️ 가위바위보 결과", interaction.guild, self.challenger, self.amount, reward, self.before_point, result_text, COLOR_GOLD if reward > self.amount else COLOR_GRAY)
        await safe_interaction_edit(interaction, embed=embed, view=self)

    @discord.ui.button(label="가위", emoji="✌️", style=discord.ButtonStyle.primary)
    async def scissors(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._finish(interaction, "scissors")

    @discord.ui.button(label="바위", emoji="✊", style=discord.ButtonStyle.primary)
    async def rock(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._finish(interaction, "rock")

    @discord.ui.button(label="보", emoji="✋", style=discord.ButtonStyle.primary)
    async def paper(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._finish(interaction, "paper")

    async def on_timeout(self):
        if self.resolved:
            return
        self.resolved = True
        for item in self.children:
            item.disabled = True
        if self.message:
            try:
                embed = _safe_game_embed("⌛ 가위바위보 시간초과", "60초 안에 선택하지 않아서 대결이 취소됐어요. 입력한 포인트는 이미 사용됐어요.", COLOR_GRAY)
                await self.message.edit(embed=embed, view=self)
            except discord.HTTPException:
                pass


class SafeParityChallengeView(discord.ui.View):
    def __init__(self, challenger: discord.Member, target: discord.Member, challenger_choice: str, amount: int, before_point: int):
        super().__init__(timeout=60)
        self.challenger = challenger
        self.target = target
        self.challenger_choice = challenger_choice
        self.amount = int(amount)
        self.before_point = int(before_point)
        self.resolved = False
        self.message = None

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.target.id:
            await safe_interaction_send(interaction, "❌ 이 버튼은 도전 받은 유저만 누를 수 있어요.", ephemeral=True)
            return False
        return True

    async def _finish(self, interaction: discord.Interaction, target_choice: str):
        if self.resolved:
            return
        self.resolved = True
        for item in self.children:
            item.disabled = True
        number = random.randint(1, 100)
        answer = "odd" if number % 2 else "even"
        c_hit = self.challenger_choice == answer
        t_hit = target_choice == answer
        if c_hit == t_hit:
            result = "무승부"
        elif c_hit:
            result = f"{self.challenger.display_name} 승리"
        else:
            result = f"{self.target.display_name} 승리"
        reward = _owner_reward_from_result(result, self.challenger.display_name, self.amount, 2.0)
        result_text = (
            f"결과 숫자: **{number}** → **{PARITY_CHOICES[answer]}**\n"
            f"{self.challenger.mention}: **{PARITY_CHOICES[self.challenger_choice]}**\n"
            f"{self.target.mention}: **{PARITY_CHOICES[target_choice]}**\n\n"
            f"🏆 결과: **{result}**\n"
            "상대 포인트는 자동 차감하지 않고, 신청자 포인트만 정산했어요."
        )
        embed = _safe_minigame_result_embed_for_member("🔢 홀짝 결과", interaction.guild, self.challenger, self.amount, reward, self.before_point, result_text, COLOR_GOLD if reward > self.amount else COLOR_GRAY)
        await safe_interaction_edit(interaction, embed=embed, view=self)

    @discord.ui.button(label="홀수", emoji="1️⃣", style=discord.ButtonStyle.success)
    async def odd(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._finish(interaction, "odd")

    @discord.ui.button(label="짝수", emoji="2️⃣", style=discord.ButtonStyle.success)
    async def even(self, interaction: discord.Interaction, button: discord.ui.Button):
        await self._finish(interaction, "even")

    async def on_timeout(self):
        if self.resolved:
            return
        self.resolved = True
        for item in self.children:
            item.disabled = True
        if self.message:
            try:
                embed = _safe_game_embed("⌛ 홀짝 시간초과", "60초 안에 선택하지 않아서 대결이 취소됐어요. 입력한 포인트는 이미 사용됐어요.", COLOR_GRAY)
                await self.message.edit(embed=embed, view=self)
            except discord.HTTPException:
                pass


@mini_game_group.command(name="가위바위보", description="입력한 포인트로 AI 또는 유저와 가위바위보를 합니다.")
@app_commands.describe(금액="사용할 서버 포인트", 내선택="내가 낼 가위/바위/보", 상대="비워두면 AI와 대결합니다.")
@app_commands.choices(내선택=[
    app_commands.Choice(name="가위", value="scissors"),
    app_commands.Choice(name="바위", value="rock"),
    app_commands.Choice(name="보", value="paper"),
])
async def mini_game_group_rps(
    interaction: discord.Interaction,
    금액: app_commands.Range[int, MANEUNG_MINIGAME_MIN_BET, MANEUNG_MINIGAME_MAX_BET],
    내선택: app_commands.Choice[str],
    상대: discord.Member = None,
):
    error = _safe_game_guild_check(interaction, "rps")
    if error:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    ok, before_point, error = _safe_minigame_start_amount(interaction, int(금액), "가위바위보")
    if not ok:
        return await safe_interaction_send(interaction, error, ephemeral=True)
    my_choice = 내선택.value
    if 상대 and not 상대.bot and 상대.id != interaction.user.id:
        view = SafeRPSChallengeView(interaction.user, 상대, my_choice, int(금액), before_point)
        embed = _safe_game_embed(
            "✌️ 가위바위보 대결",
            f"{interaction.user.mention} 님이 {상대.mention} 님에게 가위바위보를 신청했어요.\n"
            f"💸 신청자 사용금액: **{int(금액):,}P**\n"
            "신청자 선택은 결과가 나오기 전까지 공개되지 않아요.\n"
            "도전 받은 유저는 **60초 안에 버튼**을 눌러주세요.\n"
            "상대 포인트는 자동 차감하지 않아요.",
            COLOR_SOFT_SKY,
        )
        await safe_interaction_send(interaction, embed=embed, view=view)
        try:
            await interaction.followup.send(f"🔒 내 선택은 **{_mnb_choice_label(RPS_CHOICES, my_choice)}** 입니다. 상대에게는 보이지 않아요.", ephemeral=True)
        except Exception:
            pass
        try:
            view.message = await interaction.original_response()
        except Exception:
            pass
        return
    ai_choice = random.choice(list(RPS_CHOICES.keys()))
    result = _rps_result_text(my_choice, ai_choice, interaction.user.display_name, "AI")
    reward = _owner_reward_from_result(result, interaction.user.display_name, int(금액), 2.0)
    result_text = (
        f"내 선택: **{_mnb_choice_label(RPS_CHOICES, my_choice)}**\n"
        f"AI 선택: **{_mnb_choice_label(RPS_CHOICES, ai_choice)}**\n\n"
        f"🏆 결과: **{result}**"
    )
    embed = _safe_minigame_result_embed("✌️ AI 가위바위보", interaction, int(금액), reward, before_point, result_text, COLOR_GOLD if reward > int(금액) else COLOR_GRAY)
    await safe_interaction_send(interaction, embed=embed)


