# =========================
MNB_CATEGORY_DELETE_PAGE_SIZE = 20


def _mnb_sorted_categories(guild: discord.Guild):
    if guild is None:
        return []
    return sorted(list(getattr(guild, "categories", []) or []), key=lambda c: getattr(c, "position", 0))


def _mnb_category_delete_total_pages(guild: discord.Guild) -> int:
    categories = _mnb_sorted_categories(guild)
    if not categories:
        return 1
    return max(1, (len(categories) + MNB_CATEGORY_DELETE_PAGE_SIZE - 1) // MNB_CATEGORY_DELETE_PAGE_SIZE)


def build_category_delete_panel_embed(guild: discord.Guild, page: int = 0):
    categories = _mnb_sorted_categories(guild)
    total_pages = _mnb_category_delete_total_pages(guild)
    page = max(0, min(int(page or 0), total_pages - 1))
    start = page * MNB_CATEGORY_DELETE_PAGE_SIZE
    page_categories = categories[start:start + MNB_CATEGORY_DELETE_PAGE_SIZE]

    if not categories:
        desc = (
            "삭제할 카테고리가 없어요.\n\n"
            "카테고리를 만들면 이 패널에서 선택해서 삭제할 수 있어요."
        )
    else:
        lines = []
        for index, category in enumerate(page_categories, start=start + 1):
            child_channels = list(getattr(category, "channels", []) or [])
            text_count = sum(1 for ch in child_channels if isinstance(ch, discord.TextChannel))
            voice_count = sum(1 for ch in child_channels if isinstance(ch, discord.VoiceChannel))
            forum_count = sum(1 for ch in child_channels if isinstance(ch, getattr(discord, "ForumChannel", tuple()))) if hasattr(discord, "ForumChannel") else 0
            extra = f" · 포럼 {forum_count}개" if forum_count else ""
            lines.append(f"`{index:02d}.` **{category.name}** — 하위 채널 `{len(child_channels)}`개 · 채팅 {text_count}개 · 음성 {voice_count}개{extra}")
        desc = "\n".join(lines)

    embed = create_embed(
        "🗑️ 카테고리 삭제 패널",
        "삭제할 카테고리를 아래 선택창에서 고르면, 확인 화면에서 **카테고리와 안에 있는 채널을 같이 삭제**할 수 있어요.\n\n"
        "⚠️ 삭제한 카테고리/채널은 디스코드에서 되돌리기 어렵습니다. 꼭 확인하고 눌러주세요.",
        COLOR_WARNING,
    )
    if bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    embed.add_field(name="📄 페이지", value=f"`{page + 1}/{total_pages}` · 전체 카테고리 `{len(categories)}`개", inline=False)
    embed.add_field(name="📋 카테고리 목록", value=desc[:1024], inline=False)
    embed.set_footer(text="⭐ 만능 봇 | 카테고리 삭제 패널")
    return embed


class CategoryDeletePageJumpModal(discord.ui.Modal, title="카테고리 삭제 페이지 이동"):
    def __init__(self, requester_id: int):
        super().__init__(timeout=180)
        self.requester_id = requester_id
        self.page_input = discord.ui.TextInput(
            label="이동할 페이지 번호",
            placeholder="예: 2",
            required=True,
            max_length=4,
        )
        self.add_item(self.page_input)

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.user.id != self.requester_id:
            return await safe_interaction_send(interaction, "❌ 이 패널을 연 관리자만 사용할 수 있어요.", ephemeral=True)
        if not await _friend_panel_require_manager(interaction):
            return
        try:
            page_number = int(str(self.page_input.value).strip())
        except ValueError:
            return await safe_interaction_send(interaction, "❌ 숫자로 페이지를 입력해주세요. 예: `2`", ephemeral=True)
        total_pages = _mnb_category_delete_total_pages(interaction.guild)
        if page_number < 1 or page_number > total_pages:
            return await safe_interaction_send(interaction, f"❌ 페이지는 `1`부터 `{total_pages}`까지만 입력할 수 있어요.", ephemeral=True)
        page = page_number - 1
        await safe_interaction_send(
            interaction,
            embed=build_category_delete_panel_embed(interaction.guild, page),
            view=CategoryDeletePanelView(requester_id=self.requester_id, page=page),
            ephemeral=True,
        )


class CategoryDeleteSelect(discord.ui.Select):
    def __init__(self, parent_view: "CategoryDeletePanelView"):
        self.parent_view_ref = parent_view
        guild = parent_view.guild
        categories = _mnb_sorted_categories(guild)
        total_pages = _mnb_category_delete_total_pages(guild)
        page = max(0, min(parent_view.page, total_pages - 1))
        start = page * MNB_CATEGORY_DELETE_PAGE_SIZE
        page_categories = categories[start:start + MNB_CATEGORY_DELETE_PAGE_SIZE]

        options = []
        for index, category in enumerate(page_categories, start=start + 1):
            child_channels = list(getattr(category, "channels", []) or [])
            label = f"{index}. {category.name}"[:100]
            description = f"하위 채널 {len(child_channels)}개까지 같이 삭제"
            options.append(discord.SelectOption(
                label=label,
                value=str(category.id),
                description=description[:100],
                emoji="🗑️",
            ))

        disabled = False
        if not options:
            disabled = True
            options = [discord.SelectOption(label="삭제할 카테고리가 없어요", value="none", emoji="📭")]

        super().__init__(
            placeholder="삭제할 카테고리를 선택하세요",
            min_values=1,
            max_values=1,
            options=options,
            disabled=disabled,
            row=0,
        )

    async def callback(self, interaction: discord.Interaction):
        view = self.parent_view_ref
        if interaction.user.id != view.requester_id:
            return await safe_interaction_send(interaction, "❌ 이 패널을 연 관리자만 사용할 수 있어요.", ephemeral=True)
        if not await _friend_panel_require_manager(interaction):
            return
        value = self.values[0] if self.values else "none"
        if value == "none":
            return await safe_interaction_send(interaction, "삭제할 카테고리가 없어요.", ephemeral=True)
        try:
            category_id = int(value)
        except ValueError:
            return await safe_interaction_send(interaction, "❌ 카테고리 정보를 읽지 못했어요.", ephemeral=True)
        category = interaction.guild.get_channel(category_id)
        if not isinstance(category, discord.CategoryChannel):
            return await safe_interaction_send(interaction, "❌ 이미 삭제되었거나 카테고리를 찾지 못했어요.", ephemeral=True)

        child_channels = list(getattr(category, "channels", []) or [])
        preview = "없음" if not child_channels else "\n".join(f"- `{ch.name}`" for ch in child_channels[:15])
        if len(child_channels) > 15:
            preview += f"\n- 외 `{len(child_channels) - 15}`개"
        embed = create_embed(
            "⚠️ 정말 삭제할까요?",
            f"선택한 카테고리: **{category.name}** (`{category.id}`)\n"
            f"같이 삭제될 하위 채널: `{len(child_channels)}`개\n\n"
            f"{preview}\n\n"
            "아래 **삭제하기**를 누르면 카테고리와 하위 채널이 같이 삭제됩니다.",
            COLOR_WARNING,
        )
        await safe_interaction_edit(
            interaction,
            embed=embed,
            view=CategoryDeleteConfirmView(category_id=category_id, requester_id=view.requester_id, return_page=view.page),
        )


class CategoryDeletePanelView(discord.ui.View):
    def __init__(self, requester_id: int, page: int = 0, guild: discord.Guild | None = None):
        super().__init__(timeout=600)
        self.requester_id = int(requester_id)
        self.guild = guild
        self.page = max(0, int(page or 0))
        if self.guild is not None:
            total_pages = _mnb_category_delete_total_pages(self.guild)
            self.page = max(0, min(self.page, total_pages - 1))
            self.add_item(CategoryDeleteSelect(self))

    async def _require_owner_and_manager(self, interaction: discord.Interaction):
        if interaction.user.id != self.requester_id:
            await safe_interaction_send(interaction, "❌ 이 패널을 연 관리자만 사용할 수 있어요.", ephemeral=True)
            return False
        if not await _friend_panel_require_manager(interaction):
            return False
        self.guild = interaction.guild
        return True

    async def _redraw(self, interaction: discord.Interaction):
        self.guild = interaction.guild
        view = CategoryDeletePanelView(requester_id=self.requester_id, page=self.page, guild=interaction.guild)
        await safe_interaction_edit(interaction, embed=build_category_delete_panel_embed(interaction.guild, view.page), view=view)

    @discord.ui.button(label="이전", emoji="◀️", style=discord.ButtonStyle.gray, row=1)
    async def prev_page_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._require_owner_and_manager(interaction):
            return
        total_pages = _mnb_category_delete_total_pages(interaction.guild)
        self.page = (self.page - 1) % total_pages
        await self._redraw(interaction)

    @discord.ui.button(label="페이지 이동", emoji="🔢", style=discord.ButtonStyle.blurple, row=1)
    async def page_jump_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._require_owner_and_manager(interaction):
            return
        await interaction.response.send_modal(CategoryDeletePageJumpModal(self.requester_id))

    @discord.ui.button(label="다음", emoji="▶️", style=discord.ButtonStyle.gray, row=1)
    async def next_page_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._require_owner_and_manager(interaction):
            return
        total_pages = _mnb_category_delete_total_pages(interaction.guild)
        self.page = (self.page + 1) % total_pages
        await self._redraw(interaction)

    @discord.ui.button(label="새로고침", emoji="🔄", style=discord.ButtonStyle.green, row=2)
    async def refresh_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._require_owner_and_manager(interaction):
            return
        await self._redraw(interaction)


class CategoryDeleteConfirmView(discord.ui.View):
    def __init__(self, category_id: int, requester_id: int, return_page: int = 0):
        super().__init__(timeout=300)
        self.category_id = int(category_id)
        self.requester_id = int(requester_id)
        self.return_page = max(0, int(return_page or 0))

    async def _require_owner_and_manager(self, interaction: discord.Interaction):
        if interaction.user.id != self.requester_id:
            await safe_interaction_send(interaction, "❌ 이 패널을 연 관리자만 사용할 수 있어요.", ephemeral=True)
            return False
        if not await _friend_panel_require_manager(interaction):
            return False
        return True

    @discord.ui.button(label="삭제하기", emoji="🗑️", style=discord.ButtonStyle.danger, row=0)
    async def confirm_delete_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._require_owner_and_manager(interaction):
            return
        guild = interaction.guild
        bot_member = guild.me or guild.get_member(bot.user.id if bot.user else 0)
        if not bot_member or not bot_member.guild_permissions.manage_channels:
            return await safe_interaction_send(interaction, "❌ 봇에게 `채널 관리` 권한이 없어서 삭제할 수 없어요.", ephemeral=True)

        category = guild.get_channel(self.category_id)
        if not isinstance(category, discord.CategoryChannel):
            return await safe_interaction_send(interaction, "❌ 이미 삭제되었거나 카테고리를 찾지 못했어요.", ephemeral=True)

        category_name = category.name
        category_id = category.id
        child_channels = list(getattr(category, "channels", []) or [])
        deleted_children = 0
        failed_children = []

        await safe_interaction_defer(interaction, ephemeral=True)
        for child in list(child_channels):
            child_name = getattr(child, "name", "알 수 없음")
            try:
                await child.delete(reason=f"카테고리 삭제 패널 하위채널삭제 사용: {interaction.user}")
                deleted_children += 1
                await asyncio.sleep(0.15)
            except (discord.Forbidden, discord.HTTPException):
                failed_children.append(child_name)

        if failed_children:
            failed_preview = "\n".join(f"- `{name}`" for name in failed_children[:15])
            embed = create_embed(
                "⚠️ 일부 채널 삭제 실패",
                f"카테고리: **{category_name}**\n"
                f"삭제된 하위 채널: `{deleted_children}`개\n"
                f"삭제 실패: `{len(failed_children)}`개\n\n"
                f"{failed_preview}\n\n"
                "권한이 부족하거나 이미 사라진 채널이 있어요. 실패한 채널 때문에 카테고리 삭제는 중단했어요.",
                COLOR_WARNING,
            )
            await interaction.followup.send(embed=embed, ephemeral=True)
            return

        try:
            await category.delete(reason=f"카테고리 삭제 패널 사용: {interaction.user}")
        except discord.Forbidden:
            return await interaction.followup.send("❌ 권한이 부족해서 카테고리를 삭제하지 못했어요. 봇 역할 위치와 `채널 관리` 권한을 확인해주세요.", ephemeral=True)
        except discord.HTTPException as e:
            return await interaction.followup.send(f"❌ Discord 오류로 카테고리 삭제에 실패했어요.\n`{e}`", ephemeral=True)

        embed = create_embed(
            "✅ 카테고리 삭제 완료",
            f"삭제한 카테고리: **{category_name}**\n"
            f"카테고리 ID: `{category_id}`\n"
            f"같이 삭제한 하위 채널: `{deleted_children}`개",
            COLOR_WARNING,
        )
        view = CategoryDeletePanelView(requester_id=self.requester_id, page=self.return_page, guild=guild)
        await interaction.followup.send(embed=embed, view=view, ephemeral=True)
        try:
            await send_log(guild, f"🗑️ 카테고리 패널 삭제\n카테고리: `{category_name}` (`{category_id}`)\n하위 채널 삭제: `{deleted_children}`개\n관리자: {interaction.user.mention}", "general")
        except Exception:
            pass

    @discord.ui.button(label="취소", emoji="↩️", style=discord.ButtonStyle.gray, row=0)
    async def cancel_button(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self._require_owner_and_manager(interaction):
            return
        view = CategoryDeletePanelView(requester_id=self.requester_id, page=self.return_page, guild=interaction.guild)
        await safe_interaction_edit(interaction, embed=build_category_delete_panel_embed(interaction.guild, self.return_page), view=view)


async def open_category_delete_panel(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    if await reject_if_not_bot_manager(interaction):
        return
    bot_member = interaction.guild.me or interaction.guild.get_member(bot.user.id if bot.user else 0)
    if not bot_member or not bot_member.guild_permissions.manage_channels:
        return await safe_interaction_send(interaction, "❌ 봇에게 `채널 관리` 권한이 없어서 삭제할 수 없어요.", ephemeral=True)
    await safe_interaction_send(
        interaction,
        embed=build_category_delete_panel_embed(interaction.guild, 0),
        view=CategoryDeletePanelView(requester_id=interaction.user.id, page=0, guild=interaction.guild),
        ephemeral=True,
    )


