# =========================
# 미무봇(Mimu) /embed create 한국어 버전
# 이름을 붙인 나만의 임베드를 저장하고 버튼+모달로 편집합니다.
# =========================
with DB_MUTEX:
    c.execute("""
    CREATE TABLE IF NOT EXISTS custom_embeds (
        guild_id INTEGER,
        name TEXT,
        title TEXT,
        description TEXT,
        color INTEGER DEFAULT 8900346,
        author_text TEXT,
        author_icon TEXT,
        footer_text TEXT,
        footer_icon TEXT,
        thumbnail TEXT,
        image TEXT,
        use_timestamp INTEGER DEFAULT 0,
        created_by INTEGER,
        created_at TEXT,
        PRIMARY KEY (guild_id, name)
    )
    """)
    conn.commit()

MNB_EMBED_VAR_HELP = (
    "사용 가능한 변수: `{유저}`(멘션) · `{유저이름}` · `{유저아바타}`\n"
    "`{서버이름}` · `{서버아이콘}` · `{줄바꿈}`(줄바꿈)\n"
    "이모지: 디스코드에서 `\\이모지`로 나온 `:shortcode:` 코드나 커스텀 이모지 코드 `<:이름:숫자>`를 그대로 붙여넣으면 됩니다."
)


def mnb_convert_emoji_shortcodes(text: str) -> str:
    """디스코드에서 이모지 앞에 \\를 붙이면 나오는 :shortcode: 코드를 실제 이모지로 바꿔줍니다.
    커스텀 서버 이모지 코드(<:이름:숫자>, <a:이름:숫자>)는 디스코드가 알아서 그림으로 표시하므로 그대로 둡니다.
    """
    if not text or mnb_emoji_lib is None:
        return text
    try:
        return mnb_emoji_lib.emojize(text, language="alias")
    except Exception:
        return text


def mnb_embed_apply_variables(text: str, *, guild: discord.Guild = None, member=None) -> str:
    """미무봇처럼 {유저}, {서버이름} 같은 변수를 실제 값으로 치환하고, :shortcode: 이모지도 변환합니다."""
    if not text:
        return text
    replacements = {"{줄바꿈}": "\n", "{newline}": "\n"}
    if member is not None:
        try:
            replacements["{유저}"] = member.mention
            replacements["{유저이름}"] = member.display_name
            replacements["{유저아바타}"] = str(member.display_avatar.url)
        except Exception:
            pass
    if guild is not None:
        replacements["{서버이름}"] = guild.name
        replacements["{서버아이콘}"] = str(guild.icon.url) if guild.icon else ""
    for key, value in replacements.items():
        text = text.replace(key, value)
    return mnb_convert_emoji_shortcodes(text)


def mnb_embed_row_to_dict(row) -> dict:
    columns = [
        "guild_id", "name", "title", "description", "color",
        "author_text", "author_icon", "footer_text", "footer_icon",
        "thumbnail", "image", "use_timestamp", "created_by", "created_at",
    ]
    return dict(zip(columns, row))


def mnb_embed_get(guild_id: int, name: str):
    with DB_MUTEX:
        c.execute("SELECT * FROM custom_embeds WHERE guild_id=? AND name=?", (guild_id, name))
        row = c.fetchone()
    return mnb_embed_row_to_dict(row) if row else None


def mnb_embed_list(guild_id: int):
    with DB_MUTEX:
        c.execute("SELECT name FROM custom_embeds WHERE guild_id=? ORDER BY name", (guild_id,))
        rows = c.fetchall()
    return [r[0] for r in rows]


def mnb_embed_save_field(guild_id: int, name: str, **fields):
    if not fields:
        return
    with DB_MUTEX:
        assignments = ", ".join(f"{key}=?" for key in fields.keys())
        values = list(fields.values()) + [guild_id, name]
        c.execute(f"UPDATE custom_embeds SET {assignments} WHERE guild_id=? AND name=?", values)
        conn.commit()


def mnb_embed_build_discord_embed(data: dict, *, guild: discord.Guild = None, member=None) -> discord.Embed:
    title = mnb_embed_apply_variables(data.get("title") or "", guild=guild, member=member)
    description = mnb_embed_apply_variables(data.get("description") or "", guild=guild, member=member)
    color = data.get("color") or COLOR_SKY
    embed = discord.Embed(title=title or None, description=description or None, color=color)

    author_text = mnb_embed_apply_variables(data.get("author_text") or "", guild=guild, member=member)
    if author_text:
        embed.set_author(name=author_text, icon_url=data.get("author_icon") or None)

    footer_text = mnb_embed_apply_variables(data.get("footer_text") or "", guild=guild, member=member)
    if footer_text:
        embed.set_footer(text=footer_text, icon_url=data.get("footer_icon") or None)

    if data.get("thumbnail"):
        embed.set_thumbnail(url=data["thumbnail"])
    if data.get("image"):
        embed.set_image(url=data["image"])
    if data.get("use_timestamp"):
        embed.timestamp = datetime.datetime.now()

    if not embed.title and not embed.description and not embed.image and not embed.thumbnail:
        embed.description = "*(아직 내용이 비어있어요. 아래 버튼으로 편집해주세요.)*"
    return embed


# =========================
# 나만의 임베드를 환영/퇴장 메시지로 연결하기 (미무봇 {embed:이름} 대응 기능)
# 기존 환영/퇴장 메시지 로직은 그대로 두고, 연결된 이름이 있을 때만 대신 사용합니다.
# =========================
with DB_MUTEX:
    c.execute("""
    CREATE TABLE IF NOT EXISTS custom_embed_links (
        guild_id INTEGER,
        link_type TEXT,
        embed_name TEXT,
        PRIMARY KEY (guild_id, link_type)
    )
    """)
    conn.commit()

MNB_EMBED_LINK_TYPES = {"환영": "welcome", "퇴장": "goodbye"}


def mnb_embed_get_link(guild_id: int, link_type: str):
    with DB_MUTEX:
        c.execute(
            "SELECT embed_name FROM custom_embed_links WHERE guild_id=? AND link_type=?",
            (guild_id, link_type),
        )
        row = c.fetchone()
    return row[0] if row else None


def mnb_embed_set_link(guild_id: int, link_type: str, name: str):
    with DB_MUTEX:
        c.execute(
            "INSERT OR REPLACE INTO custom_embed_links (guild_id, link_type, embed_name) VALUES (?, ?, ?)",
            (guild_id, link_type, name),
        )
        conn.commit()


def mnb_embed_clear_link(guild_id: int, link_type: str):
    with DB_MUTEX:
        c.execute("DELETE FROM custom_embed_links WHERE guild_id=? AND link_type=?", (guild_id, link_type))
        conn.commit()


def mnb_embed_build_linked(guild: discord.Guild, member: discord.Member, link_type: str):
    """연결된 나만의 임베드가 있으면 그걸로 만든 Embed를, 없으면 None을 돌려줍니다."""
    if guild is None:
        return None
    name = mnb_embed_get_link(guild.id, link_type)
    if not name:
        return None
    data = mnb_embed_get(guild.id, name)
    if not data:
        return None
    return mnb_embed_build_discord_embed(data, guild=guild, member=member)


async def mnb_embed_refresh_panel(interaction: discord.Interaction, guild_id: int, name: str):
    data = mnb_embed_get(guild_id, name)
    if not data:
        await safe_interaction_send(interaction, "❌ 임베드를 찾을 수 없습니다.", ephemeral=True)
        return
    embed = mnb_embed_build_discord_embed(data, guild=interaction.guild, member=interaction.user)
    view = MNBEmbedEditView(guild_id, name)
    content = f"✏️ `{name}` 임베드를 편집 중이에요.\n{MNB_EMBED_VAR_HELP}"
    try:
        await interaction.response.edit_message(content=content, embed=embed, view=view)
    except discord.InteractionResponded:
        try:
            await interaction.edit_original_response(content=content, embed=embed, view=view)
        except Exception:
            await safe_interaction_send(interaction, content=content, embed=embed, view=view, ephemeral=True)
    except Exception:
        await safe_interaction_send(interaction, content=content, embed=embed, view=view, ephemeral=True)


class MNBEmbedBasicModal(discord.ui.Modal, title="기본 정보 수정"):
    def __init__(self, guild_id: int, name: str):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.name = name
        data = mnb_embed_get(guild_id, name) or {}
        self.title_input = discord.ui.TextInput(label="제목", required=False, max_length=256, default=data.get("title") or "")
        self.desc_input = discord.ui.TextInput(
            label="설명 (줄바꿈은 {줄바꿈} 사용)", style=discord.TextStyle.paragraph,
            required=False, max_length=4000, default=data.get("description") or "",
        )
        self.add_item(self.title_input)
        self.add_item(self.desc_input)

    async def on_submit(self, interaction: discord.Interaction):
        mnb_embed_save_field(
            self.guild_id, self.name,
            title=self.title_input.value.strip() or None,
            description=self.desc_input.value.strip() or None,
        )
        await mnb_embed_refresh_panel(interaction, self.guild_id, self.name)


