class MNBEmbedColorModal(discord.ui.Modal, title="색상 수정"):
    def __init__(self, guild_id: int, name: str):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.name = name
        data = mnb_embed_get(guild_id, name) or {}
        current = data.get("color") or COLOR_SKY
        self.color_input = discord.ui.TextInput(label="HEX 색상 코드 (예: #87CEFA)", required=False, max_length=7, default=f"#{current:06X}")
        self.add_item(self.color_input)

    async def on_submit(self, interaction: discord.Interaction):
        cleaned = self.color_input.value.strip().lstrip("#")
        if cleaned and not re.fullmatch(r"[0-9A-Fa-f]{6}", cleaned):
            await safe_interaction_send(interaction, "❌ HEX 색상은 `#87CEFA`처럼 입력해주세요.", ephemeral=True)
            return
        color_value = int(cleaned, 16) if cleaned else COLOR_SKY
        mnb_embed_save_field(self.guild_id, self.name, color=color_value)
        await mnb_embed_refresh_panel(interaction, self.guild_id, self.name)


class MNBEmbedEditView(discord.ui.View):
    def __init__(self, guild_id: int, name: str):
        super().__init__(timeout=600)
        self.guild_id = guild_id
        self.name = name

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await mnb_v227_can_manage_server(interaction.user):
            await safe_interaction_send(interaction, "❌ 관리자만 편집할 수 있습니다.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="기본 정보", style=discord.ButtonStyle.primary, emoji="📝", row=0)
    async def edit_basic(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MNBEmbedBasicModal(self.guild_id, self.name))

    @discord.ui.button(label="작성자", style=discord.ButtonStyle.secondary, emoji="👤", row=0)
    async def edit_author(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MNBEmbedAuthorModal(self.guild_id, self.name))

    @discord.ui.button(label="이미지", style=discord.ButtonStyle.secondary, emoji="🖼️", row=0)
    async def edit_image(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MNBEmbedImageModal(self.guild_id, self.name))

    @discord.ui.button(label="푸터", style=discord.ButtonStyle.secondary, emoji="🏷️", row=1)
    async def edit_footer(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MNBEmbedFooterModal(self.guild_id, self.name))

    @discord.ui.button(label="색상", style=discord.ButtonStyle.secondary, emoji="🎨", row=1)
    async def edit_color(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MNBEmbedColorModal(self.guild_id, self.name))

    @discord.ui.button(label="타임스탬프 켜기/끄기", style=discord.ButtonStyle.secondary, emoji="🕒", row=1)
    async def toggle_timestamp(self, interaction: discord.Interaction, button: discord.ui.Button):
        data = mnb_embed_get(self.guild_id, self.name)
        new_value = 0 if (data and data.get("use_timestamp")) else 1
        mnb_embed_save_field(self.guild_id, self.name, use_timestamp=new_value)
        await mnb_embed_refresh_panel(interaction, self.guild_id, self.name)

    @discord.ui.button(label="완료", style=discord.ButtonStyle.success, emoji="✅", row=2)
    async def finish(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        data = mnb_embed_get(self.guild_id, self.name)
        if data:
            embed = mnb_embed_build_discord_embed(data, guild=interaction.guild, member=interaction.user)
            content = f"✅ `{self.name}` 임베드 편집을 마쳤어요. `/나만의임베드 전송`으로 채널에 올릴 수 있어요."
        else:
            embed = mnb_simple_embed("⚠️ 오류", "임베드를 찾을 수 없습니다.", COLOR_WARNING)
            content = None
        await interaction.response.edit_message(content=content, embed=embed, view=self)


@custom_embed_group.command(name="만들기", description="이름을 가진 나만의 임베드를 만들고 버튼으로 편집합니다. (미무봇 embed create)")
@app_commands.describe(이름="임베드를 나중에 찾을 때 쓸 이름 (예: 규칙임베드)")
async def embed_group_custom_create(interaction: discord.Interaction, 이름: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await mnb_v227_can_manage_server(interaction.user):
        return await safe_interaction_send(interaction, "❌ 관리자만 사용할 수 있습니다.", ephemeral=True)

    name = 이름.strip()
    if not name:
        return await safe_interaction_send(interaction, "❌ 이름을 입력해주세요.", ephemeral=True)
    if len(name) > 50:
        return await safe_interaction_send(interaction, "❌ 이름은 50자 이하로 입력해주세요.", ephemeral=True)

    if mnb_embed_get(interaction.guild.id, name):
        return await safe_interaction_send(
            interaction,
            f"❌ `{name}` 이름의 임베드가 이미 있어요. `/나만의임베드 수정 이름:{name}`으로 편집하거나 다른 이름을 사용해주세요.",
            ephemeral=True,
        )

    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with DB_MUTEX:
        c.execute(
            "INSERT INTO custom_embeds (guild_id, name, color, created_by, created_at) VALUES (?, ?, ?, ?, ?)",
            (interaction.guild.id, name, COLOR_SKY, interaction.user.id, now),
        )
        conn.commit()

    data = mnb_embed_get(interaction.guild.id, name)
    embed = mnb_embed_build_discord_embed(data, guild=interaction.guild, member=interaction.user)
    view = MNBEmbedEditView(interaction.guild.id, name)
    await safe_interaction_send(
        interaction,
        content=f"✅ `{name}` 임베드를 만들었어요! 아래 버튼으로 내용을 채워주세요.\n{MNB_EMBED_VAR_HELP}",
        embed=embed,
        view=view,
        ephemeral=True,
    )


