@custom_embed_group.command(name="전송", description="저장된 임베드를 채널에 실제로 전송합니다. (미무봇 embed show)")
@app_commands.describe(이름="전송할 임베드 이름", 채널="비워두면 현재 채널에 전송합니다.")
async def embed_group_custom_show(interaction: discord.Interaction, 이름: str, 채널: discord.TextChannel = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await mnb_v227_can_manage_server(interaction.user):
        return await safe_interaction_send(interaction, "❌ 관리자만 사용할 수 있습니다.", ephemeral=True)

    name = 이름.strip()
    data = mnb_embed_get(interaction.guild.id, name)
    if not data:
        return await safe_interaction_send(interaction, f"❌ `{name}` 임베드를 찾을 수 없습니다.", ephemeral=True)

    target = 채널 or interaction.channel
    if not isinstance(target, discord.TextChannel):
        return await safe_interaction_send(interaction, "❌ 텍스트 채널을 선택해주세요.", ephemeral=True)

    embed = mnb_embed_build_discord_embed(data, guild=interaction.guild, member=interaction.user)
    try:
        await target.send(embed=embed)
        await safe_interaction_send(interaction, f"✅ `{name}` 임베드를 {target.mention}에 전송했어요.", ephemeral=True)
    except discord.Forbidden:
        await safe_interaction_send(interaction, "❌ 그 채널에 메시지를 보낼 권한이 없어요.", ephemeral=True)
    except Exception as e:
        await safe_interaction_send(interaction, f"❌ 전송 실패: `{str(e)[:500]}`", ephemeral=True)


@custom_embed_group.command(name="삭제", description="저장된 나만의 임베드를 삭제합니다.")
@app_commands.describe(이름="삭제할 임베드 이름")
async def embed_group_custom_delete(interaction: discord.Interaction, 이름: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await mnb_v227_can_manage_server(interaction.user):
        return await safe_interaction_send(interaction, "❌ 관리자만 사용할 수 있습니다.", ephemeral=True)

    name = 이름.strip()
    if not mnb_embed_get(interaction.guild.id, name):
        return await safe_interaction_send(interaction, f"❌ `{name}` 임베드를 찾을 수 없습니다.", ephemeral=True)

    with DB_MUTEX:
        c.execute("DELETE FROM custom_embeds WHERE guild_id=? AND name=?", (interaction.guild.id, name))
        conn.commit()
    await safe_interaction_send(interaction, f"🗑️ `{name}` 임베드를 삭제했어요.", ephemeral=True)


async def mnb_embed_quick_edit_guard(interaction: discord.Interaction, name: str):
    """임베드 존재 여부와 관리자 권한을 확인합니다. 통과하면 (guild_id, name)을, 실패하면 None을 돌려줍니다."""
    if interaction.guild is None:
        await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
        return None
    if not await mnb_v227_can_manage_server(interaction.user):
        await safe_interaction_send(interaction, "❌ 관리자만 사용할 수 있습니다.", ephemeral=True)
        return None
    name = name.strip()
    if not mnb_embed_get(interaction.guild.id, name):
        await safe_interaction_send(interaction, f"❌ `{name}` 임베드를 찾을 수 없습니다. `/나만의임베드 목록`으로 확인해주세요.", ephemeral=True)
        return None
    return interaction.guild.id, name


