# ---------- 2) 펫 탐험 파견 ----------
# pet_dispatch 컬럼에 JSON {"pet": 이름, "start": iso, "hours": n} 저장. 완료 후 수령하면 보상 지급.
RPG_DISPATCH_OPTIONS = [
    # (라벨, 시간(h), 기본 포인트, 경험치, 아이템후보)
    ("근교 순찰", 1, 400, 200, ["강화석", "낚시 미끼"]),
    ("숲속 탐험", 3, 1200, 600, ["강화석", "소환권", "세공석"]),
    ("던전 원정", 6, 2800, 1500, ["소환권", "각성석", "유물함"]),
    ("비경 탐사", 12, 6000, 3500, ["각성석", "유물함", "펫 진화석"]),
]


def rpg_get_dispatch(player: dict):
    raw = player.get("pet_dispatch") or ""
    if not raw:
        return None
    try:
        return json.loads(raw)
    except (ValueError, TypeError):
        return None


def rpg_dispatch_remaining(d: dict) -> float:
    """남은 시간(초). 0 이하이면 완료."""
    try:
        start = datetime.datetime.fromisoformat(d["start"])
    except (ValueError, KeyError, TypeError):
        return 0.0
    end = start + datetime.timedelta(hours=d.get("hours", 0))
    return (end - datetime.datetime.now()).total_seconds()


def rpg_build_dispatch_embed(guild_id: int, user_id: int) -> discord.Embed:
    player = get_or_create_rpg_player(guild_id, user_id)
    active_pet = player.get("active_pet_name") or ""
    d = rpg_get_dispatch(player)
    embed = discord.Embed(title="🧭 펫 탐험 파견", color=discord.Color.dark_teal())
    if d:
        remain = rpg_dispatch_remaining(d)
        if remain > 0:
            mins = int(remain // 60)
            embed.description = (
                f"🐾 **{d.get('pet','펫')}**이(가) **{d.get('label','탐험')}** 중이에요.\n"
                f"⏳ 남은 시간: 약 **{mins//60}시간 {mins%60}분**\n\n"
                "완료되면 이 패널에서 보상을 수령할 수 있어요."
            )
            embed.color = discord.Color.orange()
        else:
            embed.description = f"✅ **{d.get('pet','펫')}**의 **{d.get('label','탐험')}**이(가) 완료됐어요!\n아래 **보상 수령** 버튼을 누르세요."
            embed.color = discord.Color.green()
    else:
        if not active_pet:
            embed.description = "먼저 펫을 장착해야 파견을 보낼 수 있어요. (🐾 펫 장착)\n\n장착 후 아래에서 파견지를 선택하세요."
        else:
            lines = [f"🐾 파견 보낼 펫: **{active_pet}**\n", "아래에서 파견지를 선택하세요:"]
            for label, hours, pt, exp, items in RPG_DISPATCH_OPTIONS:
                lines.append(f"• **{label}** — {hours}시간 · 💰{pt:,}P · ✨{exp:,} · 🎁 {'/'.join(items)}")
            embed.description = "\n".join(lines)
    embed.set_footer(text="파견 중에는 펫 버프는 그대로 유지돼요 | 만능 봇 RPG")
    return embed


class RPGDispatchSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        options = [
            discord.SelectOption(label=f"{label} ({hours}시간)", value=str(i),
                                 description=f"{pt:,}P · {exp:,}EXP · {'/'.join(items)}")
            for i, (label, hours, pt, exp, items) in enumerate(RPG_DISPATCH_OPTIONS)
        ]
        super().__init__(placeholder="🧭 파견지 선택", min_values=1, max_values=1, options=options)

    async def callback(self, interaction):
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        active_pet = player.get("active_pet_name") or ""
        if not active_pet:
            return await interaction.response.send_message("❌ 먼저 펫을 장착하세요.", ephemeral=True)
        if rpg_get_dispatch(player):
            return await interaction.response.send_message("❌ 이미 파견 중인 펫이 있어요.", ephemeral=True)
        idx = int(self.values[0])
        label, hours, pt, exp, items = RPG_DISPATCH_OPTIONS[idx]
        data = {"pet": active_pet, "label": label, "start": datetime.datetime.now().isoformat(),
                "hours": hours, "pt": pt, "exp": exp, "items": items}
        save_rpg_player(self.guild_id, self.user_id, pet_dispatch=json.dumps(data, ensure_ascii=False))
        await interaction.response.edit_message(embed=rpg_build_dispatch_embed(self.guild_id, self.user_id),
                                                view=RPGDispatchView(self.guild_id, self.user_id))


class RPGDispatchView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=180)
        self.guild_id = guild_id
        self.user_id = user_id
        player = get_or_create_rpg_player(guild_id, user_id)
        d = rpg_get_dispatch(player)
        if d is None:
            if player.get("active_pet_name"):
                self.add_item(RPGDispatchSelect(guild_id, user_id))
        elif rpg_dispatch_remaining(d) <= 0:
            btn = discord.ui.Button(label="보상 수령", emoji="🎁", style=discord.ButtonStyle.success)
            btn.callback = self._claim
            self.add_item(btn)

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    async def _claim(self, interaction):
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        d = rpg_get_dispatch(player)
        if not d or rpg_dispatch_remaining(d) > 0:
            return await interaction.response.send_message("❌ 아직 수령할 수 없어요.", ephemeral=True)
        pt = d.get("pt", 0)
        exp = d.get("exp", 0)
        item = random.choice(d.get("items", ["강화석"]))
        item_amt = random.randint(1, 3)
        set_user_point(self.guild_id, self.user_id, get_user_point(self.guild_id, self.user_id) + pt)
        _lv, player = rpg_apply_exp(player, exp)
        add_inventory_item(self.user_id, item, item_amt, guild_id=self.guild_id)
        save_rpg_player(self.guild_id, self.user_id, pet_dispatch="",
                        level=player["level"], exp=player["exp"], max_hp=player["max_hp"], stat_points=player["stat_points"])
        await interaction.response.edit_message(
            embed=rpg_build_dispatch_embed(self.guild_id, self.user_id),
            view=RPGDispatchView(self.guild_id, self.user_id),
        )
        await interaction.followup.send(
            f"🎁 **{d.get('pet','펫')}**이(가) 돌아왔어요!\n💰 +{pt:,}P · ✨ +{exp:,} EXP · 📦 {item} {item_amt}개",
            ephemeral=True,
        )


# ---------- 3) 업적 / 도전과제 ----------
# (키, 이름, 설명, 진행도 함수(player)->현재값, 목표, 보상 포인트, 보상 아이템(이름,수량) 또는 None)
def _ach_progress_level(p): return p.get("level", 1)
def _ach_progress_pvp(p): return p.get("pvp_wins", 0) or 0
def _ach_progress_dungeon(p): return p.get("dungeon_floor", 0) or 0
def _ach_progress_rebirth(p): return p.get("rebirth", 0) or 0
def _ach_progress_streak(p): return p.get("daily_streak", 0) or 0

RPG_ACHIEVEMENTS = [
    ("lv10", "🌱 모험의 시작", "레벨 10 달성", _ach_progress_level, 10, 1000, ("소환권", 2)),
    ("lv50", "⚔️ 숙련된 모험가", "레벨 50 달성", _ach_progress_level, 50, 5000, ("각성석", 1)),
    ("lv100", "🏆 백전노장", "레벨 100 달성", _ach_progress_level, 100, 15000, ("유물함", 1)),
    ("pvp10", "🥊 결투가", "PvP 10승 달성", _ach_progress_pvp, 10, 3000, ("힘의비약", 3)),
    ("pvp50", "👑 투기장의 지배자", "PvP 50승 달성", _ach_progress_pvp, 50, 12000, ("세공석", 2)),
    ("dungeon10", "🏰 던전 탐험가", "던전 10층 돌파", _ach_progress_dungeon, 10, 4000, ("던전초기화권", 2)),
    ("dungeon30", "🗝️ 심층의 정복자", "던전 30층 돌파", _ach_progress_dungeon, 30, 10000, ("각성석", 2)),
    ("rebirth1", "♻️ 새로운 삶", "환생 1회", _ach_progress_rebirth, 1, 8000, ("전직서", 1)),
    ("streak7", "📅 성실한 모험가", "7일 연속 출석", _ach_progress_streak, 7, 3500, ("소환권", 3)),
]


def rpg_get_claimed_achievements(guild_id, user_id):
    with DB_MUTEX:
        c.execute("SELECT ach_key FROM rpg_achievements WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        return {r[0] for r in c.fetchall()}


def rpg_build_achievement_embed(guild_id, user_id) -> discord.Embed:
    player = get_or_create_rpg_player(guild_id, user_id)
    claimed = rpg_get_claimed_achievements(guild_id, user_id)
    lines = []
    for key, name, desc, prog_fn, target, pt, item in RPG_ACHIEVEMENTS:
        cur = prog_fn(player)
        done = cur >= target
        if key in claimed:
            mark = "✅ 수령완료"
        elif done:
            mark = "🎁 **수령 가능!**"
        else:
            mark = f"⬜ {min(cur, target)}/{target}"
        reward = f"💰{pt:,}P" + (f" · {item[0]}×{item[1]}" if item else "")
        lines.append(f"{mark} — **{name}**\n　{desc} · 보상 {reward}")
    embed = discord.Embed(
        title="🎯 RPG 업적",
        description="\n".join(lines),
        color=discord.Color.gold(),
    )
    claimable = sum(1 for k, _n, _d, fn, t, _p, _i in RPG_ACHIEVEMENTS if fn(player) >= t and k not in claimed)
    embed.set_footer(text=f"수령 가능한 업적 {claimable}개 · 아래 버튼으로 한 번에 수령 | 만능 봇 RPG")
    return embed


class RPGAchievementView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=120)
        self.guild_id = guild_id
        self.user_id = user_id

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="달성 업적 모두 수령", emoji="🎁", style=discord.ButtonStyle.success)
    async def claim_all(self, interaction, button):
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        claimed = rpg_get_claimed_achievements(self.guild_id, self.user_id)
        now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        total_pt = 0
        got = []
        for key, name, _desc, prog_fn, target, pt, item in RPG_ACHIEVEMENTS:
            if key in claimed or prog_fn(player) < target:
                continue
            total_pt += pt
            if item:
                add_inventory_item(self.user_id, item[0], item[1], guild_id=self.guild_id)
            with DB_MUTEX:
                c.execute("INSERT OR IGNORE INTO rpg_achievements(guild_id, user_id, ach_key, claimed_at) VALUES (?,?,?,?)",
                          (self.guild_id, self.user_id, key, now))
                conn.commit()
            got.append(name)
        if not got:
            return await interaction.response.send_message("수령할 수 있는 업적이 없어요. 더 성장해보세요!", ephemeral=True)
        if total_pt:
            set_user_point(self.guild_id, self.user_id, get_user_point(self.guild_id, self.user_id) + total_pt)
        await interaction.response.edit_message(embed=rpg_build_achievement_embed(self.guild_id, self.user_id), view=self)
        await interaction.followup.send(f"🎉 업적 {len(got)}개 수령! 💰 +{total_pt:,}P\n달성: {', '.join(got)}", ephemeral=True)


# ---------- 4) 주간 랭킹 보상 (자동 지급 루프) ----------
RPG_WEEKLY_REWARDS = [
    # 순위별 (포인트, 아이템, 수량)
    (50000, "각성석", 3),
    (30000, "각성석", 2),
    (20000, "유물함", 1),
]
RPG_WEEKLY_PARTICIPATION = (2000, "소환권", 1)  # TOP10 참가 보상


def _rpg_current_week_key() -> str:
    iso = datetime.date.today().isocalendar()
    return f"{iso[0]}-W{iso[1]:02d}"


@tasks.loop(hours=1)
async def rpg_weekly_reward_loop():
    """매주 월요일 새벽, 서버별 레벨 TOP10에게 주간 보상을 자동 지급합니다."""
    now = datetime.datetime.now()
    if now.weekday() != 0 or now.hour != 6:  # 월요일 06시대에만 동작
        return
    week_key = _rpg_current_week_key()
    for guild in bot.guilds:
        gid = guild.id
        with DB_MUTEX:
            c.execute("SELECT 1 FROM rpg_weekly_reward WHERE guild_id=? AND week_key=?", (gid, week_key))
            if c.fetchone():
                continue
            c.execute(
                "SELECT user_id, level, exp FROM rpg_players WHERE guild_id=? ORDER BY level DESC, exp DESC LIMIT 10",
                (gid,),
            )
            top = c.fetchall()
        if not top:
            continue
        winners = []
        for rank, (uid, lvl, _exp) in enumerate(top):
            if rank < len(RPG_WEEKLY_REWARDS):
                pt, item, amt = RPG_WEEKLY_REWARDS[rank]
            else:
                pt, item, amt = RPG_WEEKLY_PARTICIPATION
            set_user_point(gid, uid, get_user_point(gid, uid) + pt)
            add_inventory_item(uid, item, amt, guild_id=gid)
            winners.append((rank + 1, uid, pt, item, amt))
        with DB_MUTEX:
            c.execute("INSERT OR IGNORE INTO rpg_weekly_reward(guild_id, week_key, paid_at) VALUES (?,?,?)",
                      (gid, week_key, now.strftime("%Y-%m-%d %H:%M:%S")))
            conn.commit()
        # 안내 공지 (있으면 랭킹/공지 채널로)
        try:
            channel = guild.system_channel or next((ch for ch in guild.text_channels if ch.permissions_for(guild.me).send_messages), None)
            if channel:
                lines = [f"🏆 **{week_key} 주간 RPG 랭킹 보상 지급 완료!**"]
                medals = {1: "🥇", 2: "🥈", 3: "🥉"}
                for rank, uid, pt, item, amt in winners:
                    lines.append(f"{medals.get(rank, f'{rank}위')} <@{uid}> — 💰{pt:,}P · {item}×{amt}")
                await channel.send("\n".join(lines))
        except Exception:
            pass


@rpg_weekly_reward_loop.before_loop
async def _before_rpg_weekly_reward_loop():
    await bot.wait_until_ready()


def rpg_build_weekly_embed(guild_id: int) -> discord.Embed:
    with DB_MUTEX:
        c.execute("SELECT user_id, level, exp FROM rpg_players WHERE guild_id=? ORDER BY level DESC, exp DESC LIMIT 10", (guild_id,))
        top = c.fetchall()
    lines = []
    medals = {1: "🥇", 2: "🥈", 3: "🥉"}
    for rank, (uid, lvl, _exp) in enumerate(top, start=1):
        if rank <= len(RPG_WEEKLY_REWARDS):
            pt, item, amt = RPG_WEEKLY_REWARDS[rank - 1]
        else:
            pt, item, amt = RPG_WEEKLY_PARTICIPATION
        lines.append(f"{medals.get(rank, f'{rank}위')} <@{uid}> · Lv.{lvl} → 💰{pt:,}P · {item}×{amt}")
    embed = discord.Embed(
        title="📆 이번 주 RPG 랭킹 보상 예정",
        description="\n".join(lines) if lines else "아직 랭킹 데이터가 없어요.",
        color=discord.Color.blurple(),
    )
    embed.set_footer(text="매주 월요일 오전 6시에 레벨 TOP10에게 자동 지급됩니다 | 만능 봇 RPG")
    return embed


# ---------- 5) 일일 상점 (매일 랜덤 할인) ----------
RPG_DAILY_SHOP_SIZE = 5           # 매일 노출 상품 수
RPG_DAILY_SHOP_DISCOUNT = 0.30    # 30% 할인


def rpg_daily_shop_items(guild_id: int):
    """날짜+길드 기반으로 매일 고정되는 할인 상품 목록. [(item, price, discounted)]"""
    seed_src = f"{datetime.date.today().isoformat()}-{guild_id}"
    rng = random.Random(seed_src)
    pool = list(RPG_SHOP_ITEMS.items())
    picks = rng.sample(pool, min(RPG_DAILY_SHOP_SIZE, len(pool)))
    result = []
    for item, price in picks:
        discounted = max(1, int(price * (1 - RPG_DAILY_SHOP_DISCOUNT)))
        result.append((item, price, discounted))
    return result


def rpg_build_daily_shop_embed(guild_id: int) -> discord.Embed:
    items = rpg_daily_shop_items(guild_id)
    lines = []
    for item, price, disc in items:
        desc = RPG_SHOP_ITEM_DESC.get(item, "")
        lines.append(f"🏷️ **{item}** — ~~{price:,}P~~ → **{disc:,}P** (-{int(RPG_DAILY_SHOP_DISCOUNT*100)}%)\n　{desc}")
    embed = discord.Embed(
        title="🛒 오늘의 특가 상점",
        description="\n".join(lines) + "\n\n매일 자정에 상품이 새로 바뀌어요!",
        color=discord.Color.magenta(),
    )
    embed.set_footer(text="아래 메뉴에서 골라 할인가로 구매하세요 | 만능 봇 RPG")
    return embed


class RPGDailyShopSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        items = rpg_daily_shop_items(guild_id)
        options = [
            discord.SelectOption(label=f"{item} ({disc:,}P)", value=item,
                                 description=f"정가 {price:,}P → {disc:,}P 할인")
            for item, price, disc in items
        ]
        super().__init__(placeholder="🛒 구매할 특가 상품 선택", min_values=1, max_values=1, options=options)

    async def callback(self, interaction):
        item_name = self.values[0]
        items = dict((i, d) for i, _p, d in rpg_daily_shop_items(self.guild_id))
        price = items.get(item_name)
        if price is None:
            return await interaction.response.send_message("❌ 오늘 특가 목록에 없는 상품이에요. (자정에 갱신됐을 수 있어요)", ephemeral=True)
        cur = get_user_point(self.guild_id, self.user_id)
        if cur < price:
            return await interaction.response.send_message(f"❌ 포인트가 부족해요. (보유 {cur:,}P / 필요 {price:,}P)", ephemeral=True)
        set_user_point(self.guild_id, self.user_id, cur - price)
        add_inventory_item(self.user_id, item_name, 1, guild_id=self.guild_id)
        await interaction.response.send_message(f"✅ **{item_name}**을(를) 할인가 **{price:,}P**에 구매했어요! (잔액 {cur - price:,}P)", ephemeral=True)


class RPGDailyShopView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=180)
        self.guild_id = guild_id
        self.user_id = user_id
        self.add_item(RPGDailyShopSelect(guild_id, user_id))

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True


class RPGPanelGrowthSelect(discord.ui.Select):
    """성장·정비 계열 세부 기능 모음 (기존 셀렉트에 자리가 없어 별도 메뉴로 분리)."""

    def __init__(self):
        options = [
            discord.SelectOption(label="장신구 장착", value="장신구", emoji="💍"),
            discord.SelectOption(label="펫 각성(진화)", value="펫각성", emoji="🌟"),
            discord.SelectOption(label="전투 전술 설정", value="전술", emoji="🎯"),
            discord.SelectOption(label="커스텀 대장간(무기 조합)", value="커스텀대장간", emoji="🔨"),
            discord.SelectOption(label="커스텀 무기 보관함", value="무기보관", emoji="🗃️"),
            discord.SelectOption(label="차원 정보", value="차원", emoji="🌌"),
            discord.SelectOption(label="안전거래(에스크로)", value="거래", emoji="🤝"),
            discord.SelectOption(label="일일 보상(출석)", value="일일보상", emoji="📅"),
            discord.SelectOption(label="펫 탐험 파견", value="펫파견", emoji="🧭"),
            discord.SelectOption(label="업적/도전과제", value="업적", emoji="🎯"),
            discord.SelectOption(label="주간 랭킹 보상", value="주간보상", emoji="📆"),
            discord.SelectOption(label="오늘의 특가 상점", value="일일상점", emoji="🛒"),
        ]
        super().__init__(placeholder="🌟 성장·정비 · 일일보상 · 업적 · 특가상점", min_values=1, max_values=1, options=options, custom_id="rpg_panel_growth_v500")

    async def callback(self, interaction: discord.Interaction):
        key = self.values[0]
        gid, uid = interaction.guild.id, interaction.user.id
        if key == "장신구":
            await interaction.response.send_message(embed=rpg_build_accessory_embed(gid, uid), view=RPGAccessoryView(gid, uid), ephemeral=True)
        elif key == "펫각성":
            await interaction.response.send_message(embed=rpg_build_pet_awaken_embed(gid, uid), view=RPGPetAwakenView(gid, uid), ephemeral=True)
        elif key == "전술":
            player = get_or_create_rpg_player(gid, uid)
            await interaction.response.send_message(embed=rpg_build_tactic_embed(player), view=RPGTacticView(gid, uid), ephemeral=True)
        elif key == "커스텀대장간":
            await interaction.response.send_message(embed=rpg_build_custom_forge_embed(gid, uid), view=RPGCustomForgeView(gid, uid), ephemeral=True)
        elif key == "무기보관":
            await interaction.response.send_message(embed=rpg_build_weapon_storage_embed(gid, uid), view=RPGCustomWeaponStorageView(gid, uid), ephemeral=True)
        elif key == "차원":
            await interaction.response.send_message(embed=rpg_build_dimension_info_embed(gid, uid), ephemeral=True)
        elif key == "거래":
            await interaction.response.send_message(
                "🤝 안전거래를 시작할 상대를 아래에서 선택하세요. (아이템·포인트를 에스크로로 교환합니다)",
                view=RPGTradePartnerView(uid),
                ephemeral=True,
            )
        elif key == "일일보상":
            await interaction.response.send_message(embed=rpg_build_daily_embed(gid, uid), view=RPGDailyView(gid, uid), ephemeral=True)
        elif key == "펫파견":
            await interaction.response.send_message(embed=rpg_build_dispatch_embed(gid, uid), view=RPGDispatchView(gid, uid), ephemeral=True)
        elif key == "업적":
            await interaction.response.send_message(embed=rpg_build_achievement_embed(gid, uid), view=RPGAchievementView(gid, uid), ephemeral=True)
        elif key == "주간보상":
            await interaction.response.send_message(embed=rpg_build_weekly_embed(gid), ephemeral=True)
        elif key == "일일상점":
            await interaction.response.send_message(embed=rpg_build_daily_shop_embed(gid), view=RPGDailyShopView(gid, uid), ephemeral=True)


