@rpg_group.command(name="상점", description="RPG 전용 상점을 엽니다. (강화석·뽑기권·각성석·세공석 등, 개수 선택 구매)")
async def rpg_group_shop(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    embed = rpg_build_shop_embed(interaction.user.id, guild_id=interaction.guild.id)
    await safe_interaction_send(interaction, embed=embed, view=RPGShopView(), ephemeral=True)


async def rpg_show_inventory(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    user_id = interaction.user.id
    # RPG 소비 아이템
    consumables = []
    for item in RPG_SHOP_ITEMS:
        cnt = get_inventory_amount(user_id, item)
        if cnt > 0:
            consumables.append(f"{item} x{cnt}")
    # 드랍 재료
    materials = []
    total_value = 0
    for name, price in RPG_ITEM_SELL_PRICES.items():
        cnt = get_inventory_amount(user_id, name)
        if cnt > 0:
            materials.append(f"{name} x{cnt} ({price*cnt}P)")
            total_value += price * cnt

    embed = discord.Embed(title=f"🎒 {interaction.user.display_name}님의 RPG 인벤토리", color=discord.Color.teal())
    embed.set_thumbnail(url=interaction.user.display_avatar.url)
    embed.add_field(name="🧪 소비 아이템", value="\n".join(consumables) if consumables else "없음", inline=False)
    embed.add_field(
        name=f"💎 드랍 재료 (전체 {total_value:,}P)",
        value="\n".join(materials) if materials else "없음 · 사냥/보스로 모아보세요",
        inline=False,
    )
    embed.add_field(name="💰 보유 포인트", value=f"{get_user_point(interaction.guild.id, user_id):,}P", inline=True)
    embed.set_footer(text="드랍 재료는 /rpg 판매 로 포인트화 · 구매는 /rpg 상점 | 만능 봇 RPG")
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)


@rpg_group.command(name="인벤토리", description="내 RPG 아이템·드랍 재료·보유 포인트를 확인합니다.")
async def rpg_group_inventory(interaction: discord.Interaction):
    await rpg_show_inventory(interaction)


