# ---------- 🎽 통합 장비 패널 (무기 · 방어구 · 펫 한눈에) ----------
def rpg_build_equipment_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    try:
        rpg_sync_custom_weapon_storage(guild_id, user_id)
        player = get_or_create_rpg_player(guild_id, user_id)
    except Exception:
        pass

    # 무기 (기본 무기 + 커스텀 무기)
    w_lv = player.get("weapon_level", 1) or 1
    w_tier = rpg_rarity_tier(player.get("weapon_rarity", 0))
    w_elem = player.get("weapon_element") or ""
    elem_txt = f" · {w_elem}속성" if w_elem else ""
    weapon_line = f"{w_tier['emoji']} {w_tier['name']} 무기 **Lv.{w_lv}**{elem_txt}"
    cw = rpg_get_custom_weapon(player)
    if cw:
        weapon_line += (
            f"\n🛠️ 커스텀: **{cw['name']}** "
            f"(⚔️+{cw['power']} 🛡️+{cw['defense']} 💥+{cw['crit']*100:.0f}%)"
        )
    else:
        weapon_line += "\n🛠️ 커스텀: 미장착"
    stored_cnt = len(rpg_get_custom_weapons(guild_id, user_id))

    # 방어구
    a_lv = player.get("armor_level", 0) or 0
    a_tier = rpg_rarity_tier(player.get("armor_rarity", 0))
    armor_line = f"{a_tier['emoji']} {a_tier['name']} 방어구 **Lv.{a_lv}**"

    # 펫
    pet_name = player.get("active_pet_name") or ""
    if pet_name:
        st = rpg_get_pet_state(player, pet_name)
        pet_line = f"🐾 **{pet_name}** Lv.{st['level']} (+{rpg_pet_power_bonus(player)} 전투력)"
    else:
        pet_line = "🐾 장착한 펫 없음"

    # 장신구
    acc_id = player.get("accessory") or ""
    acc_entry = RPG_ACCESSORY_BY_ID.get(acc_id)
    if acc_entry:
        acc_line = f"💍 **{acc_entry['name']}** (⚔️+{acc_entry.get('power',0)} 🛡️+{acc_entry.get('defense',0)})"
    else:
        acc_line = "💍 장착한 장신구 없음"

    total_power = rpg_player_power(player)
    total_def = rpg_player_defense(player)

    embed = discord.Embed(
        title="🎽 내 장비",
        description=(
            f"⚔️ 총 전투력 **{total_power:,}** · 🛡️ 총 방어력 **{total_def:,}**\n"
            "아래 버튼으로 각 장비를 장착·교체하세요."
        ),
        color=discord.Color.blurple(),
    )
    embed.add_field(name="🗡️ 무기", value=f"{weapon_line}\n📦 커스텀 보관 {stored_cnt}개", inline=False)
    embed.add_field(name="🛡️ 방어구", value=armor_line, inline=False)
    embed.add_field(name="🐾 펫", value=pet_line, inline=False)
    embed.add_field(name="💍 장신구", value=acc_line, inline=False)
    embed.set_footer(text="/rpg 장비 · 커스텀 무기/펫/장신구를 한 곳에서 관리 | 만능 봇 RPG")
    return embed


