def rpg_build_accessory_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    cur_id = player.get("accessory") or ""
    lines = []
    for r in RPG_FORGE_RECIPES:
        if r["kind"] != "accessory":
            continue
        have = get_inventory_amount(user_id, r["name"])
        if have <= 0 and r["id"] != cur_id:
            continue
        mark = " ✅장착중" if r["id"] == cur_id else ""
        lines.append(f"{r['name']} (전투+{r['power']}/방어+{r['defense']}){mark}")
    desc = "\n".join(lines) if lines else "보유한 장신구가 없어요."
    embed = discord.Embed(title="💍 장신구 장착", description=desc + "\n\n아래 메뉴에서 장착할 장신구를 선택하세요.", color=discord.Color.gold())
    embed.set_footer(text="장신구는 전투력·방어력 고정 보너스를 줘요 | 만능 봇 RPG")
    return embed


class RPGAccessorySelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        player = get_or_create_rpg_player(guild_id, user_id)
        cur_id = player.get("accessory") or ""
        options = [discord.SelectOption(label="장신구 해제", value="__none__", emoji="⏹️", default=(cur_id == ""))]
        for r in RPG_FORGE_RECIPES:
            if r["kind"] != "accessory":
                continue
            have = get_inventory_amount(user_id, r["name"])
            if have <= 0 and r["id"] != cur_id:
                continue
            options.append(discord.SelectOption(
                label=r["name"][:100],
                description=f"전투+{r['power']}/방어+{r['defense']}"[:90],
                value=r["id"],
                default=(r["id"] == cur_id),
            ))
        super().__init__(placeholder="💍 장착할 장신구 선택", min_values=1, max_values=1, options=options[:25])

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.user_id:
            return await interaction.response.send_message("❌ 본인만 사용할 수 있어요.", ephemeral=True)
        val = self.values[0]
        if val == "__none__":
            save_rpg_player(self.guild_id, self.user_id, accessory="")
            msg = "💍 장신구를 해제했어요."
        else:
            entry = RPG_ACCESSORY_BY_ID.get(val)
            save_rpg_player(self.guild_id, self.user_id, accessory=val)
            msg = f"💍 **{entry['name']}** 장착 완료! (전투+{entry['power']}/방어+{entry['defense']})"
        await interaction.response.edit_message(
            embed=rpg_build_accessory_embed(self.guild_id, self.user_id),
            view=RPGAccessoryView(self.guild_id, self.user_id),
        )
        await interaction.followup.send(msg, ephemeral=True)


