# ---------- 길드 시스템 ----------
import uuid as _uuid_mod


# 6번: 길드 버프 — 길드 레벨/영지 레벨에 따라 소속원 전원이 받는 패시브 버프
def rpg_guild_buffs(guild_id, user_id) -> dict:
    """소속 길드의 레벨·영지 레벨 기반 버프 {키: 비율}. 미가입이면 빈 딕셔너리."""
    clan = rpg_get_my_clan(guild_id, user_id)
    if not clan:
        return {}
    full = rpg_get_clan_full(guild_id, clan["clan_id"])
    if not full:
        return {}
    glevel = full.get("level", 1) or 1
    tlevel = full.get("territory_level", 1) or 1
    # 길드 레벨당 공격/방어 +1%, 영지 레벨당 경험치/골드 +2%
    return {
        "power": 0.01 * glevel,
        "defense": 0.01 * glevel,
        "exp": 0.02 * tlevel,
        "gold": 0.02 * tlevel,
    }


def rpg_guild_buff(guild_id, user_id, key: str) -> float:
    return rpg_guild_buffs(guild_id, user_id).get(key, 0.0)


# 6번: 길드 상점 — 길드 자원으로 특별 아이템 구매 (길드장만)
RPG_GUILD_SHOP = [
    {"id": "gbuff_scroll", "name": "길드 강화 두루마리", "cost": 500, "reward_item": "강화석", "reward_amount": 10,
     "desc": "강화석 10개를 길드 보관함에 지급"},
    {"id": "gsummon", "name": "길드 소환권 꾸러미", "cost": 800, "reward_item": "소환권", "reward_amount": 5,
     "desc": "소환권 5개를 길드 보관함에 지급"},
    {"id": "grelic", "name": "길드 유물함", "cost": 2000, "reward_item": "유물함", "reward_amount": 3,
     "desc": "유물함 3개를 길드 보관함에 지급"},
    {"id": "gawaken", "name": "길드 각성석", "cost": 3000, "reward_item": "각성석", "reward_amount": 2,
     "desc": "각성석 2개를 길드 보관함에 지급"},
    {"id": "gpetstone", "name": "길드 펫 진화석", "cost": 3500, "reward_item": "펫 진화석", "reward_amount": 2,
     "desc": "펫 진화석 2개를 길드 보관함에 지급"},
]
RPG_GUILD_SHOP_BY_ID = {s["id"]: s for s in RPG_GUILD_SHOP}


def rpg_get_my_clan(guild_id, user_id):
    with DB_MUTEX:
        c.execute("SELECT clan_id FROM rpg_guild_members WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        row = c.fetchone()
    if not row:
        return None
    with DB_MUTEX:
        c.execute("SELECT clan_id, name, leader_id, level, exp, notice FROM rpg_guilds WHERE guild_id=? AND clan_id=?", (guild_id, row[0]))
        crow = c.fetchone()
    if not crow:
        return None
    return {"clan_id": crow[0], "name": crow[1], "leader_id": crow[2], "level": crow[3], "exp": crow[4], "notice": crow[5]}


def rpg_clan_members(guild_id, clan_id):
    with DB_MUTEX:
        c.execute("SELECT user_id, contribution FROM rpg_guild_members WHERE guild_id=? AND clan_id=? ORDER BY contribution DESC", (guild_id, clan_id))
        return c.fetchall()


def rpg_clan_by_name(guild_id, name):
    with DB_MUTEX:
        c.execute("SELECT clan_id, name, leader_id, level FROM rpg_guilds WHERE guild_id=? AND name=?", (guild_id, name))
        return c.fetchone()


def rpg_build_guild_embed(guild_id, user_id):
    clan = rpg_get_my_clan(guild_id, user_id)
    if not clan:
        with DB_MUTEX:
            c.execute("SELECT name, level FROM rpg_guilds WHERE guild_id=? ORDER BY level DESC, exp DESC LIMIT 10", (guild_id,))
            rows = c.fetchall()
        listing = "\n".join(f"• {n} (Lv.{lv})" for n, lv in rows) if rows else "아직 길드가 없어요."
        embed = discord.Embed(
            title="🏰 길드",
            description=f"소속된 길드가 없어요.\n\n**서버 길드 목록**\n{listing}\n\n아래 버튼으로 길드를 만들거나 가입하세요.",
            color=discord.Color.dark_blue(),
        )
        embed.set_footer(text="길드 생성 500P · 길드원 기여로 길드 성장 | 만능 봇 RPG")
        return embed
    members = rpg_clan_members(guild_id, clan["clan_id"])
    member_lines = []
    for uid, contrib in members[:15]:
        crown = "👑" if uid == clan["leader_id"] else "•"
        member_lines.append(f"{crown} <@{uid}> · 기여 {contrib:,}")
    need = clan["level"] * 1000
    embed = discord.Embed(
        title=f"🏰 {clan['name']} (Lv.{clan['level']})",
        description=(clan["notice"] or "_공지가 없어요_") + f"\n\n**길드 경험치** {clan['exp']:,}/{need:,}\n{rpg_progress_bar(clan['exp'], need)}",
        color=discord.Color.dark_blue(),
    )
    embed.add_field(name=f"👥 길드원 ({len(members)}명)", value="\n".join(member_lines), inline=False)
    embed.set_footer(text="기여하기 버튼으로 포인트를 길드 경험치로 전환 | 만능 봇 RPG")
    return embed


class RPGGuildCreateModal(discord.ui.Modal, title="길드 만들기"):
    clan_name = discord.ui.TextInput(label="길드 이름", max_length=20, placeholder="예: 불꽃의 기사단")

    def __init__(self, guild_id, user_id):
        super().__init__()
        self.guild_id = guild_id
        self.user_id = user_id

    async def on_submit(self, interaction: discord.Interaction):
        name = str(self.clan_name).strip()
        if not name:
            return await interaction.response.send_message("이름을 입력해주세요.", ephemeral=True)
        if rpg_get_my_clan(self.guild_id, self.user_id):
            return await interaction.response.send_message("이미 길드에 소속돼 있어요.", ephemeral=True)
        if rpg_clan_by_name(self.guild_id, name):
            return await interaction.response.send_message("같은 이름의 길드가 이미 있어요.", ephemeral=True)
        if get_user_point(self.guild_id, self.user_id) < 500:
            return await interaction.response.send_message("길드 생성 비용 500P가 부족해요.", ephemeral=True)
        set_user_point(self.guild_id, self.user_id, get_user_point(self.guild_id, self.user_id) - 500)
        clan_id = _uuid_mod.uuid4().hex[:12]
        now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with DB_MUTEX:
            c.execute("INSERT INTO rpg_guilds (guild_id, clan_id, name, leader_id, level, exp, notice, created_at) VALUES (?,?,?,?,1,0,'',?)",
                      (self.guild_id, clan_id, name, self.user_id, now))
            c.execute("INSERT OR REPLACE INTO rpg_guild_members (guild_id, user_id, clan_id, contribution, joined_at) VALUES (?,?,?,0,?)",
                      (self.guild_id, self.user_id, clan_id, now))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_embed(self.guild_id, self.user_id), view=RPGGuildView(self.guild_id, self.user_id))


class RPGGuildJoinSelect(discord.ui.Select):
    def __init__(self, guild_id):
        with DB_MUTEX:
            c.execute("SELECT clan_id, name, level FROM rpg_guilds WHERE guild_id=? ORDER BY level DESC LIMIT 25", (guild_id,))
            rows = c.fetchall()
        options = [discord.SelectOption(label=n[:100], description=f"Lv.{lv}", value=cid) for cid, n, lv in rows] or [discord.SelectOption(label="가입 가능한 길드 없음", value="__none__")]
        super().__init__(placeholder="가입할 길드 선택", min_values=1, max_values=1, options=options, row=1)

    async def callback(self, interaction: discord.Interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        gid, uid = interaction.guild.id, interaction.user.id
        if rpg_get_my_clan(gid, uid):
            return await interaction.response.send_message("이미 길드에 소속돼 있어요.", ephemeral=True)
        now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with DB_MUTEX:
            c.execute("INSERT OR REPLACE INTO rpg_guild_members (guild_id, user_id, clan_id, contribution, joined_at) VALUES (?,?,?,0,?)",
                      (gid, uid, self.values[0], now))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_embed(gid, uid), view=RPGGuildView(gid, uid))


class RPGGuildView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        clan = rpg_get_my_clan(guild_id, user_id)
        if not clan:
            self.add_item(RPGGuildJoinSelect(guild_id))

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="길드 만들기(500P)", emoji="🏰", style=discord.ButtonStyle.success, row=0)
    async def create_btn(self, interaction, button):
        if rpg_get_my_clan(self.guild_id, self.user_id):
            return await interaction.response.send_message("이미 길드에 소속돼 있어요.", ephemeral=True)
        await interaction.response.send_modal(RPGGuildCreateModal(self.guild_id, self.user_id))

    @discord.ui.button(label="기여하기(1000P→경험치)", emoji="💪", style=discord.ButtonStyle.primary, row=0)
    async def contrib_btn(self, interaction, button):
        clan = rpg_get_my_clan(self.guild_id, self.user_id)
        if not clan:
            return await interaction.response.send_message("먼저 길드에 가입해주세요.", ephemeral=True)
        if get_user_point(self.guild_id, self.user_id) < 1000:
            return await interaction.response.send_message("기여에 필요한 1000P가 부족해요.", ephemeral=True)
        set_user_point(self.guild_id, self.user_id, get_user_point(self.guild_id, self.user_id) - 1000)
        new_exp = clan["exp"] + 1000
        new_level = clan["level"]
        while new_exp >= new_level * 1000:
            new_exp -= new_level * 1000
            new_level += 1
        with DB_MUTEX:
            c.execute("UPDATE rpg_guilds SET level=?, exp=? WHERE guild_id=? AND clan_id=?", (new_level, new_exp, self.guild_id, clan["clan_id"]))
            c.execute("UPDATE rpg_guild_members SET contribution=contribution+1000 WHERE guild_id=? AND user_id=?", (self.guild_id, self.user_id))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_embed(self.guild_id, self.user_id), view=RPGGuildView(self.guild_id, self.user_id))

    @discord.ui.button(label="탈퇴", emoji="🚪", style=discord.ButtonStyle.danger, row=0)
    async def leave_btn(self, interaction, button):
        clan = rpg_get_my_clan(self.guild_id, self.user_id)
        if not clan:
            return await interaction.response.send_message("소속된 길드가 없어요.", ephemeral=True)
        with DB_MUTEX:
            c.execute("DELETE FROM rpg_guild_members WHERE guild_id=? AND user_id=?", (self.guild_id, self.user_id))
            # 리더가 나가면 길드 해산
            if clan["leader_id"] == self.user_id:
                c.execute("DELETE FROM rpg_guilds WHERE guild_id=? AND clan_id=?", (self.guild_id, clan["clan_id"]))
                c.execute("DELETE FROM rpg_guild_members WHERE guild_id=? AND clan_id=?", (self.guild_id, clan["clan_id"]))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_embed(self.guild_id, self.user_id), view=RPGGuildView(self.guild_id, self.user_id))


