RPG_PARTY_MAX_MEMBERS = 4
RPG_PARTY_EXP_BONUS = 0.15   # 파티원 1명당 경험치/골드 +15% (본인 포함 최대치 제한)


def rpg_get_my_party(guild_id, user_id):
    with DB_MUTEX:
        c.execute("SELECT party_id FROM rpg_party_members WHERE guild_id=? AND user_id=?", (guild_id, user_id))
        row = c.fetchone()
    if not row:
        return None
    with DB_MUTEX:
        c.execute("SELECT party_id, leader_id, name FROM rpg_parties WHERE guild_id=? AND party_id=?", (guild_id, row[0]))
        prow = c.fetchone()
    if not prow:
        return None
    return {"party_id": prow[0], "leader_id": prow[1], "name": prow[2]}


def rpg_party_members(guild_id, party_id):
    with DB_MUTEX:
        c.execute("SELECT user_id FROM rpg_party_members WHERE guild_id=? AND party_id=?", (guild_id, party_id))
        return [r[0] for r in c.fetchall()]


def rpg_party_size(guild_id, user_id):
    """본인이 속한 파티의 인원 수 (없으면 1)."""
    party = rpg_get_my_party(guild_id, user_id)
    if not party:
        return 1
    return len(rpg_party_members(guild_id, party["party_id"]))


def rpg_party_exp_multiplier(guild_id, user_id):
    """파티 인원에 따른 경험치/골드 배율."""
    size = rpg_party_size(guild_id, user_id)
    if size <= 1:
        return 1.0
    return 1.0 + RPG_PARTY_EXP_BONUS * (size - 1)


def rpg_build_party_embed(guild_id, user_id):
    party = rpg_get_my_party(guild_id, user_id)
    if not party:
        embed = discord.Embed(
            title="🧑‍🤝‍🧑 파티",
            description=(
                "아직 파티가 없어요.\n\n"
                "파티를 만들면 함께 사냥할 때 **경험치·골드 보너스**를 받아요.\n"
                f"(파티원 1명당 +{int(RPG_PARTY_EXP_BONUS*100)}%, 최대 {RPG_PARTY_MAX_MEMBERS}명)\n\n"
                "아래 버튼으로 파티를 만들거나, 초대를 받아 가입하세요."
            ),
            color=discord.Color.green(),
        )
        embed.set_footer(text="만능 봇 | RPG 파티")
        return embed
    members = rpg_party_members(guild_id, party["party_id"])
    mult = rpg_party_exp_multiplier(guild_id, user_id)
    lines = []
    for uid in members:
        crown = "👑" if uid == party["leader_id"] else "•"
        lines.append(f"{crown} <@{uid}>")
    embed = discord.Embed(
        title=f"🧑‍🤝‍🧑 {party['name']}",
        description="\n".join(lines) + f"\n\n현재 경험치·골드 보너스: **+{int((mult-1)*100)}%** ({len(members)}/{RPG_PARTY_MAX_MEMBERS}명)",
        color=discord.Color.green(),
    )
    embed.set_footer(text="함께 사냥/보스전을 하면 보너스가 적용돼요 | 만능 봇 RPG")
    return embed


class RPGPartyCreateModal(discord.ui.Modal, title="파티 만들기"):
    pname = discord.ui.TextInput(label="파티 이름", max_length=20, placeholder="예: 드래곤 헌터즈")

    def __init__(self, guild_id, user_id):
        super().__init__()
        self.guild_id = guild_id
        self.user_id = user_id

    async def on_submit(self, interaction):
        if rpg_get_my_party(self.guild_id, self.user_id):
            return await interaction.response.send_message("이미 파티에 속해 있어요.", ephemeral=True)
        name = str(self.pname).strip() or "이름없는 파티"
        party_id = _uuid_mod.uuid4().hex[:12]
        now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with DB_MUTEX:
            c.execute("INSERT INTO rpg_parties (guild_id, party_id, leader_id, name, created_at) VALUES (?,?,?,?,?)",
                      (self.guild_id, party_id, self.user_id, name, now))
            c.execute("INSERT OR REPLACE INTO rpg_party_members (guild_id, user_id, party_id, joined_at) VALUES (?,?,?,?)",
                      (self.guild_id, self.user_id, party_id, now))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_party_embed(self.guild_id, self.user_id), view=RPGPartyView(self.guild_id, self.user_id))


class RPGPartyInviteModal(discord.ui.Modal, title="파티원 초대"):
    target = discord.ui.TextInput(label="초대할 사람 (@멘션 또는 유저ID)", placeholder="@친구 또는 123456789")

    def __init__(self, guild_id, user_id):
        super().__init__()
        self.guild_id = guild_id
        self.user_id = user_id

    async def on_submit(self, interaction):
        party = rpg_get_my_party(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("먼저 파티를 만들어주세요.", ephemeral=True)
        if party["leader_id"] != self.user_id:
            return await interaction.response.send_message("파티장만 초대할 수 있어요.", ephemeral=True)
        if len(rpg_party_members(self.guild_id, party["party_id"])) >= RPG_PARTY_MAX_MEMBERS:
            return await interaction.response.send_message(f"파티가 가득 찼어요. (최대 {RPG_PARTY_MAX_MEMBERS}명)", ephemeral=True)
        m = re.search(r"\d{15,25}", str(self.target))
        if not m:
            return await interaction.response.send_message("@멘션이나 유저ID로 입력하세요.", ephemeral=True)
        target_id = int(m.group())
        if rpg_get_my_party(self.guild_id, target_id):
            return await interaction.response.send_message("그 사람은 이미 다른 파티에 있어요.", ephemeral=True)
        embed = discord.Embed(
            title="🧑‍🤝‍🧑 파티 초대",
            description=f"<@{target_id}> 님, **{party['name']}** 파티에 초대받았어요!\n아래 버튼으로 수락하세요. (60초)",
            color=discord.Color.green(),
        )
        await interaction.response.send_message(content=f"<@{target_id}>", embed=embed, view=RPGPartyInviteAcceptView(self.guild_id, party["party_id"], target_id))


class RPGPartyInviteAcceptView(discord.ui.View):
    def __init__(self, guild_id, party_id, target_id):
        super().__init__(timeout=60)
        self.guild_id = guild_id
        self.party_id = party_id
        self.target_id = target_id

    async def interaction_check(self, interaction):
        if interaction.user.id != self.target_id:
            await interaction.response.send_message("이 초대의 대상만 수락할 수 있어요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="파티 수락", emoji="✅", style=discord.ButtonStyle.success)
    async def accept(self, interaction, button):
        if rpg_get_my_party(self.guild_id, self.target_id):
            return await interaction.response.edit_message(content="이미 파티에 속해 있어요.", embed=None, view=None)
        with DB_MUTEX:
            c.execute("SELECT COUNT(*) FROM rpg_party_members WHERE guild_id=? AND party_id=?", (self.guild_id, self.party_id))
            if c.fetchone()[0] >= RPG_PARTY_MAX_MEMBERS:
                return await interaction.response.edit_message(content="파티가 가득 찼어요.", embed=None, view=None)
            now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            c.execute("INSERT OR REPLACE INTO rpg_party_members (guild_id, user_id, party_id, joined_at) VALUES (?,?,?,?)",
                      (self.guild_id, self.target_id, self.party_id, now))
            conn.commit()
        await interaction.response.edit_message(content=f"✅ {interaction.user.display_name} 님이 파티에 합류했어요!", embed=None, view=None)

    @discord.ui.button(label="거절", emoji="✖️", style=discord.ButtonStyle.danger)
    async def decline(self, interaction, button):
        await interaction.response.edit_message(content="파티 초대를 거절했어요.", embed=None, view=None)


