# ---------- 종족 선택 패널 ----------
def rpg_build_race_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    cur = RPG_RACES.get(player.get("race") or "")
    lines = []
    for rid, r in RPG_RACES.items():
        bonus_text = ", ".join(f"{k}+{int(v*100)}%" if v > 0 else f"{k}{int(v*100)}%" for k, v in r["bonus"].items())
        mark = " ⭐" if cur and player["race"] == rid else ""
        lines.append(f"{r['emoji']} **{r['name']}**{mark} — {r['desc']}\n└ {bonus_text}")
    desc = "\n".join(lines)
    title = f"🧬 종족 (현재: {cur['name'] if cur else '미선택'})"
    embed = discord.Embed(title=title, description=desc, color=discord.Color.teal())
    embed.set_footer(text="종족은 최초 1회 무료 선택 · 이후 변경은 종족변경권 필요 | 만능 봇 RPG")
    return embed


class RPGRaceSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        player = get_or_create_rpg_player(guild_id, user_id)
        cur = player.get("race") or ""
        options = [
            discord.SelectOption(label=f"{r['emoji']} {r['name']}", description=r["desc"][:90], value=rid, default=(rid == cur))
            for rid, r in RPG_RACES.items()
        ]
        super().__init__(placeholder="종족 선택", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction):
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        already = player.get("race") or ""
        new_race = self.values[0]
        if already and already != new_race:
            # 변경은 종족변경권 필요
            if get_inventory_amount(self.user_id, "종족변경권") < 1:
                return await interaction.response.send_message("❌ 종족을 바꾸려면 **종족변경권**이 필요해요. (최초 선택만 무료)", ephemeral=True)
            consume_inventory_item(self.user_id, "종족변경권", 1)
        save_rpg_player(self.guild_id, self.user_id, race=new_race)
        embed = rpg_build_race_embed(self.guild_id, self.user_id)
        r = RPG_RACES[new_race]
        embed.description = f"✅ **{r['name']}** 종족을 선택했어요!\n\n" + (embed.description or "")
        await interaction.response.edit_message(embed=embed, view=RPGRaceView(self.guild_id, self.user_id))


