# ---------- 퍽 트리 패널 ----------
def rpg_build_perk_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    taken = rpg_parse_perks(player)
    points = player.get("perk_points") or 0
    lines = []
    for pid, (name, desc, prereq, bonus, cost) in RPG_PERK_TREE.items():
        if pid in taken:
            mark = "✅"
        elif prereq and prereq not in taken:
            mark = "🔒"
        elif points >= cost:
            mark = "🟢"
        else:
            mark = "⬜"
        pre_text = f" (선행: {RPG_PERK_TREE[prereq][0]})" if prereq else ""
        lines.append(f"{mark} **{name}** · {cost}P — {desc}{pre_text}")
    embed = discord.Embed(
        title=f"🌳 스킬트리 · 퍽 (보유 퍽포인트: {points}P)",
        description="\n".join(lines) + f"\n\n5레벨마다 퍽포인트 1개를 얻어요. 아래 메뉴에서 습득하세요.\n✅습득 · 🟢가능 · ⬜포인트부족 · 🔒선행필요",
        color=discord.Color.dark_green(),
    )
    embed.set_footer(text="만능 봇 | RPG 퍽 트리")
    return embed


class RPGPerkSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        player = get_or_create_rpg_player(guild_id, user_id)
        taken = rpg_parse_perks(player)
        options = []
        for pid, (name, desc, prereq, bonus, cost) in RPG_PERK_TREE.items():
            if pid in taken:
                continue
            can, _reason = rpg_can_take_perk(player, pid)
            emoji = "🟢" if can else "🔒"
            options.append(discord.SelectOption(label=f"{name} ({cost}P)"[:100], description=desc[:90], value=pid, emoji=emoji))
        if not options:
            options = [discord.SelectOption(label="습득 가능한 퍽 없음", value="__none__")]
        super().__init__(placeholder="습득할 퍽 선택", min_values=1, max_values=1, options=options[:25], row=0)

    async def callback(self, interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        can, reason = rpg_can_take_perk(player, self.values[0])
        if not can:
            return await interaction.response.send_message(f"❌ {reason}", ephemeral=True)
        node = RPG_PERK_TREE[self.values[0]]
        taken = rpg_parse_perks(player)
        taken.add(self.values[0])
        save_rpg_player(self.guild_id, self.user_id, perks=",".join(taken), perk_points=player["perk_points"] - node[4])
        embed = rpg_build_perk_embed(self.guild_id, self.user_id)
        embed.description = f"✅ **{node[0]}** 습득!\n\n" + (embed.description or "")
        await interaction.response.edit_message(embed=embed, view=RPGPerkView(self.guild_id, self.user_id))


class RPGPerkView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=300)
        self.user_id = user_id
        self.add_item(RPGPerkSelect(guild_id, user_id))

