# ---------- 원소 조합 마법 패널 ----------
def rpg_build_element_embed():
    combo_lines = []
    for combo_set, (name, mult, desc) in RPG_ELEMENT_COMBOS.items():
        e1, e2 = list(combo_set)
        emo1 = RPG_ELEMENTS[e1]["emoji"]
        emo2 = RPG_ELEMENTS[e2]["emoji"]
        combo_lines.append(f"{emo1}+{emo2} → **{name}** (x{mult}) · {desc}")
    embed = discord.Embed(
        title="🔮 원소 조합 마법",
        description=(
            "두 가지 원소를 조합해 강력한 상위 마법을 발동해요!\n"
            "아래 메뉴에서 원소 2개를 골라 조합을 확인하세요.\n\n"
            + "\n".join(combo_lines)
        ),
        color=discord.Color.purple(),
    )
    embed.set_footer(text="조합 마법은 사냥/보스전에서 예약해 사용해요 | 만능 봇 RPG")
    return embed


class RPGElementSelect(discord.ui.Select):
    def __init__(self, order):
        self.order = order
        options = [discord.SelectOption(label=f"{r['emoji']} {r['name']}", value=eid) for eid, r in RPG_ELEMENTS.items()]
        super().__init__(placeholder=f"{order}번째 원소 선택", min_values=1, max_values=1, options=options, row=order - 1)

    async def callback(self, interaction):
        view: "RPGElementView" = self.view
        if self.order == 1:
            view.e1 = self.values[0]
        else:
            view.e2 = self.values[0]
        embed = rpg_build_element_embed()
        if view.e1 and view.e2:
            if view.e1 == view.e2:
                embed.add_field(name="결과", value="⚠️ 서로 다른 원소 2개를 골라야 해요.", inline=False)
            else:
                combo = rpg_element_combo(view.e1, view.e2)
                if combo:
                    name, mult, desc = combo
                    embed.add_field(name="✨ 조합 성공!", value=f"**{name}** (피해 x{mult})\n{desc}", inline=False)
                else:
                    embed.add_field(name="결과", value="이 조합은 아직 발견되지 않았어요.", inline=False)
        await interaction.response.edit_message(embed=embed, view=view)


class RPGElementView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=300)
        self.e1 = None
        self.e2 = None
        self.add_item(RPGElementSelect(1))
        self.add_item(RPGElementSelect(2))


# ============================================================
RPG_TERRITORY_UPGRADE_COST = 5000   # 영지 레벨업 기본 비용(자원)
RPG_TERRITORY_MAX_LEVEL = 20


def rpg_get_clan_full(guild_id, clan_id):
    with DB_MUTEX:
        c.execute("SELECT clan_id, name, leader_id, level, exp, notice, territory_level, resources, war_wins, war_losses FROM rpg_guilds WHERE guild_id=? AND clan_id=?", (guild_id, clan_id))
        row = c.fetchone()
    if not row:
        return None
    keys = ["clan_id", "name", "leader_id", "level", "exp", "notice", "territory_level", "resources", "war_wins", "war_losses"]
    return dict(zip(keys, row))


def rpg_build_guild_mgmt_embed(guild_id, user_id):
    party = rpg_get_my_clan(guild_id, user_id)
    if not party:
        return discord.Embed(title="🏰 길드 경영", description="먼저 길드에 가입해야 경영 기능을 쓸 수 있어요. (🏰길드 메뉴에서 생성/가입)", color=discord.Color.dark_blue())
    clan = rpg_get_clan_full(guild_id, party["clan_id"])
    terr_cost = RPG_TERRITORY_UPGRADE_COST * clan["territory_level"]
    embed = discord.Embed(
        title=f"🏰 {clan['name']} 경영",
        description=(
            f"🏙️ 영지 레벨: **{clan['territory_level']}** / {RPG_TERRITORY_MAX_LEVEL}\n"
            f"📦 길드 자원: **{clan['resources']:,}**\n"
            f"⚔️ 길드전 전적: {clan['war_wins']}승 {clan['war_losses']}패\n\n"
            f"영지를 올리면 길드원 전체가 보너스를 받아요.\n"
            f"다음 영지 레벨업 비용: 자원 **{terr_cost:,}**"
        ),
        color=discord.Color.dark_blue(),
    )
    embed.set_footer(text="자원은 기부/생산으로 모아요 · 리더만 영지 업글/외교/선전포고 | 만능 봇 RPG")
    return embed


class RPGGuildMgmtView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="자원 기부(1000P→100자원)", emoji="📦", style=discord.ButtonStyle.success, row=0)
    async def donate(self, interaction, button):
        party = rpg_get_my_clan(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("길드에 가입해주세요.", ephemeral=True)
        if get_user_point(self.guild_id, self.user_id) < 1000:
            return await interaction.response.send_message("1000P가 부족해요.", ephemeral=True)
        set_user_point(self.guild_id, self.user_id, get_user_point(self.guild_id, self.user_id) - 1000)
        with DB_MUTEX:
            c.execute("UPDATE rpg_guilds SET resources=resources+100 WHERE guild_id=? AND clan_id=?", (self.guild_id, party["clan_id"]))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_mgmt_embed(self.guild_id, self.user_id), view=RPGGuildMgmtView(self.guild_id, self.user_id))

    @discord.ui.button(label="영지 레벨업", emoji="🏙️", style=discord.ButtonStyle.primary, row=0)
    async def upgrade(self, interaction, button):
        party = rpg_get_my_clan(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("길드에 가입해주세요.", ephemeral=True)
        clan = rpg_get_clan_full(self.guild_id, party["clan_id"])
        if clan["leader_id"] != self.user_id:
            return await interaction.response.send_message("영지 업그레이드는 길드장만 가능해요.", ephemeral=True)
        if clan["territory_level"] >= RPG_TERRITORY_MAX_LEVEL:
            return await interaction.response.send_message("이미 최대 영지 레벨이에요.", ephemeral=True)
        cost = RPG_TERRITORY_UPGRADE_COST * clan["territory_level"]
        if clan["resources"] < cost:
            return await interaction.response.send_message(f"자원이 부족해요. (필요 {cost:,})", ephemeral=True)
        with DB_MUTEX:
            c.execute("UPDATE rpg_guilds SET resources=resources-?, territory_level=territory_level+1 WHERE guild_id=? AND clan_id=?", (cost, self.guild_id, party["clan_id"]))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_mgmt_embed(self.guild_id, self.user_id), view=RPGGuildMgmtView(self.guild_id, self.user_id))

    @discord.ui.button(label="길드 보관함", emoji="🗄️", style=discord.ButtonStyle.secondary, row=1)
    async def storage(self, interaction, button):
        party = rpg_get_my_clan(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("길드에 가입해주세요.", ephemeral=True)
        await interaction.response.send_message(embed=rpg_build_guild_storage_embed(self.guild_id, party["clan_id"]), view=RPGGuildStorageView(self.guild_id, self.user_id, party["clan_id"]), ephemeral=True)

    @discord.ui.button(label="외교/전쟁", emoji="⚔️", style=discord.ButtonStyle.danger, row=1)
    async def diplomacy(self, interaction, button):
        party = rpg_get_my_clan(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("길드에 가입해주세요.", ephemeral=True)
        await interaction.response.send_message(embed=rpg_build_diplomacy_embed(self.guild_id, party["clan_id"]), view=RPGDiplomacyView(self.guild_id, self.user_id, party["clan_id"]), ephemeral=True)

    @discord.ui.button(label="길드 상점", emoji="🏪", style=discord.ButtonStyle.success, row=2)
    async def guild_shop(self, interaction, button):
        party = rpg_get_my_clan(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("길드에 가입해주세요.", ephemeral=True)
        await interaction.response.send_message(embed=rpg_build_guild_shop_embed(self.guild_id, party["clan_id"]), view=RPGGuildShopView(self.guild_id, self.user_id, party["clan_id"]), ephemeral=True)

    @discord.ui.button(label="길드 버프", emoji="✨", style=discord.ButtonStyle.primary, row=2)
    async def guild_buff(self, interaction, button):
        await interaction.response.send_message(embed=rpg_build_guild_buff_embed(self.guild_id, self.user_id), ephemeral=True)

    @discord.ui.button(label="길드 레이드", emoji="🐲", style=discord.ButtonStyle.danger, row=2)
    async def guild_raid(self, interaction, button):
        party = rpg_get_my_clan(self.guild_id, self.user_id)
        if not party:
            return await interaction.response.send_message("길드에 가입해주세요.", ephemeral=True)
        await interaction.response.send_message(embed=rpg_build_guild_raid_embed(self.guild_id, party["clan_id"]), view=RPGGuildRaidView(self.guild_id, self.user_id, party["clan_id"]), ephemeral=True)


