def rpg_build_guild_shop_embed(guild_id, clan_id):
    full = rpg_get_clan_full(guild_id, clan_id)
    resources = full.get("resources", 0) if full else 0
    lines = [f"💠 현재 길드 자원: **{resources:,}**\n"]
    for s in RPG_GUILD_SHOP:
        lines.append(f"`{s['id']}` **{s['name']}** — {s['cost']:,} 자원\n└ {s['desc']}")
    embed = discord.Embed(title="🏪 길드 상점", description="\n".join(lines), color=discord.Color.dark_green())
    embed.set_footer(text="길드장만 구매 가능 · 구매품은 길드 보관함으로 | 만능 봇 RPG")
    return embed


class RPGGuildShopSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id, clan_id):
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id
        options = [discord.SelectOption(label=s["name"][:100], description=f"{s['cost']:,} 자원"[:90], value=s["id"]) for s in RPG_GUILD_SHOP]
        super().__init__(placeholder="🏪 구매할 항목 선택 (길드장 전용)", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        full = rpg_get_clan_full(self.guild_id, self.clan_id)
        if not full or full["leader_id"] != self.user_id:
            return await interaction.response.send_message("❌ 길드 상점 구매는 길드장만 가능해요.", ephemeral=True)
        item = RPG_GUILD_SHOP_BY_ID.get(self.values[0])
        if not item:
            return await interaction.response.send_message("항목을 찾을 수 없어요.", ephemeral=True)
        if full.get("resources", 0) < item["cost"]:
            return await interaction.response.send_message(f"❌ 자원이 부족해요. (필요 {item['cost']:,}, 보유 {full.get('resources',0):,})", ephemeral=True)
        with DB_MUTEX:
            c.execute("UPDATE rpg_guilds SET resources=resources-? WHERE guild_id=? AND clan_id=?", (item["cost"], self.guild_id, self.clan_id))
            # 길드 보관함에 지급
            c.execute(
                "INSERT INTO rpg_guild_storage (guild_id, clan_id, item_name, amount) VALUES (?,?,?,?) "
                "ON CONFLICT(guild_id, clan_id, item_name) DO UPDATE SET amount=amount+?",
                (self.guild_id, self.clan_id, item["reward_item"], item["reward_amount"], item["reward_amount"]),
            )
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_shop_embed(self.guild_id, self.clan_id), view=RPGGuildShopView(self.guild_id, self.user_id, self.clan_id))
        await interaction.followup.send(f"🏪 **{item['name']}** 구매 완료! {item['reward_item']} {item['reward_amount']}개를 길드 보관함에 넣었어요.", ephemeral=True)


class RPGGuildShopView(discord.ui.View):
    def __init__(self, guild_id, user_id, clan_id):
        super().__init__(timeout=180)
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id
        self.add_item(RPGGuildShopSelect(guild_id, user_id, clan_id))


