def rpg_build_guild_buff_embed(guild_id, user_id):
    buffs = rpg_guild_buffs(guild_id, user_id)
    if not buffs:
        return discord.Embed(title="✨ 길드 버프", description="길드에 가입하면 소속원 전원이 버프를 받아요!", color=discord.Color.greyple())
    clan = rpg_get_my_clan(guild_id, user_id)
    full = rpg_get_clan_full(guild_id, clan["clan_id"])
    labels = {"power": "공격력", "defense": "방어력", "exp": "획득 경험치", "gold": "획득 골드"}
    lines = [f"{labels.get(k, k)} +{v*100:.0f}%" for k, v in buffs.items()]
    embed = discord.Embed(
        title=f"✨ 길드 버프 · {clan['name']}",
        description=(
            f"길드 레벨 **{full.get('level',1)}** · 영지 레벨 **{full.get('territory_level',1)}**\n\n"
            "**소속원 전원 적용 버프**\n" + "\n".join(lines)
            + "\n\n길드 레벨/영지 레벨을 올리면 버프가 강해져요!"
        ),
        color=discord.Color.gold(),
    )
    embed.set_footer(text="길드에 기여하고 성장할수록 강해집니다 | 만능 봇 RPG")
    return embed


# ---------- 6번: 길드 레이드 ----------
RPG_GUILD_RAID_BOSSES = [
    {"min_glevel": 1, "name": "길드의 시련: 강철 골렘", "emoji": "🗿", "hp": 30000, "reward_resources": 300},
    {"min_glevel": 3, "name": "길드의 시련: 심연룡", "emoji": "🐉", "hp": 100000, "reward_resources": 800},
    {"min_glevel": 5, "name": "길드의 시련: 종말의 마룡", "emoji": "👹", "hp": 300000, "reward_resources": 2000},
]


def rpg_get_guild_raid_boss(glevel):
    eligible = [b for b in RPG_GUILD_RAID_BOSSES if b["min_glevel"] <= glevel]
    return eligible[-1] if eligible else RPG_GUILD_RAID_BOSSES[0]


def rpg_build_guild_raid_embed(guild_id, clan_id):
    full = rpg_get_clan_full(guild_id, clan_id)
    glevel = full.get("level", 1) if full else 1
    boss = rpg_get_guild_raid_boss(glevel)
    raid = rpg_get_guild_raid_state(guild_id, clan_id)
    if raid:
        hp, max_hp = raid["hp"], raid["max_hp"]
        desc = (
            f"{boss['emoji']} **{raid['boss_name']}**\n"
            f"HP {hp:,} / {max_hp:,}\n{rpg_progress_bar(hp, max_hp)}\n\n"
            "길드원 모두가 **공격** 버튼으로 함께 처치하세요! 처치 시 길드 자원을 크게 획득해요."
        )
    else:
        desc = (
            f"현재 진행 중인 길드 레이드가 없어요.\n\n"
            f"다음 보스: {boss['emoji']} **{boss['name']}** (HP {boss['hp']:,})\n"
            f"처치 보상: 길드 자원 +{boss['reward_resources']:,}\n\n"
            "**레이드 시작** 버튼으로 길드 레이드를 열 수 있어요. (길드장 전용)"
        )
    embed = discord.Embed(title="🐲 길드 레이드", description=desc, color=discord.Color.dark_red())
    embed.set_footer(text="길드원 협동 보스 · 10분 쿨타임 공격 | 만능 봇 RPG")
    return embed


def rpg_get_guild_raid_state(guild_id, clan_id):
    with DB_MUTEX:
        c.execute("SELECT boss_name, boss_emoji, max_hp, hp FROM rpg_guild_raids WHERE guild_id=? AND clan_id=?", (guild_id, clan_id))
        row = c.fetchone()
    if not row:
        return None
    return {"boss_name": row[0], "boss_emoji": row[1], "max_hp": row[2], "hp": row[3]}


class RPGGuildRaidView(discord.ui.View):
    def __init__(self, guild_id, user_id, clan_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id

    @discord.ui.button(label="레이드 시작", emoji="🚩", style=discord.ButtonStyle.success)
    async def start(self, interaction, button):
        full = rpg_get_clan_full(self.guild_id, self.clan_id)
        if not full or full["leader_id"] != self.user_id:
            return await interaction.response.send_message("❌ 길드 레이드 시작은 길드장만 가능해요.", ephemeral=True)
        if rpg_get_guild_raid_state(self.guild_id, self.clan_id):
            return await interaction.response.send_message("이미 진행 중인 길드 레이드가 있어요.", ephemeral=True)
        boss = rpg_get_guild_raid_boss(full.get("level", 1))
        with DB_MUTEX:
            c.execute(
                "INSERT OR REPLACE INTO rpg_guild_raids (guild_id, clan_id, boss_name, boss_emoji, max_hp, hp, reward_resources) VALUES (?,?,?,?,?,?,?)",
                (self.guild_id, self.clan_id, boss["name"], boss["emoji"], boss["hp"], boss["hp"], boss["reward_resources"]),
            )
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_raid_embed(self.guild_id, self.clan_id), view=RPGGuildRaidView(self.guild_id, self.user_id, self.clan_id))
        await interaction.followup.send(f"🚩 길드 레이드 **{boss['name']}** 시작! 길드원 모두 공격하세요!", ephemeral=False)

    @discord.ui.button(label="공격", emoji="⚔️", style=discord.ButtonStyle.danger)
    async def attack(self, interaction, button):
        raid = rpg_get_guild_raid_state(self.guild_id, self.clan_id)
        if not raid:
            return await interaction.response.send_message("진행 중인 길드 레이드가 없어요.", ephemeral=True)
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        _gb = rpg_guild_buffs(self.guild_id, self.user_id)
        player["_guild_power_buff"] = _gb.get("power", 0.0)
        power = rpg_player_power(player)
        dmg = max(1, int(power * random.uniform(2.0, 3.5)))  # 레이드 공격은 강하게
        new_hp = max(0, raid["hp"] - dmg)
        if new_hp <= 0:
            # 레이드 클리어 → 길드 자원 보상
            with DB_MUTEX:
                c.execute("SELECT reward_resources FROM rpg_guild_raids WHERE guild_id=? AND clan_id=?", (self.guild_id, self.clan_id))
                rr = c.fetchone()
                reward = rr[0] if rr else 500
                c.execute("DELETE FROM rpg_guild_raids WHERE guild_id=? AND clan_id=?", (self.guild_id, self.clan_id))
                c.execute("UPDATE rpg_guilds SET resources=resources+? WHERE guild_id=? AND clan_id=?", (reward, self.guild_id, self.clan_id))
                # 기여도 반영
                c.execute("UPDATE rpg_guild_members SET contribution=contribution+500 WHERE guild_id=? AND user_id=?", (self.guild_id, self.user_id))
                conn.commit()
            return await interaction.response.send_message(
                f"🎉 **{raid['boss_name']}** 처치! 막타는 <@{self.user_id}>! 길드 자원 **+{reward:,}** 획득!",
                ephemeral=False,
            )
        with DB_MUTEX:
            c.execute("UPDATE rpg_guild_raids SET hp=? WHERE guild_id=? AND clan_id=?", (new_hp, self.guild_id, self.clan_id))
            c.execute("UPDATE rpg_guild_members SET contribution=contribution+50 WHERE guild_id=? AND user_id=?", (self.guild_id, self.user_id))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_raid_embed(self.guild_id, self.clan_id), view=RPGGuildRaidView(self.guild_id, self.user_id, self.clan_id))
        await interaction.followup.send(f"⚔️ {raid['boss_emoji']} {raid['boss_name']}에게 **{dmg:,}** 피해! (남은 HP {new_hp:,})", ephemeral=True)


# ---------- 길드 보관함 ----------
def rpg_guild_storage_items(guild_id, clan_id):
    with DB_MUTEX:
        c.execute("SELECT item_name, amount FROM rpg_guild_storage WHERE guild_id=? AND clan_id=? AND amount>0 ORDER BY item_name", (guild_id, clan_id))
        return c.fetchall()


def rpg_build_guild_storage_embed(guild_id, clan_id):
    items = rpg_guild_storage_items(guild_id, clan_id)
    text = "\n".join(f"• {name} x{amt}" for name, amt in items) if items else "보관함이 비어있어요."
    embed = discord.Embed(title="🗄️ 길드 보관함", description=text + "\n\n길드원끼리 아이템을 공유할 수 있어요.", color=discord.Color.dark_blue())
    embed.set_footer(text="맡기기/찾기 버튼으로 이용 | 만능 봇 RPG")
    return embed


class RPGGuildStorageDepositModal(discord.ui.Modal, title="보관함에 맡기기"):
    item = discord.ui.TextInput(label="아이템 이름", placeholder="예: 강화석")
    amount = discord.ui.TextInput(label="개수", placeholder="1", max_length=4)

    def __init__(self, guild_id, user_id, clan_id):
        super().__init__()
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id

    async def on_submit(self, interaction):
        name = str(self.item).strip()
        try:
            n = int(str(self.amount).strip())
        except ValueError:
            n = 0
        if n < 1:
            return await interaction.response.send_message("개수는 1 이상이어야 해요.", ephemeral=True)
        if get_inventory_amount(self.user_id, name) < n:
            return await interaction.response.send_message(f"`{name}`을(를) {n}개 갖고 있지 않아요.", ephemeral=True)
        consume_inventory_item(self.user_id, name, n)
        with DB_MUTEX:
            c.execute("INSERT INTO rpg_guild_storage (guild_id, clan_id, item_name, amount) VALUES (?,?,?,?) ON CONFLICT(guild_id, clan_id, item_name) DO UPDATE SET amount=amount+?",
                      (self.guild_id, self.clan_id, name, n, n))
            conn.commit()
        await interaction.response.edit_message(embed=rpg_build_guild_storage_embed(self.guild_id, self.clan_id), view=RPGGuildStorageView(self.guild_id, self.user_id, self.clan_id))


class RPGGuildStorageWithdrawModal(discord.ui.Modal, title="보관함에서 찾기"):
    item = discord.ui.TextInput(label="아이템 이름", placeholder="예: 강화석")
    amount = discord.ui.TextInput(label="개수", placeholder="1", max_length=4)

    def __init__(self, guild_id, user_id, clan_id):
        super().__init__()
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id

    async def on_submit(self, interaction):
        name = str(self.item).strip()
        try:
            n = int(str(self.amount).strip())
        except ValueError:
            n = 0
        if n < 1:
            return await interaction.response.send_message("개수는 1 이상이어야 해요.", ephemeral=True)
        with DB_MUTEX:
            c.execute("SELECT amount FROM rpg_guild_storage WHERE guild_id=? AND clan_id=? AND item_name=?", (self.guild_id, self.clan_id, name))
            row = c.fetchone()
            if not row or row[0] < n:
                return await interaction.response.send_message("보관함에 그만큼 없어요.", ephemeral=True)
            c.execute("UPDATE rpg_guild_storage SET amount=amount-? WHERE guild_id=? AND clan_id=? AND item_name=?", (n, self.guild_id, self.clan_id, name))
            conn.commit()
        add_inventory_item(self.user_id, name, n, guild_id=self.guild_id)
        await interaction.response.edit_message(embed=rpg_build_guild_storage_embed(self.guild_id, self.clan_id), view=RPGGuildStorageView(self.guild_id, self.user_id, self.clan_id))


class RPGGuildStorageView(discord.ui.View):
    def __init__(self, guild_id, user_id, clan_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id

    @discord.ui.button(label="맡기기", emoji="📥", style=discord.ButtonStyle.success)
    async def deposit(self, interaction, button):
        await interaction.response.send_modal(RPGGuildStorageDepositModal(self.guild_id, self.user_id, self.clan_id))

    @discord.ui.button(label="찾기", emoji="📤", style=discord.ButtonStyle.primary)
    async def withdraw(self, interaction, button):
        await interaction.response.send_modal(RPGGuildStorageWithdrawModal(self.guild_id, self.user_id, self.clan_id))


# ---------- 외교 & 전쟁 ----------
def rpg_all_clans(guild_id, exclude_clan=None):
    with DB_MUTEX:
        c.execute("SELECT clan_id, name, level, territory_level FROM rpg_guilds WHERE guild_id=?", (guild_id,))
        rows = c.fetchall()
    return [r for r in rows if r[0] != exclude_clan]


def rpg_get_relation(guild_id, clan_a, clan_b):
    key = tuple(sorted([clan_a, clan_b]))
    with DB_MUTEX:
        c.execute("SELECT relation FROM rpg_guild_relations WHERE guild_id=? AND clan_a=? AND clan_b=?", (guild_id, key[0], key[1]))
        row = c.fetchone()
    return row[0] if row else "neutral"


def rpg_set_relation(guild_id, clan_a, clan_b, relation):
    key = tuple(sorted([clan_a, clan_b]))
    with DB_MUTEX:
        c.execute("INSERT INTO rpg_guild_relations (guild_id, clan_a, clan_b, relation) VALUES (?,?,?,?) ON CONFLICT(guild_id, clan_a, clan_b) DO UPDATE SET relation=?",
                  (guild_id, key[0], key[1], relation, relation))
        conn.commit()


def rpg_build_diplomacy_embed(guild_id, clan_id):
    others = rpg_all_clans(guild_id, clan_id)
    rel_emoji = {"ally": "🤝동맹", "war": "⚔️전쟁", "neutral": "😐중립"}
    lines = []
    for cid, name, lv, terr in others:
        rel = rpg_get_relation(guild_id, clan_id, cid)
        lines.append(f"{rel_emoji.get(rel, rel)} · **{name}** (Lv.{lv}·영지{terr})")
    text = "\n".join(lines) if lines else "다른 길드가 없어요."
    embed = discord.Embed(title="⚔️ 외교 & 전쟁", description=text + "\n\n아래 메뉴에서 상대 길드와 동맹/선전포고/전쟁을 진행하세요. (길드장 전용)", color=discord.Color.dark_red())
    embed.set_footer(text="전쟁 승리 시 상대 자원을 약탈해요 | 만능 봇 RPG")
    return embed


class RPGDiplomacySelect(discord.ui.Select):
    def __init__(self, guild_id, user_id, clan_id):
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id
        others = rpg_all_clans(guild_id, clan_id)
        options = [discord.SelectOption(label=name[:100], description=f"Lv.{lv}·영지{terr}", value=cid) for cid, name, lv, terr in others[:25]]
        if not options:
            options = [discord.SelectOption(label="다른 길드 없음", value="__none__")]
        super().__init__(placeholder="상대 길드 선택", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        view: "RPGDiplomacyView" = self.view
        view.target_clan = self.values[0]
        await interaction.response.send_message(f"상대 길드를 선택했어요. 아래 버튼으로 동맹/전쟁을 진행하세요.", ephemeral=True)


class RPGDiplomacyView(discord.ui.View):
    def __init__(self, guild_id, user_id, clan_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        self.clan_id = clan_id
        self.target_clan = None
        self.add_item(RPGDiplomacySelect(guild_id, user_id, clan_id))

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    def _is_leader(self):
        clan = rpg_get_clan_full(self.guild_id, self.clan_id)
        return clan and clan["leader_id"] == self.user_id

    @discord.ui.button(label="동맹 맺기", emoji="🤝", style=discord.ButtonStyle.success, row=1)
    async def ally(self, interaction, button):
        if not self._is_leader():
            return await interaction.response.send_message("길드장만 외교할 수 있어요.", ephemeral=True)
        if not self.target_clan:
            return await interaction.response.send_message("먼저 상대 길드를 메뉴에서 고르세요.", ephemeral=True)
        rpg_set_relation(self.guild_id, self.clan_id, self.target_clan, "ally")
        await interaction.response.edit_message(embed=rpg_build_diplomacy_embed(self.guild_id, self.clan_id), view=RPGDiplomacyView(self.guild_id, self.user_id, self.clan_id))

    @discord.ui.button(label="선전포고/전쟁", emoji="⚔️", style=discord.ButtonStyle.danger, row=1)
    async def war(self, interaction, button):
        if not self._is_leader():
            return await interaction.response.send_message("길드장만 전쟁을 선포할 수 있어요.", ephemeral=True)
        if not self.target_clan:
            return await interaction.response.send_message("먼저 상대 길드를 메뉴에서 고르세요.", ephemeral=True)
        # 전쟁 즉시 판정: 양쪽 영지레벨+길드레벨 + 랜덤으로 승부
        my = rpg_get_clan_full(self.guild_id, self.clan_id)
        enemy = rpg_get_clan_full(self.guild_id, self.target_clan)
        if not enemy:
            return await interaction.response.send_message("상대 길드를 찾을 수 없어요.", ephemeral=True)
        rpg_set_relation(self.guild_id, self.clan_id, self.target_clan, "war")
        my_power = (my["level"] + my["territory_level"]) * random.uniform(0.8, 1.2)
        enemy_power = (enemy["level"] + enemy["territory_level"]) * random.uniform(0.8, 1.2)
        if my_power >= enemy_power:
            loot = min(enemy["resources"], 500)
            with DB_MUTEX:
                c.execute("UPDATE rpg_guilds SET war_wins=war_wins+1, resources=resources+? WHERE guild_id=? AND clan_id=?", (loot, self.guild_id, self.clan_id))
                c.execute("UPDATE rpg_guilds SET war_losses=war_losses+1, resources=MAX(0, resources-?) WHERE guild_id=? AND clan_id=?", (loot, self.guild_id, self.target_clan))
                conn.commit()
            result = f"🏆 **{my['name']}** 승리! {enemy['name']}에게서 자원 {loot}을 약탈했어요!"
        else:
            loot = min(my["resources"], 500)
            with DB_MUTEX:
                c.execute("UPDATE rpg_guilds SET war_losses=war_losses+1, resources=MAX(0, resources-?) WHERE guild_id=? AND clan_id=?", (loot, self.guild_id, self.clan_id))
                c.execute("UPDATE rpg_guilds SET war_wins=war_wins+1, resources=resources+? WHERE guild_id=? AND clan_id=?", (loot, self.guild_id, self.target_clan))
                conn.commit()
            result = f"💥 **{my['name']}** 패배... {enemy['name']}에게 자원 {loot}을 빼앗겼어요."
        embed = rpg_build_diplomacy_embed(self.guild_id, self.clan_id)
        embed.description = result + "\n\n" + (embed.description or "")
        await interaction.response.edit_message(embed=embed, view=RPGDiplomacyView(self.guild_id, self.user_id, self.clan_id))


# ============================================================

def rpg_build_rebirth_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    rebirth = player.get("rebirth") or 0
    bonus = rpg_rebirth_bonus(player) * 100
    can = player["level"] >= RPG_REBIRTH_LEVEL
    ev_title = rpg_evolution_title(player)
    gate = rpg_dimension_gate_level(player)
    need_break = rpg_needs_dimension_break(player)

    desc = (
        f"현재: Lv.{player['level']} · 진화단계 **{ev_title}** · 환생 **{rebirth}회**\n"
        f"환생 보너스: 모든 전투 능력치 **+{bonus:.0f}%**\n\n"
    )
    if need_break:
        desc += f"⚠️ **차원 돌파 필요!** Lv.{gate} 관문에 막혀 있어요. 아래 '차원 돌파' 버튼으로 도전하세요.\n\n"
    else:
        desc += f"다음 차원 관문: Lv.{gate}\n\n"
    if can:
        desc += "🌟 **환생 가능!** 만렙을 달성했어요. 환생하면 Lv.1로 돌아가지만 영구 보너스를 얻어요."
    else:
        desc += f"환생은 Lv.{RPG_REBIRTH_LEVEL}(만렙)에서 가능해요."

    embed = discord.Embed(title="♻️ 환생 · 차원 돌파", description=desc, color=discord.Color.purple())
    embed.set_footer(text="환생 1회당 +5% (최대 20회) · 진화 시 외형/칭호 변화 | 만능 봇 RPG")
    return embed


class RPGRebirthView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="환생하기", emoji="♻️", style=discord.ButtonStyle.success, row=0)
    async def rebirth(self, interaction, button):
        gid, uid = self.guild_id, self.user_id
        player = get_or_create_rpg_player(gid, uid)
        if player["level"] < RPG_REBIRTH_LEVEL:
            return await interaction.response.send_message(f"❌ 환생은 Lv.{RPG_REBIRTH_LEVEL}(만렙)에서만 가능해요.", ephemeral=True)
        if (player.get("rebirth") or 0) >= RPG_REBIRTH_MAX:
            return await interaction.response.send_message(f"이미 최대 환생 횟수({RPG_REBIRTH_MAX}회)에 도달했어요!", ephemeral=True)
        new_rebirth = (player.get("rebirth") or 0) + 1
        # 레벨1로 리셋, 환생 횟수 +1, 스탯포인트/퍽포인트는 유지, 장비는 유지
        save_rpg_player(gid, uid, level=1, exp=0, max_hp=100, hp=100, rebirth=new_rebirth,
                        dimension=0, evolution=0)
        embed = discord.Embed(
            title="♻️ 환생 완료!",
            description=(
                f"**{new_rebirth}번째 환생**을 마쳤어요!\n"
                f"Lv.1로 돌아갔지만, 모든 전투 능력치에 영구 **+{new_rebirth*5}%** 보너스가 붙었어요.\n"
                f"장비·스탯·직업은 그대로 유지돼요. 새로운 여정을 시작하세요!"
            ),
            color=discord.Color.gold(),
        )
        await interaction.response.edit_message(embed=embed, view=None)

    @discord.ui.button(label="차원 돌파 도전", emoji="🌌", style=discord.ButtonStyle.primary, row=0)
    async def dimension_break(self, interaction, button):
        gid, uid = self.guild_id, self.user_id
        player = get_or_create_rpg_player(gid, uid)
        if not rpg_needs_dimension_break(player):
            return await interaction.response.send_message("지금은 차원 돌파가 필요하지 않아요. 계속 성장하세요!", ephemeral=True)

        dim = player.get("dimension") or 0
        challenge = RPG_DIMENSION_CHALLENGES.get(dim)
        if not challenge:
            return await interaction.response.send_message("❌ 해당 차원 도전 과제가 없어요.", ephemeral=True)

        gate = rpg_dimension_gate_level(player)
        power = rpg_player_power(player)
        required = gate * 15

        # 도전 과제 유형별 성공 판정
        success = False
        detail_msg = ""

        if challenge["type"] == "monster_hunt":
            # 특정 몬스터 처치 필요
            success = power >= required
            detail_msg = f"지역 몬스터 {challenge['target']}마리 처치 필요 (전투력: {power:,}/{required:,})"

        elif challenge["type"] == "location_hunt":
            # 특정 지역 몬스터 처치
            success = power >= required
            detail_msg = f"{challenge.get('location', '특정')} 지역 몬스터 {challenge['target']}마리 처치 필요 (전투력: {power:,}/{required:,})"

        elif challenge["type"] == "boss_hunt":
            # 보스 격파
            success = power >= int(required * 1.5)
            detail_msg = f"{challenge.get('location', '특정')} 보스 {challenge['target']}회 격파 필요 (권장 전투력: {int(required*1.5):,})"

        elif challenge["type"] == "mixed":
            # 복합 도전 (보스 + 탐험 등)
            targets_str = " + ".join([f"{v}{'🏆' if k=='boss' else '🗺️'}" for k, v in challenge.get('targets', {}).items()])
            success = power >= int(required * 1.3)
            detail_msg = f"혼합 도전: {targets_str} (권장 전투력: {int(required*1.3):,})"

        elif challenge["type"] == "explore_all":
            # 모든 지역 탐험
            success = power >= required
            detail_msg = f"모든 지역 탐험 {challenge['target']}곳 이상 발견 필요"

        elif challenge["type"] == "legendary_boss":
            # 전설 보스 격파
            success = power >= int(required * 2)
            detail_msg = f"전설급 보스 {challenge['target']}회 격파 필요 (권장 전투력: {int(required*2):,})"

        elif challenge["type"] == "boss_hunt_total":
            # 총 보스 격파 수
            success = power >= int(required * 1.2)
            detail_msg = f"총 {challenge['target']}회 이상 보스 격파 필요"

        else:
            # 기본 판정
            success = power >= required or random.random() < 0.4

        if success:
            new_dim = dim + 1
            kwargs = {"dimension": new_dim}
            evo_msg = ""
            skill_msg = ""

            # stat 보너스 적용
            if "stat_bonus" in challenge:
                bonus = challenge["stat_bonus"]
                if "hp" in bonus:
                    kwargs["max_hp"] = player.get("max_hp", 100) + bonus["hp"]
                    kwargs["hp"] = kwargs["max_hp"]

            # 진화 확인
            if "evolution" in challenge:
                kwargs["evolution"] = challenge["evolution"]
                evo_level = challenge["evolution"]
                evo_msg = f"\n✨ **{RPG_EVOLUTION_TITLES[evo_level]}으로 진화!**"

                # 진화 스킬 해금
                if evo_level in RPG_EVOLUTION_SKILLS:
                    skill = RPG_EVOLUTION_SKILLS[evo_level]
                    unlock_evolution_skill(gid, uid, evo_level, skill["name"])
                    skill_msg = f"\n🎯 **새로운 스킬 해금:** {skill['name']}\n`{skill['desc']}`"

            # 차원 패시브 설정
            passive = RPG_DIMENSION_PASSIVES.get(new_dim, {})
            passive_name = passive.get("name", "")
            passive_bonus = passive.get("power", 1.0)

            save_rpg_player(gid, uid, **kwargs)
            complete_dimension_challenge(gid, uid, dim)

            embed = discord.Embed(
                title="🌌 차원 돌파 성공!",
                description=(
                    f"**차원 {dim} → {new_dim}** 돌파 완료!\n"
                    f"`{challenge['name']}: {challenge['desc']}`\n"
                    f"다음 수준으로 나아갈 수 있어요.{evo_msg}{skill_msg}\n"
                    f"\n**새로운 패시브:** {passive_name} (전투력 배수: {passive_bonus:.1%})"
                ),
                color=discord.Color.gold(),
            )
        else:
            embed = discord.Embed(
                title="💥 차원 돌파 실패...",
                description=(
                    f"**도전과제:** {challenge['name']}\n"
                    f"{detail_msg}\n\n"
                    f"아직 준비가 부족해요. 더 강해진 뒤 다시 도전하세요! 💪"
                ),
                color=discord.Color.red(),
            )

        await interaction.response.edit_message(embed=embed, view=RPGRebirthView(gid, uid))


# ========== 7번: 차원 돌파 정보 표시 ==========
def rpg_build_dimension_info_embed(guild_id: int, user_id: int) -> discord.Embed:
    """차원 돌파 상세 정보 embed 생성"""
    player = get_or_create_rpg_player(guild_id, user_id)
    dim = player.get("dimension") or 0
    evo = player.get("evolution") or 0
    level = player["level"]

    embed = discord.Embed(
        title=f"🌌 차원 정보 (차원 {dim})",
        description=f"**현재 상태:** {RPG_DIMENSION_PASSIVES[dim]['name']} / {RPG_EVOLUTION_TITLES[min(evo, 3)]}",
        color=discord.Color.purple(),
    )

    # 현재 차원 패시브
    passive = RPG_DIMENSION_PASSIVES[dim]
    embed.add_field(
        name="⭐ 현재 패시브 능력",
        value=(
            f"**{passive['name']}**\n"
            f"• 전투력 배수: {passive['power']:.1%}\n"
            f"• 방어력 배수: {passive['defense']:.1%}\n"
            f"• 회복량 배수: {passive['heal']:.1%}"
        ),
        inline=False
    )

    # 다음 차원 도전과제
    next_challenge = RPG_DIMENSION_CHALLENGES.get(dim)
    if next_challenge:
        next_gate = rpg_dimension_gate_level(player)
        embed.add_field(
            name=f"🎯 다음 도전과제 (Lv.{next_gate})",
            value=(
                f"**{next_challenge['name']}**\n"
                f"`{next_challenge['desc']}`"
            ),
            inline=False
        )

        # 도전 진행도
        if next_challenge.get("type") == "mixed":
            targets = next_challenge.get("targets", {})
            detail = " + ".join([f"{k}: 0/{v}" for k, v in targets.items()])
        else:
            target = next_challenge.get("target", 0)
            detail = f"진행도: 0/{target}"

        embed.add_field(
            name="📊 진행 상황",
            value=f"`{detail}`",
            inline=False
        )

    # 진화 스킬
    unlocked_skills = get_player_unlocked_skills(guild_id, user_id)
    if unlocked_skills:
        skill_text = ""
        for s in unlocked_skills:
            skill_info = RPG_EVOLUTION_SKILLS.get(s["level"], {})
            skill_text += f"**{s['name']}** ({RPG_EVOLUTION_TITLES[s['level']]}) - {skill_info.get('desc', '')}\n"
        embed.add_field(name="🎯 해금된 스킬", value=skill_text, inline=False)

    # 현재 전투력/방어력
    power = rpg_player_power(player)
    defense = rpg_player_defense(player)
    embed.add_field(
        name="⚔️ 현재 능력치",
        value=f"• 전투력: {power:,}\n• 방어력: {defense:,}",
        inline=False
    )

    return embed


# ---------- 전직 퀘스트 진행 표시 ----------
def rpg_build_jobquest_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    job_id, tier = rpg_parse_job_field(player.get("job"))
    next_tier = tier + 1
    quest = RPG_JOB_QUESTS.get(next_tier)
    if not job_id:
        desc = "먼저 `/rpg 직업선택`으로 직업을 골라주세요."
    elif not quest:
        desc = "현재 진행할 전직 퀘스트가 없어요."
    else:
        prog, target, done = rpg_jobquest_progress(player, next_tier)
        status = "✅ 완료! 전직 가능" if done else f"진행 {min(prog,target)}/{target}"
        desc = f"**{quest['name']}** ({RPG_JOB_TIER_LABELS[next_tier-1]} 조건)\n{quest['desc']}\n\n{status}"
    embed = discord.Embed(title="📜 전직 퀘스트", description=desc, color=discord.Color.blurple())
    embed.set_footer(text="전직 퀘스트를 완료해야 다음 단계로 전직할 수 있어요 | 만능 봇 RPG")
    return embed


