# ---------- 6번: 탐험 패널 ----------
def rpg_build_explore_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    discovered = rpg_get_discovered(player)
    lines = []
    for zid, z in RPG_EXPLORE_ZONES.items():
        if zid in discovered:
            mark = "✅ 발견함"
        elif z["req"] and z["req"] not in discovered:
            mark = f"🔒 {RPG_EXPLORE_ZONES[z['req']]['name']} 먼저 발견 필요"
        elif player["level"] < z["min_level"]:
            mark = f"🔒 Lv.{z['min_level']} 필요"
        else:
            mark = "❓ 미발견 (탐험 가능!)"
        lines.append(f"{z['name']} — {mark}")
    embed = discord.Embed(
        title="🧭 탐험",
        description=(
            "세상을 탐험하며 새로운 지역을 발견하세요!\n"
            "**최초 발견 시 큰 보상**, 이후엔 탐험할 때마다 경험치·전리품을 얻어요.\n\n"
            + "\n".join(lines)
        ),
        color=discord.Color.teal(),
    )
    embed.set_footer(text="발견 자체가 성장! 적을 안 잡아도 경험치를 얻어요 | 만능 봇 RPG")
    return embed


class RPGExploreSelect(discord.ui.Select):
    def __init__(self, guild_id, user_id):
        self.guild_id = guild_id
        self.user_id = user_id
        player = get_or_create_rpg_player(guild_id, user_id)
        discovered = rpg_get_discovered(player)
        options = []
        for zid, z in RPG_EXPLORE_ZONES.items():
            locked = (z["req"] and z["req"] not in discovered) or player["level"] < z["min_level"]
            emoji = "✅" if zid in discovered else ("🔒" if locked else "❓")
            options.append(discord.SelectOption(label=z["name"][:100], description=f"Lv.{z['min_level']}+ 탐험", value=zid, emoji=emoji))
        super().__init__(placeholder="탐험할 지역 선택", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction):
        gid, uid = self.guild_id, self.user_id
        zid = self.values[0]
        z = RPG_EXPLORE_ZONES[zid]
        player = get_or_create_rpg_player(gid, uid)
        discovered = rpg_get_discovered(player)
        if z["req"] and z["req"] not in discovered:
            return await interaction.response.send_message(f"🔒 먼저 {RPG_EXPLORE_ZONES[z['req']]['name']}을(를) 발견해야 해요.", ephemeral=True)
        if player["level"] < z["min_level"]:
            return await interaction.response.send_message(f"🔒 Lv.{z['min_level']} 이상 필요해요.", ephemeral=True)

        first_time = zid not in discovered
        exp_gain = z["explore_exp"]
        gold_gain = z["explore_exp"] * 2
        note_lines = []
        if first_time:
            rpg_mark_discovered(gid, uid, zid)
            exp_gain += z["discover_exp"]
            gold_gain += z["discover_gold"]
            note_lines.append(f"🎉 **{z['name']} 최초 발견!** 발견 보상 +{z['discover_exp']}exp, +{z['discover_gold']}P")
        # 탐험 보상
        loot = []
        for item, chance in z["loot"]:
            if random.random() < chance:
                add_inventory_item(uid, item, 1, guild_id=gid)
                loot.append(item)
        set_user_point(gid, uid, get_user_point(gid, uid) + gold_gain)
        level_ups, player = rpg_apply_exp(player, exp_gain)
        save_rpg_player(gid, uid, level=player["level"], exp=player["exp"], max_hp=player["max_hp"],
                        stat_points=player["stat_points"], perk_points=player.get("perk_points", 0))
        note_lines.append(f"🧭 탐험 보상: +{exp_gain}exp · +{gold_gain}P" + (f" · 전리품: {', '.join(loot)}" if loot else ""))
        if level_ups:
            note_lines.append(f"🆙 레벨업! Lv.{level_ups[-1]}")
        embed = rpg_build_explore_embed(gid, uid)
        embed.description = "\n".join(note_lines) + "\n\n" + (embed.description or "")
        await interaction.response.edit_message(embed=embed, view=RPGExploreView(gid, uid))


class RPGExploreView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=300)
        self.user_id = user_id
        self.add_item(RPGExploreSelect(guild_id, user_id))

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True


# ---------- 1·2번: 직업군별 랭킹 / 숙련 랭킹 ----------
def rpg_build_job_ranking_embed(guild_id):
    with DB_MUTEX:
        c.execute("SELECT user_id, level, exp, job FROM rpg_players WHERE guild_id=? AND job != '' ORDER BY level DESC, exp DESC LIMIT 100", (guild_id,))
        rows = c.fetchall()
    # 직업군(base job)별로 최고 레벨 유저 집계
    by_job = {}
    for uid, level, exp, job in rows:
        job_id, tier = rpg_parse_job_field(job)
        # 분기면 기본 직업으로 묶기
        base = rpg_job_skill_source(job_id)
        line = rpg_resolve_job_line(job_id)
        base_name = RPG_JOB_LINES_BY_ID.get(base, {}).get("line_name", line["line_name"] if line else base)
        if base_name not in by_job or level > by_job[base_name][1]:
            by_job[base_name] = (uid, level, line["line_name"] if line else base_name, tier)
    lines = []
    for base_name, (uid, level, full_name, tier) in sorted(by_job.items(), key=lambda x: -x[1][1]):
        lines.append(f"**{base_name}** — <@{uid}> (Lv.{level}, {full_name} {tier}차)")
    embed = discord.Embed(
        title="🏆 직업군별 랭킹 (각 직업 1위)",
        description="\n".join(lines) if lines else "아직 직업을 가진 유저가 없어요.",
        color=discord.Color.gold(),
    )
    embed.set_footer(text="각 직업군의 최고 레벨 유저 | 만능 봇 RPG")
    return embed


def rpg_build_mastery_ranking_embed(guild_id):
    with DB_MUTEX:
        c.execute("SELECT user_id, mastery, professions FROM rpg_players WHERE guild_id=?", (guild_id,))
        rows = c.fetchall()
    scored = []
    for uid, mastery, professions in rows:
        total = 0
        for src_field in (mastery or "", professions or ""):
            for part in src_field.split(","):
                if ":" in part and not part.startswith("disc_") and not part.startswith("_u_"):
                    try:
                        total += int(part.split(":")[1])
                    except (ValueError, IndexError):
                        pass
        if total > 0:
            scored.append((uid, total))
    scored.sort(key=lambda x: -x[1])
    lines = [f"{i+1}. <@{uid}> — 총 숙련 {total:,}" for i, (uid, total) in enumerate(scored[:10])]
    embed = discord.Embed(
        title="🛠️ 숙련도 랭킹 TOP 10",
        description="\n".join(lines) if lines else "아직 숙련도를 쌓은 유저가 없어요.",
        color=discord.Color.dark_gold(),
    )
    embed.set_footer(text="사냥·생산 숙련의 합산 | 만능 봇 RPG")
    return embed


