# ---------- 생산직 패널 (채집/채광/낚시) ----------
def rpg_build_profession_embed(guild_id, user_id):
    player = get_or_create_rpg_player(guild_id, user_id)
    profs = rpg_parse_professions(player)
    loc = RPG_LOCATIONS.get(player.get("location") or "town")
    left = rpg_gather_daily_left(player)
    lines = []
    for pid, info in RPG_PROFESSIONS.items():
        lv = rpg_prof_level(profs.get(pid, 0))
        loc_bonus = " 📍현재지역보너스!" if loc.get("gather_bonus") == pid else ""
        lines.append(f"{info['emoji']} **{info['name']}** Lv.{lv}{loc_bonus}")
    embed = discord.Embed(
        title="🛠️ 생산직",
        description=(
            f"현재 위치: {loc['name']} · 오늘 남은 채집/채광/낚시: **{left}회**\n\n"
            + "\n".join(lines)
            + "\n\n채집·채광·낚시는 아래 버튼으로, 요리·제작은 각 버튼으로 만들어요."
        ),
        color=discord.Color.dark_gold(),
    )
    embed.set_footer(text="지역을 이동하면 특화 생산직 보너스를 받아요 | 만능 봇 RPG")
    return embed


class RPGGatherButton(discord.ui.Button):
    def __init__(self, prof, label, emoji, row):
        super().__init__(label=label, emoji=emoji, style=discord.ButtonStyle.primary, row=row)
        self.prof = prof

    async def callback(self, interaction):
        gid, uid = interaction.guild.id, interaction.user.id
        player = get_or_create_rpg_player(gid, uid)
        if rpg_gather_daily_left(player) <= 0:
            return await interaction.response.send_message(f"⏳ 오늘의 채집/채광/낚시 횟수({RPG_GATHER_DAILY_LIMIT}회)를 다 썼어요. 내일 다시 오세요!", ephemeral=True)
        info = RPG_PROFESSIONS[self.prof]
        # 지역 보너스 + 사회역할
        loc_bonus = rpg_location_gather_bonus(player, self.prof)
        role_double = rpg_social_perk(player, "mining_double") if self.prof == "mining" else 0.0
        got = []
        for item, chance in info["drops"]:
            eff = min(1.0, chance * (1 + loc_bonus))
            if random.random() < eff:
                qty = 1
                if role_double and random.random() < role_double:
                    qty = 2
                add_inventory_item(uid, item, qty, guild_id=gid)
                got.append(f"{item} x{qty}")
        # 숙련 경험치 + 일일 횟수 차감
        today = datetime.datetime.now().strftime("%Y-%m-%d")
        gcount = (player.get("gather_count") or 0) + 1 if player.get("gather_date") == today else 1
        save_rpg_player(gid, uid, gather_date=today, gather_count=gcount)
        leveled, new_lv = rpg_add_prof_exp(gid, uid, self.prof, 100)
        note = f"{info['emoji']} {info['verb']} 결과: " + (", ".join(got) if got else "허탕... 다음 기회에!")
        if leveled:
            note += f"\n🆙 {info['name']} 숙련 Lv.{new_lv} 달성!"
        embed = rpg_build_profession_embed(gid, uid)
        embed.description = note + "\n\n" + (embed.description or "")
        await interaction.response.edit_message(embed=embed, view=RPGProfessionView(gid, uid))


