def rpg_build_physical_embed(guild_id, user_id):
    embed = discord.Embed(
        title="🔥 물리 조작",
        description=(
            "환경과 직접 상호작용해요!\n\n"
            "🔥 **성냥 켜기** — 불을 붙여요. 어두운 곳을 밝힐 수 있어요.\n"
            "🏕️ **모닥불 피우기** — 야영하며 체력을 회복하고 휴식 버프를 얻어요.\n"
            "🪵 **장작 패기** — 힘을 써서 장작을 모아요 (요리 재료).\n"
            "🚪 **문 열기 / 밀기** — 막힌 길을 힘으로 밀어봐요."
        ),
        color=discord.Color.orange(),
    )
    embed.set_footer(text="소소한 상호작용도 RPG의 재미죠! | 만능 봇 RPG")
    return embed


class RPGPhysicalView(discord.ui.View):
    def __init__(self, guild_id, user_id):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        self.match_lit = False

    async def interaction_check(self, interaction):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 본인 패널이 아니에요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="성냥 켜기", emoji="🔥", style=discord.ButtonStyle.secondary, row=0)
    async def light_match(self, interaction, button):
        # 성냥은 확률적으로 켜짐 (물리 조작 감성)
        if random.random() < 0.7:
            self.match_lit = True
            msg = "🔥 치익— 성냥에 불이 붙었어요! 주변이 환해졌어요."
        else:
            msg = "🌬️ 후— 성냥불이 바람에 꺼졌어요. 다시 시도해보세요."
        await interaction.response.send_message(msg, ephemeral=True)

    @discord.ui.button(label="모닥불 피우기(휴식)", emoji="🏕️", style=discord.ButtonStyle.success, row=0)
    async def campfire(self, interaction, button):
        gid, uid = self.guild_id, self.user_id
        player = get_or_create_rpg_player(gid, uid)
        heal = int(player["max_hp"] * 0.5)
        new_hp = min(player["max_hp"], player["hp"] + heal)
        save_rpg_player(gid, uid, hp=new_hp)
        await interaction.response.send_message(f"🏕️ 모닥불 앞에서 휴식했어요. 체력을 **{new_hp - player['hp']}** 회복! (❤️ {new_hp}/{player['max_hp']})", ephemeral=True)

    @discord.ui.button(label="장작 패기", emoji="🪵", style=discord.ButtonStyle.secondary, row=0)
    async def chop_wood(self, interaction, button):
        gid, uid = self.guild_id, self.user_id
        got = random.randint(1, 3)
        add_inventory_item(uid, "장작", got, guild_id=gid)
        await interaction.response.send_message(f"🪵 힘차게 장작을 팼어요! **장작 {got}개** 획득. (요리/모닥불 재료)", ephemeral=True)

    @discord.ui.button(label="문 밀기", emoji="🚪", style=discord.ButtonStyle.secondary, row=1)
    async def push_door(self, interaction, button):
        gid, uid = self.guild_id, self.user_id
        power = rpg_player_power(get_or_create_rpg_player(gid, uid))
        if power > 100:
            msg = "🚪 끼익— 힘으로 무거운 문을 밀어 열었어요! 숨겨진 통로가 보여요."
        else:
            msg = "🚪 끙... 문이 꿈쩍도 안 해요. 더 강해져야겠어요. (전투력 100 이상 필요)"
        await interaction.response.send_message(msg, ephemeral=True)


