# ---------- 선물 시스템 ----------
class RPGGiftModal(discord.ui.Modal, title="선물 보내기"):
    target = discord.ui.TextInput(label="받는 사람 (@멘션 또는 유저ID)", placeholder="@친구 또는 123456789")
    item = discord.ui.TextInput(label="선물할 아이템 이름", placeholder="예: 소환권 / 강화석")
    amount = discord.ui.TextInput(label="개수", placeholder="1", max_length=5)

    def __init__(self, guild_id, user_id):
        super().__init__()
        self.guild_id = guild_id
        self.user_id = user_id

    async def on_submit(self, interaction: discord.Interaction):
        raw = str(self.target).strip()
        m = re.search(r"\d{15,25}", raw)
        if not m:
            return await interaction.response.send_message("받는 사람을 @멘션이나 유저ID로 입력해주세요.", ephemeral=True)
        target_id = int(m.group())
        if target_id == self.user_id:
            return await interaction.response.send_message("자기 자신에게는 선물할 수 없어요.", ephemeral=True)
        item_name = str(self.item).strip()
        try:
            qty = int(str(self.amount).strip())
        except ValueError:
            qty = 0
        if qty < 1:
            return await interaction.response.send_message("개수는 1 이상이어야 해요.", ephemeral=True)
        # 선물 가능한 아이템: RPG 소비아이템 + 드랍재료
        giftable = set(RPG_SHOP_ITEMS) | set(RPG_ITEM_SELL_PRICES)
        if item_name not in giftable:
            return await interaction.response.send_message("선물할 수 없는 아이템이에요. (RPG 소비아이템/드랍재료만 가능)", ephemeral=True)
        if get_inventory_amount(self.user_id, item_name) < qty:
            return await interaction.response.send_message(f"`{item_name}`을(를) {qty}개 갖고 있지 않아요.", ephemeral=True)
        consume_inventory_item(self.user_id, item_name, qty)
        add_inventory_item(target_id, item_name, qty, guild_id=self.guild_id)
        await interaction.response.send_message(f"🎁 <@{target_id}>님에게 **{item_name} {qty}개**를 선물했어요!", ephemeral=False)


