# ---------- 관리자 치트 ----------
class RPGAdminModal(discord.ui.Modal):
    def __init__(self, guild_id, mode):
        titles = {
            "level": "레벨 지급", "exp": "경험치 지급", "item": "아이템 지급", "point": "포인트 지급",
            "point_take": "포인트 회수", "item_take": "아이템 회수", "reset": "유저 RPG 초기화",
            "perk": "퍽 포인트 지급", "pet": "펫 지급", "weapon": "무기 지급", "armor": "방어구 지급",
            "jobquest": "전직 퀘스트 완료 처리", "custom_weapon": "커스텀 무기 지급",
            "stat": "스탯 지급", "heal": "HP 회복/풀회복", "job": "전직 강제 지정",
            "bundle": "묶음 지급 (재료·소환권)", "title": "칭호 지급", "buff": "버프 지급",
        }
        super().__init__(title=titles.get(mode, "관리자 지급"))
        self.guild_id = guild_id
        self.mode = mode
        self.target = discord.ui.TextInput(label="대상 (@멘션 또는 유저ID)", placeholder="@유저 또는 123456789")
        self.add_item(self.target)
        if mode in ("item", "item_take"):
            self.itemname = discord.ui.TextInput(label="아이템 이름", placeholder="예: 소환권")
            self.add_item(self.itemname)
        if mode == "pet":
            self.petname = discord.ui.TextInput(label="펫 이름 (이모지 없이도 가능)", placeholder="예: 태초의 용")
            self.add_item(self.petname)
        if mode == "reset":
            self.confirm = discord.ui.TextInput(label="확인 (초기화하려면 '초기화' 입력)", placeholder="초기화")
            self.add_item(self.confirm)
        elif mode == "jobquest":
            pass  # 대상만 있으면 됨 (현재 전직 단계의 퀘스트를 완료 처리)
        elif mode == "custom_weapon":
            self.cw_name = discord.ui.TextInput(label="무기 이름 (최대 20자)", placeholder="예: 서버 기념검", max_length=20)
            self.add_item(self.cw_name)
            self.cw_power = discord.ui.TextInput(label="전투력 보너스", placeholder="예: 300", max_length=8)
            self.add_item(self.cw_power)
            self.cw_defense = discord.ui.TextInput(label="방어력 보너스", placeholder="예: 150", max_length=8, required=False)
            self.add_item(self.cw_defense)
            self.cw_crit = discord.ui.TextInput(label="크리 확률 % (0~50)", placeholder="예: 10", max_length=4, required=False)
            self.add_item(self.cw_crit)
        elif mode in ("weapon", "armor"):
            self.rarity = discord.ui.TextInput(label="등급 (0~6: 일반~신화/???)", placeholder="예: 4", max_length=2)
            self.add_item(self.rarity)
            self.enhance = discord.ui.TextInput(label="강화 레벨 (0~50)", placeholder="예: 30", max_length=3)
            self.add_item(self.enhance)
        elif mode == "stat":
            stat_names = " / ".join(name for _f, name, _e, _d in RPG_STATS)
            self.statname = discord.ui.TextInput(label="스탯 종류 ('포인트'=미분배 포인트)", placeholder=f"{stat_names} / 포인트")
            self.add_item(self.statname)
            self.value = discord.ui.TextInput(label="지급 수치 (음수=회수)", placeholder="예: 20")
            self.add_item(self.value)
        elif mode == "heal":
            pass  # 대상만 있으면 됨 (HP 풀회복)
        elif mode == "job":
            self.jobname = discord.ui.TextInput(label="직업 (전사/마법사/궁수/사제/도적 등)", placeholder="예: 전사")
            self.add_item(self.jobname)
            self.jobtier = discord.ui.TextInput(label="전직 단계 (1~6)", placeholder="예: 3", max_length=1)
            self.add_item(self.jobtier)
        elif mode == "bundle":
            self.value = discord.ui.TextInput(label="세트 배수 (기본 1)", placeholder="예: 1", max_length=3, required=False, default="1")
            self.add_item(self.value)
        elif mode == "title":
            self.titlename = discord.ui.TextInput(label="칭호 이름", placeholder="예: 서버 개국공신")
            self.add_item(self.titlename)
        elif mode == "buff":
            self.bufftype = discord.ui.TextInput(label="버프 종류 (공격/방어/전체)", placeholder="공격 / 방어 / 전체")
            self.add_item(self.bufftype)
            self.value = discord.ui.TextInput(label="버프 배율 % (예: 30)", placeholder="예: 30", max_length=4)
            self.add_item(self.value)
        elif mode != "pet":
            self.value = discord.ui.TextInput(label=("레벨" if mode == "level" else "수량/값"), placeholder="예: 10")
            self.add_item(self.value)

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
        m = re.search(r"\d{15,25}", str(self.target))
        if not m:
            return await interaction.response.send_message("대상을 @멘션/유저ID로 입력하세요.", ephemeral=True)
        target_id = int(m.group())
        gid = self.guild_id

        # 초기화 모드
        if self.mode == "reset":
            if str(self.confirm).strip() != "초기화":
                return await interaction.response.send_message("❌ 초기화를 취소했어요. (확인란에 '초기화'를 정확히 입력해야 실행됩니다)", ephemeral=True)
            with DB_MUTEX:
                c.execute("DELETE FROM rpg_players WHERE guild_id=? AND user_id=?", (gid, target_id))
                conn.commit()
            get_or_create_rpg_player(gid, target_id)
            return await interaction.response.send_message(f"🗑️ <@{target_id}> 님의 RPG 데이터를 초기화했어요. (레벨/스탯/직업 리셋, 포인트·인벤토리는 유지)", ephemeral=True)

        # 전직 퀘스트 완료 처리 (현재 전직 단계의 퀘스트를 목표치까지 채움)
        if self.mode == "jobquest":
            p = get_or_create_rpg_player(gid, target_id)
            job_id, tier = rpg_parse_job_field(p.get("job"))
            next_tier = (tier or 1) + 1
            quest = RPG_JOB_QUESTS.get(next_tier)
            if not quest:
                return await interaction.response.send_message(f"ℹ️ <@{target_id}> 님은 현재 완료할 전직 퀘스트가 없어요. (이미 최종 단계이거나 직업 미선택)", ephemeral=True)
            quests = rpg_parse_jobquest(p)
            quests[quest["id"]] = quest["target"]
            save_rpg_player(gid, target_id, jobquest=",".join(f"{k}:{v}" for k, v in quests.items()))
            return await interaction.response.send_message(
                f"📜 <@{target_id}> 님의 전직 퀘스트 **{quest['name']}**({quest['desc']})을 완료 처리했어요. 이제 전직할 수 있어요!",
                ephemeral=True,
            )

        # 커스텀 무기 지급 (서버 전용 무기)
        if self.mode == "custom_weapon":
            try:
                power = max(0, int(str(self.cw_power).strip()))
                defense = max(0, int(str(self.cw_defense).strip() or "0"))
                crit = max(0.0, min(0.5, float(str(self.cw_crit).strip() or "0") / 100))
            except ValueError:
                return await interaction.response.send_message("숫자 값을 올바르게 입력하세요.", ephemeral=True)
            name = str(self.cw_name).strip()[:20]
            if not name:
                return await interaction.response.send_message("무기 이름을 입력하세요.", ephemeral=True)
            cw = {"name": name, "blade": "관리자 특제", "handle": "관리자 특제", "gem": "관리자 특제",
                  "power": power, "defense": defense, "crit": crit}
            save_rpg_player(gid, target_id, custom_weapon=json.dumps(cw, ensure_ascii=False))
            return await interaction.response.send_message(
                f"🛠️ <@{target_id}>에게 커스텀 무기 **{name}** 지급! (전투+{power}/방어+{defense}/크리+{crit*100:.0f}%)",
                ephemeral=True,
            )

        # 펫 지급
        if self.mode == "pet":
            pet_input = str(self.petname).strip()
            matched = None
            for name in RPG_PET_INFO_BY_NAME:
                if pet_input == name or pet_input in name or name.split(" ")[-1] == pet_input:
                    matched = name
                    break
            if not matched:
                return await interaction.response.send_message(f"❌ '{pet_input}' 펫을 찾을 수 없어요. 정확한 펫 이름을 입력하세요.", ephemeral=True)
            rarity_index = RPG_PET_INFO_BY_NAME[matched][0]
            rpg_add_pet(gid, target_id, matched, rarity_index)
            return await interaction.response.send_message(f"🐾 <@{target_id}>에게 펫 **{matched}**을(를) 지급했어요.", ephemeral=True)

        # 무기/방어구 지급
        if self.mode in ("weapon", "armor"):
            try:
                rarity = max(0, min(6, int(str(self.rarity).strip())))
                enhance = max(0, min(RPG_MAX_EQUIP_LEVEL, int(str(self.enhance).strip())))
            except ValueError:
                return await interaction.response.send_message("등급/강화 레벨을 숫자로 입력하세요.", ephemeral=True)
            if self.mode == "weapon":
                save_rpg_player(gid, target_id, weapon_rarity=rarity, weapon_level=max(1, enhance))
                tier = rpg_rarity_tier(rarity)
                return await interaction.response.send_message(f"⚔️ <@{target_id}>에게 **{tier['emoji']}{tier['name']} 무기 +{enhance}**를 지급했어요.", ephemeral=True)
            else:
                save_rpg_player(gid, target_id, armor_rarity=rarity, armor_level=enhance)
                tier = rpg_rarity_tier(rarity)
                return await interaction.response.send_message(f"🛡️ <@{target_id}>에게 **{tier['emoji']}{tier['name']} 방어구 +{enhance}**를 지급했어요.", ephemeral=True)

        # HP 풀회복
        if self.mode == "heal":
            p = get_or_create_rpg_player(gid, target_id)
            save_rpg_player(gid, target_id, hp=p["max_hp"])
            return await interaction.response.send_message(f"❤️ <@{target_id}> 님의 HP를 **{p['max_hp']:,}** (풀)로 회복했어요.", ephemeral=True)

        # 전직 강제 지정
        if self.mode == "job":
            job_input = str(self.jobname).strip()
            matched_id = None
            for line in RPG_JOB_LINES:
                if job_input == line["line_name"] or job_input == line["job_id"] or job_input in line["line_name"]:
                    matched_id = line["job_id"]
                    break
            if not matched_id:
                names = " / ".join(l["line_name"] for l in RPG_JOB_LINES if "_" not in l["job_id"] or l["job_id"].endswith("_base"))
                return await interaction.response.send_message(f"❌ '{job_input}' 직업을 찾을 수 없어요.\n사용 가능: {names}", ephemeral=True)
            try:
                tier = max(1, min(6, int(str(self.jobtier).strip())))
            except ValueError:
                tier = 1
            save_rpg_player(gid, target_id, job=f"{matched_id}:{tier}")
            line = rpg_resolve_job_line(matched_id)
            title = line["tier_titles"][tier - 1] if line else matched_id
            return await interaction.response.send_message(f"🎓 <@{target_id}> 님을 **{title}** ({line['line_name']} {tier}차)로 전직시켰어요.", ephemeral=True)

        # 칭호 지급
        if self.mode == "title":
            title_name = str(self.titlename).strip()
            if not title_name:
                return await interaction.response.send_message("칭호 이름을 입력하세요.", ephemeral=True)
            added = add_user_title(gid, target_id, title_name)
            if added:
                return await interaction.response.send_message(f"🏷️ <@{target_id}>에게 칭호 **{title_name}**을(를) 지급했어요.", ephemeral=True)
            return await interaction.response.send_message(f"ℹ️ <@{target_id}> 님은 이미 **{title_name}** 칭호를 보유 중이에요.", ephemeral=True)

        try:
            val = int(str(self.value).strip())
        except ValueError:
            return await interaction.response.send_message("숫자 값을 입력하세요.", ephemeral=True)
        if self.mode == "level":
            val = max(1, min(RPG_MAX_LEVEL, val))
            p = get_or_create_rpg_player(gid, target_id)
            new_max = 100 + (val - 1) * 10
            expected_pts = (val - 1) * RPG_STAT_POINTS_PER_LEVEL
            cur_alloc = sum(p[f] for f in RPG_STAT_FIELDS)
            save_rpg_player(gid, target_id, level=val, exp=0, max_hp=new_max, hp=new_max, stat_points=max(0, expected_pts - cur_alloc))
            msg = f"✅ <@{target_id}> 레벨을 **Lv.{val}**로 설정했어요."
        elif self.mode == "exp":
            p = get_or_create_rpg_player(gid, target_id)
            _lv, p = rpg_apply_exp(p, val)
            save_rpg_player(gid, target_id, level=p["level"], exp=p["exp"], max_hp=p["max_hp"], hp=p["max_hp"], stat_points=p["stat_points"])
            msg = f"✅ <@{target_id}>에게 경험치 **{val:,}**를 지급했어요. (현재 Lv.{p['level']})"
        elif self.mode == "point":
            set_user_point(gid, target_id, get_user_point(gid, target_id) + val)
            msg = f"✅ <@{target_id}>에게 **{val:,}P**를 지급했어요."
        elif self.mode == "perk":
            p = get_or_create_rpg_player(gid, target_id)
            new_perk = max(0, (p.get("perk_points", 0) or 0) + val)
            save_rpg_player(gid, target_id, perk_points=new_perk)
            msg = f"✅ <@{target_id}>에게 퍽 포인트 **{val:+}**를 지급했어요. (현재 {new_perk}P)"
        elif self.mode == "point_take":
            cur = get_user_point(gid, target_id)
            taken = min(cur, max(0, val))
            set_user_point(gid, target_id, cur - taken)
            msg = f"➖ <@{target_id}>에게서 **{taken:,}P**를 회수했어요. (잔액 {cur - taken:,}P)"
        elif self.mode == "item_take":
            item_name = str(self.itemname).strip()
            have = get_inventory_amount(target_id, item_name)
            take = min(have, max(0, val))
            if take > 0:
                consume_inventory_item(target_id, item_name, take)
            msg = f"➖ <@{target_id}>에게서 **{item_name} {take}개**를 회수했어요. (보유 {have}→{have - take})"
        elif self.mode == "stat":
            stat_input = str(self.statname).strip()
            p = get_or_create_rpg_player(gid, target_id)
            if stat_input in ("포인트", "스탯포인트", "point", "포인트지급"):
                new_pts = max(0, (p.get("stat_points", 0) or 0) + val)
                save_rpg_player(gid, target_id, stat_points=new_pts)
                msg = f"📈 <@{target_id}>에게 미분배 스탯 포인트 **{val:+}**를 지급했어요. (현재 {new_pts}P)"
            else:
                field = RPG_STAT_BY_NAME.get(stat_input)
                if not field:
                    names = " / ".join(name for _f, name, _e, _d in RPG_STATS)
                    return await interaction.response.send_message(f"❌ '{stat_input}' 스탯을 찾을 수 없어요.\n사용 가능: {names} / 포인트", ephemeral=True)
                new_v = max(0, (p.get(field, 0) or 0) + val)
                save_rpg_player(gid, target_id, **{field: new_v})
                msg = f"📈 <@{target_id}> 님의 **{stat_input}**을(를) {val:+} 조정했어요. (현재 {new_v})"
        elif self.mode == "bundle":
            times = max(1, min(999, val))
            bundle = {"소환권": 10, "강화석": 50, "보호권": 5, "축복의 물약": 3, "골드주머니": 5}
            for item_name, amt in bundle.items():
                add_inventory_item(target_id, item_name, amt * times, guild_id=gid)
            detail = ", ".join(f"{k} {v*times}개" for k, v in bundle.items())
            msg = f"🎁 <@{target_id}>에게 묶음 세트 x{times}를 지급했어요.\n({detail})"
        elif self.mode == "buff":
            btype = str(self.bufftype).strip()
            effect_map = {"공격": "buff_power", "방어": "buff_defense", "전체": "buff_all",
                          "공격력": "buff_power", "방어력": "buff_defense", "올": "buff_all"}
            effect = effect_map.get(btype)
            if not effect:
                return await interaction.response.send_message("❌ 버프 종류는 공격/방어/전체 중 하나로 입력하세요.", ephemeral=True)
            ratio = max(0.0, min(5.0, val / 100))
            save_rpg_player(gid, target_id, food_buff=f"{effect}:{ratio}")
            label = {"buff_power": "⚔️ 공격", "buff_defense": "🛡️ 방어", "buff_all": "🎉 전체"}[effect]
            msg = f"🔥 <@{target_id}>에게 {label} 버프 **+{val}%**를 지급했어요. (다음 전투 1회 적용)"
        else:  # item
            item_name = str(self.itemname).strip()
            add_inventory_item(target_id, item_name, val, guild_id=gid)
            msg = f"✅ <@{target_id}>에게 **{item_name} {val}개**를 지급했어요."
        await interaction.response.send_message(msg, ephemeral=True)


class RPGAdminInspectModal(discord.ui.Modal, title="🔍 유저 RPG 조회"):
    target = discord.ui.TextInput(label="대상 (@멘션 또는 유저ID)", placeholder="@유저 또는 123456789")

    def __init__(self, guild_id):
        super().__init__()
        self.guild_id = guild_id

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
        m = re.search(r"\d{15,25}", str(self.target))
        if not m:
            return await interaction.response.send_message("대상을 @멘션/유저ID로 입력하세요.", ephemeral=True)
        target_id = int(m.group())
        gid = self.guild_id
        p = get_or_create_rpg_player(gid, target_id)
        job_id, tier = rpg_parse_job_field(p.get("job"))
        line = rpg_resolve_job_line(job_id) if job_id else None
        job_txt = f"{line['tier_titles'][tier-1]} ({line['line_name']})" if line else "미선택"
        point = get_user_point(gid, target_id)
        stat_txt = " · ".join(f"{name}:{p.get(f, 0)}" for f, name, _e, _d in RPG_STATS)
        embed = discord.Embed(title=f"🔍 <@{target_id}> RPG 상태", color=discord.Color.dark_teal())
        embed.description = (
            f"레벨 **Lv.{p['level']}** · EXP {p['exp']:,}\n"
            f"HP {p['hp']}/{p['max_hp']} · 직업 {job_txt}\n"
            f"포인트 **{point:,}P** · 미분배 스탯 {p.get('stat_points', 0)}P\n"
            f"환생 {p.get('rebirth', 0)} · 진화 {p.get('evolution', 0)} · 차원 {p.get('dimension', 0)}\n\n"
            f"**스탯**\n{stat_txt}"
        )
        await interaction.response.send_message(embed=embed, ephemeral=True)


class RPGAdminBulkModal(discord.ui.Modal):
    """전체 유저 대상 단체 지급/공지 모달."""
    def __init__(self, guild_id, mode):
        titles = {"bulk_point": "전체 포인트 지급", "bulk_item": "전체 아이템 지급", "broadcast": "RPG 공지 보내기"}
        super().__init__(title=titles.get(mode, "단체 관리"))
        self.guild_id = guild_id
        self.mode = mode
        if mode == "bulk_point":
            self.amount = discord.ui.TextInput(label="지급할 포인트 (모든 RPG 유저에게)", placeholder="예: 1000")
            self.add_item(self.amount)
        elif mode == "bulk_item":
            self.itemname = discord.ui.TextInput(label="아이템 이름", placeholder="예: 소환권")
            self.add_item(self.itemname)
            self.amount = discord.ui.TextInput(label="개수", placeholder="예: 3", default="1")
            self.add_item(self.amount)
        elif mode == "broadcast":
            self.title_input = discord.ui.TextInput(label="공지 제목", placeholder="예: 주말 이벤트 안내", max_length=100)
            self.add_item(self.title_input)
            self.content = discord.ui.TextInput(label="공지 내용", style=discord.TextStyle.paragraph, max_length=1500)
            self.add_item(self.content)

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
        gid = self.guild_id
        # RPG 플레이어 전체 대상
        with DB_MUTEX:
            c.execute("SELECT user_id FROM rpg_players WHERE guild_id=?", (gid,))
            user_ids = [r[0] for r in c.fetchall()]

        if self.mode == "bulk_point":
            try:
                amt = int(str(self.amount).strip())
            except ValueError:
                return await interaction.response.send_message("❌ 숫자를 입력해주세요.", ephemeral=True)
            for uid in user_ids:
                set_user_point(gid, uid, get_user_point(gid, uid) + amt)
            return await interaction.response.send_message(f"✅ RPG 유저 **{len(user_ids)}명**에게 {amt:,}P를 지급했어요.", ephemeral=True)

        if self.mode == "bulk_item":
            item = str(self.itemname).strip()
            try:
                amt = max(1, int(str(self.amount).strip()))
            except ValueError:
                amt = 1
            for uid in user_ids:
                add_inventory_item(uid, item, amt, guild_id=gid)
            return await interaction.response.send_message(f"✅ RPG 유저 **{len(user_ids)}명**에게 {item} {amt}개씩 지급했어요.", ephemeral=True)

        if self.mode == "broadcast":
            embed = discord.Embed(title=f"📢 {str(self.title_input)[:250]}", description=str(self.content)[:1500].replace("\\n", "\n"), color=0x87CEFA)
            embed.set_footer(text=f"{interaction.guild.name} · RPG 공지")
            # RPG 랭킹 채널 우선, 없으면 현재 채널
            ch = None
            try:
                with DB_MUTEX:
                    c.execute("SELECT channel_id FROM rpg_channels WHERE guild_id=? AND feature=?", (gid, "랭킹"))
                    crow = c.fetchone()
                ch = interaction.guild.get_channel(crow[0]) if crow else None
            except Exception:
                ch = None
            ch = ch or interaction.channel
            try:
                await ch.send(embed=embed)
            except (discord.Forbidden, discord.HTTPException):
                return await interaction.response.send_message("⚠️ 공지 전송에 실패했어요. 채널 권한을 확인해주세요.", ephemeral=True)
            return await interaction.response.send_message(f"✅ {ch.mention}에 RPG 공지를 보냈어요.", ephemeral=True)


class RPGAdminContentView(discord.ui.View):
    """신규 콘텐츠 관리: 던전 초기화 / 월드보스 소환 / 시즌 강제 리셋."""
    def __init__(self, guild_id):
        super().__init__(timeout=180)
        self.guild_id = guild_id

    async def interaction_check(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="던전 랭킹 초기화", emoji="🏰", style=discord.ButtonStyle.danger)
    async def dungeon_reset(self, interaction, button):
        gid = self.guild_id
        top3 = rpg_dungeon_top3(gid)
        payouts = []
        for idx, (uid, floor, level) in enumerate(top3):
            reward = RPG_DUNGEON_SEASON_REWARDS.get(idx + 1)
            if not reward:
                continue
            point, item_name, item_amt = reward
            set_user_point(gid, uid, get_user_point(gid, uid) + point)
            add_inventory_item(uid, item_name, item_amt, guild_id=gid)
            payouts.append(f"{['🥇','🥈','🥉'][idx]} <@{uid}> {floor}층 · 💰{point:,}P + {item_name} {item_amt}개")
        now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        cur = rpg_dungeon_season_key()
        with DB_MUTEX:
            c.execute("UPDATE rpg_players SET dungeon_floor=0, dungeon_date='', dungeon_attempts=0 WHERE guild_id=?", (gid,))
            c.execute(
                "INSERT INTO rpg_dungeon_season(guild_id, season_key, reset_at) VALUES (?,?,?) "
                "ON CONFLICT(guild_id) DO UPDATE SET season_key=excluded.season_key, reset_at=excluded.reset_at",
                (gid, cur, now),
            )
            conn.commit()
        desc = ("보상 지급:\n" + "\n".join(payouts)) if payouts else "도전 기록이 없어 보상은 없었어요."
        await interaction.response.send_message(f"🏰 던전 랭킹을 초기화했어요.\n{desc}", ephemeral=True)

    @discord.ui.button(label="월드보스 소환", emoji="🐉", style=discord.ButtonStyle.danger)
    async def worldboss_spawn(self, interaction, button):
        if rpg_get_worldboss(self.guild_id):
            return await interaction.response.send_message("⚠️ 이미 월드보스가 등장해 있어요.", ephemeral=True)
        boss = rpg_worldboss_spawn(self.guild_id)
        await interaction.response.send_message(f"✨ {boss['boss_emoji']} **{boss['boss_name']}** 소환! (난이도 {rpg_worldboss_difficulty(boss['boss_name'])} · 체력 {boss['max_hp']:,} · 보상풀 {boss['reward_pool']:,}P)\n유저들이 `/rpg2 월드보스 행동:공격`으로 도전할 수 있어요.", ephemeral=False)

    @discord.ui.button(label="시즌패스 강제 초기화", emoji="🎟️", style=discord.ButtonStyle.secondary)
    async def season_pass_reset(self, interaction, button):
        gid = self.guild_id
        season = rpg_season_pass_month_key()
        with DB_MUTEX:
            c.execute("DELETE FROM rpg_season_pass WHERE guild_id=? AND season_key=?", (gid, season))
            conn.commit()
        await interaction.response.send_message("🎟️ 이번 달 시즌패스 진행도를 초기화했어요. (모든 유저 XP·수령기록 리셋)", ephemeral=True)


