class RPGAdminEconomyView(discord.ui.View):
    def __init__(self, guild_id):
        super().__init__(timeout=180)
        self.guild_id = guild_id

    async def interaction_check(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="복권 강제 추첨", emoji="🎲", style=discord.ButtonStyle.danger)
    async def draw_lottery(self, interaction, button):
        result = rpg_lottery_draw(self.guild_id)
        win_str = ", ".join(str(n) for n in result["winning"])
        payout_lines = [f"<@{uid}> +{amt:,}P" for uid, amt in sorted(result["payouts"].items(), key=lambda x: -x[1])[:15]]
        embed = discord.Embed(
            title=f"🎲 복권 {result['round_no']}회차 추첨 결과!",
            description=(
                f"🎯 당첨 번호: **{win_str}**\n🎫 총 판매: {result['ticket_count']}장\n\n"
                + ("**💰 당첨자**\n" + "\n".join(payout_lines) if payout_lines else "당첨자 없음 → 다음 회차 이월")
                + f"\n\n다음 회차 상금 풀: **{result['next_pool']:,}P**"
            ),
            color=discord.Color.gold(),
        )
        await interaction.response.send_message(embed=embed)

    @discord.ui.button(label="만료 경매 정산", emoji="🏛️", style=discord.ButtonStyle.primary)
    async def settle_auctions(self, interaction, button):
        results = rpg_auction_settle_expired(self.guild_id)
        sold = sum(1 for r in results if r.get("sold"))
        unsold = len(results) - sold
        await interaction.response.send_message(f"🏛️ 경매 정산 완료: 낙찰 {sold}건, 유찰 {unsold}건", ephemeral=True)

    @discord.ui.button(label="전체 경매 취소·반환", emoji="↩️", style=discord.ButtonStyle.secondary)
    async def cancel_all_auctions(self, interaction, button):
        with DB_MUTEX:
            c.execute("SELECT id FROM rpg_auctions WHERE guild_id=? AND status='open'", (self.guild_id,))
            ids = [r[0] for r in c.fetchall()]
        for aid in ids:
            a = rpg_auction_get(aid)
            if not a:
                continue
            # 최고입찰자 환불 + 판매자에게 아이템 반환
            if a["top_bidder_id"]:
                set_user_point(self.guild_id, a["top_bidder_id"], get_user_point(self.guild_id, a["top_bidder_id"]) + a["current_bid"])
            add_inventory_item(a["seller_id"], a["item_name"], a["amount"], guild_id=self.guild_id)
            with DB_MUTEX:
                c.execute("UPDATE rpg_auctions SET status='cancelled' WHERE id=?", (aid,))
                conn.commit()
        await interaction.response.send_message(f"↩️ 진행 중이던 경매 {len(ids)}건을 취소하고 아이템·입찰금을 반환했어요.", ephemeral=True)


