class _RPGAdminActionButton(discord.ui.Button):
    def __init__(self, guild_id, label, emoji, style, kind, arg, row):
        super().__init__(label=label, emoji=emoji, style=style, row=row)
        self.guild_id = guild_id
        self.kind = kind
        self.arg = arg

    async def callback(self, interaction):
        if self.kind == "inspect":
            return await interaction.response.send_modal(RPGAdminInspectModal(self.guild_id))
        if self.kind == "economy":
            embed = discord.Embed(
                title="🏦 RPG 경제 관리",
                description="복권 강제 추첨, 만료 경매 정산, 전체 경매 취소·반환을 할 수 있어요.",
                color=discord.Color.dark_gold(),
            )
            return await interaction.response.send_message(embed=embed, view=RPGAdminEconomyView(self.guild_id), ephemeral=True)
        if self.kind == "image":
            return await interaction.response.send_message(embed=rpg_build_image_admin_embed(), view=RPGImageAdminView(), ephemeral=True)
        if self.kind == "content":
            embed = discord.Embed(
                title="🐉 신규 콘텐츠 관리",
                description="던전 랭킹 초기화, 월드보스 소환, 시즌패스 강제 초기화를 할 수 있어요.",
                color=discord.Color.dark_red(),
            )
            return await interaction.response.send_message(embed=embed, view=RPGAdminContentView(self.guild_id), ephemeral=True)
        if self.kind == "bulk":
            embed = discord.Embed(
                title="📢 단체 관리",
                description="모든 RPG 유저에게 포인트·아이템을 지급하거나, RPG 공지를 보낼 수 있어요.",
                color=discord.Color.blurple(),
            )
            return await interaction.response.send_message(embed=embed, view=RPGAdminBulkView(self.guild_id), ephemeral=True)
        # kind == "modal" 또는 "reset"
        await interaction.response.send_modal(RPGAdminModal(self.guild_id, self.arg))


class _RPGAdminNavButton(discord.ui.Button):
    def __init__(self, label, emoji, direction, disabled):
        super().__init__(label=label, emoji=emoji, style=discord.ButtonStyle.secondary, row=4, disabled=disabled)
        self.direction = direction

    async def callback(self, interaction):
        view: "RPGAdminView" = self.view
        view.page = (view.page + self.direction) % len(_RPG_ADMIN_PAGES)
        view.rebuild()
        await interaction.response.edit_message(embed=view.build_embed(), view=view)


class RPGAdminView(discord.ui.View):
    def __init__(self, guild_id, page: int = 0):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.page = page
        self.rebuild()

    async def interaction_check(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
            return False
        return True

    def build_embed(self):
        page = _RPG_ADMIN_PAGES[self.page]
        embed = rpg_build_admin_embed()
        embed.add_field(
            name=f"📄 {page['title']}  ({self.page + 1}/{len(_RPG_ADMIN_PAGES)})",
            value="아래 버튼으로 실행하고, ◀ ▶ 로 페이지를 넘겨보세요.",
            inline=False,
        )
        return embed

    def rebuild(self):
        self.clear_items()
        actions = _RPG_ADMIN_PAGES[self.page]["actions"]
        for i, (label, emoji, style, kind, arg) in enumerate(actions):
            row = i // 5  # 한 줄에 5개, 최대 4줄(20개)까지
            self.add_item(_RPGAdminActionButton(self.guild_id, label, emoji, style, kind, arg, row))
        multi = len(_RPG_ADMIN_PAGES) > 1
        self.add_item(_RPGAdminNavButton("이전", "◀", -1, disabled=not multi))
        self.add_item(_RPGAdminNavButton("다음", "▶", 1, disabled=not multi))


def rpg_build_admin_embed():
    embed = discord.Embed(
        title="🛠️ RPG 관리자 도구",
        description=(
            "관리자 전용 통합 도구예요.\n\n"
            "**지급**: 레벨·경험치·포인트·아이템·퍽포인트·무기·방어구·펫\n"
            "**회수**: 포인트·아이템 차감\n"
            "**유저 조회**: 특정 유저 RPG 상태 열람\n"
            "**유저 초기화**: 레벨/스탯/직업 리셋\n"
            "**경제 관리**: 복권 추첨·경매 정산/취소\n"
            "🖼️ **이미지 등록**: 몬스터/보스/펫/유물/장신구"
        ),
        color=discord.Color.dark_red(),
    )
    embed.set_footer(text="관리자 전용 | 만능 봇 RPG")
    return embed


# ---------- 이미지 URL 등록 패널 ----------
def rpg_build_image_admin_embed(category: str = None) -> discord.Embed:
    if not category:
        desc = "이미지를 등록할 카테고리를 먼저 선택하세요.\n\n" + " · ".join(f"{v}" for v in RPG_IMAGE_CATEGORIES.values())
        embed = discord.Embed(title="🖼️ RPG 이미지 등록", description=desc, color=discord.Color.blurple())
        embed.set_footer(text="URL은 https:// 로 시작하는 이미지 직링크를 넣어주세요 | 만능 봇 RPG")
        return embed
    cat_name = RPG_IMAGE_CATEGORIES.get(category, category)
    keys = rpg_image_keys(category)
    registered = sum(1 for _label, key in keys if rpg_get_image(category, key))
    lines = []
    for label, key in keys[:20]:
        mark = "✅" if rpg_get_image(category, key) else "⬜"
        lines.append(f"{mark} {label}")
    more = f"\n… 외 {len(keys) - 20}개" if len(keys) > 20 else ""
    embed = discord.Embed(
        title=f"🖼️ {cat_name} 이미지 등록 ({registered}/{len(keys)})",
        description="\n".join(lines) + more + "\n\n아래 메뉴에서 항목을 골라 URL을 등록하세요.",
        color=discord.Color.blurple(),
    )
    embed.set_footer(text="✅=등록됨 · ⬜=미등록 | 만능 봇 RPG")
    return embed


class RPGImageCategorySelect(discord.ui.Select):
    def __init__(self, category=None):
        options = [discord.SelectOption(label=name, value=cat, default=(cat == category)) for cat, name in RPG_IMAGE_CATEGORIES.items()]
        super().__init__(placeholder="이미지 카테고리 선택", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction: discord.Interaction):
        view: "RPGImageAdminView" = self.view
        view.category = self.values[0]
        view.page = 0
        view.refresh_items()
        await interaction.response.edit_message(embed=rpg_build_image_admin_embed(view.category), view=view)


class RPGImageItemSelect(discord.ui.Select):
    def __init__(self, category, page=0):
        self.category = category
        self.page = page
        keys = rpg_image_keys(category)
        start = page * 25
        chunk = keys[start:start + 25]
        options = []
        for label, key in chunk:
            mark = "✅" if rpg_get_image(category, key) else "⬜"
            options.append(discord.SelectOption(label=f"{mark} {label}"[:100], value=str(key)))
        if not options:
            options = [discord.SelectOption(label="항목 없음", value="__none__")]
        super().__init__(placeholder="이미지를 등록할 항목 선택", min_values=1, max_values=1, options=options, row=1)

    async def callback(self, interaction: discord.Interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        await interaction.response.send_modal(RPGImageURLModal(self.category, self.values[0]))


class RPGImageURLModal(discord.ui.Modal, title="이미지 URL 등록"):
    url_input = discord.ui.TextInput(label="이미지 URL (비우면 삭제)", required=False, placeholder="https://...", max_length=500)

    def __init__(self, category, key):
        super().__init__()
        self.category = category
        self.key = key
        cur = rpg_get_image(category, key)
        if cur:
            self.url_input.default = cur

    async def on_submit(self, interaction: discord.Interaction):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
        url = str(self.url_input).strip()
        if url and not url.lower().startswith("http"):
            return await interaction.response.send_message("❌ http(s):// 로 시작하는 URL을 넣어주세요.", ephemeral=True)
        rpg_set_image(self.category, self.key, url)
        note = f"✅ **{self.key}** 이미지를 {'등록' if url else '삭제'}했어요."
        embed = rpg_build_image_admin_embed(self.category)
        embed.description = note + "\n\n" + (embed.description or "")
        try:
            await interaction.response.edit_message(embed=embed, view=RPGImageAdminView(self.category))
        except discord.InteractionResponded:
            await interaction.followup.send(note, ephemeral=True)


class RPGImageAdminView(discord.ui.View):
    def __init__(self, category=None):
        super().__init__(timeout=300)
        self.category = category
        self.page = 0
        self.refresh_items()

    async def interaction_check(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message("❌ 관리자만 사용할 수 있어요.", ephemeral=True)
            return False
        return True

    def refresh_items(self):
        self.clear_items()
        self.add_item(RPGImageCategorySelect(self.category))
        if self.category:
            self.add_item(RPGImageItemSelect(self.category, self.page))
            keys = rpg_image_keys(self.category)
            if len(keys) > 25:
                self.add_item(RPGImagePageButton(-1))
                self.add_item(RPGImagePageButton(1))


class RPGImagePageButton(discord.ui.Button):
    def __init__(self, delta):
        super().__init__(label="◀ 이전" if delta < 0 else "다음 ▶", style=discord.ButtonStyle.gray, row=2)
        self.delta = delta

    async def callback(self, interaction: discord.Interaction):
        view: "RPGImageAdminView" = self.view
        keys = rpg_image_keys(view.category)
        max_page = (len(keys) - 1) // 25
        view.page = max(0, min(max_page, view.page + self.delta))
        view.refresh_items()
        await interaction.response.edit_message(embed=rpg_build_image_admin_embed(view.category), view=view)


@rpg_group.command(name="보스", description="5분마다 강력한 보스 몬스터에게 도전합니다. (보상이 훨씬 커요)")
async def rpg_group_boss(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await rpg_check_feature_channel(interaction, "보스"):
        return

    guild_id = interaction.guild.id
    user_id = interaction.user.id
    player = get_or_create_rpg_player(guild_id, user_id)

    now = datetime.datetime.now()
    # 1번: 보스 쿨타임 5분 고정 (기존 하루 1회 제한에서 변경)
    if player["last_boss_at"]:
        try:
            last_boss = datetime.datetime.strptime(player["last_boss_at"], "%Y-%m-%d %H:%M:%S")
            elapsed_boss = (now - last_boss).total_seconds()
            if elapsed_boss < RPG_BOSS_COOLDOWN_SECONDS:
                remaining = int(RPG_BOSS_COOLDOWN_SECONDS - elapsed_boss)
                return await safe_interaction_send(interaction, f"⏳ 보스 도전은 5분마다 1번! ({remaining // 60}분 {remaining % 60}초 남음)", ephemeral=True)
        except ValueError:
            # 예전 데이터(날짜 형식)는 무시하고 도전 허용
            pass

    if player["hp"] <= 0:
        return await safe_interaction_send(interaction, "💀 체력이 없어서 도전할 수 없어요. 체력을 먼저 회복해주세요.", ephemeral=True)

    boss = rpg_pick_boss(player["level"], player.get("location"))
    # 6번: 길드 전투 버프 주입
    _gb = rpg_guild_buffs(guild_id, user_id)
    player["_guild_power_buff"] = _gb.get("power", 0.0)
    player["_guild_defense_buff"] = _gb.get("defense", 0.0)
    # 🍽️ 음식 버프 (다음 전투 1회)
    boss_food = rpg_pop_food_buff(guild_id, user_id, player)
    if boss_food:
        player["_guild_power_buff"] += boss_food.get("power", 0.0)
        player["_guild_defense_buff"] += boss_food.get("defense", 0.0)
    # 15번: 시간 스케일링 — 보스도 시간대에 따라 강함/보상 변동
    time_phase = rpg_current_time_phase()
    if time_phase["monster_mult"] != 1.0:
        boss = dict(boss)
        boss["hp"] = max(1, int(boss["hp"] * time_phase["monster_mult"]))
        boss["power"] = max(1, int(boss["power"] * time_phase["monster_mult"]))
    battle_skill = rpg_pop_active_skill(guild_id, user_id, player)
    final_hp, boss_final_hp, won, log, damage_taken = rpg_simulate_battle(player, boss, battle_skill)
    player["hp"] = final_hp

    # ⚰️ 시가바네: 보스에게 죽으면 '불굴' 특성 획득
    boss_death_note = ""
    if not won and final_hp <= 0:
        result = rpg_record_death(guild_id, user_id, "boss_kill")
        if result and not result["maxed"]:
            boss_death_note = f"⚰️ 죽음의 성장! **{result['info']['name']} Lv.{result['level']}** ({result['info']['desc']})"

    level_ups = []
    exp_gain = 0
    gold_gain = 0
    drop_lines = []
    if won:
        exp_mult = rpg_reward_multiplier(interaction.guild, guild_id, "exp")
        gold_mult = rpg_reward_multiplier(interaction.guild, guild_id, "gold")
        drop_event_mult = rpg_reward_multiplier(interaction.guild, guild_id, "drop")
        party_mult = rpg_party_exp_multiplier(guild_id, user_id)  # 파티 보너스
        # 15번: 시간대 배율
        exp_mult *= party_mult * time_phase["reward_mult"]
        gold_mult *= party_mult * time_phase["reward_mult"]
        exp_gain = int(boss["exp"] * exp_mult)
        level_ups, player = rpg_apply_exp(player, exp_gain)
        gold_gain = int(random.randint(*boss["gold"]) * gold_mult)
        set_user_point(guild_id, user_id, get_user_point(guild_id, user_id) + gold_gain)
        drop_mult = rpg_drop_rate_multiplier(player) * drop_event_mult * time_phase["drop_mult"]  # 럭 + 이벤트/부스트 + 시간대
        for drop_name, chance in boss["drops"]:
            if random.random() < min(1.0, chance * drop_mult):
                add_inventory_item(user_id, drop_name, 1, guild_id=guild_id)
                drop_lines.append(drop_name)
        rpg_add_mastery(guild_id, user_id, "boss", boss["exp"])  # 보스 숙련
        rpg_add_jobquest_progress(guild_id, user_id, "boss", 1)  # 전직 퀘스트 진행

    save_rpg_player(
        guild_id, user_id,
        level=player["level"], exp=player["exp"], hp=player["hp"], max_hp=player["max_hp"], stat_points=player["stat_points"], perk_points=player.get("perk_points", 0),
        last_boss_at=now.strftime("%Y-%m-%d %H:%M:%S"),
    )

    # 5번: 보스전 후 펫 경험치 (보스는 사냥보다 많이)
    pet_result = rpg_pet_gain_exp(guild_id, user_id, RPG_PET_EXP_PER_HUNT * (4 if won else 2))

    result_title = f"👑 {boss['emoji']} {boss['name']} 처치!" if won else f"💥 {boss['emoji']} {boss['name']}에게 패배..."
    embed = rpg_build_battle_result_embed(
        interaction.user, player, result_title,
        color=discord.Color.purple() if won else discord.Color.dark_gray(),
        log=log, won=won, exp_gain=exp_gain, gold_gain=gold_gain, drop_lines=drop_lines, level_ups=level_ups,
        footer_note="보스에게 패배했어요. 무기/방어구를 더 강화하고 5분 후 다시 도전해보세요!",
    )
    rpg_apply_image(embed, "boss", boss["name"])  # 등록된 보스 이미지가 있으면 표시
    if boss_death_note:
        embed.add_field(name="⚰️ 시가바네", value=boss_death_note, inline=False)
    if pet_result.get("leveled"):
        pet_msg = f"🐾 **{pet_result['pet_name']}** 펫이 Lv.{pet_result['level']}(으)로 성장했어요!"
        if pet_result.get("can_evolve"):
            pet_msg += "\n✨ 진화 가능! 펫 장착 패널에서 진화시켜보세요."
        embed.add_field(name="🐾 펫 성장", value=pet_msg, inline=False)
    if boss_food:
        buffs_txt = " · ".join(f"{'공격' if k=='power' else '방어'} +{v*100:.0f}%" for k, v in boss_food.items() if k != "name")
        embed.add_field(name=f"🍽️ {boss_food.get('name','음식')} 효과 발동!", value=buffs_txt, inline=False)
    embed.set_footer(text="만능 봇 | RPG 보스전 (5분마다)")
    await safe_interaction_send(interaction, embed=embed, view=RPGQuickActionsView())


# =========================
RPG_PVP_COOLDOWN_SECONDS = 300  # 같은 유저의 대결 신청 쿨타임 (5분)
RPG_PVP_COOLDOWNS = {}  # (guild_id, user_id) -> 마지막 대결 시각 (time.time())


def rpg_simulate_pvp(p1: dict, p2: dict, name1: str, name2: str):
    """두 플레이어의 스탯/직업/장비를 그대로 사용해 대결을 시뮬레이션합니다.
    실제 HP는 깎이지 않는 친선전이며, (승자 번호 1|2|0(무승부), 로그)를 돌려줍니다."""
    def make_fighter(p):
        job = rpg_job_stats(p.get("job"))
        proc_mult = 1 + rpg_stat_bonus_pct(p, "stat_mp_regen")
        return {
            "power": rpg_player_power(p),
            "defense": rpg_player_defense(p),
            "dodge": rpg_dodge_chance(p),
            "dmg_reduce": min(0.6, rpg_engrave_total(p, "opt_dmg_reduce") / 100),
            "crit_chance": 0.15 + job["crit_chance_bonus"] + rpg_engrave_total(p, "opt_crit_chance") / 100,
            "crit_mult": 1.5 + job["crit_mult_bonus"] + rpg_engrave_total(p, "opt_crit_dmg") / 100,
            "extra_chance": min(0.9, job["extra_attack_chance"] * proc_mult),
            "extra_pct": job["extra_attack_pct"] * (1 + rpg_stat_bonus_pct(p, "stat_magic") + rpg_engrave_total(p, "opt_skill_dmg") / 100),
            "hp": p["max_hp"],  # 친선전이라 최대 체력 기준으로 싸웁니다
            "max_hp": p["max_hp"],
        }

    f1, f2 = make_fighter(p1), make_fighter(p2)
    fighters = [(f1, name1), (f2, name2)]
    log = []
    for rnd in range(1, 11):
        for attacker_idx, defender_idx in ((0, 1), (1, 0)):
            atk, atk_name = fighters[attacker_idx]
            dfd, dfd_name = fighters[defender_idx]
            if atk["hp"] <= 0 or dfd["hp"] <= 0:
                break
            if dfd["dodge"] and random.random() < dfd["dodge"]:
                log.append(f"{rnd}R｜{atk_name}의 공격을 {dfd_name}이(가) 💨회피!")
                continue
            dmg = max(1, int(atk["power"] * random.uniform(0.8, 1.2)))
            crit_text = ""
            if random.random() < atk["crit_chance"]:
                dmg = int(dmg * atk["crit_mult"])
                crit_text = " 💥크리티컬!"
            extra_text = ""
            if atk["extra_chance"] and random.random() < atk["extra_chance"]:
                extra = max(1, int(atk["power"] * atk["extra_pct"]))
                dmg += extra
                extra_text = f" 🔮추가타+{extra}"
            dmg = max(1, dmg - dfd["defense"])
            if dfd.get("dmg_reduce"):
                dmg = max(1, int(dmg * (1 - dfd["dmg_reduce"])))
            dfd["hp"] -= dmg
            log.append(f"{rnd}R｜{atk_name} → {dfd_name}에게 **{dmg}** 피해{crit_text}{extra_text} (❤️{max(0, dfd['hp'])})")
            if dfd["hp"] <= 0:
                log.append(f"🏆 **{atk_name}** 승리!")
                return (attacker_idx + 1), log
        if f1["hp"] <= 0 or f2["hp"] <= 0:
            break
    # 10라운드 안에 못 끝나면 남은 체력 비율로 판정승
    r1 = f1["hp"] / max(1, f1["max_hp"])
    r2 = f2["hp"] / max(1, f2["max_hp"])
    if abs(r1 - r2) < 1e-9:
        log.append("🤝 판정 무승부!")
        return 0, log
    winner = 1 if r1 > r2 else 2
    log.append(f"⏱️ 판정승: **{fighters[winner - 1][1]}** (체력 {int(max(r1, r2) * 100)}% 남음)")
    return winner, log


# ============================================================
RPG_PVP_MAX_HP = 5_000_000   # v520: 발로란트식 대형 체력. 회복·HP바·데미지는 이 값에 비례해 자동 스케일됩니다.
# 공격력 정규화: 기존 밸런스는 체력 1000에서 power*0.35였습니다.
# 체력을 키워도 턴 수가 그대로 유지되도록, 같은 비율(체력의 0.035%)을 유지합니다.
RPG_PVP_ATK_FACTOR = 0.35 * (RPG_PVP_MAX_HP / 1000)   # 체력 1000당 0.35 → 현재 체력 비례
RPG_PVP_ATK_FLOOR = max(40, int(RPG_PVP_MAX_HP * 0.004))  # 최소 공격력도 체력 비례(기존 40 = 1000의 4%)
RPG_PVP_START_MANA = 100
RPG_PVP_MANA_REGEN = 20        # 매 턴 마나 회복
RPG_PVP_SKILL_MANA_COST = 40   # 스킬 사용 마나 소모
RPG_PVP_TURN_TIMEOUT = 90      # 각 턴 제한시간(초)

# 상태이상: 기절(stun) = 다음 턴 행동 불가 / 에어본(airborne) = 다음 턴 회피 불가 + 받는 피해 증가
RPG_PVP_STUN_CHANCE = 0.15      # 기본 공격 시 기절 유발 확률
RPG_PVP_AIRBORNE_CHANCE = 0.12  # 기본 공격 시 에어본 유발 확률
RPG_PVP_AIRBORNE_DMG_MULT = 1.5 # 에어본 상태에서 받는 피해 배율


def rpg_pvp_first_strike_bonus(player: dict) -> float:
    """직업의 선공(first_strike_chance) 보정치. 선제권 계산에 사용."""
    try:
        job = rpg_job_stats(player.get("job"))
        return float(job.get("first_strike_chance", 0.0) or 0.0)
    except Exception:
        return 0.0


class RPGPvpState:
    """턴제 PVP 한 판의 상태를 담습니다."""
    def __init__(self, guild_id, u1, u2):
        self.guild_id = guild_id
        self.users = {1: u1, 2: u2}
        p1 = get_or_create_rpg_player(guild_id, u1.id)
        p2 = get_or_create_rpg_player(guild_id, u2.id)
        self.players = {1: p1, 2: p2}
        self.hp = {1: RPG_PVP_MAX_HP, 2: RPG_PVP_MAX_HP}
        self.mana = {1: RPG_PVP_START_MANA, 2: RPG_PVP_START_MANA}
        # 전투력 기반 공격력(현재 체력에 맞춰 정규화 — 체력을 키워도 턴 수 유지)
        self.atk = {1: max(RPG_PVP_ATK_FLOOR, int(rpg_player_power(p1) * RPG_PVP_ATK_FACTOR)), 2: max(RPG_PVP_ATK_FLOOR, int(rpg_player_power(p2) * RPG_PVP_ATK_FACTOR))}
        self.defense = {1: rpg_player_defense(p1), 2: rpg_player_defense(p2)}
        self.stunned = {1: False, 2: False}
        self.airborne = {1: False, 2: False}
        self.buffs = {1: {}, 2: {}}      # 비약 버프 {"power":0.3,...}
        self.revive = {1: 0, 2: 0}        # 부활의깃털 사용 가능 횟수
        self._init_items()

        # 13번: 선제권 바퀴 (Initiative Wheel)
        # 민첩(agility) 스탯 + 직업 선공보정 + 소량 난수로 선제권 점수를 산정.
        # 선제권 점수가 높은 쪽이 선공. 각 라운드마다 선제권 게이지가 차오르며
        # 게이지가 먼저 100에 도달하는 쪽이 그 라운드의 우선권을 갖습니다.
        self.speed = {
            1: max(1, 10 + int(rpg_stat_bonus_pct(p1, "stat_agility") * 100) + int(rpg_pvp_first_strike_bonus(p1) * 20)),
            2: max(1, 10 + int(rpg_stat_bonus_pct(p2, "stat_agility") * 100) + int(rpg_pvp_first_strike_bonus(p2) * 20)),
        }
        # 선제권 게이지 (0~100). 매 라운드 speed만큼 충전.
        self.initiative = {1: 0, 2: 0}
        # 초기 선공 결정: 선제권 점수(속도)가 높은 쪽. 동점이면 약간의 난수.
        roll1 = self.speed[1] + random.uniform(0, 3)
        roll2 = self.speed[2] + random.uniform(0, 3)
        self.turn = 1 if roll1 >= roll2 else 2   # 현재 턴 플레이어 (1 or 2)
        self.first_side = self.turn              # 이 판의 선공 side
        # 선공 쪽 게이지를 가득 채운 상태로 시작 (첫 턴 우선권 표현), 상대는 0
        self.initiative = {1: 0, 2: 0}
        self.initiative[self.turn] = 100
        self.round = 1
        self.log = []
        self.finished = False
        self.winner = 0

    def _init_items(self):
        # 부활의깃털 보유 시 각자 1회 부활 가능
        for side in (1, 2):
            uid = self.users[side].id
            self.revive[side] = min(1, get_inventory_amount(uid, "부활의깃털"))

    def opponent(self, side):
        return 2 if side == 1 else 1

    def is_participant(self, user_id):
        return user_id in (self.users[1].id, self.users[2].id)

    def side_of(self, user_id):
        return 1 if self.users[1].id == user_id else 2

    def apply_damage(self, target, dmg):
        if self.airborne[target]:
            dmg = int(dmg * RPG_PVP_AIRBORNE_DMG_MULT)
        self.hp[target] = max(0, self.hp[target] - dmg)
        return dmg

    def check_death(self, target):
        """대상이 죽었는지 확인하고, 부활깃털 있으면 부활시킵니다. 최종 사망이면 True."""
        if self.hp[target] <= 0:
            if self.revive[target] > 0:
                self.revive[target] -= 1
                consume_inventory_item(self.users[target].id, "부활의깃털", 1)
                self.hp[target] = RPG_PVP_MAX_HP // 2
                self.log.append(f"🪶 {self.users[target].display_name} 부활! (HP {self.hp[target]:,})")
                return False
            return True
        return False

    def next_turn(self):
        # 13번: 선제권 바퀴는 '선공을 누가 먼저 하느냐'를 정하는 데 사용합니다.
        # 실제 턴 진행은 공정하게 엄격히 교대합니다. (PvP는 번갈아 행동)
        # 선제권 게이지는 시각화를 위해 유지하되, 행동한 쪽이 상대에게 턴을 넘깁니다.
        acted = self.turn
        # 게이지 시각화 갱신: 행동한 쪽 게이지 소모, 상대 게이지 충전
        self.initiative[acted] = max(0, self.initiative[acted] - 100)
        nxt = self.opponent(acted)
        # 다음 턴 쪽 게이지를 가득 채워 '이제 이 사람 차례'임을 표시
        self.initiative[nxt] = 100
        self.turn = nxt
        # 라운드는 선공 side 차례가 다시 돌아올 때 증가
        if self.turn == self.first_side:
            self.round += 1
        # 새 턴 시작: 마나 회복
        self.mana[self.turn] = min(100, self.mana[self.turn] + RPG_PVP_MANA_REGEN)

    def initiative_bar(self) -> str:
        """선제권 게이지를 시각화한 문자열."""
        def g(side):
            filled = min(10, int(self.initiative[side] / 10))
            return "🟦" * filled + "⬜" * (10 - filled)
        return (
            f"⚡ 선제권　{self.users[1].display_name}: {g(1)}　"
            f"{self.users[2].display_name}: {g(2)}"
        )


def rpg_pvp_build_embed(state: "RPGPvpState", note: str = ""):
    u1, u2 = state.users[1], state.users[2]

    def bar(hp):
        blocks = int(hp / RPG_PVP_MAX_HP * 10)
        return "🟥" * blocks + "⬛" * (10 - blocks)

    def status_icons(side):
        s = ""
        if state.stunned[side]:
            s += " 💫기절"
        if state.airborne[side]:
            s += " 🌀에어본"
        if state.buffs[side]:
            s += " 🧪버프"
        return s

    desc = (
        f"**{u1.display_name}**{status_icons(1)}\n"
        f"{bar(state.hp[1])} {state.hp[1]:,}/{RPG_PVP_MAX_HP:,}　💧{state.mana[1]}\n\n"
        f"**{u2.display_name}**{status_icons(2)}\n"
        f"{bar(state.hp[2])} {state.hp[2]:,}/{RPG_PVP_MAX_HP:,}　💧{state.mana[2]}\n"
    )
    embed = discord.Embed(title=f"🎮 턴제 대결 · {state.round}라운드", description=desc, color=discord.Color.orange())
    # 13번: 선제권 바퀴 시각화
    try:
        embed.add_field(name="⚡ 선제권 바퀴", value=state.initiative_bar(), inline=False)
    except Exception:
        pass
    if note:
        embed.add_field(name="상황", value=note[:1024], inline=False)
    if state.log:
        embed.add_field(name="📜 기록", value="\n".join(state.log[-6:])[-1024:], inline=False)
    if not state.finished:
        embed.set_footer(text=f"▶ {state.users[state.turn].display_name} 님의 턴입니다")
    return embed


class RPGPvpAcceptView(discord.ui.View):
    def __init__(self, challenger, opponent):
        super().__init__(timeout=60)
        self.challenger = challenger
        self.opponent = opponent

    async def interaction_check(self, interaction):
        if interaction.user.id != self.opponent.id:
            await interaction.response.send_message("이 대결의 상대만 수락할 수 있어요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="수락", emoji="⚔️", style=discord.ButtonStyle.success)
    async def accept(self, interaction, button):
        state = RPGPvpState(interaction.guild.id, self.challenger, self.opponent)
        state.log.append(f"⚔️ 대결 시작! {self.challenger.display_name} vs {self.opponent.display_name}")
        first_user = state.users[state.turn]
        note = (
            f"전투 시작! ⚡ 선제권 바퀴 결과 **{first_user.display_name}** 님이 선공! "
            f"(민첩·선공보정 기반)"
        )
        embed = rpg_pvp_build_embed(state, note)
        await interaction.response.edit_message(embed=embed, view=RPGPvpBattleView(state))

    @discord.ui.button(label="거절", emoji="✖️", style=discord.ButtonStyle.danger)
    async def decline(self, interaction, button):
        await interaction.response.edit_message(content=f"❌ {self.opponent.display_name} 님이 대결을 거절했어요.", embed=None, view=None)


class RPGPvpBattleView(discord.ui.View):
    def __init__(self, state: "RPGPvpState"):
        super().__init__(timeout=RPG_PVP_TURN_TIMEOUT)
        self.state = state

    async def interaction_check(self, interaction):
        st = self.state
        if not st.is_participant(interaction.user.id):
            await interaction.response.send_message("이 대결의 참가자가 아니에요.", ephemeral=True)
            return False
        if st.side_of(interaction.user.id) != st.turn:
            await interaction.response.send_message("아직 상대의 턴이에요. 기다려주세요!", ephemeral=True)
            return False
        return True

    async def _after_action(self, interaction, note):
        st = self.state
        # 사망 판정
        opp = st.opponent(st.turn)
        if st.check_death(opp):
            st.finished = True
            st.winner = st.turn
            await self._finish(interaction, note)
            return
        if st.check_death(st.turn):  # 반격 등으로 자신이 죽는 경우 대비
            st.finished = True
            st.winner = opp
            await self._finish(interaction, note)
            return
        # 턴 넘기기
        st.next_turn()
        # 기절이면 자동으로 턴 스킵
        skip_note = ""
        if st.stunned[st.turn]:
            st.stunned[st.turn] = False
            skip_note = f"\n💫 {st.users[st.turn].display_name} 님이 기절에서 회복하며 이번 턴을 넘깁니다!"
            st.log.append(f"💫 {st.users[st.turn].display_name} 기절로 턴 스킵")
            st.next_turn()
        # 에어본은 자기 턴 시작 시 해제
        if st.airborne[st.turn]:
            st.airborne[st.turn] = False
        embed = rpg_pvp_build_embed(st, note + skip_note)
        await interaction.response.edit_message(embed=embed, view=RPGPvpBattleView(st))

    async def _after_action_followup(self, interaction, note):
        """스킬/아이템(임시 메뉴)에서 행동 후 원본 배틀 메시지를 갱신합니다."""
        st = self.state
        opp = st.opponent(st.turn)
        if st.check_death(opp):
            st.finished = True
            st.winner = st.turn
            self._grant_rewards(st)
            embed = rpg_pvp_build_embed(st, note)
            embed.color = discord.Color.gold()
            try:
                await interaction.message.edit(embed=embed, view=None)
            except Exception:
                pass
            return
        st.next_turn()
        skip_note = ""
        if st.stunned[st.turn]:
            st.stunned[st.turn] = False
            skip_note = f"\n💫 {st.users[st.turn].display_name} 님이 기절로 이번 턴을 넘깁니다!"
            st.log.append(f"💫 {st.users[st.turn].display_name} 기절 턴 스킵")
            st.next_turn()
        if st.airborne[st.turn]:
            st.airborne[st.turn] = False
        embed = rpg_pvp_build_embed(st, note + skip_note)
        try:
            await interaction.message.edit(embed=embed, view=RPGPvpBattleView(st))
        except Exception:
            pass

    def _grant_rewards(self, st):
        wu = st.users[st.winner]
        lu = st.users[st.opponent(st.winner)]
        gid = st.guild_id
        wp = get_or_create_rpg_player(gid, wu.id)
        lp = get_or_create_rpg_player(gid, lu.id)
        gold_gain = 150 + lp["level"] * 3
        exp_gain = 50 + lp["level"]
        set_user_point(gid, wu.id, get_user_point(gid, wu.id) + gold_gain)
        level_ups, wp = rpg_apply_exp(wp, exp_gain)
        save_rpg_player(gid, wu.id, level=wp["level"], exp=wp["exp"], max_hp=wp["max_hp"], stat_points=wp["stat_points"], pvp_wins=wp["pvp_wins"] + 1)
        save_rpg_player(gid, lu.id, pvp_losses=lp["pvp_losses"] + 1)
        st.log.append(f"🏆 {wu.display_name} 승리! 💰+{gold_gain}P ✨+{exp_gain}")

    async def _finish(self, interaction, note):
        st = self.state
        self._grant_rewards(st)
        embed = rpg_pvp_build_embed(st, note)
        embed.color = discord.Color.gold()
        await interaction.response.edit_message(embed=embed, view=None)
        # PvP 랭킹 순위 역할 자동 갱신 (1~5위)
        try:
            await rpg_sync_pvp_rank_roles(interaction.guild)
        except Exception:
            pass

    @discord.ui.button(label="공격", emoji="⚔️", style=discord.ButtonStyle.primary, row=0)
    async def attack(self, interaction, button):
        st = self.state
        me = st.turn
        opp = st.opponent(me)
        base = st.atk[me]
        buff_mult = 1 + st.buffs[me].get("power", 0)
        dmg = max(1, int(base * random.uniform(0.85, 1.15) * buff_mult))
        # 방어 반영(경감)
        dmg = max(1, dmg - int(st.defense[opp] * 0.1))
        dealt = st.apply_damage(opp, dmg)
        note = f"⚔️ {st.users[me].display_name}의 공격! **{dealt:,}** 피해"
        # 상태이상 유발
        if random.random() < RPG_PVP_STUN_CHANCE:
            st.stunned[opp] = True
            note += f" · 💫{st.users[opp].display_name} 기절!"
            st.log.append(f"💫 {st.users[opp].display_name} 기절 유발")
        elif random.random() < RPG_PVP_AIRBORNE_CHANCE:
            st.airborne[opp] = True
            note += f" · 🌀{st.users[opp].display_name} 에어본!"
            st.log.append(f"🌀 {st.users[opp].display_name} 에어본 유발")
        st.log.append(f"⚔️ {st.users[me].display_name} → {dealt:,} 피해")
        await self._after_action(interaction, note)

    @discord.ui.button(label="스킬", emoji="✨", style=discord.ButtonStyle.success, row=0)
    async def skill(self, interaction, button):
        st = self.state
        me = st.turn
        if st.mana[me] < RPG_PVP_SKILL_MANA_COST:
            return await interaction.response.send_message(f"💧 마나가 부족해요! (필요 {RPG_PVP_SKILL_MANA_COST}, 보유 {st.mana[me]}) 마나물약을 쓰거나 공격하세요.", ephemeral=True)
        skills = rpg_available_skills(st.players[me])
        if not skills:
            return await interaction.response.send_message("사용 가능한 전직 스킬이 없어요. (직업/전직 필요) 일반 공격을 이용하세요.", ephemeral=True)
        await interaction.response.send_message("사용할 스킬을 고르세요:", view=RPGPvpSkillView(st, self), ephemeral=True)

    @discord.ui.button(label="아이템", emoji="🎒", style=discord.ButtonStyle.secondary, row=0)
    async def item(self, interaction, button):
        st = self.state
        await interaction.response.send_message("사용할 아이템을 고르세요:", view=RPGPvpItemView(st, self), ephemeral=True)

    @discord.ui.button(label="방어", emoji="🛡️", style=discord.ButtonStyle.secondary, row=0)
    async def defend(self, interaction, button):
        st = self.state
        me = st.turn
        # 방어: 이번 턴 마나 더 회복 + 다음 상대 공격 대비(버프 소량)
        st.mana[me] = min(100, st.mana[me] + 25)
        heal = int(RPG_PVP_MAX_HP * 0.05)
        st.hp[me] = min(RPG_PVP_MAX_HP, st.hp[me] + heal)
        note = f"🛡️ {st.users[me].display_name} 방어 태세! 💧마나+25 · ❤️{heal:,} 회복"
        st.log.append(f"🛡️ {st.users[me].display_name} 방어")
        await self._after_action(interaction, note)


class RPGPvpSkillSelect(discord.ui.Select):
    def __init__(self, state, battle_view):
        self.state = state
        self.battle_view = battle_view
        me = state.turn
        skills = rpg_available_skills(state.players[me])
        options = [discord.SelectOption(label=f"{name} (x{mult})", description=desc[:90], value=sid) for sid, name, mult, desc in skills[:25]]
        super().__init__(placeholder="스킬 선택", min_values=1, max_values=1, options=options)

    async def callback(self, interaction):
        st = self.state
        me = st.turn
        skill = rpg_skill_by_id(st.players[me], self.values[0])
        if not skill:
            return await interaction.response.send_message("스킬을 사용할 수 없어요.", ephemeral=True)
        st.mana[me] -= RPG_PVP_SKILL_MANA_COST
        opp = st.opponent(me)
        base = st.atk[me]
        buff_mult = 1 + st.buffs[me].get("power", 0)
        dmg = max(1, int(base * skill["mult"] * random.uniform(0.9, 1.1) * buff_mult))
        dealt = st.apply_damage(opp, dmg)
        note = f"✨ {st.users[me].display_name}의 {skill['name']}! **{dealt}** 피해 (💧-{RPG_PVP_SKILL_MANA_COST})"
        # 스킬은 높은 확률로 상태이상
        if random.random() < 0.35:
            if random.random() < 0.5:
                st.stunned[opp] = True
                note += f" · 💫기절!"
            else:
                st.airborne[opp] = True
                note += f" · 🌀에어본!"
        st.log.append(f"✨ {st.users[me].display_name} {skill['name']} → {dealt}")
        await interaction.response.edit_message(content="스킬 사용 완료!", view=None)
        await self.battle_view._after_action_followup(interaction, note)


class RPGPvpSkillView(discord.ui.View):
    def __init__(self, state, battle_view):
        super().__init__(timeout=60)
        self.add_item(RPGPvpSkillSelect(state, battle_view))


class RPGPvpItemSelect(discord.ui.Select):
    PVP_ITEMS = ["체력회복물약", "고급체력물약", "최상급체력물약", "마나물약", "고급마나물약", "만능회복약", "힘의비약", "수호의비약", "신속의비약"]

    def __init__(self, state, battle_view):
        self.state = state
        self.battle_view = battle_view
        me = state.turn
        uid = state.users[me].id
        options = []
        for item in self.PVP_ITEMS:
            cnt = get_inventory_amount(uid, item)
            if cnt > 0:
                options.append(discord.SelectOption(label=f"{item} ({cnt}개)", description=RPG_SHOP_ITEM_DESC.get(item, "")[:90], value=item))
        if not options:
            options = [discord.SelectOption(label="사용 가능한 아이템 없음", value="__none__")]
        super().__init__(placeholder="아이템 선택", min_values=1, max_values=1, options=options)

    async def callback(self, interaction):
        st = self.state
        me = st.turn
        item = self.values[0]
        if item == "__none__":
            return await interaction.response.send_message("사용할 아이템이 없어요.", ephemeral=True)
        uid = st.users[me].id
        if get_inventory_amount(uid, item) < 1:
            return await interaction.response.send_message("아이템이 없어요.", ephemeral=True)
        consume_inventory_item(uid, item, 1)
        note = ""
        if item == "체력회복물약":
            heal = int(RPG_PVP_MAX_HP * 0.40); st.hp[me] = min(RPG_PVP_MAX_HP, st.hp[me] + heal); note = f"🧪 체력 +{heal:,}"
        elif item == "고급체력물약":
            heal = int(RPG_PVP_MAX_HP * 0.70); st.hp[me] = min(RPG_PVP_MAX_HP, st.hp[me] + heal); note = f"🧪 체력 +{heal:,}"
        elif item == "최상급체력물약":
            st.hp[me] = RPG_PVP_MAX_HP; note = "🧪 체력 완전 회복!"
        elif item == "마나물약":
            st.mana[me] = min(100, st.mana[me] + 40); note = "💧 마나 +40"
        elif item == "고급마나물약":
            st.mana[me] = min(100, st.mana[me] + 100); note = "💧 마나 완전 회복!"
        elif item == "만능회복약":
            st.hp[me] = RPG_PVP_MAX_HP; st.mana[me] = 100; note = "🌟 체력·마나 완전 회복!"
        elif item == "힘의비약":
            st.buffs[me]["power"] = 0.30; note = "💪 공격력 +30% (이번 대결)"
        elif item == "수호의비약":
            st.defense[me] = int(st.defense[me] * 1.3) + 50; note = "🛡️ 방어력 강화!"
        elif item == "신속의비약":
            st.buffs[me]["dodge"] = 0.20; note = "💨 회피 강화!"
        note = f"🎒 {st.users[me].display_name}: {note}"
        st.log.append(note)
        await interaction.response.edit_message(content="아이템 사용 완료!", view=None)
        await self.battle_view._after_action_followup(interaction, note)


class RPGPvpItemView(discord.ui.View):
    def __init__(self, state, battle_view):
        super().__init__(timeout=60)
        self.add_item(RPGPvpItemSelect(state, battle_view))


@rpg_group.command(name="대결", description="다른 유저에게 PvP 대결을 신청합니다! (자동전투 또는 턴제)")
@app_commands.describe(상대="대결할 상대 유저", 방식="자동전투(기존) 또는 턴제(체력1000 고정·스킬/아이템)")
@app_commands.choices(방식=[
    app_commands.Choice(name="⚡ 자동 전투 (빠른 판정)", value="auto"),
    app_commands.Choice(name="🎮 턴제 대결 (체력1000·스킬/아이템)", value="turn"),
])
async def rpg_group_pvp(interaction: discord.Interaction, 상대: discord.Member, 방식: app_commands.Choice[str] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await rpg_check_feature_channel(interaction, "대결"):
        return
    if 상대.id == interaction.user.id:
        return await safe_interaction_send(interaction, "❌ 자기 자신과는 대결할 수 없어요!", ephemeral=True)
    if 상대.bot:
        return await safe_interaction_send(interaction, "❌ 봇과는 대결할 수 없어요!", ephemeral=True)

    mode = 방식.value if 방식 is not None else "auto"

    # 🎮 턴제 대결: 상대에게 수락을 받고 턴제 전투 시작
    if mode == "turn":
        embed = discord.Embed(
            title="🎮 턴제 대결 신청!",
            description=(
                f"{interaction.user.mention} 님이 {상대.mention} 님에게 **턴제 대결**을 신청했어요!\n\n"
                f"• 양쪽 체력 **1000** 고정 · 마나 **100** 시작\n"
                f"• 전직 스킬·회복/마나 포션·비약 사용 가능\n"
                f"• 기절/에어본 상태이상 발동\n\n"
                f"{상대.display_name} 님, 아래 버튼으로 수락하세요! (60초)"
            ),
            color=discord.Color.orange(),
        )
        return await safe_interaction_send(interaction, embed=embed, view=RPGPvpAcceptView(interaction.user, 상대))

    guild_id = interaction.guild.id
    cooldown_key = (guild_id, interaction.user.id)
    now_ts = time.time()
    last_ts = RPG_PVP_COOLDOWNS.get(cooldown_key, 0)
    if now_ts - last_ts < RPG_PVP_COOLDOWN_SECONDS:
        remaining = int(RPG_PVP_COOLDOWN_SECONDS - (now_ts - last_ts))
        return await safe_interaction_send(interaction, f"⏳ 대결은 5분에 1번만 신청할 수 있어요. ({remaining}초 남음)", ephemeral=True)
    RPG_PVP_COOLDOWNS[cooldown_key] = now_ts

    p1 = get_or_create_rpg_player(guild_id, interaction.user.id)
    p2 = get_or_create_rpg_player(guild_id, 상대.id)
    name1 = interaction.user.display_name
    name2 = 상대.display_name

    winner, log = rpg_simulate_pvp(p1, p2, name1, name2)

    reward_text = "무승부라 보상이 없어요."
    if winner != 0:
        winner_user = interaction.user if winner == 1 else 상대
        loser_user = 상대 if winner == 1 else interaction.user
        winner_player = p1 if winner == 1 else p2
        loser_player = p2 if winner == 1 else p1
        gold_gain = 100 + loser_player["level"] * 2
        exp_gain = 30 + loser_player["level"]
        set_user_point(guild_id, winner_user.id, get_user_point(guild_id, winner_user.id) + gold_gain)
        level_ups, winner_player = rpg_apply_exp(winner_player, exp_gain)
        save_rpg_player(
            guild_id, winner_user.id,
            level=winner_player["level"], exp=winner_player["exp"], max_hp=winner_player["max_hp"],
            stat_points=winner_player["stat_points"],
            pvp_wins=winner_player["pvp_wins"] + 1,
        )
        save_rpg_player(guild_id, loser_user.id, pvp_losses=loser_player["pvp_losses"] + 1)
        reward_text = f"🏆 **{winner_user.display_name}** 승리 보상: 💰 +{gold_gain}P · ✨ 경험치 +{exp_gain}"
        if level_ups:
            reward_text += f" · 🆙 **Lv.{level_ups[-1]}** 달성!"
        reward_text += f"\n📊 전적: {winner_user.display_name} {winner_player['pvp_wins'] + 1}승 {winner_player['pvp_losses']}패"
        # PvP 랭킹 순위 역할 자동 갱신 (1~5위)
        try:
            await rpg_sync_pvp_rank_roles(interaction.guild)
        except Exception:
            pass

    embed = discord.Embed(
        title=f"⚔️ PvP 대결: {name1} vs {name2}",
        description=f"⚔️ {name1} (Lv.{p1['level']} · 전투력 {rpg_player_power(p1)}) vs {name2} (Lv.{p2['level']} · 전투력 {rpg_player_power(p2)})",
        color=discord.Color.red() if winner == 1 else (discord.Color.blue() if winner == 2 else discord.Color.greyple()),
    )
    embed.add_field(name="📜 전투 기록", value="\n".join(log)[-1024:], inline=False)
    embed.add_field(name="🎁 결과", value=reward_text, inline=False)
    embed.set_footer(text="친선전이라 체력은 소모되지 않아요 | 만능 봇 RPG PvP")
    await safe_interaction_send(interaction, embed=embed)


# =========================
# 16번: 서버 경제 시스템 (복권 · 경매장 · 유저 시장)
# =========================
RPG_LOTTERY_TICKET_PRICE = 500       # 복권 1장 가격
RPG_LOTTERY_POOL_SEED = 2000         # 매 회차 기본 상금 시드
RPG_LOTTERY_CONTRIB = 400            # 티켓 1장당 상금 풀에 적립되는 금액
RPG_AUCTION_DURATION_HOURS = 6       # 경매 기본 진행 시간
RPG_AUCTION_MIN_INCREMENT = 100      # 최소 입찰 증가액
RPG_MARKET_FEE_RATE = 0.05           # 시장/경매 판매 수수료 5%


def _rpg_today():
    return datetime.datetime.now().strftime("%Y-%m-%d")


def _rpg_now_str():
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")


# ---------- 복권 ----------
def rpg_get_lottery(guild_id: int) -> dict:
    with DB_MUTEX:
        c.execute("SELECT round_no, pool, draw_date FROM rpg_lottery WHERE guild_id=?", (guild_id,))
        row = c.fetchone()
        if row is None:
            c.execute(
                "INSERT INTO rpg_lottery (guild_id, round_no, pool, draw_date) VALUES (?, 1, ?, ?)",
                (guild_id, RPG_LOTTERY_POOL_SEED, _rpg_today()),
            )
            conn.commit()
            return {"round_no": 1, "pool": RPG_LOTTERY_POOL_SEED, "draw_date": _rpg_today()}
    return {"round_no": row[0], "pool": row[1], "draw_date": row[2]}


def rpg_lottery_buy_ticket(guild_id: int, user_id: int, numbers: str) -> dict:
    """복권 1장 구매. 성공 시 정보를 반환, 실패 시 error 키 포함."""
    lot = rpg_get_lottery(guild_id)
    balance = get_user_point(guild_id, user_id)
    if balance < RPG_LOTTERY_TICKET_PRICE:
        return {"error": f"포인트가 부족해요. (복권 1장 {RPG_LOTTERY_TICKET_PRICE:,}P, 보유 {balance:,}P)"}
    set_user_point(guild_id, user_id, balance - RPG_LOTTERY_TICKET_PRICE)
    with DB_MUTEX:
        c.execute(
            "INSERT INTO rpg_lottery_tickets (guild_id, round_no, user_id, numbers, bought_at) VALUES (?, ?, ?, ?, ?)",
            (guild_id, lot["round_no"], user_id, numbers, _rpg_now_str()),
        )
        c.execute("UPDATE rpg_lottery SET pool = pool + ? WHERE guild_id=?", (RPG_LOTTERY_CONTRIB, guild_id))
        conn.commit()
    lot = rpg_get_lottery(guild_id)
    return {"round_no": lot["round_no"], "pool": lot["pool"], "numbers": numbers}


def rpg_lottery_my_tickets(guild_id: int, user_id: int, round_no: int) -> list:
    with DB_MUTEX:
        c.execute(
            "SELECT numbers FROM rpg_lottery_tickets WHERE guild_id=? AND round_no=? AND user_id=?",
            (guild_id, round_no, user_id),
        )
        return [r[0] for r in c.fetchall()]


def rpg_lottery_draw(guild_id: int) -> dict:
    """복권 추첨을 실행합니다. 당첨 번호를 뽑아 일치 개수에 따라 상금을 분배."""
    lot = rpg_get_lottery(guild_id)
    round_no = lot["round_no"]
    pool = lot["pool"]
    winning = sorted(random.sample(range(1, 46), 6))
    winning_set = set(winning)
    with DB_MUTEX:
        c.execute(
            "SELECT user_id, numbers FROM rpg_lottery_tickets WHERE guild_id=? AND round_no=?",
            (guild_id, round_no),
        )
        tickets = c.fetchall()
    # 등수별 가중치: 6개=1등, 5개=2등, 4개=3등, 3개=4등
    grade_weight = {6: 60, 5: 20, 4: 12, 3: 8}
    graded = {6: [], 5: [], 4: [], 3: []}
    for uid, nums in tickets:
        try:
            picked = set(int(x) for x in nums.split("-") if x.strip())
        except Exception:
            picked = set()
        match = len(picked & winning_set)
        if match in graded:
            graded[match].append(uid)
    # 각 등수 풀에 나눠줄 상금 (해당 등수 당첨자 없으면 그 몫은 이월)
    payouts = {}  # uid -> 상금
    carried = 0
    for grade in (6, 5, 4, 3):
        winners = graded[grade]
        grade_pool = int(pool * grade_weight[grade] / 100)
        if not winners:
            carried += grade_pool
            continue
        each = grade_pool // len(winners)
        for uid in winners:
            payouts[uid] = payouts.get(uid, 0) + each
    # 상금 지급
    for uid, amt in payouts.items():
        set_user_point(guild_id, uid, get_user_point(guild_id, uid) + amt)
    # 회차 종료 → 다음 회차 시작 (이월금 + 시드)
    next_pool = RPG_LOTTERY_POOL_SEED + carried
    with DB_MUTEX:
        c.execute(
            "UPDATE rpg_lottery SET round_no = round_no + 1, pool = ?, draw_date = ? WHERE guild_id=?",
            (next_pool, _rpg_today(), guild_id),
        )
        conn.commit()
    return {
        "round_no": round_no, "winning": winning, "pool": pool,
        "graded": {g: len(w) for g, w in graded.items()},
        "payouts": payouts, "carried": carried, "next_pool": next_pool,
        "ticket_count": len(tickets),
    }


def rpg_build_lottery_embed(guild_id: int, user_id: int) -> discord.Embed:
    lot = rpg_get_lottery(guild_id)
    my = rpg_lottery_my_tickets(guild_id, user_id, lot["round_no"])
    my_text = "\n".join(f"🎫 {n}" for n in my[:10]) if my else "아직 구매한 복권이 없어요."
    if len(my) > 10:
        my_text += f"\n… 외 {len(my) - 10}장"
    embed = discord.Embed(
        title=f"🎟️ 서버 복권 · {lot['round_no']}회차",
        description=(
            f"💰 현재 상금 풀: **{lot['pool']:,}P**\n"
            f"🎫 복권 1장: **{RPG_LOTTERY_TICKET_PRICE:,}P** (1~45 중 6개 선택)\n"
            f"6개 일치 1등 / 5개 2등 / 4개 3등 / 3개 4등\n\n"
            f"**내 복권 ({len(my)}장)**\n{my_text}"
        ),
        color=discord.Color.gold(),
    )
    embed.set_footer(text="아래 버튼으로 자동/수동 구매 · 관리자는 추첨 실행 | 만능 봇 RPG 복권")
    return embed


# ---------- 경매장 ----------
def rpg_auction_create(guild_id, seller_id, item_name, amount, start_price) -> dict:
    item_name = normalize_shop_item(item_name)
    have = get_inventory_amount(seller_id, item_name)
    if have < amount:
        return {"error": f"'{item_name}' 보유 수량이 부족해요. (보유 {have}개)"}
    if not consume_inventory_item(seller_id, item_name, amount):
        return {"error": "아이템을 등록하는 데 실패했어요."}
    end_at = (datetime.datetime.now() + datetime.timedelta(hours=RPG_AUCTION_DURATION_HOURS)).strftime("%Y-%m-%d %H:%M:%S")
    with DB_MUTEX:
        c.execute(
            "INSERT INTO rpg_auctions (guild_id, seller_id, item_name, amount, start_price, current_bid, top_bidder_id, end_at, status, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?, 0, ?, 'open', ?)",
            (guild_id, seller_id, item_name, amount, start_price, start_price, end_at, _rpg_now_str()),
        )
        conn.commit()
        auction_id = c.lastrowid
    return {"id": auction_id, "item_name": item_name, "amount": amount, "start_price": start_price, "end_at": end_at}


def rpg_auction_list(guild_id, only_open=True) -> list:
    with DB_MUTEX:
        q = "SELECT id, seller_id, item_name, amount, start_price, current_bid, top_bidder_id, end_at, status FROM rpg_auctions WHERE guild_id=?"
        params = [guild_id]
        if only_open:
            q += " AND status='open'"
        q += " ORDER BY end_at ASC LIMIT 25"
        c.execute(q, params)
        rows = c.fetchall()
    keys = ["id", "seller_id", "item_name", "amount", "start_price", "current_bid", "top_bidder_id", "end_at", "status"]
    return [dict(zip(keys, r)) for r in rows]


def rpg_auction_get(auction_id) -> dict:
    with DB_MUTEX:
        c.execute(
            "SELECT id, guild_id, seller_id, item_name, amount, start_price, current_bid, top_bidder_id, end_at, status FROM rpg_auctions WHERE id=?",
            (auction_id,),
        )
        row = c.fetchone()
    if not row:
        return None
    keys = ["id", "guild_id", "seller_id", "item_name", "amount", "start_price", "current_bid", "top_bidder_id", "end_at", "status"]
    return dict(zip(keys, row))


def rpg_auction_bid(guild_id, auction_id, bidder_id, bid_amount) -> dict:
    a = rpg_auction_get(auction_id)
    if not a or a["guild_id"] != guild_id or a["status"] != "open":
        return {"error": "이미 종료되었거나 존재하지 않는 경매예요."}
    if a["seller_id"] == bidder_id:
        return {"error": "자신의 경매에는 입찰할 수 없어요."}
    # 마감 시간 지났으면 정산
    if _rpg_now_str() >= a["end_at"]:
        return {"error": "이미 마감된 경매예요. 정산을 기다려주세요."}
    min_bid = a["current_bid"] + (RPG_AUCTION_MIN_INCREMENT if a["top_bidder_id"] else 0)
    if bid_amount < min_bid:
        return {"error": f"최소 입찰가는 {min_bid:,}P 이에요."}
    balance = get_user_point(guild_id, bidder_id)
    if balance < bid_amount:
        return {"error": f"포인트가 부족해요. (필요 {bid_amount:,}P, 보유 {balance:,}P)"}
    with DB_MUTEX:
        # 이전 최고 입찰자에게 환불
        if a["top_bidder_id"]:
            prev = a["top_bidder_id"]
            set_user_point(guild_id, prev, get_user_point(guild_id, prev) + a["current_bid"])
        # 새 입찰자 포인트 차감(에스크로)
        set_user_point(guild_id, bidder_id, balance - bid_amount)
        c.execute(
            "UPDATE rpg_auctions SET current_bid=?, top_bidder_id=? WHERE id=?",
            (bid_amount, bidder_id, auction_id),
        )
        conn.commit()
    return {"id": auction_id, "current_bid": bid_amount, "item_name": a["item_name"], "amount": a["amount"]}


def rpg_auction_settle(auction_id) -> dict:
    """마감된 경매를 정산합니다. 낙찰자에게 아이템, 판매자에게 대금(수수료 제외)."""
    a = rpg_auction_get(auction_id)
    if not a or a["status"] != "open":
        return None
    gid = a["guild_id"]
    with DB_MUTEX:
        c.execute("UPDATE rpg_auctions SET status='closed' WHERE id=?", (auction_id,))
        conn.commit()
    if a["top_bidder_id"]:
        # 낙찰: 아이템은 낙찰자에게, 대금은 판매자에게(수수료 제외)
        add_inventory_item(a["top_bidder_id"], a["item_name"], a["amount"], guild_id=gid)
        fee = int(a["current_bid"] * RPG_MARKET_FEE_RATE)
        payout = a["current_bid"] - fee
        set_user_point(gid, a["seller_id"], get_user_point(gid, a["seller_id"]) + payout)
        return {"sold": True, "winner": a["top_bidder_id"], "seller": a["seller_id"],
                "price": a["current_bid"], "fee": fee, "payout": payout,
                "item_name": a["item_name"], "amount": a["amount"]}
    else:
        # 유찰: 아이템 판매자에게 반환
        add_inventory_item(a["seller_id"], a["item_name"], a["amount"], guild_id=gid)
        return {"sold": False, "seller": a["seller_id"], "item_name": a["item_name"], "amount": a["amount"]}


def rpg_auction_settle_expired(guild_id) -> list:
    """마감시간이 지난 경매들을 일괄 정산합니다."""
    now = _rpg_now_str()
    with DB_MUTEX:
        c.execute("SELECT id FROM rpg_auctions WHERE guild_id=? AND status='open' AND end_at<=?", (guild_id, now))
        ids = [r[0] for r in c.fetchall()]
    results = []
    for aid in ids:
        r = rpg_auction_settle(aid)
        if r:
            results.append(r)
    return results


def rpg_build_auction_embed(guild_id) -> discord.Embed:
    rpg_auction_settle_expired(guild_id)  # 조회 시 만료 경매 자동 정산
    auctions = rpg_auction_list(guild_id, only_open=True)
    if not auctions:
        desc = "진행 중인 경매가 없어요. 아래 버튼으로 아이템을 경매에 올려보세요!"
    else:
        lines = []
        for a in auctions:
            bid_txt = f"{a['current_bid']:,}P" + (f" (입찰자 있음)" if a['top_bidder_id'] else " (시작가)")
            end_short = a["end_at"][5:16]
            lines.append(f"`#{a['id']}` {a['item_name']} x{a['amount']} · 현재 **{bid_txt}** · ~{end_short}")
        desc = "\n".join(lines)
    embed = discord.Embed(
        title="🏛️ 경매장",
        description=desc + f"\n\n입찰 시 이전 최고입찰자는 자동 환불돼요. 판매 수수료 {int(RPG_MARKET_FEE_RATE*100)}%.",
        color=discord.Color.dark_gold(),
    )
    embed.set_footer(text="아래 버튼으로 등록/입찰 · 마감 시 자동 낙찰 | 만능 봇 RPG 경매장")
    return embed


# ---------- 유저 시장 (고정가 즉시구매) ----------
def rpg_market_create(guild_id, seller_id, item_name, amount, price) -> dict:
    item_name = normalize_shop_item(item_name)
    have = get_inventory_amount(seller_id, item_name)
    if have < amount:
        return {"error": f"'{item_name}' 보유 수량이 부족해요. (보유 {have}개)"}
    if not consume_inventory_item(seller_id, item_name, amount):
        return {"error": "아이템 등록에 실패했어요."}
    with DB_MUTEX:
        c.execute(
            "INSERT INTO rpg_market (guild_id, seller_id, item_name, amount, price, status, created_at) "
            "VALUES (?, ?, ?, ?, ?, 'open', ?)",
            (guild_id, seller_id, item_name, amount, price, _rpg_now_str()),
        )
        conn.commit()
        listing_id = c.lastrowid
    return {"id": listing_id, "item_name": item_name, "amount": amount, "price": price}


def rpg_market_list(guild_id) -> list:
    with DB_MUTEX:
        c.execute(
            "SELECT id, seller_id, item_name, amount, price FROM rpg_market WHERE guild_id=? AND status='open' ORDER BY created_at DESC LIMIT 25",
            (guild_id,),
        )
        rows = c.fetchall()
    keys = ["id", "seller_id", "item_name", "amount", "price"]
    return [dict(zip(keys, r)) for r in rows]


def rpg_market_get(listing_id) -> dict:
    with DB_MUTEX:
        c.execute(
            "SELECT id, guild_id, seller_id, item_name, amount, price, status FROM rpg_market WHERE id=?",
            (listing_id,),
        )
        row = c.fetchone()
    if not row:
        return None
    keys = ["id", "guild_id", "seller_id", "item_name", "amount", "price", "status"]
    return dict(zip(keys, row))


def rpg_market_buy(guild_id, listing_id, buyer_id) -> dict:
    m = rpg_market_get(listing_id)
    if not m or m["guild_id"] != guild_id or m["status"] != "open":
        return {"error": "이미 판매되었거나 존재하지 않는 매물이에요."}
    if m["seller_id"] == buyer_id:
        return {"error": "자신의 매물은 구매할 수 없어요."}
    balance = get_user_point(guild_id, buyer_id)
    if balance < m["price"]:
        return {"error": f"포인트가 부족해요. (가격 {m['price']:,}P, 보유 {balance:,}P)"}
    with DB_MUTEX:
        c.execute("UPDATE rpg_market SET status='sold' WHERE id=? AND status='open'", (listing_id,))
        if c.rowcount == 0:
            conn.rollback()
            return {"error": "방금 다른 사람이 구매했어요."}
        conn.commit()
    # 결제 & 지급
    set_user_point(guild_id, buyer_id, balance - m["price"])
    add_inventory_item(buyer_id, m["item_name"], m["amount"], guild_id=guild_id)
    fee = int(m["price"] * RPG_MARKET_FEE_RATE)
    payout = m["price"] - fee
    set_user_point(guild_id, m["seller_id"], get_user_point(guild_id, m["seller_id"]) + payout)
    return {"item_name": m["item_name"], "amount": m["amount"], "price": m["price"],
            "seller": m["seller_id"], "fee": fee, "payout": payout}


def rpg_market_cancel(guild_id, listing_id, seller_id) -> dict:
    m = rpg_market_get(listing_id)
    if not m or m["guild_id"] != guild_id or m["status"] != "open":
        return {"error": "취소할 수 없는 매물이에요."}
    if m["seller_id"] != seller_id:
        return {"error": "본인 매물만 취소할 수 있어요."}
    with DB_MUTEX:
        c.execute("UPDATE rpg_market SET status='cancelled' WHERE id=?", (listing_id,))
        conn.commit()
    add_inventory_item(seller_id, m["item_name"], m["amount"], guild_id=guild_id)
    return {"item_name": m["item_name"], "amount": m["amount"]}


def rpg_build_market_embed(guild_id) -> discord.Embed:
    listings = rpg_market_list(guild_id)
    if not listings:
        desc = "등록된 매물이 없어요. 아래 버튼으로 아이템을 판매 등록해보세요!"
    else:
        lines = [f"`#{m['id']}` {m['item_name']} x{m['amount']} · **{m['price']:,}P** · <@{m['seller_id']}>" for m in listings]
        desc = "\n".join(lines)
    embed = discord.Embed(
        title="🛒 유저 시장 (고정가 즉시구매)",
        description=desc + f"\n\n판매 수수료 {int(RPG_MARKET_FEE_RATE*100)}%. 즉시 구매/판매 등록이 가능해요.",
        color=discord.Color.blue(),
    )
    embed.set_footer(text="아래 버튼으로 판매등록/구매 | 만능 봇 RPG 시장")
    return embed


# ---------- 경제 통합 허브 UI ----------
def rpg_build_economy_embed(guild_id, user_id) -> discord.Embed:
    lot = rpg_get_lottery(guild_id)
    open_auctions = len(rpg_auction_list(guild_id, only_open=True))
    open_market = len(rpg_market_list(guild_id))
    balance = get_user_point(guild_id, user_id)
    embed = discord.Embed(
        title="💰 서버 경제",
        description=(
            f"내 보유 포인트: **{balance:,}P**\n\n"
            f"🎟️ **복권** — {lot['round_no']}회차 · 상금 풀 {lot['pool']:,}P\n"
            f"🏛️ **경매장** — 진행 중 {open_auctions}건\n"
            f"🛒 **유저 시장** — 매물 {open_market}건\n\n"
            "아래 버튼으로 각 기능을 이용하세요."
        ),
        color=discord.Color.gold(),
    )
    embed.set_footer(text="복권·경매·시장을 한 곳에서 | 만능 봇 RPG 경제")
    return embed


class RPGLotteryBuyModal(discord.ui.Modal, title="🎟️ 복권 구매 (1~45 중 6개)"):
    numbers = discord.ui.TextInput(label="번호 6개 (예: 3-11-17-22-38-45)", placeholder="비워두면 자동 선택", required=False, max_length=30)

    def __init__(self, gid, uid):
        super().__init__()
        self.gid = gid
        self.uid = uid

    async def on_submit(self, interaction: discord.Interaction):
        raw = (self.numbers.value or "").strip()
        if not raw:
            picked = sorted(random.sample(range(1, 46), 6))
        else:
            try:
                parts = [int(x) for x in re.split(r"[-,\s]+", raw) if x.strip()]
                parts = sorted(set(parts))
                if len(parts) != 6 or any(n < 1 or n > 45 for n in parts):
                    raise ValueError
                picked = parts
            except ValueError:
                return await interaction.response.send_message("❌ 1~45 사이 서로 다른 6개 번호를 입력해주세요. (예: 3-11-17-22-38-45)", ephemeral=True)
        numbers_str = "-".join(str(n) for n in picked)
        result = rpg_lottery_buy_ticket(self.gid, self.uid, numbers_str)
        if "error" in result:
            return await interaction.response.send_message(f"❌ {result['error']}", ephemeral=True)
        await interaction.response.send_message(
            f"🎫 복권 구매 완료! **{result['round_no']}회차** · 번호 `{numbers_str}`\n현재 상금 풀: **{result['pool']:,}P**",
            ephemeral=True,
        )


class RPGAuctionCreateModal(discord.ui.Modal, title="🏛️ 경매 등록"):
    item = discord.ui.TextInput(label="아이템 이름", placeholder="예: 각성석", max_length=40)
    amount = discord.ui.TextInput(label="수량", placeholder="1", default="1", max_length=6)
    start_price = discord.ui.TextInput(label="시작가 (P)", placeholder="예: 1000", max_length=12)

    def __init__(self, gid, uid):
        super().__init__()
        self.gid = gid
        self.uid = uid

