class RPGLotteryView(discord.ui.View):
    def __init__(self, gid, uid):
        super().__init__(timeout=180)
        self.gid = gid
        self.uid = uid

    @discord.ui.button(label="복권 구매", emoji="🎫", style=discord.ButtonStyle.success)
    async def buy(self, interaction, button):
        await interaction.response.send_modal(RPGLotteryBuyModal(self.gid, self.uid))

    @discord.ui.button(label="자동 5장 구매", emoji="🎰", style=discord.ButtonStyle.secondary)
    async def buy5(self, interaction, button):
        bought = []
        for _ in range(5):
            nums = "-".join(str(n) for n in sorted(random.sample(range(1, 46), 6)))
            r = rpg_lottery_buy_ticket(self.gid, self.uid, nums)
            if "error" in r:
                if not bought:
                    return await interaction.response.send_message(f"❌ {r['error']}", ephemeral=True)
                break
            bought.append(nums)
        await interaction.response.send_message(
            f"🎰 자동 복권 {len(bought)}장 구매 완료!\n" + "\n".join(f"🎫 {n}" for n in bought),
            ephemeral=True,
        )

    @discord.ui.button(label="추첨 실행(관리자)", emoji="🎲", style=discord.ButtonStyle.danger)
    async def draw(self, interaction, button):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ 추첨은 관리자만 실행할 수 있어요.", ephemeral=True)
        result = rpg_lottery_draw(self.gid)
        win_str = ", ".join(str(n) for n in result["winning"])
        grade_names = {6: "1등", 5: "2등", 4: "3등", 3: "4등"}
        grade_lines = [f"{grade_names[g]}: {result['graded'].get(g, 0)}명" for g in (6, 5, 4, 3)]
        payout_lines = [f"<@{uid}> +{amt:,}P" for uid, amt in sorted(result["payouts"].items(), key=lambda x: -x[1])[:15]]
        embed = discord.Embed(
            title=f"🎲 복권 {result['round_no']}회차 추첨 결과!",
            description=(
                f"🎯 당첨 번호: **{win_str}**\n"
                f"🎫 총 판매: {result['ticket_count']}장 · 상금 풀 {result['pool']:,}P\n\n"
                + "\n".join(grade_lines)
                + ("\n\n**💰 당첨자**\n" + "\n".join(payout_lines) if payout_lines else "\n\n당첨자가 없어 상금이 다음 회차로 이월돼요.")
                + f"\n\n➡️ 다음 회차 상금 풀: **{result['next_pool']:,}P** (이월 {result['carried']:,}P)"
            ),
            color=discord.Color.gold(),
        )
        await interaction.response.send_message(embed=embed)


