# =========================
# 19번: 낚시 시스템 (독립 미니게임)
# =========================
# 낚시터에서 미끼를 던져 물고기를 낚습니다. 희귀도별 확률과 판매가가 다르고,
# 대어를 낚으면 큰 포인트를 얻어요. 하루 낚시 횟수에 제한이 있습니다.
RPG_FISHING_DAILY_LIMIT = 30
RPG_FISHING_COOLDOWN = 3  # 초
RPG_FISH_TABLE = [
    # (이름, 이모지, 가중치, 판매가, 희귀도라벨)
    ("멸치",       "🐟", 30, 20,   "흔함"),
    ("정어리",     "🐟", 26, 30,   "흔함"),
    ("고등어",     "🐟", 22, 45,   "흔함"),
    ("전갱이",     "🐟", 18, 60,   "흔함"),
    ("오징어",     "🦑", 15, 80,   "보통"),
    ("문어",       "🐙", 12, 130,  "보통"),
    ("게",         "🦀", 11, 160,  "보통"),
    ("새우",       "🦐", 10, 190,  "보통"),
    ("복어",       "🐡", 9,  260,  "희귀"),
    ("가오리",     "🐠", 6,  420,  "희귀"),
    ("해파리",     "🎐", 5,  600,  "희귀"),
    ("돛새치",     "🗡️", 4,  900,  "희귀"),
    ("상어",       "🦈", 3,  1200, "전설"),
    ("바다거북",   "🐢", 2,  2200, "전설"),
    ("고래",       "🐋", 1,  4000, "전설"),
    ("대왕오징어", "🦑", 1,  6000, "전설"),
    ("황금 잉어",  "🥇", 1,  8000, "신화"),
    ("무지개 송어", "🌈", 1,  11000,"신화"),
    ("인어의 눈물", "💎", 1,  15000,"신화"),
    ("심해의 군주", "👑", 1,  25000,"신화"),
]
# 낚시 중 가끔 나오는 잡템/쓰레기 (재미 요소)
RPG_FISHING_JUNK = [
    ("낡은 장화", "🥾", 5, 1),
    ("빈 병", "🍾", 5, 1),
    ("해초", "🌿", 8, 2),
]
RPG_FISH_BAIT_ITEM = "낚시 미끼"   # 있으면 대어 확률 상승


def rpg_fish_roll(player: dict, *, bait: bool = False) -> dict:
    """물고기 또는 잡템을 확률적으로 뽑습니다. 럭 스탯이 대어 확률에 소폭 반영.
    bait=True(미끼 사용)이면 잡템이 나오지 않고, '흔함' 등급도 제외되어 보통 이상만 낚입니다."""
    luck_bonus = rpg_stat_bonus_pct(player, "stat_luck")  # 0.0~
    # 미끼가 없을 때만 잡템(쓰레기) 가능
    if not bait:
        junk_chance = max(0.05, 0.15 - luck_bonus * 0.3)
        if random.random() < junk_chance:
            name, emoji, weight, price = random.choices(
                RPG_FISHING_JUNK, weights=[j[2] for j in RPG_FISHING_JUNK], k=1
            )[0]
            return {"name": name, "emoji": emoji, "price": price, "rarity": "잡템", "is_fish": False}
    # 물고기 풀: 미끼면 '흔함' 제외(보통 이상만)
    fishes = [f for f in RPG_FISH_TABLE if f[4] != "흔함"] if bait else RPG_FISH_TABLE
    weights = []
    for i, (_n, _e, w, _p, _r) in enumerate(fishes):
        rarity_factor = 1 + luck_bonus * (i / max(1, len(fishes))) * 2
        # 미끼 사용 시 상위 어종 가중치를 추가로 부양
        if bait:
            rarity_factor *= 1 + (i / max(1, len(fishes))) * 0.8
        weights.append(w * rarity_factor)
    name, emoji, weight, price, rarity = random.choices(fishes, weights=weights, k=1)[0]
    return {"name": name, "emoji": emoji, "price": price, "rarity": rarity, "is_fish": True}


def rpg_build_fishing_embed(guild_id, user_id) -> discord.Embed:
    player = get_or_create_rpg_player(guild_id, user_id)
    today = _rpg_today()
    count = player.get("gather_count", 0) if player.get("gather_date") == today else 0
    balance = get_user_point(guild_id, user_id)
    # 인벤토리에 모인 물고기 집계
    stored_cnt = 0
    stored_val = 0
    for name, _e, _w, price, _r in RPG_FISH_TABLE:
        amt = get_inventory_amount(user_id, name)
        if amt > 0:
            stored_cnt += amt
            stored_val += price * amt
    dex_lines = []
    for name, emoji, w, price, rarity in RPG_FISH_TABLE:
        dex_lines.append(f"{emoji} {name} ({rarity}) — {price:,}P")
    embed = discord.Embed(
        title="🎣 낚시터",
        description=(
            f"보유 포인트: **{balance:,}P**\n"
            f"오늘 낚시: **{count}/{RPG_FISHING_DAILY_LIMIT}회**\n"
            f"📦 보관 중인 물고기: **{stored_cnt}마리** (환전 시 +{stored_val:,}P)\n\n"
            "🎣 **낚시 던지기**로 물고기를 낚고, 💰 **물고기 환전**으로 한꺼번에 팔아요!\n"
            f"미끼(`{RPG_FISH_BAIT_ITEM}`)를 쓰면 잡템 없이 **보통 등급 이상**만 낚여요.\n\n"
            "**🐟 어종 도감**\n" + "\n".join(dex_lines)
        ),
        color=discord.Color.teal(),
    )
    embed.set_footer(text="물고기는 모아뒀다가 환전 · 잡템은 즉시 환전 | 만능 봇 RPG 낚시")
    return embed


def rpg_do_fishing(guild_id, user_id) -> dict:
    player = get_or_create_rpg_player(guild_id, user_id)
    today = _rpg_today()
    count = player.get("gather_count", 0) if player.get("gather_date") == today else 0
    if count >= RPG_FISHING_DAILY_LIMIT:
        return {"error": f"오늘 낚시 횟수를 모두 사용했어요. (하루 {RPG_FISHING_DAILY_LIMIT}회)"}
    # 미끼가 있으면 소비하고 bait 모드(잡템X, 보통 이상만)로 낚습니다.
    used_bait = False
    if get_inventory_amount(user_id, RPG_FISH_BAIT_ITEM) > 0:
        consume_inventory_item(user_id, RPG_FISH_BAIT_ITEM, 1)
        used_bait = True
    result = rpg_fish_roll(player, bait=used_bait)
    # 물고기는 인벤토리에 모아두고(나중에 일괄 환전), 잡템은 즉시 소액 환전
    if result["is_fish"]:
        add_inventory_item(user_id, result["name"], 1, guild_id=guild_id)
        result["stored"] = True
    else:
        set_user_point(guild_id, user_id, get_user_point(guild_id, user_id) + result["price"])
        result["stored"] = False
    new_count = count + 1
    save_rpg_player(guild_id, user_id, gather_count=new_count, gather_date=today)
    if result["is_fish"] and result["rarity"] in ("전설", "신화"):
        try:
            rpg_add_mastery(guild_id, user_id, "fishing", result["price"] // 10)
        except Exception:
            pass
    result["used_bait"] = used_bait
    result["count"] = new_count
    return result


def rpg_fish_price(name: str) -> int:
    """물고기 이름으로 판매가를 조회합니다."""
    for n, _e, _w, price, _r in RPG_FISH_TABLE:
        if n == name:
            return price
    return 0


def rpg_sell_all_fish(guild_id, user_id) -> dict:
    """인벤토리에 모인 모든 물고기를 포인트로 환전합니다. (1마리 이상일 때만 작동)"""
    total = 0
    sold = 0
    details = []
    for name, _e, _w, price, _r in RPG_FISH_TABLE:
        amt = get_inventory_amount(user_id, name)
        if amt > 0:
            consume_inventory_item(user_id, name, amt)
            gained = price * amt
            total += gained
            sold += amt
            details.append((name, amt, gained))
    if sold < 1:
        return {"error": "환전할 물고기가 없어요. 먼저 낚시로 물고기를 모아보세요!"}
    set_user_point(guild_id, user_id, get_user_point(guild_id, user_id) + total)
    return {"ok": True, "total": total, "sold": sold, "details": details}


class RPGFishingView(discord.ui.View):
    def __init__(self, gid, uid):
        super().__init__(timeout=180)
        self.gid = gid
        self.uid = uid

    @discord.ui.button(label="낚시 던지기", emoji="🎣", style=discord.ButtonStyle.success)
    async def cast(self, interaction, button):
        if interaction.user.id != self.uid:
            return await interaction.response.send_message("본인만 낚시할 수 있어요.", ephemeral=True)
        result = rpg_do_fishing(self.gid, self.uid)
        if "error" in result:
            return await interaction.response.send_message(f"❌ {result['error']}", ephemeral=True)
        bait_txt = " (미끼 사용🪱)" if result.get("used_bait") else ""
        if result["is_fish"]:
            rarity_emoji = {"흔함": "⚪", "보통": "🟢", "희귀": "🔵", "전설": "🟣", "신화": "🌟"}.get(result["rarity"], "")
            big = "\n🎉 **대어를 낚았어요!**" if result["rarity"] in ("전설", "신화") else ""
            msg = (
                f"🎣 낚시 성공!{bait_txt}\n"
                f"{result['emoji']} **{result['name']}** {rarity_emoji}{result['rarity']} 획득! (판매가 {result['price']:,}P)\n"
                f"📦 인벤토리에 보관했어요. `💰 물고기 환전` 버튼으로 한꺼번에 팔 수 있어요.{big}\n\n"
                f"오늘 낚시: {result['count']}/{RPG_FISHING_DAILY_LIMIT}회"
            )
        else:
            msg = (
                f"🎣 이런...{bait_txt}\n"
                f"{result['emoji']} **{result['name']}**을(를) 건졌어요. (+{result['price']:,}P 즉시 환전)\n\n"
                f"오늘 낚시: {result['count']}/{RPG_FISHING_DAILY_LIMIT}회"
            )
        await interaction.response.send_message(msg, ephemeral=True)

    @discord.ui.button(label="물고기 환전", emoji="💰", style=discord.ButtonStyle.primary)
    async def sell_fish(self, interaction, button):
        if interaction.user.id != self.uid:
            return await interaction.response.send_message("본인만 환전할 수 있어요.", ephemeral=True)
        res = rpg_sell_all_fish(self.gid, self.uid)
        if "error" in res:
            return await interaction.response.send_message(f"❌ {res['error']}", ephemeral=True)
        top = sorted(res["details"], key=lambda d: d[2], reverse=True)[:5]
        detail_txt = "\n".join(f"{n} x{a} → {g:,}P" for n, a, g in top)
        more = f"\n…외 {len(res['details']) - 5}종" if len(res["details"]) > 5 else ""
        await interaction.response.send_message(
            f"💰 **물고기 {res['sold']}마리 환전 완료!** +{res['total']:,}P\n{detail_txt}{more}",
            ephemeral=True,
        )

    @discord.ui.button(label="낚시터 새로고침", emoji="🔄", style=discord.ButtonStyle.secondary)
    async def refresh(self, interaction, button):
        await interaction.response.edit_message(embed=rpg_build_fishing_embed(self.gid, self.uid), view=self)


# =========================
# A와 B가 각자 아이템/포인트를 걸고, 양쪽이 모두 '준비완료'하면 동시에 교환됩니다.
# 거래 세션은 메모리에 보관하며, 봇 재시작 시 미체결 거래는 안전하게 사라집니다.
# 거래 불가 품목(장착 중 유물 등)은 인벤토리 아이템만 다루므로 자연히 제외됩니다.
RPG_TRADE_SESSIONS = {}          # trade_id -> dict
RPG_TRADE_TTL = 600              # 거래 세션 유효시간(초)
RPG_TRADE_MAX_ITEM_KINDS = 10    # 한 쪽이 걸 수 있는 아이템 종류 수


def _rpg_trade_key(guild_id, a, b):
    return f"{guild_id}:{min(a,b)}:{max(a,b)}"


def rpg_trade_get(guild_id, user_id):
    """이 유저가 참여 중인 활성 거래 세션을 돌려줍니다."""
    now = time.time()
    for tid, s in list(RPG_TRADE_SESSIONS.items()):
        if s["guild_id"] != guild_id:
            continue
        if now - s["created_at"] > RPG_TRADE_TTL:
            RPG_TRADE_SESSIONS.pop(tid, None)
            continue
        if user_id in (s["a"], s["b"]):
            return tid, s
    return None, None


def rpg_trade_create(guild_id, a, b, a_name, b_name):
    tid = _rpg_trade_key(guild_id, a, b)
    now = time.time()
    RPG_TRADE_SESSIONS[tid] = {
        "guild_id": guild_id, "a": a, "b": b,
        "names": {a: a_name, b: b_name},
        "items": {a: {}, b: {}},      # user_id -> {item_name: amount}
        "points": {a: 0, b: 0},
        "ready": {a: False, b: False},
        "created_at": now, "done": False,
    }
    return tid, RPG_TRADE_SESSIONS[tid]


def rpg_trade_side(session, user_id):
    return "a" if user_id == session["a"] else "b"


def rpg_trade_settle(session) -> dict:
    """양쪽이 준비완료된 거래를 체결합니다. 체결 직전 보유/잔액을 재확인합니다."""
    if session["done"]:
        return {"error": "이미 완료된 거래예요."}
    gid = session["guild_id"]
    a, b = session["a"], session["b"]
    # 1) 최종 검증: 각자 걸어둔 아이템·포인트를 실제로 보유하는지
    for uid in (a, b):
        for item, amt in session["items"][uid].items():
            if get_inventory_amount(uid, item) < amt:
                return {"error": f"<@{uid}> 님의 **{item}** 수량이 부족해 거래가 취소됐어요."}
        need_pt = session["points"][uid]
        if need_pt > 0 and get_user_point(gid, uid) < need_pt:
            return {"error": f"<@{uid}> 님의 포인트가 부족해 거래가 취소됐어요."}
    # 2) 원자적 교환: 먼저 양쪽에서 회수, 그다음 상대에게 지급
    try:
        for uid in (a, b):
            for item, amt in session["items"][uid].items():
                consume_inventory_item(uid, item, amt)
            if session["points"][uid] > 0:
                set_user_point(gid, uid, get_user_point(gid, uid) - session["points"][uid])
        # 지급 (a가 건 것 → b에게, b가 건 것 → a에게)
        for giver, receiver in ((a, b), (b, a)):
            for item, amt in session["items"][giver].items():
                add_inventory_item(receiver, item, amt, guild_id=gid)
            if session["points"][giver] > 0:
                set_user_point(gid, receiver, get_user_point(gid, receiver) + session["points"][giver])
    except Exception as e:
        return {"error": f"거래 처리 중 오류가 발생했어요: {e}"}
    session["done"] = True
    RPG_TRADE_SESSIONS.pop(_rpg_trade_key(gid, a, b), None)
    return {"ok": True}


def rpg_trade_cancel(session):
    session["done"] = True
    RPG_TRADE_SESSIONS.pop(_rpg_trade_key(session["guild_id"], session["a"], session["b"]), None)


def rpg_build_trade_embed(session) -> discord.Embed:
    a, b = session["a"], session["b"]
    def side_text(uid):
        lines = []
        for item, amt in session["items"][uid].items():
            lines.append(f"　{item} x{amt}")
        if session["points"][uid] > 0:
            lines.append(f"　💰 {session['points'][uid]:,}P")
        if not lines:
            lines.append("　(아직 없음)")
        ready = "✅ 준비완료" if session["ready"][uid] else "⏳ 준비 중"
        return f"**{session['names'][uid]}** — {ready}\n" + "\n".join(lines)
    embed = discord.Embed(
        title="🤝 안전거래 (에스크로)",
        description=(
            "양쪽이 걸 물건을 등록하고 **준비완료**를 누르면 교환돼요.\n"
            "상대가 건 목록을 확인한 뒤 확정하세요!\n\n"
            + side_text(a) + "\n\n" + side_text(b)
        ),
        color=discord.Color.gold(),
    )
    embed.set_footer(text="아이템/포인트 추가 후 준비완료 · 한쪽이라도 목록을 바꾸면 준비완료가 해제돼요")
    return embed


class RPGTradeItemSelect(discord.ui.Select):
    """자기 인벤토리에서 거래에 걸 아이템을 고르는 셀렉트."""
    def __init__(self, session, user_id):
        self.session = session
        self.user_id = user_id
        rows = [(n, a) for n, a in get_inventory_rows(user_id) if a > 0][:25]
        options = []
        for name, amt in rows:
            already = session["items"][user_id].get(name, 0)
            options.append(discord.SelectOption(
                label=name[:100],
                description=f"보유 {amt}개" + (f" · 등록 {already}" if already else ""),
                value=name,
            ))
        if not options:
            options.append(discord.SelectOption(label="거래할 아이템이 없어요", value="__none__"))
        super().__init__(placeholder="걸 아이템 선택 (1개씩 추가)", min_values=1, max_values=1, options=options)

    async def callback(self, interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        item = self.values[0]
        cur = self.session["items"][self.user_id].get(item, 0)
        if cur + 1 > get_inventory_amount(self.user_id, item):
            return await interaction.response.send_message("❌ 보유 수량을 초과했어요.", ephemeral=True)
        if item not in self.session["items"][self.user_id] and len(self.session["items"][self.user_id]) >= RPG_TRADE_MAX_ITEM_KINDS:
            return await interaction.response.send_message(f"❌ 아이템은 최대 {RPG_TRADE_MAX_ITEM_KINDS}종까지 걸 수 있어요.", ephemeral=True)
        self.session["items"][self.user_id][item] = cur + 1
        # 목록이 바뀌면 양쪽 준비완료 해제
        self.session["ready"] = {self.session["a"]: False, self.session["b"]: False}
        await interaction.response.edit_message(embed=rpg_build_trade_embed(self.session), view=RPGTradeView(self.session))


class RPGTradePointModal(discord.ui.Modal, title="💰 거래에 걸 포인트"):
    amount = discord.ui.TextInput(label="포인트 (숫자만)", placeholder="예: 1000", required=True, max_length=12)

    def __init__(self, session, user_id):
        super().__init__()
        self.session = session
        self.user_id = user_id

    async def on_submit(self, interaction):
        try:
            amt = int(str(self.amount.value).replace(",", "").strip())
        except ValueError:
            return await interaction.response.send_message("❌ 숫자만 입력해주세요.", ephemeral=True)
        if amt < 0:
            return await interaction.response.send_message("❌ 0 이상이어야 해요.", ephemeral=True)
        if amt > get_user_point(self.session["guild_id"], self.user_id):
            return await interaction.response.send_message("❌ 보유 포인트를 초과했어요.", ephemeral=True)
        self.session["points"][self.user_id] = amt
        self.session["ready"] = {self.session["a"]: False, self.session["b"]: False}
        await interaction.response.edit_message(embed=rpg_build_trade_embed(self.session), view=RPGTradeView(self.session))


class RPGTradeView(discord.ui.View):
    def __init__(self, session):
        super().__init__(timeout=RPG_TRADE_TTL)
        self.session = session
        self.add_item(RPGTradeItemSelect(session, session["a"]))

    async def interaction_check(self, interaction):
        s = self.session
        if interaction.user.id not in (s["a"], s["b"]):
            await interaction.response.send_message("❌ 이 거래의 참여자가 아니에요.", ephemeral=True)
            return False
        if s["done"]:
            await interaction.response.send_message("이미 종료된 거래예요.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="내 아이템 추가", emoji="📦", style=discord.ButtonStyle.secondary, row=1)
    async def add_item(self, interaction, button):
        # 각자 자기 인벤토리에서 고르도록, 누른 사람 기준 셀렉트를 임시로 보여줌
        v = discord.ui.View(timeout=120)
        v.add_item(RPGTradeItemSelect(self.session, interaction.user.id))
        await interaction.response.send_message("걸 아이템을 골라주세요 (버튼 누를 때마다 1개씩 추가):", view=v, ephemeral=True)

    @discord.ui.button(label="포인트 걸기", emoji="💰", style=discord.ButtonStyle.secondary, row=1)
    async def add_point(self, interaction, button):
        await interaction.response.send_modal(RPGTradePointModal(self.session, interaction.user.id))

    @discord.ui.button(label="내 등록 초기화", emoji="🧹", style=discord.ButtonStyle.secondary, row=1)
    async def clear_mine(self, interaction, button):
        self.session["items"][interaction.user.id] = {}
        self.session["points"][interaction.user.id] = 0
        self.session["ready"] = {self.session["a"]: False, self.session["b"]: False}
        await interaction.response.edit_message(embed=rpg_build_trade_embed(self.session), view=RPGTradeView(self.session))

    @discord.ui.button(label="준비완료", emoji="✅", style=discord.ButtonStyle.success, row=2)
    async def ready(self, interaction, button):
        s = self.session
        uid = interaction.user.id
        s["ready"][uid] = not s["ready"][uid]
        # 양쪽 다 준비완료 → 체결
        if s["ready"][s["a"]] and s["ready"][s["b"]]:
            res = rpg_trade_settle(s)
            if "error" in res:
                s["ready"] = {s["a"]: False, s["b"]: False}
                return await interaction.response.edit_message(
                    embed=rpg_build_trade_embed(s),
                    view=RPGTradeView(s),
                )
            done_embed = discord.Embed(
                title="🤝 거래 완료!",
                description="양쪽의 물건이 안전하게 교환됐어요. 🎉",
                color=discord.Color.green(),
            )
            for item in list(self.children):
                item.disabled = True
            return await interaction.response.edit_message(embed=done_embed, view=self)
        await interaction.response.edit_message(embed=rpg_build_trade_embed(s), view=RPGTradeView(s))

    @discord.ui.button(label="거래 취소", emoji="✖️", style=discord.ButtonStyle.danger, row=2)
    async def cancel(self, interaction, button):
        rpg_trade_cancel(self.session)
        cancel_embed = discord.Embed(title="✖️ 거래 취소됨", description=f"{interaction.user.display_name} 님이 거래를 취소했어요.", color=discord.Color.red())
        for item in list(self.children):
            item.disabled = True
        await interaction.response.edit_message(embed=cancel_embed, view=self)


