def rpg_get_raid(guild_id: int):
    with DB_MUTEX:
        c.execute("SELECT boss_name, boss_emoji, max_hp, hp, difficulty, started_at, started_by FROM rpg_raids WHERE guild_id=?", (guild_id,))
        row = c.fetchone()
    if not row:
        return None
    keys = ["boss_name", "boss_emoji", "max_hp", "hp", "difficulty", "started_at", "started_by"]
    return dict(zip(keys, row))


def rpg_raid_top_damage(guild_id: int, limit: int = 10):
    with DB_MUTEX:
        c.execute("SELECT user_id, damage FROM rpg_raid_damage WHERE guild_id=? ORDER BY damage DESC LIMIT ?", (guild_id, limit))
        return c.fetchall()


def rpg_raid_clear(guild_id: int):
    with DB_MUTEX:
        c.execute("DELETE FROM rpg_raids WHERE guild_id=?", (guild_id,))
        c.execute("DELETE FROM rpg_raid_damage WHERE guild_id=?", (guild_id,))
        conn.commit()


def rpg_raid_auto_spawn(guild_id: int, difficulty: str = None):
    """자동 소환용: 레이드가 없을 때 랜덤(또는 지정) 난이도로 소환. 이미 있으면 None."""
    if rpg_get_raid(guild_id):
        return None
    # 자동 소환은 지나치게 강한 보스는 제외하고 쉬움~어려움 위주로
    if difficulty is None:
        difficulty = random.choice(["쉬움", "쉬움", "보통", "보통", "어려움"])
    boss = RPG_RAID_BOSSES.get(difficulty)
    if not boss:
        return None
    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with DB_MUTEX:
        c.execute(
            "INSERT OR REPLACE INTO rpg_raids (guild_id, boss_name, boss_emoji, max_hp, hp, difficulty, started_at, started_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
            (guild_id, boss["name"], boss["emoji"], boss["hp"], boss["hp"], difficulty, now, 0),
        )
        c.execute("DELETE FROM rpg_raid_damage WHERE guild_id=?", (guild_id,))
        conn.commit()
    return {"name": boss["name"], "emoji": boss["emoji"], "hp": boss["hp"], "difficulty": difficulty}


