@rpg2_group.command(name="명예의전당", description="역대 시즌 PvP·던전 1위 기록을 확인합니다.")
@app_commands.describe(종류="확인할 랭킹 종류")
@app_commands.choices(종류=[
    app_commands.Choice(name="⚔️ PvP 역대 1위", value="PvP"),
    app_commands.Choice(name="🏰 던전 역대 1위", value="던전"),
])
async def rpg_group_hall_of_fame(interaction: discord.Interaction, 종류: app_commands.Choice[str] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    category = 종류.value if 종류 is not None else "PvP"
    rows = rpg_hall_of_fame_list(interaction.guild.id, category, limit=10)

    unit = "승" if category == "PvP" else "층"
    icon = "⚔️" if category == "PvP" else "🏰"
    if not rows:
        desc = f"아직 기록된 {category} 시즌 우승자가 없어요.\n시즌이 한 번 종료되면 1위가 여기에 영구 기록돼요!"
    else:
        lines = []
        for season_key, user_id, record, recorded_at in rows:
            date_part = (recorded_at or "")[:10]
            lines.append(f"🏅 **시즌 {season_key}** — <@{user_id}> ({record}{unit}) · {date_part}")
        desc = "\n".join(lines)

    embed = discord.Embed(title=f"{icon} 명예의 전당 · {category}", description=desc, color=discord.Color.gold())
    embed.set_footer(text="시즌 종료 시 1위가 자동으로 기록돼요 | 만능 봇 RPG")
    await safe_interaction_send(interaction, embed=embed)


@rpg2_group.command(name="시즌패스", description="활동으로 XP를 쌓아 티어 보상을 받는 월간 시즌패스입니다. (매달 1일 초기화)")
async def rpg_group_season_pass(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    gid = interaction.guild.id
    uid = interaction.user.id
    get_or_create_rpg_player(gid, uid)

    # 대기 중인 보상 자동 수령
    payouts = rpg_season_pass_claim(gid, uid)
    xp, claimed = rpg_season_pass_get(gid, uid)
    reached = rpg_season_pass_tier_from_xp(xp)
    max_tier = len(RPG_SEASON_PASS_TIERS)

    lines = []
    for i, (need, (rtype, value)) in enumerate(RPG_SEASON_PASS_TIERS, start=1):
        reward_label = f"{value:,}P" if rtype == "point" else f"{value} 1개"
        if i <= reached:
            mark = "✅"
        elif xp < need:
            mark = "🔒"
        else:
            mark = "⬜"
        lines.append(f"{mark} **T{i}** ({need:,}XP) — {reward_label}")

    next_need = None
    for need, _ in RPG_SEASON_PASS_TIERS:
        if xp < need:
            next_need = need
            break

    desc = f"🎟️ **시즌패스** (월간 시즌)\n현재 XP: **{xp:,}** · 도달 티어: **T{reached}/{max_tier}**\n"
    if next_need:
        desc += f"다음 티어까지: **{next_need - xp:,}XP**\n"
    else:
        desc += "🏆 모든 티어를 완료했어요!\n"
    desc += "\n" + "\n".join(lines)
    desc += "\n\n💡 사냥·보스·출석 등 활동을 하면 XP가 쌓여요."

    embed = discord.Embed(title="🎟️ 시즌패스", description=desc, color=0x9B59B6)
    embed.set_footer(text="시즌은 매달 1일 초기화 · 다음 초기화: " + rpg_season_pass_next_reset_date() + " | 만능 봇 RPG")
    if payouts:
        got = "\n".join(f"T{t} — {label}" for t, label in payouts)
        embed.add_field(name="🎉 방금 받은 보상", value=got, inline=False)
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)


@rpg2_group.command(name="펫합성", description="같은 희귀도 펫 2종을 합성해 상위 희귀도 펫에 도전합니다.")
@app_commands.describe(펫1="재료 펫 1 (이름 일부)", 펫2="재료 펫 2 (이름 일부)")
async def rpg_group_pet_fusion(interaction: discord.Interaction, 펫1: str, 펫2: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    gid = interaction.guild.id
    uid = interaction.user.id
    get_or_create_rpg_player(gid, uid)

    # 이름 일부로 보유 펫 매칭
    name_a = rpg_match_pet_name(gid, uid, 펫1)
    name_b = rpg_match_pet_name(gid, uid, 펫2)
    if not name_a or not name_b:
        missing = 펫1 if not name_a else 펫2
        return await safe_interaction_send(interaction, f"❌ `{missing}`에 해당하는 보유 펫을 찾지 못했어요. `/rpg 펫목록`에서 이름을 확인해주세요.", ephemeral=True)

    result = rpg_pet_fusion(gid, uid, name_a, name_b)
    if not result["ok"]:
        return await safe_interaction_send(interaction, f"❌ {result['msg']}", ephemeral=True)

    if result["success"]:
        desc = f"✨ **합성 성공!**\n`{name_a}` + `{name_b}`\n→ 상위 희귀도 **{result['pet']}** 획득! 🎉"
        color = discord.Color.gold()
    else:
        desc = f"💥 **합성 실패...**\n`{name_a}` + `{name_b}`\n→ 같은 희귀도 **{result['pet']}**(으)로 만족해야 했어요."
        color = discord.Color.greyple()
    embed = discord.Embed(title="🧬 펫 합성 결과", description=desc, color=color)
    embed.set_footer(text=f"성공 확률 {int(RPG_PET_FUSION_SUCCESS*100)}% · 실패해도 동급 펫을 받아요 | 만능 봇 RPG")
    await safe_interaction_send(interaction, embed=embed)


@rpg2_group.command(name="길드랭킹", description="이 서버 길드들의 레벨·자원·길드전 전적 순위를 확인합니다.")
@app_commands.describe(기준="정렬 기준 (기본: 레벨)")
@app_commands.choices(기준=[
    app_commands.Choice(name="🏰 레벨", value="level"),
    app_commands.Choice(name="💰 자원", value="resources"),
    app_commands.Choice(name="⚔️ 길드전 승수", value="war"),
])
async def rpg2_group_guild_ranking(interaction: discord.Interaction, 기준: app_commands.Choice[str] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    sort_key = 기준.value if 기준 is not None else "level"
    gid = interaction.guild.id

    if sort_key == "resources":
        order, label, unit, icon = "resources DESC, level DESC", "자원", "자원", "💰"
    elif sort_key == "war":
        order, label, unit, icon = "war_wins DESC, level DESC", "길드전 승수", "승", "⚔️"
    else:
        order, label, unit, icon = "level DESC, exp DESC", "레벨", "Lv.", "🏰"

    with DB_MUTEX:
        c.execute(
            f"SELECT clan_id, name, level, resources, war_wins, war_losses FROM rpg_guilds "
            f"WHERE guild_id=? ORDER BY {order} LIMIT 10",
            (gid,),
        )
        rows = c.fetchall()

    if not rows:
        return await safe_interaction_send(interaction, "아직 이 서버에 만들어진 길드가 없어요. `/rpg2 길드`로 만들어보세요!", ephemeral=True)

    medals = ["🥇", "🥈", "🥉"]
    lines = []
    for idx, (clan_id, name, level, resources, war_wins, war_losses) in enumerate(rows):
        rank_icon = medals[idx] if idx < 3 else f"`{idx + 1}.`"
        member_count = len(rpg_clan_members(gid, clan_id))
        if sort_key == "resources":
            metric = f"💰 {resources:,}"
        elif sort_key == "war":
            metric = f"⚔️ {war_wins}승 {war_losses}패"
        else:
            metric = f"Lv.{level}"
        lines.append(f"{rank_icon} **{name}** — {metric} · 👥 {member_count}명")

    embed = discord.Embed(title=f"{icon} 길드 랭킹 · {label} TOP 10", description="\n".join(lines), color=0xF1C40F)
    embed.set_footer(text="만능 봇 | 길드 랭킹")
    await safe_interaction_send(interaction, embed=embed)


@rpg2_group.command(name="펫랭킹", description="펫을 가장 많이 모은 수집왕 TOP 10을 확인합니다.")
async def rpg2_group_pet_ranking(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    gid = interaction.guild.id

    # 유저별 (보유 펫 종류 수, 총 마릿수) 집계
    with DB_MUTEX:
        c.execute(
            "SELECT user_id, COUNT(DISTINCT pet_name) AS kinds, SUM(count) AS total "
            "FROM rpg_pets WHERE guild_id=? GROUP BY user_id ORDER BY kinds DESC, total DESC LIMIT 10",
            (gid,),
        )
        rows = c.fetchall()

    if not rows:
        return await safe_interaction_send(interaction, "아직 펫을 모은 사람이 없어요. `/rpg 뽑기`로 펫을 뽑아보세요!", ephemeral=True)

    medals = ["🥇", "🥈", "🥉"]
    lines = []
    for idx, (user_id, kinds, total) in enumerate(rows):
        rank_icon = medals[idx] if idx < 3 else f"`{idx + 1}.`"
        lines.append(f"{rank_icon} <@{user_id}> — 🐾 **{kinds}종** (총 {total}마리)")

    embed = discord.Embed(title="🐾 펫 수집왕 랭킹 TOP 10", description="\n".join(lines), color=0x2ECC71)
    embed.set_footer(text="펫 종류 수 기준 · 동점 시 총 마릿수 | 만능 봇 펫 랭킹")
    await safe_interaction_send(interaction, embed=embed)


@rpg2_group.command(name="월드보스", description="서버 전체가 함께 때리는 월드보스! 공격하고 처치 기여도로 보상을 받아요.")
@app_commands.describe(행동="공격/현황/소환 중 선택 (비우면 공격)", 난이도="[소환 전용] 원하는 난이도로 소환 (비우면 랜덤, 관리자만)")
@app_commands.choices(행동=[
    app_commands.Choice(name="⚔️ 공격하기", value="공격"),
    app_commands.Choice(name="📊 현황·기여 순위", value="현황"),
    app_commands.Choice(name="✨ 보스 소환(관리자)", value="소환"),
])
@app_commands.choices(난이도=[
    app_commands.Choice(name="🟢 쉬움", value="0"),
    app_commands.Choice(name="🟡 보통", value="2"),
    app_commands.Choice(name="🟠 어려움", value="3"),
    app_commands.Choice(name="🔴 위험", value="4"),
    app_commands.Choice(name="🟣 매우 위험", value="5"),
    app_commands.Choice(name="⚫ 지옥", value="6"),
])
async def rpg2_group_worldboss(interaction: discord.Interaction, 행동: app_commands.Choice[str] = None, 난이도: app_commands.Choice[str] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await rpg_check_feature_channel(interaction, "월드보스"):
        return
    gid = interaction.guild.id
    uid = interaction.user.id
    mode = 행동.value if 행동 is not None else "공격"
    boss = rpg_get_worldboss(gid)

    # ----- 소환 -----
    if mode == "소환":
        if not interaction.user.guild_permissions.administrator:
            return await safe_interaction_send(interaction, "❌ 월드보스 소환은 관리자만 할 수 있어요.", ephemeral=True)
        if boss:
            return await safe_interaction_send(interaction, f"⚠️ 이미 {boss['boss_emoji']} **{boss['boss_name']}**이(가) 등장해 있어요! `/rpg2 월드보스 행동:공격`으로 공격하세요.", ephemeral=True)
        tier = int(난이도.value) if 난이도 is not None else None
        boss = rpg_worldboss_spawn(gid, tier)
        embed = discord.Embed(
            title=f"{boss['boss_emoji']} 월드보스 출현!",
            description=(
                f"**{boss['boss_name']}**이(가) 나타났어요!\n"
                f"🎚️ 난이도: **{rpg_worldboss_difficulty(boss['boss_name'])}**\n"
                f"❤️ 체력: **{boss['max_hp']:,}**\n"
                f"💰 처치 보상 풀: **{boss['reward_pool']:,}P** (기여도 비례 분배)\n\n"
                "모두 `/rpg2 월드보스 행동:공격`으로 함께 쓰러뜨려요! 상위 기여자는 추가 아이템도 받아요."
            ),
            color=discord.Color.dark_red(),
        )
        embed.set_footer(text="만능 봇 | 월드보스")
        rpg_apply_image(embed, "worldboss", boss["boss_name"])
        return await safe_interaction_send(interaction, embed=embed)

    # ----- 현황 -----
    if mode == "현황":
        if not boss:
            return await safe_interaction_send(interaction, "지금 등장한 월드보스가 없어요. `/rpg2 월드보스 행동:소환`으로 불러오세요!", ephemeral=True)
        top = rpg_worldboss_top_damage(gid, 10)
        hp_ratio = boss["hp"] / boss["max_hp"] if boss["max_hp"] else 0
        bar = rpg_progress_bar(boss["hp"], boss["max_hp"])
        lines = []
        medals = ["🥇", "🥈", "🥉"]
        for idx, (u, dmg) in enumerate(top):
            ic = medals[idx] if idx < 3 else f"`{idx + 1}.`"
            lines.append(f"{ic} <@{u}> — {dmg:,} 피해")
        embed = discord.Embed(
            title=f"{boss['boss_emoji']} {boss['boss_name']} 현황",
            description=f"❤️ {boss['hp']:,} / {boss['max_hp']:,} ({hp_ratio*100:.1f}%)\n{bar}\n\n**기여 순위**\n" + ("\n".join(lines) if lines else "아직 공격한 사람이 없어요."),
            color=discord.Color.dark_red(),
        )
        embed.set_footer(text=f"처치 보상 풀 {boss['reward_pool']:,}P | 만능 봇 월드보스")
        rpg_apply_image(embed, "worldboss", boss["boss_name"], thumbnail=True)
        return await safe_interaction_send(interaction, embed=embed)

    # ----- 공격 -----
    if not boss:
        return await safe_interaction_send(interaction, "지금 등장한 월드보스가 없어요. `/rpg2 월드보스 행동:소환`으로 불러오세요!", ephemeral=True)

    player = get_or_create_rpg_player(gid, uid)
    now_dt = datetime.datetime.now()

    # 개인 공격 쿨다운 확인
    with DB_MUTEX:
        c.execute("SELECT damage, last_attack_at FROM rpg_worldboss_damage WHERE guild_id=? AND user_id=?", (gid, uid))
        drow = c.fetchone()
    my_damage = int(drow[0]) if drow else 0
    if drow and drow[1]:
        try:
            last = datetime.datetime.strptime(drow[1], "%Y-%m-%d %H:%M:%S")
            wait = RPG_WORLDBOSS_COOLDOWN - (now_dt - last).total_seconds()
            if wait > 0:
                return await safe_interaction_send(interaction, f"⏳ 숨 고르는 중… **{int(wait) + 1}초** 뒤에 다시 공격할 수 있어요.", ephemeral=True)
        except ValueError:
            pass

    # 데미지 계산 (레이드와 동일한 방식: 공격력 기반 3타)
    power = rpg_player_power(player)
    total_damage = 0
    hit_lines = []
    for hit in range(1, 4):
        dmg = max(1, int(power * random.uniform(0.9, 1.3)))
        crit_text = ""
        if random.random() < 0.15:
            dmg = int(dmg * 1.5)
            crit_text = " 💥"
        total_damage += dmg
        hit_lines.append(f"{hit}타: **{dmg:,}**{crit_text}")

    new_hp = max(0, boss["hp"] - total_damage)
    now_str = now_dt.strftime("%Y-%m-%d %H:%M:%S")
    with DB_MUTEX:
        c.execute(
            "INSERT OR REPLACE INTO rpg_worldboss_damage (guild_id, user_id, damage, last_attack_at) VALUES (?,?,?,?)",
            (gid, uid, my_damage + total_damage, now_str),
        )
        c.execute("UPDATE rpg_worldboss SET hp=? WHERE guild_id=?", (new_hp, gid))
        conn.commit()

    # 시즌패스 XP도 함께 적립
    try:
        rpg_season_pass_add_xp(gid, uid, 15)
    except Exception:
        pass

    # 처치 판정
    if new_hp <= 0:
        payouts = rpg_worldboss_settle(gid)
        medals = ["🥇", "🥈", "🥉"]
        lines = []
        for p in payouts[:10]:
            ic = medals[p["rank"] - 1] if p["rank"] <= 3 else f"{p['rank']}."
            item_txt = f" + {p['item']}" if p["item"] else ""
            lines.append(f"{ic} <@{p['user_id']}> — {p['damage']:,} 피해 · 💰{p['point']:,}P{item_txt}")
        desc = f"🎉 **{boss['boss_emoji']} {boss['boss_name']} 처치 성공!**\n마지막 일격: {interaction.user.mention}\n\n**기여도 보상**\n" + ("\n".join(lines) if lines else "기여자 없음")
        embed = discord.Embed(title="🏆 월드보스 처치!", description=desc, color=discord.Color.gold())
        embed.set_footer(text="다음 보스는 /rpg2 월드보스 행동:소환 으로 | 만능 봇")
        rpg_apply_image(embed, "worldboss", boss["boss_name"])
        try:
            await send_log(interaction.guild, f"🏆 월드보스 처치: {boss['boss_name']} (막타 {interaction.user})", "general")
        except Exception:
            pass
        return await safe_interaction_send(interaction, embed=embed)

    embed = discord.Embed(
        title=f"⚔️ {boss['boss_emoji']} {boss['boss_name']} 공격!",
        description="\n".join(hit_lines) + f"\n\n총 피해: **{total_damage:,}**\n❤️ 남은 체력: **{new_hp:,} / {boss['max_hp']:,}**\n🗡️ 내 누적 기여: **{my_damage + total_damage:,}**",
        color=discord.Color.orange(),
    )
    embed.set_footer(text=f"{RPG_WORLDBOSS_COOLDOWN}초마다 공격 가능 | 만능 봇 월드보스")
    await safe_interaction_send(interaction, embed=embed)


@rpg2_group.command(name="던전초기화", description="던전 층수 랭킹을 지금 즉시 초기화하고 현재 1~3등에게 보상을 줍니다. (관리자 전용)")
async def rpg2_group_dungeon_reset(interaction: discord.Interaction):
    if not await require_admin_interaction(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id

    # 현재 1~3등 산정 후 보상 지급
    top3 = rpg_dungeon_top3(gid)
    payouts = []
    for idx, (uid, floor, level) in enumerate(top3):
        rank = idx + 1
        reward = RPG_DUNGEON_SEASON_REWARDS.get(rank)
        if not reward:
            continue
        point, item_name, item_amt = reward
        set_user_point(gid, uid, get_user_point(gid, uid) + point)
        add_inventory_item(uid, item_name, item_amt, guild_id=gid)
        payouts.append({"rank": rank, "user_id": uid, "floor": floor, "point": point, "item": item_name, "amount": item_amt})

    # 던전 층수/도전 필드 초기화 + 시즌 키 동기화(자동 루프가 또 초기화하지 않도록)
    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    current = rpg_dungeon_season_key()
    with DB_MUTEX:
        c.execute("UPDATE rpg_players SET dungeon_floor=0, dungeon_date='', dungeon_attempts=0 WHERE guild_id=?", (gid,))
        c.execute(
            "INSERT INTO rpg_dungeon_season(guild_id, season_key, reset_at) VALUES (?,?,?) "
            "ON CONFLICT(guild_id) DO UPDATE SET season_key=excluded.season_key, reset_at=excluded.reset_at",
            (gid, current, now),
        )
        conn.commit()

    medals = ["🥇", "🥈", "🥉"]
    if payouts:
        lines = []
        for p in payouts:
            m = medals[p["rank"] - 1] if p["rank"] <= 3 else f"{p['rank']}."
            lines.append(f"{m} <@{p['user_id']}> — {p['floor']}층 · 💰{p['point']:,}P + {p['item']} {p['amount']}개")
        desc = "🏰 **던전 랭킹을 수동으로 초기화했어요!**\n1~3등 보상이 지급되었습니다.\n\n" + "\n".join(lines)
    else:
        desc = "🏰 **던전 랭킹을 수동으로 초기화했어요!**\n(도전 기록이 없어 지급된 보상은 없어요.)"
    desc += "\n\n모든 플레이어의 던전 층수가 0으로 초기화됐어요."

    embed = discord.Embed(title="🏰 던전 수동 초기화", description=desc, color=discord.Color.dark_purple())
    embed.set_footer(text=f"실행: {interaction.user.display_name} | 만능 봇 RPG 던전")
    try:
        await send_log(interaction.guild, f"🏰 던전 랭킹 수동 초기화 (실행: {interaction.user})", "general")
    except Exception:
        pass
    await interaction.followup.send(embed=embed, ephemeral=False)


@rpg_group.command(name="도감", description="RPG 도감 — 몬스터/보스/펫/유물/직업을 클릭해서 자세히 봅니다.")
async def rpg_group_bestiary(interaction: discord.Interaction):
    embed = rpg_build_dex_overview_embed()
    await safe_interaction_send(interaction, embed=embed, view=RPGDexView())


def rpg_build_dex_overview_embed() -> discord.Embed:
    embed = discord.Embed(
        title="📖 RPG 도감",
        description=(
            "아래 메뉴에서 카테고리를 고르고, 각 항목을 클릭하면 상세 정보가 나와요.\n\n"
            f"👹 몬스터 {len(RPG_MONSTERS)}종 · 👑 보스 {len(RPG_BOSSES)}종 · "
            f"🐾 펫 {sum(len(e['pets']) for e in RPG_PET_POOL)}종 · 🧿 유물 세트 {len(RPG_RELIC_SETS)}종 · 🎓 직업 {len(RPG_JOB_LINES)}계열"
        ),
        color=discord.Color.dark_green(),
    )
    if bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    embed.set_footer(text="만능 봇 | RPG 도감")
    return embed


class RPGDexCategorySelect(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label="몬스터", value="monster", emoji="👹"),
            discord.SelectOption(label="보스", value="boss", emoji="👑"),
            discord.SelectOption(label="레이드 보스", value="raid", emoji="🔥"),
            discord.SelectOption(label="펫", value="pet", emoji="🐾"),
            discord.SelectOption(label="유물 세트", value="relic", emoji="🧿"),
            discord.SelectOption(label="직업", value="job", emoji="🎓"),
        ]
        super().__init__(placeholder="카테고리 선택", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction: discord.Interaction):
        view: "RPGDexView" = self.view
        view.category = self.values[0]
        view.refresh_items()
        embed = rpg_build_dex_category_embed(view.category)
        await interaction.response.edit_message(embed=embed, view=view)


def rpg_build_dex_category_embed(category: str) -> discord.Embed:
    if category == "monster":
        lines = [f"{m['emoji']} **{m['name']}** (Lv.{m['min_level']}+)" for m in RPG_MONSTERS]
        return discord.Embed(title="👹 몬스터 도감", description="\n".join(lines) + "\n\n아래 메뉴에서 몬스터를 클릭해 상세정보를 보세요.", color=discord.Color.dark_green())
    if category == "boss":
        lines = [f"{b['emoji']} **{b['name']}** (Lv.{b['min_level']}+)" for b in RPG_BOSSES]
        return discord.Embed(title="👑 보스 도감", description="\n".join(lines) + "\n\n아래 메뉴에서 보스를 클릭해 드랍 확률을 보세요.", color=discord.Color.purple())
    if category == "raid":
        lines = [f"{cfg['emoji']} **{cfg['name']}** ({diff}) · HP {cfg['hp']:,}" for diff, cfg in RPG_RAID_BOSSES.items()]
        return discord.Embed(title="🔥 레이드 보스 도감", description="\n".join(lines) + "\n\n아래 메뉴에서 레이드 보스를 클릭해 상세정보를 보세요.", color=discord.Color.dark_red())
    if category == "pet":
        lines = [f"{rpg_rarity_tier(e['rarity_index'])['emoji']} {rpg_rarity_tier(e['rarity_index'])['name']}: {', '.join(e['pets'])}" for e in RPG_PET_POOL]
        return discord.Embed(title="🐾 펫 도감", description="\n".join(lines), color=discord.Color.magenta())
    if category == "relic":
        lines = [f"{s['set_name']} · {s['set_bonus_text']}" for s in RPG_RELIC_SETS]
        return discord.Embed(title="🧿 유물 도감", description="\n".join(lines) + "\n\n아래 메뉴에서 세트를 클릭해 상세정보를 보세요.", color=discord.Color.teal())
    if category == "job":
        lines = [f"{RPG_JOB_LINES_BY_ID[l['job_id']]['tier_titles'][0]} 계열: {l['line_name']}" for l in RPG_JOB_LINES]
        return discord.Embed(title="🎓 직업 도감", description="\n".join(f"{l['line_name']} · {l['skill_desc']}" for l in RPG_JOB_LINES) + "\n\n아래 메뉴에서 직업을 클릭해 전직 로드맵을 보세요.", color=discord.Color.blurple())
    return rpg_build_dex_overview_embed()


class RPGDexDetailSelect(discord.ui.Select):
    def __init__(self, category: str):
        self.category = category
        options = []
        if category == "monster":
            for i, m in enumerate(RPG_MONSTERS[:25]):
                options.append(discord.SelectOption(label=m["name"][:100], value=str(i), emoji=None))
        elif category == "boss":
            for i, b in enumerate(RPG_BOSSES[:25]):
                options.append(discord.SelectOption(label=b["name"][:100], value=str(i)))
        elif category == "raid":
            for i, (diff, cfg) in enumerate(RPG_RAID_BOSSES.items()):
                options.append(discord.SelectOption(label=f"{cfg['name']} ({diff})"[:100], value=str(i)))
        elif category == "relic":
            for i, s in enumerate(RPG_RELIC_SETS[:25]):
                options.append(discord.SelectOption(label=s["set_name"][:100], value=str(i)))
        elif category == "job":
            for i, l in enumerate(RPG_JOB_LINES[:25]):
                options.append(discord.SelectOption(label=l["line_name"][:100], value=str(i)))
        elif category == "pet":
            for i, e in enumerate(RPG_PET_POOL[:25]):
                t = rpg_rarity_tier(e["rarity_index"])
                options.append(discord.SelectOption(label=f"{t['name']} 등급", value=str(i)))
        if not options:
            options = [discord.SelectOption(label="항목 없음", value="__none__")]
        super().__init__(placeholder="상세히 볼 항목 선택", min_values=1, max_values=1, options=options, row=1)

    async def callback(self, interaction: discord.Interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        idx = int(self.values[0])
        embed = rpg_build_dex_detail_embed(self.category, idx)
        await interaction.response.edit_message(embed=embed, view=self.view)


def rpg_build_dex_detail_embed(category: str, idx: int) -> discord.Embed:
    if category == "monster":
        m = RPG_MONSTERS[idx]
        drops = ", ".join(f"{n} {int(ch*100)}%" for n, ch in m["drops"]) or "없음"
        e = discord.Embed(title=f"{m['emoji']} {m['name']}", color=discord.Color.dark_green())
        e.add_field(name="등장 레벨", value=f"Lv.{m['min_level']}+", inline=True)
        e.add_field(name="체력/공격력", value=f"HP {m['hp']} / ATK {m['power']}", inline=True)
        e.add_field(name="보상", value=f"EXP {m['exp']} · {m['gold'][0]}~{m['gold'][1]}P", inline=True)
        e.add_field(name="드랍 아이템", value=drops, inline=False)
        rpg_apply_image(e, "monster", m["name"])
        return e
    if category == "boss":
        b = RPG_BOSSES[idx]
        drops = "\n".join(f"• {n} — {int(ch*100)}%" for n, ch in b["drops"]) or "없음"
        e = discord.Embed(title=f"{b['emoji']} {b['name']} (보스)", color=discord.Color.purple())
        e.add_field(name="등장 레벨", value=f"Lv.{b['min_level']}+", inline=True)
        e.add_field(name="체력/공격력", value=f"HP {b['hp']} / ATK {b['power']}", inline=True)
        e.add_field(name="보상", value=f"EXP {b['exp']} · {b['gold'][0]}~{b['gold'][1]}P", inline=True)
        e.add_field(name="🎁 드랍 확률표", value=drops, inline=False)
        rpg_apply_image(e, "boss", b["name"])
        return e
    if category == "raid":
        diff_list = list(RPG_RAID_BOSSES.items())
        diff, cfg = diff_list[idx]
        e = discord.Embed(title=f"{cfg['emoji']} {cfg['name']}", description=f"레이드 난이도: **{diff}**", color=discord.Color.dark_red())
        e.add_field(name="체력", value=f"{cfg['hp']:,}", inline=True)
        e.add_field(name="보상 풀", value=f"💰 {cfg['gold_pool']:,}P · ✨ {cfg['exp_pool']:,} EXP", inline=True)
        e.add_field(name="유물함 확률", value=f"{int(cfg['relic_chance']*100)}%", inline=True)
        e.add_field(name="참여 방법", value="`/rpg 레이드`로 소환/참여 · 서버원 모두가 함께 공격 (기여도 비례 보상)", inline=False)
        rpg_apply_image(e, "raid", diff)
        return e
    if category == "relic":
        s = RPG_RELIC_SETS[idx]
        pieces = "\n".join(f"• {p['name']} (전투+{p['power']}/방어+{p['defense']})" for p in s["pieces"])
        e = discord.Embed(title=s["set_name"], description=f"세트효과(3개 장착): **{s['set_bonus_text']}** · 등장확률 {s['weight']}%", color=discord.Color.teal())
        e.add_field(name="구성 유물", value=pieces, inline=False)
        rpg_apply_image(e, "relic", s["pieces"][0]["relic_id"])  # 세트 대표 이미지(첫 유물)
        return e
    if category == "job":
        l = RPG_JOB_LINES[idx]
        roadmap = "\n".join(f"{RPG_JOB_TIER_LABELS[i]} · Lv.{RPG_JOB_TIER_LEVELS[i]} · {l['tier_titles'][i]}" for i in range(6))
        skills = "\n".join(f"{name} (T{req}, x{mult}) — {desc}" for _sid, name, req, mult, desc in RPG_JOB_SKILLS.get(l["job_id"], []))
        e = discord.Embed(title=f"🎓 {l['line_name']} 계열", description=l["skill_desc"], color=discord.Color.blurple())
        e.add_field(name="전직 로드맵", value=roadmap, inline=False)
        # 2차 전직 분기 (선택의 의식)
        branches = RPG_JOB_BRANCHES.get(l["job_id"])
        if branches:
            branch_text = "\n".join(f"▸ **{bname}** — {bdesc}" for _bid, bname, bdesc, _m in branches)
            e.add_field(name="✨ 2차 전직 분기 (선택의 의식)", value=branch_text, inline=False)
        if skills:
            e.add_field(name="스킬", value=skills, inline=False)
        return e
    if category == "pet":
        e_entry = RPG_PET_POOL[idx]
        t = rpg_rarity_tier(e_entry["rarity_index"])
        e = discord.Embed(title=f"{t['emoji']} {t['name']} 등급 펫", description=f"등장확률 {e_entry['rate']*100:g}% · 전투력 보너스 +{e_entry['power_bonus']}", color=discord.Color.magenta())
        e.add_field(name="펫 목록", value=", ".join(e_entry["pets"]), inline=False)
        return e
    return rpg_build_dex_overview_embed()


class RPGDexView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=300)
        self.category = None
        self.refresh_items()

    def refresh_items(self):
        self.clear_items()
        self.add_item(RPGDexCategorySelect())
        if self.category:
            self.add_item(RPGDexDetailSelect(self.category))


@rpg_group.command(name="랭킹", description="이 서버의 RPG 랭킹 TOP 10을 확인합니다. (레벨/PvP)")
@app_commands.describe(종류="확인할 랭킹 종류 (기본: 레벨)")
@app_commands.choices(종류=[
    app_commands.Choice(name="🏆 레벨 랭킹", value="레벨"),
    app_commands.Choice(name="⚔️ PvP 승리 랭킹", value="PvP"),
    app_commands.Choice(name="🏰 던전 층수 랭킹", value="던전"),
    app_commands.Choice(name="🎓 직업군별 랭킹", value="직업"),
    app_commands.Choice(name="🛠️ 숙련도 랭킹", value="숙련"),
])
async def rpg_group_ranking(interaction: discord.Interaction, 종류: app_commands.Choice[str] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await rpg_check_feature_channel(interaction, "랭킹"):
        return
    kind = 종류.value if 종류 is not None else "레벨"
    medals = ["🥇", "🥈", "🥉"]

    if kind == "직업":
        return await safe_interaction_send(interaction, embed=rpg_build_job_ranking_embed(interaction.guild.id))
    if kind == "숙련":
        return await safe_interaction_send(interaction, embed=rpg_build_mastery_ranking_embed(interaction.guild.id))

    if kind == "던전":
        with DB_MUTEX:
            c.execute(
                "SELECT user_id, dungeon_floor, level FROM rpg_players WHERE guild_id=? AND dungeon_floor > 0 "
                "ORDER BY dungeon_floor DESC, level DESC LIMIT 10",
                (interaction.guild.id,),
            )
            rows = c.fetchall()
        if not rows:
            return await safe_interaction_send(interaction, "아직 던전에 도전한 사람이 없어요. `/rpg 던전`으로 1층부터 올라보세요!", ephemeral=True)
        lines = []
        for idx, (user_id, floor, level) in enumerate(rows):
            rank_icon = medals[idx] if idx < 3 else f"`{idx + 1}.`"
            crown = " 👑" if floor >= 100 else ""
            lines.append(f"{rank_icon} <@{user_id}> — **{floor}층**{crown} (Lv.{level})")
        embed = discord.Embed(title="🏰 던전 층수 랭킹 TOP 10", description="\n".join(lines), color=discord.Color.dark_purple())
        if bot.user:
            embed.set_thumbnail(url=bot.user.display_avatar.url)
        embed.set_footer(text="만능 봇 | RPG 랭킹")
        return await safe_interaction_send(interaction, embed=embed)

    if kind == "PvP":
        with DB_MUTEX:
            c.execute(
                "SELECT user_id, pvp_wins, pvp_losses, level FROM rpg_players WHERE guild_id=? AND pvp_wins > 0 "
                "ORDER BY pvp_wins DESC, pvp_losses ASC LIMIT 10",
                (interaction.guild.id,),
            )
            rows = c.fetchall()
        if not rows:
            return await safe_interaction_send(interaction, "아직 PvP 승리 기록이 없어요. `/rpg 대결`로 첫 승리를 노려보세요!", ephemeral=True)
        lines = []
        for idx, (user_id, wins, losses, level) in enumerate(rows):
            rank_icon = medals[idx] if idx < 3 else f"`{idx + 1}.`"
            wins = wins or 0
            losses = losses or 0
            total = wins + losses
            win_rate = int(wins / total * 100) if total else 0
            lines.append(f"{rank_icon} <@{user_id}> — **{wins}승** {losses}패 (승률 {win_rate}% · Lv.{level})")
        embed = discord.Embed(title="⚔️ PvP 승리 랭킹 TOP 10", description="\n".join(lines), color=discord.Color.red())
        embed.add_field(
            name="🏆 시즌 보상 (2주마다 초기화)",
            value=(
                "🥇1위 50,000P+각성석3 · 🥈2위 30,000P+유물함3 · 🥉3위 20,000P+유물함2\n"
                "4위 12,000P+소환권5 · 5위 8,000P+소환권3\n"
                f"다음 시즌 종료: **{rpg_pvp_next_season_date()}**"
            ),
            inline=False,
        )
    else:
        with DB_MUTEX:
            c.execute(
                "SELECT user_id, level, exp, weapon_level, armor_level FROM rpg_players WHERE guild_id=? ORDER BY level DESC, exp DESC LIMIT 10",
                (interaction.guild.id,),
            )
            rows = c.fetchall()
        if not rows:
            return await safe_interaction_send(interaction, "아직 RPG를 플레이한 사람이 없어요. `/rpg 사냥`으로 시작해보세요!", ephemeral=True)
        lines = []
        for idx, (user_id, level, exp, weapon_level, armor_level) in enumerate(rows):
            rank_icon = medals[idx] if idx < 3 else f"`{idx + 1}.`"
            lines.append(f"{rank_icon} <@{user_id}> — Lv.{level} (무기+{weapon_level}　방어+{armor_level})")
        embed = discord.Embed(title="🏆 RPG 레벨 랭킹 TOP 10", description="\n".join(lines), color=discord.Color.gold())

    if bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    embed.set_footer(text="만능 봇 | RPG 랭킹")
    await safe_interaction_send(interaction, embed=embed)


async def rpg_group_daily_quest_impl(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    guild_id = interaction.guild.id
    user_id = interaction.user.id
    player = get_or_create_rpg_player(guild_id, user_id)
    today_str = datetime.date.today().isoformat()

    if player["daily_quest_date"] != today_str:
        current_count = 0
        claimed = False
    else:
        current_count = player["daily_hunt_count"]
        claimed = bool(player["daily_quest_claimed"])

    progress = min(current_count, RPG_DAILY_QUEST_TARGET)
    if current_count >= RPG_DAILY_QUEST_TARGET and not claimed:
        level_ups, player = rpg_apply_exp(player, RPG_DAILY_QUEST_REWARD_EXP)
        set_user_point(guild_id, user_id, get_user_point(guild_id, user_id) + RPG_DAILY_QUEST_REWARD_GOLD)
        save_rpg_player(
            guild_id, user_id,
            level=player["level"], exp=player["exp"], max_hp=player["max_hp"], hp=player["hp"], stat_points=player["stat_points"], perk_points=player.get("perk_points", 0),
            daily_quest_claimed=1, daily_quest_date=today_str,
        )
        embed = discord.Embed(
            title="🎉 일일퀘스트 보상 수령!",
            description=f"오늘 사냥 {RPG_DAILY_QUEST_TARGET}회 완료 보상을 받았어요!\n✨ 경험치 +{RPG_DAILY_QUEST_REWARD_EXP}　💰 포인트 +{RPG_DAILY_QUEST_REWARD_GOLD}P",
            color=discord.Color.green(),
        )
        if level_ups:
            embed.add_field(name="🆙 레벨업!", value=f"Lv.{level_ups[0] - 1} → **Lv.{level_ups[-1]}**", inline=False)
    else:
        status_text = "✅ 보상 수령 완료" if claimed else f"진행도 {progress}/{RPG_DAILY_QUEST_TARGET}"
        embed = discord.Embed(
            title="📜 오늘의 일일퀘스트",
            description=f"**몬스터 사냥 {RPG_DAILY_QUEST_TARGET}회 하기**\n{status_text}\n\n보상: 경험치 +{RPG_DAILY_QUEST_REWARD_EXP} / 포인트 +{RPG_DAILY_QUEST_REWARD_GOLD}P",
            color=discord.Color.blurple(),
        )
    if bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)
    embed.set_footer(text="만능 봇 | RPG 일일퀘스트 (매일 초기화)")
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)


# =========================
def rpg_build_engrave_embed_full(guild_id: int, user_id: int, kind: str, extra_desc: str = "") -> discord.Embed:
    player = get_or_create_rpg_player(guild_id, user_id)
    kind_label = "무기" if kind == "weapon" else "방어구"
    kind_emoji = "🗡️" if kind == "weapon" else "🛡️"
    options = rpg_get_equip_options(player, kind)
    locked_count = sum(1 for o in options if o.get("locked"))
    cost = 1 + locked_count
    stones = get_inventory_amount(user_id, RPG_ENGRAVE_ITEM)

    lines = []
    for i in range(RPG_ENGRAVE_MAX_OPTIONS):
        if i < len(options):
            opt = options[i]
            meta = RPG_ENGRAVE_OPTION_META.get(opt.get("id"))
            if meta:
                name, unit, _r = meta
                lock_icon = "🔒" if opt.get("locked") else "🔓"
                lines.append(f"`{i+1}.` {lock_icon} {rpg_engrave_quality(opt['id'], opt['value'])} **{name} +{opt['value']}{unit}**")
                continue
        lines.append(f"`{i+1}.` ▫️ (비어있음)")

    embed = discord.Embed(
        title=f"{kind_emoji} {kind_label} 세공 패널",
        description="\n".join(lines) + (f"\n\n{extra_desc}" if extra_desc else ""),
        color=discord.Color.dark_purple(),
    )
    embed.add_field(
        name="💎 비용 / 보유",
        value=f"세공 1회 = 세공석 **{cost}개** (기본 1 + 🔒잠금당 +1) · 보유: **{stones}개**",
        inline=True,
    )
    embed.add_field(name="⚔️ 능력치", value=f"전투력 {rpg_player_power(player)} · 방어력 {rpg_player_defense(player)}", inline=True)
    embed.set_footer(text="🔒잠근 옵션은 세공해도 유지 · 잠금 상태는 저장돼요 | 만능 봇 RPG 세공")
    return embed


class RPGEngraveLockButton(discord.ui.Button):
    def __init__(self, index: int, opt: dict):
        meta = RPG_ENGRAVE_OPTION_META.get(opt.get("id"), ("옵션", "", (0, 0)))
        locked = bool(opt.get("locked"))
        label = f"{index + 1}번 {meta[0]} +{opt.get('value', 0)}{meta[1]}"[:78]
        super().__init__(
            label=label,
            emoji="🔒" if locked else "🔓",
            style=discord.ButtonStyle.danger if locked else discord.ButtonStyle.secondary,
            row=0,
        )
        self.index = index

    async def callback(self, interaction: discord.Interaction):
        await self.view.toggle_lock(interaction, self.index)


class RPGEngraveRollButton(discord.ui.Button):
    def __init__(self, cost: int):
        super().__init__(label=f"세공하기 (세공석 {cost}개)", emoji="✨", style=discord.ButtonStyle.success, row=1)

    async def callback(self, interaction: discord.Interaction):
        await self.view.do_roll(interaction)


class RPGEngraveResetButton(discord.ui.Button):
    def __init__(self):
        super().__init__(label="전체 초기화", emoji="🗑️", style=discord.ButtonStyle.gray, row=1)

    async def callback(self, interaction: discord.Interaction):
        await self.view.do_reset(interaction)


class RPGEngraveView(discord.ui.View):
    """세공 패널: 옵션별 잠금 토글 + 잠기지 않은 슬롯만 리롤합니다."""

    def __init__(self, guild_id: int, user_id: int, kind: str):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        self.kind = kind
        self.options_field = "weapon_options" if kind == "weapon" else "armor_options"
        self.refresh_items()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 이 세공 패널은 다른 사람이 연 거예요. `/rpg 세공`으로 본인 패널을 열어주세요.", ephemeral=True)
            return False
        return True

    def refresh_items(self):
        self.clear_items()
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        options = rpg_get_equip_options(player, self.kind)
        for i, opt in enumerate(options[:RPG_ENGRAVE_MAX_OPTIONS]):
            self.add_item(RPGEngraveLockButton(i, opt))
        locked_count = sum(1 for o in options if o.get("locked"))
        self.add_item(RPGEngraveRollButton(1 + locked_count))
        self.add_item(RPGEngraveResetButton())

    async def _refresh_message(self, interaction: discord.Interaction, extra_desc: str = ""):
        self.refresh_items()
        embed = rpg_build_engrave_embed_full(self.guild_id, self.user_id, self.kind, extra_desc)
        await interaction.response.edit_message(embed=embed, view=self)

    async def toggle_lock(self, interaction: discord.Interaction, index: int):
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        options = rpg_get_equip_options(player, self.kind)
        if index >= len(options):
            return await interaction.response.defer()
        options[index]["locked"] = not options[index].get("locked", False)
        save_rpg_player(self.guild_id, self.user_id, **{self.options_field: json.dumps(options, ensure_ascii=False)})
        await self._refresh_message(interaction)

    async def do_roll(self, interaction: discord.Interaction):
        player = get_or_create_rpg_player(self.guild_id, self.user_id)
        options = rpg_get_equip_options(player, self.kind)
        locked_count = sum(1 for o in options if o.get("locked"))
        if locked_count >= RPG_ENGRAVE_MAX_OPTIONS:
            return await self._refresh_message(interaction, "ℹ️ 3개 옵션이 전부 🔒잠겨있어서 세공할 슬롯이 없어요. 잠금을 하나 풀어주세요.")
        cost = 1 + locked_count
        if get_inventory_amount(self.user_id, RPG_ENGRAVE_ITEM) < cost:
            return await self._refresh_message(interaction, f"❌ 세공석이 부족해요. (필요 {cost}개) `/rpg 상점`에서 구매해주세요.")
        consume_inventory_item(self.user_id, RPG_ENGRAVE_ITEM, cost)

        pool = RPG_ENGRAVE_OPTIONS[self.kind]
        new_options = []
        changed = []
        for i in range(RPG_ENGRAVE_MAX_OPTIONS):
            if i < len(options) and options[i].get("locked"):
                new_options.append(options[i])  # 잠긴 옵션은 그대로 유지
                continue
            opt_id, opt_name, unit, (lo, hi) = random.choice(pool)
            value = random.randint(lo, hi)
            new_options.append({"id": opt_id, "value": value, "locked": False})
            changed.append(f"{rpg_engrave_quality(opt_id, value)} {opt_name} +{value}{unit}")
        save_rpg_player(self.guild_id, self.user_id, **{self.options_field: json.dumps(new_options, ensure_ascii=False)})
        await self._refresh_message(interaction, "✨ 새로 굴린 옵션: " + " · ".join(changed) + f" (세공석 {cost}개 사용)")

    async def do_reset(self, interaction: discord.Interaction):
        save_rpg_player(self.guild_id, self.user_id, **{self.options_field: ""})
        await self._refresh_message(interaction, "🗑️ 옵션을 전부 초기화했어요. (잠금 포함)")


@rpg_group.command(name="세공", description="세공 패널을 엽니다. 좋은 옵션은 🔒잠그고 나머지만 다시 굴릴 수 있어요!")
@app_commands.describe(부위="세공할 장비")
@app_commands.choices(부위=[
    app_commands.Choice(name="🗡️ 무기", value="weapon"),
    app_commands.Choice(name="🛡️ 방어구", value="armor"),
])
async def rpg_group_engrave(interaction: discord.Interaction, 부위: app_commands.Choice[str]):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await rpg_check_feature_channel(interaction, "강화"):
        return
    kind = 부위.value
    view = RPGEngraveView(interaction.guild.id, interaction.user.id, kind)
    embed = rpg_build_engrave_embed_full(interaction.guild.id, interaction.user.id, kind)
    await safe_interaction_send(interaction, embed=embed, view=view, ephemeral=True)


@rpg_group.command(name="각성", description="각성석으로 장비 등급을 올려요. (성공/유지/하락/파괴, 각성보호권으로 안전하게)")
@app_commands.describe(대상="각성할 장비", 보호="각성보호권을 사용해 파괴/하락을 막을지 여부")
@app_commands.choices(대상=[
    app_commands.Choice(name="🗡️ 무기", value="weapon"),
    app_commands.Choice(name="🛡️ 방어구", value="armor"),
    app_commands.Choice(name="🐾 펫 (같은 펫 5마리로 각성)", value="pet"),
])
@app_commands.choices(보호=[
    app_commands.Choice(name="🛡️ 보호권 사용 (파괴/하락 방지)", value="yes"),
    app_commands.Choice(name="위험 감수 (보호권 미사용)", value="no"),
])
async def rpg_group_awaken(interaction: discord.Interaction, 대상: app_commands.Choice[str], 보호: app_commands.Choice[str] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not await rpg_check_feature_channel(interaction, "강화"):
        return
    if 대상.value == "pet":
        return await safe_interaction_send(
            interaction,
            embed=rpg_build_pet_awaken_embed(interaction.guild.id, interaction.user.id),
            view=RPGPetAwakenView(interaction.guild.id, interaction.user.id),
            ephemeral=True,
        )
    user_id = interaction.user.id
    if get_inventory_amount(user_id, "각성석") < 1:
        return await safe_interaction_send(interaction, "❌ 각성석이 없어요. `/rpg 상점`에서 구매하거나 보스에게서 얻어보세요.", ephemeral=True)

    player = get_or_create_rpg_player(interaction.guild.id, user_id)
    field_key = "weapon_rarity" if 대상.value == "weapon" else "armor_rarity"
    label = "무기" if 대상.value == "weapon" else "방어구"
    current_index = player[field_key]
    current_tier = rpg_rarity_tier(current_index)

    if current_index >= len(RPG_AWAKEN_TABLE):
        return await safe_interaction_send(interaction, f"✨ {label}는 이미 최고 등급 **{current_tier['emoji']} {current_tier['name']}** 이에요! 더 이상 각성할 수 없어요.", ephemeral=True)

    use_protect = 보호 is not None and 보호.value == "yes"
    if use_protect and get_inventory_amount(user_id, RPG_AWAKEN_PROTECT_ITEM) < 1:
        return await safe_interaction_send(interaction, f"❌ {RPG_AWAKEN_PROTECT_ITEM}이 없어요. `/rpg 상점`에서 구매하거나 보호 없이 도전해주세요.", ephemeral=True)

    consume_inventory_item(user_id, "각성석", 1)
    outcome = rpg_awaken_roll(current_index)

    # 보호권: 파괴/하락을 '유지'로 대체
    protected_note = ""
    if use_protect and outcome in ("down", "destroy"):
        consume_inventory_item(user_id, RPG_AWAKEN_PROTECT_ITEM, 1)
        protected_note = f"\n🛡️ **{RPG_AWAKEN_PROTECT_ITEM}**이 {('파괴' if outcome == 'destroy' else '하락')}을 막았어요!"
        outcome = "keep"
    elif use_protect:
        consume_inventory_item(user_id, RPG_AWAKEN_PROTECT_ITEM, 1)  # 성공/유지여도 보호권은 소모
        protected_note = f"\n🛡️ {RPG_AWAKEN_PROTECT_ITEM} 사용 (이번엔 위험이 없었어요)"

    table = RPG_AWAKEN_TABLE[current_index]
    if outcome == "success":
        new_index = current_index + 1
        save_rpg_player(interaction.guild.id, user_id, **{field_key: new_index})
        new_tier = rpg_rarity_tier(new_index)
        embed = discord.Embed(
            title="🌟 각성 성공!",
            description=f"{label}이(가) **{current_tier['emoji']} {current_tier['name']} → {new_tier['emoji']} {new_tier['name']}** 등급으로 각성했어요!{protected_note}",
            color=discord.Color.orange(),
        )
    elif outcome == "keep":
        embed = discord.Embed(
            title="😐 각성 실패 (유지)",
            description=f"등급 변화 없이 **{current_tier['emoji']} {current_tier['name']}** 그대로예요. (각성석 소모){protected_note}",
            color=discord.Color.greyple(),
        )
    elif outcome == "down":
        new_index = max(0, current_index - 1)
        save_rpg_player(interaction.guild.id, user_id, **{field_key: new_index})
        new_tier = rpg_rarity_tier(new_index)
        embed = discord.Embed(
            title="📉 각성 실패 (등급 하락!)",
            description=f"이런! {label} 등급이 **{current_tier['emoji']} {current_tier['name']} → {new_tier['emoji']} {new_tier['name']}** 로 하락했어요.{protected_note}",
            color=discord.Color.red(),
        )
    else:  # destroy
        save_rpg_player(interaction.guild.id, user_id, **{field_key: 0, ("weapon_level" if 대상.value == "weapon" else "armor_level"): 0})
        embed = discord.Embed(
            title="💥 각성 대실패 (장비 파괴!)",
            description=f"**{label}가 파괴**되어 일반 등급 +0으로 초기화됐어요... 다음엔 각성보호권을 사용해보세요.{protected_note}",
            color=discord.Color.dark_red(),
        )
    embed.set_footer(
        text=f"확률 성공 {table['success']}% / 유지 {table['keep']}% / 하락 {table['down']}% / 파괴 {table['destroy']}% | 만능 봇 RPG"
    )
    await safe_interaction_send(interaction, embed=embed)


# =========================
# 무기/방어구 뽑기 희귀도 확률 (일반~신)
RPG_EQUIP_GACHA_RATES = [0.40, 0.30, 0.16, 0.09, 0.04, 0.00995, 0.00005]  # 마지막 = ??? 사신수 0.005%
RPG_EQUIP_GACHA_LEVEL_RANGE = (1, 30)  # 뽑기로 나오는 강화 수치 범위
RPG_GACHA_TICKETS = {"펫": "소환권", "무기": "무기뽑기권", "방어구": "방어구뽑기권", "유물": RPG_RELIC_BOX_ITEM}

#  - 무기/방어구: 200회 전설(3), 500회 신화(4), 1000회 신(5) 확정 (각 임계값에서 개별 초기화)
#  - 펫: 1000회 단일 천장 → 신(5) 확정 + 카운터 초기화 (중간 200/500 초기화 없음)
RPG_GACHA_PITY_TIERS = [
    (200, 3),   # (누적 횟수, 최소 보장 등급)
    (500, 4),
    (1000, 5),
]
# 펫 전용 천장: 200회 전설+, 500회 신화+, 1000회 신+ 모두 보장.
# 단, 카운터 초기화는 오직 1000회 달성 시에만 발생 (200/500은 유지하며 계속 누적).
RPG_PET_PITY_TIERS = [
    (200, 3),   # 전설+
    (500, 4),   # 신화+
    (1000, 5),  # 신+
]
# 카운터를 초기화하는 임계값 (종류별). 펫은 1000회에서만 초기화.
RPG_PITY_RESET_THRESHOLDS = {
    "펫": {1000},
    "무기": {200, 500, 1000},      # 무기/방어구는 기존대로 각 임계값에서 초기화
    "방어구": {200, 500, 1000},
}
RPG_GACHA_PITY_LIMIT = RPG_GACHA_PITY_TIERS[0][0]  # 하위호환용 (기존 참조)
RPG_GACHA_PITY_MIN_RARITY = 3
RPG_GACHA_PITY_TYPES = {"펫", "무기", "방어구"}  # 등급이 있는 뽑기에만 천장 적용


def _rpg_pity_tiers_for(gacha_type: str):
    """뽑기 종류별 천장 단계 목록."""
    if gacha_type == "펫":
        return RPG_PET_PITY_TIERS
    return RPG_GACHA_PITY_TIERS


def _rpg_pity_resets(gacha_type: str) -> set:
    """이 종류에서 카운터를 0으로 초기화하는 임계값 집합."""
    return RPG_PITY_RESET_THRESHOLDS.get(gacha_type, {th for th, _ in _rpg_pity_tiers_for(gacha_type)})


def rpg_get_pity(guild_id: int, user_id: int, gacha_type: str) -> int:
    with DB_MUTEX:
        c.execute("SELECT count FROM rpg_gacha_pity WHERE guild_id=? AND user_id=? AND gacha_type=?", (guild_id, user_id, gacha_type))
        row = c.fetchone()
        return row[0] if row else 0


def rpg_set_pity(guild_id: int, user_id: int, gacha_type: str, count: int):
    with DB_MUTEX:
        c.execute(
            "INSERT OR REPLACE INTO rpg_gacha_pity (guild_id, user_id, gacha_type, count) VALUES (?, ?, ?, ?)",
            (guild_id, user_id, gacha_type, count),
        )
        conn.commit()


def rpg_pity_forced_rarity(guild_id: int, user_id: int, gacha_type: str):
    """이번 뽑기가 천장 발동인지 판단합니다.
    (보장 최소등급 or None, 도달한 임계값 or None)을 돌려줍니다.

    - 초기화되는 임계값(무기/방어구의 200/500/1000, 펫의 1000): 누적이 그 값 '이상'이면 발동.
      (초기화되므로 계속 이상이 되는 상황이 생기지 않음)
    - 초기화되지 않는 임계값(펫의 200/500): 누적이 '정확히' 그 값일 때만 발동.
      (초기화 안 하고 계속 누적되므로, 지나친 임계값이 매번 재발동하지 않도록)
    """
    if gacha_type not in RPG_GACHA_PITY_TYPES:
        return None, None
    next_count = rpg_get_pity(guild_id, user_id, gacha_type) + 1
    resets = _rpg_pity_resets(gacha_type)
    forced_rarity = None
    hit_threshold = None
    for threshold, min_rarity in _rpg_pity_tiers_for(gacha_type):
        if threshold in resets:
            reached = next_count >= threshold      # 초기화형: 이상이면 발동
        else:
            reached = next_count == threshold       # 비초기화형: 정확히 도달 시에만
        if reached:
            if forced_rarity is None or min_rarity > forced_rarity:
                forced_rarity = min_rarity
                hit_threshold = threshold
    return forced_rarity, hit_threshold


def rpg_pity_update(guild_id: int, user_id: int, gacha_type: str, hit_threshold):
    """뽑기 결과 반영: 카운터는 매 뽑기마다 +1 누적됩니다.
    단, 초기화 대상 임계값(펫은 1000회만, 무기/방어구는 200/500/1000)에 도달했을 때만 0으로 초기화합니다."""
    if gacha_type not in RPG_GACHA_PITY_TYPES:
        return
    resets = _rpg_pity_resets(gacha_type)
    if hit_threshold is not None and hit_threshold in resets:
        rpg_set_pity(guild_id, user_id, gacha_type, 0)
    else:
        rpg_set_pity(guild_id, user_id, gacha_type, rpg_get_pity(guild_id, user_id, gacha_type) + 1)


def rpg_roll_pet_min_rarity(min_rarity: int) -> tuple:
    """천장 발동용: 지정 등급 이상에서만 펫을 뽑습니다. (확률은 해당 구간 내에서 재정규화)"""
    eligible = [e for e in RPG_PET_POOL if e["rarity_index"] >= min_rarity] or [RPG_PET_POOL[-1]]
    total = sum(rpg_pet_tier_weight(e) for e in eligible)
    roll = random.uniform(0, total)
    cumulative = 0.0
    for entry in eligible:
        cumulative += rpg_pet_tier_weight(entry)
        if roll <= cumulative:
            return random.choice(entry["pets"]), entry["rarity_index"], entry["power_bonus"]
    last = eligible[-1]
    return random.choice(last["pets"]), last["rarity_index"], last["power_bonus"]


def rpg_roll_pet_shifted(rarity_shift: float) -> tuple:
    """이벤트/부스트 보너스가 있을 때 상위등급 확률을 rarity_shift만큼 끌어올려 펫을 뽑습니다."""
    if rarity_shift <= 0:
        return rpg_roll_pet()
    # 하위 등급 확률의 일부를 상위 등급으로 이동 (단, ??? 사신수는 이벤트로도 확률을 올리지 않음)
    weights = [rpg_pet_tier_weight(e) for e in RPG_PET_POOL]
    shift_amount = min(weights[0] * 0.9, rarity_shift)  # 최하위에서 덜어냄
    # ???(마지막)은 제외하고 그 바로 아래(신)로 몰아줌
    boost_target = len(weights) - 2 if len(weights) >= 2 else 0
    if len(weights) >= 2:
        weights[0] -= shift_amount
        weights[boost_target] += shift_amount
    total = sum(weights)
    roll = random.uniform(0, total)
    cumulative = 0.0
    for entry, w in zip(RPG_PET_POOL, weights):
        cumulative += w
        if roll <= cumulative:
            return random.choice(entry["pets"]), entry["rarity_index"], entry["power_bonus"]
    last = RPG_PET_POOL[-1]
    return random.choice(last["pets"]), last["rarity_index"], last["power_bonus"]


def rpg_roll_equip_gacha(min_rarity: int = 0, rarity_shift: float = 0.0) -> tuple:
    """무기/방어구 뽑기: (희귀도 인덱스, 강화 수치)를 확률로 결정합니다.
    min_rarity를 주면(천장) 그 등급 이상에서만 재정규화. rarity_shift(이벤트/부스트)는 상위등급 확률을 끌어올립니다.
    ??? 사신수 등급은 이벤트/부스트/천장으로 확률이 오르지 않고 순수 운으로만 나옵니다."""
    weights = list(RPG_EQUIP_GACHA_RATES)
    if rarity_shift > 0 and min_rarity == 0:
        shift_amount = min(weights[0] * 0.9, rarity_shift)
        weights[0] -= shift_amount
        # ???(마지막)은 제외하고 그 바로 아래(신)로 몰아줌
        boost_target = len(weights) - 2 if len(weights) >= 2 else 0
        weights[boost_target] += shift_amount
    rates = list(enumerate(weights))
    if min_rarity > 0:
        # 천장 보장은 ??? 바로 아래(신)까지만 — ???는 확정 대상에서 제외
        cap = RPG_SASIN_RARITY_INDEX - 1
        rates = [(i, r) for i, r in rates if min_rarity <= i <= cap] or [(cap, weights[cap])]
    total = sum(r for _i, r in rates)
    roll = random.uniform(0, total)
    cumulative = 0.0
    rarity_index = rates[-1][0]
    for idx, rate in rates:
        cumulative += rate
        if roll <= cumulative:
            rarity_index = idx
            break
    level = random.randint(*RPG_EQUIP_GACHA_LEVEL_RANGE)
    if rarity_index >= RPG_SASIN_RARITY_INDEX:
        level = random.randint(35, RPG_MAX_EQUIP_LEVEL)  # ??? 사신수 장비는 높은 강화수치로 등장 (초레어 보호)
    return rarity_index, level


def rpg_equip_score(kind: str, rarity_index: int, level: int) -> float:
    """장비 비교용 점수입니다. 뽑은 장비가 현재 장비보다 좋은지 판단할 때 씁니다."""
    mult = rpg_rarity_tier(rarity_index)["multiplier"]
    if kind == "weapon":
        return (10 + level * 8) * mult
    return (level * 3) * mult


def rpg_gacha_pet_once(guild_id: int, user_id: int, rarity_shift: float = 0.0, detail_out: list = None) -> str:
    forced_rarity, hit_threshold = rpg_pity_forced_rarity(guild_id, user_id, "펫")
    if forced_rarity is not None:
        pet_name, rarity_index, power_bonus = rpg_roll_pet_min_rarity(forced_rarity)
    else:
        pet_name, rarity_index, power_bonus = rpg_roll_pet_shifted(rarity_shift)
    rpg_pity_update(guild_id, user_id, "펫", hit_threshold)
    already_owned = rpg_owns_pet(guild_id, user_id, pet_name)
    rpg_add_pet(guild_id, user_id, pet_name, rarity_index)
    tier = rpg_rarity_tier(rarity_index)
    dup = " (중복)" if already_owned else " ✨NEW!"
    pity_text = f" 🎯{hit_threshold}회 천장!" if hit_threshold else ""
    # 화려한 연출을 위해 상세 정보를 detail_out에 담아둠 (최고 등급 감지용)
    if detail_out is not None:
        detail_out.append({
            "pet_name": pet_name, "rarity_index": rarity_index, "power_bonus": power_bonus,
            "already_owned": already_owned, "pity": hit_threshold, "tier": tier,
        })
    return f"{tier['emoji']} **{pet_name}** · {tier['name']} · 전투력 +{power_bonus}{dup}{pity_text}"


def rpg_gacha_relic_once(guild_id: int, user_id: int, rarity_shift: float = 0.0) -> str:
    piece = rpg_roll_relic()
    _p, set_entry = RPG_RELIC_BY_ID[piece["relic_id"]]
    already_owned = rpg_owns_relic(guild_id, user_id, piece["relic_id"])
    rpg_add_relic(guild_id, user_id, piece["relic_id"])
    dup = " (중복)" if already_owned else " ✨NEW!"
    return f"**{piece['name']}** · {set_entry['set_name']} · 전투 +{piece['power']}/방어 +{piece['defense']}{dup}"


def rpg_gacha_equip_once(guild_id: int, user_id: int, player: dict, kind: str, rarity_shift: float = 0.0) -> str:
    """무기/방어구 뽑기 1회. 현재 장비보다 좋으면 자동 교체, 아니면 강화석으로 분해합니다.
    player dict를 직접 갱신하므로 연뽑에서도 최신 장비와 비교됩니다."""
    gacha_type = "무기" if kind == "weapon" else "방어구"
    forced_rarity, hit_threshold = rpg_pity_forced_rarity(guild_id, user_id, gacha_type)
    rarity_index, level = rpg_roll_equip_gacha(forced_rarity or 0, rarity_shift)
    rpg_pity_update(guild_id, user_id, gacha_type, hit_threshold)
    tier = rpg_rarity_tier(rarity_index)
    name = rpg_equip_name(kind, level, rarity_index)
    rarity_field = "weapon_rarity" if kind == "weapon" else "armor_rarity"
    level_field = "weapon_level" if kind == "weapon" else "armor_level"
    new_score = rpg_equip_score(kind, rarity_index, level)
    cur_score = rpg_equip_score(kind, player[rarity_field], player[level_field])
    pity_text = f" 🎯{hit_threshold}회 천장!" if hit_threshold else ""
    if new_score > cur_score:
        player[rarity_field] = rarity_index
        player[level_field] = level
        save_rpg_player(guild_id, user_id, **{rarity_field: rarity_index, level_field: level})
        return f"{tier['emoji']} **{name} +{level}** ({tier['name']}) → 🎉 **장착!** (기존보다 강함){pity_text}"
    stone = "강화석" if kind == "weapon" else "방어구강화석"
    add_inventory_item(user_id, stone, 1, guild_id=guild_id)
    return f"{tier['emoji']} {name} +{level} ({tier['name']}) → 기존보다 약해서 **{stone} 1개**로 분해{pity_text}"


def rpg_build_legendary_pet_embed(interaction, detail: dict) -> discord.Embed:
    """최고 등급 펫 획득 시 화려한 축하 연출 임베드. 등록된 펫 이미지를 크게 표시."""
    pet_name = detail["pet_name"]
    tier = detail["tier"]
    rarity_index = detail["rarity_index"]
    # 등급별 연출 강도
    if rarity_index >= 6:      # ??? 사신수
        color = discord.Color.from_rgb(255, 215, 0)  # 골드
        banner = "🐲✨🎊  **사 신 수  강 림!**  🎊✨🐲"
        flair = "🌟🐉🔥🐅🐢🌈🐉🌟"
        hype = f"전설을 넘어선 존재, **{pet_name}**이(가) 당신의 곁에 나타났습니다!\n서버가 뒤흔들리는 순간이에요!"
    elif rarity_index == 5:    # 신
        color = discord.Color.from_rgb(255, 235, 59)
        banner = "⭐✨  **신 급  펫  획 득!**  ✨⭐"
        flair = "🌟⭐✨⭐🌟"
        hype = f"신의 반열에 오른 **{pet_name}**을(를) 얻었어요! 엄청난 행운이에요!"
    else:                      # 신화
        color = discord.Color.from_rgb(244, 67, 54)
        banner = "🔴✨  **신 화  펫  획 득!**  ✨🔴"
        flair = "🔥✨🔥✨🔥"
        hype = f"신화 등급 **{pet_name}**을(를) 획득했어요! 축하합니다!"

    owned_text = " (중복)" if detail["already_owned"] else " ✨ NEW!"
    embed = discord.Embed(
        title=banner,
        description=(
            f"{flair}\n\n"
            f"{tier['emoji']} **{pet_name}**{owned_text}\n"
            f"등급: **{tier['name']}** · 전투력 +{detail['power_bonus']}\n\n"
            f"{hype}\n\n{flair}"
        ),
        color=color,
    )
    # 관리자가 등록한 펫 이미지를 크게 표시 (없으면 표시 안 됨)
    rpg_apply_image(embed, "pet", pet_name, thumbnail=False)
    if detail.get("pity"):
        embed.add_field(name="🎯 천장 달성", value=f"{detail['pity']}회 천장으로 확정 획득!", inline=False)
    embed.add_field(name="🎒 장착", value="`/rpg 펫장착`으로 바로 장착해 강력한 버프를 받으세요!", inline=False)
    embed.set_footer(text=f"{interaction.user.display_name} 님의 위대한 순간 | 만능 봇 RPG")
    return embed


def rpg_build_gacha_panel_embed(guild_id: int, user_id: int, selected: str, guild=None) -> discord.Embed:
    """뽑기 패널 임베드: 보유 뽑기권과 종류별 천장 현황을 보여줍니다."""
    emoji_map = {"펫": "🐾", "무기": "🗡️", "방어구": "🛡️", "유물": "🧿"}
    lines = []
    for gtype, ticket in RPG_GACHA_TICKETS.items():
        have = get_inventory_amount(user_id, ticket)
        cursor = "▶ " if gtype == selected else "　"
        pity_text = ""
        if gtype in RPG_GACHA_PITY_TYPES:
            pity_now = rpg_get_pity(guild_id, user_id, gtype)
            cap = 1000 if gtype == "펫" else 200
            pity_text = f" · 🎯 {pity_now}/{cap}회"
        lines.append(f"{cursor}{emoji_map[gtype]} **{gtype}** · {ticket} {have}개{pity_text}")
    desc = (
        "\n".join(lines)
        + "\n\n메뉴에서 **종류**를 고르고 아래 버튼으로 뽑아요!\n"
        "🎯 천장 — 🐾**펫**: 200전설/500신화/1000신 (1000회 달성 시에만 초기화)\n"
        "🗡️🛡️**무기/방어구**: 200회 전설+ · 500회 신화+ · 1000회 신 확정"
    )
    shift = rpg_gacha_rarity_shift(guild, guild_id) if guild else 0.0
    if shift > 0:
        desc += "\n🍀 **확률 UP 진행 중!** (이벤트/서버부스트로 상위등급 확률 증가)"
    # 뽑기 레벨 현황
    total_pulls = rpg_get_gacha_total(guild_id, user_id)
    cur_level = rpg_gacha_level_for_count(total_pulls)
    next_th, remain = rpg_gacha_next_threshold(total_pulls)
    lvl_bonus = (cur_level - 1) * RPG_GACHA_LEVEL_SHIFT_PER * 100
    if next_th:
        desc += f"\n\n🎲 **뽑기 레벨 Lv.{cur_level}** · 누적 {total_pulls:,}회 · 상위등급 +{lvl_bonus:.0f}% (다음 레벨까지 {remain}회)"
    else:
        desc += f"\n\n🎲 **뽑기 레벨 Lv.{cur_level}** (최고!) · 누적 {total_pulls:,}회 · 상위등급 +{lvl_bonus:.0f}%"
    embed = discord.Embed(title="🎰 뽑기 패널", description=desc, color=discord.Color.magenta())
    embed.set_footer(text="뽑기권은 /rpg 상점 에서 구매할 수 있어요 | 만능 봇 RPG 뽑기")
    return embed


class RPGGachaTypeSelect(discord.ui.Select):
    def __init__(self, selected: str):
        emoji_map = {"펫": "🐾", "무기": "🗡️", "방어구": "🛡️", "유물": "🧿"}
        options = [
            discord.SelectOption(label=f"{gtype} ({ticket})", value=gtype, emoji=emoji_map[gtype], default=(gtype == selected))
            for gtype, ticket in RPG_GACHA_TICKETS.items()
        ]
        super().__init__(placeholder="뽑을 종류를 선택하세요", min_values=1, max_values=1, options=options, row=0)

    async def callback(self, interaction: discord.Interaction):
        view = self.view
        view.selected = self.values[0]
        view.refresh_items()
        embed = rpg_build_gacha_panel_embed(view.guild_id, view.user_id, view.selected, interaction.guild)
        await interaction.response.edit_message(embed=embed, view=view)


class RPGGachaRollButton(discord.ui.Button):
    def __init__(self, count: int):
        label = "1회 뽑기" if count == 1 else f"{count}연뽑"
        super().__init__(label=label, emoji="🎰", style=discord.ButtonStyle.success if count == 10 else discord.ButtonStyle.primary, row=1)
        self.count = count

    async def callback(self, interaction: discord.Interaction):
        view = self.view
        await rpg_group_gacha.callback(
            interaction,
            app_commands.Choice(name=view.selected, value=view.selected),
            app_commands.Choice(name=str(self.count), value=self.count),
        )


RPG_AUTO_GACHA_SAFETY_CAP = 100  # 자동 뽑기 1회 실행당 최대 시도 횟수 (뽑기권 폭주 방지)


class RPGGachaAutoSelect(discord.ui.Select):
    """자동 뽑기 목표 등급을 고르는 메뉴 (선택 시 자동 리롤 ON)."""

    def __init__(self, target_index):
        options = [discord.SelectOption(label="자동 뽑기 OFF", value="off", emoji="⏹️", default=(target_index is None))]
        for idx in range(1, len(RPG_RARITY_TIERS)):  # 희귀~신 (일반은 목표로 부적합)
            tier = RPG_RARITY_TIERS[idx]
            options.append(discord.SelectOption(
                label=f"{tier['name']} 나올 때까지",
                value=str(idx), emoji=tier["emoji"], default=(target_index == idx),
            ))
        super().__init__(placeholder="🎯 목표 등급 자동 뽑기 (펫/무기/방어구)", min_values=1, max_values=1, options=options, row=2)

    async def callback(self, interaction: discord.Interaction):
        view: RPGGachaPanelView = self.view
        if self.values[0] == "off":
            view.auto_target = None
            view.refresh_items()
            embed = rpg_build_gacha_panel_embed(view.guild_id, view.user_id, view.selected, interaction.guild)
            embed.add_field(name="🎯 자동 뽑기", value="OFF 상태예요.", inline=False)
            return await interaction.response.edit_message(embed=embed, view=view)
        view.auto_target = int(self.values[0])
        await view.run_auto(interaction)


class RPGGachaPanelView(discord.ui.View):
    """뽑기 패널: 종류를 고르고 1회/5연/10연 버튼으로 바로 뽑습니다. 목표 등급 자동 뽑기도 지원."""

    def __init__(self, guild_id: int, user_id: int):
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.user_id = user_id
        self.selected = "펫"
        self.auto_target = None
        self.refresh_items()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("❌ 이 뽑기 패널은 다른 사람이 연 거예요. `/rpg 뽑기`로 본인 패널을 열어주세요.", ephemeral=True)
            return False
        return True

    def refresh_items(self):
        self.clear_items()
        self.add_item(RPGGachaTypeSelect(self.selected))
        for count in (1, 5, 10):
            self.add_item(RPGGachaRollButton(count))
        if self.selected in RPG_GACHA_PITY_TYPES:  # 유물은 등급 개념이 없어 자동 뽑기 제외
            self.add_item(RPGGachaAutoSelect(self.auto_target))

    async def run_auto(self, interaction: discord.Interaction):
        """목표 등급이 나올 때까지 자동으로 뽑습니다. (뽑기권 소진/안전상한 도달 시 정지)"""
        gtype = self.selected
        target = self.auto_target
        ticket = RPG_GACHA_TICKETS[gtype]
        rarity_shift = rpg_gacha_rarity_shift(interaction.guild, self.guild_id)
        rarity_shift += rpg_gacha_level_shift(self.guild_id, self.user_id)  # 뽑기 레벨 보너스
        player = get_or_create_rpg_player(self.guild_id, self.user_id)

        attempts = 0
        got = False
        best_rarity = -1
        used = 0
        while attempts < RPG_AUTO_GACHA_SAFETY_CAP:
            if get_inventory_amount(self.user_id, ticket) < 1:
                break
            consume_inventory_item(self.user_id, ticket, 1)
            used += 1
            attempts += 1
            # 등급만 필요하므로 결과 문자열 대신 등급을 직접 계산
            if gtype == "펫":
                forced_rarity, hit = rpg_pity_forced_rarity(self.guild_id, self.user_id, "펫")
                if forced_rarity is not None:
                    name, ri, pb = rpg_roll_pet_min_rarity(forced_rarity)
                else:
                    name, ri, pb = rpg_roll_pet_shifted(rarity_shift)
                rpg_pity_update(self.guild_id, self.user_id, "펫", hit)
                rpg_add_pet(self.guild_id, self.user_id, name, ri)
            else:
                kind = "weapon" if gtype == "무기" else "armor"
                forced_rarity, hit = rpg_pity_forced_rarity(self.guild_id, self.user_id, gtype)
                ri, level = rpg_roll_equip_gacha(forced_rarity or 0, rarity_shift)
                rpg_pity_update(self.guild_id, self.user_id, gtype, hit)
                rarity_field = "weapon_rarity" if kind == "weapon" else "armor_rarity"
                level_field = "weapon_level" if kind == "weapon" else "armor_level"
                if rpg_equip_score(kind, ri, level) > rpg_equip_score(kind, player[rarity_field], player[level_field]):
                    player[rarity_field] = ri
                    player[level_field] = level
                    save_rpg_player(self.guild_id, self.user_id, **{rarity_field: ri, level_field: level})
                else:
                    stone = "강화석" if kind == "weapon" else "방어구강화석"
                    add_inventory_item(self.user_id, stone, 1, guild_id=self.guild_id)
            best_rarity = max(best_rarity, ri)
            if ri >= target:
                got = True
                break

        self.auto_target = None
        self.refresh_items()
        # 뽑기 레벨 누적 (자동뽑기에서 사용한 횟수만큼)
        auto_level_ups = rpg_gacha_add_pulls(self.guild_id, self.user_id, used) if used else []
        tier = rpg_rarity_tier(target)
        best_tier = rpg_rarity_tier(best_rarity) if best_rarity >= 0 else None
        if got:
            result = f"🎉 **{tier['emoji']} {tier['name']}** 등급 획득! (총 {used}회 뽑음)"
        elif get_inventory_amount(self.user_id, ticket) < 1:
            result = f"🛑 뽑기권이 떨어져서 멈췄어요. ({used}회 뽑음, 최고 {best_tier['emoji']}{best_tier['name']})\n`/rpg 상점`에서 {ticket}을 더 사보세요."
        else:
            result = f"🛑 안전상한 {RPG_AUTO_GACHA_SAFETY_CAP}회에 도달해 멈췄어요. ({best_tier['emoji']}{best_tier['name']}까지 나옴) 다시 눌러 계속할 수 있어요."
        embed = rpg_build_gacha_panel_embed(self.guild_id, self.user_id, self.selected, interaction.guild)
        embed.add_field(name=f"🎯 자동 뽑기 결과 (목표: {tier['emoji']}{tier['name']})", value=result, inline=False)
        if auto_level_ups:
            up_lines = [f"🎉 **뽑기 Lv.{lv}** 달성! 보상: {pt:,}P + {iname} {iamt}개" for lv, (pt, iname, iamt) in auto_level_ups]
            embed.add_field(name="🆙 뽑기 레벨 업!", value="\n".join(up_lines), inline=False)
        await interaction.response.edit_message(embed=embed, view=self)


@rpg_group.command(name="뽑기", description="뽑기 패널을 엽니다. 종류를 고르고 1회/5연/10연 버튼으로 바로 뽑아요! (200회 천장)")
@app_commands.describe(종류="바로 뽑고 싶다면 종류를 지정하세요. 비워두면 패널이 열려요.", 횟수="1회 / 5연뽑 / 10연뽑")
@app_commands.choices(
    종류=[
        app_commands.Choice(name="🐾 펫 (소환권)", value="펫"),
        app_commands.Choice(name="🗡️ 무기 (무기뽑기권)", value="무기"),
        app_commands.Choice(name="🛡️ 방어구 (방어구뽑기권)", value="방어구"),
        app_commands.Choice(name="🧿 유물 (유물함)", value="유물"),
    ],
    횟수=[
        app_commands.Choice(name="1회", value=1),
        app_commands.Choice(name="🎰 5연뽑", value=5),
        app_commands.Choice(name="🎰 10연뽑", value=10),
    ],
)
async def rpg_group_gacha(interaction: discord.Interaction, 종류: app_commands.Choice[str] = None, 횟수: app_commands.Choice[int] = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    # 종류 미지정 → 뽑기 패널 열기
    if 종류 is None:
        view = RPGGachaPanelView(interaction.guild.id, interaction.user.id)
        embed = rpg_build_gacha_panel_embed(interaction.guild.id, interaction.user.id, view.selected, interaction.guild)
        return await safe_interaction_send(interaction, embed=embed, view=view, ephemeral=True)
    feature = "펫뽑기" if 종류.value == "펫" else ("유물" if 종류.value == "유물" else "뽑기")
    if not await rpg_check_feature_channel(interaction, feature):
        return
    guild_id = interaction.guild.id
    user_id = interaction.user.id
    count = 횟수.value if 횟수 is not None else 1
    ticket = RPG_GACHA_TICKETS[종류.value]

    if get_inventory_amount(user_id, ticket) < count:
        have = get_inventory_amount(user_id, ticket)
        return await safe_interaction_send(
            interaction,
            f"❌ **{ticket}**이(가) {count}개 필요해요. (보유: {have}개)\n`/rpg 상점`에서 구매할 수 있어요.",
            ephemeral=True,
        )
    consume_inventory_item(user_id, ticket, count)

    rarity_shift = rpg_gacha_rarity_shift(interaction.guild, guild_id)  # 이벤트/부스트 상위등급 보너스
    rarity_shift += rpg_gacha_level_shift(guild_id, user_id)            # 뽑기 레벨 상위등급 보너스
    player = get_or_create_rpg_player(guild_id, user_id)
    lines = []
    pet_details = []  # 화려한 연출용 상세 정보 (펫만)
    for i in range(count):
        if 종류.value == "펫":
            lines.append(rpg_gacha_pet_once(guild_id, user_id, rarity_shift, detail_out=pet_details))
        elif 종류.value == "유물":
            lines.append(rpg_gacha_relic_once(guild_id, user_id, rarity_shift))
        elif 종류.value == "무기":
            lines.append(rpg_gacha_equip_once(guild_id, user_id, player, "weapon", rarity_shift))
        else:
            lines.append(rpg_gacha_equip_once(guild_id, user_id, player, "armor", rarity_shift))

    # 뽑기 레벨 누적 (모든 뽑기 합산) — 레벨업 시 보상 지급
    gacha_level_ups = rpg_gacha_add_pulls(guild_id, user_id, count)

    type_emoji = {"펫": "🐾", "무기": "🗡️", "방어구": "🛡️", "유물": "🧿"}[종류.value]
    count_label = {1: "뽑기", 5: "5연뽑", 10: "10연뽑"}.get(count, f"{count}연뽑")
    title = f"{type_emoji} {종류.value} {count_label} 결과!"
    numbered = "\n".join(f"`{i+1:>2}.` {line}" for i, line in enumerate(lines)) if count > 1 else lines[0]
    embed = discord.Embed(title=title, description=numbered[:4096], color=discord.Color.magenta())
    embed.set_thumbnail(url=interaction.user.display_avatar.url)
    if rarity_shift > 0:
        boost_src = []
        if rpg_get_event(guild_id).get("gacha", 1.0) > 1.0:
            boost_src.append("이벤트")
        if rpg_guild_boosted(interaction.guild):
            boost_src.append("서버부스트")
        embed.add_field(name="🍀 확률 UP!", value=f"{'·'.join(boost_src)}로 상위등급 확률이 올라간 상태예요!", inline=False)
    if 종류.value == "펫":
        embed.add_field(name="🎒 장착", value="`/rpg 펫장착 이름:…` 으로 장착할 수 있어요.", inline=False)
    elif 종류.value == "유물":
        embed.add_field(name="🎒 장착", value=f"`/rpg 장비` 패널 또는 `/rpg 명령어` → 🧿 유물 장착 메뉴에서 장착할 수 있어요. (최대 {RPG_MAX_RELIC_SLOTS}개, 중첩 가능)", inline=False)
    footer = f"{ticket} {count}개 사용"
    if 종류.value in RPG_GACHA_PITY_TYPES:
        pity_now = rpg_get_pity(guild_id, user_id, 종류.value)
        if 종류.value == "펫":
            footer += f" · 🎯 천장 {pity_now}/1000회 (200전설/500신화/1000신, 1000회만 초기화)"
        else:
            footer += f" · 🎯 천장 {pity_now}회 (200전설/500신화/1000신 확정)"

    # 뽑기 레벨 현황 + 레벨업 알림
    total_pulls = rpg_get_gacha_total(guild_id, user_id)
    cur_level = rpg_gacha_level_for_count(total_pulls)
    next_th, remain = rpg_gacha_next_threshold(total_pulls)
    if gacha_level_ups:
        up_lines = []
        for lv, (pt, iname, iamt) in gacha_level_ups:
            up_lines.append(f"🎉 **뽑기 Lv.{lv}** 달성! 보상: {pt:,}P + {iname} {iamt}개")
        embed.add_field(name="🆙 뽑기 레벨 업!", value="\n".join(up_lines), inline=False)
    level_info = f"🎲 뽑기 레벨 **Lv.{cur_level}** · 누적 {total_pulls:,}회 · 상위등급 확률 +{(cur_level-1)*RPG_GACHA_LEVEL_SHIFT_PER*100:.0f}%"
    if next_th:
        level_info += f"\n다음 레벨까지 **{remain}회** (누적 {next_th:,}회)"
    else:
        level_info += "\n🏆 최고 뽑기 레벨 달성!"
    embed.add_field(name="🎲 뽑기 레벨", value=level_info, inline=False)
    embed.set_footer(text=f"{footer} | 만능 봇 RPG 뽑기")
    await safe_interaction_send(interaction, embed=embed)

    # 🐲 화려한 연출: 신화(5)/신(5)/사신수(6) 등 최고 등급 펫이 나오면 별도 축하 임베드 전송
    if 종류.value == "펫" and pet_details:
        legendary = [d for d in pet_details if d["rarity_index"] >= 4]  # 신화 이상
        # 가장 높은 등급 하나만 대표로 화려하게 연출 (여러 개면 최고 등급)
        if legendary:
            best = max(legendary, key=lambda d: d["rarity_index"])
            try:
                flashy = rpg_build_legendary_pet_embed(interaction, best)
                await safe_interaction_send(interaction, embed=flashy)
            except Exception:
                pass


def rpg_normalize_name(text: str) -> str:
    """이모지·공백을 제거해 이름 매칭에 쓰는 정규화 함수. (예: '🔥 화염 반지' → '화염반지')"""
    if not text:
        return ""
    cleaned = "".join(ch for ch in text if ch.isalnum())
    return cleaned.lower()


def rpg_match_pet_name(guild_id: int, user_id: int, query: str):
    """이모지 없이 입력해도 보유 펫과 매칭합니다. 매칭된 정식 이름 or None."""
    norm = rpg_normalize_name(query)
    for pet_name, _ri, _cnt in rpg_get_pets(guild_id, user_id):
        if rpg_normalize_name(pet_name) == norm or norm in rpg_normalize_name(pet_name):
            return pet_name
    return None


def rpg_match_relic_name(query: str):
    """이모지 없이 입력해도 유물과 매칭합니다. relic_id or None."""
    norm = rpg_normalize_name(query)
    for rid, (piece, _s) in RPG_RELIC_BY_ID.items():
        if rpg_normalize_name(piece["name"]) == norm or norm in rpg_normalize_name(piece["name"]):
            return rid
    return None


