RPG_CHANNEL_FEATURES = ["사냥", "보스", "강화", "속성부여", "펫뽑기", "뽑기", "유물", "랭킹", "대결", "레이드", "던전", "월드보스"]


def rpg_get_feature_channel(guild_id: int, feature: str):
    with DB_MUTEX:
        c.execute("SELECT channel_id FROM rpg_channels WHERE guild_id=? AND feature=?", (guild_id, feature))
        row = c.fetchone()
        return row[0] if row else None


async def rpg_check_feature_channel(interaction: discord.Interaction, feature: str) -> bool:
    """해당 기능에 전용 채널이 설정돼 있으면 그 채널에서만 사용 가능하게 합니다.
    사용할 수 없으면 안내 메시지를 보내고 False를 돌려줍니다."""
    if interaction.guild is None:
        return True
    channel_id = rpg_get_feature_channel(interaction.guild.id, feature)
    if channel_id and interaction.channel_id != channel_id:
        await safe_interaction_send(
            interaction,
            f"📍 **{feature}** 기능은 <#{channel_id}> 채널에서만 사용할 수 있어요!",
            ephemeral=True,
        )
        return False
    return True


@rpg_group.command(name="채널설정", description="RPG 기능별 전용 채널을 확인하거나 설정합니다. (설정은 관리자만)")
@app_commands.describe(기능="전용 채널을 지정할 RPG 기능 (비워두면 현재 설정 현황을 확인해요)", 채널="전용 채널 (비워두면 설정 해제)")
@app_commands.choices(기능=[app_commands.Choice(name=f, value=f) for f in RPG_CHANNEL_FEATURES])
async def rpg_group_channel_config(interaction: discord.Interaction, 기능: app_commands.Choice[str] = None, 채널: discord.TextChannel = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    # 조회 모드: 기능을 지정하지 않으면 누구나 현황 확인 가능
    if 기능 is None:
        lines = []
        for feature in RPG_CHANNEL_FEATURES:
            channel_id = rpg_get_feature_channel(interaction.guild.id, feature)
            lines.append(f"**{feature}**: " + (f"<#{channel_id}>" if channel_id else "제한 없음"))
        embed = discord.Embed(title="📍 RPG 기능별 전용 채널", description="\n".join(lines), color=discord.Color.dark_teal())
        embed.set_footer(text="관리자는 /rpg 채널설정 기능:… 채널:… 으로 변경할 수 있어요 | 만능 봇 RPG")
        return await safe_interaction_send(interaction, embed=embed, ephemeral=True)

    # 설정 모드: 관리자 전용
    if not interaction.user.guild_permissions.administrator:
        return await safe_interaction_send(interaction, "❌ 채널 설정 변경은 관리자만 할 수 있어요.", ephemeral=True)

    with DB_MUTEX:
        if 채널 is None:
            c.execute("DELETE FROM rpg_channels WHERE guild_id=? AND feature=?", (interaction.guild.id, 기능.value))
        else:
            c.execute(
                "INSERT OR REPLACE INTO rpg_channels (guild_id, feature, channel_id) VALUES (?, ?, ?)",
                (interaction.guild.id, 기능.value, 채널.id),
            )
        conn.commit()

    if 채널 is None:
        await safe_interaction_send(interaction, f"✅ **{기능.value}** 기능의 전용 채널 설정을 해제했어요. 이제 아무 채널에서나 사용 가능해요.", ephemeral=True)
    else:
        await safe_interaction_send(interaction, f"✅ **{기능.value}** 기능은 이제 {채널.mention} 채널에서만 사용할 수 있어요!", ephemeral=True)


