@birthday_group.command(name="보상설정", description="생일 자동 축하 시 지급할 포인트/역할 보상을 설정합니다. (관리자)")
@app_commands.describe(
    자동보상="생일 자동 축하 시 포인트/역할을 지급할지 여부",
    포인트="생일 당사자에게 지급할 포인트 (0이면 미지급)",
    역할이름="생일 하루 동안 붙여줄 역할 이름 (비우면 그대로 유지, '없음' 입력 시 역할 미사용)",
    다음날회수="생일 다음 날 역할을 자동으로 회수할지 여부",
    축하dm="생일 당사자에게 축하 DM을 보낼지 여부",
)
async def birthday_group_reward_config(
    interaction: discord.Interaction,
    자동보상: bool = None,
    포인트: int = None,
    역할이름: str = None,
    다음날회수: bool = None,
    축하dm: bool = None,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)

    fields = {}
    if 자동보상 is not None:
        fields["enabled"] = 1 if 자동보상 else 0
    if 포인트 is not None:
        fields["reward_point"] = max(int(포인트), 0)
    if 역할이름 is not None:
        cleaned = 역할이름.strip()
        # '없음/off/-' 입력 시 역할 기능을 끕니다.
        fields["role_name"] = "" if cleaned.lower() in ("없음", "off", "-", "x") else cleaned
    if 다음날회수 is not None:
        fields["remove_next_day"] = 1 if 다음날회수 else 0
    if 축하dm is not None:
        fields["dm_enabled"] = 1 if 축하dm else 0

    settings = update_birthday_reward_settings(interaction.guild.id, **fields)

    role_display = settings["role_name"] if settings["role_name"] else "사용 안 함"
    embed = discord.Embed(
        title="🎂 생일 자동 보상 설정",
        description="생일 자동 축하(매일 오전 9시 KST)와 함께 지급되는 보상 설정이에요.",
        color=0x87CEEB,
    )
    embed.add_field(name="자동 보상", value="✅ 켜짐" if settings["enabled"] else "⛔ 꺼짐", inline=True)
    embed.add_field(name="지급 포인트", value=f"{int(settings['reward_point']):,} P", inline=True)
    embed.add_field(name="생일 역할", value=role_display, inline=True)
    embed.add_field(name="다음 날 역할 회수", value="✅ 켜짐" if settings["remove_next_day"] else "⛔ 꺼짐", inline=True)
    embed.add_field(name="축하 DM", value="✅ 켜짐" if settings["dm_enabled"] else "⛔ 꺼짐", inline=True)
    embed.set_footer(text="만능 봇 | 생일 보상 설정")
    await interaction.followup.send(embed=embed, ephemeral=True)


