@community_group.command(name="매칭", description="랜덤 매칭 대기열에 참여합니다. 인원이 모이면 짝꿍/소그룹으로 묶어드려요.")
async def community_group_match(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    guild_id = interaction.guild.id
    user_id = interaction.user.id
    settings = get_community_settings(guild_id)
    group_size = settings["match_group_size"]

    # 대기열 등록 (이미 있으면 안내)
    c.execute("SELECT 1 FROM community_match_queue WHERE guild_id=? AND user_id=?", (guild_id, user_id))
    already = c.fetchone()
    if not already:
        c.execute(
            "INSERT OR IGNORE INTO community_match_queue(guild_id, user_id, joined_at) VALUES (?, ?, ?)",
            (guild_id, user_id, datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
        )
        conn.commit()

    # 현재 대기 인원 확인 (탈퇴/부재 멤버는 정리)
    c.execute("SELECT user_id FROM community_match_queue WHERE guild_id=? ORDER BY joined_at ASC", (guild_id,))
    waiting_ids = []
    for (uid,) in c.fetchall():
        if interaction.guild.get_member(int(uid)) is not None:
            waiting_ids.append(int(uid))
        else:
            c.execute("DELETE FROM community_match_queue WHERE guild_id=? AND user_id=?", (guild_id, int(uid)))
    conn.commit()

    # 아직 인원이 부족하면 대기 안내
    if len(waiting_ids) < group_size:
        need = group_size - len(waiting_ids)
        embed = discord.Embed(
            title="🤝 랜덤 매칭 대기 중",
            description=(
                f"대기열에 참여했어요! 현재 **{len(waiting_ids)}명** 대기 중이에요.\n"
                f"**{need}명** 더 모이면 자동으로 매칭이 발표돼요.\n\n"
                f"(그룹 크기: {group_size}명 · `/커뮤니티 매칭취소`로 나갈 수 있어요)"
            ),
            color=0xCDB4DB,
        )
        return await interaction.followup.send(embed=embed, ephemeral=True)

    # 인원이 모였으면 그룹으로 묶어 발표
    groups = chunk_members_for_matching(waiting_ids, group_size)

    # 대기열 비우기
    c.execute("DELETE FROM community_match_queue WHERE guild_id=?", (guild_id,))
    conn.commit()

    match_date = today_key()
    result_embed = discord.Embed(
        title="🎉 랜덤 매칭 결과",
        description="새로운 인연을 만나보세요! 각 그룹마다 대화 주제도 함께 드려요. 💬",
        color=0xCDB4DB,
    )
    now_text = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for idx, group in enumerate(groups, start=1):
        mentions = " ".join(f"<@{uid}>" for uid in group)
        topic = random.choice(COMMUNITY_MATCH_TOPICS)
        label = "짝꿍" if len(group) == 2 else f"{len(group)}인 그룹"
        result_embed.add_field(
            name=f"💞 {idx}번 {label}",
            value=f"{mentions}\n🗣️ 오늘의 주제: **{topic}**",
            inline=False,
        )
        c.execute(
            "INSERT INTO community_match_logs(guild_id, match_date, member_ids, topic, created_at) VALUES (?, ?, ?, ?, ?)",
            (guild_id, match_date, ",".join(str(u) for u in group), topic, now_text),
        )
    conn.commit()
    result_embed.set_footer(text="만능 봇 | 랜덤 매칭 · 편하게 인사 나눠봐요!")

    # 매칭 결과는 채널에 공개로 발표 (모두가 볼 수 있게)
    try:
        await interaction.channel.send(embed=result_embed)
        await interaction.followup.send("✅ 인원이 모여서 매칭 결과를 채널에 발표했어요!", ephemeral=True)
    except (discord.Forbidden, discord.HTTPException):
        await interaction.followup.send(embed=result_embed, ephemeral=True)


@community_group.command(name="매칭취소", description="랜덤 매칭 대기열에서 나갑니다.")
async def community_group_match_cancel(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)
    c.execute(
        "DELETE FROM community_match_queue WHERE guild_id=? AND user_id=?",
        (interaction.guild.id, interaction.user.id),
    )
    changed = c.rowcount
    conn.commit()
    await interaction.followup.send(
        "✅ 대기열에서 나왔어요." if changed else "ℹ️ 대기열에 참여한 기록이 없어요.",
        ephemeral=True,
    )


@community_group.command(name="챌린지", description="오늘의 커뮤니티 챌린지를 확인하고 참여 보상을 받습니다.")
async def community_group_challenge(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    guild_id = interaction.guild.id
    user_id = interaction.user.id
    settings = get_community_settings(guild_id)
    challenge_text = pick_daily_challenge(guild_id)
    challenge_date = today_key()

    c.execute(
        "SELECT 1 FROM community_challenge_claims WHERE guild_id=? AND user_id=? AND challenge_date=?",
        (guild_id, user_id, challenge_date),
    )
    already = c.fetchone()

    embed = discord.Embed(
        title="🎯 오늘의 커뮤니티 챌린지",
        description=f"**{challenge_text}**",
        color=0xA0E7A0,
    )

    if already:
        embed.add_field(name="상태", value="✅ 오늘은 이미 참여 보상을 받았어요!", inline=False)
        embed.set_footer(text="만능 봇 | 커뮤니티 챌린지 · 내일 또 만나요!")
        return await interaction.followup.send(embed=embed, ephemeral=True)

    # 참여 보상 지급
    reward_point = int(settings["challenge_reward_point"] or 0)
    reward_box = int(settings["challenge_reward_box"] or 0)
    reward_lines = []
    if reward_point > 0:
        current_point = get_user_point(guild_id, user_id)
        set_user_point(guild_id, user_id, current_point + reward_point)
        reward_lines.append(f"💰 {reward_point:,} 포인트")
    if reward_box > 0:
        try:
            add_inventory_item(user_id, "랜덤박스", reward_box, guild_id=guild_id)
            reward_lines.append(f"🎁 랜덤박스 {reward_box}개")
        except Exception:
            pass

    c.execute(
        "INSERT OR IGNORE INTO community_challenge_claims(guild_id, user_id, challenge_date, claimed_at) VALUES (?, ?, ?, ?)",
        (guild_id, user_id, challenge_date, datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")),
    )
    conn.commit()

    embed.add_field(
        name="🎉 참여 보상 지급 완료",
        value="\n".join(reward_lines) if reward_lines else "오늘 챌린지에 참여했어요!",
        inline=False,
    )
    embed.set_footer(text="만능 봇 | 커뮤니티 챌린지 · 하루 1회 참여 가능")
    await interaction.followup.send(embed=embed, ephemeral=True)


@community_group.command(name="커뮤니티설정", description="랜덤 매칭 그룹 크기, 챌린지 보상, 익명 상자 채널을 설정합니다. (관리자)")
@app_commands.describe(
    매칭그룹크기="한 그룹에 묶을 인원 수 (2 이상, 기본 2=1:1 짝꿍)",
    챌린지포인트="오늘의 챌린지 참여 시 지급할 포인트",
    챌린지박스="오늘의 챌린지 참여 시 지급할 랜덤박스 개수",
    익명상자채널="익명 건의/칭찬이 게시될 채널 (지정 안 하면 명령을 쓴 채널로 전송)",
)
async def community_group_settings(
    interaction: discord.Interaction,
    매칭그룹크기: int = None,
    챌린지포인트: int = None,
    챌린지박스: int = None,
    익명상자채널: discord.TextChannel = None,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)

    fields = {}
    if 매칭그룹크기 is not None:
        fields["match_group_size"] = max(2, int(매칭그룹크기))
    if 챌린지포인트 is not None:
        fields["challenge_reward_point"] = max(0, int(챌린지포인트))
    if 챌린지박스 is not None:
        fields["challenge_reward_box"] = max(0, int(챌린지박스))
    if 익명상자채널 is not None:
        fields["suggestion_channel_id"] = 익명상자채널.id

    settings = update_community_settings(interaction.guild.id, **fields)

    box_channel_id = settings.get("suggestion_channel_id", 0)
    box_channel_text = f"<#{box_channel_id}>" if box_channel_id else "명령 사용 채널"

    embed = discord.Embed(
        title="⚙️ 커뮤니티 기능 설정",
        color=0xCDB4DB,
    )
    embed.add_field(name="매칭 그룹 크기", value=f"{settings['match_group_size']}명", inline=True)
    embed.add_field(name="챌린지 포인트", value=f"{settings['challenge_reward_point']:,} P", inline=True)
    embed.add_field(name="챌린지 랜덤박스", value=f"{settings['challenge_reward_box']}개", inline=True)
    embed.add_field(name="익명 상자 채널", value=box_channel_text, inline=True)
    embed.set_footer(text="만능 봇 | 커뮤니티 설정")
    await interaction.followup.send(embed=embed, ephemeral=True)


