@role_group.command(name="삭제", description="지정한 역할을 서버에서 삭제합니다. (관리자)")
@app_commands.describe(역할="삭제할 역할")
async def ops_group_delete_role(interaction: discord.Interaction, 역할: discord.Role):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if not interaction.user.guild_permissions.manage_roles:
        return await safe_interaction_send(interaction, "❌ 역할 관리 권한이 필요해요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    me = interaction.guild.me
    if 역할.is_default():
        return await interaction.followup.send("❌ @everyone 역할은 삭제할 수 없어요.", ephemeral=True)
    if 역할.managed:
        return await interaction.followup.send("❌ 연동(봇/부스트) 역할은 삭제할 수 없어요.", ephemeral=True)
    if me and 역할 >= me.top_role:
        return await interaction.followup.send("⚠️ 이 역할은 봇 역할보다 높거나 같아서 삭제할 수 없어요.", ephemeral=True)

    role_name = 역할.name
    member_count = len(역할.members)
    try:
        await 역할.delete(reason=f"역할 삭제 by {interaction.user}")
    except (discord.Forbidden, discord.HTTPException):
        return await interaction.followup.send("⚠️ 역할 삭제 중 오류가 났어요.", ephemeral=True)

    log_moderation_action(interaction.guild.id, 0, interaction.user.id, "delete_role", f"{role_name} ({member_count}명)")
    await send_log(interaction.guild, f"🗑️ 역할 삭제\n역할: `{role_name}` ({member_count}명 보유)\n관리자: {interaction.user.mention}", "general")
    await interaction.followup.send(f"🗑️ `{role_name}` 역할을 삭제했어요. ({member_count}명이 보유 중이었어요)", ephemeral=True)


@role_group.command(name="정보", description="역할의 색상·권한·인원 등 상세 정보를 확인합니다.")
@app_commands.describe(역할="조회할 역할")
async def ops_group_role_info(interaction: discord.Interaction, 역할: discord.Role):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    key_perms_map = {
        "administrator": "관리자", "manage_guild": "서버 관리", "manage_roles": "역할 관리",
        "manage_channels": "채널 관리", "manage_messages": "메시지 관리", "kick_members": "추방",
        "ban_members": "밴", "moderate_members": "타임아웃", "mention_everyone": "@everyone 멘션",
    }
    key_perms = [label for attr, label in key_perms_map.items() if getattr(역할.permissions, attr, False)]

    embed = create_embed(f"🎭 역할 정보 · {역할.name}", 역할.mention, 역할.color.value or 0x87CEFA)
    embed.add_field(name="🆔 ID", value=f"`{역할.id}`", inline=True)
    embed.add_field(name="🎨 색상", value=str(역할.color), inline=True)
    embed.add_field(name="👥 인원", value=f"{len(역할.members)}명", inline=True)
    embed.add_field(name="📌 표시 여부", value="따로 표시됨" if 역할.hoist else "일반", inline=True)
    embed.add_field(name="💬 멘션 가능", value="예" if 역할.mentionable else "아니오", inline=True)
    embed.add_field(name="📅 생성일", value=역할.created_at.strftime("%Y-%m-%d"), inline=True)
    embed.add_field(name="🔑 주요 권한", value=", ".join(key_perms) if key_perms else "특별한 관리 권한 없음", inline=False)
    await interaction.followup.send(embed=embed, ephemeral=True)


@ops_group.command(name="채널정보", description="채널의 종류·카테고리·슬로우모드 등 정보를 확인합니다.")
@app_commands.describe(채널="조회할 채널 (비우면 현재 채널)")
async def ops_group_channel_info(interaction: discord.Interaction, 채널: discord.TextChannel = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    ch = 채널 or interaction.channel
    embed = create_embed(f"#️⃣ 채널 정보 · {ch.name}", getattr(ch, "mention", ch.name), 0x87CEFA)
    embed.add_field(name="🆔 ID", value=f"`{ch.id}`", inline=True)
    embed.add_field(name="📂 카테고리", value=ch.category.name if ch.category else "없음", inline=True)
    embed.add_field(name="📅 생성일", value=ch.created_at.strftime("%Y-%m-%d"), inline=True)
    if isinstance(ch, discord.TextChannel):
        embed.add_field(name="🐌 슬로우모드", value=f"{ch.slowmode_delay}초" if ch.slowmode_delay else "없음", inline=True)
        embed.add_field(name="🔞 NSFW", value="예" if ch.is_nsfw() else "아니오", inline=True)
        if ch.topic:
            embed.add_field(name="📝 주제", value=ch.topic[:1024], inline=False)
    await interaction.followup.send(embed=embed, ephemeral=True)


@ops_group.command(name="멤버검색", description="닉네임·이름에 특정 단어가 들어간 멤버를 찾습니다.")
@app_commands.describe(검색어="찾을 단어 (닉네임 또는 유저명 일부)")
async def ops_group_search_members(interaction: discord.Interaction, 검색어: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if not interaction.user.guild_permissions.manage_messages:
        return await safe_interaction_send(interaction, "❌ 메시지 관리 권한이 필요해요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    q = (검색어 or "").strip().lower()
    if len(q) < 1:
        return await interaction.followup.send("❌ 검색어를 입력해주세요.", ephemeral=True)

    matched = [m for m in interaction.guild.members if q in m.name.lower() or q in m.display_name.lower()]
    embed = create_embed("🔍 멤버 검색", f"`{검색어}`가 들어간 멤버 **{len(matched)}명**을 찾았어요.", 0x87CEFA)
    if matched:
        lines = [f"{m.mention} · `{m.name}`" for m in matched[:30]]
        if len(matched) > 30:
            lines.append(f"… 외 {len(matched) - 30}명")
        embed.add_field(name="결과", value="\n".join(lines)[:1024], inline=False)
    else:
        embed.add_field(name="결과", value="일치하는 멤버가 없어요.", inline=False)
    await interaction.followup.send(embed=embed, ephemeral=True)


@ops_group.command(name="닉네임변경", description="특정 멤버의 서버 닉네임을 변경합니다. (관리자)")
@app_commands.describe(유저="닉네임을 바꿀 멤버", 닉네임="새 닉네임 (비우면 초기화)")
async def ops_group_set_nickname(interaction: discord.Interaction, 유저: discord.Member, 닉네임: str = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if not interaction.user.guild_permissions.manage_nicknames:
        return await safe_interaction_send(interaction, "❌ 닉네임 관리 권한이 필요해요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    me = interaction.guild.me
    if me and 유저.top_role >= me.top_role:
        return await interaction.followup.send("⚠️ 이 멤버는 봇 역할보다 높거나 같아서 닉네임을 바꿀 수 없어요.", ephemeral=True)
    new_nick = (닉네임 or "").strip()[:32] or None
    try:
        await 유저.edit(nick=new_nick, reason=f"닉네임 변경 by {interaction.user}")
    except (discord.Forbidden, discord.HTTPException):
        return await interaction.followup.send("⚠️ 닉네임 변경 중 오류가 났어요. 봇 권한을 확인해주세요.", ephemeral=True)

    label = f"`{new_nick}`" if new_nick else "기본값(초기화)"
    await send_log(interaction.guild, f"✏️ 닉네임 변경\n대상: {유저.mention} → {label}\n관리자: {interaction.user.mention}", "general")
    await interaction.followup.send(f"✏️ {유저.mention}님의 닉네임을 {label}(으)로 바꿨어요.", ephemeral=True)


@ops_group.command(name="차단사유", description="차단된 유저의 차단 사유를 유저 ID로 확인합니다. (관리자)")
@app_commands.describe(유저id="확인할 유저의 ID")
async def ops_group_ban_reason(interaction: discord.Interaction, 유저id: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if not interaction.user.guild_permissions.ban_members:
        return await safe_interaction_send(interaction, "❌ 멤버 차단 권한이 필요해요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    raw = (유저id or "").strip()
    if not raw.isdigit():
        return await interaction.followup.send("❌ 유저 ID는 숫자만 입력해주세요.", ephemeral=True)
    try:
        ban_entry = await interaction.guild.fetch_ban(discord.Object(id=int(raw)))
    except discord.NotFound:
        return await interaction.followup.send("❌ 그 ID로 차단된 유저를 찾지 못했어요.", ephemeral=True)
    except (discord.Forbidden, discord.HTTPException):
        return await interaction.followup.send("⚠️ 차단 정보를 확인하는 중 오류가 났어요.", ephemeral=True)

    embed = create_embed("⛔ 차단 사유", f"`{ban_entry.user}` (`{ban_entry.user.id}`)", 0xED4245)
    embed.add_field(name="사유", value=ban_entry.reason or "사유 없음", inline=False)
    await interaction.followup.send(embed=embed, ephemeral=True)


@ops_group.command(name="서버아이콘", description="현재 서버의 아이콘과 배너 이미지를 확인합니다.")
async def ops_group_server_icon(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    guild = interaction.guild
    if not guild.icon and not guild.banner:
        return await interaction.followup.send("이 서버에는 아이콘과 배너가 없어요.", ephemeral=True)

    embed = create_embed("🖼️ 서버 이미지", f"**{guild.name}**의 아이콘/배너예요.", 0x87CEFA)
    if guild.icon:
        embed.set_image(url=guild.icon.url)
        embed.add_field(name="아이콘 링크", value=guild.icon.url, inline=False)
    if guild.banner:
        embed.add_field(name="배너 링크", value=guild.banner.url, inline=False)
    await interaction.followup.send(embed=embed, ephemeral=True)


