# PvP 시즌(2주)을 체크해서, 시즌이 바뀌면 1~5등에게 보상을 주고 전적을 초기화합니다.
@tasks.loop(hours=6)
async def rpg_pvp_season_loop():
    try:
        for guild in list(bot.guilds):
            try:
                payouts = rpg_pvp_season_reset_and_reward(guild.id)
                if payouts is None:
                    continue  # 시즌 변동 없음 또는 첫 등록
                # 시즌 종료 공지 임베드
                medals = ["🥇", "🥈", "🥉", "4️⃣", "5️⃣"]
                if payouts:
                    lines = []
                    for p in payouts:
                        m = medals[p["rank"] - 1] if p["rank"] <= 5 else f"{p['rank']}."
                        lines.append(f"{m} <@{p['user_id']}> — {p['wins']}승 · 보상 💰{p['point']:,}P + {p['item']} {p['amount']}개")
                    desc = "🏆 **PvP 시즌이 종료되었습니다!**\n지난 시즌 순위 보상이 지급되었어요.\n\n" + "\n".join(lines)
                else:
                    desc = "🏆 **PvP 시즌이 종료되었습니다!**\n이번 시즌에는 순위 기록이 없어 보상이 없었어요."
                desc += f"\n\n⚔️ 새 시즌이 시작됐어요! 전적이 초기화되었습니다.\n다음 시즌 종료: **{rpg_pvp_next_season_date()}**"
                embed = discord.Embed(title="⚔️ PvP 시즌 종료 & 보상", description=desc, color=discord.Color.gold())
                embed.set_footer(text="2주마다 시즌이 초기화돼요 | 만능 봇 RPG PvP")
                # 랭킹 채널 우선, 없으면 일반 로그로
                try:
                    with DB_MUTEX:
                        c.execute("SELECT channel_id FROM rpg_channels WHERE guild_id=? AND feature=?", (guild.id, "랭킹"))
                        crow = c.fetchone()
                    ch = guild.get_channel(crow[0]) if crow else None
                    if ch:
                        await ch.send(embed=embed)
                    else:
                        await send_log(guild, desc, "general")
                except Exception:
                    pass
                # 시즌 초기화 후 순위 역할도 갱신 (전적이 0이 되므로 역할 회수)
                try:
                    await rpg_sync_pvp_rank_roles(guild)
                except Exception:
                    pass
            except Exception as e:
                print(f"⚠️ PvP 시즌 처리 실패(guild {guild.id}): {e}")
    except Exception as e:
        print(f"⚠️ PvP 시즌 루프 오류: {e}")


