# ===== 커스텀 자동응답 =====


async def handle_custom_response(message: discord.Message):
    """메시지에 등록된 트리거가 있으면 자동응답을 보냅니다.
    v246: 시작/끝/정규식 매칭, 확률, 쿨다운, 채널 제한, 랜덤 응답, 반응 이모지를 지원합니다.
    """
    try:
        if message.guild is None or message.author.bot or not message.content:
            return
        raw = message.content.strip()
        lowered = raw.lower()
        with DB_MUTEX:
            c.execute(
                "SELECT trigger, response, match_type, COALESCE(chance,100), COALESCE(cooldown_sec,0), "
                "COALESCE(channel_id,0), COALESCE(reaction,''), COALESCE(enabled,1) "
                "FROM custom_responses WHERE guild_id=?",
                (message.guild.id,),
            )
            rows = c.fetchall()

        for trig, resp, match_type, chance, cooldown, ch_id, reaction, enabled in rows:
            if not int(enabled or 0):
                continue
            # 채널 제한이 걸려 있으면 그 채널에서만 반응합니다.
            if int(ch_id or 0) and message.channel.id != int(ch_id):
                continue

            match_type = str(match_type or "exact")
            target = raw if match_type == "regex" else lowered
            if not _mnb_response_matches(match_type, str(trig), target):
                continue

            # 쿨다운: 아직 안 지났으면 조용히 넘어갑니다.
            cd = int(cooldown or 0)
            if cd > 0:
                key = (message.guild.id, str(trig))
                last = _MNB_RESPONSE_COOLDOWN.get(key, 0)
                if time.time() - last < cd:
                    return
                _MNB_RESPONSE_COOLDOWN[key] = time.time()

            # 확률: 걸리지 않으면 아무것도 하지 않고 끝냅니다.
            ch = int(chance or 100)
            if ch < 100 and random.randint(1, 100) > ch:
                return

            perms = message.channel.permissions_for(message.guild.me)

            reaction = str(reaction or "").strip()
            if reaction:
                try:
                    if perms.add_reactions:
                        await message.add_reaction(reaction)
                except Exception:
                    pass

            resp = str(resp or "")
            if resp and perms.send_messages:
                # `|` 로 구분된 여러 응답 중 하나를 무작위로 고릅니다.
                parts = [p.strip() for p in resp.split("|") if p.strip()]
                pick = random.choice(parts) if parts else resp
                # 사용할 수 있는 치환자입니다.
                pick = (
                    pick.replace("{user}", message.author.mention)
                        .replace("{name}", message.author.display_name)
                        .replace("{server}", message.guild.name)
                )
                await message.channel.send(
                    pick[:1900], allowed_mentions=discord.AllowedMentions(users=True)
                )

            try:
                with DB_MUTEX:
                    c.execute(
                        "UPDATE custom_responses SET use_count=COALESCE(use_count,0)+1 "
                        "WHERE guild_id=? AND trigger=?",
                        (message.guild.id, str(trig)),
                    )
                    conn.commit()
            except Exception:
                pass
            break
    except Exception:
        pass


# ===== 익명 질문상자 =====
@bot.tree.command(name="질문상자설정", description="익명 질문이 올라갈 채널을 지정합니다. (관리자)")
@app_commands.describe(채널="익명 질문이 게시될 채널")
async def anon_question_setup(interaction: discord.Interaction, 채널: discord.TextChannel):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if not interaction.user.guild_permissions.manage_guild:
        return await safe_interaction_send(interaction, "❌ 서버 관리 권한이 필요해요.", ephemeral=True)
    with DB_MUTEX:
        c.execute(
            "INSERT INTO anon_question_settings(guild_id, channel_id, enabled) VALUES (?,?,1) "
            "ON CONFLICT(guild_id) DO UPDATE SET channel_id=excluded.channel_id, enabled=1",
            (interaction.guild.id, 채널.id),
        )
        conn.commit()
    await safe_interaction_send(interaction, f"✅ 익명 질문상자 채널을 {채널.mention}(으)로 설정했어요.\n이제 누구나 `/질문`으로 익명 질문을 보낼 수 있어요.", ephemeral=True)


