# ===== 개인 할일 목록 (todo) =====
@bot.tree.command(name="할일추가", description="개인 할일을 추가합니다. (나만 보여요)")
@app_commands.describe(내용="할 일 내용", 마감일="선택 · YYYY-MM-DD 형식 (예: 2026-08-01)")
async def todo_add(interaction: discord.Interaction, 내용: str, 마감일: str = None):
    content = (내용 or "").strip()[:200]
    if not content:
        return await safe_interaction_send(interaction, "❌ 할일 내용을 입력해주세요.", ephemeral=True)

    due = ""
    if 마감일:
        try:
            due = datetime.datetime.strptime(마감일.strip(), "%Y-%m-%d").date().isoformat()
        except ValueError:
            return await safe_interaction_send(interaction, "❌ 마감일은 `YYYY-MM-DD` 형식으로 입력해주세요.", ephemeral=True)

    now = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with DB_MUTEX:
        c.execute("SELECT COUNT(*) FROM todos WHERE user_id=? AND done=0", (interaction.user.id,))
        if c.fetchone()[0] >= 50:
            return await safe_interaction_send(interaction, "❌ 완료하지 않은 할일이 50개예요. 먼저 정리해주세요.", ephemeral=True)
        c.execute(
            "INSERT INTO todos(user_id, content, done, due_date, created_at) VALUES (?,?,0,?,?)",
            (interaction.user.id, content, due, now),
        )
        conn.commit()
        todo_id = c.lastrowid

    due_text = f"\n📅 마감: {due}" if due else ""
    await safe_interaction_send(interaction, f"✅ 할일을 추가했어요! `#{todo_id}`\n**{content}**{due_text}", ephemeral=True)


@bot.tree.command(name="할일", description="내 할일 목록을 확인합니다. (나만 보여요)")
@app_commands.describe(완료포함="완료한 할일도 함께 볼지 (기본: 안 봄)")
async def todo_list(interaction: discord.Interaction, 완료포함: bool = False):
    with DB_MUTEX:
        if 완료포함:
            c.execute("SELECT id, content, done, due_date FROM todos WHERE user_id=? ORDER BY done ASC, id ASC LIMIT 40", (interaction.user.id,))
        else:
            c.execute("SELECT id, content, done, due_date FROM todos WHERE user_id=? AND done=0 ORDER BY id ASC LIMIT 40", (interaction.user.id,))
        rows = c.fetchall()

    if not rows:
        return await safe_interaction_send(interaction, "할일이 없어요! `/할일추가`로 등록해보세요. 🎉", ephemeral=True)

    today = datetime.date.today()
    pending, finished = [], []
    for tid, content, done, due in rows:
        # 마감일 배지
        badge = ""
        if due:
            try:
                d = datetime.date.fromisoformat(due)
                diff = (d - today).days
                if diff < 0:
                    badge = f" 🔴 `D+{abs(diff)} 지남`"
                elif diff == 0:
                    badge = " ⚠️ `오늘 마감`"
                else:
                    badge = f" 📅 `D-{diff}`"
            except ValueError:
                pass
        if done:
            finished.append(f"`#{tid}` ~~{content}~~")
        else:
            pending.append(f"`#{tid}` {content}{badge}")

    desc = ""
    if pending:
        desc += "**📌 남은 할일**\n" + "\n".join(pending)
    if finished:
        desc += ("\n\n" if desc else "") + "**✅ 완료**\n" + "\n".join(finished)

    embed = create_embed("📝 내 할일 목록", desc, 0x87CEFA)
    embed.set_footer(text="완료: /할일완료 번호:# · 삭제: /할일삭제 번호:#")
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)


@bot.tree.command(name="할일완료", description="할일을 완료 처리합니다.")
@app_commands.describe(번호="/할일 목록에서 확인한 번호")
async def todo_done(interaction: discord.Interaction, 번호: int):
    with DB_MUTEX:
        c.execute("SELECT content, done, user_id FROM todos WHERE id=?", (번호,))
        row = c.fetchone()
        if not row or row[2] != interaction.user.id:
            return await safe_interaction_send(interaction, "❌ 그 번호의 할일을 찾을 수 없어요. (본인 할일만 처리할 수 있어요)", ephemeral=True)
        if row[1]:
            return await safe_interaction_send(interaction, f"이미 완료한 할일이에요: **{row[0]}**", ephemeral=True)
        c.execute("UPDATE todos SET done=1 WHERE id=?", (번호,))
        conn.commit()
    await safe_interaction_send(interaction, f"🎉 완료했어요! **{row[0]}**\n수고했어요 👏", ephemeral=True)


@bot.tree.command(name="할일삭제", description="할일을 목록에서 삭제합니다.")
@app_commands.describe(번호="/할일 목록에서 확인한 번호 (0을 넣으면 완료한 할일 전체 삭제)")
async def todo_delete(interaction: discord.Interaction, 번호: int):
    # 0이면 완료 항목 일괄 정리
    if 번호 == 0:
        with DB_MUTEX:
            c.execute("SELECT COUNT(*) FROM todos WHERE user_id=? AND done=1", (interaction.user.id,))
            cnt = c.fetchone()[0]
            c.execute("DELETE FROM todos WHERE user_id=? AND done=1", (interaction.user.id,))
            conn.commit()
        return await safe_interaction_send(interaction, f"🧹 완료한 할일 **{cnt}개**를 정리했어요.", ephemeral=True)

    with DB_MUTEX:
        c.execute("SELECT content, user_id FROM todos WHERE id=?", (번호,))
        row = c.fetchone()
        if not row or row[1] != interaction.user.id:
            return await safe_interaction_send(interaction, "❌ 그 번호의 할일을 찾을 수 없어요. (본인 할일만 삭제할 수 있어요)", ephemeral=True)
        c.execute("DELETE FROM todos WHERE id=?", (번호,))
        conn.commit()
    await safe_interaction_send(interaction, f"🗑️ **{row[0]}** 할일을 삭제했어요.", ephemeral=True)


# =========================
# 기존 /경제 출석, /경제 출첵은 다시 만들지 않고 /출첵, !출첵 기준을 유지합니다.
MNB_KST = datetime.timezone(datetime.timedelta(hours=9))
MNB_STARTED_AT = datetime.datetime.now(MNB_KST)
utility_group = app_commands.Group(name="편의", description="만능 봇 편의 기능 25개 모음")


def mnb_now_kst():
    return datetime.datetime.now(MNB_KST)


def mnb_format_delta(delta: datetime.timedelta) -> str:
    seconds = max(0, int(delta.total_seconds()))
    days, seconds = divmod(seconds, 86400)
    hours, seconds = divmod(seconds, 3600)
    minutes, seconds = divmod(seconds, 60)
    parts = []
    if days:
        parts.append(f"{days}일")
    if hours:
        parts.append(f"{hours}시간")
    if minutes:
        parts.append(f"{minutes}분")
    if seconds or not parts:
        parts.append(f"{seconds}초")
    return " ".join(parts)


def mnb_clean_items(text: str, limit: int = 20):
    items = [x.strip() for x in re.split(r"[,/|\n]+", text or "") if x.strip()]
    return items[:limit]


def mnb_simple_embed(title: str, description: str, color: int = BOT_COLOR):
    embed = discord.Embed(title=title, description=description, color=color)
    embed.set_footer(text="만능 봇 | /편의")
    return embed


def mnb_member_badges(member: discord.Member) -> str:
    badges = []
    if member.guild_permissions.administrator:
        badges.append("관리자")
    if member.bot:
        badges.append("봇")
    if getattr(member, "premium_since", None):
        badges.append("서버부스터")
    return ", ".join(badges) if badges else "일반 멤버"


def mnb_safe_calculate(expression: str):
    expression = (expression or "").strip()
    if not expression or len(expression) > 80:
        raise ValueError("식은 1~80자 안에서 입력해주세요.")
    allowed_bin = {
        ast.Add: lambda a, b: a + b,
        ast.Sub: lambda a, b: a - b,
        ast.Mult: lambda a, b: a * b,
        ast.Div: lambda a, b: a / b,
        ast.FloorDiv: lambda a, b: a // b,
        ast.Mod: lambda a, b: a % b,
        ast.Pow: lambda a, b: a ** b,
    }
    allowed_unary = {
        ast.UAdd: lambda a: +a,
        ast.USub: lambda a: -a,
    }

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in allowed_bin:
            left = _eval(node.left)
            right = _eval(node.right)
            if isinstance(node.op, ast.Pow) and abs(right) > 8:
                raise ValueError("제곱은 너무 큰 수로 계산할 수 없어요.")
            value = allowed_bin[type(node.op)](left, right)
            if abs(value) > 10**12:
                raise ValueError("결과가 너무 커요.")
            return value
        if isinstance(node, ast.UnaryOp) and type(node.op) in allowed_unary:
            return allowed_unary[type(node.op)](_eval(node.operand))
        raise ValueError("숫자와 + - * / // % ** 괄호만 사용할 수 있어요.")

    tree = ast.parse(expression, mode="eval")
    return _eval(tree)


async def mnb_timer_finish(channel_id: int, user_id: int, seconds: int, memo: str):
    await asyncio.sleep(seconds)
    channel = bot.get_channel(channel_id)
    if channel is None:
        return
    try:
        embed = mnb_simple_embed(
            "⏰ 타이머 완료",
            f"<@{user_id}> 타이머가 끝났어요!\n메모: {memo or '없음'}",
            COLOR_GOLD,
        )
        await channel.send(content=f"<@{user_id}>", embed=embed)
    except Exception:
        pass


