@utility_group.command(name="셔플", description="입력한 항목 순서를 섞어줍니다. 쉼표로 구분하세요.")
@app_commands.describe(options="예: 1팀, 2팀, 3팀")
async def utility_shuffle(interaction: discord.Interaction, options: str):
    items = mnb_clean_items(options)
    if len(items) < 2:
        await safe_interaction_send(interaction, embed=mnb_simple_embed("⚠️ 셔플 실패", "항목을 2개 이상 입력해주세요.", COLOR_WARNING), ephemeral=True)
        return
    random.shuffle(items)
    await safe_interaction_send(interaction, embed=mnb_simple_embed("🔀 셔플", "\n".join(f"{i}. {item}" for i, item in enumerate(items, 1))))


