class MnbExtraInputModal(discord.ui.Modal):
    def __init__(self, mode: str):
        self.mode = mode
        title_map = {
            "생일축하문구": "생일 축하 문구",
            "공지양식": "공지 양식 만들기",
            "이벤트문구": "이벤트 문구 만들기",
            "모집글": "모집글 만들기",
            "초대문구": "초대 문구 만들기",
            "팀나누기": "팀 나누기",
            "사다리뽑기": "사다리 뽑기",
            "번호뽑기": "번호 뽑기",
            "랜덤닉네임": "랜덤 닉네임",
            "암호생성": "암호 생성",
            "선택룰렛": "선택 룰렛",
            "패치노트양식": "패치노트 양식",
        }
        super().__init__(title=title_map.get(mode, "추가기능 입력"))
        self.first = None
        self.second = None
        self.third = None

        def add_first(label, placeholder="", required=True, max_length=300, default=None, style=discord.TextStyle.short):
            self.first = discord.ui.TextInput(label=label, placeholder=placeholder, required=required, max_length=max_length, default=default, style=style)
            self.add_item(self.first)

        def add_second(label, placeholder="", required=True, max_length=300, default=None, style=discord.TextStyle.short):
            self.second = discord.ui.TextInput(label=label, placeholder=placeholder, required=required, max_length=max_length, default=default, style=style)
            self.add_item(self.second)

        def add_third(label, placeholder="", required=True, max_length=300, default=None, style=discord.TextStyle.short):
            self.third = discord.ui.TextInput(label=label, placeholder=placeholder, required=required, max_length=max_length, default=default, style=style)
            self.add_item(self.third)

        if mode == "생일축하문구":
            add_first("이름", "예: 냥이", required=False)
            add_second("분위기", "귀엽게 / 진심으로 / 짧게", required=False, default="귀엽게")
        elif mode == "공지양식":
            add_first("공지 제목", "예: 서버 점검 안내")
            add_second("공지 내용", "핵심 내용을 적어주세요", max_length=2500, style=discord.TextStyle.paragraph)
        elif mode == "이벤트문구":
            add_first("이벤트 이름", "예: 주말 내전")
            add_second("일정/보상", "예: 토요일 8시 / 1등 3000P")
            add_third("참여 방법", "예: 댓글로 참여 신청")
        elif mode == "모집글":
            add_first("모집 종류", "친구 / 우프 / 게임 / 내전", default="게임")
            add_second("조건/내용", "예: 마이크 가능, 즐겜", max_length=1000, style=discord.TextStyle.paragraph)
        elif mode == "초대문구":
            add_first("서버 이름", "예: 냥이 친목방", required=False)
            add_second("강조할 점", "예: 수다/게임/음성방 활발", required=False)
        elif mode == "팀나누기":
            add_first("참가자", "쉼표/줄바꿈으로 구분", max_length=2000, style=discord.TextStyle.paragraph)
            add_second("팀 수", "예: 2", default="2")
        elif mode == "사다리뽑기":
            add_first("참가자", "쉼표/줄바꿈으로 구분", max_length=1500, style=discord.TextStyle.paragraph)
            add_second("결과/보상", "쉼표/줄바꿈으로 구분", max_length=1500, style=discord.TextStyle.paragraph)
        elif mode == "번호뽑기":
            add_first("최소 번호", "예: 1", default="1")
            add_second("최대 번호", "예: 100", default="100")
            add_third("뽑을 개수", "예: 3", default="1")
        elif mode == "랜덤닉네임":
            add_first("느낌", "귀여운 / 게임 / 하늘 / 고양이", required=False, default="귀여운")
        elif mode == "암호생성":
            add_first("길이", "8~32", default="12")
        elif mode == "선택룰렛":
            add_first("항목", "쉼표/줄바꿈으로 구분", max_length=2000, style=discord.TextStyle.paragraph)
        elif mode == "패치노트양식":
            add_first("버전", "예: v1.2.0", required=False, default="v1.0.0")
            add_second("변경 내용", "추가/수정/삭제 내용을 적어주세요", max_length=2500, style=discord.TextStyle.paragraph)
        else:
            add_first("입력", "값을 입력해주세요")

    async def on_submit(self, interaction: discord.Interaction):
        try:
            a = str(self.first.value).strip() if self.first else ""
            b = str(self.second.value).strip() if self.second else ""
            d = str(self.third.value).strip() if self.third else ""
            mode = self.mode

            if mode == "생일축하문구":
                name = a or "오늘의 주인공"
                style = b or "귀엽게"
                text = f"🎂 **{name}님 생일 축하해요!**\n오늘 하루는 {name}님이 제일 빛나는 날이에요. 맛있는 것도 먹고, 좋은 말도 많이 듣는 행복한 하루 보내세요 💖\n분위기: `{style}`"
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("🎂 생일축하문구", text, color=COLOR_PINK))

            if mode == "공지양식":
                embed = discord.Embed(title=f"📢 {a}", description=b, color=COLOR_SKY)
                embed.add_field(name="확인", value="내용을 확인했다면 ✅ 반응을 눌러주세요.", inline=False)
                embed.set_footer(text="공지 양식 미리보기")
                return await safe_interaction_send(interaction, embed=embed)

            if mode == "이벤트문구":
                embed = discord.Embed(
                    title=f"🎉 {a}",
                    description=f"서버 이벤트가 열려요!\n\n📅 **일정/보상**\n{b}\n\n📝 **참여 방법**\n{d}",
                    color=COLOR_GOLD,
                )
                embed.set_footer(text="이벤트 문구 미리보기")
                return await safe_interaction_send(interaction, embed=embed)

            if mode == "모집글":
                embed = discord.Embed(
                    title=f"🤝 {a} 할 사람?",
                    description=f"같이 할 사람을 구해요!\n\n**내용**\n{b}\n\n관심 있으면 댓글이나 멘션으로 알려주세요 🌸",
                    color=COLOR_LAVENDER,
                )
                return await safe_interaction_send(interaction, embed=embed)

            if mode == "초대문구":
                server_name = a or (interaction.guild.name if interaction.guild else "우리 서버")
                point = b or "수다, 게임, 음성방, 이벤트를 같이 즐길 수 있어요"
                text = f"💌 **{server_name}** 에 놀러오세요!\n{point}\n처음 온 분도 편하게 적응할 수 있는 따뜻한 친목방이에요 ✨"
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("💌 초대문구", text, color=COLOR_SOFT_SKY))

            if mode == "팀나누기":
                members = [x.strip() for x in re.split(r"[,\n]", a) if x.strip()]
                team_count = max(2, min(10, int(b or 2)))
                if len(members) < team_count:
                    return await safe_interaction_send(interaction, "❌ 참가자 수가 팀 수보다 적어요.", ephemeral=True)
                random.shuffle(members)
                teams = [[] for _ in range(team_count)]
                for idx, member in enumerate(members):
                    teams[idx % team_count].append(member)
                embed = discord.Embed(title="👥 팀나누기 결과", color=COLOR_MINT)
                for idx, team in enumerate(teams, 1):
                    embed.add_field(name=f"Team {idx}", value="\n".join(team) or "없음", inline=True)
                return await safe_interaction_send(interaction, embed=embed)

            if mode == "사다리뽑기":
                members = [x.strip() for x in re.split(r"[,\n]", a) if x.strip()]
                prizes = [x.strip() for x in re.split(r"[,\n]", b) if x.strip()]
                if not members or not prizes:
                    return await safe_interaction_send(interaction, "❌ 참가자와 결과를 모두 입력해주세요.", ephemeral=True)
                random.shuffle(prizes)
                lines = [f"{member} → **{prizes[idx % len(prizes)]}**" for idx, member in enumerate(members)]
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("🪜 사다리뽑기 결과", "\n".join(lines), color=COLOR_GOLD))

            if mode == "번호뽑기":
                low, high, count = int(a), int(b), int(d or 1)
                if low > high:
                    low, high = high, low
                count = max(1, min(30, count))
                pool = list(range(low, high + 1))
                if count > len(pool):
                    count = len(pool)
                picked = random.sample(pool, count)
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("🔢 번호뽑기", ", ".join(map(str, sorted(picked))), color=COLOR_SKY))

            if mode == "랜덤닉네임":
                theme = a or "귀여운"
                prefixes = ["몽글", "하늘", "말랑", "반짝", "새벽", "구름", "복숭", "달빛", "냥", "푸딩"]
                suffixes = ["냥이", "별", "구름", "토끼", "요정", "젤리", "나비", "여우", "쿠키", "마카롱"]
                names = [f"{random.choice(prefixes)}{random.choice(suffixes)}" for _ in range(5)]
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("🐾 랜덤닉네임", f"느낌: `{theme}`\n" + "\n".join(f"• {x}" for x in names), color=COLOR_PINK))

            if mode == "암호생성":
                length = max(8, min(32, int(a or 12)))
                alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%"
                password = "".join(random.choice(alphabet) for _ in range(length))
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("🔐 암호생성", f"`{password}`\n\n다른 곳에 공유하지 말고 필요한 곳에만 사용하세요.", color=COLOR_GRAY), ephemeral=True)

            if mode == "선택룰렛":
                items = [x.strip() for x in re.split(r"[,\n]", a) if x.strip()]
                if len(items) < 2:
                    return await safe_interaction_send(interaction, "❌ 항목을 2개 이상 입력해주세요.", ephemeral=True)
                return await safe_interaction_send(interaction, embed=mnb_extra_random_embed("🎯 선택룰렛", f"결과: **{random.choice(items)}**", color=COLOR_GOLD))

            if mode == "패치노트양식":
                embed = discord.Embed(
                    title=f"📝 패치노트 {a or 'v1.0.0'}",
                    description=(
                        "✨ **새 기능**\n- 내용을 입력해주세요\n\n"
                        "🐛 **버그 수정**\n- 내용을 입력해주세요\n\n"
                        "⚡ **개선/최적화**\n- 내용을 입력해주세요\n\n"
                        f"📌 **메모**\n{b}"
                    ),
                    color=COLOR_SOFT_SKY,
                )
                embed.set_footer(text="패치노트 양식 미리보기")
                return await safe_interaction_send(interaction, embed=embed)

        except Exception as e:
            await safe_interaction_send(interaction, f"❌ 처리 중 오류가 발생했어요: `{maneung_safe_text(e, 500) if 'maneung_safe_text' in globals() else str(e)}`", ephemeral=True)


class MnbExtraFeatureSelect(discord.ui.Select):
    def __init__(self):
        options = [
            discord.SelectOption(label=name, value=name, description=desc[:100], emoji=emoji)
            for name, emoji, desc in MNB_EXTRA_FEATURE_OPTIONS
        ]
        super().__init__(
            placeholder="추가 기능을 선택해주세요",
            min_values=1,
            max_values=1,
            options=options,
            custom_id="mnb_extra_feature_select_v197",
        )

    async def callback(self, interaction: discord.Interaction):
        mode = self.values[0]
        direct_actions = {
            "오늘운세": extra_today_fortune,
            "친목질문": extra_friend_question,
            "밸런스게임": extra_balance_game,
            "게임추천": extra_game_recommend,
            "채팅주제": extra_chat_topic,
            "서버체크리스트": extra_server_checklist,
            "권한안내": extra_permission_guide,
            "출석응원": extra_attendance_cheer,
        }
        if mode in direct_actions:
            return await direct_actions[mode](interaction)
        await interaction.response.send_modal(MnbExtraInputModal(mode))


class MnbExtraFeatureView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=600)
        self.add_item(MnbExtraFeatureSelect())

    @discord.ui.button(label="새로고침", emoji="🔄", style=discord.ButtonStyle.gray, custom_id="mnb_extra_refresh_v197")
    async def refresh(self, interaction: discord.Interaction, button: discord.ui.Button):
        await safe_interaction_edit(interaction, embed=build_mnb_extra_panel_embed(), view=MnbExtraFeatureView())

    @discord.ui.button(label="상점 열기", emoji="🛒", style=discord.ButtonStyle.green, custom_id="mnb_extra_shop_v200")
    async def open_shop(self, interaction: discord.Interaction, button: discord.ui.Button):
        await mnb_shop_open_channel_panel_response(interaction)


async def mnb_extra_features_unified_command(interaction: discord.Interaction):
    await safe_interaction_send(interaction, embed=build_mnb_extra_panel_embed(), view=MnbExtraFeatureView(), ephemeral=True)


