# ---------- 공통 헬퍼 ----------
def _mnb_now_str():
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def _mnb_row_to_dict(cursor, row):
    if row is None:
        return None
    cols = [d[0] for d in cursor.description]
    return dict(zip(cols, row))


def _mnb_get_settings(table: str, guild_id: int, defaults: dict) -> dict:
    c.execute(f"SELECT * FROM {table} WHERE guild_id=?", (guild_id,))
    row = _mnb_row_to_dict(c, c.fetchone())
    if row is None:
        c.execute(f"INSERT OR IGNORE INTO {table}(guild_id, updated_at) VALUES (?, ?)", (guild_id, _mnb_now_str()))
        conn.commit()
        c.execute(f"SELECT * FROM {table} WHERE guild_id=?", (guild_id,))
        row = _mnb_row_to_dict(c, c.fetchone()) or {}
    merged = dict(defaults)
    merged.update({k: v for k, v in row.items() if v is not None})
    return merged


def _mnb_update_settings(table: str, guild_id: int, defaults: dict, **fields) -> dict:
    _mnb_get_settings(table, guild_id, defaults)
    fields = {k: v for k, v in fields.items() if v is not None}
    if fields:
        sets = ", ".join(f"{k}=?" for k in fields)
        c.execute(
            f"UPDATE {table} SET {sets}, updated_at=? WHERE guild_id=?",
            (*fields.values(), _mnb_now_str(), guild_id),
        )
        conn.commit()
    return _mnb_get_settings(table, guild_id, defaults)


MNB_TICKET_DEFAULTS = {
    "category_id": 0, "staff_role_id": 0, "log_channel_id": 0,
    "open_message": "", "ticket_seq": 0,
}
MNB_MOD_DEFAULTS = {
    "spam_enabled": 0, "spam_count": 5, "spam_seconds": 5, "spam_action": "timeout",
    "mention_limit": 0, "caps_limit": 0, "invite_block": 0, "link_block": 0,
    "newbie_days": 0, "raid_join_count": 0, "raid_seconds": 60, "log_channel_id": 0,
}


def get_ticket_settings(guild_id: int) -> dict:
    return _mnb_get_settings("mnb_ticket_settings", guild_id, MNB_TICKET_DEFAULTS)


def update_ticket_settings(guild_id: int, **fields) -> dict:
    return _mnb_update_settings("mnb_ticket_settings", guild_id, MNB_TICKET_DEFAULTS, **fields)


def get_mod_settings(guild_id: int) -> dict:
    return _mnb_get_settings("mnb_mod_settings", guild_id, MNB_MOD_DEFAULTS)


def update_mod_settings(guild_id: int, **fields) -> dict:
    return _mnb_update_settings("mnb_mod_settings", guild_id, MNB_MOD_DEFAULTS, **fields)


async def _mnb_log_to(guild: discord.Guild, channel_id: int, embed: discord.Embed):
    if not channel_id or guild is None:
        return
    try:
        ch = guild.get_channel(int(channel_id))
        if ch is not None:
            await ch.send(embed=embed)
    except Exception:
        pass


