class MnbTicketOpenModal(discord.ui.Modal, title="문의 티켓 열기"):
    def __init__(self):
        super().__init__()
        self.subject = discord.ui.TextInput(label="문의 제목", max_length=80)
        self.detail = discord.ui.TextInput(
            label="문의 내용", style=discord.TextStyle.paragraph, max_length=1000, required=False
        )
        self.add_item(self.subject)
        self.add_item(self.detail)

    async def on_submit(self, interaction: discord.Interaction):
        await mnb_create_ticket(interaction, str(self.subject), str(self.detail or ""))


class MnbTicketPanelView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="문의 열기", style=discord.ButtonStyle.primary, emoji="🎫",
                       custom_id="mnb_ticket_open")
    async def open_ticket(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(MnbTicketOpenModal())


class MnbTicketControlView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="담당하기", style=discord.ButtonStyle.success, emoji="🙋",
                       custom_id="mnb_ticket_claim")
    async def claim(self, interaction: discord.Interaction, button: discord.ui.Button):
        c.execute(
            "UPDATE mnb_tickets SET claimed_by=? WHERE guild_id=? AND channel_id=?",
            (interaction.user.id, interaction.guild.id, interaction.channel.id),
        )
        conn.commit()
        await safe_interaction_send(interaction, f"🙋 {interaction.user.mention} 님이 이 티켓을 담당합니다.")

    @discord.ui.button(label="티켓 닫기", style=discord.ButtonStyle.danger, emoji="🔒",
                       custom_id="mnb_ticket_close")
    async def close(self, interaction: discord.Interaction, button: discord.ui.Button):
        await mnb_close_ticket(interaction)


async def mnb_create_ticket(interaction: discord.Interaction, subject: str, detail: str = ""):
    guild = interaction.guild
    if guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)

    settings = get_ticket_settings(guild.id)

    c.execute(
        "SELECT channel_id FROM mnb_tickets WHERE guild_id=? AND owner_id=? AND status='open'",
        (guild.id, interaction.user.id),
    )
    exist = c.fetchone()
    if exist and guild.get_channel(int(exist[0])):
        return await interaction.followup.send(
            f"❌ 이미 열려 있는 티켓이 있어요: <#{exist[0]}>", ephemeral=True
        )

    ticket_no = int(settings.get("ticket_seq") or 0) + 1
    category = guild.get_channel(int(settings.get("category_id") or 0))
    if not isinstance(category, discord.CategoryChannel):
        category = None

    overwrites = {
        guild.default_role: discord.PermissionOverwrite(view_channel=False),
        guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True),
        interaction.user: discord.PermissionOverwrite(view_channel=True, send_messages=True),
    }
    staff_role = guild.get_role(int(settings.get("staff_role_id") or 0))
    if staff_role is not None:
        overwrites[staff_role] = discord.PermissionOverwrite(view_channel=True, send_messages=True)

    try:
        ch = await guild.create_text_channel(
            name=f"티켓-{ticket_no:04d}",
            category=category,
            overwrites=overwrites,
            reason=f"티켓 생성 · {interaction.user}",
        )
    except discord.Forbidden:
        return await interaction.followup.send("❌ 채널 생성 권한이 없어요. 봇 권한을 확인해주세요.", ephemeral=True)
    except Exception as e:
        return await interaction.followup.send(f"❌ 티켓 생성 실패: `{str(e)[:200]}`", ephemeral=True)

    c.execute(
        "INSERT OR REPLACE INTO mnb_tickets(guild_id, channel_id, ticket_no, owner_id, subject, status, claimed_by, created_at, closed_at) "
        "VALUES (?, ?, ?, ?, ?, 'open', 0, ?, '')",
        (guild.id, ch.id, ticket_no, interaction.user.id, subject, _mnb_now_str()),
    )
    update_ticket_settings(guild.id, ticket_seq=ticket_no)

    embed = discord.Embed(
        title=f"🎫 티켓 #{ticket_no:04d}",
        description=settings.get("open_message") or "담당자가 곧 확인합니다. 문의 내용을 자세히 적어주세요!",
        color=COLOR_SKY,
    )
    embed.add_field(name="제목", value=subject[:1000], inline=False)
    if detail:
        embed.add_field(name="내용", value=detail[:1000], inline=False)
    embed.add_field(name="작성자", value=interaction.user.mention, inline=True)
    embed.set_footer(text="만능 봇 | 티켓 시스템")

    mention = staff_role.mention if staff_role else ""
    await ch.send(content=f"{interaction.user.mention} {mention}".strip(), embed=embed, view=MnbTicketControlView())
    await interaction.followup.send(f"✅ 티켓이 생성되었어요: {ch.mention}", ephemeral=True)


async def mnb_close_ticket(interaction: discord.Interaction, reason: str = ""):
    guild = interaction.guild
    if guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    c.execute(
        "SELECT ticket_no, owner_id, subject FROM mnb_tickets WHERE guild_id=? AND channel_id=? AND status='open'",
        (guild.id, interaction.channel.id),
    )
    row = c.fetchone()
    if not row:
        return await safe_interaction_send(interaction, "❌ 이 채널은 열려 있는 티켓이 아니에요.", ephemeral=True)

    await safe_interaction_defer(interaction)
    ticket_no, owner_id, subject = int(row[0]), int(row[1]), row[2]

    c.execute(
        "UPDATE mnb_tickets SET status='closed', closed_at=? WHERE guild_id=? AND channel_id=?",
        (_mnb_now_str(), guild.id, interaction.channel.id),
    )
    conn.commit()

    settings = get_ticket_settings(guild.id)
    lines = []
    try:
        async for m in interaction.channel.history(limit=300, oldest_first=True):
            if m.content:
                lines.append(f"[{m.created_at.strftime('%m-%d %H:%M')}] {m.author}: {m.content}")
    except Exception:
        pass

    log_embed = discord.Embed(
        title=f"🔒 티켓 #{ticket_no:04d} 종료",
        color=COLOR_GRAY,
        description=f"**제목:** {subject}\n**작성자:** <@{owner_id}>\n**종료자:** {interaction.user.mention}",
    )
    if reason:
        log_embed.add_field(name="사유", value=reason[:1000], inline=False)
    log_embed.set_footer(text="만능 봇 | 티켓 로그")

    log_ch_id = int(settings.get("log_channel_id") or 0)
    if log_ch_id and lines:
        try:
            ch = guild.get_channel(log_ch_id)
            if ch:
                buf = io.BytesIO("\n".join(lines).encode("utf-8"))
                await ch.send(
                    embed=log_embed,
                    file=discord.File(buf, filename=f"ticket-{ticket_no:04d}.txt"),
                )
        except Exception:
            await _mnb_log_to(guild, log_ch_id, log_embed)
    else:
        await _mnb_log_to(guild, log_ch_id, log_embed)

    await interaction.followup.send("🔒 티켓을 종료합니다. 5초 뒤 채널이 삭제돼요.")
    await asyncio.sleep(5)
    try:
        await interaction.channel.delete(reason=f"티켓 종료 · {interaction.user}")
    except Exception:
        pass


