@ticket_group.command(name="목록", description="현재 열려 있는 티켓 목록을 확인합니다. (관리자)")
async def ticket_group_list(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    c.execute(
        "SELECT ticket_no, channel_id, owner_id, subject, claimed_by FROM mnb_tickets "
        "WHERE guild_id=? AND status='open' ORDER BY ticket_no DESC LIMIT 25",
        (interaction.guild.id,),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send("📭 열려 있는 티켓이 없어요.", ephemeral=True)
    embed = discord.Embed(title="🎫 열린 티켓 목록", color=COLOR_SKY)
    for no, ch_id, owner, subject, claimed in rows:
        staff = f"<@{claimed}>" if claimed else "미배정"
        embed.add_field(
            name=f"#{int(no):04d} · {str(subject)[:40]}",
            value=f"<#{ch_id}> · 작성자 <@{owner}> · 담당 {staff}",
            inline=False,
        )
    embed.set_footer(text=f"만능 봇 | 총 {len(rows)}건")
    await interaction.followup.send(embed=embed, ephemeral=True)


@ticket_group.command(name="통계", description="티켓 처리 통계를 확인합니다. (관리자)")
async def ticket_group_stats(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    c.execute("SELECT COUNT(*) FROM mnb_tickets WHERE guild_id=?", (gid,))
    total = int((c.fetchone() or [0])[0])
    c.execute("SELECT COUNT(*) FROM mnb_tickets WHERE guild_id=? AND status='open'", (gid,))
    opened = int((c.fetchone() or [0])[0])
    c.execute(
        "SELECT claimed_by, COUNT(*) FROM mnb_tickets WHERE guild_id=? AND claimed_by!=0 "
        "GROUP BY claimed_by ORDER BY COUNT(*) DESC LIMIT 5",
        (gid,),
    )
    tops = c.fetchall()
    embed = discord.Embed(title="📊 티켓 통계", color=COLOR_MINT)
    embed.add_field(name="총 티켓", value=f"{total:,}건", inline=True)
    embed.add_field(name="열림", value=f"{opened:,}건", inline=True)
    embed.add_field(name="종료", value=f"{max(0, total - opened):,}건", inline=True)
    if tops:
        embed.add_field(
            name="🏅 담당 순위",
            value="\n".join(f"{i}. <@{u}> · {n}건" for i, (u, n) in enumerate(tops, 1)),
            inline=False,
        )
    embed.set_footer(text="만능 봇 | 티켓 통계")
    await interaction.followup.send(embed=embed, ephemeral=True)


# ==========================================================
# 모더레이션 (자동 관리)
# ==========================================================
MNB_SPAM_BUCKET = {}
MNB_RAID_BUCKET = {}
MNB_INVITE_RE = re.compile(r"(discord\.(gg|io|me|li)|discordapp\.com/invite)/\S+", re.I)
MNB_LINK_RE = re.compile(r"https?://\S+", re.I)


def _mnb_is_immune(guild_id: int, member: discord.Member) -> bool:
    if member.guild_permissions.manage_messages or member.guild_permissions.administrator:
        return True
    c.execute("SELECT target_id, kind FROM mnb_mod_immune WHERE guild_id=?", (guild_id,))
    rows = c.fetchall()
    if not rows:
        return False
    role_ids = {r.id for r in getattr(member, "roles", [])}
    for target_id, kind in rows:
        if kind == "user" and int(target_id) == member.id:
            return True
        if kind == "role" and int(target_id) in role_ids:
            return True
    return False


async def _mnb_mod_punish(message: discord.Message, settings: dict, reason: str):
    guild = message.guild
    member = message.author
    action = str(settings.get("spam_action") or "timeout")
    try:
        await message.delete()
    except Exception:
        pass
    try:
        if action == "timeout":
            until = discord.utils.utcnow() + datetime.timedelta(minutes=10)
            await member.timeout(until, reason=reason)
        elif action == "kick":
            await member.kick(reason=reason)
        elif action == "ban":
            await member.ban(reason=reason, delete_message_days=1)
    except Exception:
        pass
    c.execute(
        "INSERT INTO mnb_mod_logs(guild_id, user_id, reason, action, created_at) VALUES (?, ?, ?, ?, ?)",
        (guild.id, member.id, reason, action, _mnb_now_str()),
    )
    conn.commit()
    embed = discord.Embed(title="🛡️ 자동 제재", color=COLOR_WARNING, description=f"{member.mention} · {reason}")
    embed.add_field(name="조치", value=action, inline=True)
    embed.add_field(name="채널", value=message.channel.mention, inline=True)
    embed.set_footer(text="만능 봇 | 모더레이션")
    await _mnb_log_to(guild, int(settings.get("log_channel_id") or 0), embed)


async def mnb_moderation_check(message: discord.Message):
    try:
        if message.guild is None or message.author.bot:
            return
        settings = get_mod_settings(message.guild.id)
        if not any([
            settings.get("spam_enabled"), settings.get("mention_limit"),
            settings.get("caps_limit"), settings.get("invite_block"),
            settings.get("link_block"), settings.get("newbie_days"),
        ]):
            return
        if _mnb_is_immune(message.guild.id, message.author):
            return

        content = message.content or ""

        newbie_days = int(settings.get("newbie_days") or 0)
        if newbie_days > 0 and (MNB_INVITE_RE.search(content) or MNB_LINK_RE.search(content)):
            age = (discord.utils.utcnow() - message.author.created_at).days
            if age < newbie_days:
                return await _mnb_mod_punish(message, settings, f"신규 계정({age}일) 링크 차단")

        if int(settings.get("invite_block") or 0) and MNB_INVITE_RE.search(content):
            return await _mnb_mod_punish(message, settings, "초대 링크 차단")

        if int(settings.get("link_block") or 0) and MNB_LINK_RE.search(content):
            return await _mnb_mod_punish(message, settings, "링크 차단")

        mention_limit = int(settings.get("mention_limit") or 0)
        if mention_limit > 0 and len(message.mentions) + len(message.role_mentions) >= mention_limit:
            return await _mnb_mod_punish(message, settings, f"과도한 멘션({len(message.mentions)}회)")

        caps_limit = int(settings.get("caps_limit") or 0)
        if caps_limit > 0 and len(content) >= 10:
            letters = [ch for ch in content if ch.isalpha()]
            if letters:
                ratio = sum(1 for ch in letters if ch.isupper()) * 100 // len(letters)
                if ratio >= caps_limit:
                    return await _mnb_mod_punish(message, settings, f"대문자 도배({ratio}%)")

        if int(settings.get("spam_enabled") or 0):
            window = int(settings.get("spam_seconds") or 5)
            limit = int(settings.get("spam_count") or 5)
            key = (message.guild.id, message.author.id)
            now = time.time()
            bucket = [t for t in MNB_SPAM_BUCKET.get(key, []) if now - t <= window]
            bucket.append(now)
            MNB_SPAM_BUCKET[key] = bucket
            if len(bucket) >= limit:
                MNB_SPAM_BUCKET[key] = []
                return await _mnb_mod_punish(message, settings, f"도배 감지({len(bucket)}회/{window}초)")
    except Exception:
        pass


mod_group = app_commands.Group(name="모더", description="도배·링크·멘션 자동 차단과 레이드 감지를 설정합니다.")


@mod_group.command(name="설정", description="자동 모더레이션 규칙을 설정합니다. (관리자)")
@app_commands.describe(
    도배감지="도배 자동 감지 사용 여부",
    도배횟수="몇 개 메시지부터 도배로 볼지",
    도배초="도배 판정 시간(초)",
    조치="도배/위반 시 조치 (timeout/kick/ban/delete)",
    멘션제한="한 메시지 최대 멘션 수 (0=끔)",
    대문자비율="대문자 비율 % 제한 (0=끔)",
    초대링크차단="디스코드 초대 링크 차단",
    링크차단="모든 링크 차단",
    신규계정일="가입 N일 미만 계정의 링크 차단 (0=끔)",
    로그채널="제재 로그를 남길 채널",
)
async def mod_group_settings(
    interaction: discord.Interaction,
    도배감지: bool = None,
    도배횟수: int = None,
    도배초: int = None,
    조치: str = None,
    멘션제한: int = None,
    대문자비율: int = None,
    초대링크차단: bool = None,
    링크차단: bool = None,
    신규계정일: int = None,
    로그채널: discord.TextChannel = None,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)

    if 조치 is not None and 조치 not in ("timeout", "kick", "ban", "delete"):
        return await interaction.followup.send(
            "❌ 조치는 `timeout`, `kick`, `ban`, `delete` 중에서 골라주세요.", ephemeral=True
        )

    settings = update_mod_settings(
        interaction.guild.id,
        spam_enabled=None if 도배감지 is None else int(도배감지),
        spam_count=None if 도배횟수 is None else max(2, int(도배횟수)),
        spam_seconds=None if 도배초 is None else max(1, int(도배초)),
        spam_action=조치,
        mention_limit=None if 멘션제한 is None else max(0, int(멘션제한)),
        caps_limit=None if 대문자비율 is None else max(0, min(100, int(대문자비율))),
        invite_block=None if 초대링크차단 is None else int(초대링크차단),
        link_block=None if 링크차단 is None else int(링크차단),
        newbie_days=None if 신규계정일 is None else max(0, int(신규계정일)),
        log_channel_id=로그채널.id if 로그채널 else None,
    )

    def onoff(v):
        return "✅ 켜짐" if int(v or 0) else "❌ 꺼짐"

    log_id = int(settings.get("log_channel_id") or 0)
    embed = discord.Embed(title="🛡️ 자동 모더레이션 설정", color=COLOR_LAVENDER)
    embed.add_field(
        name="도배 감지",
        value=f"{onoff(settings.get('spam_enabled'))} · {settings.get('spam_count')}개/{settings.get('spam_seconds')}초",
        inline=False,
    )
    embed.add_field(name="조치", value=str(settings.get("spam_action")), inline=True)
    embed.add_field(
        name="멘션 제한",
        value=f"{settings.get('mention_limit')}회" if int(settings.get("mention_limit") or 0) else "끔",
        inline=True,
    )
    embed.add_field(
        name="대문자 비율",
        value=f"{settings.get('caps_limit')}%" if int(settings.get("caps_limit") or 0) else "끔",
        inline=True,
    )
    embed.add_field(name="초대 링크 차단", value=onoff(settings.get("invite_block")), inline=True)
    embed.add_field(name="링크 차단", value=onoff(settings.get("link_block")), inline=True)
    embed.add_field(
        name="신규 계정 제한",
        value=f"{settings.get('newbie_days')}일" if int(settings.get("newbie_days") or 0) else "끔",
        inline=True,
    )
    embed.add_field(name="로그 채널", value=f"<#{log_id}>" if log_id else "미설정", inline=True)
    embed.set_footer(text="만능 봇 | 모더레이션 · 관리자와 면제 대상은 검사하지 않습니다")
    await interaction.followup.send(embed=embed, ephemeral=True)


@mod_group.command(name="면제", description="자동 모더레이션을 면제할 역할/유저를 추가합니다. (관리자)")
@app_commands.describe(역할="면제할 역할", 유저="면제할 유저")
async def mod_group_immune(
    interaction: discord.Interaction,
    역할: discord.Role = None,
    유저: discord.Member = None,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    if 역할 is None and 유저 is None:
        return await safe_interaction_send(interaction, "❌ 역할 또는 유저를 지정해주세요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)
    added = []
    if 역할 is not None:
        c.execute(
            "INSERT OR IGNORE INTO mnb_mod_immune(guild_id, target_id, kind) VALUES (?, ?, 'role')",
            (interaction.guild.id, 역할.id),
        )
        added.append(역할.mention)
    if 유저 is not None:
        c.execute(
            "INSERT OR IGNORE INTO mnb_mod_immune(guild_id, target_id, kind) VALUES (?, ?, 'user')",
            (interaction.guild.id, 유저.id),
        )
        added.append(유저.mention)
    conn.commit()
    await interaction.followup.send(f"✅ 면제 대상 추가: {', '.join(added)}", ephemeral=True)


