# ==========================================================
# 스케줄 (예약 메시지 / 정기 공지 / 리마인더)
# ==========================================================
def _mnb_parse_when(text: str):
    """'2026-08-01 20:00' 또는 '30m', '2h', '3d' 형식을 datetime으로 변환합니다."""
    text = (text or "").strip()
    m = re.fullmatch(r"(\d+)\s*([smhd분시간일초])", text, re.I)
    if m:
        n = int(m.group(1))
        unit = m.group(2).lower()
        if unit in ("s", "초"):
            delta = datetime.timedelta(seconds=n)
        elif unit in ("m", "분"):
            delta = datetime.timedelta(minutes=n)
        elif unit in ("h", "시간"):
            delta = datetime.timedelta(hours=n)
        else:
            delta = datetime.timedelta(days=n)
        return datetime.datetime.now() + delta
    for fmt in ("%Y-%m-%d %H:%M", "%Y/%m/%d %H:%M", "%m-%d %H:%M", "%H:%M"):
        try:
            dt = datetime.datetime.strptime(text, fmt)
            now = datetime.datetime.now()
            if fmt == "%H:%M":
                dt = dt.replace(year=now.year, month=now.month, day=now.day)
                if dt <= now:
                    dt += datetime.timedelta(days=1)
            elif fmt == "%m-%d %H:%M":
                dt = dt.replace(year=now.year)
                if dt <= now:
                    dt = dt.replace(year=now.year + 1)
            return dt
        except ValueError:
            continue
    return None


