@tasks.loop(minutes=1)
async def mnb_schedule_runner():
    try:
        now = datetime.datetime.now()
        now_str = now.strftime("%Y-%m-%d %H:%M:%S")
        c.execute(
            "SELECT schedule_id, guild_id, channel_id, author_id, content, kind, interval_minutes "
            "FROM mnb_schedules WHERE active=1 AND run_at<=?",
            (now_str,),
        )
        rows = c.fetchall()
        for sid, gid, ch_id, author_id, content, kind, interval in rows:
            try:
                guild = bot.get_guild(int(gid))
                if guild is None:
                    continue
                if kind == "remind":
                    user = guild.get_member(int(author_id))
                    if user:
                        embed = discord.Embed(
                            title="⏰ 리마인더", description=str(content)[:2000], color=COLOR_GOLD
                        )
                        embed.set_footer(text=f"만능 봇 | {guild.name}")
                        try:
                            await user.send(embed=embed)
                        except Exception:
                            pass
                else:
                    ch = guild.get_channel(int(ch_id))
                    if ch:
                        await ch.send(str(content)[:2000])
            except Exception:
                pass

            if kind == "repeat" and int(interval or 0) > 0:
                nxt = now + datetime.timedelta(minutes=int(interval))
                c.execute(
                    "UPDATE mnb_schedules SET run_at=?, last_run_at=? WHERE schedule_id=?",
                    (nxt.strftime("%Y-%m-%d %H:%M:%S"), now_str, sid),
                )
            else:
                c.execute(
                    "UPDATE mnb_schedules SET active=0, last_run_at=? WHERE schedule_id=?",
                    (now_str, sid),
                )
        if rows:
            conn.commit()
    except Exception:
        pass


# ==========================================================
# 통계
# ==========================================================
def mnb_record_message_stat(message: discord.Message):
    try:
        if message.guild is None or message.author.bot:
            return
        now = datetime.datetime.now()
        c.execute(
            "INSERT INTO mnb_stat_messages(guild_id, stat_date, hour, channel_id, user_id, amount) "
            "VALUES (?, ?, ?, ?, ?, 1) "
            "ON CONFLICT(guild_id, stat_date, hour, channel_id, user_id) DO UPDATE SET amount=amount+1",
            (message.guild.id, now.strftime("%Y-%m-%d"), now.hour,
             message.channel.id, message.author.id),
        )
        conn.commit()
    except Exception:
        pass


def mnb_record_join_stat(guild_id: int, joined: bool = True):
    try:
        today = datetime.datetime.now().strftime("%Y-%m-%d")
        col = "joins" if joined else "leaves"
        c.execute(
            "INSERT INTO mnb_stat_joins(guild_id, stat_date, joins, leaves) VALUES (?, ?, 0, 0) "
            "ON CONFLICT(guild_id, stat_date) DO NOTHING",
            (guild_id, today),
        )
        c.execute(
            f"UPDATE mnb_stat_joins SET {col}={col}+1 WHERE guild_id=? AND stat_date=?",
            (guild_id, today),
        )
        conn.commit()
    except Exception:
        pass


async def mnb_raid_watch(member: discord.Member):
    """설정한 시간 안에 기준 인원 이상 입장하면 로그 채널로 경고를 보냅니다."""
    try:
        guild = member.guild
        settings = get_mod_settings(guild.id)
        limit = int(settings.get("raid_join_count") or 0)
        if limit <= 0:
            return
        window = int(settings.get("raid_seconds") or 60)
        now = time.time()
        bucket = [t for t in MNB_RAID_BUCKET.get(guild.id, []) if now - t <= window]
        bucket.append(now)
        MNB_RAID_BUCKET[guild.id] = bucket
        if len(bucket) < limit:
            return
        MNB_RAID_BUCKET[guild.id] = []
        embed = discord.Embed(
            title="🚨 레이드 의심 감지",
            description=f"최근 **{window}초** 안에 **{len(bucket)}명** 이 입장했어요.",
            color=COLOR_WARNING,
        )
        embed.add_field(name="최근 입장", value=member.mention, inline=True)
        embed.add_field(
            name="권장 조치",
            value="`/모더 잠금` 으로 채널을 잠그거나 서버 인증 수준을 높여주세요.",
            inline=False,
        )
        embed.set_footer(text="만능 봇 | 레이드 감지")
        await _mnb_log_to(guild, int(settings.get("log_channel_id") or 0), embed)
    except Exception:
        pass


def _mnb_bar(value: int, maximum: int, width: int = 12) -> str:
    if maximum <= 0:
        return "░" * width
    filled = max(0, min(width, round(value * width / maximum)))
    return "█" * filled + "░" * (width - filled)


stats_group = app_commands.Group(name="통계", description="서버 활동량, 채널·유저 순위, 시간대 분포를 확인합니다.")


@stats_group.command(name="서버", description="최근 N일간 서버 활동 요약을 확인합니다.")
@app_commands.describe(일수="집계할 기간 (기본 7일, 최대 30일)")
async def stats_group_server(interaction: discord.Interaction, 일수: int = 7):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    gid = interaction.guild.id
    days = max(1, min(30, int(일수)))
    since = (datetime.datetime.now() - datetime.timedelta(days=days - 1)).strftime("%Y-%m-%d")

    c.execute(
        "SELECT COALESCE(SUM(amount),0), COUNT(DISTINCT user_id) FROM mnb_stat_messages "
        "WHERE guild_id=? AND stat_date>=?",
        (gid, since),
    )
    total, actives = c.fetchone() or (0, 0)
    c.execute(
        "SELECT COALESCE(SUM(joins),0), COALESCE(SUM(leaves),0) FROM mnb_stat_joins "
        "WHERE guild_id=? AND stat_date>=?",
        (gid, since),
    )
    joins, leaves = c.fetchone() or (0, 0)

    embed = discord.Embed(title=f"📊 최근 {days}일 서버 통계", color=COLOR_MINT)
    embed.add_field(name="총 메시지", value=f"{int(total):,}개", inline=True)
    embed.add_field(name="활동 멤버", value=f"{int(actives):,}명", inline=True)
    embed.add_field(name="일평균", value=f"{int(total)//days:,}개", inline=True)
    embed.add_field(name="입장", value=f"+{int(joins):,}명", inline=True)
    embed.add_field(name="퇴장", value=f"-{int(leaves):,}명", inline=True)
    embed.add_field(name="순증감", value=f"{int(joins)-int(leaves):+,}명", inline=True)
    embed.add_field(name="현재 멤버", value=f"{interaction.guild.member_count:,}명", inline=True)

    c.execute(
        "SELECT stat_date, SUM(amount) FROM mnb_stat_messages WHERE guild_id=? AND stat_date>=? "
        "GROUP BY stat_date ORDER BY stat_date",
        (gid, since),
    )
    daily = c.fetchall()
    if daily:
        mx = max(int(v) for _, v in daily)
        embed.add_field(
            name="📈 일별 추이",
            value="\n".join(f"`{d[5:]}` {_mnb_bar(int(v), mx)} {int(v):,}" for d, v in daily)[:1000],
            inline=False,
        )
    embed.set_footer(text="만능 봇 | 통계는 기능 추가 시점부터 집계됩니다")
    await interaction.followup.send(embed=embed)


