    c.execute(
        "SELECT channel_id, SUM(amount) FROM mnb_stat_messages WHERE guild_id=? AND stat_date>=? AND user_id=? "
        "GROUP BY channel_id ORDER BY SUM(amount) DESC LIMIT 3",
        (gid, since, target.id),
    )
    fav = c.fetchall()

