class MnbChosungView(discord.ui.View):
    def __init__(self, answer: str, reward: int):
        super().__init__(timeout=60)
        self.answer = answer
        self.reward = reward
        self.solved = False

    @discord.ui.button(label="정답 입력", style=discord.ButtonStyle.primary, emoji="✏️")
    async def answer_btn(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.solved:
            return await safe_interaction_send(interaction, "이미 누군가 맞혔어요!", ephemeral=True)
        await interaction.response.send_modal(MnbChosungModal(self))


class MnbChosungModal(discord.ui.Modal, title="초성 퀴즈 정답"):
    def __init__(self, view: "MnbChosungView"):
        super().__init__()
        self.view_ref = view
        self.guess = discord.ui.TextInput(label="정답", max_length=30)
        self.add_item(self.guess)

    async def on_submit(self, interaction: discord.Interaction):
        if self.view_ref.solved:
            return await safe_interaction_send(interaction, "이미 누군가 맞혔어요!", ephemeral=True)
        if str(self.guess).strip() != self.view_ref.answer:
            return await safe_interaction_send(interaction, "❌ 오답이에요! 다시 도전해보세요.", ephemeral=True)
        self.view_ref.solved = True
        reward = self.view_ref.reward
        gid = interaction.guild.id
        set_user_point(gid, interaction.user.id, get_user_point(gid, interaction.user.id) + reward)
        embed = discord.Embed(
            title="🎉 초성 퀴즈 정답!",
            description=f"{interaction.user.mention} 님이 **{self.view_ref.answer}** 를 맞혔어요!",
            color=COLOR_GREEN,
        )
        embed.add_field(name="보상", value=f"💰 {reward:,} 포인트", inline=True)
        embed.set_footer(text="만능 봇 | 초성 퀴즈")
        await safe_interaction_send(interaction, embed=embed)


