@mini_game_group.command(name="타자대결", description="주어진 문장을 가장 빨리 정확하게 입력하세요.")
@app_commands.describe(보상="우승자에게 지급할 포인트 (기본 500)")
async def mini_game_group_typing(interaction: discord.Interaction, 보상: int = 500):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    sentence = random.choice(MNB_TYPING_SENTENCES)
    reward = max(0, min(100000, int(보상)))
    embed = discord.Embed(
        title="⌨️ 타자 대결",
        description=f"아래 문장을 **그대로** 채팅에 입력하세요! (30초)\n\n```{sentence}```",
        color=COLOR_SOFT_SKY,
    )
    embed.add_field(name="보상", value=f"💰 {reward:,} 포인트", inline=True)
    embed.set_footer(text="만능 봇 | 타자 대결")
    await interaction.followup.send(embed=embed)

    start = time.time()

    def check(m: discord.Message):
        return (
            m.channel.id == interaction.channel.id
            and not m.author.bot
            and m.content.strip() == sentence
        )

    try:
        msg = await bot.wait_for("message", check=check, timeout=30.0)
    except asyncio.TimeoutError:
        return await interaction.followup.send("⏰ 시간 초과! 아무도 완성하지 못했어요.")

    elapsed = time.time() - start
    gid = interaction.guild.id
    set_user_point(gid, msg.author.id, get_user_point(gid, msg.author.id) + reward)
    cpm = int(len(sentence) / elapsed * 60) if elapsed > 0 else 0
    win = discord.Embed(
        title="🏆 타자 대결 우승!",
        description=f"{msg.author.mention} 님이 **{elapsed:.2f}초** 만에 완성했어요!",
        color=COLOR_GREEN,
    )
    win.add_field(name="속도", value=f"약 {cpm:,} 타/분", inline=True)
    win.add_field(name="보상", value=f"💰 {reward:,} 포인트", inline=True)
    win.set_footer(text="만능 봇 | 타자 대결")
    await interaction.followup.send(embed=win)


@mini_game_group.command(name="숫자야구", description="3자리 숫자를 맞히는 숫자야구 게임입니다.")
async def mini_game_group_baseball(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    digits = random.sample("123456789", 3)
    answer = "".join(digits)
    embed = discord.Embed(
        title="⚾ 숫자야구",
        description=(
            "서로 다른 **3자리 숫자**(1~9)를 맞혀보세요!\n"
            "채팅에 숫자를 입력하면 판정해드려요. (9번 기회 · 90초)\n\n"
            "`스트라이크` 자리와 숫자 모두 일치 · `볼` 숫자만 일치"
        ),
        color=COLOR_SKY,
    )
    embed.set_footer(text="만능 봇 | 숫자야구 · '포기' 입력 시 종료")
    await interaction.followup.send(embed=embed)

    tries = 0

    def check(m: discord.Message):
        if m.channel.id != interaction.channel.id or m.author.bot:
            return False
        t = m.content.strip()
        return t == "포기" or (len(t) == 3 and t.isdigit() and len(set(t)) == 3 and "0" not in t)

    while tries < 9:
        try:
            msg = await bot.wait_for("message", check=check, timeout=90.0)
        except asyncio.TimeoutError:
            return await interaction.followup.send(f"⏰ 시간 초과! 정답은 **{answer}** 였어요.")

        guess = msg.content.strip()
        if guess == "포기":
            return await interaction.followup.send(f"🏳️ 게임을 종료했어요. 정답은 **{answer}** 였어요.")

        tries += 1
        strike = sum(1 for i in range(3) if guess[i] == answer[i])
        ball = sum(1 for ch in guess if ch in answer) - strike

        if strike == 3:
            reward = max(200, 1500 - (tries - 1) * 150)
            gid = interaction.guild.id
            set_user_point(gid, msg.author.id, get_user_point(gid, msg.author.id) + reward)
            win = discord.Embed(
                title="🎉 정답입니다!",
                description=f"{msg.author.mention} 님이 **{tries}번** 만에 **{answer}** 를 맞혔어요!",
                color=COLOR_GREEN,
            )
            win.add_field(name="보상", value=f"💰 {reward:,} 포인트", inline=True)
            win.set_footer(text="만능 봇 | 숫자야구")
            return await interaction.followup.send(embed=win)

        result = "아웃" if strike == 0 and ball == 0 else f"{strike}스트라이크 {ball}볼"
        try:
            await msg.reply(f"⚾ `{guess}` → **{result}** (남은 기회 {9 - tries}회)", mention_author=False)
        except Exception:
            pass

    await interaction.followup.send(f"😢 9번 모두 사용했어요! 정답은 **{answer}** 였어요.")


def _mnb_chain_valid(prev_word: str, next_word: str) -> bool:
    if not prev_word:
        return True
    return prev_word[-1] == next_word[0]


