async def mnb_wordchain_check(message: discord.Message):
    try:
        if message.guild is None or message.author.bot:
            return
        content = (message.content or "").strip()
        if not content or len(content) < 2 or " " in content:
            return
        if not all("\uac00" <= ch <= "\ud7a3" for ch in content):
            return
        c.execute(
            "SELECT last_word, last_user_id, turn_count, used_words FROM mnb_word_chain "
            "WHERE guild_id=? AND channel_id=? AND active=1",
            (message.guild.id, message.channel.id),
        )
        row = c.fetchone()
        if not row:
            return
        last_word, last_user, turns, used = row[0], int(row[1]), int(row[2]), (row[3] or "")
        used_list = [w for w in used.split(",") if w]

        if not _mnb_chain_valid(last_word, content):
            return
        if last_user == message.author.id:
            try:
                await message.reply("⚠️ 연속으로는 이어갈 수 없어요! 다른 분을 기다려주세요.", mention_author=False)
            except Exception:
                pass
            return
        if content in used_list:
            try:
                await message.reply(f"❌ **{content}** 은(는) 이미 나온 단어예요!", mention_author=False)
            except Exception:
                pass
            return

        used_list.append(content)
        turns += 1
        c.execute(
            "UPDATE mnb_word_chain SET last_word=?, last_user_id=?, turn_count=?, used_words=? "
            "WHERE guild_id=? AND channel_id=?",
            (content, message.author.id, turns, ",".join(used_list[-200:]),
             message.guild.id, message.channel.id),
        )
        conn.commit()
        try:
            await message.add_reaction("✅")
        except Exception:
            pass
        if turns % 10 == 0:
            reward = 300
            gid = message.guild.id
            set_user_point(gid, message.author.id, get_user_point(gid, message.author.id) + reward)
            try:
                await message.channel.send(
                    f"🎉 **{turns}턴** 달성! {message.author.mention} 님에게 {reward:,} 포인트를 드려요."
                )
            except Exception:
                pass
    except Exception:
        pass


