@community_group.command(name="다지선다", description="선택지가 여러 개인 투표를 만듭니다.")
@app_commands.describe(
    제목="투표 제목",
    선택지="쉼표(,)로 구분해서 최대 10개까지 입력",
    시간="투표 마감 시간(분, 0=무제한)",
)
async def community_group_poll(
    interaction: discord.Interaction, 제목: str, 선택지: str, 시간: int = 0
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    options = [o.strip() for o in (선택지 or "").split(",") if o.strip()][:10]
    if len(options) < 2:
        return await interaction.followup.send("❌ 선택지를 쉼표로 구분해 2개 이상 입력해주세요.")
    emojis = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]
    embed = discord.Embed(
        title=f"🗳️ {제목[:200]}",
        description="\n".join(f"{emojis[i]} {o}" for i, o in enumerate(options)),
        color=COLOR_LAVENDER,
    )
    embed.set_footer(text=f"만능 봇 | {interaction.user.display_name} 님의 투표")
    if int(시간) > 0:
        embed.add_field(name="마감", value=f"{int(시간)}분 후", inline=True)
    msg = await interaction.followup.send(embed=embed)
    for i in range(len(options)):
        try:
            await msg.add_reaction(emojis[i])
        except Exception:
            pass

    if int(시간) > 0:
        await asyncio.sleep(min(int(시간), 1440) * 60)
        try:
            msg = await interaction.channel.fetch_message(msg.id)
            counts = []
            for i, o in enumerate(options):
                r = discord.utils.get(msg.reactions, emoji=emojis[i])
                counts.append((o, (r.count - 1) if r else 0))
            counts.sort(key=lambda x: x[1], reverse=True)
            total = sum(n for _, n in counts) or 1
            result = discord.Embed(
                title=f"📊 투표 결과 · {제목[:180]}",
                description="\n".join(
                    f"**{i}.** {o} — `{n}표` ({n*100//total}%)" for i, (o, n) in enumerate(counts, 1)
                ),
                color=COLOR_GREEN,
            )
            result.set_footer(text=f"만능 봇 | 총 {total}표")
            await interaction.channel.send(embed=result)
        except Exception:
            pass


