# ==========================================================
# 역할 통합 그룹
# ==========================================================
# role_group 정의는 다른 그룹들과 함께 위쪽 그룹 정의 블록에 있습니다.


# ==========================================================
# 로그 보강 (초대 추적 / 삭제 메시지 복구 / 변경 로그)
# ==========================================================
async def mnb_sync_invite_cache(guild: discord.Guild):
    """서버의 초대 코드 사용 횟수를 캐시에 저장합니다."""
    try:
        invites = await guild.invites()
    except Exception:
        return []
    for inv in invites:
        c.execute(
            "INSERT INTO mnb_invite_tracker(guild_id, invite_code, inviter_id, uses) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(guild_id, invite_code) DO UPDATE SET uses=excluded.uses, inviter_id=excluded.inviter_id",
            (guild.id, inv.code, getattr(inv.inviter, "id", 0) or 0, int(inv.uses or 0)),
        )
    conn.commit()
    return invites


async def mnb_detect_inviter(member: discord.Member):
    """입장한 멤버를 누가 초대했는지 캐시와 비교해 찾아냅니다."""
    guild = member.guild
    try:
        c.execute("SELECT invite_code, uses FROM mnb_invite_tracker WHERE guild_id=?", (guild.id,))
        before = {code: int(u or 0) for code, u in c.fetchall()}
        invites = await guild.invites()
    except Exception:
        return None

    found = None
    for inv in invites:
        prev = before.get(inv.code, 0)
        if int(inv.uses or 0) > prev:
            found = inv
            break

    for inv in invites:
        c.execute(
            "INSERT INTO mnb_invite_tracker(guild_id, invite_code, inviter_id, uses) VALUES (?, ?, ?, ?) "
            "ON CONFLICT(guild_id, invite_code) DO UPDATE SET uses=excluded.uses, inviter_id=excluded.inviter_id",
            (guild.id, inv.code, getattr(inv.inviter, "id", 0) or 0, int(inv.uses or 0)),
        )
    conn.commit()

    if found is None:
        return None

    inviter_id = getattr(found.inviter, "id", 0) or 0
    c.execute(
        "INSERT OR REPLACE INTO mnb_invite_joins(guild_id, user_id, inviter_id, invite_code, joined_at) "
        "VALUES (?, ?, ?, ?, ?)",
        (guild.id, member.id, inviter_id, found.code, _mnb_now_str()),
    )
    conn.commit()
    return found


def mnb_store_deleted_message(message: discord.Message):
    try:
        if message.guild is None or message.author.bot or not (message.content or "").strip():
            return
        c.execute(
            "INSERT INTO mnb_deleted_messages(guild_id, channel_id, author_id, content, deleted_at) "
            "VALUES (?, ?, ?, ?, ?)",
            (message.guild.id, message.channel.id, message.author.id,
             message.content[:1800], _mnb_now_str()),
        )
        # 채널당 최근 50개만 남깁니다.
        c.execute(
            "DELETE FROM mnb_deleted_messages WHERE rowid NOT IN "
            "(SELECT rowid FROM mnb_deleted_messages WHERE guild_id=? AND channel_id=? "
            "ORDER BY rowid DESC LIMIT 50) AND guild_id=? AND channel_id=?",
            (message.guild.id, message.channel.id, message.guild.id, message.channel.id),
        )
        conn.commit()
    except Exception:
        pass


@log_group.command(name="초대추적", description="누가 누구를 초대했는지 추적 기록을 확인합니다. (관리자)")
@app_commands.describe(유저="특정 유저를 초대한 사람 조회 (선택)")
async def log_group_invite_track(interaction: discord.Interaction, 유저: discord.Member = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)

    if 유저 is not None:
        c.execute(
            "SELECT inviter_id, invite_code, joined_at FROM mnb_invite_joins WHERE guild_id=? AND user_id=?",
            (interaction.guild.id, 유저.id),
        )
        row = c.fetchone()
        if not row:
            return await interaction.followup.send(
                f"📭 {유저.mention} 님의 초대 기록이 없어요. (기능 추가 이후 입장한 멤버만 기록됩니다)",
                ephemeral=True,
            )
        embed = discord.Embed(title="🔗 초대 기록", color=COLOR_SKY)
