        embed.add_field(name="초대한 사람", value=f"<@{row[0]}>" if row[0] else "알 수 없음", inline=True)
        embed.add_field(name="초대 코드", value=f"`{row[1]}`", inline=True)
        embed.add_field(name="입장 시각", value=str(row[2]), inline=False)
        embed.set_footer(text="만능 봇 | 초대 추적")
