@log_group.command(name="최근", description="최근 자동 제재·로그 활동 요약을 확인합니다. (관리자)")
async def log_group_recent(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    embed = discord.Embed(title="📋 최근 로그 요약", color=COLOR_GRAY)

    c.execute("SELECT COUNT(*) FROM mnb_deleted_messages WHERE guild_id=?", (gid,))
    deleted = int((c.fetchone() or [0])[0])
    c.execute("SELECT COUNT(*) FROM mnb_invite_joins WHERE guild_id=?", (gid,))
    invited = int((c.fetchone() or [0])[0])
    try:
        c.execute("SELECT COUNT(*) FROM mnb_mod_logs WHERE guild_id=?", (gid,))
        punished = int((c.fetchone() or [0])[0])
    except Exception:
        punished = 0

    embed.add_field(name="보관 중인 삭제 메시지", value=f"{deleted:,}개", inline=True)
    embed.add_field(name="추적된 초대 입장", value=f"{invited:,}건", inline=True)
    embed.add_field(name="자동 제재", value=f"{punished:,}건", inline=True)

    c.execute(
        "SELECT log_type, enabled, channel_id FROM log_settings WHERE guild_id=? ORDER BY log_type",
        (gid,),
    )
    rows = c.fetchall()
    if rows:
        lines = []
        for lt, en, ch in rows[:15]:
            label = LOG_TYPE_LABELS.get(str(lt), str(lt))
            state = "✅" if int(en or 0) else "❌"
            where = f"<#{ch}>" if ch else "미설정"
            lines.append(f"{state} {label} · {where}")
        embed.add_field(name="로그 설정", value="\n".join(lines)[:1000], inline=False)
    embed.set_footer(text="만능 봇 | 로그 요약")
    await interaction.followup.send(embed=embed, ephemeral=True)


# ==========================================================
# 주식 보강 (배당 / 포트폴리오 / 예약 매매 / 차트)
# ==========================================================
def _mnb_get_stock(guild_id: int, code: str):
    c.execute(
        "SELECT stock_code, stock_name, price, last_price FROM stock_prices WHERE guild_id=? AND stock_code=?",
        (guild_id, code.upper()),
    )
    return c.fetchone()


@stock_group.command(name="포트폴리오", description="내 주식 보유 현황과 총 평가손익을 확인합니다.")
@app_commands.describe(유저="다른 사람 조회 (선택)")
async def stock_group_portfolio(interaction: discord.Interaction, 유저: discord.Member = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    target = 유저 or interaction.user
    gid = interaction.guild.id
    c.execute(
        "SELECT h.stock_code, h.amount, h.avg_price, p.stock_name, p.price "
        "FROM stock_holdings h LEFT JOIN stock_prices p "
        "ON h.guild_id=p.guild_id AND h.stock_code=p.stock_code "
        "WHERE h.guild_id=? AND h.user_id=? AND h.amount>0",
        (gid, target.id),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send(f"📭 {target.display_name} 님은 보유한 주식이 없어요.")

    total_buy = total_now = 0
    lines = []
    for code, amount, avg, name, price in rows:
        amount = int(amount or 0)
        avg = int(avg or 0)
        price = int(price or 0)
        buy_sum = avg * amount
        now_sum = price * amount
        total_buy += buy_sum
        total_now += now_sum
        diff = now_sum - buy_sum
        rate = (diff * 100 // buy_sum) if buy_sum else 0
        icon = "🔺" if diff > 0 else ("🔻" if diff < 0 else "➖")
        lines.append(
            f"{icon} **{name or code}** `{code}`\n"
            f"　{amount:,}주 · 평단 {avg:,} → 현재 {price:,}\n"
            f"　평가 {now_sum:,} P ({diff:+,} P · {rate:+d}%)"
        )

    total_diff = total_now - total_buy
    total_rate = (total_diff * 100 // total_buy) if total_buy else 0
    color = COLOR_GREEN if total_diff > 0 else (COLOR_WARNING if total_diff < 0 else COLOR_GRAY)
    embed = discord.Embed(title=f"📈 {target.display_name} 님의 포트폴리오", color=color)
    embed.description = "\n\n".join(lines)[:3500]
    embed.add_field(name="매입 총액", value=f"{total_buy:,} P", inline=True)
    embed.add_field(name="평가 총액", value=f"{total_now:,} P", inline=True)
    embed.add_field(name="총 손익", value=f"{total_diff:+,} P ({total_rate:+d}%)", inline=True)
    embed.set_footer(text="만능 봇 | 포트폴리오")
    await interaction.followup.send(embed=embed)


@stock_group.command(name="배당설정", description="종목별 일일 배당률을 설정합니다. (관리자)")
@app_commands.describe(종목코드="배당을 설정할 종목 코드", 배당률="보유 평가액 대비 일일 배당률 % (0=배당 없음)")
async def stock_group_dividend_set(interaction: discord.Interaction, 종목코드: str, 배당률: int):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    code = (종목코드 or "").strip().upper()
    stock = _mnb_get_stock(interaction.guild.id, code)
    if not stock:
        return await interaction.followup.send(f"❌ `{code}` 종목을 찾을 수 없어요.", ephemeral=True)
    rate = max(0, min(20, int(배당률)))
    c.execute(
        "INSERT INTO mnb_stock_dividends(guild_id, stock_code, rate) VALUES (?, ?, ?) "
        "ON CONFLICT(guild_id, stock_code) DO UPDATE SET rate=excluded.rate",
        (interaction.guild.id, code, rate),
    )
    conn.commit()
    if rate == 0:
        return await interaction.followup.send(f"✅ `{code}` 배당을 껐어요.", ephemeral=True)
    await interaction.followup.send(
        f"✅ `{stock[1] or code}` 일일 배당률을 **{rate}%** 로 설정했어요. (하루 1회 `/주식 배당받기`)",
        ephemeral=True,
    )


@stock_group.command(name="배당받기", description="보유 주식의 일일 배당금을 받습니다. (하루 1회)")
async def stock_group_dividend_claim(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    uid = interaction.user.id
    today = datetime.datetime.now().strftime("%Y-%m-%d")

    c.execute(
        "SELECT amount FROM mnb_stock_dividend_claims WHERE guild_id=? AND user_id=? AND claim_date=?",
        (gid, uid, today),
    )
    if c.fetchone():
        return await interaction.followup.send("❌ 오늘 배당금은 이미 받았어요. 내일 다시 오세요!", ephemeral=True)

    c.execute(
        "SELECT h.stock_code, h.amount, p.stock_name, p.price, d.rate "
        "FROM stock_holdings h "
        "JOIN mnb_stock_dividends d ON h.guild_id=d.guild_id AND h.stock_code=d.stock_code "
        "LEFT JOIN stock_prices p ON h.guild_id=p.guild_id AND h.stock_code=p.stock_code "
        "WHERE h.guild_id=? AND h.user_id=? AND h.amount>0 AND d.rate>0",
        (gid, uid),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send(
            "📭 배당이 설정된 보유 종목이 없어요. `/주식 배당목록` 으로 확인해보세요.", ephemeral=True
        )

    total = 0
    lines = []
    for code, amount, name, price, rate in rows:
        value = int(price or 0) * int(amount or 0)
        pay = value * int(rate or 0) // 100
        if pay <= 0:
            continue
        total += pay
        lines.append(f"**{name or code}** · {int(rate)}% → 💰 {pay:,} P")

    if total <= 0:
        return await interaction.followup.send("📭 이번 배당금은 0원이에요.", ephemeral=True)

    set_user_point(gid, uid, get_user_point(gid, uid) + total)
    c.execute(
        "INSERT OR REPLACE INTO mnb_stock_dividend_claims(guild_id, user_id, claim_date, amount) VALUES (?, ?, ?, ?)",
        (gid, uid, today, total),
    )
    conn.commit()

    embed = discord.Embed(title="💵 배당금 지급", color=COLOR_GOLD)
    embed.description = "\n".join(lines)[:2000]
    embed.add_field(name="총 배당금", value=f"💰 {total:,} 포인트", inline=False)
    embed.set_footer(text="만능 봇 | 배당은 하루 1회 받을 수 있어요")
    await interaction.followup.send(embed=embed, ephemeral=True)


