@stock_group.command(name="차트", description="종목의 최근 가격 흐름을 확인합니다.")
@app_commands.describe(종목코드="조회할 종목 코드")
async def stock_group_chart(interaction: discord.Interaction, 종목코드: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    code = (종목코드 or "").strip().upper()
    stock = _mnb_get_stock(interaction.guild.id, code)
    if not stock:
        return await interaction.followup.send(f"❌ `{code}` 종목을 찾을 수 없어요.")
    _, name, price, last = stock
    price = int(price or 0)
    last = int(last or 0)

    c.execute(
        "SELECT price FROM stock_logs WHERE guild_id=? AND stock_code=? ORDER BY rowid DESC LIMIT 20",
        (interaction.guild.id, code),
    )
    hist = [int(r[0]) for r in c.fetchall()][::-1]
    if not hist:
        hist = [last, price]

    lo, hi = min(hist), max(hist)
    span = max(1, hi - lo)
    blocks = "▁▂▃▄▅▆▇█"
    spark = "".join(blocks[min(7, (v - lo) * 7 // span)] for v in hist)

    diff = price - last
    rate = (diff * 100 // last) if last else 0
    icon = "🔺" if diff > 0 else ("🔻" if diff < 0 else "➖")
    color = COLOR_GREEN if diff > 0 else (COLOR_WARNING if diff < 0 else COLOR_GRAY)

    embed = discord.Embed(title=f"📊 {name or code} `{code}`", color=color)
    embed.add_field(name="현재가", value=f"{price:,} P", inline=True)
    embed.add_field(name="전일 대비", value=f"{icon} {diff:+,} P ({rate:+d}%)", inline=True)
    embed.add_field(name="최근 거래가 흐름", value=f"```{spark}```\n최저 {lo:,} · 최고 {hi:,}", inline=False)
    embed.set_footer(text=f"만능 봇 | 최근 거래 {len(hist)}건 기준")
    await interaction.followup.send(embed=embed)


