async def mnb_process_stock_orders(guild: discord.Guild):
    """시세 갱신 후 예약 주문 조건을 확인해 체결합니다."""
    try:
        if guild is None:
            return
        c.execute(
            "SELECT order_id, user_id, stock_code, kind, target_price, amount "
            "FROM mnb_stock_orders WHERE guild_id=? AND active=1",
            (guild.id,),
        )
        orders = c.fetchall()
        if not orders:
            return
        for oid, uid, code, kind, target, amount in orders:
            stock = _mnb_get_stock(guild.id, code)
            if not stock:
                continue
            price = int(stock[2] or 0)
            target = int(target)
            amount = int(amount)
            hit = (kind == "buy" and price <= target) or (kind == "sell" and price >= target)
            if not hit:
                continue

            done = False
            note = ""
            if kind == "buy":
                cost = price * amount
                bal = get_user_point(guild.id, uid)
                if bal >= cost:
                    set_user_point(guild.id, uid, bal - cost)
                    c.execute(
                        "SELECT amount, avg_price FROM stock_holdings WHERE guild_id=? AND user_id=? AND stock_code=?",
                        (guild.id, uid, code),
                    )
                    h = c.fetchone()
                    if h:
                        old_amt, old_avg = int(h[0] or 0), int(h[1] or 0)
                        new_amt = old_amt + amount
                        new_avg = (old_avg * old_amt + price * amount) // max(1, new_amt)
                        c.execute(
                            "UPDATE stock_holdings SET amount=?, avg_price=? WHERE guild_id=? AND user_id=? AND stock_code=?",
                            (new_amt, new_avg, guild.id, uid, code),
                        )
                    else:
                        c.execute(
                            "INSERT INTO stock_holdings(guild_id, user_id, stock_code, amount, avg_price) VALUES (?, ?, ?, ?, ?)",
                            (guild.id, uid, code, amount, price),
                        )
                    done = True
                    note = f"{amount:,}주 매수 · -{cost:,} P"
                else:
                    note = "포인트 부족으로 취소"
            else:
                c.execute(
                    "SELECT amount FROM stock_holdings WHERE guild_id=? AND user_id=? AND stock_code=?",
                    (guild.id, uid, code),
                )
                h = c.fetchone()
                have = int(h[0]) if h else 0
                if have >= amount:
                    gain = price * amount
                    c.execute(
                        "UPDATE stock_holdings SET amount=amount-? WHERE guild_id=? AND user_id=? AND stock_code=?",
                        (amount, guild.id, uid, code),
                    )
                    set_user_point(guild.id, uid, get_user_point(guild.id, uid) + gain)
                    done = True
                    note = f"{amount:,}주 매도 · +{gain:,} P"
                else:
                    note = "보유 수량 부족으로 취소"

            if done:
                c.execute(
                    "INSERT INTO stock_logs(guild_id, user_id, stock_code, action, amount, price, total, created_at) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    (guild.id, uid, code, kind, amount, price, price * amount, _mnb_now_str()),
                )
            c.execute("UPDATE mnb_stock_orders SET active=0 WHERE order_id=?", (oid,))
            conn.commit()

            member = guild.get_member(int(uid))
            if member:
                embed = discord.Embed(
                    title="⏳ 예약 주문 체결" if done else "⚠️ 예약 주문 취소",
                    description=f"**{stock[1] or code}** `{code}` · 목표가 {target:,} P\n{note}",
                    color=COLOR_GREEN if done else COLOR_WARNING,
                )
                embed.set_footer(text=f"만능 봇 | {guild.name}")
                try:
                    await member.send(embed=embed)
                except Exception:
                    pass
    except Exception:
        pass


