@birthday_group.command(name="이번달", description="이번 달 생일인 멤버를 모두 확인합니다.")
@app_commands.describe(월="조회할 월 (비우면 이번 달)")
async def birthday_group_month(interaction: discord.Interaction, 월: int = 0):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    now = datetime.datetime.now()
    month = int(월) if 1 <= int(월) <= 12 else now.month
    c.execute(
        "SELECT user_id, day, birth_year, age_visible FROM birthday_records "
        "WHERE guild_id=? AND month=? ORDER BY day",
        (interaction.guild.id, month),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send(f"📭 {month}월 생일인 멤버가 없어요.")
    lines = []
    for uid, day, year, visible in rows:
        age = ""
        if int(visible or 0) and int(year or 0) > 0:
            age = f" ({now.year - int(year)}세)"
        mark = "🎂" if (month == now.month and int(day) == now.day) else "・"
        lines.append(f"{mark} **{month}월 {int(day)}일** — <@{uid}>{age}")
    embed = discord.Embed(title=f"🎂 {month}월 생일자", color=COLOR_PINK)
    embed.description = "\n".join(lines)[:4000]
    embed.set_footer(text=f"만능 봇 | 총 {len(rows)}명")
    await interaction.followup.send(embed=embed)


@birthday_group.command(name="다가오는", description="곧 다가오는 생일을 순서대로 확인합니다.")
@app_commands.describe(일수="며칠 이내를 볼지 (기본 30일)")
async def birthday_group_upcoming(interaction: discord.Interaction, 일수: int = 30):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    days = max(1, min(365, int(일수)))
    today = datetime.date.today()
    c.execute(
        "SELECT user_id, month, day FROM birthday_records WHERE guild_id=?",
        (interaction.guild.id,),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send("📭 등록된 생일이 없어요.")

    upcoming = []
    for uid, month, day in rows:
        month, day = int(month or 0), int(day or 0)
        if not (1 <= month <= 12 and 1 <= day <= 31):
            continue
        for year in (today.year, today.year + 1):
            try:
                d = datetime.date(year, month, day)
            except ValueError:
                # 2월 29일생은 평년에는 2월 28일로 계산합니다.
                if month == 2 and day == 29:
                    try:
                        d = datetime.date(year, 2, 28)
                    except ValueError:
                        continue
                else:
                    continue
            delta = (d - today).days
            if 0 <= delta <= days:
                upcoming.append((delta, uid, month, day))
                break
    if not upcoming:
        return await interaction.followup.send(f"📭 앞으로 {days}일 안에 생일인 멤버가 없어요.")
    upcoming.sort()
    lines = []
    for delta, uid, month, day in upcoming[:25]:
        when = "🎉 **오늘!**" if delta == 0 else (f"내일" if delta == 1 else f"D-{delta}")
        lines.append(f"`{month:02d}/{day:02d}` <@{uid}> — {when}")
    embed = discord.Embed(title=f"🎂 다가오는 생일 (앞으로 {days}일)", color=COLOR_PINK)
    embed.description = "\n".join(lines)[:4000]
    embed.set_footer(text=f"만능 봇 | 총 {len(upcoming)}명")
    await interaction.followup.send(embed=embed)


@birthday_group.command(name="자동역할", description="생일 당일에 자동으로 지급할 역할을 설정합니다. (관리자)")
@app_commands.describe(역할="생일 당일 지급할 역할 (비우면 해제)")
async def birthday_group_auto_role(interaction: discord.Interaction, 역할: discord.Role = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    role_id = 역할.id if 역할 else 0
    if 역할 is not None:
        me = interaction.guild.me
        if me and 역할 >= me.top_role:
            return await interaction.followup.send(
                "⚠️ 봇 역할보다 높거나 같은 역할은 지급할 수 없어요. 역할 순서를 조정해주세요.", ephemeral=True
            )
    c.execute(
        "INSERT INTO birthday_reward_settings(guild_id) VALUES (?) ON CONFLICT(guild_id) DO NOTHING",
        (gid,),
    )
    c.execute(
        "UPDATE birthday_reward_settings SET birthday_role_id=? WHERE guild_id=?",
        (role_id, gid),
    )
    conn.commit()
    if role_id == 0:
        return await interaction.followup.send("✅ 생일 자동 역할을 해제했어요.", ephemeral=True)
    await interaction.followup.send(
        f"✅ 생일 당일에 {역할.mention} 역할을 자동 지급하고, 다음 날 자동 회수합니다.", ephemeral=True
    )


@birthday_group.command(name="통계", description="서버 생일 등록 현황을 확인합니다.")
async def birthday_group_stats(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    gid = interaction.guild.id
    c.execute("SELECT COUNT(*) FROM birthday_records WHERE guild_id=?", (gid,))
    total = int((c.fetchone() or [0])[0])
    if total == 0:
        return await interaction.followup.send("📭 등록된 생일이 없어요.")
    c.execute(
        "SELECT month, COUNT(*) FROM birthday_records WHERE guild_id=? GROUP BY month ORDER BY month",
        (gid,),
    )
    per = dict((int(m), int(n)) for m, n in c.fetchall())
    mx = max(per.values()) if per else 1
    lines = [f"`{m:2d}월` {_mnb_bar(per.get(m, 0), mx, 10)} {per.get(m, 0)}명" for m in range(1, 13)]
    members = max(1, interaction.guild.member_count or 1)
    embed = discord.Embed(title="🎂 생일 등록 현황", color=COLOR_PINK)
    embed.add_field(name="등록 인원", value=f"{total:,}명", inline=True)
    embed.add_field(name="등록률", value=f"{total*100//members}%", inline=True)
    embed.add_field(name="월별 분포", value="\n".join(lines), inline=False)
    embed.set_footer(text="만능 봇 | 생일 통계")
    await interaction.followup.send(embed=embed)


async def mnb_birthday_role_sync():
    """생일 당일 역할을 지급하고, 지난 사람에게서 회수합니다."""
    try:
        today = datetime.date.today()
        c.execute(
            "SELECT guild_id, birthday_role_id FROM birthday_reward_settings WHERE birthday_role_id!=0"
        )
        rows = c.fetchall()
        for gid, role_id in rows:
            guild = bot.get_guild(int(gid))
            if guild is None:
                continue
            role = guild.get_role(int(role_id))
            if role is None:
                continue
            me = guild.me
            if me and role >= me.top_role:
                continue

            c.execute(
                "SELECT user_id FROM birthday_records WHERE guild_id=? AND month=? AND day=?",
                (int(gid), today.month, today.day),
            )
            today_ids = {int(r[0]) for r in c.fetchall()}

            # 평년의 2월 28일에는 2월 29일생도 생일자로 함께 처리합니다.
            if today.month == 2 and today.day == 28:
                is_leap = (today.year % 4 == 0 and today.year % 100 != 0) or today.year % 400 == 0
                if not is_leap:
                    c.execute(
                        "SELECT user_id FROM birthday_records WHERE guild_id=? AND month=2 AND day=29",
                        (int(gid),),
                    )
                    today_ids |= {int(r[0]) for r in c.fetchall()}

            for member in list(role.members):
                if member.id not in today_ids:
                    try:
                        await member.remove_roles(role, reason="생일 종료 · 자동 회수")
                    except Exception:
                        pass
            for uid in today_ids:
                member = guild.get_member(uid)
                if member and role not in member.roles:
                    try:
                        await member.add_roles(role, reason="생일 당일 · 자동 지급")
                    except Exception:
                        pass
    except Exception:
        pass


@tasks.loop(hours=6)
async def mnb_birthday_role_loop():
    await mnb_birthday_role_sync()


