MNB_TEMP_VOICE_DEFAULTS = {
    "hub_channel_id": 0, "category_id": 0, "name_template": "", "user_limit": 0,
}


def get_temp_voice_settings(guild_id: int) -> dict:
    return _mnb_get_settings("mnb_temp_voice_settings", guild_id, MNB_TEMP_VOICE_DEFAULTS)


def update_temp_voice_settings(guild_id: int, **fields) -> dict:
    return _mnb_update_settings("mnb_temp_voice_settings", guild_id, MNB_TEMP_VOICE_DEFAULTS, **fields)


def _mnb_temp_room_owner(guild_id: int, channel_id: int) -> int:
    c.execute(
        "SELECT owner_id FROM mnb_temp_voice_rooms WHERE guild_id=? AND channel_id=?",
        (guild_id, channel_id),
    )
    row = c.fetchone()
    return int(row[0]) if row else 0


@voice_group.command(name="임시방설정", description="입장하면 개인 음성방이 생성되는 허브 채널을 지정합니다. (관리자)")
@app_commands.describe(
    허브채널="이 음성 채널에 들어오면 새 방이 생성됩니다",
    카테고리="생성될 방이 들어갈 카테고리 (비우면 허브와 같은 곳)",
    이름형식="방 이름 형식. {user} 자리에 닉네임이 들어갑니다",
    인원제한="생성될 방의 기본 인원 제한 (0=무제한)",
)
async def voice_group_temp_setup(
    interaction: discord.Interaction,
    허브채널: discord.VoiceChannel,
    카테고리: discord.CategoryChannel = None,
    이름형식: str = "🔊 {user} 님의 방",
    인원제한: int = 0,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    settings = update_temp_voice_settings(
        interaction.guild.id,
        hub_channel_id=허브채널.id,
        category_id=카테고리.id if 카테고리 else 0,
        name_template=(이름형식 or "")[:80],
        user_limit=max(0, min(99, int(인원제한))),
    )
    embed = discord.Embed(title="🔊 임시 음성방 설정", color=COLOR_LAVENDER)
    embed.add_field(name="허브 채널", value=허브채널.mention, inline=True)
    embed.add_field(name="카테고리", value=카테고리.mention if 카테고리 else "허브와 동일", inline=True)
    embed.add_field(name="이름 형식", value=f"`{settings.get('name_template')}`", inline=False)
    embed.add_field(
        name="기본 인원 제한",
        value=f"{settings.get('user_limit')}명" if int(settings.get("user_limit") or 0) else "무제한",
        inline=True,
    )
    embed.set_footer(text="만능 봇 | 방이 비면 자동으로 삭제됩니다")
    await interaction.followup.send(embed=embed, ephemeral=True)


