@app_commands.describe(이름="새 방 이름")
async def voice_group_room_rename(interaction: discord.Interaction, 이름: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)
    vs = interaction.user.voice
    if vs is None or vs.channel is None:
        return await interaction.followup.send("❌ 먼저 음성 채널에 들어가주세요.", ephemeral=True)
    owner = _mnb_temp_room_owner(interaction.guild.id, vs.channel.id)
