@level_group.command(name="보상설정", description="특정 레벨 도달 시 지급할 역할/포인트를 설정합니다. (관리자)")
@app_commands.describe(레벨="달성 레벨", 역할="지급할 역할 (선택)", 포인트="지급할 포인트 (선택)")
async def level_group_reward_set(
    interaction: discord.Interaction,
    레벨: int,
    역할: discord.Role = None,
    포인트: int = 0,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    lv = max(1, int(레벨))
    if 역할 is None and int(포인트) <= 0:
        return await interaction.followup.send("❌ 역할이나 포인트 중 하나는 지정해주세요.", ephemeral=True)
    if 역할 is not None:
        me = interaction.guild.me
        if me and 역할 >= me.top_role:
            return await interaction.followup.send(
                "⚠️ 봇 역할보다 높거나 같은 역할은 지급할 수 없어요. 역할 순서를 조정해주세요.", ephemeral=True
            )
    c.execute(
        "INSERT INTO mnb_level_rewards(guild_id, level, role_id, point) VALUES (?, ?, ?, ?) "
        "ON CONFLICT(guild_id, level) DO UPDATE SET role_id=excluded.role_id, point=excluded.point",
        (interaction.guild.id, lv, 역할.id if 역할 else 0, max(0, int(포인트))),
    )
    conn.commit()
    parts = []
    if 역할 is not None:
        parts.append(역할.mention)
    if int(포인트) > 0:
        parts.append(f"💰 {int(포인트):,} 포인트")
    await interaction.followup.send(
        f"✅ **Lv.{lv}** 달성 보상을 설정했어요: {' + '.join(parts)}", ephemeral=True
    )


@level_group.command(name="보상목록", description="레벨 보상 설정을 확인하거나 삭제합니다. (관리자)")
@app_commands.describe(삭제레벨="삭제할 레벨 (비우면 목록만 표시)")
async def level_group_reward_list(interaction: discord.Interaction, 삭제레벨: int = 0):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    if int(삭제레벨) > 0:
        c.execute(
            "DELETE FROM mnb_level_rewards WHERE guild_id=? AND level=?", (gid, int(삭제레벨))
        )
        conn.commit()
        if c.rowcount:
            return await interaction.followup.send(f"🗑️ Lv.{삭제레벨} 보상을 삭제했어요.", ephemeral=True)
        return await interaction.followup.send("❌ 해당 레벨 보상이 없어요.", ephemeral=True)

    c.execute(
        "SELECT level, role_id, point FROM mnb_level_rewards WHERE guild_id=? ORDER BY level",
        (gid,),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send("📭 설정된 레벨 보상이 없어요.", ephemeral=True)
    lines = []
    for lv, rid, pt in rows:
        parts = []
        if int(rid or 0):
            parts.append(f"<@&{rid}>")
        if int(pt or 0):
            parts.append(f"💰 {int(pt):,} P")
        lines.append(f"**Lv.{int(lv)}** — {' + '.join(parts) if parts else '없음'}")
    embed = discord.Embed(title="🎁 레벨 보상 설정", color=COLOR_GOLD)
    embed.description = "\n".join(lines)[:4000]
    embed.set_footer(text="만능 봇 | /레벨 보상목록 삭제레벨:<숫자> 로 삭제")
    await interaction.followup.send(embed=embed, ephemeral=True)


