@level_group.command(name="지급", description="유저에게 레벨이나 XP를 직접 지급합니다. (관리자)")
@app_commands.describe(
    유저="대상 유저",
    종류="채팅 또는 음성",
    레벨="설정할 레벨 (0이면 변경 안 함)",
    경험치="설정할 경험치 (-1이면 변경 안 함)",
)
@app_commands.choices(종류=[
    app_commands.Choice(name="💬 채팅", value="chat"),
    app_commands.Choice(name="🔊 음성", value="voice"),
])
async def level_group_grant(
    interaction: discord.Interaction,
    유저: discord.Member,
    종류: app_commands.Choice[str],
    레벨: int = 0,
    경험치: int = -1,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    table = "voice_levels" if 종류.value == "voice" else "levels"
    if 종류.value == "voice":
        cur_exp, cur_level, _ = get_or_create_voice_level_user(gid, 유저.id)
    else:
        cur_exp, cur_level = get_or_create_level_user(gid, 유저.id)

    new_level = max(1, int(레벨)) if int(레벨) > 0 else int(cur_level)
    new_exp = max(0, int(경험치)) if int(경험치) >= 0 else int(cur_exp)

    c.execute(
        f"UPDATE {table} SET exp=?, level=? WHERE guild_id=? AND user_id=?",
        (new_exp, new_level, gid, 유저.id),
    )
    conn.commit()
    label = "음성" if 종류.value == "voice" else "채팅"
    await interaction.followup.send(
        f"✅ {유저.mention} 님의 {label} 레벨을 **Lv.{new_level}** ({new_exp} EXP) 로 설정했어요.",
        ephemeral=True,
    )
    try:
        await mnb_grant_level_rewards(유저, new_level)
    except Exception:
        pass


@level_group.command(name="초기화", description="레벨 데이터를 초기화합니다. (관리자)")
@app_commands.describe(유저="특정 유저만 초기화 (비우면 서버 전체)", 확인="전체 초기화 시 True 필요")
async def level_group_reset(
    interaction: discord.Interaction, 유저: discord.Member = None, 확인: bool = False
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    if 유저 is not None:
        c.execute("DELETE FROM levels WHERE guild_id=? AND user_id=?", (gid, 유저.id))
        c.execute("DELETE FROM voice_levels WHERE guild_id=? AND user_id=?", (gid, 유저.id))
        conn.commit()
        return await interaction.followup.send(f"🗑️ {유저.mention} 님의 레벨을 초기화했어요.", ephemeral=True)
    if not 확인:
        return await interaction.followup.send(
            "⚠️ 이 서버의 **모든 멤버** 레벨이 초기화됩니다.\n"
            "정말 진행하려면 `/레벨 초기화 확인:True` 로 다시 실행해주세요.",
            ephemeral=True,
        )
    c.execute("DELETE FROM levels WHERE guild_id=?", (gid,))
    c.execute("DELETE FROM voice_levels WHERE guild_id=?", (gid,))
    conn.commit()
    await interaction.followup.send("🗑️ 이 서버의 레벨 데이터를 모두 초기화했어요.", ephemeral=True)


# ==========================================================
# 백업 (채널/역할 구조 저장·복원)
# ==========================================================
def _mnb_serialize_guild(guild: discord.Guild) -> dict:
    """서버의 역할/카테고리/채널 구조를 딕셔너리로 만듭니다."""
    roles = []
    for r in sorted(guild.roles, key=lambda x: x.position, reverse=True):
        if r.is_default() or r.managed:
            continue
        roles.append({
            "name": r.name,
            "color": r.color.value,
            "hoist": bool(r.hoist),
            "mentionable": bool(r.mentionable),
            "permissions": r.permissions.value,
            "position": r.position,
        })

    categories = []
    for cat in sorted(guild.categories, key=lambda x: x.position):
        categories.append({"name": cat.name, "position": cat.position})

    channels = []
    for ch in sorted(guild.channels, key=lambda x: x.position):
        if isinstance(ch, discord.CategoryChannel):
            continue
        kind = "text" if isinstance(ch, discord.TextChannel) else (
            "voice" if isinstance(ch, discord.VoiceChannel) else None
        )
        if kind is None:
            continue
        entry = {
            "name": ch.name,
            "kind": kind,
            "category": ch.category.name if ch.category else None,
            "position": ch.position,
        }
        if kind == "text":
            entry["topic"] = (ch.topic or "")[:500]
            entry["nsfw"] = bool(ch.nsfw)
            entry["slowmode"] = int(ch.slowmode_delay or 0)
        else:
            entry["user_limit"] = int(ch.user_limit or 0)
            entry["bitrate"] = int(ch.bitrate or 64000)
        channels.append(entry)

    return {
        "guild_name": guild.name,
        "roles": roles,
        "categories": categories,
        "channels": channels,
        "saved_at": _mnb_now_str(),
    }


