class MnbBackupRestoreView(discord.ui.View):
    """복원은 되돌릴 수 없으므로 반드시 확인 버튼을 거칩니다."""

    def __init__(self, author_id: int, backup_id: int, data: dict, do_roles: bool, do_channels: bool):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.backup_id = backup_id
        self.data = data
        self.do_roles = do_roles
        self.do_channels = do_channels

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await safe_interaction_send(
                interaction, "❌ 명령어를 실행한 분만 사용할 수 있어요.", ephemeral=True
            )
            return False
        return True

    @discord.ui.button(label="복원 실행", style=discord.ButtonStyle.danger, emoji="♻️")
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        try:
            await interaction.response.edit_message(view=self)
        except discord.HTTPException:
            pass

        guild = interaction.guild
        made_roles = []
        made_cats = []
        made_chans = []
        failed = []

        if self.do_roles:
            existing = {r.name for r in guild.roles}
            # 낮은 위치부터 만들어야 순서가 자연스럽게 쌓입니다.
            for entry in sorted(self.data.get("roles", []), key=lambda x: x.get("position", 0)):
                if entry["name"] in existing:
                    continue
                try:
                    await guild.create_role(
                        name=entry["name"],
                        colour=discord.Colour(int(entry.get("color", 0))),
                        hoist=bool(entry.get("hoist")),
                        mentionable=bool(entry.get("mentionable")),
                        permissions=discord.Permissions(int(entry.get("permissions", 0))),
                        reason=f"백업 복원 · {interaction.user}",
                    )
                    made_roles.append(entry["name"])
                    await asyncio.sleep(0.4)
                except (discord.Forbidden, discord.HTTPException):
                    failed.append(f"역할 {entry['name']}")

        if self.do_channels:
            cat_map = {ca.name: ca for ca in guild.categories}
            for entry in self.data.get("categories", []):
                if entry["name"] in cat_map:
                    continue
                try:
                    newc = await guild.create_category(
                        entry["name"], reason=f"백업 복원 · {interaction.user}"
                    )
                    cat_map[entry["name"]] = newc
                    made_cats.append(entry["name"])
                    await asyncio.sleep(0.4)
                except (discord.Forbidden, discord.HTTPException):
                    failed.append(f"카테고리 {entry['name']}")

            existing_text = {ch.name for ch in guild.text_channels}
            existing_voice = {ch.name for ch in guild.voice_channels}
            for entry in self.data.get("channels", []):
                nm = entry["name"]
                kind = entry.get("kind")
                if kind == "text" and nm in existing_text:
                    continue
                if kind == "voice" and nm in existing_voice:
                    continue
                parent = cat_map.get(entry.get("category")) if entry.get("category") else None
                try:
                    if kind == "text":
                        await guild.create_text_channel(
                            nm,
                            category=parent,
                            topic=entry.get("topic") or None,
                            nsfw=bool(entry.get("nsfw")),
                            slowmode_delay=int(entry.get("slowmode", 0)),
                            reason=f"백업 복원 · {interaction.user}",
                        )
                    else:
                        await guild.create_voice_channel(
                            nm,
                            category=parent,
                            user_limit=int(entry.get("user_limit", 0)) or None,
                            reason=f"백업 복원 · {interaction.user}",
                        )
                    made_chans.append(nm)
                    await asyncio.sleep(0.4)
                except (discord.Forbidden, discord.HTTPException):
                    failed.append(f"채널 {nm}")

        embed = discord.Embed(title="♻️ 복원 완료", color=COLOR_GREEN)
        embed.add_field(
            name=f"만든 역할 ({len(made_roles)})",
            value=", ".join(made_roles)[:1000] if made_roles else "없음 (이미 존재)",
            inline=False,
        )
        embed.add_field(
            name=f"만든 카테고리 ({len(made_cats)})",
            value=", ".join(made_cats)[:1000] if made_cats else "없음 (이미 존재)",
            inline=False,
        )
        embed.add_field(
            name=f"만든 채널 ({len(made_chans)})",
            value=", ".join(made_chans)[:1000] if made_chans else "없음 (이미 존재)",
            inline=False,
        )
        if failed:
            embed.add_field(name="⚠️ 실패", value=", ".join(failed)[:1000], inline=False)
        embed.set_footer(text="만능 봇 | 기존 채널·역할은 지우지 않고 없는 것만 추가합니다")
        try:
            await interaction.followup.send(embed=embed, ephemeral=True)
        except discord.HTTPException:
            pass
        self.stop()

    @discord.ui.button(label="취소", style=discord.ButtonStyle.secondary, emoji="✖️")
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        for child in self.children:
            child.disabled = True
        try:
            await interaction.response.edit_message(view=self)
        except discord.HTTPException:
            pass
        await safe_interaction_send(interaction, "✅ 복원을 취소했어요.", ephemeral=True)
        self.stop()


@backup_group.command(name="복원", description="백업 내용대로 없는 채널·역할을 만듭니다. (관리자)")
@app_commands.describe(
    아이디="복원할 백업 ID",
    역할복원="역할을 복원할지 여부",
    채널복원="카테고리와 채널을 복원할지 여부",
)
async def backup_group_restore(
    interaction: discord.Interaction,
    아이디: int,
    역할복원: bool = True,
    채널복원: bool = True,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    if not 역할복원 and not 채널복원:
        return await interaction.followup.send("❌ 역할 또는 채널 중 하나는 켜주세요.", ephemeral=True)

    c.execute(
        "SELECT name, payload FROM mnb_backups WHERE guild_id=? AND backup_id=?",
        (interaction.guild.id, int(아이디)),
    )
    row = c.fetchone()
    if not row:
        return await interaction.followup.send("❌ 해당 백업을 찾을 수 없어요.", ephemeral=True)
    try:
        data = json.loads(row[1])
    except Exception:
        return await interaction.followup.send("❌ 백업 데이터가 손상되었어요.", ephemeral=True)

    guild = interaction.guild
    existing_roles = {r.name for r in guild.roles}
    existing_cats = {ca.name for ca in guild.categories}
    existing_text = {ch.name for ch in guild.text_channels}
    existing_voice = {ch.name for ch in guild.voice_channels}

    new_roles = [r["name"] for r in data.get("roles", []) if r["name"] not in existing_roles] if 역할복원 else []
    new_cats = [ca["name"] for ca in data.get("categories", []) if ca["name"] not in existing_cats] if 채널복원 else []
    new_chans = []
    if 채널복원:
        for ch in data.get("channels", []):
            if ch.get("kind") == "text" and ch["name"] not in existing_text:
                new_chans.append("#" + ch["name"])
            elif ch.get("kind") == "voice" and ch["name"] not in existing_voice:
                new_chans.append("🔊" + ch["name"])

    if not new_roles and not new_cats and not new_chans:
        return await interaction.followup.send(
            "✅ 백업 내용이 이미 서버에 모두 있어요. 새로 만들 것이 없습니다.", ephemeral=True
        )

    embed = discord.Embed(
        title="♻️ 복원 미리보기",
        description="**기존 채널과 역할은 지우지 않습니다.** 백업에는 있는데 서버에 없는 것만 새로 만듭니다.",
        color=COLOR_WARNING,
    )
    if new_roles:
        embed.add_field(name=f"새로 만들 역할 ({len(new_roles)})", value=", ".join(new_roles)[:1000], inline=False)
    if new_cats:
        embed.add_field(name=f"새로 만들 카테고리 ({len(new_cats)})", value=", ".join(new_cats)[:1000], inline=False)
    if new_chans:
        embed.add_field(name=f"새로 만들 채널 ({len(new_chans)})", value=", ".join(new_chans)[:1000], inline=False)
    embed.set_footer(text=f"만능 봇 | 총 {len(new_roles)+len(new_cats)+len(new_chans)}개 생성 예정")

    view = MnbBackupRestoreView(interaction.user.id, int(아이디), data, 역할복원, 채널복원)
    await interaction.followup.send(embed=embed, view=view, ephemeral=True)


