class MnbFirstComeView(discord.ui.View):
    """먼저 누른 사람 순서대로 보상을 주는 선착순 버튼입니다."""

    def __init__(self, limit: int, reward: int):
        super().__init__(timeout=None)
        self.limit = limit
        self.reward = reward
        self.claimed = []

    @discord.ui.button(label="선착순 참여!", style=discord.ButtonStyle.danger, emoji="⚡")
    async def claim(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id in self.claimed:
            return await safe_interaction_send(interaction, "이미 참여하셨어요!", ephemeral=True)
        if len(self.claimed) >= self.limit:
            return await safe_interaction_send(interaction, "😢 아쉽지만 마감되었어요!", ephemeral=True)

        self.claimed.append(interaction.user.id)
        rank = len(self.claimed)
        gid = interaction.guild.id
        if self.reward > 0:
            set_user_point(gid, interaction.user.id, get_user_point(gid, interaction.user.id) + self.reward)

        if rank >= self.limit:
            button.disabled = True
            button.label = "마감되었습니다"
            try:
                await interaction.response.edit_message(view=self)
            except discord.HTTPException:
                pass
            await safe_interaction_send(
                interaction,
                f"⚡ **{rank}번째**로 성공! 💰 {self.reward:,} 포인트를 받았어요. (마지막 자리!)",
                ephemeral=True,
            )
            try:
                await interaction.followup.send(
                    f"🏁 선착순 마감! 총 {rank}명이 참여했어요.\n"
                    + "\n".join(f"{i}. <@{u}>" for i, u in enumerate(self.claimed, 1))[:1500]
                )
            except discord.HTTPException:
                pass
            self.stop()
            return

        await safe_interaction_send(
            interaction,
            f"⚡ **{rank}번째**로 성공! 💰 {self.reward:,} 포인트를 받았어요. (남은 자리 {self.limit - rank})",
            ephemeral=True,
        )


