@event_group.command(name="랜덤박스", description="하루 한 번 랜덤 보상 상자를 엽니다.")
async def event_group_randombox(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    gid = interaction.guild.id
    uid = interaction.user.id
    today = datetime.datetime.now().strftime("%Y-%m-%d")

    c.execute(
        "SELECT count FROM mnb_event_boxes WHERE guild_id=? AND user_id=? AND open_date=?",
        (gid, uid, today),
    )
    row = c.fetchone()
    if row and int(row[0]) >= 1:
        return await interaction.followup.send("❌ 오늘의 상자는 이미 열었어요. 내일 다시 오세요!")

    # 등급별 확률: 꽝 25% / 일반 45% / 희귀 20% / 전설 10%
    roll = random.random()
    if roll < 0.25:
        grade, emoji, amount, color = "꽝", "💨", 0, COLOR_GRAY
    elif roll < 0.70:
        grade, emoji, amount, color = "일반", "📦", random.randint(100, 500), COLOR_SOFT_SKY
    elif roll < 0.90:
        grade, emoji, amount, color = "희귀", "🎁", random.randint(800, 2000), COLOR_LAVENDER
    else:
        grade, emoji, amount, color = "전설", "💎", random.randint(3000, 10000), COLOR_GOLD

    c.execute(
        "INSERT INTO mnb_event_boxes(guild_id, user_id, open_date, count) VALUES (?, ?, ?, 1) "
        "ON CONFLICT(guild_id, user_id, open_date) DO UPDATE SET count=count+1",
        (gid, uid, today),
    )
    conn.commit()
    if amount > 0:
        set_user_point(gid, uid, get_user_point(gid, uid) + amount)

    embed = discord.Embed(title=f"{emoji} {grade} 상자!", color=color)
    if amount > 0:
        embed.description = f"{interaction.user.mention} 님이 **{amount:,} 포인트**를 획득했어요!"
    else:
        embed.description = f"{interaction.user.mention} 님... 아쉽게도 상자가 비어 있었어요. 내일 다시 도전!"
    embed.set_footer(text="만능 봇 | 랜덤박스는 하루 한 번")
    await interaction.followup.send(embed=embed)


