achievement_group = app_commands.Group(
    name="업적",
    description="서버 전용 커스텀 업적을 만들고 관리합니다.",
)


@achievement_group.command(name="목록", description="이 서버에서 달성할 수 있는 업적을 모두 확인합니다.")
async def achievement_group_list(interaction: discord.Interaction):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    try:
        definitions = get_achievement_definitions(interaction.guild.id)
    except Exception:
        definitions = []
    if not definitions:
        return await interaction.followup.send("📭 등록된 업적이 없어요.")

    basic = [d for d in definitions if not d.get("custom")]
    custom = [d for d in definitions if d.get("custom")]

    embed = discord.Embed(title="🏆 업적 목록", color=COLOR_GOLD)
    if basic:
        embed.add_field(
            name=f"📘 기본 업적 ({len(basic)})",
            value="\n".join(
                f"{d.get('emoji','🏆')} **{d.get('name')}** — {str(d.get('condition',''))[:60]}"
                for d in basic[:15]
            )[:1000],
            inline=False,
        )
    if custom:
        try:
            conds = mnb_get_custom_achievement_conditions(interaction.guild.id)
            stats = mnb_get_achievement_stats_ex(interaction.guild.id, interaction.user.id)
        except Exception:
            conds, stats = {}, {}
        lines = []
        for d in custom[:15]:
            key = str(d.get("key"))
            head = f"{d.get('emoji','🏆')} **{d.get('name')}** `{key}`"
            ctype, cvalue = conds.get(key, ("manual", 0))
            if ctype == "manual":
                lines.append(head + f"\n　{str(d.get('condition',''))[:60]} · ✋ 수동")
                continue
            label, unit = MNB_ACHIEVEMENT_CONDITIONS.get(ctype, (ctype, ""))
            prog = mnb_achievement_progress(ctype, cvalue, stats)
            if prog:
                cur, need = prog
                done = "✅" if cur >= need else "🔒"
                lines.append(head + f"\n　{done} {label} {min(cur, need):,}/{need:,}{unit}")
            else:
                lines.append(head + f"\n　{label} {cvalue:,}{unit}")
        embed.add_field(
            name=f"⭐ 서버 전용 업적 ({len(custom)})",
            value="\n".join(lines)[:1000],
            inline=False,
        )
    else:
        embed.add_field(
            name="⭐ 서버 전용 업적",
            value="아직 없어요. `/업적 추가` 로 만들 수 있습니다.",
            inline=False,
        )
    embed.set_footer(text="만능 봇 | 업적")
    await interaction.followup.send(embed=embed)


@achievement_group.command(name="추가", description="서버 전용 업적을 만듭니다. (관리자)")
@app_commands.describe(
    키="업적 구분용 영문/숫자 키 (예: first_win)",
    이름="업적 이름",
    조건="달성 조건 설명",
    조건종류="자동 달성 조건 (수동 지급이면 그대로 두세요)",
    목표값="조건 달성에 필요한 숫자 (예: 레벨 10 → 10)",
    이모지="업적 아이콘 (기본 🏆)",
    보상포인트="달성 시 지급할 포인트",
    보상칭호="달성 시 지급할 칭호 (선택)",
)
@app_commands.choices(조건종류=[
    app_commands.Choice(name="✋ 수동 지급", value="manual"),
    app_commands.Choice(name="📊 채팅 레벨 도달", value="level"),
    app_commands.Choice(name="🔊 음성 레벨 도달", value="voice_level"),
    app_commands.Choice(name="💰 포인트 보유", value="point"),
    app_commands.Choice(name="📅 누적 출석 일수", value="attendance"),
    app_commands.Choice(name="🔥 연속 출석 일수", value="streak"),
    app_commands.Choice(name="💬 누적 메시지 수", value="message"),
    app_commands.Choice(name="🎧 누적 통화 시간(시간)", value="voice_time"),
    app_commands.Choice(name="🔗 초대한 인원", value="invite"),
])
async def achievement_group_add(
    interaction: discord.Interaction,
    키: str,
    이름: str,
    조건: str,
    조건종류: app_commands.Choice[str] = None,
    목표값: int = 0,
    이모지: str = "🏆",
    보상포인트: int = 0,
    보상칭호: str = "",
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)

    key = re.sub(r"[^a-zA-Z0-9_]", "", (키 or "").strip())[:40]
    if not key:
        return await interaction.followup.send(
            "❌ 키는 영문/숫자/밑줄만 쓸 수 있어요. (예: `first_win`)", ephemeral=True
        )

    # 기본 업적 키와 겹치면 덮어써 버리므로 막습니다.
    try:
        reserved = {str(d.get("key")) for d in ACHIEVEMENT_DEFINITIONS}
    except Exception:
        reserved = set()
    if key in reserved:
        return await interaction.followup.send(
            f"❌ `{key}` 는 기본 업적에서 이미 쓰는 키예요. 다른 키를 써주세요.", ephemeral=True
        )

    ctype = 조건종류.value if 조건종류 else "manual"
    cvalue = max(0, int(목표값))
    if ctype != "manual" and cvalue <= 0:
        return await interaction.followup.send(
            "❌ 자동 달성 조건을 고르셨으면 **목표값**도 1 이상으로 정해주세요.\n"
            "예) 조건종류 `채팅 레벨 도달` + 목표값 `10`",
            ephemeral=True,
        )

    c.execute(
        "INSERT INTO custom_achievements(guild_id, achievement_key, name, emoji, condition_text, "
        "reward_point, reward_item, reward_item_amount, reward_title, is_active, created_at, "
        "condition_type, condition_value) "
        "VALUES (?, ?, ?, ?, ?, ?, '', 0, ?, 1, ?, ?, ?) "
        "ON CONFLICT(guild_id, achievement_key) DO UPDATE SET "
        "name=excluded.name, emoji=excluded.emoji, condition_text=excluded.condition_text, "
        "reward_point=excluded.reward_point, reward_title=excluded.reward_title, is_active=1, "
        "condition_type=excluded.condition_type, condition_value=excluded.condition_value",
        (
            interaction.guild.id, key, (이름 or "")[:60], (이모지 or "🏆")[:8],
            (조건 or "")[:200], max(0, int(보상포인트)),
            normalize_title_name(보상칭호) if 보상칭호 else "",
            _mnb_now_str(), ctype, cvalue,
        ),
    )
    conn.commit()

    embed = discord.Embed(title="✅ 업적 등록 완료", color=COLOR_GREEN)
    embed.add_field(name="업적", value=f"{(이모지 or '🏆')} **{이름}**", inline=False)
    embed.add_field(name="키", value=f"`{key}`", inline=True)
    embed.add_field(name="조건", value=(조건 or "")[:200], inline=False)
    if ctype != "manual":
        label, unit = MNB_ACHIEVEMENT_CONDITIONS.get(ctype, (ctype, ""))
        embed.add_field(name="자동 달성", value=f"{label} **{cvalue:,}{unit}**", inline=True)
    else:
        embed.add_field(name="자동 달성", value="✋ 수동 지급", inline=True)
    if int(보상포인트) > 0:
        embed.add_field(name="보상 포인트", value=f"💰 {int(보상포인트):,} P", inline=True)
    if 보상칭호:
        embed.add_field(name="보상 칭호", value=f"`{normalize_title_name(보상칭호)}`", inline=True)
    embed.set_footer(text="만능 봇 | /업적 지급 으로 달성 처리할 수 있어요")
    await interaction.followup.send(embed=embed, ephemeral=True)


