@achievement_group.command(name="지급", description="유저에게 업적 달성을 직접 부여합니다. (관리자)")
@app_commands.describe(유저="대상 유저", 키="업적 키")
async def achievement_group_grant(interaction: discord.Interaction, 유저: discord.Member, 키: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    gid = interaction.guild.id
    key = (키 or "").strip()

    try:
        definitions = {str(d.get("key")): d for d in get_achievement_definitions(gid)}
    except Exception:
        definitions = {}
    if key not in definitions:
        return await interaction.followup.send(
            f"❌ `{key}` 업적을 찾을 수 없어요. `/업적 목록` 에서 키를 확인해주세요.", ephemeral=True
        )

    c.execute(
        "SELECT 1 FROM achievement_claims WHERE guild_id=? AND user_id=? AND achievement_key=?",
        (gid, 유저.id, key),
    )
    if c.fetchone():
        return await interaction.followup.send(
            f"ℹ️ {유저.mention} 님은 이미 이 업적을 달성했어요.", ephemeral=True
        )

    c.execute(
        "INSERT OR IGNORE INTO achievement_claims(guild_id, user_id, achievement_key, claimed_at) "
        "VALUES (?, ?, ?, ?)",
        (gid, 유저.id, key, _mnb_now_str()),
    )
    conn.commit()

    d = definitions[key]
    point = int(d.get("reward_point") or 0)
    if point > 0:
        set_user_point(gid, 유저.id, get_user_point(gid, 유저.id) + point)

    embed = discord.Embed(
        title="🏆 업적 달성!",
        description=f"{유저.mention} 님이 **{d.get('emoji','🏆')} {d.get('name')}** 업적을 달성했어요!",
        color=COLOR_GOLD,
    )
    if point > 0:
        embed.add_field(name="보상", value=f"💰 {point:,} 포인트", inline=True)
    embed.set_footer(text="만능 봇 | 업적")
    try:
        await interaction.channel.send(embed=embed)
    except Exception:
        pass
    await interaction.followup.send(f"✅ {유저.mention} 님에게 업적을 지급했어요.", ephemeral=True)


