@mod_group.command(name="금지어추가", description="자동 필터에 걸릴 단어를 추가합니다. (관리자)")
@app_commands.describe(단어="추가할 금지어 (쉼표로 여러 개 가능)")
async def mod_group_filter_add(interaction: discord.Interaction, 단어: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    words = [w.strip() for w in (단어 or "").split(",") if w.strip()][:20]
    if not words:
        return await interaction.followup.send("❌ 추가할 단어를 입력해주세요.", ephemeral=True)
    added, skipped = [], []
    for w in words:
        try:
            if add_custom_filter_word(interaction.guild.id, w, interaction.user.id):
                added.append(w)
            else:
                skipped.append(w)
        except Exception:
            skipped.append(w)
    msg = ""
    if added:
        msg += f"✅ 추가 ({len(added)}개): " + ", ".join(f"`{w}`" for w in added) + "\n"
    if skipped:
        msg += f"ℹ️ 이미 있음 ({len(skipped)}개): " + ", ".join(f"`{w}`" for w in skipped)
    await interaction.followup.send(msg[:1900] or "변경된 내용이 없어요.", ephemeral=True)


