# ==========================================================
# 통계 보강 (명령어 사용 통계)
# ==========================================================
@stats_group.command(name="명령어", description="가장 많이 쓰인 명령어 순위를 확인합니다.")
@app_commands.describe(일수="집계 기간 (기본 7일, 최대 90일)")
async def stats_group_commands(interaction: discord.Interaction, 일수: int = 7):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    days = max(1, min(90, int(일수)))
    since = (datetime.datetime.now() - datetime.timedelta(days=days - 1)).strftime("%Y-%m-%d")
    try:
        c.execute(
            "SELECT command_name, COUNT(*) FROM command_usage_logs "
            "WHERE guild_id=? AND created_at>=? GROUP BY command_name "
            "ORDER BY COUNT(*) DESC LIMIT 15",
            (interaction.guild.id, since),
        )
        rows = c.fetchall()
    except Exception:
        rows = []
    if not rows:
        return await interaction.followup.send("📭 아직 집계된 명령어 사용 기록이 없어요.")
    mx = int(rows[0][1])
    embed = discord.Embed(title=f"⌨️ 명령어 사용 순위 (최근 {days}일)", color=COLOR_MINT)
    embed.description = "\n".join(
        f"**{i}.** `/{nm}` {_mnb_bar(int(n), mx)} `{int(n):,}회`"
        for i, (nm, n) in enumerate(rows, 1)
    )[:4000]
    total = sum(int(n) for _, n in rows)
    embed.set_footer(text=f"만능 봇 | 상위 {len(rows)}개 · 합계 {total:,}회")
    await interaction.followup.send(embed=embed)


@stats_group.command(name="성장", description="멤버 수 증감 추이를 확인합니다.")
@app_commands.describe(일수="집계 기간 (기본 14일, 최대 60일)")
async def stats_group_growth(interaction: discord.Interaction, 일수: int = 14):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    days = max(1, min(60, int(일수)))
    since = (datetime.datetime.now() - datetime.timedelta(days=days - 1)).strftime("%Y-%m-%d")
    c.execute(
        "SELECT stat_date, joins, leaves FROM mnb_stat_joins WHERE guild_id=? AND stat_date>=? "
        "ORDER BY stat_date",
        (interaction.guild.id, since),
    )
    rows = c.fetchall()
    if not rows:
        return await interaction.followup.send(
            "📭 아직 집계된 입퇴장 기록이 없어요. (기능 추가 이후부터 쌓입니다)"
        )
    total_j = sum(int(j or 0) for _, j, _ in rows)
    total_l = sum(int(l or 0) for _, _, l in rows)
    mx = max(max(int(j or 0), int(l or 0)) for _, j, l in rows) or 1
    lines = []
    for d, j, l in rows[-20:]:
        j, l = int(j or 0), int(l or 0)
        lines.append(f"`{d[5:]}` +{j:<3} -{l:<3} {_mnb_bar(j, mx, 8)}│{_mnb_bar(l, mx, 8)}")
    net = total_j - total_l
    embed = discord.Embed(
        title=f"📈 멤버 성장 추이 (최근 {days}일)",
        color=COLOR_GREEN if net >= 0 else COLOR_WARNING,
    )
    embed.add_field(name="입장", value=f"+{total_j:,}명", inline=True)
    embed.add_field(name="퇴장", value=f"-{total_l:,}명", inline=True)
    embed.add_field(name="순증감", value=f"{net:+,}명", inline=True)
    embed.add_field(name="현재 멤버", value=f"{interaction.guild.member_count:,}명", inline=True)
    if total_j:
        embed.add_field(name="잔존율", value=f"{max(0, total_j - total_l) * 100 // total_j}%", inline=True)
    embed.add_field(name="일별 (입장│퇴장)", value="\n".join(lines)[:1000], inline=False)
    embed.set_footer(text="만능 봇 | 성장 통계")
    await interaction.followup.send(embed=embed)


