MNB_POLL_EMOJIS = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]


def _mnb_poll_counts(poll_id: int, option_count: int):
    counts = [0] * option_count
    try:
        c.execute(
            "SELECT choice, COUNT(*) FROM mnb_poll_votes WHERE poll_id=? GROUP BY choice",
            (poll_id,),
        )
        for choice, n in c.fetchall():
            idx = int(choice)
            if 0 <= idx < option_count:
                counts[idx] = int(n)
    except Exception:
        pass
    return counts


def _mnb_poll_embed(poll_id: int, question: str, options: list, anonymous: bool,
                    multi: bool, closed: bool, ends_at: str = ""):
    counts = _mnb_poll_counts(poll_id, len(options))
    total = sum(counts) or 0
    lines = []
    for i, opt in enumerate(options):
        n = counts[i]
        pct = (n * 100 // total) if total else 0
        filled = (pct * 10) // 100
        bar = "█" * filled + "░" * (10 - filled)
        lines.append(f"{MNB_POLL_EMOJIS[i]} **{opt}**\n　`{bar}` {n}표 ({pct}%)")

    embed = discord.Embed(
        title=("📊 " if not closed else "🔒 ") + question[:240],
        description="\n".join(lines)[:3500],
        color=COLOR_LAVENDER if not closed else COLOR_GRAY,
    )
    tags = []
    tags.append("🕵️ 익명" if anonymous else "👁️ 공개")
    tags.append("☑️ 복수 선택" if multi else "1️⃣ 단일 선택")
    if closed:
        tags.append("🔒 종료됨")
    elif ends_at:
        tags.append(f"⏰ {ends_at} 마감")
    embed.add_field(name="설정", value=" · ".join(tags), inline=False)
    embed.set_footer(text=f"만능 봇 | 투표 ID {poll_id} · 총 {total}표")
    return embed


class MnbPollView(discord.ui.View):
    """투표 버튼입니다. 봇이 재시작돼도 동작하도록 DB에서 상태를 읽습니다."""

    def __init__(self, poll_id: int, options: list, multi: bool):
        super().__init__(timeout=None)
        self.poll_id = poll_id
        self.options = options
        self.multi = multi
        for i, opt in enumerate(options[:10]):
            btn = discord.ui.Button(
                label=str(opt)[:60],
                emoji=MNB_POLL_EMOJIS[i],
                style=discord.ButtonStyle.secondary,
                custom_id=f"mnb_poll:{poll_id}:{i}",
                row=i // 5,
            )
            btn.callback = self._make_callback(i)
            self.add_item(btn)

        end_btn = discord.ui.Button(
            label="투표 종료",
            emoji="🔒",
            style=discord.ButtonStyle.danger,
            custom_id=f"mnb_poll_end:{poll_id}",
            row=min(4, (len(options[:10]) - 1) // 5 + 1),
        )
        end_btn.callback = self._end_callback
        self.add_item(end_btn)

    def _make_callback(self, index: int):
        async def callback(interaction: discord.Interaction):
            await self._vote(interaction, index)
        return callback

    async def _vote(self, interaction: discord.Interaction, index: int):
        c.execute(
            "SELECT closed, multi, anonymous, question, options, ends_at FROM mnb_polls WHERE poll_id=?",
            (self.poll_id,),
        )
        row = c.fetchone()
        if not row:
            return await safe_interaction_send(interaction, "❌ 투표를 찾을 수 없어요.", ephemeral=True)
        if int(row[0]):
            return await safe_interaction_send(interaction, "🔒 이미 종료된 투표예요.", ephemeral=True)

        multi = bool(int(row[1]))
        uid = interaction.user.id

        c.execute(
            "SELECT choice FROM mnb_poll_votes WHERE poll_id=? AND user_id=?",
            (self.poll_id, uid),
        )
        mine = {int(r[0]) for r in c.fetchall()}

        if index in mine:
            c.execute(
                "DELETE FROM mnb_poll_votes WHERE poll_id=? AND user_id=? AND choice=?",
                (self.poll_id, uid, index),
            )
            msg = f"↩️ **{self.options[index]}** 선택을 취소했어요."
        else:
            if not multi and mine:
                c.execute(
                    "DELETE FROM mnb_poll_votes WHERE poll_id=? AND user_id=?",
                    (self.poll_id, uid),
                )
            c.execute(
                "INSERT OR IGNORE INTO mnb_poll_votes(poll_id, user_id, choice, voted_at) VALUES (?, ?, ?, ?)",
                (self.poll_id, uid, index, _mnb_now_str()),
            )
            msg = f"✅ **{self.options[index]}** 에 투표했어요!"
        conn.commit()

        options = json.loads(row[4])
        embed = _mnb_poll_embed(
            self.poll_id, row[3], options, bool(int(row[2])), multi, False, str(row[5] or "")
        )
        try:
            await interaction.response.edit_message(embed=embed, view=self)
        except discord.HTTPException:
            pass
        try:
            await interaction.followup.send(msg, ephemeral=True)
        except discord.HTTPException:
            pass

    async def _end_callback(self, interaction: discord.Interaction):
        c.execute(
            "SELECT author_id, question, options, anonymous, multi, closed FROM mnb_polls WHERE poll_id=?",
            (self.poll_id,),
        )
        row = c.fetchone()
        if not row:
            return await safe_interaction_send(interaction, "❌ 투표를 찾을 수 없어요.", ephemeral=True)
        if int(row[5]):
            return await safe_interaction_send(interaction, "🔒 이미 종료된 투표예요.", ephemeral=True)

        is_author = int(row[0]) == interaction.user.id
        is_manager = interaction.user.guild_permissions.manage_guild
        if not (is_author or is_manager):
            return await safe_interaction_send(
                interaction, "❌ 투표를 만든 분이나 서버 관리자만 종료할 수 있어요.", ephemeral=True
            )

        c.execute("UPDATE mnb_polls SET closed=1 WHERE poll_id=?", (self.poll_id,))
        conn.commit()

        options = json.loads(row[2])
        for child in self.children:
            child.disabled = True
        embed = _mnb_poll_embed(
            self.poll_id, row[1], options, bool(int(row[3])), bool(int(row[4])), True
        )
        try:
            await interaction.response.edit_message(embed=embed, view=self)
        except discord.HTTPException:
            pass

        counts = _mnb_poll_counts(self.poll_id, len(options))
        total = sum(counts)
        if total:
            best = max(range(len(options)), key=lambda i: counts[i])
            tied = [i for i in range(len(options)) if counts[i] == counts[best]]
            if len(tied) > 1:
                result = "🤝 동점: " + ", ".join(f"**{options[i]}**" for i in tied)
            else:
                result = f"🏆 1위: **{options[best]}** ({counts[best]}표)"
        else:
            result = "투표한 사람이 없어요."
        try:
            await interaction.followup.send(f"🔒 투표가 종료되었습니다.\n{result}")
        except discord.HTTPException:
            pass
        self.stop()


poll_group = app_commands.Group(
    name="투표",
    description="버튼으로 참여하는 투표를 만들고 결과를 확인합니다.",
)


@poll_group.command(name="시작", description="버튼으로 참여하는 투표를 만듭니다.")
@app_commands.describe(
    질문="투표 질문",
    선택지="쉼표(,)로 구분해서 2~10개",
    익명="True 면 누가 뭘 골랐는지 공개하지 않습니다",
    복수선택="True 면 여러 개를 고를 수 있습니다",
    시간="자동 마감 시간(분, 0=수동 종료)",
)
async def poll_group_start(
    interaction: discord.Interaction,
    질문: str,
    선택지: str,
    익명: bool = False,
    복수선택: bool = False,
    시간: int = 0,
):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)

    options = [o.strip() for o in (선택지 or "").split(",") if o.strip()][:10]
    if len(options) < 2:
        return await interaction.followup.send(
            "❌ 선택지를 쉼표로 구분해서 2개 이상 입력해주세요.\n예) `짜장,짬뽕,볶음밥`"
        )

    ends_at = ""
    if int(시간) > 0:
        minutes = min(int(시간), 10080)  # 최대 7일
        ends_at = (datetime.datetime.now() + datetime.timedelta(minutes=minutes)).strftime("%Y-%m-%d %H:%M")

    c.execute(
        "INSERT INTO mnb_polls(guild_id, channel_id, message_id, author_id, question, options, "
        "anonymous, multi, closed, ends_at, created_at) VALUES (?, ?, 0, ?, ?, ?, ?, ?, 0, ?, ?)",
        (
            interaction.guild.id, interaction.channel.id, interaction.user.id,
            질문[:240], json.dumps(options, ensure_ascii=False),
            int(bool(익명)), int(bool(복수선택)), ends_at, _mnb_now_str(),
        ),
    )
    conn.commit()
    poll_id = c.lastrowid

    embed = _mnb_poll_embed(poll_id, 질문[:240], options, bool(익명), bool(복수선택), False, ends_at)
    view = MnbPollView(poll_id, options, bool(복수선택))
    msg = await interaction.followup.send(embed=embed, view=view)
    try:
        c.execute("UPDATE mnb_polls SET message_id=? WHERE poll_id=?", (msg.id, poll_id))
        conn.commit()
    except Exception:
        pass


@poll_group.command(name="결과", description="투표 결과를 자세히 확인합니다.")
@app_commands.describe(아이디="투표 ID")
async def poll_group_result(interaction: discord.Interaction, 아이디: int):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction)
    c.execute(
        "SELECT question, options, anonymous, multi, closed, ends_at FROM mnb_polls "
        "WHERE poll_id=? AND guild_id=?",
        (int(아이디), interaction.guild.id),
    )
    row = c.fetchone()
    if not row:
        return await interaction.followup.send("❌ 해당 투표를 찾을 수 없어요.")
    options = json.loads(row[1])
    anonymous = bool(int(row[2]))
    embed = _mnb_poll_embed(
        int(아이디), row[0], options, anonymous, bool(int(row[3])), bool(int(row[4])), str(row[5] or "")
    )

    # 익명 투표는 누가 뭘 골랐는지 절대 공개하지 않습니다.
    if not anonymous:
        c.execute(
            "SELECT choice, user_id FROM mnb_poll_votes WHERE poll_id=? ORDER BY choice",
            (int(아이디),),
        )
        by_choice = {}
        for ch, uid in c.fetchall():
            by_choice.setdefault(int(ch), []).append(int(uid))
        if by_choice:
            lines = []
            for i, opt in enumerate(options):
                voters = by_choice.get(i, [])
                if voters:
                    lines.append(
                        f"{MNB_POLL_EMOJIS[i]} **{opt}**: "
                        + ", ".join(f"<@{u}>" for u in voters[:15])
                        + (f" 외 {len(voters)-15}명" if len(voters) > 15 else "")
                    )
            if lines:
                embed.add_field(name="투표한 사람", value="\n".join(lines)[:1000], inline=False)
    else:
        embed.add_field(name="투표한 사람", value="🕵️ 익명 투표라 공개하지 않아요.", inline=False)

    await interaction.followup.send(embed=embed)


