@poll_group.command(name="종료", description="진행 중인 투표를 종료합니다.")
@app_commands.describe(아이디="종료할 투표 ID")
async def poll_group_close(interaction: discord.Interaction, 아이디: int):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    await safe_interaction_defer(interaction, ephemeral=True)
    c.execute(
        "SELECT author_id, question, options, anonymous, multi, closed FROM mnb_polls "
        "WHERE poll_id=? AND guild_id=?",
        (int(아이디), interaction.guild.id),
    )
    row = c.fetchone()
    if not row:
        return await interaction.followup.send("❌ 해당 투표를 찾을 수 없어요.", ephemeral=True)
    if int(row[5]):
        return await interaction.followup.send("🔒 이미 종료된 투표예요.", ephemeral=True)
    if int(row[0]) != interaction.user.id and not interaction.user.guild_permissions.manage_guild:
        return await interaction.followup.send(
            "❌ 투표를 만든 분이나 서버 관리자만 종료할 수 있어요.", ephemeral=True
        )
    c.execute("UPDATE mnb_polls SET closed=1 WHERE poll_id=?", (int(아이디),))
