@autoresponse_group.command(name="테스트", description="어떤 문장이 어떤 자동응답에 걸리는지 확인합니다. (관리자)")
@app_commands.describe(문장="테스트할 문장")
async def autoresponse_group_test(interaction: discord.Interaction, 문장: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    text = (문장 or "").strip()
    lowered = text.lower()
    with DB_MUTEX:
        c.execute(
            "SELECT trigger, response, match_type, COALESCE(chance,100), COALESCE(enabled,1), "
            "COALESCE(reaction,'') FROM custom_responses WHERE guild_id=?",
            (interaction.guild.id,),
        )
        rows = c.fetchall()

    hits = []
    for trig, resp, mt, chance, enabled, reaction in rows:
        target = text if str(mt) == "regex" else lowered
        if _mnb_response_matches(str(mt), str(trig), target):
            hits.append((str(trig), str(resp or ""), str(mt), int(chance), int(enabled), str(reaction or "")))

    if not hits:
        return await interaction.followup.send(
            f"🔍 `{text[:100]}` 에 걸리는 자동응답이 없어요.", ephemeral=True
        )

    lines = []
    for i, (trig, resp, mt, chance, enabled, reaction) in enumerate(hits, 1):
        mark = "✅" if enabled else "⏸️"
        first = " (첫 번째로 발동)" if i == 1 and enabled else ""
        detail = f"{mark} `{trig}` — {MNB_MATCH_LABELS.get(mt, mt)}"
        if chance < 100:
            detail += f" · {chance}%"
        detail += first
        if resp:
            parts = [p.strip() for p in resp.split("|") if p.strip()]
            detail += f"\n　→ {parts[0][:80]}" + (f" 외 {len(parts)-1}개" if len(parts) > 1 else "")
        if reaction:
            detail += f"\n　→ 반응 {reaction}"
        lines.append(detail)

    embed = discord.Embed(
        title="🔍 자동응답 테스트",
        description=f"입력: `{text[:200]}`\n\n" + "\n\n".join(lines)[:3500],
        color=COLOR_MINT,
    )
    embed.set_footer(text=f"만능 봇 | {len(hits)}개 일치 · 실제로는 맨 위 하나만 발동합니다")
    await interaction.followup.send(embed=embed, ephemeral=True)


@autoresponse_group.command(name="초기화", description="이 서버의 자동응답을 모두 삭제합니다. (관리자)")
@app_commands.describe(확인="정말 삭제하려면 True 로 설정하세요")
async def autoresponse_group_reset(interaction: discord.Interaction, 확인: bool = False):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있어요.", ephemeral=True)
    if await reject_if_not_setup_manager(interaction):
        return
    await safe_interaction_defer(interaction, ephemeral=True)
    with DB_MUTEX:
        c.execute("SELECT COUNT(*) FROM custom_responses WHERE guild_id=?", (interaction.guild.id,))
        total = int((c.fetchone() or [0])[0])
    if total == 0:
        return await interaction.followup.send("📭 삭제할 자동응답이 없어요.", ephemeral=True)
    if not 확인:
        return await interaction.followup.send(
            f"⚠️ 자동응답 **{total}개**가 모두 삭제됩니다.\n"
            f"정말 진행하려면 `/자동응답 초기화 확인:True` 로 다시 실행해주세요.",
            ephemeral=True,
        )
    with DB_MUTEX:
        c.execute("DELETE FROM custom_responses WHERE guild_id=?", (interaction.guild.id,))
        conn.commit()
    await interaction.followup.send(f"🗑️ 자동응답 {total}개를 모두 삭제했어요.", ephemeral=True)


