_MNB_V213_LEGACY_ON_MESSAGE = _mnb_legacy_on_message


# =========================
# 보물찾기 — 채팅 중 낮은 확률로 보물 상자가 등장, 먼저 버튼을 누른 사람이 획득
# =========================
TREASURE_SPAWN_CHANCE = 0.02          # 메시지당 등장 확률 (2%)
TREASURE_CHANNEL_COOLDOWN = 180       # 같은 채널 재등장 최소 간격(초)
TREASURE_MIN_MEMBERS_MSG_LEN = 2      # 너무 짧은 메시지(도배)는 트리거 제외
_treasure_last_spawn = {}             # {channel_id: timestamp}
TREASURE_REWARDS = [
    ("💰", "포인트 한 줌", "point", 200),
    ("💰", "두둑한 포인트", "point", 500),
    ("💎", "보석 무더기", "point", 1000),
    ("🎁", "랜덤박스", "item", "랜덤박스"),
    ("🎫", "상점할인권", "item", "상점할인권"),
]


class TreasureChestView(discord.ui.View):
    def __init__(self, guild_id: int, reward):
        super().__init__(timeout=60)
        self.guild_id = guild_id
        self.reward = reward
        self.claimed = False

    @discord.ui.button(label="보물 줍기!", emoji="🪙", style=discord.ButtonStyle.success)
    async def claim(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.claimed:
            return await interaction.response.send_message("😢 아쉽지만 이미 다른 사람이 주웠어요!", ephemeral=True)
        self.claimed = True
        emoji, label, rtype, value = self.reward
        uid = interaction.user.id
        if rtype == "point":
            set_user_point(self.guild_id, uid, get_user_point(self.guild_id, uid) + value)
            got = f"💰 **{value:,}P**"
        else:
            add_inventory_item(uid, value, 1, guild_id=self.guild_id)
            got = f"{emoji} **{value} 1개**"
        button.disabled = True
        button.label = f"{interaction.user.display_name} 님이 획득!"
        try:
            await interaction.response.edit_message(view=self)
        except discord.HTTPException:
            pass
        await interaction.followup.send(f"🎉 {interaction.user.mention} 님이 {label}을(를) 주웠어요! {got}", ephemeral=False)
        self.stop()

    async def on_timeout(self):
        for child in self.children:
            child.disabled = True


async def maybe_spawn_treasure(message: discord.Message):
    """채팅 메시지에 반응해 낮은 확률로 보물 상자를 띄웁니다."""
    try:
        if message.guild is None or message.author.bot:
            return
        if not message.content or len(message.content.strip()) < TREASURE_MIN_MEMBERS_MSG_LEN:
            return
        if random.random() >= TREASURE_SPAWN_CHANCE:
            return
        now_ts = datetime.datetime.now().timestamp()
        last = _treasure_last_spawn.get(message.channel.id, 0)
        if now_ts - last < TREASURE_CHANNEL_COOLDOWN:
            return
        # 봇이 메시지를 보낼 수 있는지 확인
        perms = message.channel.permissions_for(message.guild.me)
        if not perms.send_messages:
            return
        _treasure_last_spawn[message.channel.id] = now_ts

        reward = random.choice(TREASURE_REWARDS)
        emoji, label, _, _ = reward
        embed = discord.Embed(
            title=f"{emoji} 보물 상자가 나타났다!",
            description="가장 먼저 **보물 줍기!** 버튼을 누른 사람이 보상을 가져가요! (60초)",
            color=0xF1C40F,
        )
        embed.set_footer(text="만능 봇 | 보물찾기")
        await message.channel.send(embed=embed, view=TreasureChestView(message.guild.id, reward))
    except Exception:
        pass


@bot.event
async def on_message(message: discord.Message):
    # 같은 메시지가 2번 처리되는 경우를 먼저 차단합니다.
    if not mnb_v213_claim_message(message):
        return
    # 제재되어 메시지가 삭제되면 이후 처리를 건너뜁니다.
    try:
        if message.guild is not None and not message.author.bot:
            await mnb_moderation_check(message)
            mnb_record_message_stat(message)
            await mnb_wordchain_check(message)
    except Exception:
        pass
    if _MNB_V213_LEGACY_ON_MESSAGE:
        await _MNB_V213_LEGACY_ON_MESSAGE(message)
    await maybe_spawn_treasure(message)
    await handle_custom_response(message)


@bot.event
async def on_ready():
    global MNB_V213_READY_DONE, MNB_V212_BOOTSTRAPPED, MNB_ON_READY_RAN_ONCE
    async with mnb_v213_get_ready_lock():
        if MNB_V213_READY_DONE:
            mnb_v213_start_background_loops_once()
            return
        MNB_V213_READY_DONE = True
        MNB_V212_BOOTSTRAPPED = True
        MNB_ON_READY_RAN_ONCE = True

        mnb_v210_register_required_commands(force=True)
        mnb_v213_register_persistent_views_once()
        mnb_v213_start_background_loops_once()

        for _g in list(bot.guilds):
            try:
                await mnb_sync_invite_cache(_g)
            except Exception:
                pass

        try:
            await mnb_restore_poll_views()
        except Exception:
            pass

        sync_results = await mnb_sync_commands_guild_only("startup_v214")
        try:
            slash_count = max((count for _, count, _ in sync_results), default=0)
            if slash_count <= 0:
                # 이미 동기화가 끝난 재호출이면 현재 로컬 명령어 개수로 표시합니다.
                slash_count = len([cmd for cmd in bot.tree.get_commands(guild=None) if getattr(cmd, "name", "") not in MNB_REMOVED_TOP_LEVEL_COMMAND_NAMES])
            print(f"✅ 슬래시 명령어 동기화: {slash_count}개")
        except Exception:
            print("✅ 슬래시 명령어 동기화: 완료")
        print(f"✅ 로그인 완료: {bot.user}")

        for guild in list(bot.guilds):
            if guild.id in MNB_V213_SHOP_PANEL_GUILDS:
                continue
            MNB_V213_SHOP_PANEL_GUILDS.add(guild.id)
            try:
                shop_result = await ensure_integrated_shop_panel_for_guild(guild, create_missing=not (MNB_FREE_CHANNEL_MODE and MNB_SHOP_CURRENT_CHANNEL_MODE))
                if shop_result.get("panel_changed"):
                    channel = shop_result.get("channel")
                    pass
            except Exception as e:
                print(f"⚠️ {guild.name} 통합상점 자동 생성 실패: {e}")

        for guild in list(bot.guilds):
            if guild.id in MNB_V213_DEVLOG_GUILDS:
                continue
            MNB_V213_DEVLOG_GUILDS.add(guild.id)
            try:
                devlog_result = await ensure_development_log_channels(guild)
                created_count = len(devlog_result.get("created", [])) if isinstance(devlog_result, dict) else 0
                updated_count = len(devlog_result.get("updated", [])) if isinstance(devlog_result, dict) else 0
                if created_count or updated_count:
                    pass
            except Exception as e:
                print(f"⚠️ {guild.name} 개발로그 자동 생성/복구 실패: {e}")

        for guild in list(bot.guilds):
            if guild.id in MNB_V213_INVITE_CACHE_GUILDS:
                continue
            MNB_V213_INVITE_CACHE_GUILDS.add(guild.id)
            try:
                await refresh_invite_cache(guild)
            except Exception:
                pass


# =========================
# - 처음 온 유저가 헷갈리지 않게 /가이드, /빠른메뉴 추가
