# - 버튼은 재시작 후에도 다시 연결되도록 persistent view로 등록


def mnb_v227_is_admin_member(member) -> bool:
    try:
        if getattr(member.guild_permissions, "administrator", False):
            return True
    except Exception:
        pass
    try:
        return bool(asyncio.iscoroutinefunction(can_use_setup_commands)) and False
    except Exception:
        return False


async def mnb_v227_can_manage_server(member) -> bool:
    try:
        if getattr(member.guild_permissions, "administrator", False):
            return True
    except Exception:
        pass
    try:
        return await can_use_setup_commands(member)
    except Exception:
        return False


def mnb_v227_channel_mention(guild: discord.Guild, channel_id: int, fallback: str = "아직 설정 안 됨") -> str:
    try:
        channel_id = int(channel_id or 0)
    except (TypeError, ValueError):
        channel_id = 0
    if guild and channel_id:
        ch = guild.get_channel(channel_id)
        if ch:
            return ch.mention
    return fallback


def mnb_v227_get_settings_row(guild_id: int):
    try:
        ensure_dashboard_sync_tables()
        c.execute("SELECT * FROM guild_settings WHERE guild_id=?", (int(guild_id),))
        row = c.fetchone()
        columns = [desc[0] for desc in c.description] if c.description else []
        if row:
            return dict(zip(columns, row))
    except Exception:
        return {}
    return {}


