@bot.command(name="편의패널전송")
async def mnb_v227_prefix_send_comfort_panel(ctx: commands.Context, channel: discord.TextChannel = None):
    if ctx.guild is None:
        return await ctx.reply("❌ 서버에서만 사용할 수 있습니다.", mention_author=False)
    if not await mnb_v227_can_manage_server(ctx.author):
        return await ctx.reply("❌ 관리자만 사용할 수 있습니다.", mention_author=False)
    target = channel or ctx.channel
    try:
        await target.send(embed=mnb_v227_build_guide_embed(ctx.guild), view=MNBComfortGuideView(), silent=True)
        await ctx.reply(f"✅ 편의 안내 패널을 {target.mention}에 전송했어요.", mention_author=False)
    except discord.Forbidden:
        await ctx.reply("❌ 그 채널에 메시지를 보낼 권한이 없어요.", mention_author=False)
    except Exception as e:
        await ctx.reply(f"❌ 전송 실패: `{str(e)[:500]}`", mention_author=False)

@bot.tree.command(name="공지", description="서버 공지 패널을 생성합니다.")
@app_commands.describe(channel="공지를 보낼 채널을 선택하세요.")
async def notice_command(interaction: discord.Interaction, channel: discord.TextChannel = None):
    # 기존 보안 함수 활용
    if await reject_if_not_bot_manager(interaction): return 

    data = NoticeData(interaction.guild.id)
    if channel: data.channel_id = channel.id

    view = NoticePanelView(interaction.user.id, data)
    await safe_interaction_send(interaction, embed=create_notice_embed(data), view=view, ephemeral=True)

# 박스형 레이아웃 및 GIF가 적용된 create_notice_embed 함수
def create_notice_embed(data: NoticeData):
    # description 앞뒤에 구분선을 넣어 박스 형태를 만듭니다
    embed = discord.Embed(
        title=f"📢 {data.title}", 
        description=f"━━━━━━━━━━━━━━━━━━\n{data.description[:1024]}\n━━━━━━━━━━━━━━━━━━", 
        color=data.color
    )

    # 공지 채널을 깔끔하게 필드로 추가합니다
    embed.add_field(
        name="📢 공지 채널", 
        value=f"<#{data.channel_id}>" if data.channel_id else "설정 안 됨", 
        inline=False
    )

    # 설정된 GIF 또는 이미지가 있다면 하단에 자동으로 표시됩니다
    if data.image:
        embed.set_image(url=data.image)

    embed.set_footer(text="Sky Bot • Notice System")
    return embed


# ────────────────────────────────────────────────────────────────
# 관리자 RPG 지급 명령어 (/rpg지급)
#  - /rpg 그룹은 25개 서브커맨드 하드 리밋에 걸려 있어 최상위 명령어로 붙입니다.
#  - 종류: 포인트 / 아이템(상점재료) / 펫 / 유물 을 선택해 지급합니다.
#  - 펫/유물/아이템은 개수(수량)를 지정할 수 있습니다.
# ────────────────────────────────────────────────────────────────
def _rpg_all_pet_names() -> list:
    """지급 자동완성용 전체 펫 이름 목록."""
    return list(RPG_PET_INFO_BY_NAME.keys())


def _rpg_all_relic_choices() -> dict:
    """유물 지급용 {relic_id: 표시이름} 매핑."""
    mapping = {}
    try:
        for element in RPG_RELIC_SETS:
            for relic in element.get("pieces", []):
                mapping[relic["relic_id"]] = relic["name"]
    except Exception:
        pass
    return mapping


@bot.tree.command(name="rpg지급", description="관리자 전용 — 유저에게 포인트/아이템/펫/유물을 지급합니다.")
@app_commands.describe(
    유저="지급 대상 유저",
    종류="지급할 항목 종류",
    이름="아이템/펫/유물 이름 (포인트는 비워도 됩니다)",
    수량="지급 개수 (기본 1, 포인트는 지급할 포인트 액수)",
)
@app_commands.choices(종류=[
    app_commands.Choice(name="💰 포인트", value="point"),
    app_commands.Choice(name="🎒 아이템(재료)", value="item"),
    app_commands.Choice(name="🐾 펫", value="pet"),
    app_commands.Choice(name="🏺 유물", value="relic"),
])
async def rpg_admin_give(
    interaction: discord.Interaction,
    유저: discord.Member,
    종류: app_commands.Choice[str],
    이름: str = None,
    수량: int = 1,
):
    if await reject_if_not_bot_manager(interaction):
        return

    guild_id = interaction.guild.id
    target_id = 유저.id
    kind = 종류.value

    try:
        수량 = int(수량)
    except (TypeError, ValueError):
        수량 = 1
    if 수량 <= 0:
        return await safe_interaction_send(interaction, "❌ 수량은 1 이상이어야 합니다.", ephemeral=True)

    # ── 포인트 지급 ────────────────────────────────
    if kind == "point":
        point = get_user_point(guild_id, target_id) + 수량
        set_user_point(guild_id, target_id, point)
        embed = discord.Embed(
            title="💰 포인트 지급 완료",
            description=f"대상: {유저.mention}\n지급: **{수량:,}P**\n현재 포인트: **{max(point, 0):,}P**",
            color=discord.Color.gold(),
        )
        await safe_interaction_send(interaction, embed=embed, ephemeral=True)
        await send_log(interaction.guild, f"💰 RPG 포인트 지급\n대상: {유저.mention}\n관리자: {interaction.user.mention}\n금액: {수량:,}P")
        return

    # 이름이 필요한 종류들
    if not 이름:
        return await safe_interaction_send(interaction, "❌ 이 종류는 `이름`을 입력해야 합니다.", ephemeral=True)
    이름 = 이름.strip()

    # ── 펫 지급 ───────────────────────────────────
    if kind == "pet":
        # 이모지 없이 입력해도 최대한 매칭되도록 부분일치 허용
        pet_name = None
        if 이름 in RPG_PET_INFO_BY_NAME:
            pet_name = 이름
        else:
            for name in RPG_PET_INFO_BY_NAME:
                clean = name.split(" ", 1)[-1] if " " in name else name
                if 이름 == clean or 이름 in name:
                    pet_name = name
                    break
        if pet_name is None:
            return await safe_interaction_send(
                interaction,
                f"❌ `{이름}` 펫을 찾을 수 없습니다. `/rpg 펫목록`(전체 도감)에서 이름을 확인해주세요.",
                ephemeral=True,
            )
        rarity_index = RPG_PET_INFO_BY_NAME[pet_name][0]
        for _ in range(수량):
            rpg_add_pet(guild_id, target_id, pet_name, rarity_index)
        embed = discord.Embed(
            title="🐾 펫 지급 완료",
            description=f"대상: {유저.mention}\n펫: **{pet_name}**\n지급 수량: **{수량}마리**\n\n(같은 펫 {RPG_PET_AWAKEN_COST}마리마다 `/rpg 각성`에서 진화시킬 수 있어요.)",
            color=discord.Color.purple(),
        )
        await safe_interaction_send(interaction, embed=embed, ephemeral=True)
        await send_log(interaction.guild, f"🐾 RPG 펫 지급\n대상: {유저.mention}\n관리자: {interaction.user.mention}\n펫: {pet_name} ×{수량}")
        return

    # ── 유물 지급 ─────────────────────────────────
    if kind == "relic":
        relic_map = _rpg_all_relic_choices()
        relic_id = None
        if 이름 in relic_map:
            relic_id = 이름
        else:
            for rid, rname in relic_map.items():
                clean = rname.split(" ", 1)[-1] if " " in rname else rname
                if 이름 == clean or 이름 in rname or 이름 == rid:
                    relic_id = rid
                    break
        if relic_id is None:
            return await safe_interaction_send(
                interaction,
                f"❌ `{이름}` 유물을 찾을 수 없습니다. `/rpg 유물목록`에서 이름을 확인해주세요.",
                ephemeral=True,
            )
        for _ in range(수량):
            rpg_add_relic(guild_id, target_id, relic_id)
        display = relic_map.get(relic_id, relic_id)
        embed = discord.Embed(
            title="🏺 유물 지급 완료",
            description=f"대상: {유저.mention}\n유물: **{display}**\n지급 수량: **{수량}개**",
            color=discord.Color.dark_gold(),
        )
        await safe_interaction_send(interaction, embed=embed, ephemeral=True)
        await send_log(interaction.guild, f"🏺 RPG 유물 지급\n대상: {유저.mention}\n관리자: {interaction.user.mention}\n유물: {display} ×{수량}")
        return

    # ── 아이템(재료/상점 아이템) 지급 ───────────────
    if kind == "item":
        item_name = normalize_shop_item(이름)
        valid = set(ALL_SHOP_ITEMS) | set(RPG_SHOP_ITEMS)
        if item_name not in valid:
            return await safe_interaction_send(
                interaction,
                f"❌ `{이름}` 아이템을 찾을 수 없습니다. `/rpg 상점` 또는 `/통합상점`에서 판매 아이템 이름을 확인해주세요.",
                ephemeral=True,
            )
        ok = add_inventory_item(target_id, item_name, 수량, guild_id=guild_id)
        if not ok:
            return await safe_interaction_send(interaction, "❌ 아이템 지급 중 오류가 발생했습니다.", ephemeral=True)
        embed = discord.Embed(
            title="🎒 아이템 지급 완료",
            description=f"대상: {유저.mention}\n아이템: **{item_name}**\n지급 수량: **{수량}개**",
            color=discord.Color.green(),
        )
        await safe_interaction_send(interaction, embed=embed, ephemeral=True)
        await send_log(interaction.guild, f"🎒 RPG 아이템 지급\n대상: {유저.mention}\n관리자: {interaction.user.mention}\n아이템: {item_name} ×{수량}")
        return


@rpg_admin_give.autocomplete("이름")
async def _rpg_admin_give_name_ac(interaction: discord.Interaction, current: str):
    """선택한 종류에 맞춰 이름 자동완성을 제공합니다."""
    try:
        kind = None
        for opt in (interaction.data.get("options") or []):
            if opt.get("name") == "종류":
                kind = opt.get("value")
                break
        current = (current or "").strip()
        pool = []
        if kind == "pet":
            pool = _rpg_all_pet_names()
        elif kind == "relic":
            pool = list(_rpg_all_relic_choices().values())
        elif kind == "item":
            pool = list(dict.fromkeys(list(ALL_SHOP_ITEMS) + list(RPG_SHOP_ITEMS)))
        else:
            return []
        if current:
            pool = [p for p in pool if current.lower() in p.lower()]
        return [app_commands.Choice(name=p[:100], value=p[:100]) for p in pool[:25]]
    except Exception:
        return []


