@server_setup_group.command(name="뮤트", description="특정 유저를 일정 시간 동안 뮤트(타임아웃) 시킵니다.")
@app_commands.describe(유저="뮤트할 유저", 시간="뮤트할 시간 (예: 10m, 1h, 1d)")
@app_commands.default_permissions(moderate_members=True)
async def admin_mute_user(interaction: discord.Interaction, 유저: discord.Member, 시간: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not interaction.user.guild_permissions.moderate_members:
        return await safe_interaction_send(interaction, "❌ 멤버 타임아웃 권한이 필요합니다.", ephemeral=True)

    duration_seconds = 0
    time_value = int(re.findall(r'\d+', 시간)[0]) if re.findall(r'\d+', 시간) else 0
    if 's' in 시간: duration_seconds = time_value
    elif 'm' in 시간: duration_seconds = time_value * 60
    elif 'h' in 시간: duration_seconds = time_value * 3600
    elif 'd' in 시간: duration_seconds = time_value * 86400
    else:
        return await safe_interaction_send(interaction, "❌ 시간 형식이 올바르지 않습니다. (예: 10m, 1h, 1d)", ephemeral=True)

    if duration_seconds <= 0:
        return await safe_interaction_send(interaction, "❌ 뮤트 시간은 0보다 커야 합니다.", ephemeral=True)

    try:
        # Discord API v2에서 타임아웃은 datetime.timedelta 객체를 사용합니다.
        timeout_duration = datetime.timedelta(seconds=duration_seconds)
        await 유저.timeout(timeout_duration, reason=f"관리자 {interaction.user.display_name}에 의해 뮤트됨")
        await safe_interaction_send(interaction, f"✅ {유저.display_name}님을 {시간} 동안 뮤트했습니다.", ephemeral=True)
    except discord.Forbidden:
        await safe_interaction_send(interaction, "❌ 유저를 뮤트할 권한이 없습니다. 봇에게 멤버 타임아웃 권한을 부여해주세요.", ephemeral=True)
    except Exception as e:
        await safe_interaction_send(interaction, f"❌ 유저 뮤트 중 오류가 발생했습니다: {e}", ephemeral=True)


@server_setup_group.command(name="경고조회", description="특정 유저의 경고 내역을 조회합니다.")
@app_commands.describe(유저="경고 내역을 조회할 유저")
@app_commands.default_permissions(kick_members=True)
async def admin_check_warnings(interaction: discord.Interaction, 유저: discord.Member):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not interaction.user.guild_permissions.kick_members:
        return await safe_interaction_send(interaction, "❌ 멤버 추방 권한이 필요합니다.", ephemeral=True)

    await interaction.response.defer(ephemeral=True)
    with DB_MUTEX:
        c.execute("SELECT moderator_id, reason, time FROM warnings WHERE user_id = ? ORDER BY time DESC", (유저.id,))
        warnings = c.fetchall()

    if not warnings:
        return await safe_interaction_send(interaction, f"✅ {유저.display_name}님은 경고 내역이 없습니다.", ephemeral=True)

    embed = discord.Embed(title=f"⚠️ {유저.display_name}님의 경고 내역", color=COLOR_WARNING)
    for mod_id, reason, warn_time in warnings:
        moderator = interaction.guild.get_member(mod_id) or f"알 수 없는 관리자 (ID: {mod_id})"
        embed.add_field(name=f"사유: {reason}", value=f"관리자: {moderator} | 시간: {warn_time}", inline=False)

    await safe_interaction_send(interaction, embed=embed, ephemeral=True)


