@community_group.command(name="투표", description="이모지 반응을 이용한 투표를 생성합니다.")
@app_commands.describe(주제="투표 주제", 항목들="쉼표로 구분된 투표 항목들 (최대 10개)")
async def community_poll(interaction: discord.Interaction, 주제: str, 항목들: str):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    options = [item.strip() for item in 항목들.split(',') if item.strip()]
    if not (2 <= len(options) <= 10):
        return await safe_interaction_send(interaction, "❌ 투표 항목은 최소 2개, 최대 10개까지 가능합니다.", ephemeral=True)

    emojis = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣', '6️⃣', '7️⃣', '8️⃣', '9️⃣', '🔟']
    description = f"**{주제}**\n\n"
    for i, option in enumerate(options):
        description += f"{emojis[i]} {option}\n"

    embed = discord.Embed(
        title="📊 새로운 투표가 시작되었습니다!",
        description=description,
        color=COLOR_SKY
    )
    embed.set_footer(text=f"투표 생성자: {interaction.user.display_name}")

    await interaction.response.send_message(embed=embed)
    message = await interaction.original_response()

    for i in range(len(options)):
        await message.add_reaction(emojis[i])


@community_group.command(name="프로필", description="자신의 서버 내 정보를 보여줍니다.")
async def community_profile(interaction: discord.Interaction, 유저: discord.Member = None):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    target_user = 유저 or interaction.user

    await interaction.response.defer(ephemeral=True)

    with DB_MUTEX:
        # 유저 포인트 정보 조회
        c.execute("SELECT point, attendance_count, streak, last_attendance FROM users WHERE guild_id = ? AND user_id = ?",
                  (interaction.guild.id, target_user.id))
        user_data = c.fetchone()

        # 유저 레벨 정보 조회
        c.execute("SELECT exp, level FROM levels WHERE user_id = ?", (target_user.id,))
        level_data = c.fetchone()

    points = user_data[0] if user_data else 0
    attendance_count = user_data[1] if user_data else 0
    streak = user_data[2] if user_data else 0
    last_attendance = user_data[3] if user_data else "없음"

    exp = level_data[0] if level_data else 0
    level = level_data[1] if level_data else 1

    # 다음 레벨까지 필요한 경험치 (간단한 예시, 실제 봇의 레벨 시스템에 따라 조정 필요)
    exp_to_next_level = level * 100

    embed = discord.Embed(
        title=f"👤 {target_user.display_name}님의 프로필",
        color=COLOR_SKY
    )
    embed.set_thumbnail(url=target_user.display_avatar.url)
    embed.add_field(name="레벨", value=f"**{level}** (경험치: {exp}/{exp_to_next_level})", inline=True)
    embed.add_field(name="포인트", value=f"**{points}**", inline=True)
    embed.add_field(name="서버 가입일", value=discord.utils.format_dt(target_user.joined_at, "D"), inline=True)
    embed.add_field(name="출석 횟수", value=f"{attendance_count}회 (연속: {streak}일)", inline=True)
    embed.add_field(name="마지막 출석", value=last_attendance, inline=True)

    await safe_interaction_send(interaction, embed=embed)


@community_group.command(name="슬롯", description="포인트를 걸고 슬롯머신 게임을 합니다.")
@app_commands.describe(베팅액="걸 포인트를 입력하세요 (최소 100)")
async def community_slots(interaction: discord.Interaction, 베팅액: app_commands.Range[int, 100, 10000]):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)

    user_id = interaction.user.id
    guild_id = interaction.guild.id

    await interaction.response.defer(ephemeral=False)

    with DB_MUTEX:
        c.execute("SELECT point FROM users WHERE guild_id = ? AND user_id = ?", (guild_id, user_id))
        user_points = c.fetchone()
        current_points = user_points[0] if user_points else 0

        if current_points < 베팅액:
            return await safe_interaction_send(interaction, f"❌ 포인트가 부족합니다! 현재 포인트: {current_points}", ephemeral=True)

        # 베팅액 차감
        new_points = current_points - 베팅액
        c.execute("UPDATE users SET point = ? WHERE guild_id = ? AND user_id = ?", (new_points, guild_id, user_id))
        conn.commit()

    # 슬롯 심볼 정의
    symbols = ["🍒", "🍋", "🍊", "🍇", "🔔", "⭐", "💎", "🍀"]
    results = random.choices(symbols, k=3)

    # 결과 판정
    winnings = 0
    color = COLOR_WARNING # 기본은 잃음
    title = "🎰 슬롯머신 결과"
    description = f"**[ {results[0]} | {results[1]} | {results[2]} ]**\n\n"

    if results[0] == results[1] == results[2]:
        # 트리플 매치
        if results[0] == "💎": # 다이아몬드 트리플은 더 높은 배당
            winnings = 베팅액 * 10
            description += f"🎉 **{results[0]}{results[0]}{results[0]}! 다이아몬드 트리플! {winnings} 포인트 획득!**"
            color = COLOR_GOLD
        else:
            winnings = 베팅액 * 5
            description += f"🎉 **{results[0]}{results[0]}{results[0]}! 트리플! {winnings} 포인트 획득!**"
            color = COLOR_GOLD
    elif results[0] == results[1] or results[1] == results[2] or results[0] == results[2]:
        # 더블 매치
        winnings = 베팅액 * 2
        description += f"✨ **더블! {winnings} 포인트 획득!**"
        color = COLOR_GREEN
    else:
        description += f"😭 **아쉽지만 다음 기회에... {베팅액} 포인트 손실!**"

    # 포인트 업데이트
    with DB_MUTEX:
        new_points += winnings
        c.execute("UPDATE users SET point = ? WHERE guild_id = ? AND user_id = ?", (new_points, guild_id, user_id))
        conn.commit()

    embed = discord.Embed(
        title=title,
        description=description,
        color=color
    )
    embed.add_field(name="베팅액", value=f"{베팅액} 포인트", inline=True)
    embed.add_field(name="획득 포인트", value=f"{winnings} 포인트", inline=True)
    embed.add_field(name="현재 포인트", value=f"{new_points} 포인트", inline=False)
    embed.set_footer(text=f"플레이어: {interaction.user.display_name}")

    await safe_interaction_send(interaction, embed=embed)


