@server_setup_group.command(name="추방", description="특정 유저를 서버에서 추방합니다.")
@app_commands.describe(유저="추방할 유저", 사유="추방 사유")
@app_commands.default_permissions(kick_members=True)
async def server_kick(interaction: discord.Interaction, 유저: discord.Member, 사유: str = "관리자에 의한 추방"):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
    if not interaction.user.guild_permissions.kick_members:
        return await safe_interaction_send(interaction, "❌ 멤버 추방 권한이 필요합니다.", ephemeral=True)

    try:
        await 유저.kick(reason=사유)
        await safe_interaction_send(interaction, f"✅ **{유저.display_name}**님을 추방했습니다. (사유: {사유})", ephemeral=True)
    except discord.Forbidden:
        await safe_interaction_send(interaction, "❌ 유저를 추방할 권한이 없습니다. 봇의 역할 순위가 대상보다 높은지 확인해주세요.", ephemeral=True)
    except Exception as e:
        await safe_interaction_send(interaction, f"❌ 추방 중 오류가 발생했습니다: {e}", ephemeral=True)

@server_setup_group.command(name="차단", description="특정 유저를 서버에서 차단(밴)합니다.")
@app_commands.describe(유저="차단할 유저", 사유="차단 사유", 삭제일수="메시지 삭제 기간 (0-7일)")
@app_commands.default_permissions(ban_members=True)
async def server_ban(interaction: discord.Interaction, 유저: discord.Member, 사유: str = "관리자에 의한 차단", 삭제일수: app_commands.Range[int, 0, 7] = 0):
    if interaction.guild is None:
        return await safe_interaction_send(interaction, "❌ 서버에서만 사용할 수 있습니다.", ephemeral=True)
