    if not invites: return await safe_interaction_send(interaction, "❌ 활성화된 초대 링크가 없습니다.", ephemeral=True)
    text = "\n".join([f"• {inv.code} (생성자: {inv.inviter}, 사용: {inv.uses}회)" for inv in invites[:20]])
