@channel_tools_group.command(name="메시지고정목록", description="현재 채널의 고정된 메시지 목록을 확인합니다.")
async def channel_pins(interaction: discord.Interaction):
    pins = await interaction.channel.pins()
    if not pins: return await safe_interaction_send(interaction, "✅ 고정된 메시지가 없습니다.", ephemeral=True)
    text = "\n".join([f"• {p.author}: {p.content[:30]}... ([이동]({p.jump_url}))" for p in pins])
    embed = discord.Embed(title="📌 고정된 메시지 목록", description=text, color=COLOR_SKY)
    await safe_interaction_send(interaction, embed=embed, ephemeral=True)

@channel_tools_group.command(name="채널로그확인", description="채널의 최근 메시지 로그를 텍스트 파일로 추출합니다.")
@app_commands.describe(개수="추출할 메시지 개수")
@app_commands.default_permissions(manage_messages=True)
async def channel_export_logs(interaction: discord.Interaction, 개수: int = 100):
    await interaction.response.defer(ephemeral=True)
    logs = ""
    async for msg in interaction.channel.history(limit=개수):
        logs = f"[{msg.created_at.strftime('%Y-%m-%d %H:%M:%S')}] {msg.author}: {msg.content}\n" + logs

    file = discord.File(io.BytesIO(logs.encode()), filename=f"logs_{interaction.channel.name}.txt")
    await safe_interaction_send(interaction, f"✅ 최근 {개수}개의 메시지 로그입니다.", file=file, ephemeral=True)

@channel_tools_group.command(name="채널비우기", description="채널의 모든 메시지를 삭제합니다. (purge 1000)")
@app_commands.default_permissions(administrator=True)
async def channel_clear_all(interaction: discord.Interaction):
    await interaction.response.defer(ephemeral=True)
    try:
        deleted = await interaction.channel.purge(limit=1000)
        await safe_interaction_send(interaction, f"✅ {len(deleted)}개의 메시지를 삭제했습니다.", ephemeral=True)
    except Exception as e:
        await safe_interaction_send(interaction, f"❌ 삭제 실패: {e}", ephemeral=True)

